def _base_dir():
    """Hvor gemte spil, indstillinger og fejllog ligger: ved siden af spillet (også som .exe). Kan der ikke
    skrives dér (fx under Programmer), bruges en mappe i brugerens AppData i stedet."""
    if getattr(sys, "frozen", False):                  # pakket som .exe: __file__ peger på en midlertidig mappe
        d = os.path.dirname(os.path.abspath(sys.executable))
    else:
        d = os.path.dirname(os.path.abspath(__file__))
    try:
        probe = os.path.join(d, ".farmland_skrivetest")
        with open(probe, "w") as f:
            f.write("ok")
        os.remove(probe)
        return d
    except OSError:
        alt = os.path.join(os.environ.get("APPDATA") or os.path.expanduser("~"), "FarmLand")
        try:
            os.makedirs(alt, exist_ok=True)
            return alt
        except OSError:
            return d


BASE_DIR = _base_dir()
ERROR_LOG = os.path.join(BASE_DIR, "farmland_fejl.txt")
BACKUP_DIR = os.path.join(BASE_DIR, "backup")
BACKUP_EVERY = 20 * 60        # sekunder (rigtig tid) mellem ekstra sikkerhedskopier
BACKUP_KEEP = 5


def log_error(where, exc_text):
    """Skriv en fejl i fejlloggen (i stedet for konsollen, som ikke ses i .exe-udgaven)."""
    try:
        new = not os.path.exists(ERROR_LOG) or os.path.getsize(ERROR_LOG) > 200_000
        with open(ERROR_LOG, "w" if new else "a", encoding="utf-8") as f:
            f.write(f"\n=== {time.strftime('%Y-%m-%d %H:%M:%S')} · FarmLand {GAME_VERSION} (gem v{VERSION}) · "
                    f"Python {sys.version.split()[0]} · {where} ===\n{exc_text}\n")
    except OSError:
        pass
SAVE_SINGLE = os.path.join(BASE_DIR, "farmland_single.json")
SAVE_MULTI = os.path.join(BASE_DIR, "farmland_multi.json")
CFG_PATH = os.path.join(BASE_DIR, "farmland_config.json")


def migrate_old_files():
    """Spillet hed tidligere Høstland: flyt gamle gemte spil og indstillinger over til de nye navne."""
    for new in (SAVE_SINGLE, SAVE_MULTI, CFG_PATH):
        old = new.replace("farmland_", "hoestland_")
        for ext in ("", ".bak"):
            if os.path.exists(old + ext) and not os.path.exists(new + ext):
                try:
                    os.replace(old + ext, new + ext)
                except OSError:
                    pass

