def new_game_opts(cfg):
    """Vejr/skader og årets længde, som et nyt spil starter med (valgt i hovedmenuens Indstillinger)."""
    d = cfg.get("newopts") or {}
    out = {k: bool(d.get(k, True)) for k in WEATHER_OPTS}
    pv = d.get("pace", YEAR_PACE_DEFAULT)
    out["pace"] = float(pv) if isinstance(pv, (int, float)) and float(pv) in YEAR_PACE else YEAR_PACE_DEFAULT
    return out
