def wagon_key(w):
    """'w:stor_tipvogn#2' / 'stor_tipvogn' -> 'stor_tipvogn'."""
    if not w:
        return None
    return (w[2:] if w.startswith("w:") else w).split("#")[0]


def wagon_base(w):
    """Vogntypen, den store vogn er en udgave af (til tegningen) – fx 'stor_tipvogn' -> 'tipvogn'."""
    k = wagon_key(w)
    return WAGONS.get(k, {}).get("base", k)


def wagon_hk(w):
    """Mindste hestekræfter, en traktor skal have for at trække vognen (0 = alle)."""
    return WAGONS.get(wagon_key(w), {}).get("hk", 0)
