def pull_max(power):
    """Hvor langt en traktor med den trækkraft højst kan trække slæden (m) – slæden bliver tungere undervejs."""
    if power <= 0.3:
        return 0.0
    return PULL_FULL * min(1.0, (power - 0.3) / 1.9) ** (1 / 1.3)


def meters(d):
    return f"{d:.1f}".replace(".", ",") + " m"


def pull_resist(x):
    return 0.3 + 1.9 * (max(0.0, x) / PULL_FULL) ** 1.3


