def upg_fits(key, model):
    """Passer opgraderingen til maskinmodellen? (slags – og for småkøretøjer også typen)"""
    u = UPGRADES.get(key)
    v = VEHICLES.get(model)
    if not u or not v or v["kind"] not in u["kinds"]:
        return False
    only = (u.get("only") or {}).get(v["kind"])
    return not only or v.get("style") in only


def upg_price(key, model):
    u = UPGRADES[key]
    return (u.get("prices") or {}).get(VEHICLES.get(model, {}).get("kind"), u["price"])


def plow_on(tr):
    """Sidder sneploven (opgraderingen) på maskinen lige nu?"""
    return "sneplov" in (tr.get("upg") or ()) and not tr.get("plow_off")


def loader_on(tr):
    """Kan maskinen løfte baller? Traktor med frontlæsser (ikke mens sneploven sidder foran) – eller en
    gaffeltruck/minilæsser, der har det indbygget."""
    if VEHICLES.get(tr["k"], {}).get("loader"):
        return True
    return "frontlaesser" in (tr.get("upg") or ()) and not (vkind(tr["k"]) == "tractor" and plow_on(tr))


def yard_grid(w, h):
    """Ballepladsens stakke: (søjler, rækker, lag) for en plads på w×h felter."""
    return 2 * w, 2 * h, 3


def yard_slots(w, h, nh, nw):
    """De synlige baller på ballepladsen i fast rækkefølge: [((søjle, række, lag), wrap)].
    Halmen stables stak for stak fra den ene ende, wrapballerne fra den anden – en stak fyldes, før den næste."""
    cols, rows, lay = yard_grid(w, h)
    n = cols * rows
    out = []
    for i in range(min(nh, n * lay)):
        k = i // lay
        out.append(((k % cols, k // cols, i % lay), False))
    for i in range(min(nw, n * lay - len(out))):
        k = n - 1 - i // lay
        out.append(((k % cols, k // cols, i % lay), True))
    return out


def bale_unit(g, shape=None):
    """Enheder i én balle af varen g (wrapballer er altid runde)."""
    if g != "halm":
        return BALE_U
    return BALE_SHAPES.get(shape or "rund", BALE_SHAPES["rund"])["u"]


def bale_name(g, shape=None, n=2):
    if g == "wrap":
        return "wrapballe" if n == 1 else "wrapballer"
    sh = BALE_SHAPES.get(shape or "rund", BALE_SHAPES["rund"])
    return sh["navn"] if n == 1 else sh["flertal"]


def wagon_slots_used(load, shape=None):
    """Hvor mange pladser ballerne fylder på en ballevogn."""
    return (load.get("halm", 0.0) / bale_unit("halm", shape) + load.get("wrap", 0.0) / BALE_U) if load else 0.0


def wagon_slots(w):
    """Pladser til baller på vognen (den store ballevogn har flere)."""
    return WAGONS.get(wagon_key(w), {}).get("slots", BALE_SLOTS)


def bale_wagon(w):
    """Er vognen (nøgle, 'w:nøgle#n' eller None) en ballevogn – kun til baller?"""
    if not w:
        return False
    if w.startswith("w:"):
        w = w[2:]
    return bool(WAGONS.get(w.split("#")[0], {}).get("bales"))


def bale_view(load, slots=None, shape=None):
    """Ballerne på en vogn som ("bl", halm, wrap, form) i hele baller – eller None, hvis det ikke er baller."""
    if not load or not set(load) <= set(BALE_GOODS):
        return None
    slots = slots or BALE_SLOTS
    nh = int(round(load.get("halm", 0.0) / bale_unit("halm", shape)))
    nw = int(round(load.get("wrap", 0.0) / BALE_U))
    if nh + nw == 0:
        nh = 1 if load.get("halm", 0) >= load.get("wrap", 0) else 0
        nw = 1 - nh
    nh = min(nh, slots)
    return ("bl", nh, min(nw, slots - nh), shape or "rund")


def view_plow(v):
    return len(v) > 30 and bool(v[30])


def view_loader(v):
    if VEHICLES.get(v[6], {}).get("loader"):
        return True
    return len(v) > 21 and "frontlaesser" in (v[21] or []) and not (vkind(v[6]) == "tractor" and view_plow(v))


FUEL_TILE = 0.3                  # liter pr. bearbejdet felt for en mellemtraktor
FUEL_MOVE = 0.03                 # liter pr. felt, maskinen kører
WEAR_TILE = 0.05                 # % slid pr. bearbejdet felt
WEAR_MOVE = 0.004                # % slid pr. felt kørsel
SERVICE_AT = 50                  # værkstedet servicerer selv maskiner, der er slidt så meget, når de holder hjemme
SERVICE_RATE = 0.06              # service ved 100% slid koster 6% af maskinens pris


FUEL_TANK = {"tractor": 90, "combine": 160, "truck": 220, "car": 45, "smaa": 30}   # liter i maskinens egen tank
FUEL_RESCUE_FEE = 400            # tankbilen rykker ud til en maskine, der er løbet tør
FUEL_RATE = 45                   # liter pr. sekund ved pumpen, når man selv tanker
FUEL_TOWN_MARKUP = 1.1           # diesel ved grovvarehandlens pumpe koster lidt mere end dagsprisen


def fuel_cap(key, tr=None):
    v = VEHICLES.get(key, {})
    cap = int(FUEL_TANK.get(v.get("kind"), 90) * max(0.8, min(1.6, (v.get("hk", 82) / 82) ** 0.35)))
    return int(cap * 1.5) if tr is not None and "ekstratank" in (tr.get("upg") or ()) else cap


def fuel_factor(key):
    """Dieselforbrug i forhold til en mellemtraktor. Store maskiner bruger mere, men arbejder hurtigere."""
    v = VEHICLES[key]
    if v["kind"] == "car":
        return 0.4
    if v["kind"] == "smaa":
        return 0.3
    if v["kind"] == "truck":
        return (v["hk"] / 250) ** 0.5 * 1.3
    return (v["hk"] / 82) ** 0.6 / max(0.5, v["kraft"])


def wear_factor(key):
    """Pålidelige maskiner slides langsommere."""
    return 0.6 + (100 - VEHICLES[key]["rel"]) / 25


def service_cost(key, wear):
    return int(VEHICLES[key]["price"] * SERVICE_RATE * wear / 100 / 10 + 1) * 10
