def vname(key):
    v = VEHICLES[key]
    return f"{MAKERS[v['maker']]['navn']} {v['model']}"


def vkind(key):
    if key in VEHICLES:
        return VEHICLES[key]["kind"]
    return "car" if key.startswith("car:") else key
