def set_world(w=None):
    """Sæt kortets størrelse og byens placering (alle faste positioner i byen følger med)."""
    global MAP_W, MAP_H, TOWN, ROAD_X, ROAD_Y, KVAEGTORV, JAGTBUTIK, SAVVAERK, GROVVARE, DEPOT, SHOW_POS, PULL_POS
    global SHOW_SPOTS, TOWN_CENTER, KIRKE
    w = dict(w or {})
    size = w.get("w") or MAP_SIZES.get(w.get("size", "normal"), 72)
    MAP_W = MAP_H = int(size)
    tx, ty = w.get("tx"), w.get("ty")
    if tx is None:
        tx, ty = MAP_W // 2 - 6, MAP_H // 2 - 5
    TOWN = (tx, ty, tx + 11, ty + 9)
    ROAD_X, ROAD_Y = tx + 6, ty + 5
    o = _TOWN_OFS
    KVAEGTORV = (tx + o["kvaeg"][0], ty + o["kvaeg"][1])
    JAGTBUTIK = (tx + o["jagt"][0], ty + o["jagt"][1])
    SAVVAERK = (tx + o["sav"][0], ty + o["sav"][1])
    GROVVARE = (tx + o["grov"][0], ty + o["grov"][1])
    KIRKE = (tx + o["kirke"][0], ty + o["kirke"][1])
    TOWN_CENTER = (tx + o["center"][0], ty + o["center"][1])
    DEPOT = (ROAD_X, ROAD_Y)
    SHOW_POS = PULL_POS = KVAEGTORV
    SHOW_SPOTS = [(tx + a, ty + b) for a, b in o["show"]]
    set_pull_area(w.get("pull_area"))
    set_buyers(w.get("buyers"))
    for k, (a, b) in o["proj"].items():
        PROJECTS[k]["pos"] = (tx + a, ty + b)


def set_pull_area(area):
    """Traktortræk-pladsen (gemmes i kortets indstillinger). Uden plads bruges festpladsen ved kvægtorvet."""
    global PULL_AREA, PULL_POS
    PULL_AREA = dict(area) if area else None
    PULL_POS = pull_cells()["track"][0] if PULL_AREA else KVAEGTORV


def set_buyers(b):
    global SLAGTERI, MEJERIET
    b = b or {}
    SLAGTERI = tuple(b["slagteri"]) if b.get("slagteri") else None
    MEJERIET = tuple(b["mejeriet"]) if b.get("mejeriet") else None


def freight_dest(g):
    """Hvor en solgt vare skal køres hen."""
    if g == "tommer":
        return SAVVAERK
    if g == "svin":
        return SLAGTERI or KVAEGTORV
    if g == "maelk":
        return MEJERIET or DEPOT
    return GROVVARE


def dest_name(g):
    return {"tommer": "savværket", "svin": "slagteriet", "maelk": "mejeriet"}.get(g, "grovvarehandlen")


def pull_cells(area=None):
    """Felterne på traktortræk-pladsen: parkering (ved vejen), bane og tribune – hver række fra byens side."""
    a = area or PULL_AREA
    if not a:
        return {"park": [], "track": [], "stand": []}
    rows = {}
    for name, r in (("park", 1), ("track", 2), ("stand", 3)):
        off = a["road"] + a["side"] * r
        cells = [(a["s"] + i, off) if a["axis"] == "x" else (off, a["s"] + i) for i in range(PULL_LEN)]
        rows[name] = cells if not a.get("rev") else cells[::-1]
    return rows


def park_tile_ok(t, pid):
    """Må man parkere fast her? Egne fliser – eller parkeringen og banen ved traktortrækket (fælles plads)."""
    return (t.t == "fliser" and t.o == pid) or t.t in ("pullpark", "bane")


def at_pull_xy(x, y):
    """Står man ved traktortræk-banen (parkering eller bane – eller festpladsen i gamle spil)?"""
    if PULL_AREA:
        c = pull_cells()
        xs = [p[0] for p in c["park"] + c["track"]]
        ys = [p[1] for p in c["park"] + c["track"]]
        return min(xs) - 1.5 <= x <= max(xs) + 1.5 and min(ys) - 1.5 <= y <= max(ys) + 1.5
    return max(abs(x - PULL_POS[0]), abs(y - PULL_POS[1])) <= 4.0


def world_cfg(w=None):
    """Et fuldt kort-valg med byens placering udregnet (gemmes med spillet)."""
    w = {**WORLD_DEFAULT, **(w or {})}
    size = MAP_SIZES.get(w["size"], 72)
    w["w"] = w["h"] = size
    if w.get("tx") is None:
        rng = random.Random(w.get("seed", 0) * 7 + 3)
        m = 5
        by = w["by"]
        if by == "tilfaeldig":
            by = rng.choice(("midt", "kant", "soe", "fri"))
        if by == "kant":
            side = rng.randrange(4)
            along = rng.randint(m + 4, size - 12 - m - 4)
            tx, ty = [(m, along), (size - 12 - m, along), (along, m), (along, size - 10 - m)][side]
        elif by in ("soe", "fri"):
            tx, ty = rng.randint(m + 4, size - 12 - m - 4), rng.randint(m + 4, size - 10 - m - 4)
        else:
            tx, ty = size // 2 - 6, size // 2 - 5
        w["tx"], w["ty"], w["lake_town"] = tx, ty, by == "soe"
    return w


