def clamp(v, a, b):
    return a if v < a else b if v > b else v


def kr(v):
    n = int(round(v))
    return ("-" if n < 0 else "") + f"{abs(n):,}".replace(",", ".") + " kr"


def fmt_price(p):
    return f"{p:.2f}".replace(".", ",") + " kr"


def months_str(months):
    """'okt–jan', 'mar–apr og nov' eller 'hele året' – også når perioden går hen over nytår."""
    ms = sorted(set(months))
    if not ms:
        return "fredet"
    if len(ms) == 12:
        return "hele året"
    if 0 in ms and 11 in ms:                      # start efter hullet, så okt–jan hænger sammen
        k = next(i for i in range(1, len(ms)) if ms[i] != ms[i - 1] + 1)
        ms = ms[k:] + ms[:k]
    parts, start = [], None
    for i, m in enumerate(ms):
        if start is None:
            start = m
        if i == len(ms) - 1 or ms[i + 1] != (m + 1) % 12:
            parts.append(MONTHS_SHORT[start] if start == m else f"{MONTHS_SHORT[start]}–{MONTHS_SHORT[m]}")
            start = None
    return " og ".join(parts)


def sow_months_str(crop):
    """'mar–maj' eller 'mar–apr og nov', når månederne ikke hænger sammen."""
    ms, parts, start = sorted(CROPS[crop]["months"]), [], None
    for i, m in enumerate(ms):
        if start is None:
            start = m
        if i == len(ms) - 1 or ms[i + 1] != m + 1:
            parts.append(MONTHS_SHORT[start] if start == m else f"{MONTHS_SHORT[start]}–{MONTHS_SHORT[m]}")
            start = None
    return " og ".join(parts)


RIPE_DAYS = 45                   # så længe en moden afgrøde kan stå uden at tabe sig
OVERRIPE_DEAD = 100              # herefter er den helt visnet (imellem falder udbyttet langsomt)


def ripe_day(crop, day, g=0.0):
    """Hvilken dag afgrøden forventes moden, sået (eller med vækst g) på dagen 'day' – ved normal fugt."""
    c = CROPS[crop]
    for _ in range(900):
        if g >= 1:
            return day
        day += 1
        m = (day % DAYS_PER_YEAR) // DAYS_PER_MONTH
        g += (0.96 if 2 <= m <= 9 else (0.15 if c["hardy"] else 0.0)) / c["days"]   # typisk vejr
    return None


def when_str(day, now=None):
    """'midt i juli', 'først i maj næste år' …"""
    m, dom = (day % DAYS_PER_YEAR) // DAYS_PER_MONTH, day % DAYS_PER_MONTH
    txt = ("først i " if dom < 10 else "midt i " if dom < 20 else "sidst i ") + MONTHS[m]
    if now is not None and day // DAYS_PER_YEAR > now // DAYS_PER_YEAR:
        txt += " næste år"
    return txt


def crop_plan(crop, now):
    """Såtid og forventet høst for en afgrøde set fra dagen 'now'. Returnerer (kort tekst, lange linjer)."""
    c = CROPS[crop]
    months = c["months"]
    sow = sow_months_str(crop)
    m = (now % DAYS_PER_YEAR) // DAYS_PER_MONTH
    lines = [f"Såtid: {MONTHS[months[0]]} til {MONTHS[months[-1]]}"]
    if c.get("orchard"):
        lines.append("Træerne plantes én gang og giver frugt hvert år i september–oktober. Frost i april–maj "
                     "koster frugt, og bladlus skal sprøjtes. Plukkes af et plukkehold med traktor.")
        lines.append("Pløjes træerne op, er plantagen væk.")
        return f"plantes {sow} · frugt hvert år i sep–okt", lines
    if c.get("perennial"):
        mo = f"{c['days'] // 30}½" if c["days"] % 30 >= 10 else str(c["days"] // 30)
        lines.append(f"Første slæt ca. {mo} måned efter såning, derefter en ny slæt hver gang græsset er "
                     "vokset op igen (marts–oktober).")
        lines.append("Står i flere år – skal ikke sås igen.")
        return f"sås {sow} · slæt ca. hver {mo} måned", lines
    if c.get("green"):
        lines.append("Sås efter høsten på stubmarken (pløj først). Den høstes ikke – den dækker jorden hen over "
                     "vinteren, samler næring og kvæler ukrudt.")
        lines.append("Pløj den ned i foråret: jorden får op til +22 næring, og vårsæden gror bedre.")
        return f"sås {sow} · pløjes ned i foråret", lines
    y0 = now - now % DAYS_PER_YEAR
    start = y0 + months[0] * DAYS_PER_MONTH
    if start + DAYS_PER_MONTH * len(months) <= now:
        start += DAYS_PER_YEAR                        # sæsonen er forbi – næste år
    end = start + len(months) * DAYS_PER_MONTH - 1
    a, b = ripe_day(crop, start), ripe_day(crop, end)
    ma, mb = MONTHS[(a % DAYS_PER_YEAR) // DAYS_PER_MONTH], MONTHS[(b % DAYS_PER_YEAR) // DAYS_PER_MONTH]
    span = ma if ma == mb else f"{ma}–{mb}"
    if b // DAYS_PER_YEAR > start // DAYS_PER_YEAR:
        span += " året efter"
    lines.append(f"Høst: ca. {span} (ca. {round(c['days'] / 30)} måneders vækst"
                 + (", vokser lidt om vinteren)" if c["hardy"] else ")"))
    if m in months:
        r = ripe_day(crop, now)
        short = f"sås nu, klar til høst {when_str(r, now)}"
        lines.append(f"Sås den i dag, er den klar {when_str(r, now)}.")
    else:
        short = f"sås {sow} · høst {span}"
        lines.append(f"Kan ikke sås nu – næste såtid er {MONTHS[months[0]]}.")
    lines.append(f"Kan stå moden i ca. {RIPE_DAYS} dage. Derefter falder udbyttet langsomt, og efter "
                 f"ca. {OVERRIPE_DEAD} dage er den visnet.")
    return short, lines


def line_cells(x0, y0, x1, y1):
    """Felter langs en L-formet linje: først vandret, så lodret (til veje og grøfter)."""
    cells = [(x, y0) for x in range(x0, x1 + (1 if x1 >= x0 else -1), 1 if x1 >= x0 else -1)]
    cells += [(x1, y) for y in range(y0, y1 + (1 if y1 >= y0 else -1), 1 if y1 >= y0 else -1)][1:]
    return cells


def in_town(x, y, margin=0):
    x0, y0, x1, y1 = TOWN
    return x0 - margin <= x <= x1 + margin and y0 - margin <= y <= y1 + margin


# ── terræn: bakker som i Transport Tycoon ───────────────────────────────────
# Hvert hjørne i feltgitteret har en højde (0–9). To nabohjørner (også på skrå) må højst være ét trin fra
# hinanden, så et felt er enten fladt eller skråner ét trin. Fladt land (standard) har ingen højdekort.
HSTEP = 10                       # pixels pr. højdetrin ved zoom 1 (under et halvt felt, så jorden aldrig skjuler jord)
def hstep(z):
    """Pixels pr. højdetrin ved zoom z (hele pixels, så felterne passer sammen uden huller)."""
    return int(round(HSTEP * z))


TERRAIN_OPTS = {"fladt": "Fladt land", "bakket": "Bakket terræn"}
TERRAIN_AMP = {"blandet": 4, "vestjylland": 3, "fyn": 4, "lolland": 2, "soehoejland": 6, "marsken": 1}


def hm_pack(hm):
    return ["".join(str(v) for v in row) for row in hm] if hm else None


def hm_unpack(d):
    return [[int(c) for c in row] for row in d] if d else None


def hm_relax(hm, fixed=None):
    """Sænk hjørner, til ingen naboer er mere end ét trin fra hinanden (sænker kun, hæver aldrig)."""
    H1, W1 = len(hm), len(hm[0])
    todo = [(x, y) for y in range(H1) for x in range(W1)]
    while todo:
        nxt = set()
        for x, y in todo:
            v = hm[y][x]
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    X, Y = x + dx, y + dy
                    if (dx or dy) and 0 <= X < W1 and 0 <= Y < H1 and hm[Y][X] > v + 1:
                        hm[Y][X] = v + 1
                        nxt.add((X, Y))
        todo = nxt


def hm_gen(st, rng, amp):
    """Bløde bakker af støj i tre størrelser; søer i flade lavninger; byen på fladt land."""
    W, H = st.W, st.H

    def octave(cell):
        g = [[rng.random() for _ in range(W // cell + 3)] for _ in range(H // cell + 3)]

        def f(x, y):
            fx, fy = x / cell, y / cell
            ix, iy = int(fx), int(fy)
            u, v = fx - ix, fy - iy
            u, v = u * u * (3 - 2 * u), v * v * (3 - 2 * v)
            a = g[iy][ix] + (g[iy][ix + 1] - g[iy][ix]) * u
            b = g[iy + 1][ix] + (g[iy + 1][ix + 1] - g[iy + 1][ix]) * u
            return a + (b - a) * v
        return f
    o1, o2, o3 = octave(26), octave(13), octave(6)
    hm = [[0] * (W + 1) for _ in range(H + 1)]
    for y in range(H + 1):
        for x in range(W + 1):
            n = 0.62 * o1(x, y) + 0.3 * o2(x, y) + 0.08 * o3(x, y)
            hm[y][x] = int(round(clamp((n - 0.28) / 0.46, 0.0, 1.0) * amp))
    hm_relax(hm)
    # byen, traktortræk-pladsen, slagteri/mejeri og søerne ligger på fladt land (sænkes til laveste hjørne)
    T = st.tiles
    flats = []
    x0, y0, x1, y1 = TOWN
    flats.append({(x, y) for y in range(y0 - 1, y1 + 2) for x in range(x0 - 1, x1 + 2) if st.inb(x, y)})
    for (x, y) in ((x, y) for y in range(H) for x in range(W)):
        if T[y][x].t in ("bane", "pullpark") or T[y][x].b in ("slagteri", "mejeriet", "tribune", "pullsign"):
            flats.append({(x, y)})
    seen = set()
    for y in range(H):
        for x in range(W):
            if T[y][x].t == "water" and (x, y) not in seen:
                comp, stack = set(), [(x, y)]
                seen.add((x, y))
                while stack:
                    cx, cy = stack.pop()
                    comp.add((cx, cy))
                    for dx, dy in N4:
                        nx, ny = cx + dx, cy + dy
                        if st.inb(nx, ny) and (nx, ny) not in seen and T[ny][nx].t == "water":
                            seen.add((nx, ny))
                            stack.append((nx, ny))
                flats.append(comp)
    for _ in range(8):                      # sænk og efterjustér, til alle flader er flade
        ok = True
        for cells in flats:
            cs = {(x + a, y + b) for x, y in cells for a in (0, 1) for b in (0, 1)}
            lo = min(hm[cy][cx] for cx, cy in cs)
            if any(hm[cy][cx] != lo for cx, cy in cs):
                ok = False
                for cx, cy in cs:
                    hm[cy][cx] = lo
        hm_relax(hm)
        if ok:
            break
    return hm


def hm_level(hm, x0, y0, w, h, target=None):
    """Udjævn felterne (x0, y0)–(x0+w-1, y0+h-1) til én højde; omgivelserne følger med i en jævn skråning.
    Giver de ændrede hjørner tilbage."""
    H1, W1 = len(hm), len(hm[0])
    cs = [(x, y) for y in range(y0, y0 + h + 1) for x in range(x0, x0 + w + 1) if 0 <= x < W1 and 0 <= y < H1]
    if not cs:
        return []
    if target is None:
        vals = sorted(hm[y][x] for x, y in cs)
        target = vals[len(vals) // 2]
    R = 10
    changed = []
    for y in range(max(0, y0 - R), min(H1, y0 + h + 1 + R)):
        for x in range(max(0, x0 - R), min(W1, x0 + w + 1 + R)):
            d = max(x0 - x, x - (x0 + w), y0 - y, y - (y0 + h), 0)     # afstand til fladen (hjørner)
            v = hm[y][x]
            nv = min(max(v, target - d), target + d)
            if nv != v:
                hm[y][x] = nv
                changed.append((x, y))
    return changed


# ═════════════════════════════════════════════════════════════════════════════
#  SIMULATION (kører autoritativt på serveren; klienterne har en spejling)
# ═════════════════════════════════════════════════════════════════════════════
class Tile:
    __slots__ = ("t", "b", "crop", "g", "h", "m", "pest", "dead", "o", "imm", "rip", "ba", "n", "wd", "lc", "kc")

    def __init__(self, t="grass"):
        self.t, self.b, self.crop = t, None, None
        self.g, self.h, self.m = 0.0, 100.0, 50.0
        self.pest, self.dead, self.o, self.imm, self.rip = 0, False, -1, 0, 0
        self.ba = None       # (ankerx, ankery, bredde, dybde) for bygninger over flere felter
        self.n, self.wd, self.lc = float(SOIL_START), 0.0, None   # næring, ukrudt, forrige afgrøde
        self.kc = 75.0                                             # kalktilstand (jordens pH), 0–100

    def clear_crop(self):
        self.crop, self.g, self.h, self.dead, self.pest, self.rip = None, 0.0, 100.0, False, 0, 0

    def pack(self):
        return [self.t, self.b, self.crop, int(self.g * 100), int(self.h), int(self.m), self.pest,
                int(self.dead), self.o, self.ba, int(self.n), int(self.wd), self.lc, int(self.kc)]

    def pack_save(self):
        return [self.t, self.b, self.crop, round(self.g, 5), round(self.h, 2), round(self.m, 2),
                self.pest, int(self.dead), self.o, self.imm, self.rip, self.ba, round(self.n, 2),
                round(self.wd, 2), self.lc, round(self.kc, 1)]

    def unpack(self, d):
        self.t, self.b, self.crop = d[0], d[1], d[2]
        if len(d) >= 15:          # gemt spil (fuld præcision)
            self.g, self.h, self.m = d[3], d[4], d[5]
            self.imm, self.rip = d[9], d[10]
            ba = d[11]
            self.n, self.wd, self.lc = d[12], d[13], d[14]
            self.kc = d[15] if len(d) > 15 else 75.0
        else:                     # over netværket
            self.g, self.h, self.m = d[3] / 100.0, d[4], d[5]
            ba = d[9]
            self.n, self.wd, self.lc = d[10], d[11], d[12]
            self.kc = d[13] if len(d) > 13 else 75.0
        self.pest, self.dead, self.o = d[6], bool(d[7]), d[8]
        self.ba = tuple(ba) if ba else None


class GameState:
    def __init__(self):
        self.W, self.H = MAP_W, MAP_H
        self.tiles = [[Tile() for _ in range(self.W)] for _ in range(self.H)]
        self.world = {"size": next((k for k, v in MAP_SIZES.items() if v == MAP_W), "normal"), "w": MAP_W, "h": MAP_H,
                      "tx": TOWN[0], "ty": TOWN[1], "egn": "blandet", "by": "midt"}
        self.day = START_DAY
        self.weather, self.drought, self.speed = "Sol", 0, START_SPEED
        self.players = {}
        self.tractors = []
        self.tractor_view = []
        self.nid = 1
        self.market = {g: {"p": v["base"], "h": [v["base"]] * 30} for g, v in GOODS.items()}
        self.projects = {k: {"have": {r: 0 for r in v["need"]}, "done": False, "by": {}}
                         for k, v in PROJECTS.items()}
        self.events = []
        self.dirty = set()
        self.rng = random.Random()
        self.ver = 0
        self._stats = {}
        self.opts = {k: True for k in WEATHER_OPTS}
        self.contracts = []          # tilbud og aftaler, fælles for alle spillere
        self.deal_offers = []        # tilbud om leveringsaftaler (den første, der siger ja, får aftalen)
        self.ms_req = []             # maskinstation: bestillinger af markarbejde hos en anden gård
        self.rent_offers = []        # maskiner, redskaber og vogne, der er sat til leje
        self.torders = []            # byens fælles bestillinger (højst TOWN_ORDER_MAX ad gangen)
        self.hm, self.hm_ver, self.hm_t = None, 0, 0.0     # højdekort (None = fladt land)
        self.rentals = []            # igangværende udlejninger
        self.ctiles = {}             # (x, y) -> kontrakt-id for naboernes marker
        self.town = {"pts": 0.0, "lvl": 0, "pop": 0, "ph": [], "built": 0, "lm": []}
        self.phist = {g: [] for g in GOODS}   # gennemsnitspris pr. måned (til grafer)
        self.diesel = 1.0            # dieselprisen i forhold til normalprisen
        self.snow = 0.0              # snedække 0..1 (kun grafik)
        self.plowed = set()          # vejfelter, der er ryddet for sne siden sidste snefald
        self.offers = {}             # tilbud hos grovvarehandlen: {vare: {"pct", "until"}}
        self.news = []               # egnens avis: [{"id", "day", "title", "text", "big"}]
        self.records = {}
        self.npcs = []               # computernaboerne, man dyster med om årets gård
        self.aarets = None           # sidste års kåring
        self.mode = dict(MODE_DEFAULT)   # spiltilstand: drive auto/manual, farm own/shared
        self.pull = None             # traktortrækket i år: {"year", "stage", "entries", "npc", "results"}
        self.vote = None             # afstemning om hastigheden (multiplayer)
        self.n_voters, self.prev_speed, self.vote_seq = 1, 1, 0
        self.show = None             # Egnens Dyrskue i år: {"year", "stage", "entries", "results"}

    def manual_mode(self):
        return self.mode.get("drive") == "manual"

    def shared(self):
        return self.mode.get("farm") == "shared"

    def sandbox(self):
        return self.mode.get("money") == "sandbox"

    def start_money(self):
        return START_MONEY_OPTS.get(self.mode.get("money"), START_MONEY)

    def _sandbox_topup(self):
        if self.sandbox():
            for p in self.players.values():
                if p.get("ai"):
                    continue                      # computernaboerne driver deres gård på almindelige vilkår
                if p["money"] < SANDBOX_MONEY:
                    p["money"] = float(SANDBOX_MONEY)
                p["loan"], p["loans"] = 0, []

    def n_helpers(self, pid):
        if self.tractors:
            return sum(1 for t in self.tractors if t["o"] == pid and t.get("helper"))
        return sum(1 for t in self.tractor_view if t[1] == pid and len(t) > 16 and t[16])

    # ── dato og hjælpere ─────────────────────────────────────────────────────
    def month(self):
        return (self.day % DAYS_PER_YEAR) // DAYS_PER_MONTH

    def dom(self):
        return self.day % DAYS_PER_MONTH + 1

    def year(self):
        return self.day // DAYS_PER_YEAR + 1

    @staticmethod
    def pdate(day):
        return f"{day % DAYS_PER_MONTH + 1}. {MONTHS_SHORT[(day % DAYS_PER_YEAR) // DAYS_PER_MONTH]} år {day // DAYS_PER_YEAR + 1}"

    def date_str(self):
        return f"{self.dom()}. {MONTHS[self.month()]}, år {self.year()}"

    def inb(self, x, y):
        return 0 <= x < self.W and 0 <= y < self.H

    def owner(self, x, y):
        if not self.inb(x, y):
            return None
        o = self.tiles[y][x].o
        return None if o < 0 else o

    def done(self, k):
        pr = self.projects.get(k)
        return bool(pr and pr["done"])

    def hire_harvest(self):
        """Maskinstationens pris pr. felt (halv pris, når den fælles maskinstation er bygget)."""
        return HIRE_HARVEST_F if self.done("maskinst") else HIRE_HARVEST

    def park_share(self, p):
        """Spillerens andel af vindmølleparken (efter hvor mange penge han har givet til den)."""
        by = self.projects.get("vindpark", {}).get("by", {})
        tot = sum(by.values())
        return by.get(p["name"], 0) / tot if tot else 0.0

    def _shared_power(self):
        """Fælles biogasanlæg og vindmøllepark: hver dag strøm til alle, der er med."""
        if self.done("vindpark"):
            pay_all = VINDPARK_BASE * self.wind_now()
            for p in self.players.values():
                sh = self.park_share(p)
                if sh > 0 and pay_all > 0:
                    pay = pay_all * sh
                    p["money"] += pay
                    self.book(p, "stroem", pay)
                    p["park_kr"] = p.get("park_kr", 0.0) + pay
        if self.done("biogas_f"):
            for p in self.players.values():
                if self.stats(p["id"])["b"].get("biogas"):
                    continue                                 # eget anlæg: gyllen går dertil
                g = sum(GYLLE[k] * p.get(k, 0) for k in ANIMALS)
                if g <= 0:
                    continue
                pay = g * BIOGAS_F_KWH * POWER_PRICE
                p["money"] += pay
                self.book(p, "stroem", pay)
                p["bio_f_kr"] = p.get("bio_f_kr", 0.0) + pay

    def log(self, text, pid=None, color="info"):
        self.events.append((pid, text, color))

    def pname(self, pid):
        p = self.players.get(pid)
        return p["name"] if p else f"Spiller {pid + 1}"

    def touch(self, x, y):
        self.dirty.add((x, y))
        self.ver += 1
        self._fold_mark(x, y)
        for c in self.__dict__.get("_rgs", {}).values():   # vejfindingens felter regnes om for hver ejer
            c[2].add((x, y))

    def _fold_mark(self, x, y):
        """Foldene regnes kun om, når en fold, en bygning eller ejeren af et felt ændrer sig (ikke ved hvert lille
        skridt i markarbejdet)."""
        t = self.tiles[y][x]
        sig = (t.t == "pasture", t.b if t.b in BUILDINGS else None, t.o)
        fs = self.__dict__.setdefault("_fsig", {})
        if fs.get((x, y)) != sig:
            fs[(x, y)] = sig
            self.fver = getattr(self, "fver", 0) + 1

    def wet_ditches(self):
        """Grøfter, der hænger sammen med en sø eller en brønd (caches indtil noget ændrer sig)."""
        c = getattr(self, "_wet", None)
        if c and c[0] == self.ver:
            return c[1]
        T = self.tiles
        wet, dq = set(), deque()
        for y, row in enumerate(T):
            for x, t in enumerate(row):
                if t.t == "ditch" and any(self._source(x, y, dx, dy) for dx, dy in N4):
                    wet.add((x, y))
                    dq.append((x, y))
        while dq:
            x, y = dq.popleft()
            for dx, dy in N4:
                nx, ny = x + dx, y + dy
                if not self.inb(nx, ny):
                    continue
                k = 0
                while k < CULVERT_SPAN and self.inb(nx, ny) and T[ny][nx].t in ROADS:
                    nx, ny, k = nx + dx, ny + dy, k + 1     # rør under vejen: grøften fortsætter på den anden side
                if not self.inb(nx, ny):
                    continue
                if (nx, ny) not in wet and T[ny][nx].t == "ditch":
                    wet.add((nx, ny))
                    dq.append((nx, ny))
        self._wet = (self.ver, wet)
        return wet

    def _source(self, x, y, dx, dy):
        """Er der en sø eller brønd i retningen (dx, dy) – evt. på den anden side af en vej?"""
        for k in (1, 2):
            nx, ny = x + dx * k, y + dy * k
            if not self.inb(nx, ny):
                return False
            n = self.tiles[ny][nx]
            if n.t == "water" or n.b == "broend":
                return True
            if k == 1 and n.t not in ROADS:
                return False
        return False

    def stats(self, pid):
        """Opsummering af en spillers jord (caches indtil noget ændrer sig)."""
        c = self._stats.get(pid)
        if c and c[0] == self.ver:
            return c[1]
        s = {"tiles": 0, "b": {}, "bpos": {}, "crops": {}}
        for y, row in enumerate(self.tiles):
            for x, t in enumerate(row):
                if t.o != pid or (x, y) in self.ctiles:
                    continue
                s["tiles"] += 1
                if t.b and (t.ba is None or (t.ba[0], t.ba[1]) == (x, y)):
                    s["b"][t.b] = s["b"].get(t.b, 0) + 1
                    s["bpos"].setdefault(t.b, []).append((x, y))
                if t.crop:
                    k = s["crops"].setdefault(t.crop, [0, 0, 0, 0])
                    k[0] += 1
                    k[1] += (t.g >= 1 and not t.dead and not CROPS[t.crop].get("green"))
                    k[2] += t.dead
                    k[3] += t.pest
        self._stats[pid] = (self.ver, s)
        return s

    def auto_on(self, p, key):
        """Er automatikken slået til for spilleren? (Computerspillere har alt slået til.)"""
        if not p:
            return False
        if p.get("ai"):
            return True
        if key == "maelk":
            return p.get("milk_auto", True)
        return p.get("auto", {}).get(key, AUTO_OPTS[key][3])

    def shelter_cells(self):
        """Felter i læ af et læhegn (inden for LAEHEGN_REACH felter) – caches pr. dag."""
        c = self.__dict__.get("_shelter")
        if c and c[0] == (self.day, self.ver):
            return c[1]
        out = set()
        R = LAEHEGN_REACH
        for p in self.players.values():
            for k, col in (p.get("yfence") or {}).items():
                if col != "laehegn":
                    continue
                x, y, _d = map(int, k.split(","))
                for dy in range(-R, R + 2):
                    for dx in range(-R, R + 2):
                        out.add((x + dx, y + dy))
        self._shelter = ((self.day, self.ver), out)
        return out

    def feed_order(self, p):
        """Foderplanen: med en fodersilo fodres der med det, der er billigst på markedet i dag – ellers kartofler,
        majs, byg og hvede (billigst ved normalpris først)."""
        if p and self.capacity(p, "fodersilo"):
            return tuple(sorted(FEED_ORDER, key=lambda g: self.market[g]["p"]))
        return FEED_ORDER

    def has_digger(self, pid):
        """Har gården en rendegraver?"""
        return any(VEHICLES.get(t["k"], {}).get("digger") for t in self.tractors if t["o"] == pid)

    def robot_cap(self, p):
        """Køer, malkerobotterne kan klare: pladserne i de kostalde, der har en robot (+ gamle robotbygninger)."""
        n = 0
        for k in list((p.get("robots") or {})):
            x, y = map(int, k.split(","))
            b = self.tiles[y][x].b if self.inb(x, y) else None
            if b in ROBOT_COST and self.tiles[y][x].o == p["id"]:
                n += BUILDINGS[b]["cap"]
        return n + self.capacity(p, "malkerobot")

    def act_robot(self, pid, x, y):
        """Installer en malkerobot i kostalden."""
        p = self.players.get(pid)
        if not p or not self.inb(x, y):
            return
        ax, ay = self.anchor(x, y)[:2]
        t = self.tiles[ay][ax]
        if t.o != pid or t.b not in ROBOT_COST:
            return
        key = f"{ax},{ay}"
        rb = p.setdefault("robots", {})
        if key in rb:
            return
        cost = ROBOT_COST[t.b]
        if p["money"] < cost and not self.sandbox():
            self.log(f"En malkerobot koster {kr(cost)}.", pid, "err")
            return
        p["money"] -= cost
        self.book(p, "byggeri", -cost)
        rb[key] = True
        self.touch(ax, ay)
        self.log(f"Malkerobotten er installeret i {BUILDINGS[t.b]['navn'].lower()} (-{kr(cost)}): køerne bliver "
                 f"malket, når de vil, og giver {int(ROBOT_MILK * 100)}% mere mælk.", pid, "good")

    def _robots_fix(self, p):
        """Ældre gemte spil: en malkerobot-bygning flyttes ind i den nærmeste kostald uden robot."""
        bp = self.stats(p["id"])["bpos"]
        old = list(bp.get("malkerobot", []))
        if not old:
            return
        rb = p.setdefault("robots", {})
        stalls = [(tuple(pos), k) for k in ROBOT_COST for pos in bp.get(k, [])]
        for pos in old:
            free = [s_ for s_ in stalls if f"{s_[0][0]},{s_[0][1]}" not in rb]
            if not free:
                continue                                     # ingen kostald – den gamle robot bliver stående
            (sx, sy), _k = min(free, key=lambda s_: abs(s_[0][0] - pos[0]) + abs(s_[0][1] - pos[1]))
            rb[f"{sx},{sy}"] = True
            t = self.tiles[pos[1]][pos[0]]
            t.b, t.ba, t.t = None, None, "gravel"
            self.touch(pos[0], pos[1])

    def has_feeder(self, pid):
        """Har gården en gummiged til udfodringen?"""
        return any(VEHICLES.get(t["k"], {}).get("feeder") for t in self.tractors if t["o"] == pid)

    def has_foderhal(self, p):
        """Har gården en rundbuehal bygget om til foderhal?"""
        return self.stats(p["id"])["b"].get("rundbuehal_foder", 0) > 0

    def feed_factor(self, pid):
        """Grovfoder, dyrene skal have: 10% mindre spild med en gummiged, 15% med den store."""
        vs = [VEHICLES.get(t["k"], {}) for t in self.tractors if t["o"] == pid]
        return 0.85 if any(v.get("big_feeder") for v in vs) else 0.9 if any(v.get("feeder") for v in vs) else 1.0

    def gylle_cap(self, p):
        """Plads til gylle: fortanken under staldene + gylletankene."""
        return BASE_GYLLE + self.capacity(p, "gylletank")

    def _harrow_ok(self, p, t, forced=False):
        """Harves feltet med stubharven i stedet for at blive pløjet? (kun stubmark uden afgrøde)"""
        if not p or t.t != "stub" or t.crop or t.b:
            return False
        return forced or (p.get("plowmode") == "harve" and self.owns_tool(p, "harrow"))

    def use_gylle(self, p):
        """Gødes der med gylle (valgt, og der er nok i tanken)? Ellers kunstgødning."""
        return p.get("fert", "gylle") == "gylle" and p.get("gylle", 0) >= GYLLE_PER_TILE

    def capacity(self, p, group):
        """Samlet plads i alle bygninger af en slags (små + store)."""
        b = self.stats(p["id"])["b"]
        return sum(n * (BUILDINGS[k]["cap"] if BUILDINGS[k]["group"] == group else BUILDINGS[k].get("also", {}).get(group, 0))
                   for k, n in b.items() if k in BUILDINGS)

    def pasture(self, pid):
        """Foldfelter, der hænger sammen med en af spillerens stalde (caches, til en fold eller bygning ændres)."""
        fv = getattr(self, "fver", 0)
        c = getattr(self, "_past", {}).get(pid)
        if c and c[0] == fv:
            return c[1]
        T = self.tiles
        seen, dq = set(), deque()
        for y, row in enumerate(T):
            for x, t in enumerate(row):
                if t.o == pid and t.b in BUILDINGS and BUILDINGS[t.b]["group"] in ("kostald", "faarestald", "hestestald",
                                                                                   "svinestald", "hoensehus"):
                    for dx, dy in N4:
                        nx, ny = x + dx, y + dy
                        if self.inb(nx, ny) and T[ny][nx].t == "pasture" and T[ny][nx].o == pid \
                                and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            dq.append((nx, ny))
        while dq:
            x, y = dq.popleft()
            for dx, dy in N4:
                nx, ny = x + dx, y + dy
                if self.inb(nx, ny) and (nx, ny) not in seen and T[ny][nx].t == "pasture" and T[ny][nx].o == pid:
                    seen.add((nx, ny))
                    dq.append((nx, ny))
        res = sorted(seen, key=lambda c: (c[0] + c[1], c[0]))
        if not hasattr(self, "_past"):
            self._past = {}
        self._past[pid] = (fv, res)
        return res

    FOLD_GROUPS = ("kostald", "faarestald", "hestestald", "svinestald", "hoensehus")
    FOLD_ORDER = ("cows", "horses", "sheep", "pigs", "chickens")   # hvem der får plads først i en fælles fold

    def folds(self, pid):
        """Hver fold for sig: [(felter sorteret nærmest stalden først, {staldtyper der rører folden})] (caches)."""
        fv = getattr(self, "fver", 0)
        c = getattr(self, "_foldc", {}).get(pid)
        if c and c[0] == fv:
            return c[1]
        T, out, seen = self.tiles, [], set()
        for comp in self.fold_parts(pid):
            groups, near = set(), []
            for (x, y) in comp:
                for dx, dy in N4:
                    nx, ny = x + dx, y + dy
                    if self.inb(nx, ny) and T[ny][nx].o == pid and T[ny][nx].b in BUILDINGS and \
                            BUILDINGS[T[ny][nx].b]["group"] in self.FOLD_GROUPS:
                        groups.add(BUILDINGS[T[ny][nx].b]["group"])
                        near.append((x, y))
            if not groups:
                continue                                     # en fold, der ikke rører en stald, tæller ikke
            comp = sorted(comp, key=lambda c_: (min(abs(c_[0] - a) + abs(c_[1] - b) for a, b in near), c_))
            out.append((comp, groups))
        self.__dict__.setdefault("_foldc", {})[pid] = (fv, out)
        return out

    def _fold_need(self, p, kind, n=None):
        """Foldfelter, en dyreart skal bruge (grise og høns kun, når de går økologisk på græs)."""
        n = p.get(kind, 0) if n is None else n
        if kind in GRAZERS:
            return n * GRAZERS[kind]
        if kind in ECO_KINDS and (p.get("eco") or {}).get(kind):
            return n * ECO_KINDS[kind]
        return 0.0

    def fold_alloc(self, p, skip=None):
        """Fordel dyrene på foldene: hver art kun i de folde, der rører dens egen stald. Returnerer
        ({art: felter fået}, [ledige felter pr. fold], {felt: art})."""
        key = (getattr(self, "fver", 0), skip, tuple(p.get(k, 0) for k in self.FOLD_ORDER),
               tuple(sorted((p.get("eco") or {}).items())))
        ca = self.__dict__.setdefault("_falloc", {})
        hit = ca.get(p["id"], {}).get(key)
        if hit is not None:
            return hit
        res = self._fold_alloc(p, skip)
        d_ = ca.setdefault(p["id"], {})
        if len(d_) > 16:
            d_.clear()
        d_[key] = res
        return res

    def _fold_alloc(self, p, skip=None):
        folds = self.folds(p["id"])
        free = [float(len(f[0])) for f in folds]
        got, used = {}, [0] * len(folds)
        tiles = {}
        for k in self.FOLD_ORDER:
            if k == skip:
                continue
            need = self._fold_need(p, k)
            g = ANIMALS[k][0]
            got[k] = 0.0
            for i, (comp, groups) in enumerate(folds):
                if need <= 1e-9:
                    break
                if g not in groups or free[i] <= 1e-9:
                    continue
                take = min(need, free[i])
                n0 = used[i]
                for c_ in comp[n0:n0 + int(math.ceil(take - 1e-9))]:
                    tiles[c_] = k
                used[i] = n0 + int(math.ceil(take - 1e-9))
                free[i] -= take
                need -= take
                got[k] += take
        return got, free, tiles

    def animal_cap(self, p, kind):
        """Hvor mange dyr der er plads til. Køer, heste og får kræver både stald og fold – i en fold, der rører
        deres egen stald."""
        cap = self.capacity(p, ANIMALS[kind][0])
        if kind in GRAZERS:
            _, free, _t = self.fold_alloc(p, skip=kind)
            g = ANIMALS[kind][0]
            room = sum(fr for fr, (comp, groups) in zip(free, self.folds(p["id"])) if g in groups)
            cap = min(cap, int(room / GRAZERS[kind] + 1e-6))
        return max(0, cap)

    def fold_tiles_for(self, p, kind):
        """Antal foldfelter i de folde, der rører dyreartens stald."""
        g = ANIMALS[kind][0]
        return sum(len(comp) for comp, groups in self.folds(p["id"]) if g in groups)

    def fold_use(self, p):
        """{felt: dyreart} – hvem der græsser hvor (hver art i folden ved sin egen stald)."""
        return self.fold_alloc(p)[2]

    def feed_need(self, p, kind):
        """Foder pr. dag for en dyreart uden for folden (grise og høns på græs æder lidt mere)."""
        n = p.get(kind, 0) * ANIMALS[kind][4]
        return n * (1.0 + ECO_FEED * self.eco_share(p, kind)) if kind in ECO_KINDS else n

    def eco_share(self, p, kind):
        """Hvor stor en del af grisene/hønsene, der går på græs (0 … 1) – folden ved deres stald skal have plads."""
        if not (p.get("eco") or {}).get(kind) or not p.get(kind, 0):
            return 0.0
        need = self._fold_need(p, kind)
        got = self.fold_alloc(p)[0].get(kind, 0.0)
        return max(0.0, min(1.0, got / need)) if need > 0 else 0.0

    def sheds(self, pid):
        """[(ankerposition, pladser)] for spillerens maskinhuse."""
        bpos = self.stats(pid)["bpos"]
        return [(tuple(pos), BUILDINGS[k]["cap"]) for k in BUILDINGS if BUILDINGS[k]["group"] == "maskinhus"
                for pos in bpos.get(k, [])]

    def anchor(self, x, y):
        """(ankerx, ankery, bredde, dybde) for bygningen på feltet."""
        t = self.tiles[y][x]
        return t.ba if t.ba else (x, y, 1, 1)

    def yield_factor(self, t):
        """Udbytte ud fra jordens næring, ukrudt og sædskifte."""
        soil = 0.55 + 0.45 * min(1.0, t.n / 70.0)
        weeds = 1.0 - 0.4 * min(100.0, t.wd) / 100.0
        rot = 1.0
        if t.lc and t.crop and t.crop != "graes":
            rot = 0.85 if t.lc == t.crop else 1.08
        lime = 1.0 if t.kc >= 55 else 0.75 + 0.25 * t.kc / 55      # sur jord giver mindre
        return soil * weeds * rot * lime

    def job_cost(self, p, tool, t, crop, kind, src=None):
        """Pris for ét felt: arbejde + leje. Gødskning bruger gylle, hvis der er nok.
        src: 'gylle' eller 'kunst', når redskabet bestemmer det (man kører selv med gyllevogn eller spreder)."""
        cost = self._cost(tool, t, crop)
        if cost is None:
            return None, 0, False
        if p and p.get("scen") == "oko" and (tool == "spray" or (tool == "fertilize" and src != "gylle" and
                                                                 not self.use_gylle(p))):
            return None, 0, False                             # økologisk: ingen sprøjtemidler eller kunstgødning
        if tool == "plow" and src != "plov" and self._harrow_ok(p, t, src == "harve"):
            return HARROW_COST, 0, True                       # stubharven (egen): billigere og hurtigere
        if src == "gylle":
            use_gylle = tool == "fertilize" and p.get("gylle", 0) >= GYLLE_PER_TILE
        elif src == "kunst":
            use_gylle = False
        else:
            use_gylle = tool == "fertilize" and self.use_gylle(p)
        inp = self._input_for(tool, use_gylle)
        if inp and p.get("inputs", {}).get(inp, 0) < 1:
            cost += self.input_price(inp) * INPUT_SPOT          # intet på lager: købes på stedet
        cost = round(cost, 2)
        rent = self.rent(p, tool, "orchard" if tool == "harvest" and t.crop and CROPS[t.crop].get("orchard") else
                         "potato" if tool == "harvest" and t.crop == "kartofler" and vkind(kind) == "tractor" else kind)
        if use_gylle:                                       # gylle køres ud med gyllevognen (egen eller lejet)
            rent = 0 if self.owns_tool(p, "gylle") or src == "gylle" else RENT_GYLLE
        return cost + rent, rent, use_gylle

    @staticmethod
    def _input_for(tool, gylle=False):
        if tool == "fertilize" and not gylle:
            return "goedning"
        return {"spray": "sproejte", "lime": "kalk"}.get(tool)

    def input_price(self, key):
        """Dagspris pr. enhed: sæsonpris og evt. tilbud."""
        i = INPUTS[key]
        price = i["base"] * i["season"].get(self.month(), 1.0)
        off = self.offers.get(key)
        if off and off["until"] >= self.day:
            price *= 1 - off["pct"]
        return price

    def act_buyinput(self, pid, key, qty):
        p = self.players.get(pid)
        if not p or key not in INPUTS or qty <= 0:
            return
        cost = round(self.input_price(key) * qty)
        if p["money"] < cost:
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= cost
        self.book(p, "varekoeb", -cost)
        if key == "saasaed":
            p["forraad"] = p.get("forraad", 0.0) + qty
            self.log(f"Du købte såsæd for {kr(qty)} og betalte {kr(cost)}.", pid, "good")
        else:
            inv = p.setdefault("inputs", {})
            inv[key] = inv.get(key, 0) + qty
            self.log(f"Du købte {INPUTS[key]['navn'].lower()} til {qty} felter for {kr(cost)}. "
                     f"Lager: {int(inv[key])} felter.", pid, "good")

    LOCAL_NEWS = [
        ("Høstmarked på torvet", "Der er høstmarked i {by} på lørdag med musik, pølser og traktortræk for børnene."),
        ("Kirkekoncert", "Kirkens kor synger sensommerens sange i kirken søndag aften. Alle er velkomne."),
        ("Rideskolen søger heste", "Rideskolen har flere elever end nogensinde og søger pensionsheste på egnen."),
        ("Mejeriet fejrer jubilæum", "Mejeriet fejrer 75 år med åbent hus og gratis is til alle."),
        ("Ny cykelsti", "Kommunen vil lave en cykelsti langs hovedvejen, så børnene sikkert kan cykle til skole."),
        ("Storkene er tilbage", "Et storkepar er set på engen syd for {by}. Det er første gang i mange år."),
        ("Fodboldklubben vandt", "{by} IF vandt 3–1 over naboklubben efter et sent mål af bagerens søn."),
        ("Købmanden udvider", "Købmanden bygger nyt lager og vil sælge flere lokale varer fra egnens gårde."),
        ("Sommerfest i forsamlingshuset", "Der er sommerfest med ringridning og dans i forsamlingshuset."),
        ("Traktortræf", "Veterantraktorklubben holder træf ved {by}. Den ældste traktor er fra 1938."),
    ]

    def add_news(self, title, text, big=False):
        nid = (self.news[-1]["id"] + 1) if self.news else 1
        self.news = (self.news + [{"id": nid, "day": self.day, "title": title, "text": text, "big": big}])[-40:]

    def _aarets_gaard(self):
        if self.sandbox():
            return                                    # i sandkassen kåres der ikke nogen årets gård
        self._aarets_gaard_run()

    def _aarets_gaard_run(self):
        """Årets gård: formue, høst og dyr – spillerne dyster med computernaboerne."""
        yr = self.year() - 1
        rng = self.rng
        if not self.npcs:
            self.npcs = [{"name": f"Gårdejer {n}", "worth": rng.uniform(55000, 80000), "harv": 0, "dyr": rng.randint(0, 20)}
                         for n in NEIGHBOURS[:max(0, 3 - len(self.ai_players()))]]
        for n in self.npcs:
            n["worth"] = n["worth"] * rng.uniform(1.04, 1.18) + rng.uniform(4000, 16000)
            n["harv"] = int(rng.uniform(700, 1800) * (1 + 0.3 * yr))
            n["dyr"] = int(n["dyr"] * rng.uniform(1.0, 1.25) + rng.randint(0, 8))
        rows = [{"name": n["name"], "worth": int(n["worth"]), "harv": n["harv"], "dyr": n["dyr"], "pid": None}
                for n in self.npcs]
        for p in self.players.values():
            h = p["hist"][-1] if p.get("hist") else {}
            rows.append({"name": p["name"], "worth": int(self.worth(p)), "pid": p["id"],
                         "harv": int(sum(v for g, v in h.get("harv", {}).items())),
                         "dyr": int(sum(p.get(k, 0) * (0.05 if k == "chickens" else 1) for k in ANIMALS))})
        for key in ("worth", "harv", "dyr"):
            for i, r in enumerate(sorted(rows, key=lambda r: -r[key])):
                r["pts"] = r.get("pts", 0) + len(rows) - 1 - i
        rows.sort(key=lambda r: (-r["pts"], -r["worth"]))
        win = rows[0]
        self.aarets = {"year": yr, "rows": rows, "winner": win["name"]}
        if win["pid"] is not None and win["pid"] in self.players:
            p = self.players[win["pid"]]
            p["trophies"] = p.get("trophies", 0) + 1
            p["money"] += AARETS_PRIZE
            self.book(p, "praemie", AARETS_PRIZE)
            self.log(f"Tillykke! {p['name']} er kåret som Årets gård {yr} og får en pokal og {kr(AARETS_PRIZE)}.",
                     None, "big")
        self.add_news(f"{win['name']} er Årets gård {yr}",
                      "Egnens landboforening har kåret årets gård ud fra formue, høst og dyr. " +
                      " · ".join(f"{i + 1}. {r['name']} ({r['pts']} point)" for i, r in enumerate(rows[:4])), big=True)

    def _new_offers(self):
        """Grovvarehandlen har af og til tilbud på gødning, sprøjtemiddel eller såsæd."""
        self.offers = {k: v for k, v in self.offers.items() if v["until"] >= self.day}
        if self.rng.random() < 0.45:
            key = self.rng.choice([k for k in INPUTS if k not in self.offers] or [None])
            if key:
                pct, days = self.rng.choice((0.15, 0.2, 0.25, 0.3)), self.rng.randint(10, 20)
                self.offers[key] = {"pct": pct, "until": self.day + days}
                self.add_news(f"Tilbud på {INPUTS[key]['navn'].lower()}",
                              f"Grovvarehandlen sætter prisen på {INPUTS[key]['navn'].lower()} ned med {int(pct * 100)}% "
                              f"de næste {days} dage.")
                self.log(f"TILBUD hos grovvarehandlen: {INPUTS[key]['navn'].lower()} {int(pct * 100)}% billigere "
                         f"de næste {days} dage. Se Marked › Indkøb.", None, "big")

    def _stock_part(self, p, tool, crop, gylle):
        """Så meget af prisen, der kan tages fra lageret af såsæd (i kroner)."""
        part = CROPS[crop]["seed"] if tool == "sow" and crop in CROPS else 0
        return min(part, p.get("forraad", 0.0))

    # ── driftsregnskab: pr. mark, afgrøde, dyr og maskine ────────────────────
    def val(self, g, amt):
        """Værdien af en vare til dagens pris (bruges til at værdisætte høst og produktion)."""
        mk = self.market.get(g)
        return amt * (mk["p"] if mk else GOODS.get(g, {}).get("base", 0.0))

    def _field_cost(self, p, pos, amount):
        """Udgifter, der hører til et felt, samles, til feltet høstes."""
        if pos is None or amount <= 0 or tuple(pos) in self.ctiles:
            return
        k = f"{int(pos[0])},{int(pos[1])}"
        ta = p.setdefault("tacc", {})
        ta[k] = ta.get(k, 0.0) + amount

    def _acc(self, p, group, key, **add):
        """Læg tal til årets regnskab for en afgrøde/dyreart/maskine: p[group][år][key][felt] += værdi."""
        d = p.setdefault(group, {}).setdefault(str(self.year()), {}).setdefault(str(key), {})
        for f, v in add.items():
            d[f] = d.get(f, 0) + v
        return d

    def _macc(self, tr, **add):
        p = self.players.get(tr["o"])
        if not p or tr.get("hire"):
            return
        d = self._acc(p, "macc", tr["id"], **add)
        d["k"] = tr["k"]

    def _work_diesel(self, tr):
        if not tr or tr.get("hire"):
            return 0.0
        return FUEL_TILE * fuel_factor(tr["k"]) * (1.1 if "tuning" in tr.get("upg", ()) else 1.0) * \
            self.diesel_price()

    def _pay_work(self, p, tool, crop, gylle, cost, tr=None, pos=None):
        """Betal for ét felts arbejde – såsæd, gødning og sprøjtemiddel tages først fra lageret."""
        if tool == "fertilize" and not gylle and p.get("fert", "gylle") == "gylle" and not p.get("ai") and \
                any(p.get(k, 0) for k in ANIMALS) and self.day - p.get("gylle_warn", -99) >= 10:
            p["gylle_warn"] = self.day                        # gylle valgt, men tanken er tom
            self.log("Gylletanken er tom – der gødes med kunstgødning i stedet (dyrere). Vent, til der er samlet "
                     "mere gylle, eller vælg kunstgødning.", p["id"], "info")
        inp = self._input_for(tool, gylle)
        inv = p.setdefault("inputs", {})
        if pos is not None and tool not in ("snow", "mow"):
            extra = self.input_price(inp) if inp and inv.get(inp, 0) >= 1 else 0.0
            self._field_cost(p, pos, cost + extra + self._work_diesel(tr))
            if tr and not tr.get("hire"):
                self._macc(tr, tiles=1, alt=self.hire_harvest() if tool == "harvest" else SNOW_PAY if tool == "snow"
                           else RENT.get(tool, 0) * 2)
        if inp and inv.get(inp, 0) >= 1:
            inv[inp] -= 1
        stock = self._stock_part(p, tool, crop, gylle)
        if stock:
            p["forraad"] -= stock
        paid = cost - stock
        p["money"] -= paid
        self.book(p, "markarbejde", -paid)
        return paid

    def act_preorder(self, pid, amount):
        """Forudbestil såsæd og gødning i vintermånederne med rabat."""
        p = self.players.get(pid)
        if not p or amount <= 0:
            return
        if self.month() not in PREORDER_MONTHS:
            self.log("Forudbestilling kan kun ske i december, januar og februar.", pid, "err")
            return
        price = int(amount * (1 - PREORDER_DISCOUNT))
        if p["money"] < price:
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= price
        self.book(p, "varekoeb", -price)
        p["forraad"] = p.get("forraad", 0.0) + amount
        self.log(f"Du forudbestilte såsæd og gødning for {kr(amount)} og betalte {kr(price)}. "
                 "Forrådet bruges automatisk, når der sås og gødes.", pid, "good")

    def owns_tool(self, p, tool):
        return any(EQUIPMENT[k]["tool"] == tool for k in p.get("equip", []))

    def rent(self, p, tool, kind="tractor"):
        if tool == "harvest" and kind == "orchard":
            return ORCHARD_PICK
        if tool == "harvest" and kind == "potato":       # egen kartoffeloptager bag traktoren
            return 0
        if tool == "harvest":                    # egen mejetærsker = ingen leje, ellers maskinstationen
            return self.hire_harvest() if kind == "maskinstation" or vkind(kind) != "combine" else 0
        if tool not in RENT or self.owns_tool(p, "fertilize" if tool == "lime" else tool):
            return 0
        return RENT[tool]

    @staticmethod
    def store_group(g):
        """Ensilage ligger i plansiloen, tømmer på tømmerpladsen, alt andet (korn, frugt, halm) i kornlageret."""
        return "ensilage" if g in ("graes", "majsens") else "tommer" if g == "tommer" else "baller" if g in BALE_GOODS else "korn"

    def storage_cap(self, p, g=None):
        if g is not None and self.store_group(g) == "ensilage":
            return BASE_SILAGE + self.capacity(p, "plansilo")
        if g is not None and self.store_group(g) == "tommer":
            return self.capacity(p, "toemmerplads") + (TIMBER_YARD if p.get("old_yard") else 0)
        if g is not None and self.store_group(g) == "baller":
            return BASE_BALES + self.capacity(p, "balleplads")
        return BASE_STORAGE + self.capacity(p, "silo") + self.capacity(p, "kartoffellager") + \
            self.capacity(p, "fodersilo")

    def stored(self, p, g=None):
        grp = self.store_group(g) if g is not None else "korn"
        return sum(p["inv"].get(c, 0) for c in STORE_GOODS if self.store_group(c) == grp)

    def vehicles_of(self, pid):
        """[(id, kind)] – serveren kender køretøjerne, klienten kun deres visning."""
        if self.tractors:
            return [(t["id"], t["k"]) for t in self.tractors if t["o"] == pid and not t.get("hire")]
        return [(t[0], t[6]) for t in self.tractor_view if t[1] == pid and not VEHICLES.get(t[6], {}).get("hidden")]

    def n_vehicles(self, pid):
        return len(self.vehicles_of(pid))

    # ── maskinhuse: båse, redskaber og vogne ─────────────────────────────────
    @staticmethod
    def shed_key(pos):
        return f"{int(pos[0])},{int(pos[1])}"

    def shed_bays(self, pid):
        """{"x,y": antal rækker (hver to båse dyb)} for spillerens maskinhuse."""
        bpos = self.stats(pid)["bpos"]
        return {self.shed_key(pos): BUILDINGS[k]["bays"] for k in BUILDINGS if BUILDINGS[k]["group"] == "maskinhus"
                for pos in bpos.get(k, [])}

    def item_size(self, item):
        if item.startswith("v"):
            tr = next((t for t in self.tractors if t["id"] == int(item[1:])), None) if self.tractors else \
                next((t for t in self.tractor_view if t[0] == int(item[1:])), None)
            kind = (tr["k"] if isinstance(tr, dict) else tr[6]) if tr else None
            return 2 if kind and vkind(kind) in ("truck", "combine") else 1
        return 1

    def item_name(self, item):
        if item.startswith("h:"):
            return "Jagthytte"
        if item.startswith("v"):
            tr = next((t for t in self.tractors if t["id"] == int(item[1:])), None) if self.tractors else \
                next((t for t in self.tractor_view if t[0] == int(item[1:])), None)
            kind = (tr["k"] if isinstance(tr, dict) else tr[6]) if tr else None
            return f"{vname(kind)} #{item[1:]}" if kind else item
        if item.startswith("e:"):
            return EQUIPMENT[item[2:]]["navn"] if item[2:] in EQUIPMENT else item
        w = item[2:].split("#")[0]
        return WAGONS[w]["navn"] if w in WAGONS else item

    def owned_items(self, p):
        pid = p["id"]
        out = [f"v{t['id']}" for t in self.tractors if t["o"] == pid and not t.get("hire") and vkind(t["k"]) != "car"]
        out += [f"e:{k}" for k in p.get("equip", []) if k in GEAR_IMP]
        out += [f"w:{w}#{i}" for w, n in p.get("wagons", {}).items() for i in range(n)]
        return out

    @staticmethod
    def bay_idx(slot, cols, size):
        """Båsene en genstand fylder: 1 bås, eller en hel række (forreste og bageste bås) for store maskiner."""
        c = slot % cols
        return [c, c + cols] if size == 2 else [slot]

    def _free_bay(self, lay, cols, size, prefer_front=True):
        if size == 2:
            for c in range(cols):
                if lay[c] is None and lay[c + cols] is None:
                    return c
            return None
        rows = (1, 0) if prefer_front else (0, 1)
        for r in rows:
            for c in range(cols):
                if lay[r * cols + c] is None:
                    return r * cols + c
        return None

    def bays_used(self, p):
        lay = p.get("park", {})
        tot = sum(n * SHED_ROWS for n in self.shed_bays(p["id"]).values())
        used = sum(1 for k, l in lay.items() for it in l if it)
        return used, tot

    def _gear_spot(self, p, skip=None):
        """Et sted ved gården, hvor et redskab eller en vogn kan stå udenfor."""
        pid = p["id"]
        hx, hy = p["home"]
        taken = {tuple(t["hs"]) for t in self.tractors if t["o"] == pid} | \
            {tuple(v) for k, v in p.get("gear_pos", {}).items() if k != skip}
        best = None                                        # fliser (parkeringsplads) foretrækkes, ellers tættest på
        for y in range(hy - 8, hy + 9):
            for x in range(hx - 8, hx + 9):
                if (x, y) == (hx, hy) or not self.inb(x, y) or (x, y) in taken:
                    continue
                t = self.tiles[y][x]
                if t.o == pid and not t.b and not t.crop and t.t in ("grass", "gravel", "stub", "field", "fliser"):
                    d = max(abs(x - hx), abs(y - hy)) + (0 if t.t == "fliser" else 6)
                    if best is None or d < best[0]:
                        best = (d, [x, y])
        return best[1] if best else [hx, hy]

    def _sync_park(self, p, quiet=False):
        """Hold styr på, hvor alle maskiner, redskaber og vogne står: en bås i et maskinhus, ude på jorden
        eller koblet på en traktor. Nye ting får en ledig bås, og er der ikke plads, står de udenfor."""
        pid = p["id"]
        bays = self.shed_bays(pid)
        park = p.setdefault("park", {})
        gpos = p.setdefault("gear_pos", {})
        for k in list(park):
            if k not in bays:
                del park[k]
        for k, cols in bays.items():
            lay = park.get(k) or []
            park[k] = (lay + [None] * (cols * SHED_ROWS))[:cols * SHED_ROWS]
        owned = set(self.owned_items(p))
        mine = [t for t in self.tractors if t["o"] == pid]
        for tr in mine:
            if tr.get("hitch") and tr["hitch"] not in owned:
                tr["hitch"] = None
                if tr.get("man"):
                    self._cargo_abort(tr)
                    tr["man"]["wagon"] = None
        hitched = {tr["hitch"] for tr in mine if tr.get("hitch")}
        for k, lay in park.items():                         # fjern det, der er solgt eller koblet på
            cols = bays[k]
            for i, it in enumerate(lay):
                if it and (it not in owned or it in hitched):
                    lay[i] = None
            for c in range(cols):                           # en stor maskine skal fylde hele rækken
                a, b = lay[c], lay[c + cols]
                for it in {a, b} - {None}:
                    if self.item_size(it) == 2 and a != b:
                        lay[c] = None if lay[c] == it else lay[c]
                        lay[c + cols] = None if lay[c + cols] == it else lay[c + cols]
            seen = set()
            for i, it in enumerate(lay):                    # samme ting to steder: behold den første
                if it and self.item_size(it) == 1:
                    if it in seen:
                        lay[i] = None
                    seen.add(it)
        placed = {}
        for k, lay in park.items():
            for it in lay:
                if it and it not in placed:
                    placed[it] = k
        for it in list(gpos):
            if it not in owned or it in hitched or it in placed:
                del gpos[it]

        def place(it, prefer=None, front=True):
            size = self.item_size(it)
            for k in ([prefer] if prefer in park else []) + [k for k in park if k != prefer]:
                slot = self._free_bay(park[k], bays[k], size, front)
                if slot is not None:
                    for i in self.bay_idx(slot, bays[k], size):
                        park[k][i] = it
                    placed[it] = k
                    return k
            return None
        moved_out = []
        for tr in mine:
            if tr.get("hire") or vkind(tr["k"]) == "car":
                continue
            it = f"v{tr['id']}"
            sp = tr.get("spot")
            if sp:                                         # fast plads på fliserne (valgt med P)
                ok_ = self.inb(*sp) and park_tile_ok(self.tiles[sp[1]][sp[0]], pid)
                if ok_:
                    tr["out"] = True
                    if list(tr["hs"]) != list(sp):
                        tr["hs"] = list(sp)
                        if tr["s"] == "parked":
                            tr["s"] = "idle"
                    continue
                tr.pop("spot", None)                       # fliserne er væk: tilbage i maskinhuset
            k = placed.get(it)
            if k is None:
                k = place(it, self.shed_key(tr["hs"]))
            if k is not None:
                hs = [int(v) for v in k.split(",")]
                if tr.get("out") and not quiet:
                    self.log(f"{vname(tr['k'])} er kommet i ly i maskinhuset.", pid, "good")
                tr["out"] = False
            else:
                hs = tr["hs"] if tr.get("out") else self._outside_spot(pid, skip=tr)
                if not tr.get("out"):
                    moved_out.append(vname(tr["k"]))
                tr["out"] = True
            if list(tr["hs"]) != list(hs):
                tr["hs"] = list(hs)
                if tr["s"] == "parked":
                    tr["s"] = "idle"
        for it in self.owned_items(p):
            if it.startswith("v") or it in placed or it in hitched or it in gpos:
                continue
            if place(it, None, front=False) is None:
                gpos[it] = self._gear_spot(p, skip=it)
        if moved_out and not quiet:
            self.log(f"Ingen plads i maskinhusene: {', '.join(moved_out)} står nu udenfor ved stuehuset "
                     "og slides af vind og vejr.", pid, "warn")

    def item_where(self, p, item):
        """('shed', key, [båse]) | ('ground', [x, y]) | ('hitch', vid) | None"""
        for k, lay in p.get("park", {}).items():
            idx = [i for i, it in enumerate(lay) if it == item]
            if idx:
                return ("shed", k, idx)
        if item in p.get("gear_pos", {}):
            return ("ground", p["gear_pos"][item])
        for tr in (self.tractors or []):
            if tr["o"] == p["id"] and tr.get("hitch") == item:
                return ("hitch", tr["id"])
        return None

    def act_park(self, pid, item, shed, slot):
        """Flyt en maskine, et redskab eller en vogn til en bås i et maskinhus – eller udenfor (shed=None)."""
        p = self.players.get(pid)
        if not p or not isinstance(item, str):
            return
        self._sync_park(p, True)
        if item not in self.owned_items(p):
            return
        name = self.item_name(item)
        where = self.item_where(p, item)
        if where and where[0] == "hitch":
            self.log(f"{name} er koblet på en traktor – kobl den af først (K).", pid, "err")
            return
        if shed is not None and int(slot) < 0:          # "flyt til et andet maskinhus": første ledige bås
            if shed not in p["park"] or (where and where[0] == "shed" and where[1] == shed):
                return
            lay_ = [None if it == item else it for it in p["park"][shed]]
            fs = self._free_bay(lay_, self.shed_bays(pid)[shed], self.item_size(item))
            if fs is None:
                self.log(f"Der er ikke plads til {name if item.startswith('v') else name.lower()} i det maskinhus.",
                         pid, "err")
                return
            slot = fs
            if item.startswith("v"):
                self.log(f"{name} kører over i det andet maskinhus.", pid, "info")
            else:
                self.log(f"{name} er flyttet til det andet maskinhus.", pid, "info")
        tr = None
        if item.startswith("v"):
            tr = next((t for t in self.tractors if t["id"] == int(item[1:])), None)
            if not tr or tr["s"] == "manual":
                self.log(f"{name} bliver kørt lige nu.", pid, "err")
                return
        elif where and where[0] == "ground":
            hx, hy = p["home"]
            gx, gy = where[1]
            near_shed = shed and max(abs(gx - int(shed.split(",")[0])), abs(gy - int(shed.split(",")[1]))) <= 6
            if max(abs(gx - hx), abs(gy - hy)) > 8 and not near_shed:
                self.log(f"{name} står ude i marken – hent den med en traktor (bak hen til den og tryk K).", pid, "err")
                return
        park, gpos = p["park"], p["gear_pos"]
        size = self.item_size(item)
        # tag genstanden fra, hvor den står nu
        origin = None
        if where and where[0] == "shed":
            origin = (where[1], where[2])
            for i in where[2]:
                park[where[1]][i] = None
        elif where and where[0] == "ground":
            del gpos[item]
        if shed is None:
            if tr:
                tr["hs"] = self._outside_spot(pid, skip=tr)
                tr["out"] = True
                if tr["s"] == "parked":
                    tr["s"] = "idle"
            else:
                gpos[item] = self._gear_spot(p, skip=item)
            self.log(f"{name} står nu udenfor ved gården.", pid, "info")
            return
        if shed not in park:
            return
        cols = self.shed_bays(pid)[shed]
        slot = int(slot)
        if not 0 <= slot < cols * SHED_ROWS:
            return
        idx = self.bay_idx(slot, cols, size)
        lay = park[shed]
        occ = []
        for i in idx:
            if lay[i] and lay[i] not in occ:
                occ.append(lay[i])
        for o in occ:                                     # dem, der står der, bytter plads eller flytter
            for i, it in enumerate(lay):
                if it == o:
                    lay[i] = None
        for i in idx:
            lay[i] = item
        for o in occ:
            osize = self.item_size(o)
            done = False
            if origin and origin[0] in park:
                ok, ocols = origin[1], self.shed_bays(pid)[origin[0]]
                tgt = self.bay_idx(ok[0], ocols, osize) if osize == 2 else (ok[:1] if osize == 1 else [])
                if osize == 2 and sorted(ok) != sorted(tgt):
                    tgt = []
                if tgt and all(park[origin[0]][i] is None for i in tgt):
                    for i in tgt:
                        park[origin[0]][i] = o
                    rest = [i for i in ok if i not in tgt]
                    origin = (origin[0], rest) if rest else None
                    done = True
            if not done:
                fs = self._free_bay(lay, cols, osize, not o.startswith("v") and False or True)
                if fs is not None:
                    for i in self.bay_idx(fs, cols, osize):
                        lay[i] = o
                    done = True
            if not done:
                if o.startswith("v"):
                    ot = next((t for t in self.tractors if t["id"] == int(o[1:])), None)
                    if ot:
                        ot["hs"] = self._outside_spot(pid, skip=ot)
                        ot["out"] = True
                else:
                    gpos[o] = self._gear_spot(p, skip=o)
                on = self.item_name(o)
                self.log(f"Der var ikke plads til {on if o.startswith('v') else on.lower()} – den står nu udenfor.",
                         pid, "warn")
        self._sync_park(p, True)

    def act_park_here(self, pid, vid, drv=None):
        """Styr selv: parkér maskinen, man kører, i maskinhuset, man holder ved."""
        tr = self._veh(pid, vid)
        p = self.players.get(pid)
        if not self._mine(tr, drv) or not p or vkind(tr["k"]) == "car":
            return
        k = self.shed_near(pid, (tr["x"], tr["y"]), 1.3)
        if not k:
            fx, fy = int(round(tr["x"])), int(round(tr["y"]))
            if self.inb(fx, fy) and park_tile_ok(self.tiles[fy][fx], pid):
                return self._park_on_tiles(p, tr, fx, fy)
            self.log("Kør hen foran et af dine maskinhuse – ud på dine fliser eller parkeringen ved traktortræk-banen "
                     "– for at parkere.", pid, "err")
            return
        tr.pop("spot", None)                               # ind i maskinhuset igen: den faste plads ude slippes
        self._sync_park(p, True)
        item = f"v{vid}"
        lay, cols = p["park"][k], self.shed_bays(pid)[k]
        if item not in lay:
            lay_ = [None if it == item else it for it in lay]
            fs = self._free_bay(lay_, cols, self.item_size(item))
            if fs is None:
                self.log("Der er ikke plads i det maskinhus – prøv et andet, eller flyt noget (højreklik på huset).",
                         pid, "err")
                return
            for lay2 in p["park"].values():
                for i, it in enumerate(lay2):
                    if it == item:
                        lay2[i] = None
            for i in self.bay_idx(fs, cols, self.item_size(item)):
                lay[i] = item
        self._release(tr)
        hs = [int(v) for v in k.split(",")]
        tr.update(hs=hs, out=False, x=float(hs[0]), y=float(hs[1]), s="parked", path=None)
        self._sync_park(p, True)
        self.log(f"{vname(tr['k'])} #{vid} er parkeret i maskinhuset.", pid, "good")

    def _park_on_tiles(self, p, tr, x, y):
        """Styr selv + P på fliserne: maskinen får sin faste plads her (fx på række med de andre)."""
        pid = p["id"]
        if any(t is not tr and list(t["hs"]) == [x, y] and t["s"] == "parked" and
               (t["o"] == pid or self.tiles[y][x].t != "fliser") for t in self.tractors):
            self.log("Der holder allerede en maskine på det felt – vælg et ledigt felt.", pid, "err")
            return
        item = f"v{tr['id']}"
        for lay in p.get("park", {}).values():               # ud af båsen i maskinhuset
            for i, it in enumerate(lay):
                if it == item:
                    lay[i] = None
        self._release(tr)
        tr.update(hs=[x, y], spot=[x, y], spot_d=tr.get("d", 0), out=True, x=float(x), y=float(y), s="parked",
                  path=None)
        self._sync_park(p, True)
        if self.tiles[y][x].t in ("pullpark", "bane"):
            self.log(f"{vname(tr['k'])} #{tr['id']} er parkeret ved traktortræk-banen. Kør den hjem til maskinhuset og "
                     "tryk P, når den skal hjem igen.", pid, "good")
        else:
            self.log(f"{vname(tr['k'])} #{tr['id']} holder nu fast her på fliserne. Kør den hen til maskinhuset og "
                     "tryk P, hvis den skal ind igen.", pid, "good")

    # ── at koble redskaber og vogne på, når man selv kører ───────────────────
    @staticmethod
    def rear_point(x, y, hdg, reach=0.75):
        sx, sy = math.cos(hdg), math.sin(hdg)
        ux, uy = (sx / HALF_W + sy / HALF_H) / 2, (sy / HALF_H - sx / HALF_W) / 2
        n = math.hypot(ux, uy) or 1.0
        return x - ux / n * reach, y - uy / n * reach

    def shed_near(self, pid, pt, margin=0.9):
        """Maskinhuset, som et punkt (traktorens bagende) er helt henne ved – ellers None."""
        for k in self.shed_bays(pid):
            ax, ay = map(int, k.split(","))
            ba = self.tiles[ay][ax].ba
            if not ba:
                continue
            x0, y0, bw, bh = ba
            if x0 - 0.5 - margin <= pt[0] <= x0 + bw - 0.5 + margin and \
                    y0 - 0.5 - margin <= pt[1] <= y0 + bh - 0.5 + margin:
                return k
        return None

    def hitch_options(self, p, x, y, hdg):
        """Redskaber og vogne, traktoren kan koble på herfra: på jorden bag den eller i maskinhuset, den bakker ind mod."""
        rx, ry = self.rear_point(x, y, hdg)
        out = [it for it, pos in p.get("gear_pos", {}).items() if math.hypot(pos[0] - rx, pos[1] - ry) <= HITCH_REACH]
        k = self.shed_near(p["id"], (rx, ry))
        if k:
            lay = p.get("park", {}).get(k, [])
            out += [it for i, it in enumerate(lay) if it and not it.startswith("v") and it not in out]
        return out, k

    def act_hitch(self, pid, vid, item=None, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv) or vkind(tr["k"]) != "tractor":
            return
        p, m = self.players[pid], tr["man"]
        self._sync_park(p, True)
        if abs(m["v"]) > 0.3:
            self.log("Hold stille for at koble på eller af.", pid, "info")
            return
        cur = tr.get("hitch")
        if cur:                                             # kobl af
            c = m.get("cargo")
            if c and (c.get("src") != "pile" or not cur.startswith("w:")):
                self.log("Kør varerne færdig, før du kobler vognen af.", pid, "err")
                return
            if c:                                           # læsset bliver på vognen
                p.setdefault("wload", {})[cur] = dict(c["load"])
                if c.get("s"):
                    p.setdefault("wshape", {})[cur] = c["s"]
                m["cargo"] = None
            rx, ry = self.rear_point(tr["x"], tr["y"], m["hdg"])
            k = self.shed_near(pid, (rx, ry))
            name = self.item_name(cur)
            if k:
                lay = p["park"][k]
                slot = self._free_bay(lay, self.shed_bays(pid)[k], 1, False)
                if slot is None:
                    self.log("Der er ingen ledig bås i maskinhuset.", pid, "err")
                    return
                lay[slot] = cur
                where = "i maskinhuset"
            else:
                gx, gy = int(round(rx)), int(round(ry))
                if not self.inb(gx, gy) or self._blocked(gx, gy) or self.tiles[gy][gx].t == "water":
                    gx, gy = int(round(tr["x"])), int(round(tr["y"]))
                p["gear_pos"][cur] = [gx, gy]
                where = "her"
            tr["hitch"] = None
            m["tool"], m["wagon"], m["job"] = None, None, None
            self.log(f"Du koblede {name.lower()} af {where}.", pid, "info")
            return
        opts, k = self.hitch_options(p, tr["x"], tr["y"], m["hdg"])
        if item is not None:
            opts = [it for it in opts if it == item]
        if not opts:
            self.log("Bak helt hen til et redskab eller en vogn – eller bak ind mod maskinhuset – og tryk K.", pid,
                     "info")
            return
        hk_ = VEHICLES.get(tr["k"], {}).get("hk", 0)
        opts = [it for it in opts if not it.startswith("w:") or hk_ >= wagon_hk(it)] or opts
        it = opts[0]
        if it.startswith("w:") and hk_ < wagon_hk(it):
            self.log(f"{self.item_name(it)} kræver en traktor på mindst {wagon_hk(it)} hk – "
                     f"{vname(tr['k'])} har {VEHICLES[tr['k']].get('hk', 0)} hk.", pid, "err")
            return
        where = self.item_where(p, it)
        if where and where[0] == "shed":
            for i in where[2]:
                p["park"][where[1]][i] = None
        elif where and where[0] == "ground":
            del p["gear_pos"][it]
        tr["hitch"] = it
        m["tool"], m["job"] = None, None
        if it.startswith("w:"):
            w = it[2:].split("#")[0]
            m["wagon"] = w if WAGONS[w]["cargo"] == "grain" else None
            wl = p.get("wload", {}).pop(it, None)
            ws_ = p.get("wshape", {}).pop(it, None)
            if wl and m["wagon"]:
                m["cargo"] = {"src": "pile", "load": wl, "s": ws_}
        else:
            m["wagon"] = None
        ld_ = sum(m["cargo"]["load"].values()) if m.get("cargo") else 0
        amt_ = f"{int(round(wagon_slots_used(m['cargo']['load'], m['cargo'].get('s'))))} baller" \
            if m.get("cargo") and set(m["cargo"]["load"]) <= set(BALE_GOODS) \
            else f"{int(ld_)} enheder"
        self.log(f"{self.item_name(it)} er koblet på." + (" Sænk den med L." if it.startswith("e:") else
                 f" Den har {amt_} på – kør helt hen til lageret derhjemme, så læsses den af."
                 if m.get("cargo") else ""), pid, "good")

    def front_point(self, tr, reach=0.8):
        m = tr.get("man") or {}
        hdg = m.get("hdg")
        if hdg is None:
            cx, cy = VDIRS[tr["d"] % 8]
            hdg = math.atan2((cx + cy) * HALF_H, (cx - cy) * HALF_W)
        return self.rear_point(tr["x"], tr["y"], hdg, -reach)

    def ground_wagon(self, p, pt, r=1.3):
        """En vogn, der står på jorden ved punktet (til at læsse baller på med frontlæsseren)."""
        best = None
        for it, pos in p.get("gear_pos", {}).items():
            if it.startswith("w:") and WAGONS.get(it[2:].split("#")[0], {}).get("cargo") == "grain":
                d = math.hypot(pos[0] - pt[0], pos[1] - pt[1])
                if d <= r and (best is None or (not bale_wagon(it), d) < best[0]):
                    best = ((not bale_wagon(it), d), it)
        return best[1] if best else None

    def loader_cap(self, tr, g="halm", shape=None):
        """Hvor meget læsseren bærer: 2 baller oven på hinanden – med balleklo 2 stakke ved siden af hinanden."""
        big = 2 if VEHICLES.get(tr["k"], {}).get("style") == "gummiged_stor" else 1    # den store skovl: dobbelt
        return 2 * big * bale_unit(g, shape) * (2 if "ballegreb" in tr.get("upg", ()) else 1)

    @staticmethod
    def bale_shape(p):
        """Hvilke halmballer gården presser: den valgte presser (ellers den senest købte) – rundballer som standard."""
        presses = [k for k in p.get("equip", []) if EQUIPMENT.get(k, {}).get("tool") == "bale"]
        pref = p.get("bshape_pref")
        if pref and any(EQUIPMENT[k].get("shape") == pref for k in presses):
            return pref
        return EQUIPMENT[presses[-1]].get("shape", "rund") if presses else "rund"

    @staticmethod
    def spot_shape(p, g, k):
        return p.get("bshape", {}).get(k, "rund") if g == "halm" else "rund"

    def wagon_room(self, kind, load, wshape, g, shape):
        """Hvor meget af varen g (i form shape) der er plads til på vognen. På ballevognen tælles pladser."""
        if bale_wagon(kind):
            free = wagon_slots(kind) - wagon_slots_used(load, wshape or shape)
            return max(0.0, free) * bale_unit(g, shape)
        return WAGONS[kind.split("#")[0].replace("w:", "")]["cap"] - sum(load.values())

    def hitched_wagon(self, p, pt, skip=None, r=1.0):
        """En vogn (tip- eller ballevogn), der sidder på en anden traktor, som holder stille ved punktet."""
        best = None
        for t in self.tractors:
            if t is skip or t["o"] != p["id"] or t["s"] != "manual":
                continue
            m = t["man"]
            if not m.get("wagon") or WAGONS[m["wagon"]]["cargo"] != "grain" or abs(m["v"]) > 0.2:
                continue
            c = m.get("cargo")
            if c and (c["src"] != "pile" or not set(c["load"]) <= set(BALE_GOODS)):
                continue                       # vognen har korn eller solgte varer på – ikke baller oveni
            wx, wy = self.rear_point(t["x"], t["y"], m["hdg"], 1.05 if bale_wagon(m["wagon"]) else 0.85)
            d = math.hypot(wx - pt[0], wy - pt[1])
            if d <= r and (best is None or (not bale_wagon(m["wagon"]), d) < best[0]):
                best = ((not bale_wagon(m["wagon"]), d), t)
        return best[1] if best else None

    def loader_target(self, p, pt, tr=None, r=1.3):
        """Hvor læsserens baller kan læsses af ved punktet: ('ground', vogn) eller ('hitch', traktor) – eller None."""
        wg = self.ground_wagon(p, pt, r)
        if wg:
            return ("ground", wg)
        t = self.hitched_wagon(p, pt, tr, r * 0.8)
        return ("hitch", t) if t else None

    def bales_at(self, p, pt, r=0.95):
        """(dk, vare, nøgle) for de nærmeste baller ved punktet – eller None."""
        best = None
        for dk, g in (("bales", "halm"), ("wraps", "wrap")):
            for k, v in p.get(dk, {}).items():
                if v < 0.5:
                    continue
                kx, ky = map(int, k.split(","))
                d = math.hypot(kx - pt[0], ky - pt[1])
                if d <= r and (best is None or d < best[0]):
                    best = (d, dk, g, k)
        return best[1:] if best else None

    def act_loader(self, pid, vid, drv=None):
        """Frontlæsseren: sænk (sæt ballerne fra dig) og hæv (løft baller op)."""
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        p, m = self.players[pid], tr["man"]
        builtin = bool(VEHICLES.get(tr["k"], {}).get("loader"))
        if not builtin and vkind(tr["k"]) != "tractor":
            self.log("Den maskine kan ikke løfte baller – det kan en traktor med frontlæsser, en gaffeltruck "
                     "eller en minilæsser.", pid, "err")
            return
        if not builtin and "frontlaesser" not in tr.get("upg", ()):
            self.log("Traktoren har ingen frontlæsser – køb den under Opgrader og få den monteret i værkstedet.",
                     pid, "err")
            return
        if not loader_on(tr):
            self.log("Sneploven sidder foran – afmontér den (højreklik › Opgrader), før du bruger frontlæsseren.",
                     pid, "err")
            return
        if abs(m["v"]) > 0.3:
            self.log("Hold stille, mens du hæver eller sænker frontlæsseren.", pid, "info")
            return
        fp = self.front_point(tr)
        fl = m.get("fl")
        if not fl and VEHICLES.get(tr["k"], {}).get("style") in MUCK_STYLES and self._muck(tr, p):
            return                                        # gummiged/minilæsser ved stalddøren: muge ud
        if m.get("ld", "up") == "up":
            m["ld"] = "down"
            if fl:
                self._loader_drop(tr, p, fp)
            return
        m["ld"] = "up"
        if fl:
            return
        hit = self.bales_at(p, fp)
        if not hit:
            self._lift_from_yard(tr, p, fp)
            return
        dk, g, k = hit
        sh = self.spot_shape(p, g, k)
        a = min(p[dk][k], self.loader_cap(tr, g, sh))
        p[dk][k] -= a
        if p[dk][k] < 0.5:
            del p[dk][k]
            p.get("bshape", {}).pop(k, None)
        kx, ky = map(int, k.split(","))
        self.touch(kx, ky)
        m["fl"] = {"g": g, "n": a, "s": sh}
        m.pop("full_warn", None)
        n_b = max(1, round(a / bale_unit(g, sh)))
        self.log(f"Du løftede {n_b} {bale_name(g, sh, n_b)} op. "
                 "Kør helt frem til ballevognen (eller tipvognen), så læsses de af af sig selv – eller sænk (E) "
                 "ved ballepladsen.", pid, "info")

    def _lift_from_yard(self, tr, p, fp):
        """Løft baller fra lageret ved ballepladsen (eller gården) – fx for at køre en balle ud i folden."""
        m = tr["man"]
        near = self._near({"x": fp[0], "y": fp[1]}, self.bale_spot(tr["o"]), UNLOAD_RANGE) or \
            self._near({"x": fp[0], "y": fp[1]}, self._drop_spot(tr["o"]), UNLOAD_RANGE)
        if not near:
            return
        inv = p["inv"]
        sh = p.get("yshape") or "rund"
        g = "halm" if inv.get("halm", 0) >= bale_unit("halm", sh) else \
            "wrap" if inv.get("wrap", 0) >= bale_unit("wrap", "rund") else None
        if g is None:
            self.log("Der er ingen baller på lageret.", tr["o"], "info")
            return
        if g == "wrap":
            sh = "rund"
        a = min(inv[g], self.loader_cap(tr, g, sh))
        inv[g] -= a
        m["fl"] = {"g": g, "n": a, "s": sh}
        m.pop("full_warn", None)
        n_b = max(1, round(a / bale_unit(g, sh)))
        self.log(f"Du tog {n_b} {bale_name(g, sh, n_b)} fra lageret. Kør ud i folden og sænk (E) ved "
                 "foderhækken – så yder dyrene mere en tid.", tr["o"], "info")

    def _loader_drop(self, tr, p, fp):
        m = tr["man"]
        fl = m["fl"]
        g, n = fl["g"], fl["n"]
        sh = fl.get("s") or "rund"
        what = "wrapballerne" if g == "wrap" else BALE_SHAPES[sh]["flertal"] if sh != "rund" else "halmballerne"
        tg = self.loader_target(p, fp, tr)
        if tg:
            ws_store = p.setdefault("wshape", {})
            if tg[0] == "ground":
                wg = tg[1]
                wl = p.setdefault("wload", {}).setdefault(wg, {})
                name = self.item_name(wg)
                wsh = ws_store.get(wg) if wl.get("halm", 0) >= 0.5 else None
            else:
                ot = tg[1]
                wg = ot.get("hitch") or ("w:" + ot["man"]["wagon"])
                c_ = ot["man"].get("cargo") or {"src": "pile", "load": {}}
                ot["man"]["cargo"] = c_
                wl = c_["load"]
                name = WAGONS[ot["man"]["wagon"]]["navn"]
                wsh = c_.get("s") if wl.get("halm", 0) >= 0.5 else None
            if g == "halm" and wsh and wsh != sh:                # ikke to slags halmballer på samme vogn
                if m.get("full_warn") != ("mix", wg):
                    m["full_warn"] = ("mix", wg)
                    self.log(f"Der er allerede {BALE_SHAPES[wsh]['flertal']} på {name.lower()} – læs "
                             f"{BALE_SHAPES[sh]['flertal']} på en anden vogn, eller kør dem hjem i læsseren.",
                             tr["o"], "err")
                m["ld"] = "up"
                return False
            kind_ = wg[2:].split("#")[0] if wg.startswith("w:") else wg
            room = self.wagon_room(kind_, wl, wsh, g, sh)
            if room < 0.5:
                if m.get("full_warn") != wg:                 # kun én besked pr. vogn
                    m["full_warn"] = wg
                    self.log(f"{name} er fuld – kobl den på (K) og kør den hjem til ballepladsen.", tr["o"], "err")
                m["ld"] = "up"
                return False
            a = min(n, room)
            wl[g] = wl.get(g, 0.0) + a
            n -= a
            if g == "halm":
                if tg[0] == "ground":
                    ws_store[wg] = sh
                else:
                    c_["s"] = sh
            hsh = sh if g == "halm" else (wsh or "rund")
            if bale_wagon(kind_):
                used = wagon_slots_used(wl, hsh)
                nb_, full_ = int(round(used)), wagon_slots(kind_)
                done = used >= wagon_slots(kind_) - 0.5
            else:
                tot = sum(wl.values())
                nb_, full_ = int(round(tot / bale_unit(g, sh))), int(WAGONS[kind_]["cap"] // bale_unit(g, sh))
                done = tot >= WAGONS[kind_]["cap"] - 0.5
            unit_ = "pakker" if g == "halm" and sh == "lille" and not wl.get("wrap") else "baller"
            self.log(f"Du læssede {what} på {name.lower()} – {nb_} af {full_} {unit_}." +
                     (" Vognen er fuld – kobl den på (K) og kør den hjem til ballepladsen." if done else ""),
                     tr["o"], "good")
            if tg[0] == "hitch":
                ot["man"]["cargo"] = c_
        elif self._fold_tile(p, fp) is not None:
            n = self._fold_bale(tr, p, self._fold_tile(p, fp), g, n, sh)
        elif self._near({"x": fp[0], "y": fp[1]}, self.bale_spot(tr["o"]), UNLOAD_RANGE) or \
                self._near({"x": fp[0], "y": fp[1]}, self._drop_spot(tr["o"]), UNLOAD_RANGE):
            got = self._unload_grain(p, {g: n})
            p["hauled"] = p.get("hauled", 0) + got
            if g == "halm":
                p["yshape"] = sh
            n = 0
            self.log(f"Du satte {what} af på gården ({int(got)} enheder).", tr["o"], "good")
        else:
            gx, gy = int(round(fp[0])), int(round(fp[1]))
            if not self.inb(gx, gy) or self._blocked(gx, gy):
                gx, gy = int(round(tr["x"])), int(round(tr["y"]))
            dk = BALE_GOODS[g]
            key = f"{gx},{gy}"
            p.setdefault(dk, {})[key] = p[dk].get(key, 0.0) + n
            if g == "halm":
                p.setdefault("bshape", {})[key] = sh
            self.touch(gx, gy)
            n = 0
            self.log(f"Du satte {what} ned her.", tr["o"], "info")
        m["fl"] = {"g": g, "n": n, "s": sh} if n >= 0.5 else None
        return True

    def _fold_tile(self, p, fp):
        """Foldfeltet foran læsseren (en fold ved en af dine stalde) – ellers None."""
        gx, gy = int(round(fp[0])), int(round(fp[1]))
        if not self.inb(gx, gy) or self.tiles[gy][gx].t != "pasture" or self.tiles[gy][gx].o != p["id"]:
            return None
        return (gx, gy) if (gx, gy) in set(self.pasture(p["id"])) else None

    def _fold_bale(self, tr, p, cell, g, n, sh):
        """Sæt én balle i foderhækken i folden: dyrene yder lidt mere i FOLD_BALE_DAYS dage. Returnerer resten."""
        u = bale_unit(g, sh)
        key = f"{cell[0]},{cell[1]}"
        fb = p.setdefault("fbales", {})
        old = fb.get(key)
        if old and old["d"] > FOLD_BALE_DAYS * 0.6:
            self.log("Der står allerede en frisk balle i hækken her – sæt den næste et andet sted i folden, "
                     "eller vent til den er ædt halvt op.", tr["o"], "info")
            tr["man"]["ld"] = "up"
            return n
        a = min(n, u)
        fb[key] = {"g": g, "s": sh, "d": float(FOLD_BALE_DAYS), "f": a if g == "wrap" else 0.0, "f0": a}
        self.touch(*cell)
        units = sum(p.get(k, 0) * f for k, f in GRAZERS.items())
        what = "wrapballe" if g == "wrap" else "halmballe"
        if units <= 0:
            self.log(f"Du satte en {what} i folden – men der går ingen dyr i den endnu.", tr["o"], "info")
        else:
            cov = min(1.0, self.fold_cover(p) / units)
            self.log(f"Du satte en {what} i folden. Dyrene i folden yder {int(round(FOLD_BALE_BONUS * cov * 100))}% "
                     f"mere i {FOLD_BALE_DAYS} dage" + ("" if cov >= 0.999 else
                                                        f" – flere baller giver op til {int(FOLD_BALE_BONUS * 100)}% "
                                                        "til hele flokken") + ".", tr["o"], "good")
        return n - a

    def fold_cover(self, p):
        """Hvor mange foldfelter de friske baller i folden rækker til."""
        return sum(FOLD_BALE_COVER for b in p.get("fbales", {}).values() if b["d"] > 0)

    def fold_bonus(self, p):
        """Ekstra ydelse for dyrene i folden fra ballerne i foderhækkene (0 … FOLD_BALE_BONUS)."""
        units = sum(p.get(k, 0) * f for k, f in GRAZERS.items())
        return FOLD_BALE_BONUS * min(1.0, self.fold_cover(p) / units) if units > 0 else 0.0

    def hitch_tool(self, tr):
        """Hvilket arbejde det påkoblede redskab kan (plow, sow …) – eller None."""
        it = tr.get("hitch") or ""
        t_ = GEAR_IMP.get(it[2:]) if it.startswith("e:") else None
        return {"gylle": "fertilize", "gylle_s": "fertilize", "potato": "harvest",
                "harrow": "plow"}.get(t_, t_)                         # gyllevogn gøder, optager høster, harve harver

    @staticmethod
    def hitch_vis(tr):
        """Hvordan det påkoblede redskab ser ud (gyllevognen tegnes som gyllevogn, ikke som spreder)."""
        it = tr.get("hitch") or ""
        return GEAR_IMP.get(it[2:]) if it.startswith("e:") else None

    def shed_load(self, pid):
        """{shed: antal køretøjer} for spillerens maskinhuse."""
        load = {sp: 0 for sp, _ in self.sheds(pid)}
        for tr in self.tractors:
            if tr["o"] == pid and tuple(tr["hs"]) in load:
                load[tuple(tr["hs"])] += 1
        return load

    def upkeep(self, p):
        """Faste udgifter, der trækkes den 1. i hver måned."""
        return sum(v for _, _, v in self.upkeep_lines(p))

    def upkeep_lines(self, p, plan=False):
        """De faste udgifter pr. måned, post for post: [(gruppe, tekst, kr)] – summen er upkeep().
        plan=True: driftslederens markplan (kr pr. felt) kommer med, selv om den trækkes for sig."""
        s = self.stats(p["id"])
        out = [("Gården", "Gården (forsikring, el og vand)", FARM_UPKEEP),
               ("Gården", f"Ejendomsskat ({s['tiles']} felter à {LAND_TAX} kr)", s["tiles"] * LAND_TAX)]
        adds = {}
        for a in p.get("addons", []):
            adds[a] = adds.get(a, 0) + 1
        for a, n in adds.items():
            if ADDONS[a]["upkeep"]:
                out.append(("Gården", ADDONS[a]["navn"] + (f" ×{n}" if n > 1 else ""), ADDONS[a]["upkeep"] * n))
        hut_n = sum(1 for h in p.get("huts", []) if h[2] == "state")
        if hut_n:
            out.append(("Gården", "Jagthytte i statsskoven (jagtleje)" + (f" ×{hut_n}" if hut_n > 1 else ""),
                        (BUILDINGS["jagthytte"]["upkeep"] + HUT_LEASE) * hut_n))
        stables = {a[0] for a in ANIMALS.values()}
        for b, n in sorted(s["b"].items(), key=lambda kv: -BUILDINGS.get(kv[0], {}).get("upkeep", 0) * kv[1]):
            if b in BUILDINGS and BUILDINGS[b]["upkeep"]:
                grp = "Dyr" if BUILDINGS[b]["group"] in stables else "Bygninger"
                out.append((grp, BUILDINGS[b]["navn"] + (f" ×{n}" if n > 1 else ""), BUILDINGS[b]["upkeep"] * n))
        for k_, d_ in PETS.items():
            if (p.get("pets") or {}).get(k_):
                out.append(("Dyr", d_["navn"] + " (foder og dyrlæge)", d_["upkeep"]))
        nr = len(p.get("robots") or {})
        if nr:
            out.append(("Dyr", "Malkerobot (service)" + (f" ×{nr}" if nr > 1 else ""), ROBOT_UPKEEP * nr))
        vs = {}
        for _, k in self.vehicles_of(p["id"]):
            vs[k] = vs.get(k, 0) + 1
        for k, n in sorted(vs.items(), key=lambda kv: -VEHICLES[kv[0]]["upkeep"] * kv[1]):
            if VEHICLES[k]["upkeep"]:
                out.append(("Maskiner", vname(k) + (f" ×{n}" if n > 1 else ""), VEHICLES[k]["upkeep"] * n))
        for w, n in p.get("wagons", {}).items():
            if n and WAGONS[w]["upkeep"]:
                out.append(("Maskiner", WAGONS[w]["navn"] + (f" ×{n}" if n > 1 else ""), WAGONS[w]["upkeep"] * n))
        if p.get("manager"):
            out.append(("Løn", "Driftsleder", MANAGER_WAGE))
        nh = self.n_helpers(p["id"]) if self.manual_mode() and not p.get("ai") else 0
        if nh:
            out.append(("Løn", f"Medhjælper ×{nh}" if nh > 1 else "Medhjælper", HELPER_WAGE * nh))
        if plan and p.get("manager") and p.get("fplan"):
            fl = dict(self.fields_of(p["id"]))
            nf = sum(len(fl.get(k, [])) for k, v in p["fplan"].items() if v.get("auto"))
            if nf:
                out.append(("Løn", f"Driftslederens markplan ({nf} felter à {PLAN_FEE} kr)", PLAN_FEE * nf))
        for a, n in adds.items():
            if ADDONS[a].get("income", 0):
                out.append(("Indtægter", ADDONS[a]["navn"] + (f" ×{n}" if n > 1 else ""), -ADDONS[a]["income"] * n))
        return out

    def animal_month(self, p):
        """Hvad hver dyreart anslået giver og koster pr. måned: {art: dict(n, ind, foder, stald, netto)}.
        Foderet regnes til markedspris, også når det kommer fra egne marker (så kunne det være solgt)."""
        def price(g):
            mk = self.market.get(g)
            return ((mk["p"] if mk else GOODS[g]["base"]) + GOODS[g]["base"]) / 2
        grazing = 2 <= self.month() <= 9
        ff = self.feed_factor(p["id"]) * (1.0 - FODERHAL_SAVE if self.has_foderhal(p) else 1.0)
        bcount = self.stats(p["id"])["b"]
        out = {}
        for k, a in ANIMALS.items():
            n = p.get(k, 0)
            if not n:
                continue
            ind = a[6] * n * DAYS_PER_MONTH * price(a[5]) * self.sale_bonus(a[5], p) if a[5] else 0.0
            if k == "horses":
                ind += HORSE_PENSION * n * DAYS_PER_MONTH
            if k in GRAZERS:
                need = n * a[4] * (0.5 if grazing else 1.0) * ff * DAYS_PER_MONTH
                feed = need * (0.7 * price("graes") + 0.3 * price("byg"))
            else:
                feed = self.feed_need(p, k) * DAYS_PER_MONTH * price("byg")
            stald = sum(BUILDINGS[b]["upkeep"] * c for b, c in bcount.items()
                        if b in BUILDINGS and BUILDINGS[b]["group"] == a[0])
            if k == "cows":
                stald += ROBOT_UPKEEP * len(p.get("robots") or {})
            out[k] = dict(n=n, ind=ind, foder=feed, stald=stald, netto=ind - feed - stald)
        return out

    def land_price(self):
        return int(round(LAND_PRICE * egn_of(self).get("land", 1.0) / 10.0) * 10)

    def budget(self, p, months=12):
        """Pengestrøm de næste måneder: [{'m': måned, 'inc': {kategori: kr}, 'out': {kategori: kr}}].
        Høsten regnes solgt i den måned, den bliver moden, til en pris midt mellem dagens og normalprisen."""
        ck = (self.day, months, round(p["money"]), p.get("loan"), len(p.get("jobs", [])))
        bc = self.__dict__.setdefault("_budget_cache", {})
        if bc.get(p["id"], (None,))[0] == ck:
            return bc[p["id"]][1]
        m0 = self.day // DAYS_PER_MONTH
        rows = [{"m": (m0 + i) % 12, "yr": (m0 + i) // 12 + 1, "inc": {}, "out": {}} for i in range(months)]
        ripe_memo = {}

        def add(i, side, cat, v):
            if 0 <= i < months and v:
                d = rows[i][side]
                d[cat] = d.get(cat, 0.0) + v

        def price(g):
            mk = self.market.get(g)
            return ((mk["p"] if mk else GOODS[g]["base"]) + GOODS[g]["base"]) / 2
        own_c = any(vkind(k) == "combine" for _, k in self.vehicles_of(p["id"]))
        baler = self.owns_tool(p, "bale")
        # afgrøderne på markerne
        for y, row in enumerate(self.tiles):
            for x, t in enumerate(row):
                if t.o != p["id"] or not t.crop or t.dead or (x, y) in self.ctiles:
                    continue
                c = CROPS[t.crop]
                g = crop_good(t.crop)
                if not g or c.get("green") or (c.get("perennial") and g == "graes"):
                    continue
                mk_ = (t.crop, round(t.g, 2))
                if mk_ not in ripe_memo:
                    ripe_memo[mk_] = ripe_day(t.crop, self.day, t.g)
                rd = ripe_memo[mk_]
                if rd is None:
                    continue
                i = rd // DAYS_PER_MONTH - m0
                amt = c["udbytte"] * max(10.0, t.h) / 100.0 * self.yield_factor(t)
                val = amt * (price(g) - (SALE_PICKUP if g in STORE_GOODS else 0))
                if t.crop in STRAW_CROPS and baler:
                    val += amt * STRAW_RATIO * GOODS.get("halm", {}).get("base", 0)
                add(i, "inc", "Høst", val)
                add(i, "out", "Høstarbejde", 3 + (0 if own_c else self.hire_harvest()))
        # dyrene: produktion hver måned, foder købes, når lageret slipper op
        feed = sum(p["inv"].get(g, 0) for g in FEED_ORDER) + sum(p["inv"].get(g, 0) for g in SILAGE_GOODS)
        need = sum(p.get(k, 0) * a[4] for k, a in ANIMALS.items()) * DAYS_PER_MONTH
        prod = sum(a[6] * p.get(k, 0) * DAYS_PER_MONTH * price(a[5]) * self.sale_bonus(a[5], p)
                   for k, a in ANIMALS.items() if a[5])
        prod += HORSE_PENSION * p.get("horses", 0) * DAYS_PER_MONTH
        for i in range(months):
            add(i, "inc", "Dyr", prod)
            use = min(feed, need)
            feed -= use
            add(i, "out", "Foder", (need - use) * price("majs"))
        # vind og sol (gennemsnitligt vejr)
        bp = self.stats(p["id"])["bpos"]
        nm, ns = len(bp.get("vindmoelle", [])), len(bp.get("solcelleanlaeg", []))
        wind = egn_of(self)["wind"]
        for i, r in enumerate(rows):
            add(i, "inc", "Strøm", nm * MILL_BASE * 0.9 * WIND_SEASON[r["m"]] * wind * DAYS_PER_MONTH +
                ns * SOLAR_BASE * 0.55 * SUN_SEASON[r["m"]] * DAYS_PER_MONTH)
        # faste udgifter og lån
        up = self.upkeep(p)
        if p.get("manager") and p.get("fplan"):
            fl = dict(self.fields_of(p["id"]))
            up += PLAN_FEE * sum(len(fl.get(k, [])) for k, v in p["fplan"].items() if v.get("auto"))
        loans = [dict(l_) for l_ in self.loans(p)]
        for i in range(months):
            add(i, "out", "Faste udgifter", up)
            for l_ in loans:
                if l_["amt"] < 1:
                    continue
                r_ = l_["amt"] * LOAN_RATE / 12
                a_ = min(l_["amt"], l_["rate"])
                l_["amt"] -= a_
                add(i, "out", "Lån (rente og afdrag)", r_ + a_)
        bc[p["id"]] = (ck, rows)
        return rows

    def worth(self, p):
        w = p["money"] - p["loan"]
        w += sum(v * self.market[g]["p"] for g, v in p["inv"].items())
        w += sum(p[k] * a[1] * 0.6 for k, a in ANIMALS.items())
        w += self.stats(p["id"])["tiles"] * self.land_price() * 0.8
        w += sum(VEHICLES[k]["price"] * 0.6 for _, k in self.vehicles_of(p["id"]))
        w += sum(WAGONS[k]["price"] * 0.6 * n for k, n in p.get("wagons", {}).items())
        w += sum(v * self.market[g]["p"] for g, v in p.get("pile", {}).items())
        w += sum(v * self.market["halm"]["p"] for v in p.get("bales", {}).values())
        w += sum(v * self.market["wrap"]["p"] for v in p.get("wraps", {}).values())
        w += sum(f["value"] if f["dir"] == "out" else f["qty"] * self.market[f["good"]]["p"] for f in p.get("freight", []))
        return w

    # ── verden ───────────────────────────────────────────────────────────────
    @classmethod
    def new_world(cls, seed=None, world=None):
        w = world_cfg({**(world or {}), "seed": seed if seed is not None else 0})
        set_world(w)
        s = cls()
        s.world = w
        eg = EGNE.get(w["egn"], EGNE["blandet"])
        rng = random.Random(seed)
        s.rng = random.Random(None if seed is None else seed + 1)
        T = s.tiles
        area = (s.W * s.H) / (72 * 72)                  # større kort: flere søer og skove
        if w.get("lake_town"):                          # byen ved søen: en stor sø lige ved siden af byen
            x0, y0, x1, y1 = TOWN
            lx, ly = rng.choice(((x0 - 4, (y0 + y1) // 2), (x1 + 4, (y0 + y1) // 2), ((x0 + x1) // 2, y0 - 4),
                                 ((x0 + x1) // 2, y1 + 4)))
            s._blob(rng, clamp(lx, 0, s.W - 1), clamp(ly, 0, s.H - 1), 70, "water")
        for _ in range(int(eg["lakes"] * area)):
            s._blob(rng, rng.randrange(s.W), rng.randrange(s.H), rng.randint(*eg["lake"]), "water")
        for _ in range(int(eg["forest"] * area)):
            s._blob(rng, rng.randrange(s.W), rng.randrange(s.H), rng.randint(8, 40), "forest")
        for _ in range(int(eg["trees"] * area)):
            t = T[rng.randrange(s.H)][rng.randrange(s.W)]
            if t.t == "grass":
                t.t = "forest"
        for x in range(s.W):
            T[ROAD_Y][x].t = "road"
        for y in range(s.H):
            T[y][ROAD_X].t = "road"
        x0, y0, x1, y1 = TOWN
        for y in range(y0 - 1, y1 + 2):
            for x in range(x0 - 1, x1 + 2):
                t = T[y][x]
                if t.t != "road":
                    t.t = "town" if in_town(x, y) else "grass"
        # ringvej rundt om byen
        for x in range(x0, x1 + 1):
            T[y0][x].t = T[y1][x].t = "road"
        for y in range(y0, y1 + 1):
            T[y][x0].t = T[y][x1].t = "road"
        T[KIRKE[1]][KIRKE[0]].b = "kirke"
        T[KVAEGTORV[1]][KVAEGTORV[0]].t = "town"
        T[KVAEGTORV[1]][KVAEGTORV[0]].b = "kvaegtorv"
        T[GROVVARE[1]][GROVVARE[0]].t = "town"
        T[GROVVARE[1]][GROVVARE[0]].b = "grovvare"
        T[SAVVAERK[1]][SAVVAERK[0]].t = "town"
        T[SAVVAERK[1]][SAVVAERK[0]].b = "savvaerk"
        T[JAGTBUTIK[1]][JAGTBUTIK[0]].t = "town"
        T[JAGTBUTIK[1]][JAGTBUTIK[0]].b = "jagtbutik"
        for k, p in PROJECTS.items():
            x, y = p["pos"]
            T[y][x].t = "town"
            T[y][x].b = "site:" + k
        for y in range(y0 + 1, y1):
            for x in range(x0 + 1, x1):
                t = T[y][x]
                if t.t != "town" or t.b:
                    continue
                r = rng.random()
                if r < 0.45:
                    t.b = "hus%d" % rng.randrange(3)
                elif r < 0.58:
                    t.b = "trae"
        area = s.find_pull_area()                         # traktortræk-pladsen lige uden for byen
        if area:
            w["pull_area"] = area
            s.apply_pull_area(area)
        b = s.find_buyer_spots()                          # slagteriet og mejeriet
        if b:
            w["buyers"] = b
            s.apply_buyers(b)
        for row in T:
            for t in row:
                t.kc = rng.uniform(*eg["kc"])         # jorden er ikke lige kalket overalt
                t.n = rng.uniform(*eg["n"])           # egnens jord: sandet i vest, fed på øerne
        s.town["pop"] = s.town_pop()
        if w.get("terrain") == "bakket":                # bakket terræn (valgfrit)
            s.hm = hm_gen(s, random.Random((seed or 0) * 13 + 5), TERRAIN_AMP.get(w["egn"], 4))
        return s

    # ── terræn ────────────────────────────────────────────────────────────────
    def hcorners(self, x, y):
        """Hjørnehøjderne for feltet (x, y): top, højre, bund, venstre (som på skærmen)."""
        hm = self.hm
        if not hm:
            return (0, 0, 0, 0)
        return hm[y][x], hm[y][x + 1], hm[y + 1][x + 1], hm[y + 1][x]

    def hpos(self, fx, fy):
        """Højden (i trin) i et punkt i hjørnekoordinater – feltet (x, y) har sin midte i (x+0.5, y+0.5)."""
        hm = self.hm
        if not hm:
            return 0.0
        ix, iy = int(clamp(math.floor(fx), 0, self.W - 1)), int(clamp(math.floor(fy), 0, self.H - 1))
        u, v = clamp(fx - ix, 0.0, 1.0), clamp(fy - iy, 0.0, 1.0)
        h0, h1, h2, h3 = hm[iy][ix], hm[iy][ix + 1], hm[iy + 1][ix + 1], hm[iy + 1][ix]
        if u >= v:                                   # samme to trekanter som jorden tegnes med
            return h0 + (h1 - h0) * u + (h2 - h1) * v
        return h0 + (h3 - h0) * v + (h2 - h3) * u

    def htile(self, x, y):
        """Feltets højde i midten (trin)."""
        return self.hpos(x + 0.5, y + 0.5) if self.hm else 0.0

    def slope_of(self, x, y):
        """0 = fladt, 1 = skråt felt."""
        if not self.hm:
            return 0
        c = self.hcorners(x, y)
        return int(max(c) != min(c))

    def level(self, x0, y0, w, h, target=None):
        """Jævn jorden under en bygning (eller en ny sø). Nabobygninger og søer bestemmer højden, hvis de rører."""
        hm = self.hm
        if not hm:
            return
        if target is None:
            pins = []
            for y in range(y0 - 1, y0 + h + 1):
                for x in range(x0 - 1, x0 + w + 1):
                    if not self.inb(x, y) or (x0 <= x < x0 + w and y0 <= y < y0 + h):
                        continue
                    t = self.tiles[y][x]
                    if t.b or t.t == "water":
                        c = self.hcorners(x, y)
                        if max(c) == min(c):
                            pins.append((0 if t.b else 1, c[0]))
            if pins:
                best = min(p_[0] for p_ in pins)
                vals = [p_[1] for p_ in pins if p_[0] == best]
                target = max(set(vals), key=vals.count)
        changed = hm_level(hm, x0, y0, w, h, target)
        if not changed:
            return
        self.hm_ver += 1
        self.hm_t = time.time()
        self._topo = None
        for cx, cy in changed:
            for x, y in ((cx, cy), (cx - 1, cy), (cx, cy - 1), (cx - 1, cy - 1)):
                if self.inb(x, y):
                    self.touch(x, y)

    def topo_moist(self, x, y):
        """Bakketoppe tørrer hurtigere ud, og vandet samler sig i lavningerne (fugt pr. dag)."""
        if not self.hm:
            return 0.0
        c = getattr(self, "_topo", None)
        if c is None:
            W, H, R = self.W, self.H, 4
            hc = [[self.htile(x_, y_) for x_ in range(W)] for y_ in range(H)]
            c = [[0.0] * W for _ in range(H)]
            for y_ in range(H):
                for x_ in range(W):
                    tot = n = 0
                    for yy in range(max(0, y_ - R), min(H, y_ + R + 1), 2):
                        for xx in range(max(0, x_ - R), min(W, x_ + R + 1), 2):
                            tot += hc[yy][xx]
                            n += 1
                    c[y_][x_] = clamp((tot / n - hc[y_][x_]) * 1.4, -3.0, 3.0)
            self._topo = c
        return c[y][x]

    def slope_speed(self, x0, y0, x1, y1):
        """Fartfaktor fra (x0, y0) mod (x1, y1): op ad bakke går det langsommere, ned ad lidt hurtigere."""
        if not self.hm:
            return 1.0
        d = math.hypot(x1 - x0, y1 - y0)
        if d < 1e-6:
            return 1.0
        g = (self.hpos(x1 + 0.5, y1 + 0.5) - self.hpos(x0 + 0.5, y0 + 0.5)) / d     # trin pr. felt
        return clamp(1.0 - 0.3 * g, 0.65, 1.12) if g > 0 else clamp(1.0 - 0.1 * g, 1.0, 1.12)

    def find_pull_area(self):
        """Find en plads til traktortræk-banen langs en af hovedvejene lige uden for byen."""
        x0, y0, x1, y1 = TOWN
        T, L = self.tiles, PULL_LEN
        tries = []
        for gap in range(4, 16):
            for side in (-1, 1):                       # helst bag vejen: så står tribunen bagerst og banen ses
                tries.append({"axis": "x", "road": ROAD_Y, "side": side, "s": x1 + gap})
                tries.append({"axis": "x", "road": ROAD_Y, "side": side, "s": x0 - gap - L + 1, "rev": True})
                tries.append({"axis": "y", "road": ROAD_X, "side": side, "s": y1 + gap})
                tries.append({"axis": "y", "road": ROAD_X, "side": side, "s": y0 - gap - L + 1, "rev": True})
        for a in tries:
            c = pull_cells(a)
            cells = c["park"] + c["track"] + c["stand"]
            ok = True
            for x, y in cells:
                if not self.inb(x, y) or in_town(x, y, 3):
                    ok = False
                    break
                t = T[y][x]
                if t.t not in ("grass", "forest") or t.b or t.o >= 0 or t.crop or (x, y) in self.ctiles:
                    ok = False
                    break
            if ok:
                return a
        return None

    def find_buyer_spots(self):
        """Slagteriet og mejeriet: hver sit felt ved en hovedvej lige uden for byen (ikke på traktortræk-pladsen)."""
        x0, y0, x1, y1 = TOWN
        T = self.tiles
        pull = set(c for cs in pull_cells().values() for c in cs)
        cands = []
        for gap in range(3, 10):
            for side in (-1, 1):
                cands += [(x1 + gap, ROAD_Y + side), (x0 - gap, ROAD_Y + side),
                          (ROAD_X + side, y1 + gap), (ROAD_X + side, y0 - gap)]
        ok = []
        for x, y in cands:
            if not self.inb(x, y) or (x, y) in pull or in_town(x, y, 1):
                continue
            t = T[y][x]
            if t.t in ("grass", "forest") and not t.b and t.o < 0 and not t.crop and (x, y) not in self.ctiles:
                if all(abs(x - a) + abs(y - b) >= 4 for a, b in ok):
                    ok.append((x, y))
            if len(ok) >= 2:
                return {"slagteri": list(ok[0]), "mejeriet": list(ok[1])}
        return None

    def apply_buyers(self, b):
        set_buyers(b)
        for key, pos in (b or {}).items():
            t = self.tiles[pos[1]][pos[0]]
            t.t, t.b, t.lc = "town", key, None
            t.clear_crop()
            self.touch(*pos)

    def apply_pull_area(self, area):
        """Anlæg pladsen: grusparkering ved vejen, jordbane og en tribune med skilt."""
        set_pull_area(area)
        if not area:
            return
        c = pull_cells(area)
        for x, y in c["park"]:
            t = self.tiles[y][x]
            t.t, t.b, t.lc = "pullpark", None, None
            t.clear_crop()
        for x, y in c["track"]:
            t = self.tiles[y][x]
            t.t, t.b, t.lc = "bane", None, None
            t.clear_crop()
        for i, (x, y) in enumerate(c["stand"]):
            t = self.tiles[y][x]
            t.t, t.lc = "grass", None
            t.clear_crop()
            t.b = "pullsign" if i == 0 else "tribune" if 1 <= i <= PULL_LEN - 3 else None
        for x, y in c["park"] + c["track"] + c["stand"]:
            self.touch(x, y)

    def _blob(self, rng, x, y, n, kind):
        for _ in range(n * 4):
            if n <= 0:
                break
            t = self.tiles[y][x]
            if t.t == "grass" and not in_town(x, y, 2):
                t.t = kind
                n -= 1
            dx, dy = rng.choice(N4)
            x, y = clamp(x + dx, 0, self.W - 1), clamp(y + dy, 0, self.H - 1)

    def found_farm(self, pid, near=None):
        """Giver en spiller en tilfældig startgrund på 12 x 12 felter (near: så tæt på dette punkt som muligt)."""
        rng, T = self.rng, self.tiles
        spot = None
        for strict in (True, False):
            cands = []
            for _ in range(1500):
                px, py = rng.randint(1, self.W - PLOT - 1), rng.randint(1, self.H - PLOT - 1)
                if not (px + PLOT < TOWN[0] - 5 or px > TOWN[2] + 5 or py + PLOT < TOWN[1] - 5 or py > TOWN[3] + 5):
                    continue
                gap = 4 if strict else 0
                bad = water = 0
                for y in range(py - gap, py + PLOT + gap):
                    for x in range(px - gap, px + PLOT + gap):
                        if not self.inb(x, y):
                            continue
                        t = T[y][x]
                        inside = px <= x < px + PLOT and py <= y < py + PLOT
                        if t.o >= 0 or (inside and (t.t in PUBLIC_T or t.b)):
                            bad = 1
                        if inside and t.t == "water":
                            water += 1
                if bad or water > (25 if strict else 60):
                    continue
                if near is None:
                    spot = (px, py)
                    break
                dist = math.hypot(px + PLOT / 2 - near[0], py + PLOT / 2 - near[1])
                cands.append((dist, px, py))
                if dist < PLOT + 10:
                    break
            if cands:
                spot = min(cands)[1:]
            if spot:
                break
        if spot is None:
            return False
        px, py = spot
        for y in range(py, py + PLOT):
            for x in range(px, px + PLOT):
                T[y][x].o = pid
                self.touch(x, y)
        hx, hy = px + PLOT // 2 - 2, py + PLOT - 3
        T[hy][hx].t, T[hy][hx].b = "grass", "gaard"
        T[hy][hx].clear_crop()
        self._place(hx + 2, hy - 1, 2, 2, "maskinhus")
        # kun en kort grussti fra stuehuset til maskinhuset
        lane = [(hx + 1, hy)]
        for x, y in lane:
            t = T[y][x]
            if t.t in ("grass", "forest") and not t.b:
                t.t = "gravel"
        self.players[pid]["home"] = [hx, hy]
        self._spawn_vehicle(pid, START_TRACTOR)
        return True

    def _spawn_vehicle(self, pid, kind, shed=None):
        if shed is None:
            sh = self.sheds(pid)
            shed = sh[0][0] if sh else tuple(self._outside_spot(pid))
        tr = {"id": self.nid, "o": pid, "k": kind, "hs": list(shed), "out": False,
              "x": float(shed[0]), "y": float(shed[1]), "d": 0, "s": "parked", "tx": None,
              "ty": None, "w": 0.0, "j": None, "tool": None, "path": None}
        self.tractors.append(tr)
        self.nid += 1
        p = self.players.get(pid)
        if p and vkind(kind) != "car":
            self._sync_park(p, True)
            tr["x"], tr["y"], tr["s"] = float(tr["hs"][0]), float(tr["hs"][1]), "parked"
        return tr

    # ── spillere ─────────────────────────────────────────────────────────────
    def add_player(self, pid, name):
        if pid in self.players:
            self.players[pid]["connected"] = True
            self.players[pid]["name"] = name
            return
        self.players[pid] = dict(id=pid, name=name, money=float(self.start_money()), loan=0,
                                 inv={g: 0.0 for g in GOODS}, cows=0, pigs=0, chickens=0, sheep=0, horses=0,
                                 connected=True, hungry=False, jobs=[], home=[0, 0], equip=[],
                                 house=0, addons=[], manager=False,
                                 pile={}, pile_pos=None, wagons={k: 0 for k in WAGONS}, deliv=[], gylle=0.0,
                                 yr=self.new_book(self.start_money(), 0), hist=[], wh=[],
                                 inputs={"goedning": 0, "sproejte": 0, "kalk": 0}, forraad=0.0, old_yard=False)
        if self.mode.get("guide") == "on":
            self.players[pid]["guide"] = {"i": 0}
        if not self.found_farm(pid):
            self.log("Der var ikke plads til en ny gård på kortet.", pid, "err")
        else:
            if self.tractors:
                self._sync_park(self.players[pid], True)
            self._apply_scenario(self.players[pid])
        self._sandbox_topup()
        self._spawn_ai(self.players[pid]["home"])

    def _apply_scenario(self, p):
        """Scenariet bestemmer, hvordan gården ser ud ved starten (kun nye menneskelige spillere)."""
        sc = self.mode.get("scen", "normal")
        if sc not in SCENARIOS or sc == "normal" or self.sandbox():
            return
        p["scen"] = sc
        pid = p["id"]
        rng = self.rng
        own = [(x, y) for y, row in enumerate(self.tiles) for x, t in enumerate(row) if t.o == pid]
        if sc == "nedslidt":
            for x, y in own:
                t = self.tiles[y][x]
                t.n = rng.uniform(22, 40)
                t.kc = rng.uniform(32, 46)
                if t.t in ("grass", "field", "stub"):
                    t.wd = rng.uniform(45, 75)
                self.touch(x, y)
            for tr in self.tractors:
                if tr["o"] == pid:
                    tr["wear"], tr["dirt"] = 72.0, 60
            p["money"] += 8000
        elif sc == "far":
            hx, hy = p["home"]
            for r in range(1, 4):                              # lidt mere jord rundt om grunden
                for x, y in list(own):
                    for dx, dy in N4:
                        q = (x + dx * r, y + dy * r)
                        if self.inb(*q) and self.tiles[q[1]][q[0]].o < 0 and self.tiles[q[1]][q[0]].t not in PUBLIC_T \
                                and not self.tiles[q[1]][q[0]].b and abs(q[0] - hx) < 11 and abs(q[1] - hy) < 11:
                            self.tiles[q[1]][q[0]].o = pid
                            self.touch(*q)
            cells = [(x, y) for y, row in enumerate(self.tiles) for x, t in enumerate(row) if t.o == pid]
            pos = self._ai_place(p, "kostald", cells)
            if pos:
                x, y = pos
                for yy in range(y - 2, y + 4):              # folden rundt om stalden
                    for xx in range(x - 2, x + 4):
                        if self.inb(xx, yy) and self.tiles[yy][xx].o == pid and not self.tiles[yy][xx].b and \
                                self.tiles[yy][xx].t in ("grass", "field", "stub"):
                            self.tiles[yy][xx].t = "pasture"
                            self.tiles[yy][xx].clear_crop()
                            self.touch(xx, yy)
                self.fver = getattr(self, "fver", 0) + 1
                self.ver += 1
                p["cows"] = min(10, self.animal_cap(p, "cows"))
            self._ai_place(p, "silo", cells)
            self._spawn_vehicle(pid, "fordal_7600")
            p["inv"]["hvede"] = 300.0
            p["inv"]["graes"] = 300.0
            p["money"] = max(p["money"], 15000.0)
            self.loans(p).append({"amt": float(FAR_LOAN), "orig": float(FAR_LOAN), "rate": FAR_LOAN / FAR_LOAN_MONTHS,
                                  "left": FAR_LOAN_MONTHS, "day": self.day})
            p["loan"] = p.get("loan", 0) + FAR_LOAN
            self.book(p, "drift", 0)
        elif sc == "oko":
            cells = own
            pos = self._ai_place(p, "hoensehus", cells)
            if pos:
                x, y = pos
                for yy in range(y - 2, y + 3):
                    for xx in range(x - 2, x + 4):
                        if self.inb(xx, yy) and self.tiles[yy][xx].o == pid and not self.tiles[yy][xx].b and \
                                self.tiles[yy][xx].t in ("grass", "field", "stub"):
                            self.tiles[yy][xx].t = "pasture"
                            self.tiles[yy][xx].clear_crop()
                            self.touch(xx, yy)
                self.fver = getattr(self, "fver", 0) + 1
                self.ver += 1
                p["chickens"] = 30
                p["money"] += BUILDINGS["hoensehus"]["cost"]       # hønsehuset følger med gården
                p.setdefault("eco", {})["chickens"] = True
            p["fert"] = "gylle"
        self.ver += 1
        self.log(f"Scenarie: {SCENARIOS[sc][0]}. {SCENARIOS[sc][1]}", pid, "big")

    def oko_farm(self, p):
        return bool(p) and p.get("scen") == "oko"

    # ── computernaboer ───────────────────────────────────────────────────────
    def ai_players(self):
        return [p for p in self.players.values() if p.get("ai")]

    def _spawn_ai(self, near):
        """Computernaboerne får hver sit hjørne af kortet – de hjørner, der ligger længst fra den første spiller."""
        want = min(AI_MAX, int(self.mode.get("ai", 0) or 0))
        m = PLOT // 2 + 3
        corners = [(m, m), (self.W - m, m), (m, self.H - m), (self.W - m, self.H - m)]
        corners.sort(key=lambda c: -math.hypot(c[0] - near[0], c[1] - near[1]))
        for i in range(want):
            if AI_BASE + i not in self.players:
                self.add_ai(i, corners[i % len(corners)])

    def add_ai(self, i, near=None):
        pid = AI_BASE + i
        pref = {"soehoejland": ("ko", "svin", "korn"), "lolland": ("korn", "svin", "korn"),
                "vestjylland": ("svin", "ko", "korn"), "marsken": ("ko", "korn", "ko")}
        style = pref.get((self.world or {}).get("egn"), tuple(AI_STYLES))[i % 3]     # egnen bestemmer driften
        self.players[pid] = dict(id=pid, name=AI_NAMES[i % len(AI_NAMES)], money=float(self.start_money()), loan=0,
                                 inv={g: 0.0 for g in GOODS}, cows=0, pigs=0, chickens=0, sheep=0, horses=0,
                                 connected=False, hungry=False, jobs=[], home=[0, 0], equip=[],
                                 house=0, addons=[], manager=False,
                                 pile={}, pile_pos=None, wagons={k: 0 for k in WAGONS}, deliv=[], gylle=0.0,
                                 yr=self.new_book(self.start_money(), 0), hist=[], wh=[],
                                 inputs={"goedning": 0, "sproejte": 0, "kalk": 0}, forraad=0.0, old_yard=False,
                                 ai={"style": style})
        if not self.found_farm(pid, near):
            del self.players[pid]
            return False
        self._sync_park(self.players[pid], True)
        self.log(f"{self.players[pid]['name']} driver en gård i den anden ende af egnen – mest {AI_STYLES[style]}.", None, "info")
        return True

    def _ai_cells(self, pid):
        return [(x, y) for y, row in enumerate(self.tiles) for x, t in enumerate(row) if t.o == pid]

    def _ai_days(self):
        for p in self.ai_players():
            try:
                self._ai_day(p)
            except Exception as e:                     # en computernabo må aldrig vælte spillet
                p["ai"]["err"] = repr(e)[:120]

    def _ai_job(self, p, tool, cells, crop=None):
        if any(j["tool"] == tool for j in p["jobs"]):
            return
        xs = [c[0] for c in cells]
        ys = [c[1] for c in cells]
        self._handle(p["id"], {"a": "tool", "tool": tool, "x0": min(xs), "y0": min(ys), "x1": max(xs), "y1": max(ys),
                               "crop": crop})

    def _ai_place(self, p, kind, cells):
        """Byg tæt på gården på et ledigt stykke (græs, stub eller tom mark)."""
        b = BUILDINGS[kind]
        w, hh = b["size"]
        hx, hy = p["home"]
        own = set(cells)
        n0 = len(self.stats(p["id"])["bpos"].get(kind, []))
        for r in range(1, 12):
            for y in range(hy - r, hy + r + 1):
                for x in range(hx - r, hx + r + 1):
                    if max(abs(x - hx), abs(y - hy)) != r:
                        continue
                    if not all((xx, yy) in own and not self.tiles[yy][xx].b and not self.tiles[yy][xx].crop
                               and self.tiles[yy][xx].t in ("grass", "field", "stub")
                               for yy in range(y, y + hh) for xx in range(x, x + w)):
                        continue
                    self._handle(p["id"], {"a": "tool", "tool": kind, "x0": x, "y0": y, "x1": x, "y1": y})
                    if len(self.stats(p["id"])["bpos"].get(kind, [])) > n0:
                        return (x, y)
        return None

    def _ai_buy_land(self, p, cells, n=5):
        xs = [c[0] for c in cells]
        ys = [c[1] for c in cells]
        x0, y0, x1, y1 = min(xs), min(ys), max(xs), max(ys)
        best = None
        for (a, b, c, d) in ((x0 - n, y0, x0 - 1, y1), (x1 + 1, y0, x1 + n, y1), (x0, y0 - n, x1, y0 - 1),
                             (x0, y1 + 1, x1, y1 + n)):
            free = sum(1 for y in range(b, d + 1) for x in range(a, c + 1) if self.inb(x, y) and
                       self.tiles[y][x].o < 0 and self.tiles[y][x].t == "grass" and not self.tiles[y][x].b
                       and not in_town(x, y))
            if best is None or free > best[0]:
                best = (free, (a, b, c, d))
        if best and best[0] > 12:
            a, b, c, d = best[1]
            self._handle(p["id"], {"a": "tool", "tool": "buyland", "x0": a, "y0": b, "x1": c, "y1": d})

    def _ai_day(self, p):
        """En computernabo passer sin gård: så, gød, sprøjt, høst, sælg – og udvid, når der er råd."""
        pid, st = p["id"], p["ai"]["style"]
        m, d, yr = self.month(), self.dom(), self.year()
        for t in self.tractors:                           # maskinerne kører selv – også i Styr selv-spil
            if t["o"] == pid and vkind(t["k"]) != "car" and not t.get("helper"):
                t["helper"] = True
        if p["money"] < 3000 and self.loan_room(p)[0] >= 5000:
            self.act_loan(pid, amt=10000)
        elif p["money"] > 40000 and p["loan"] > 0 and d == 15:
            self.act_loan(pid, -1)
        cells = self._ai_cells(pid)
        if not cells:
            return
        if d % 10 == pid % 10:
            self._ai_chores(p)
        info = self.stats(pid)
        crops = info["crops"]
        if sum(v[1] for v in crops.values()):
            self._ai_job(p, "harvest", cells)
        if sum(v[3] for v in crops.values()) >= 2:
            self._ai_job(p, "spray", cells)
        if d % 5 == (pid % 5):
            spring = {"korn": "hvede" if yr % 2 else "vaarbyg", "ko": "majs" if yr % 2 else "graes",
                      "svin": "majs"}.get(st, "hvede")
            autumn = "raps" if st == "korn" and yr % 2 == 0 else ("vinterbyg" if yr % 2 else "vinterhvede")
            crop = next((c for c in (autumn, spring) if m in CROPS[c]["months"]), None)
            if crop:
                T = self.tiles
                empty = [(x, y) for x, y in cells if T[y][x].t in ("field", "stub", "grass") and not T[y][x].crop
                         and not T[y][x].b]
                if len(empty) >= 4:
                    self._ai_job(p, "plow", cells)
                    if sum(1 for x, y in empty if T[y][x].t == "field" and T[y][x].n < 45) > 5:
                        self._ai_job(p, "fertilize", cells)
                    if any(T[y][x].t == "field" for x, y in empty):
                        self._ai_job(p, "sow", cells, crop)
        full = self.stored(p) > self.storage_cap(p) * 0.85
        good = any(self.market[g]["p"] >= GOODS[g]["base"] * 1.02 and p["inv"].get(g, 0) >= 20
                   for g in ("hvede", "byg", "majs", "raps", "kartofler"))
        if d % 3 == pid % 3 and (good or full):
            if self.sellall_plan(p):
                self.act_sellall(pid)
        if d % 7 == 0:
            for g in ("maelk", "aeg", "svin", "uld", "tommer", "halm"):
                q = int(p["inv"].get(g, 0))
                if q >= 20 and not (g == "halm" and st != "korn"):
                    self.act_sell(pid, g, q)
        if sum((p.get("wetg") or {}).values()) > 60 and not self.capacity(p, "korntoerreri") and d % 3 == 0:
            if self.sellall_plan(p):
                self.act_sellall(pid)                        # vådt korn uden tørreri: sælg det, før det mugner
        if self.owns_tool(p, "water") and self.weather == "Tørke" and d % 4 == pid % 4:
            T = self.tiles
            dry = [c for c in cells if T[c[1]][c[0]].crop and not T[c[1]][c[0]].dead and T[c[1]][c[0]].m < 25]
            if len(dry) > 8:
                self._ai_job(p, "water", cells)
        if self.owns_tool(p, "snow") and self.snow >= 0.3 and d % 3 == 0:
            xs, ys = [c[0] for c in cells], [c[1] for c in cells]
            if not any(j["tool"] == "snow" for j in p["jobs"]):
                self.act_job(pid, "snow", min(xs) - 6, min(ys) - 6, max(xs) + 6, max(ys) + 6, None, quiet=True)
        if d != 10 + pid:
            return
        eg = egn_of(self)
        free_ = p["money"] - p["loan"]
        bp = info["bpos"]
        if free_ > 45000 and not bp.get("vindmoelle") and (eg["wind"] >= 1.1 or yr >= 3):
            self._ai_place(p, "vindmoelle", cells)
        elif free_ > 35000 and not bp.get("solcelleanlaeg") and yr >= 3:
            self._ai_place(p, "solcelleanlaeg", cells)
        if free_ > 22000 and not self.owns_tool(p, "water") and eg["drought"] >= 1.0 and yr >= 2:
            self._handle(pid, {"a": "equip", "key": "vandingsanlaeg"})
        if free_ > 25000 and st == "korn" and not bp.get("korntoerreri") and yr >= 2:
            self._ai_place(p, "korntoerreri", cells)
        if free_ > 30000 and not self.owns_tool(p, "snow") and m in (9, 10):
            self._handle(pid, {"a": "equip", "key": "sneplov"})
        free = lambda: p["money"] - p["loan"]            # egne penge – lånte penge investeres ikke
        if free() > 30000:
            for k in ("plov", "saamaskine", "goedningsspreder", "sproejte"):
                if k not in p.get("equip", []) and free() > 18000:
                    self._handle(pid, {"a": "equip", "key": k})
        if yr >= 2 and free() > 60000 and not any(vkind(k) == "combine" for _, k in self.vehicles_of(pid)):
            self._handle(pid, {"a": "vehicle", "kind": "claus_dominator"})
        if self.storage_cap(p) - self.stored(p) < 150 and p["money"] > 9000:
            self._ai_place(p, "silo", cells)
        if st == "ko":
            if not info["bpos"].get("kostald") and p["money"] > 12000:
                pos = self._ai_place(p, "kostald", cells)
                if pos:
                    x, y = pos
                    self._handle(pid, {"a": "tool", "tool": "pasture", "x0": x - 2, "y0": y - 2, "x1": x + 3,
                                       "y1": y + 3})
            elif info["bpos"].get("kostald") and p["cows"] < self.animal_cap(p, "cows") and p["money"] > 6000:
                self.act_animal(pid, "cows", min(5, self.animal_cap(p, "cows") - p["cows"]))
            feed = sum(p["inv"].get(g, 0) for g in ("hvede", "byg", "majs", "graes", "majsens"))
            need = 30 * p["cows"] * 0.4
            if feed < need and p["money"] > 3000:
                self.act_buy(pid, "majs", int(need - feed) + 50)
        elif st == "svin":
            feed = sum(p["inv"].get(g, 0) for g in ("hvede", "byg", "majs"))
            need = 30 * (p["pigs"] * 0.25 + p["chickens"] * 0.05)
            if feed < need and p["money"] > 3000:
                self.act_buy(pid, "majs", int(need - feed) + 50)
            if not info["bpos"].get("svinestald") and p["money"] > 10000:
                self._ai_place(p, "svinestald", cells)
            elif info["bpos"].get("svinestald") and p["pigs"] < self.animal_cap(p, "pigs") and p["money"] > 5000:
                self.act_animal(pid, "pigs", min(10, self.animal_cap(p, "pigs") - p["pigs"]))
            if yr >= 2 and not info["bpos"].get("hoensehus") and p["money"] > 8000:
                self._ai_place(p, "hoensehus", cells)
            elif info["bpos"].get("hoensehus") and p["chickens"] < self.animal_cap(p, "chickens") and \
                    p["money"] > 4000:
                self.act_animal(pid, "chickens", 20)
        self._ai_new_things(p, cells, info, free)
        if free() > 50000 and m in (2, 3, 8, 9, 10):
            self._ai_buy_land(p, cells)

    def _ai_new_things(self, p, cells, info, free):
        """Computernaboerne bruger også de nyere ting: gylletank, fodersilo, malkerobot, økologi og
        rundbuehal (én gang om måneden, når der er råd)."""
        pid, st = p["id"], p["ai"]["style"]
        bp = info["bpos"]
        animals = sum(p.get(k, 0) for k in ANIMALS)
        if animals and p.get("gylle", 0) >= self.gylle_cap(p) * 0.9 and free() > 12000:
            self._ai_place(p, "gylletank", cells)
        if st == "svin" and p.get("pigs", 0) >= 10 and not bp.get("fodersilo") and free() > 15000:
            self._ai_place(p, "fodersilo", cells)
        if st == "ko" and p.get("cows", 0) >= 8 and free() > 40000:
            rb = p.get("robots") or {}
            for k_ in ROBOT_COST:
                for pos in bp.get(k_, []):
                    if f"{int(pos[0])},{int(pos[1])}" not in rb and free() > ROBOT_COST[k_] + 15000:
                        self.act_robot(pid, int(pos[0]), int(pos[1]))
                        break
        if st == "svin":                                  # grise og høns på græs (økologi) med en fold ved stalden
            for kind, grp in (("pigs", "svinestald"), ("chickens", "hoensehus")):
                if not p.get(kind, 0) or not bp.get(grp):
                    continue
                if self.fold_tiles_for(p, kind) == 0 and free() > 8000:
                    x, y = bp[grp][0]
                    self._handle(pid, {"a": "tool", "tool": "pasture", "x0": x - 2, "y0": y - 2, "x1": x + 3,
                                       "y1": y + 3})
                if self.fold_tiles_for(p, kind) and not (p.get("eco") or {}).get(kind):
                    p.setdefault("eco", {})[kind] = True
        if st == "korn" and self.bales_total(p) + p["inv"].get("halm", 0) + p["inv"].get("wrap", 0) > \
                self.storage_cap(p, "halm") * 0.9 and free() > 15000:
            self._ai_place(p, "rundbuehal_halm", cells)
        # de nyeste ting: ét nyt byggeri ad gangen, når der er god råd
        yr = self.year()
        if st == "ko":
            p["majsens"] = True                           # kvæggårdene høster majsen som ensilage
            if p.get("cows", 0) >= 10 and not bp.get("kalvehytter") and free() > 8000:
                self._ai_place(p, "kalvehytter", cells)
                return
            if p.get("cows", 0) >= 15 and not bp.get("rundbuehal_foder") and free() > 15000:
                self._ai_place(p, "rundbuehal_foder", cells)
                return
        if st == "korn":
            if not bp.get("bistade") and free() > 6000:
                self._ai_place(p, "bistade", cells)
                return
            if not bp.get("halmfyr") and p["inv"].get("halm", 0) > 600 and free() > 25000:
                self._ai_place(p, "halmfyr", cells)
                return
            if not bp.get("kornmoelle") and p["inv"].get("hvede", 0) > 800 and free() > 40000:
                self._ai_place(p, "kornmoelle", cells)
                return
        if yr >= 2 and free() > 10000:
            for k_ in ("kat", "hund"):
                if not (p.get("pets") or {}).get(k_):
                    self.act_pet(pid, k_)
        if yr >= 2 and not bp.get("lade") and free() > 50000:
            self._ai_place(p, "lade", cells)
            return
        if yr >= 3 and not bp.get("drivhus") and free() > 60000:
            self._ai_place(p, "drivhus", cells)
            return
        if yr >= 3 and not bp.get("andedam") and free() > 80000:
            self._ai_place(p, "andedam", cells)

    def has_loader(self, pid):
        """Har gården noget, der kan løfte en balle? (traktor med frontlæsser eller en læsser/gummiged)"""
        return any(t["o"] == pid and not t.get("hire") and
                   ((vkind(t["k"]) == "tractor" and loader_on(t)) or VEHICLES.get(t["k"], {}).get("loader"))
                   for t in self.tractors)

    def _auto_fold_bales(self, p):
        """Automatik › Baller i foderhækken: med en læsser på gården sætter karlen nye baller i foldene."""
        if p.get("ai") or not self.auto_on(p, "foderhaek") or not self.has_loader(p["id"]):
            return
        n = self._fill_fold_bales(p)
        if n:
            p["money"] -= n * FOLD_AUTO_FEE
            self.book(p, "drift", -n * FOLD_AUTO_FEE)
            if self.day - p.get("fb_log", -99) >= 15:
                p["fb_log"] = self.day
                self.log(f"Karlen har sat {n} {'balle' if n == 1 else 'baller'} i foderhækken i folden "
                         f"(+{int(FOLD_BALE_BONUS * 100)}% mælk og afkast).", p["id"], "info")

    def _fill_fold_bales(self, p):
        """Sæt baller i foderhækkene, så der er nok til græsserne (halm først, ellers wrap). Returnerer antal."""
        units = sum(p.get(k, 0) * f for k, f in GRAZERS.items())
        if units <= 0:
            return 0
        fb = p.setdefault("fbales", {})
        past = [c for c in self.pasture(p["id"]) if f"{c[0]},{c[1]}" not in fb]
        need = int(math.ceil(units / FOLD_BALE_COVER)) - sum(1 for b in fb.values() if b["d"] > 0)
        n = 0
        for _ in range(max(0, need)):
            g = "halm" if p["inv"].get("halm", 0) >= BALE_U else "wrap" if p["inv"].get("wrap", 0) >= BALE_U else None
            if not g or not past:
                break
            c = past.pop(self.rng.randrange(len(past)))
            p["inv"][g] -= BALE_U
            fb[f"{c[0]},{c[1]}"] = {"g": g, "s": "rund", "d": float(FOLD_BALE_DAYS), "f": BALE_U if g == "wrap" else 0.0,
                                    "f0": BALE_U}
            self.touch(*c)
            n += 1
        return n

    def _ai_chores(self, p):
        """Computernaboerne har ingen, der selv kører – de små opgaver klares 'af karlen': stalden mugges ud,
        og der sættes baller i foderhækkene, når der er halm på lageret."""
        bp = self.stats(p["id"])["bpos"]
        mk = p.setdefault("muck", {})
        for k_, poss in bp.items():
            if k_ in BUILDINGS and BUILDINGS[k_]["group"] in STALL_GROUPS:
                for pos in poss:
                    key = f"{int(pos[0])},{int(pos[1])}"
                    if mk.get(key, 0) <= 0 and any(p.get(a_, 0) for a_, v in ANIMALS.items()
                                                    if v[0] == BUILDINGS[k_]["group"]):
                        mk[key] = float(MUCK_DAYS)
        self._fill_fold_bales(p)

    # ── handlinger fra spillere ──────────────────────────────────────────────
    def handle(self, pid, msg):
        self._handle(pid, msg)
        self._sandbox_topup()
        if any(q.get("guide") for q in self.players.values()):
            self._guide_check()

    def _handle(self, pid, msg):
        a = msg.get("a")
        self.ver += 1
        try:
            if a == "tool":
                self.act_tool(pid, msg["tool"], int(msg["x0"]), int(msg["y0"]), int(msg["x1"]), int(msg["y1"]),
                              msg.get("crop"), msg.get("rot", False))
            elif a == "buyinput":
                self.act_buyinput(pid, msg.get("key"), int(msg.get("qty", 0)))
            elif a == "preorder":
                self.act_preorder(pid, int(msg.get("amount", 0)))
            elif a == "biosilage":
                p_ = self.players.get(pid)
                if p_:
                    p_["bio_silage"] = bool(msg.get("on"))
            elif a == "pet":
                self.act_pet(pid, msg.get("k"), bool(msg.get("on", True)))
            elif a in ("millon", "hfauto", "calfkeep"):
                p_ = self.players.get(pid)
                if p_:
                    p_[{"millon": "mill_on", "hfauto": "hf_auto", "calfkeep": "calf_keep"}[a]] = bool(msg.get("on"))
            elif a == "demolish":
                self.act_demolish(pid, int(msg.get("x", -1)), int(msg.get("y", -1)))
            elif a == "farmname":
                p_ = self.players.get(pid)
                if p_:
                    nm_ = str(msg.get("name", "")).strip()[:28]
                    p_["farm_name"] = nm_ or None
                    self.log(f"Gården hedder nu {nm_}." if nm_ else "Gårdskiltet viser nu dit navn.", pid, "good")
            elif a == "majsens":
                p_ = self.players.get(pid)
                if p_:
                    p_["majsens"] = bool(msg.get("on"))
                    self.log("Majsen høstes nu som " + ("majsensilage: hele planten hakkes og køres i plansiloen "
                             f"({MAJSENS_YIELD:g} gange så meget foder som kernemajs)." if p_["majsens"] else
                             "kernemajs til kornlageret."), pid, "info")
            elif a == "milkauto":
                p_ = self.players.get(pid)
                if p_:
                    p_["milk_auto"] = bool(msg.get("on"))
                    self.log("Mejeriet henter mælken hver 10. dag." if p_["milk_auto"] else
                             "Mejeriet henter ikke længere mælken – sælg den selv under Marked.", pid, "info")
            elif a == "sellall":
                self.act_sellall(pid)
            elif a == "sell":
                self.act_sell(pid, msg["good"], int(msg["qty"]))
            elif a == "buy":
                self.act_buy(pid, msg["good"], int(msg["qty"]))
            elif a == "animal":
                self.act_animal(pid, msg["kind"], int(msg["delta"]))
            elif a == "drive":
                self.act_drive(pid, int(msg["id"]), bool(msg.get("on")), msg.get("_drv"), msg.get("_nm"))
            elif a == "steer":
                self.act_steer(pid, int(msg["id"]), int(msg.get("thr", 0)), int(msg.get("turn", 0)), msg.get("_drv"))
            elif a == "pos":
                self.act_pos(pid, int(msg["id"]), float(msg["x"]), float(msg["y"]), float(msg["hdg"]),
                             float(msg["v"]), msg.get("_drv"))
            elif a == "implement":
                self.act_implement(pid, int(msg["id"]), msg.get("tool"), msg.get("crop"), msg.get("_drv"))
            elif a == "helper":
                self.act_helper(pid, int(msg["id"]), bool(msg.get("on")))
            elif a == "trip":
                self.act_trip(pid, int(msg["id"]), msg.get("kind"), msg.get("_drv"))
            elif a == "shoot":
                self.act_shoot(pid, int(msg["id"]), msg.get("_drv"))
            elif a == "gear":
                self.act_gear(pid, msg.get("key"))
            elif a == "wash":
                self.act_wash(pid, int(msg["id"]))
            elif a == "parts":
                self.act_parts(pid, int(msg.get("n", 1)))
            elif a == "fieldname":
                self.act_fieldname(pid, int(msg["x"]), int(msg["y"]), str(msg.get("name", "")))
            elif a == "show":
                self.act_show(pid, msg)
            elif a == "diesel":
                self.act_diesel(pid, int(msg.get("liters", 0)))
            elif a == "upgrade":
                self.act_upgrade(pid, int(msg["id"]), msg.get("key"))
            elif a == "front":
                self.act_front(pid, int(msg["id"]))
            elif a == "gps":
                self.act_gps(pid, int(msg["id"]), msg.get("_drv"))
            elif a == "loader":
                self.act_loader(pid, int(msg["id"]), msg.get("_drv"))
            elif a == "fplan":
                self.act_fplan(pid, int(msg["x"]), int(msg["y"]), msg.get("crop", "keep"), msg.get("auto"),
                               bool(msg.get("run")))
            elif a == "townoffer":
                self.act_townoffer(pid, bool(msg.get("yes")))
            elif a == "guide":
                self.act_guide(pid, msg.get("op"))
            elif a == "fuelhelp":
                self.act_fuelhelp(pid, int(msg["id"]), msg.get("_drv"))
            elif a == "pull":
                self.act_pull(pid, msg, msg.get("_drv"))
            elif a == "parkhere":
                self.act_park_here(pid, int(msg["id"]), msg.get("_drv"))
            elif a == "park":
                self.act_park(pid, msg.get("item"), msg.get("shed"), int(msg.get("slot", 0)))
            elif a == "hitch":
                self.act_hitch(pid, int(msg["id"]), msg.get("item"), msg.get("_drv"))
            elif a == "opt" and msg.get("key") == "pace":
                v = msg.get("val")
                v = float(v) if isinstance(v, (int, float)) and float(v) in YEAR_PACE else None
                if v is not None and self.pace() != v:
                    self.opts["pace"] = v
                    self.log(f"{self.pname(pid)} satte årets længde til {YEAR_PACE[v].lower()}.", None, "info")
            elif a == "opt":
                key, val = msg.get("key"), bool(msg.get("val"))
                if key in WEATHER_OPTS and self.opts.get(key) != val:
                    self.opts[key] = val
                    if key == "drought" and not val:
                        self.drought = 0
                    if key == "weeds" and not val:
                        for row in self.tiles:
                            for t in row:
                                t.wd = 0.0
                        self.ver += 1
                    if key == "pests" and not val:
                        for row in self.tiles:
                            for t in row:
                                t.pest = 0
                        self.ver += 1
                    self.log(f"{self.pname(pid)} slog '{WEATHER_OPTS[key].lower()}' {'til' if val else 'fra'}.",
                             None, "info")
            elif a == "house":
                self.act_house(pid)
            elif a == "addon":
                self.act_addon(pid, msg.get("key"))
            elif a == "manager":
                self.act_manager(pid, bool(msg.get("on")))
            elif a == "contract":
                self.act_contract(pid, int(msg["id"]), msg.get("op"))
            elif a == "robot":
                self.act_robot(pid, int(msg.get("x", -1)), int(msg.get("y", -1)))
            elif a == "eco":
                k_ = msg.get("k")
                if k_ in ECO_KINDS and pid in self.players:
                    self.players[pid].setdefault("eco", {})[k_] = bool(msg.get("on"))
                    q_ = self.players[pid]
                    nm_ = ANIMALS[k_][3]
                    if msg.get("on"):
                        sh_ = self.eco_share(q_, k_)
                        self.log(f"Økologiske {nm_} på græs: {int(ECO_BONUS * 100)}% økotillæg for den del, der går ude "
                                 f"(de giver {int(ECO_YIELD * 100)}% mindre og æder {int(ECO_FEED * 100)}% mere)"
                                 + (" – alle har plads i folden." if sh_ >= 0.999 else
                                    f" – folden har plads til {int(sh_ * 100)}% af dem. Lav en større fold ved stalden."),
                                 pid, "good" if sh_ >= 0.999 else "warn")
                    else:
                        self.log(f"{nm_.capitalize()} går inde igen (konventionel produktion).", pid, "info")
            elif a == "gate":
                self.act_gate(pid, int(msg.get("x", -1)), int(msg.get("y", -1)), int(msg.get("d", 0)),
                              msg.get("op", "toggle"), msg.get("id"))
            elif a == "hoop":
                self.act_hoop(pid, int(msg.get("x", -1)), int(msg.get("y", -1)), msg.get("to"))
            elif a == "torder":
                self.act_torder(pid, int(msg.get("qty", 0)), msg.get("id"))
            elif a == "hutsell":
                self.act_hut_sell(pid, int(msg.get("x", -1)), int(msg.get("y", -1)))
            elif a == "rent":
                self.act_rent(pid, msg.get("op"), msg)
            elif a == "ms":
                self.act_ms(pid, msg.get("op"), msg)
            elif a == "deal":
                self.act_deal(pid, int(msg.get("id", -1)), msg.get("op"))
            elif a == "wagon":
                self.act_wagon(pid, msg.get("key"), int(msg.get("delta", 1)))
            elif a == "auto":                         # automatik til/fra (Menu › Automatik)
                p_ = self.players.get(pid)
                k_ = msg.get("key")
                if p_ and k_ in AUTO_OPTS:
                    if k_ == "maelk":
                        p_["milk_auto"] = bool(msg.get("on"))
                    else:
                        p_.setdefault("auto", {})[k_] = bool(msg.get("on"))
            elif a == "plowmode":                     # pløj med plov eller stubharve
                p_ = self.players.get(pid)
                if p_ and msg.get("v") in ("plov", "harve"):
                    p_["plowmode"] = msg["v"]
            elif a == "fert":                         # gød med gylle eller kunstgødning
                p_ = self.players.get(pid)
                if p_ and msg.get("v") in ("gylle", "kunst"):
                    p_["fert"] = msg["v"]
            elif a == "bshape":                       # vælg hvilken presser, halmen presses med
                pl = self.players[pid]
                if msg.get("key") in BALE_SHAPES and any(EQUIPMENT[k_].get("shape") == msg["key"]
                                                         for k_ in pl.get("equip", []) if k_ in EQUIPMENT):
                    pl["bshape_pref"] = msg["key"]
                    self.log(f"Halmen presses nu til {BALE_SHAPES[msg['key']]['flertal']}.", pid, "good")
            elif a == "equip":
                self.act_equip(pid, msg.get("key"))
            elif a == "service":
                self.act_service(pid, int(msg["id"]))
            elif a == "vehicle":
                self.act_vehicle(pid, msg.get("kind"), msg.get("shed"), msg.get("sell"))
            elif a == "cancel":
                self.act_cancel(pid, int(msg["job"]))
            elif a == "send":
                self.act_send(pid, int(msg["to"]), msg["what"], int(msg["qty"]))
            elif a == "contribute":
                self.act_contribute(pid, msg["project"], msg["what"], int(msg["qty"]))
            elif a == "loan":
                self.act_loan(pid, int(msg.get("delta", 0)), msg.get("amt"), msg.get("payoff"))
            elif a == "speed":
                self.act_speed(pid, int(clamp(int(msg["v"]), 0, 5)), msg.get("_drv"), msg.get("_nm"))
            elif a == "vote":
                self.act_vote(int(msg["id"]), bool(msg["yes"]), msg.get("_drv"))
            elif a == "chat":
                text = str(msg.get("text", ""))[:160].strip()
                if text:
                    self.log(f"{msg.get('_nm') or self.pname(pid)}: {text}", None, "chat")
        except (KeyError, ValueError, TypeError):
            pass

    def _cost(self, tool, t, crop):
        if tool == "plow":
            if t.b is None and (t.t in ("grass", "stub") or (t.t == "field" and (
                    (t.crop and (t.dead or t.crop == "graes" or CROPS[t.crop].get("green") or
                                 CROPS[t.crop].get("orchard"))) or
                    (not t.crop and t.wd >= 20)))):
                return 20 if t.t == "grass" else 5
        elif tool == "fertilize":
            if t.t in ("field", "stub") and t.b is None and not t.dead and t.n < 95:
                return WORK_LABOR
        elif tool == "lime":
            if t.t in ("field", "stub") and t.b is None and t.kc < 90:
                return WORK_LABOR
        elif tool == "fell":
            if t.t == "forest" and t.b is None and t.lc != "ung":
                return 20
        elif tool == "water":
            if t.t == "field" and t.b is None and t.m < 80:
                return WATER_COST
        elif tool == "snow":
            if t.t in ROADS and self.snow >= 0.3:
                return 0
        elif tool == "sow":
            if t.t == "field" and not t.crop and t.b is None:
                return CROPS[crop]["seed"]
        elif tool == "harvest":
            if t.crop and (t.dead or (t.g >= 1 and not CROPS[t.crop].get("green"))):
                return 3
        elif tool == "spray":
            if t.crop and not t.dead:
                return WORK_LABOR
        elif tool == "tree":
            if t.t == "grass" and t.b is None:
                return 30
        elif tool == "pasture":
            if t.t in ("grass", "field", "stub", "plaene") and not t.crop and t.b is None:
                return PASTURE_COST
        elif tool == "bulldoze":
            if (t.b or "").startswith("ext:"):
                return 100                                    # bygninger rives ned med "Riv ned" (spørger først)
            if t.b:
                return None
            if t.t == "forest":
                return 80
            if t.t in ("field", "stub", "gravel", "asphalt", "ditch", "pasture", "fliser", "plaene"):
                return 10
            if t.t == "water":
                return FILL_COST                      # der skal køres jord til
        elif tool == "lake":
            if t.t in ("grass", "field", "stub", "plaene") and not t.crop and not t.b:
                return LAKE_COST
        elif tool == "fliser":
            if (t.t in ("grass", "field", "stub", "gravel", "plaene") or (t.t == "fliser" and t.lc == "brosten")) \
                    and not t.crop and not t.b:
                return FLISER_COST
        elif tool == "brosten":                          # brosten: en flisebelagt plads, der ser gammel og pæn ud
            if (t.t in ("grass", "field", "stub", "gravel", "plaene") or (t.t == "fliser" and t.lc != "brosten")) \
                    and not t.crop and not t.b:
                return BROSTEN_COST
        elif tool == "plaene":
            if t.t in ("grass", "field", "stub") and not t.crop and not t.b:
                return PLAENE_COST
        elif tool == "mow":
            if t.t == "plaene" and t.g >= 0.1 and not t.b:
                return 0
        elif tool in ("gravel", "ditch"):
            if t.t in ("grass", "field", "stub", "plaene") and not t.crop and not t.b:
                return LINE_TOOLS[tool]
            if tool == "gravel" and t.t == "ditch" and not t.b:
                return LINE_TOOLS["gravel"] + CULVERT_COST      # rør i grøften – vandet løber videre under vejen
        elif tool == "asphalt":
            if t.t in ("grass", "field", "stub", "plaene") and not t.crop and not t.b:
                return LINE_TOOLS["asphalt"]
            if t.t == "ditch" and not t.b:
                return LINE_TOOLS["asphalt"] + CULVERT_COST
            if t.t == "gravel":
                return LINE_TOOLS["asphalt"] - LINE_TOOLS["gravel"]
        elif tool in BUILDINGS:
            if t.b is None and t.t in ("grass", "field", "stub", "plaene") and not t.crop:
                return BUILDINGS[tool]["cost"]
        return None

    def _apply(self, tool, t, crop, p, job=None, pos=None, gylle=False, by=None):
        if tool == "plow" and gylle and t.t == "stub" and not t.crop:     # stubharven: hurtig, men lidt ukrudt bliver
            t.t = "field"
            t.wd = min(t.wd, 8.0)
            return
        if tool == "plow":
            if t.crop == "graes" or (t.crop and CROPS[t.crop].get("green") and not t.dead):
                t.n = min(100.0, t.n + (15 if t.crop == "graes" else 12 + 10 * min(1.0, t.g)))  # grøngødning
                t.lc = t.crop
            t.t = "field"
            t.clear_crop()
            t.wd = min(t.wd, 3.0)
        elif tool == "sow":
            t.clear_crop()
            t.crop = crop
            if pos is not None and p is not None:
                self._field_note(p, pos, "sow", t, crop, 0)
            t.wd *= 0.5                                   # såbedet harves – halvdelen af ukrudtet forsvinder
        elif tool == "harvest":
            contract = pos is not None and tuple(pos) in self.ctiles
            crop = t.crop
            if not t.dead:
                amt = CROPS[crop]["udbytte"] * t.h / 100.0 * self.yield_factor(t)
                if crop == "kartofler" and by is not None and vkind(by) == "combine":
                    amt *= POTATO_COMBINE_LOSS                # mejetærskeren knuser en del af kartoflerne
                good = crop_good(crop)
                if crop in BEE_CROPS and crop != "graes" and pos is not None and self.bee_near(*pos):
                    amt *= 1 + BEE_POLLEN                     # bierne har bestøvet blomsterne
                if good == "majs" and p is not None and p.get("majsens"):   # hele planten hakkes til ensilage
                    good, amt = "majsens", amt * MAJSENS_YIELD
                if not contract and good == "graes" and self.owns_tool(p, "wrap") and pos is not None:
                    key = f"{pos[0]},{pos[1]}"                # wrapballer bliver liggende på marken
                    wr = p.setdefault("wraps", {})
                    wr[key] = wr.get(key, 0.0) + amt
                    self._rec(p, "harv", "wrap", amt)
                    if job is not None:
                        job["yield"]["wrap"] = job["yield"].get("wrap", 0) + amt
                    good = None
                if not contract and good:             # på en kontraktmark tilhører høsten naboen
                    p["pile"][good] = p["pile"].get(good, 0.0) + amt      # høsten ligger i marken til den hentes
                    self._rec(p, "harv", good, amt)
                    if good in WET_GOODS and (self.weather in ("Regn", "Storm") or t.m >= 85):
                        wg = p.setdefault("wetg", {})
                        wg[good] = wg.get(good, 0.0) + amt
                        if p.get("wet_hint", -99) < self.day - 5:
                            p["wet_hint"] = self.day
                            self.log("Kornet høstes vådt (regnvejr eller meget våd mark). " +
                                     ("Korntørreriet tørrer det." if self.capacity(p, "korntoerreri") else
                                      "Vådt korn mugner lidt hver dag og sælges med fugtfradrag – sælg det hurtigt, "
                                      "eller byg et korntørreri."), p["id"], "warn")
                    if crop in STRAW_CROPS and self.owns_tool(p, "bale") and pos is not None:
                        key = f"{pos[0]},{pos[1]}"            # halmballerne bliver liggende på marken
                        bl = p.setdefault("bales", {})
                        bl[key] = bl.get(key, 0.0) + amt * STRAW_RATIO
                        p.setdefault("bshape", {})[key] = self.bale_shape(p)
                        self._rec(p, "harv", "halm", amt * STRAW_RATIO)
                        if job is not None:
                            job["yield"]["halm"] = job["yield"].get("halm", 0) + amt * STRAW_RATIO
                    if pos is not None:
                        p["pile_pos"] = list(pos)
                    if job is not None:
                        job["yield"][good] = job["yield"].get(good, 0) + amt
                t.n = max(0.0, t.n - DRAIN[crop] - (SAME_CROP_DRAIN if t.lc == crop and crop != "graes" else 0))
            if not contract and pos is not None and p is not None:
                rev = 0.0
                if not t.dead:
                    rev = self.val("majsens" if crop_good(crop) == "majs" and p.get("majsens") else crop_good(crop),
                                   amt)
                    if crop in STRAW_CROPS and self.owns_tool(p, "bale"):
                        rev += self.val("halm", amt * STRAW_RATIO)
                k_ = f"{int(pos[0])},{int(pos[1])}"
                cost = p.setdefault("tacc", {}).pop(k_, 0.0)
                self._acc(p, "cacc", crop, cost=cost, rev=rev, n=1, amt=0 if t.dead else amt)
                self._field_note(p, pos, "harvest", t, crop, 0 if t.dead else amt, cost, rev)
            t.lc = crop
            if CROPS[crop].get("perennial") and not t.dead:
                t.g, t.rip = 0.0, 0                   # græsset gror op igen til næste slæt
            else:
                t.clear_crop()
                t.t = "stub"                          # stubmark – skal pløjes, før der kan sås igen
        elif tool == "spray":
            t.pest, t.imm, t.wd = 0, SPRAY_IMMUNE, 0.0
        elif tool == "fertilize":
            slange = gylle and p is not None and "gyllevogn_slange" in p.get("equip", [])
            t.n = min(100.0, t.n + FERTILIZER * (GYLLE_SLANGE if slange else 1.0))
            t.kc = max(0.0, t.kc - 2)                 # kunstgødning forsurer jorden lidt
        elif tool == "lime":
            t.kc = min(100.0, t.kc + LIME_GAIN)
        elif tool == "fell":
            t.t, t.lc, t.g = "grass", None, 0.0
            if p is not None:
                p["pile"]["tommer"] = p["pile"].get("tommer", 0.0) + TIMBER_TILE
                self._rec(p, "harv", "tommer", TIMBER_TILE)
                if pos is not None:
                    p["pile_pos"] = list(pos)
                if job is not None:
                    job["yield"]["tommer"] = job["yield"].get("tommer", 0) + TIMBER_TILE
        elif tool == "water":
            t.m = max(t.m, 92.0)                      # vandkanonen: marken er gennemvædet i en uges tid
        elif tool == "snow":
            if pos is not None and tuple(pos) not in self.plowed:
                self.plowed.add((int(pos[0]), int(pos[1])))
                if t.o < 0 and p is not None:         # offentlig vej: kommunen betaler
                    p["money"] += SNOW_PAY
                    self.book(p, "sne", SNOW_PAY)
                    if job is not None:
                        job["earn"] = job.get("earn", 0) + SNOW_PAY
        elif tool == "tree":
            t.t, t.lc, t.g = "forest", "ung", 0.0          # ung skov – kan fældes om et par år
        elif tool == "pasture":
            t.t = "pasture"
            t.clear_crop()
        elif tool in ("fliser", "brosten"):
            t.t = "fliser"
            t.clear_crop()
            t.lc = "brosten" if tool == "brosten" else None
        elif tool == "plaene":
            t.t = "plaene"
            t.clear_crop()
            t.g = 0.15
        elif tool == "mow":
            g0, t.g = t.g, 0.0
            if p is not None:
                p["mowed"] = p.get("mowed", 0) + 1
                n, avg = p.get("lawn") or (0, 0.0)
                if n:
                    p["lawn"] = (n, round(max(0.0, avg - g0 / n), 3))
        elif tool in LINE_TOOLS:
            t.t = tool
            t.clear_crop()
        elif tool == "bulldoze":
            if t.b:
                t.b, t.ba = None, None
            else:
                if t.t == "water":                    # opfyldt sø: mager jord, der skal gødes og kalkes
                    t.n, t.kc = FILL_SOIL
                    t.wd = 0.0
                t.t = "grass"
                t.clear_crop()
                if t.lc == "brosten":
                    t.lc = None
        elif tool == "lake":
            t.t = "water"
            t.clear_crop()
            t.lc, t.g = None, 0.0
            if self.hm and pos is not None:                # vandet ligger fladt: der graves ned til laveste hjørne
                px_, py_ = int(pos[0]), int(pos[1])
                self.level(px_, py_, 1, 1, min(self.hcorners(px_, py_)))
            if p is not None and pos is not None:
                (p.get("tacc") or {}).pop(f"{int(pos[0])},{int(pos[1])}", None)
        elif tool in BUILDINGS:
            t.b, t.t = tool, "grass"
            t.clear_crop()
            if self.hm and pos is not None:
                self.level(int(pos[0]), int(pos[1]), 1, 1)

    def _place(self, ax, ay, w, h, kind):
        for q in self.players.values():                   # en gammel spejlvending på samme plads gælder ikke længere
            if q.get("bflip"):
                q["bflip"].pop(f"{ax},{ay}", None)
        for y in range(ay, ay + h):
            for x in range(ax, ax + w):
                t = self.tiles[y][x]
                t.clear_crop()
                t.t, t.b, t.ba = "grass", kind, ((ax, ay, w, h) if (w, h) != (1, 1) else None)
                self.touch(x, y)
        if self.hm:                                       # bygninger står på fladt land: jorden jævnes
            self.level(ax, ay, w, h)

    def mill_site(self, x, y):
        """Vindmøllen skal stå mindst MILL_DIST felter fra stuehuse (også naboernes) og byen."""
        R = MILL_DIST
        for yy in range(y - R, y + R + 1):
            for xx in range(x - R, x + R + 1):
                if self.inb(xx, yy):
                    t = self.tiles[yy][xx]
                    if t.b == "gaard" or (t.b or "").startswith("ext:") or t.t == "town" or in_town(xx, yy):
                        return False
        return True

    def act_build(self, pid, kind, x0, y0, rot=False):
        p = self.players[pid]
        b = BUILDINGS[kind]
        if kind == "jagthytte":
            return self.act_hut(pid, x0, y0)
        w, h = b["size"][::-1] if rot else b["size"]
        if kind == "vindmoelle" and not self.mill_site(x0, y0):
            self.log(f"En vindmølle skal stå mindst {MILL_DIST} felter fra stuehuse og byen – den larmer.", pid, "err")
            return
        cells = [(x, y) for y in range(y0, y0 + h) for x in range(x0, x0 + w)]
        for x, y in cells:
            if not self.inb(x, y) or self.tiles[y][x].o != pid:
                self.log(f"{b['navn']} ({w}×{h} felter) skal stå på din egen jord.", pid, "err")
                return
            t = self.tiles[y][x]
            if t.b or t.crop or t.t not in ("grass", "field", "stub", "plaene"):
                self.log(f"Der skal være {w}×{h} ledige felter græs eller tom mark.", pid, "err")
                return
        if p["money"] < b["cost"]:
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= b["cost"]
        self.book(p, "byggeri", -b["cost"])
        self._place(x0, y0, w, h, kind)
        if rot and w == h:                                 # kvadratiske bygninger drejes ved at spejlvende dem
            p.setdefault("bflip", {})[f"{x0},{y0}"] = True
        self.log(f"{b['navn']} bygget (-{kr(b['cost'])}).", pid, "good")
        if b.get("group") == "maskinhus":
            self._fix_capacity(p)

    # ── jagthytter ───────────────────────────────────────────────────────────
    def hut_site(self, pid, x, y):
        """('own'|'state', None) hvis der må stå en jagthytte her – ellers (None, hvorfor ikke)."""
        if not self.inb(x, y):
            return None, "Uden for kortet."
        t = self.tiles[y][x]
        if t.b or t.crop:
            return None, "Feltet er optaget."
        if t.o == pid and t.t in ("grass", "forest", "field", "stub", "plaene"):
            kind = "own"
        elif t.o < 0 and t.t == "forest" and t.lc != "ung" and not in_town(x, y, 3) and (x, y) not in self.ctiles:
            kind = "state"
        else:
            return None, "En jagthytte skal stå på din egen jord eller i statsskoven (skov, ingen ejer)."
        if self.near_forest(x, y, pid)[0] < 6:
            return None, "Der skal være skov tæt på (din egen eller statsskov)."
        return kind, None

    def act_hut(self, pid, x, y):
        p = self.players[pid]
        huts = p.setdefault("huts", [])
        if len(huts) >= HUT_MAX:
            self.log(f"Du har allerede {HUT_MAX} jagthytter.", pid, "err")
            return
        kind, why = self.hut_site(pid, x, y)
        if not kind:
            self.log(why, pid, "err")
            return
        cost = BUILDINGS["jagthytte"]["cost"]
        if p["money"] < cost and not self.sandbox():
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= cost
        self.book(p, "byggeri", -cost)
        t = self.tiles[y][x]
        t.b, t.ba = "jagthytte", None
        self.level(x, y, 1, 1)
        self.touch(x, y)
        huts.append([x, y, kind])
        self.log("Jagthytten står klar" + (f" i statsskoven (jagtleje {kr(HUT_LEASE)} pr. måned)" if kind == "state"
                 else "") + f" (-{kr(cost)}). Kør herud og tryk J for at gå på jagt.", pid, "good")

    def hut_owner(self, x, y):
        for p in self.players.values():
            for h in p.get("huts", []):
                if h[0] == x and h[1] == y:
                    return p, h
        return None, None

    def act_hut_sell(self, pid, x, y):
        p, h = self.hut_owner(x, y)
        if not p or p["id"] != pid:
            return
        p["huts"].remove(h)
        it = f"h:{x},{y}"
        self.rentals = [r for r in self.rentals if r["item"] != it]
        self.rent_offers = [o for o in self.rent_offers if o["item"] != it]
        t = self.tiles[y][x]
        if t.b == "jagthytte":
            t.b = None
            self.touch(x, y)
        back = BUILDINGS["jagthytte"]["cost"] * 0.5
        p["money"] += back
        self.book(p, "byggeri", back)
        self.log(f"Du har solgt jagthytten (+{kr(back)}).", pid, "info")

    def huts_of(self, p):
        """Hytterne man må bruge: sine egne og dem, man har lejet. → [(x, y, ejer-id)]"""
        out = [(h[0], h[1], p["id"]) for h in p.get("huts", [])]
        for r in self.rentals:
            if r["renter"] == p["id"] and r["item"].startswith("h:"):
                x, y = map(int, r["item"][2:].split(","))
                out.append((x, y, r["owner"]))
        return out

    def near_hut(self, p, x, y):
        return any(max(abs(hx - x), abs(hy - y)) <= HUT_RANGE for hx, hy, _ in self.huts_of(p))

    def hut_hosts(self, p, x, y):
        """Ejerne af lejede hytter tæt på – man må jage i deres skov."""
        return {o for hx, hy, o in self.huts_of(p) if o != p["id"] and max(abs(hx - x), abs(hy - y)) <= HUT_RANGE}

    def movable(self, b):
        return bool(b) and b != "jagthytte" and (b in BUILDINGS or (b.startswith("ext:") and b[4:] in ADDONS))

    # ── låger i foldens hegn: hegnet spærrer, når man selv kører – lågen kan åbnes og lukkes (O) ──
    @staticmethod
    def gate_key(x, y, d):
        return f"{x},{y},{d}"

    def fence_edge(self, x, y, d):
        """Er der foldhegn på kanten mellem foldfeltet (x, y) og naboen i retning N4[d]?"""
        if not self.inb(x, y) or self.tiles[y][x].t != "pasture":
            return False
        dx, dy = N4[d]
        nx, ny = x + dx, y + dy
        return not self.inb(nx, ny) or self.tiles[ny][nx].t != "pasture" or self.tiles[ny][nx].o != self.tiles[y][x].o

    def gate_ok(self, x, y, d):
        """Må der sidde en låge her? (på foldens hegn – ud mod åben jord, ikke ind i en bygning eller sø)"""
        if not self.fence_edge(x, y, d):
            return False
        dx, dy = N4[d]
        nx, ny = x + dx, y + dy
        return self.inb(nx, ny) and not self.tiles[ny][nx].b and self.tiles[ny][nx].t != "water"

    def gate_at(self, x, y, d):
        """(ejer, åben) for lågen på kanten – eller None."""
        if not self.inb(x, y):
            return None
        o = self.tiles[y][x].o
        g = (self.players.get(o) or {}).get("gates", {}).get(self.gate_key(x, y, d))
        return None if g is None else (o, bool(g))

    def fence_blocks(self, a, b):
        """Spærrer et foldhegn (uden åben låge) mellem to nabofelter? Bruges, når man selv kører."""
        (ax, ay), (bx, by) = a, b
        dx, dy = bx - ax, by - ay
        if abs(dx) + abs(dy) != 1:
            if abs(dx) == 1 and abs(dy) == 1:             # på skrå: spærret, hvis begge veje rundt er spærret
                return (self.fence_blocks(a, (bx, ay)) or self.fence_blocks((bx, ay), b)) and \
                    (self.fence_blocks(a, (ax, by)) or self.fence_blocks((ax, by), b))
            return False
        for (px, py), (qx, qy) in ((a, b), (b, a)):
            d = N4.index((qx - px, qy - py))
            if self.fence_edge(px, py, d):
                g = self.gate_at(px, py, d)
                if (not g or not g[1]) and not self.fence_broken(px, py, d):
                    return True
        return False

    def fence_broken(self, x, y, d):
        """Har stormen slået hul i hegnet her?"""
        if not self.inb(x, y):
            return False
        return self.gate_key(x, y, d) in (self.players.get(self.tiles[y][x].o) or {}).get("fbreak", {})

    def breaks_near(self, pid, x, y, r=1.3):
        out = []
        for k in (self.players.get(pid) or {}).get("fbreak", {}):
            gx, gy, d = map(int, k.split(","))
            dd = math.hypot(gx + N4[d][0] * 0.5 - x, gy + N4[d][1] * 0.5 - y)
            if dd <= r:
                out.append((dd, gx, gy, d))
        return sorted(out)

    def _fix_fence(self, p, key, paid=False):
        p.get("fbreak", {}).pop(key, None)
        x, y, _ = map(int, key.split(","))
        self.touch(x, y)
        lo = p.get("loose")
        if lo and lo.get("gate") == key:
            self._animal_home(p, "Hegnet er lappet, og {n} gik tilbage i folden.")
        self.log("Du lappede hullet i hegnet" + (f" (-{kr(FENCE_FIX_COST)})." if paid else "."), p["id"], "good")

    def gates_near(self, x, y, r=1.3):
        """Lågerne nær et punkt (feltkoordinater med midten i heltal): [(afstand, x, y, d)]."""
        out = []
        for gx in range(int(x) - 2, int(x) + 3):
            for gy in range(int(y) - 2, int(y) + 3):
                if not self.inb(gx, gy) or self.tiles[gy][gx].t != "pasture":
                    continue
                for d in range(4):
                    if self.gate_at(gx, gy, d):
                        mx, my = gx + N4[d][0] * 0.5, gy + N4[d][1] * 0.5      # midt på kanten
                        dd = math.hypot(mx - x, my - y)
                        if dd <= r:
                            out.append((dd, gx, gy, d))
        return sorted(out)

    def act_gate(self, pid, x, y, d, op="toggle", vid=None):
        p = self.players.get(pid)
        if not p or not 0 <= d < 4:
            return
        if vid is not None:                               # O, mens man kører: den nærmeste låge
            tr = self._veh(pid, int(vid))
            if not tr:
                return
            br = self.breaks_near(pid, tr["x"], tr["y"])
            if br:                                        # et hul i hegnet: lap det med ATV/UTV/terrænbil
                if VEHICLES.get(tr["k"], {}).get("style") in ATV_STYLES:
                    self._fix_fence(p, self.gate_key(*br[0][1:]))
                else:
                    self.log("Hegnet lappes fra en ATV, UTV eller terrænbil – eller klik på hullet med Fold og hegn "
                             f"({kr(FENCE_FIX_COST)}).", pid, "info")
                return
            near = self.gates_near(tr["x"], tr["y"])
            near = [g for g in near if self.tiles[g[2]][g[1]].o == pid]
            if not near:
                self.log("Der er ingen låge lige her – kør helt hen til lågen i hegnet.", pid, "info")
                return
            _, x, y, d = near[0]
            op = "toggle"
        if not self.inb(x, y) or self.tiles[y][x].o != pid:
            return
        gates = p.setdefault("gates", {})
        k = self.gate_key(x, y, d)
        if k in p.get("fbreak", {}):                      # klik på et hul i hegnet: lap det
            if p["money"] < FENCE_FIX_COST and not self.sandbox():
                self.log("Ikke nok penge.", pid, "err")
                return
            p["money"] -= FENCE_FIX_COST
            self.book(p, "byggeri", -FENCE_FIX_COST)
            self._fix_fence(p, k, paid=True)
            return
        if op == "place":
            if k in gates:
                op = "toggle"
            elif not self.gate_ok(x, y, d):
                self.log("En låge sidder i foldens hegn ud mod åben jord – ikke ind mod en bygning eller sø.",
                         pid, "err")
                return
            elif p["money"] < GATE_COST and not self.sandbox():
                self.log(f"En låge koster {kr(GATE_COST)}.", pid, "err")
                return
            else:
                p["money"] -= GATE_COST
                self.book(p, "byggeri", -GATE_COST)
                gates[k] = False
                self.touch(x, y)
                self.log(f"Satte en låge i hegnet (-{kr(GATE_COST)}). Åbn og luk den med O, når du selv kører – "
                         "eller klik på den med Fold og hegn.", pid, "good")
                return
        if op == "remove":
            if k in gates and sum(1 for g in gates if self._gate_fold(p, g) == self._gate_fold(p, k)) > 1:
                del gates[k]
                self.touch(x, y)
            return
        if k not in gates:
            return
        gates[k] = not gates[k]
        self.touch(x, y)
        loose = p.get("loose")
        if not gates[k] and loose and loose.get("gate") == k:
            self._animal_home(p, "Du lukkede lågen, og {n} gik tilbage i folden.")

    def _gate_fold(self, p, key):
        """Hvilken fold (sammenhængende foldfelter) en låge hører til – som et fast felt i folden."""
        x, y, _ = map(int, key.split(","))
        for comp in self.fold_parts(p["id"]):
            if (x, y) in comp:
                return comp[0]
        return None

    def fold_parts(self, pid):
        """Spillerens folde som lister af sammenhængende foldfelter."""
        T, seen, out = self.tiles, set(), []
        for y in range(self.H):
            for x in range(self.W):
                if (x, y) in seen or T[y][x].t != "pasture" or T[y][x].o != pid:
                    continue
                comp, todo = [], [(x, y)]
                seen.add((x, y))
                while todo:
                    cx, cy = todo.pop()
                    comp.append((cx, cy))
                    for dx, dy in N4:
                        nx, ny = cx + dx, cy + dy
                        if self.inb(nx, ny) and (nx, ny) not in seen and T[ny][nx].t == "pasture" and \
                                T[ny][nx].o == pid:
                            seen.add((nx, ny))
                            todo.append((nx, ny))
                out.append(sorted(comp))
        return out

    def ensure_gates(self, p):
        """Fjern låger, der ikke længere sidder i et hegn, og giv hver fold uden låge én (lukket) låge –
        på siden mod stalden, vejen eller gården."""
        gates = p.setdefault("gates", {})
        for k in list(gates):
            x, y, d = map(int, k.split(","))
            if not self.gate_ok(x, y, d) or self.tiles[y][x].o != p["id"]:
                del gates[k]
        for k in list(p.get("fbreak", {})):
            x, y, d = map(int, k.split(","))
            if not self.fence_edge(x, y, d) or self.tiles[y][x].o != p["id"]:
                del p["fbreak"][k]
        have = {tuple(map(int, k.split(",")))[:2] for k in gates}
        hx, hy = p.get("home", (0, 0))
        for comp in self.fold_parts(p["id"]):
            if any(c in have for c in comp):
                continue
            best = None
            for (x, y) in comp:
                for d in range(4):
                    if not self.gate_ok(x, y, d):
                        continue
                    nx, ny = x + N4[d][0], y + N4[d][1]
                    tt = self.tiles[ny][nx].t
                    sc = abs(nx - hx) + abs(ny - hy) - (3 if tt in ROADS or tt in ("gravel", "fliser") else 0)
                    if best is None or sc < best[0]:
                        best = (sc, x, y, d)
            if best:
                gates[self.gate_key(*best[1:])] = False
                self.touch(best[1], best[2])

    def _farm_chores(self, p):
        """Små opgaver på gården: udmugning tæller ned, storm slår hul i hegnet, og om foråret kælver koen."""
        mk = p.get("muck")
        if mk:
            for k in list(mk):
                x, y = map(int, k.split(","))
                t = self.tiles[y][x]
                mk[k] -= 1
                if mk[k] <= 0 or not t.b or BUILDINGS.get(t.b, {}).get("group") not in STALL_GROUPS:
                    del mk[k]
                    self.touch(x, y)
        if p.get("ai"):
            return
        parts = None
        if self.weather == "Storm" and self.rng.random() < FENCE_BREAK:
            parts = self.fold_parts(p["id"])
            edges = [(x, y, d) for comp in parts for (x, y) in comp for d in range(4)
                     if self.gate_ok(x, y, d) and self.gate_key(x, y, d) not in p.get("gates", {})
                     and self.gate_key(x, y, d) not in p.get("fbreak", {})]
            if edges:
                x, y, d = self.rng.choice(edges)
                p.setdefault("fbreak", {})[self.gate_key(x, y, d)] = True
                self.touch(x, y)
                self.log("Stormen har slået hul i hegnet om folden! Kør ud på en ATV, UTV eller terrænbil og lap det "
                         f"(O) – eller klik på hullet med Fold og hegn ({kr(FENCE_FIX_COST)}).", p["id"], "warn")
        b = p.get("birth")
        if b:
            b["d"] -= 1
            if b["d"] <= 0:
                p.pop("birth")
                self.touch(b["x"], b["y"])
                self.log(f"{ANIMAL_ONE.get(b['k'], 'Dyret').capitalize()} klarede {BIRTH_WORD[b['k']][0]} selv.",
                         p["id"], "info")
        elif self.month() in (2, 3, 4) and self.rng.random() < BIRTH_CHANCE:
            kinds = [k for k in ("cows", "sheep") if p.get(k, 0) >= 2]
            past = self.pasture(p["id"])
            if kinds and past:
                k = self.rng.choice(kinds)
                x, y = self.rng.choice(past)
                p["birth"] = {"k": k, "x": x, "y": y, "d": BIRTH_DAYS}
                self.touch(x, y)
                self.log(f"{ANIMAL_ONE[k].capitalize()} er ved at {BIRTH_WORD[k][1]} ude i folden! Kør derud inden "
                         f"for {BIRTH_DAYS} dage og hjælp til – så får du {BIRTH_WORD[k][2]} mere.", p["id"], "warn")

    def _birth_visit(self, tr):
        """Man kører selv hen til koen, der kælver: en kalv (eller et lam) mere."""
        p = self.players.get(tr["o"])
        b = p and p.get("birth")
        if not b or math.hypot(tr["x"] - b["x"], tr["y"] - b["y"]) > 1.3:
            return
        p.pop("birth")
        k = b["k"]
        self.touch(b["x"], b["y"])
        if self.animal_cap(p, k) > p.get(k, 0):
            p[k] += 1
            self.log(f"Du hjalp til – {BIRTH_WORD[k][2]} kom sundt til verden. Du har nu {p[k]} "
                     f"{ANIMALS[k][3]}.", p["id"], "good")
        elif k == "cows" and len(p.setdefault("calves", [])) < self.capacity(p, "kalvehytter"):
            p["calves"].append({"d": 0})
            self.log(f"Du hjalp til – {BIRTH_WORD[k][2]} kom sundt til verden og er flyttet ud i kalvehytterne.",
                     p["id"], "good")
        else:
            v = ANIMALS[k][1] * 0.6
            p["money"] += v
            self.book(p, "dyr", v)
            self.log(f"Du hjalp til – {BIRTH_WORD[k][2]} kom sundt til verden. Der er ikke plads i stalden, så den er "
                     f"solgt til naboen (+{kr(v)}).", p["id"], "good")

    def muck_spot(self, tr):
        """Stalden, maskinen holder foran porten til: (ankernøgle, bygning) – ellers None."""
        p = self.players.get(tr["o"])
        if not p:
            return None
        fp = self.front_point(tr) if tr.get("man") else (tr["x"], tr["y"])
        best = None
        for k, poss in self.stats(tr["o"])["bpos"].items():
            if k not in BUILDINGS or BUILDINGS[k]["group"] not in STALL_GROUPS:
                continue
            for pos in poss:
                dr = self.bdoor(pos[0], pos[1])
                if not dr:
                    continue
                (dx_, dy_), _ = dr
                d = min(math.hypot(dx_ - fp[0], dy_ - fp[1]), math.hypot(dx_ - tr["x"], dy_ - tr["y"]))
                if d <= 1.1 and (best is None or d < best[0]):
                    best = (d, f"{int(pos[0])},{int(pos[1])}", k)
        return best[1:] if best else None

    def _muck(self, tr, p):
        sp = self.muck_spot(tr)
        if not sp:
            return False
        key, kind = sp
        mk = p.setdefault("muck", {})
        if mk.get(key, 0) > MUCK_DAYS * 0.5:
            self.log(f"{BUILDINGS[kind]['navn']} er muget ud for nylig – kom igen om {int(mk[key] - MUCK_DAYS * 0.5) + 1} "
                     "dage.", p["id"], "info")
            return True
        mk[key] = float(MUCK_DAYS)
        p["gylle"] = min(self.gylle_cap(p), p.get("gylle", 0.0) + MUCK_GYLLE)
        x, y = map(int, key.split(","))
        self.touch(x, y)
        self.log(f"Du mugede {BUILDINGS[kind]['navn'].lower()} ud og lagde frisk strøelse: dyrene i den yder "
                 f"{int(MUCK_BONUS * 100)}% mere i {MUCK_DAYS} dage (møget kom i gylletanken).", p["id"], "good")
        return True

    def muck_bonus(self, p, kind):
        """Ekstra ydelse for en dyreart fra udmugede stalde (efter hvor stor en del af pladsen, der er muget)."""
        mk = p.get("muck")
        if not mk:
            return 0.0
        grp = ANIMALS[kind][0]
        tot = self.capacity(p, grp)
        if tot <= 0:
            return 0.0
        done = 0
        for k in mk:
            x, y = map(int, k.split(","))
            b = self.tiles[y][x].b
            if b in BUILDINGS and BUILDINGS[b]["group"] == grp:
                done += BUILDINGS[b]["cap"]
        return MUCK_BONUS * min(1.0, done / tot)

    def _gates_day(self, p):
        """Åbne låger: et dyr kan smutte ud og gå en tur – det giver intet, til det er tilbage."""
        lo = p.get("loose")
        if lo and (p.get("pets") or {}).get("hund"):
            self._animal_home(p, "Gårdhunden drev {n} tilbage i folden.")
            return
        if lo:
            lo["d"] -= 1
            g = p.get("gates", {}).get(lo.get("gate"), p.get("fbreak", {}).get(lo.get("gate")))
            if lo["d"] <= 0 or g is None:
                self._animal_home(p, "{N} er gået tilbage i folden af sig selv.")
            return
        open_ = [k for k, v in p.get("gates", {}).items() if v] + list(p.get("fbreak", {}))
        kinds = [k for k in GRAZERS if p.get(k, 0) > 0]
        if not open_ or not kinds or p.get("ai"):
            return
        for k in open_:
            if self.rng.random() < GATE_ESCAPE:
                kind = self.rng.choice(kinds)
                p["loose"] = {"k": kind, "gate": k, "d": GATE_AWAY}
                x, y, _ = map(int, k.split(","))
                self.touch(x, y)
                if self.day - p.get("esc_log", -99) < 10:      # ikke en besked hver gang – Råd-fanen husker det
                    return
                p["esc_log"] = self.day
                hole = k in p.get("fbreak", {})
                one = ANIMAL_ONE.get(kind, "et dyr").capitalize()
                self.log(f"{one} er smuttet ud ad hullet i hegnet og går en tur! Lap hegnet (O fra en ATV, UTV eller "
                         "terrænbil), så går den tilbage." if hole else
                         f"{one} er smuttet ud ad den åbne låge og går en tur! Luk lågen (O, eller klik på den med "
                         "Fold og hegn), så går den tilbage.", p["id"], "warn")
                return

    def _animal_home(self, p, msg):
        lo = p.pop("loose", None)
        if not lo:
            return
        n = ANIMAL_ONE.get(lo["k"], "dyret")
        self.log(msg.format(n=n, N=n.capitalize()), p["id"], "good")
        try:
            x, y, _ = map(int, lo["gate"].split(","))
            self.touch(x, y)
        except (ValueError, KeyError):
            pass

    def act_hoop(self, pid, x, y, to=None):
        """Byg rundbuehallen om: maskinhal, halmlager eller foderhal (to = den nye slags)."""
        p = self.players.get(pid)
        if not p or not self.inb(x, y):
            return
        t = self.tiles[y][x]
        if t.o != pid or t.b not in HOOP_KINDS:
            return
        new = to if to in HOOP_KINDS else HOOP_KINDS[1] if t.b == HOOP_KINDS[0] else HOOP_KINDS[0]
        if new == t.b:
            return
        probe = {"rundbuehal_halm": "halm", "rundbuehal_foder": "graes"}.get(t.b)
        if probe:                                        # det, der ligger i hallen, skal kunne være et andet sted
            room = self.storage_cap(p, probe) - BUILDINGS[t.b]["cap"]
            if self.stored(p, probe) > room + 0.5:
                self.log("Der ligger for meget i hallen – " +
                         ("sælg eller fodr nogle baller" if probe == "halm" else "fodr eller sælg noget ensilage") +
                         ", eller byg mere plads først.", pid, "err")
                return
        if p["money"] < HOOP_SWITCH:
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= HOOP_SWITCH
        self.book(p, "byggeri", -HOOP_SWITCH)
        ax, ay, w, h = self.anchor(x, y)
        for yy in range(ay, ay + h):
            for xx in range(ax, ax + w):
                self.tiles[yy][xx].b = new
                self.touch(xx, yy)
        self.log(f"Rundbuehallen er nu {HOOP_WHAT[new]} "
                 f"(-{kr(HOOP_SWITCH)}).", pid, "good")
        self._fix_capacity(p)                            # maskiner, der ikke længere har en bås, holder udenfor

    def move_cost(self, b):
        base = BUILDINGS[b]["cost"] if b in BUILDINGS else ADDONS[b[4:]]["cost"]
        return max(MOVE_MIN, int(round(base * MOVE_FRAC / 50.0)) * 50)

    def act_move(self, pid, sx, sy, x0, y0, rot=False):
        """Flyt en bygning (eller tilbygning) til en ny plads på egen jord – mod et lille beløb."""
        p = self.players.get(pid)
        if not p or not self.inb(sx, sy):
            return
        t0 = self.tiles[sy][sx]
        b = t0.b
        if t0.o != pid or not self.movable(b):
            self.log("Der er ingen bygning at flytte her.", pid, "err")
            return
        ax, ay, w0, h0 = self.anchor(sx, sy)
        size = BUILDINGS[b]["size"] if b in BUILDINGS else ADDONS[b[4:]]["size"]
        w, h = size[::-1] if rot else size
        name = BUILDINGS[b]["navn"] if b in BUILDINGS else ADDONS[b[4:]]["navn"]
        old = [(x, y) for y in range(ay, ay + h0) for x in range(ax, ax + w0)]
        new = [(x, y) for y in range(y0, y0 + h) for x in range(x0, x0 + w)]
        olds = set(old)
        for x, y in new:
            if not self.inb(x, y) or self.tiles[y][x].o != pid:
                self.log(f"{name} ({w}×{h} felter) skal stå på din egen jord.", pid, "err")
                return
            t = self.tiles[y][x]
            if (x, y) not in olds and (t.b or t.crop or t.t not in ("grass", "field", "stub", "plaene")):
                self.log(f"Der skal være {w}×{h} ledige felter græs eller tom mark.", pid, "err")
                return
        if b == "vindmoelle" and not self.mill_site(x0, y0):
            self.log(f"En vindmølle skal stå mindst {MILL_DIST} felter fra stuehuse og byen – den larmer.", pid, "err")
            return
        flip_now = bool(p.get("aflip", {}).get(b[4:])) if b.startswith("ext:") else \
            bool(p.get("bflip", {}).get(f"{ax},{ay}")) if w0 == h0 else (w0, h0) != tuple(size)
        if (x0, y0) == (ax, ay) and (w, h) == (w0, h0) and bool(rot) == flip_now:
            return
        cost = self.move_cost(b)
        if p["money"] < cost and not self.sandbox():
            self.log(f"Det koster {kr(cost)} at flytte {name.lower()}.", pid, "err")
            return
        snap = {c: (self.tiles[c[1]][c[0]].t, self.tiles[c[1]][c[0]].b, self.tiles[c[1]][c[0]].ba)
                for c in olds | set(new)}
        before = {k: self.animal_cap(p, k) for k in ANIMALS}
        for x, y in old:
            t = self.tiles[y][x]
            t.b, t.ba = None, None
            self.touch(x, y)
        self._place(x0, y0, w, h, b)
        short = [k for k in ANIMALS if p.get(k, 0) > self.animal_cap(p, k) and self.animal_cap(p, k) < before[k]]
        if short:                                          # dyrene ville miste deres plads: fortryd flytningen
            for (x, y), (tt, tb, tba) in snap.items():
                t = self.tiles[y][x]
                t.t, t.b, t.ba = tt, tb, tba
                self.touch(x, y)
            self.log(f"Ikke her – så er der ikke plads til dine {ANIMALS[short[0]][3]}. Stalden skal røre folden.",
                     pid, "err")
            return
        if b.startswith("ext:"):
            p.setdefault("aflip", {})[b[4:]] = bool(rot)
        elif w == h:
            p.setdefault("bflip", {}).pop(f"{ax},{ay}", None)
            if rot:
                p["bflip"][f"{x0},{y0}"] = True
        if BUILDINGS.get(b, {}).get("group") == "maskinhus":   # maskinerne og båsene følger med huset
            ok, nk = self.shed_key((ax, ay)), self.shed_key((x0, y0))
            park = p.setdefault("park", {})
            if ok in park:
                park[nk] = park.pop(ok)
            for tr in self.tractors:
                if tr["o"] == pid and list(tr["hs"]) == [ax, ay]:
                    tr["hs"] = [x0, y0]
                    if tr["s"] == "parked":
                        tr["x"], tr["y"] = float(x0), float(y0)
        if not self.sandbox():
            p["money"] -= cost
            self.book(p, "byggeri", -cost)
        self._sync_park(p, True)
        self.log(f"{name} er flyttet (-{kr(cost)}).", pid, "good")

    def demolish_preview(self, p, x, y):
        """Hvad sker der, hvis bygningen rives ned? -> (bygning, kr tilbage, [linjer]) eller None.
        Bruges både af serveren (selve nedrivningen) og af vinduet, der spørger først."""
        if not self.inb(x, y):
            return None
        t = self.tiles[y][x]
        b = t.b
        if not p or t.o != p["id"] or b not in BUILDINGS:
            return None
        d = BUILDINGS[b]
        refund = int(round(d["cost"] * DEMOLISH_REFUND)) - DEMOLISH_FEE
        lines = []
        grp = d["group"]
        caps = {grp: d["cap"], **d.get("also", {})}
        for kind, a in ANIMALS.items():                     # dyr, der ikke længere er plads til
            if a[0] in caps and p.get(kind, 0):
                left = max(0, self.animal_cap(p, kind) - caps[a[0]])
                n = p[kind] - left
                if n > 0:
                    lines.append((f"{n} {a[3] if n > 1 else a[2]} er der ikke plads til – de sælges for "
                                  f"{kr(n * a[1] * 0.6)}", C_WARN))
        if grp == "maskinhus":                              # maskiner, der må holde udenfor
            bays = d.get("bays", 0) * SHED_ROWS if "bays" in d else d["cap"]
            n = len(self.vehicles_of(p["id"]))
            room = sum(self.shed_bays(p["id"]).values()) * SHED_ROWS - bays
            if n > room:
                lines.append((f"{n - max(0, room)} maskine{'r' if n - max(0, room) > 1 else ''} må holde udenfor "
                              "(slides mere af vejret)", C_WARN))
        for g_, probe in (("baller", "halm"), ("plansilo", "graes"), ("korn", "hvede"), ("toemmerplads", "tommer")):
            grp_ = {"baller": "balleplads", "korn": "silo"}.get(g_, g_)
            lost = caps.get(grp_, 0) if grp_ != "silo" else sum(caps.get(k_, 0) for k_ in ("silo", "kartoffellager",
                                                                                         "fodersilo"))
            if lost and self.stored(p, probe) > self.storage_cap(p, probe) - lost:
                over = int(self.stored(p, probe) - (self.storage_cap(p, probe) - lost))
                lines.append((f"Lageret bliver {over} enheder for lille – sælg eller brug noget af det", C_WARN))
        key = f"{x},{y}"
        ax, ay = (t.ba or (x, y))[:2]
        if f"{ax},{ay}" in (p.get("robots") or {}):
            lines.append(("Malkerobotten i stalden forsvinder med", C_WARN))
        if b == "kalvehytter" and p.get("calves"):
            left = self.capacity(p, "kalvehytter") - d["cap"]
            if len(p["calves"]) > left:
                lines.append((f"{len(p['calves']) - max(0, left)} kalve sælges", C_WARN))
        if d.get("upkeep"):
            lines.append((f"Udgifterne falder med {kr(d['upkeep'])} om måneden", C_GOOD))
        lines.append((f"Du får {kr(d['cost'] * DEMOLISH_REFUND)} for materialerne, og nedrivningen koster "
                      f"{kr(DEMOLISH_FEE)}", C_DIM))
        return b, refund, lines

    def act_demolish(self, pid, x, y):
        """Riv en bygning ned: 25% af byggeprisen tilbage (minus nedrivningen); dyr og maskiner tilpasses."""
        p = self.players.get(pid)
        pv = self.demolish_preview(p, x, y)
        if not pv:
            return
        b, refund, _lines = pv
        t = self.tiles[y][x]
        ax, ay = (t.ba or (x, y))[:2]
        (p.get("robots") or {}).pop(f"{ax},{ay}", None)
        if b == "kalvehytter" and p.get("calves"):
            left = max(0, self.capacity(p, "kalvehytter") - BUILDINGS[b]["cap"])
            sold = p["calves"][left:]
            if sold:
                p["calves"] = p["calves"][:left]
                p["money"] += len(sold) * CALF_PRICE
                self.book(p, "dyr", len(sold) * CALF_PRICE)
        self._demolish(x, y)
        p["money"] += refund
        self.book(p, "byggeri", refund)
        self.fver = getattr(self, "fver", 0) + 1
        self._fix_capacity(p)
        self.ensure_gates(p)
        self._sync_park(p, True)
        self.log(f"{BUILDINGS[b]['navn']} er revet ned ({'+' if refund >= 0 else ''}{kr(refund)}).", pid, "info")

    def _demolish(self, x, y):
        b = self.tiles[y][x].b or ""
        if b.startswith("ext:"):
            p = self.players.get(self.tiles[y][x].o)
            if p and b[4:] in p["addons"]:
                p["addons"].remove(b[4:])
        ax, ay, w, h = self.anchor(x, y)
        for yy in range(ay, ay + h):
            for xx in range(ax, ax + w):
                t = self.tiles[yy][xx]
                t.b, t.ba = None, None
                self.touch(xx, yy)

    def _rect(self, x0, y0, x1, y1):
        ax0, ax1 = sorted((x0, x1))
        ay0, ay1 = sorted((y0, y1))
        ax0, ay0 = max(ax0, 0), max(ay0, 0)
        ax1, ay1 = min(ax1, self.W - 1), min(ay1, self.H - 1)
        return [(x, y) for y in range(ay0, ay1 + 1) for x in range(ax0, ax1 + 1)]

    def act_tool(self, pid, tool, x0, y0, x1, y1, crop=None, rot=False):
        p = self.players.get(pid)
        if not p:
            return
        if tool == "buyland":
            return self.act_buy_land(pid, x0, y0, x1, y1)
        if tool in TRACTOR_TOOLS:
            return self.act_job(pid, tool, x0, y0, x1, y1, crop)
        if tool in BUILDINGS:
            return self.act_build(pid, tool, x0, y0, bool(rot))
        if tool.startswith("house:"):
            return self.act_house(pid, tool[6:], x0, y0, bool(rot))
        if tool.startswith("addon:"):
            return self.act_addon(pid, tool[6:], x0, y0, bool(rot))
        if tool.startswith("move:"):
            sx, sy = (int(v) for v in tool[5:].split(","))
            return self.act_move(pid, sx, sy, x0, y0, bool(rot))
        if tool == "hegn":
            return self.act_yardfence(pid, x0, y0, x1, y1, crop or "hvid")
        if tool not in ("tree", "bulldoze", "pasture", "lake", "fliser", "brosten", "plaene", *LINE_TOOLS):
            return
        area = line_cells(x0, y0, x1, y1) if tool in LINE_TOOLS else self._rect(x0, y0, x1, y1)
        if tool == "lake" and (abs(x1 - x0) < 1 or abs(y1 - y0) < 1):
            self.log("En sø skal være mindst 2×2 felter – træk et større område.", pid, "err")
            return
        wet0 = len(self.wet_ditches()) if tool == "bulldoze" else 0
        nf = self._fence_clear(p, {(x, y) for x, y in area}) if tool == "bulldoze" else 0
        if nf:
            self.log(f"Fjernede {nf} stykke{'r' if nf > 1 else ''} gårdhegn.", pid, "info")
        public = tool in ("gravel", "asphalt")          # veje må også bygges på jord uden ejer (hen til hovedvejen)
        cells = [(x, y) for x, y in area if self.inb(x, y) and (self.tiles[y][x].o == pid or (
            public and self.tiles[y][x].o < 0 and (x, y) not in self.ctiles and not in_town(x, y)))]
        if not cells:
            self.log("Du kan kun arbejde på din egen jord. Køb mere jord med 'Køb jord'.", pid, "err")
            return
        n = spent = 0
        broke = False
        digger = tool in ("ditch", "lake", "bulldoze") and self.has_digger(pid)   # egen rendegraver: 40% billigere
        saved_ = 0.0 if digger else None
        for x, y in cells:
            t = self.tiles[y][x]
            cost = self._cost(tool, t, crop)
            if cost is None:
                continue
            if digger:
                cost = round(cost * 0.6)
            if p["money"] < cost:
                broke = True
                break
            p["money"] -= cost
            self.book(p, "byggeri", -cost)
            spent += cost
            n += 1
            if digger and saved_ is not None:
                saved_ += cost / 0.6 * 0.4
            if tool == "bulldoze" and t.b in BUILDINGS:
                p["money"] += cost                            # bygninger rives ned med "Riv ned", der spørger først
                self.book(p, "byggeri", cost)
                spent -= cost
                n -= 1
                continue
            if tool == "bulldoze" and (t.b or "").startswith("ext:"):
                self._demolish(x, y)
            else:
                self._apply(tool, t, crop, p, pos=(x, y))
            self.touch(x, y)
        if tool in ("bulldoze", "pasture"):
            self._fix_capacity(p)
            self.ensure_gates(p)
        dry = wet0 - len(self.wet_ditches()) if tool == "bulldoze" and n else 0
        if n == 0:
            if nf:
                return
            hints = {"tree": "Skov kan kun plantes på græs.", "bulldoze": "Intet at rydde her.",
                     "pasture": "En fold laves på græs eller tom mark på din jord.",
                     "gravel": "Veje bygges på græs, tom mark eller over en grøft på din jord.",
                     "asphalt": "Asfalt lægges på græs, tom mark, grusvej eller over en grøft på din jord.",
                     "ditch": "Grøfter graves i græs eller tom mark på din jord.",
                     "lake": "En sø graves i græs, stub eller tom mark på din jord.",
                     "fliser": "Fliser lægges på græs, tom mark eller grusvej på din jord.",
                     "brosten": "Brosten lægges på græs, tom mark, grusvej eller fliser på din jord.",
                     "plaene": "En græsplæne sås på græs eller tom mark på din jord."}
            self.log("Ikke nok penge." if broke else hints.get(tool, "Du kan ikke bygge her."), pid, "err")
            return
        if tool in BUILDINGS:
            self.log(f"{BUILDINGS[tool]['navn']} bygget (-{kr(spent)}).", pid, "good")
            return
        verb = {"tree": "Plantede skov på", "pasture": "Satte hegn om fold på", "gravel": "Anlagde grusvej på",
                "asphalt": "Asfalterede", "fliser": "Lagde fliser på", "brosten": "Lagde brosten på", "plaene": "Såede græsplæne på",
                "ditch": "Gravede grøft på", "lake": "Gravede sø på"}.get(tool, "Ryddede")
        if tool == "bulldoze" and spent >= n * FILL_COST - 1:
            verb = "Fyldte sø op med jord på"
        self.log(f"{verb} {n} felt{'er' if n > 1 else ''} (-{kr(spent)})"
                 + (f" – din rendegraver sparede {kr(saved_)}" if saved_ else "")
                 + (" – pengene slap op." if broke else "."), pid, "info")
        if dry > 0:
            self.log(f"{dry} grøftefelter har mistet vandet, da søen blev fyldt op.", pid, "warn")
        if tool == "bulldoze" and spent >= n * FILL_COST - 1:
            self.log("Den opfyldte jord er mager – gød og kalk den et par gange, før den giver fuld høst.", pid, "info")

    # ── gårdhegn: et hvidt stakit langs felternes kanter (pynt – det spærrer ikke for noget) ──
    def fence_plan(self, pid, x0, y0, x1, y1, alle=False):
        """Hegnsstykker langs en trukket linje (samme L-form som veje) som (x, y, d): d=0 = kanten mellem (x,y) og
        (x+1,y), d=1 = mellem (x,y) og (x,y+1). Hegnet sættes i yderkanten: på den side af linjen, der vender ud
        mod vej, nabo eller jord, der ikke er din – ellers på siden væk fra stuehuset."""
        p = self.players.get(pid)
        if not p:
            return []
        T = self.tiles
        path = line_cells(x0, y0, x1, y1)
        hx, hy = p.get("home", (x0, y0))

        def outside(c):
            if not self.inb(*c):
                return True
            t = T[c[1]][c[0]]
            return t.o != pid or t.t in ROADS or t.t in ("town", "water")
        out = []
        if alle and any(self.inb(x, y) and T[y][x].t in ROADS for x, y in path):
            # læhegn trukket hen ad en vej: træer på begge sider af vejen – en allé
            for i, (x, y) in enumerate(path):
                if not self.inb(x, y) or T[y][x].t not in ROADS:
                    continue
                nb = [c for c in (path[i - 1] if i else None, path[i + 1] if i + 1 < len(path) else None) if c]
                axes = {"x" if c[1] == y else "y" for c in nb} or {"x", "y"}
                for ax in axes:
                    cand = [((x, y - 1, 1), (x, y - 1)), ((x, y, 1), (x, y + 1))] if ax == "x" else \
                        [((x - 1, y, 0), (x - 1, y)), ((x, y, 0), (x + 1, y))]
                    for e, (nx, ny) in cand:
                        if not self.inb(nx, ny):
                            continue
                        n_ = T[ny][nx]
                        if n_.t in ROADS or n_.t in ("town", "water") or n_.b:
                            continue                           # ikke hen over en sidevej, i byen eller ind i en bygning
                        if T[y][x].o != pid and n_.o != pid:
                            continue                           # vejen eller jorden ved siden af skal være din
                        if e not in out:
                            out.append(e)
            return out
        for i, (x, y) in enumerate(path):
            if not self.inb(x, y):
                continue
            t = T[y][x]
            if t.o != pid or t.t in ROADS or t.t in ("town", "water"):
                continue                                       # ikke på vejen selv – der bliver en låge
            nb = [c for c in (path[i - 1] if i else None, path[i + 1] if i + 1 < len(path) else None) if c]
            axes = {"x" if c[1] == y else "y" for c in nb} or {"x", "y"}
            for ax in axes:
                cand = [((x, y - 1, 1), (x, y - 1)), ((x, y, 1), (x, y + 1))] if ax == "x" else \
                    [((x - 1, y, 0), (x - 1, y)), ((x, y, 0), (x + 1, y))]
                pick = [e for e, n in cand if outside(n)]
                if not pick:                                   # midt på egen jord: siden væk fra stuehuset
                    e, n = max(cand, key=lambda en: abs(en[1][0] - hx) + abs(en[1][1] - hy))
                    pick = [e]
                out += [e for e in pick if e not in out]
        return out

    def act_yardfence(self, pid, x0, y0, x1, y1, col="hvid"):
        p = self.players.get(pid)
        if not p:
            return
        alle = col == "alle"                               # allé: læhegn på begge sider af vejen
        col = "laehegn" if alle else col if col in FENCE_COLS else "hvid"
        fence = p.setdefault("yfence", {})
        edges = self.fence_plan(pid, x0, y0, x1, y1, alle=alle)
        if not edges and alle:
            self.log("Træk alléen hen ad en vej – på din egen jord eller langs dine marker.", pid, "err")
            return
        if not edges:
            self.log("Træk hegnet langs dine egne felter – fx langs vejen eller skellet. Det sættes i yderkanten, "
                     "og hvor det krydser en vej, bliver der en låge.", pid, "err")
            return
        keys = ["%d,%d,%d" % e for e in edges]
        if all(k in fence and (fence[k] == col or (fence[k] == 1 and col == "hvid")) for k in keys):   # igen: ned
            for k in keys:
                fence.pop(k, None)
            self.log(f"Tog {len(keys)} stykker gårdhegn ned.", pid, "info")
            return
        new = [k for k in keys if k not in fence]
        cost = len(new) * (LAEHEGN_COST if col == "laehegn" else HAEK_COST if col == "haek" else YARD_FENCE_COST)
        if p["money"] < cost and not self.sandbox():
            self.log(f"Hegnet koster {kr(cost)} – ikke nok penge.", pid, "err")
            return
        recol = sum(1 for k in keys if k in fence and fence[k] != col)
        for k in keys:
            fence[k] = col
        if not self.sandbox():
            p["money"] -= cost
            self.book(p, "byggeri", -cost)
        what = {"hvid": "hvidt", "sort": "sort", "trae": "træfarvet", "laehegn": "", "haek": ""}[col]
        if col == "laehegn":
            on_road = alle
            msg = (f"Plantede en allé langs vejen: {len(new)} stykker læhegn (-{kr(cost)}) – markerne ved siden af "
                   "får læ for storm og tørke" if on_road else
                   f"Plantede {len(new)} stykker læhegn (-{kr(cost)}) – markerne bag det får læ for storm og tørke") \
                if new else "Hegnet er skiftet til læhegn"
        elif col == "haek":
            msg = f"Plantede {len(new)} stykker bøgehæk (-{kr(cost)})" if new else "Hegnet er skiftet til bøgehæk"
        else:
            msg = f"Satte {len(new)} stykker {what} stakit op (-{kr(cost)})" if new else "Hegnet er malet om"
        if recol and new:
            msg += f" og malede {recol} stykker om"
        self.log(msg + ". Træk samme linje igen i samme farve for at fjerne det.", pid, "good")

    def _fence_clear(self, p, cells):
        fence = p.get("yfence") or {}
        gone = [k for k in fence if (lambda x, y, d: (x, y) in cells or
                                     ((x + 1, y) if d == 0 else (x, y + 1)) in cells)(*map(int, k.split(",")))]
        for k in gone:
            fence.pop(k, None)
        return len(gone)

    def act_buy_land(self, pid, x0, y0, x1, y1):
        p = self.players[pid]
        T = self.tiles
        valid = {(x, y) for x, y in self._rect(x0, y0, x1, y1)
                 if T[y][x].o < 0 and T[y][x].t not in PUBLIC_T and not T[y][x].b}
        if not valid:
            self.log("Der er ingen jord til salg her.", pid, "err")
            return

        def mine(x, y):
            return self.inb(x, y) and T[y][x].o == pid and (x, y) not in self.ctiles
        frontier = [c for c in valid if any(mine(c[0] + dx, c[1] + dy) for dx, dy in N4)]
        if not frontier:
            self.log("Du kan kun købe jord, der grænser op til din egen.", pid, "err")
            return
        order, seen = [], set(frontier)
        dq = deque(frontier)
        while dq:
            c = dq.popleft()
            order.append(c)
            for dx, dy in N4:
                nb = (c[0] + dx, c[1] + dy)
                if nb in valid and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        n = spent = 0
        for x, y in order:
            price = WATER_PRICE if T[y][x].t == "water" else self.land_price()
            if p["money"] < price:
                break
            p["money"] -= price
            self.book(p, "jord", -price)
            spent += price
            n += 1
            T[y][x].o = pid
            self.touch(x, y)
        if n == 0:
            self.log("Ikke nok penge til at købe jord.", pid, "err")
        else:
            self.log(f"Købte {n} felter jord (-{kr(spent)}).", pid, "good")

    def water_reach(self):
        """Felter, et vandingsanlæg kan nå: højst WATER_REACH felter fra en sø, en brønd eller en grøft med vand."""
        c = getattr(self, "_wreach", None)
        key = (self.day, self.ver)
        if c and c[0] == key:
            return c[1]
        src = set(self.wet_ditches())
        for y, row in enumerate(self.tiles):
            for x, t in enumerate(row):
                if t.t == "water" or t.b == "broend":
                    src.add((x, y))
        seen, frontier = set(src), list(src)
        for _ in range(WATER_REACH):
            nxt = []
            for x, y in frontier:
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        q = (x + dx, y + dy)
                        if q not in seen and self.inb(*q):
                            seen.add(q)
                            nxt.append(q)
            frontier = nxt
        self._wreach = (key, seen)
        return seen

    def _snow_ready(self, p):
        trucks = any(plow_on(t) for t in self.tractors if t["o"] == p["id"])
        if not self.owns_tool(p, "snow") and not trucks:
            self.log("Du skal have en sneplov – til traktoren under Byg og køb › Udstyr, eller som opgradering "
                     "på en lastbil (højreklik på den).", p["id"], "err")
            return False
        if self.snow < 0.3:
            self.log("Der ligger ingen sne på vejene lige nu.", p["id"], "err")
            return False
        return True

    def _water_ready(self, p):
        if not self.owns_tool(p, "water"):
            self.log("Du skal have et vandingsanlæg (slangetromle) for at vande – køb det under Byg og køb › Udstyr.",
                     p["id"], "err")
            return False
        return True

    def _fell_ready(self, p):
        """Skovning kræver en skovvogn med kran og en tømmerplads at lægge stammerne på."""
        if not self.owns_tool(p, "fell"):
            self.log("Du skal have en skovvogn med kran for at fælde skov – køb den under Byg og køb › Udstyr.",
                     p["id"], "err")
            return False
        if self.storage_cap(p, "tommer") <= 0:
            self.log("Byg en tømmerplads ved gården først (Byg og køb › Bygninger) – stammerne skal ligge et sted.",
                     p["id"], "err")
            return False
        return True

    def act_job(self, pid, tool, x0, y0, x1, y1, crop, cells_in=None, quiet=False):
        p = self.players[pid]
        if self.oko_farm(p) and (tool == "spray" or (tool == "fertilize" and not self.use_gylle(p))):
            if not quiet:
                self.log("Økologisk gård: " + ("ingen sprøjtemidler – pløj ukrudtet ned og brug sædskifte."
                                               if tool == "spray" else
                                               "kun gylle – der er ikke gylle nok i tanken lige nu."), pid, "err")
            return None
        if tool == "sow":
            if crop not in CROPS:
                return
            if self.month() not in CROPS[crop]["months"]:
                self.log(f"{CROPS[crop]['navn']} kan kun sås i {sow_months_str(crop)}.", pid, "err")
                return
        if tool == "fell" and not self._fell_ready(p):
            return
        if tool == "water" and not self._water_ready(p):
            return
        if tool == "snow" and not self._snow_ready(p):
            return
        queued = {(c[0], c[1]) for j in p["jobs"] for c in j["tiles"]}
        reach = self.water_reach() if tool == "water" else None
        cells = [[x, y] for x, y in (cells_in if cells_in is not None else self._rect(x0, y0, x1, y1))
                 if (self.tiles[y][x].o == pid or (tool == "snow" and self.tiles[y][x].o < 0))
                 and (x, y) not in queued and not (tool == "snow" and (x, y) in self.plowed)
                 and self._cost(tool, self.tiles[y][x], crop) is not None and (reach is None or (x, y) in reach)]
        if not cells:
            if quiet:
                return None
            hints = {"plow": "Intet at pløje her – vælg græs, stubmark eller visnede afgrøder på din jord.",
                     "sow": "Du kan kun så på pløjet jord uden afgrøder. Høstede marker (stub) skal pløjes først.",
                     "harvest": "Intet modent at høste her.",
                     "spray": "Ingen afgrøder at sprøjte her.",
                     "fertilize": "Intet at gøde her – kun marker med under 95% næring.",
                     "lime": "Intet at kalke her – kun marker med under 90% kalk.",
                     "fell": "Ingen voksen skov at fælde her på din jord.",
                     "snow": "Ingen sne at rydde her – træk hen over veje, der ikke er ryddet.",
                     "water": f"Intet at vande her – kun tørre marker (under 80% fugt) højst {WATER_REACH} felter fra "
                              "en sø, en brønd eller en grøft med vand."}
            self.log(hints.get(tool, "Intet at gøre her."), pid, "err")
            return
        if tool not in p.setdefault("did", []):
            p["did"].append(tool)
        job = {"id": self.nid, "tool": tool, "crop": crop, "tiles": cells, "all": [list(c) for c in cells],
               "n": len(cells), "spent": 0, "made": self.day,
               "yield": {}, "lost": 0.0}
        self.nid += 1
        p["jobs"].append(job)
        if quiet:
            return job
        what = JOB_NAMES[tool].lower() + (f" af {CROPS[crop]['navn'].lower()}" if tool == "sow" else "")
        own_c = any(vkind(k) == "combine" for _, k in self.vehicles_of(pid))
        rent = self.rent(p, tool, "claus_dominator" if tool == "harvest" and own_c else "tractor")
        extra = f" Du lejer udstyr for {rent} kr/felt – køb dit eget under Byg og køb." if rent else ""
        if tool == "harvest" and not own_c:
            extra = (f" Maskinstationen sender en mejetærsker med fører ({self.hire_harvest()} kr/felt). "
                     "Med din egen mejetærsker slipper du.") if self.auto_on(p, "maskinstation") else \
                (" Men du har ingen mejetærsker, og maskinstationen er slået fra under Automatik – kornet bliver "
                 "stående, til du slår den til eller køber en mejetærsker.")
        self.log(f"Ny traktoropgave: {what} af {len(cells)} felter.{extra}", pid, "info")
        if tool != "harvest" and not any(tool in self.jobs_for(t) for t in self.tractors if t["o"] == pid
                                          and not t.get("hire")):
            self.log("Du har ingen maskine til den opgave! Højreklik på et maskinhus for at købe en.", pid, "warn")

    # ── markplan og driftslederen ────────────────────────────────────────────
    def plan_options(self, p, comp):
        """Afgrøder til en mark, bedst først: [(afgrøde, resultat pr. felt, udbytte pr. felt, begrundelser, kan sås nu)].
        Regnet på markens jord (næring, kalk, ukrudt, sædskifte), dagens priser og de normale udgifter."""
        T = self.tiles
        tiles = [T[y][x] for x, y in comp]
        if not tiles:
            return []
        n = len(tiles)
        avg_n = sum(t.n for t in tiles) / n
        avg_kc = sum(t.kc for t in tiles) / n
        avg_wd = sum(t.wd for t in tiles) / n
        lcs = {}
        for t in tiles:
            last = t.crop if t.crop else t.lc
            if last:
                lcs[last] = lcs.get(last, 0) + 1
        last = max(lcs, key=lcs.get) if lcs else None
        own_c = any(vkind(k) == "combine" for _, k in self.vehicles_of(p["id"]))
        dsl = FUEL_TILE * 4 * self.diesel_price()
        out = []
        for c, cd in CROPS.items():
            g = crop_good(c)
            if not g or cd.get("orchard") or cd.get("green"):
                continue
            if g == "graes" and not (p.get("cows") or p.get("sheep") or p.get("horses")):
                continue
            why = []
            n_after = avg_n + (FERTILIZER if avg_n < 45 else 0)
            soil = 0.55 + 0.45 * min(1.0, n_after / 70.0)
            weeds = 1.0 - 0.4 * (avg_wd if avg_wd < 20 else 3.0) / 100.0      # pløjning fjerner ukrudtet
            rot = 1.0
            if last and c != "graes":
                if last == c:
                    rot = 0.85
                    why.append("samme afgrøde som sidst: -15%")
                else:
                    rot = 1.08
                    why.append("godt sædskifte: +8%")
            lime = 1.0 if avg_kc >= 55 else 0.75 + 0.25 * avg_kc / 55
            if avg_kc < 55:
                why.append("sur jord – kalk først")
            if avg_n < 45:
                why.append("lav næring – gødes først")
            y_ = cd["udbytte"] * soil * weeds * rot * lime * 0.75      # skadedyr, vejr og ukrudt tager en del
            hn = sum(v.get(c, {}).get("n", 0) for v in (p.get("cacc") or {}).values())
            if hn >= 10:                                  # dine egne tal for afgrøden vejer halvt med
                ha = sum(v.get(c, {}).get("amt", 0) for v in (p.get("cacc") or {}).values()) / hn
                y_ = (y_ + ha * rot / (1.08 if rot > 1 else 1.0)) / 2
                why.append(f"dine egne høster: {ha:.0f}/felt".replace(".", ","))
            mk = self.market.get(g)
            price = ((mk["p"] if mk else GOODS[g]["base"]) + GOODS[g]["base"]) / 2
            rev = y_ * (price - (SALE_PICKUP if g in STORE_GOODS else 0))
            if c in STRAW_CROPS and self.owns_tool(p, "bale"):
                rev += y_ * STRAW_RATIO * GOODS.get("halm", {}).get("base", 0)
            cost = cd["seed"] + 5 + dsl
            cost += WORK_LABOR + self.input_price("sproejte") + (0 if self.owns_tool(p, "spray") else RENT["spray"])
            if avg_n < 45:
                cost += WORK_LABOR + self.input_price("goedning") + (0 if self.owns_tool(p, "fertilize") else
                                                                    RENT["fertilize"])
            if avg_kc < 55:
                cost += WORK_LABOR + self.input_price("kalk")
            cost += 3 + (0 if own_c else self.hire_harvest())
            out.append((c, rev - cost, y_, why, self.month() in cd["months"]))
        out.sort(key=lambda o: -o[1])
        return out

    def act_fplan(self, pid, x, y, crop="keep", auto=None, run=False):
        """Markplan: vælg næste afgrøde, slå driftslederen til/fra for marken, eller udfør planen nu."""
        p = self.players.get(pid)
        if not p or not self.inb(x, y):
            return
        key = self.field_key(pid, x, y)
        if not key:
            self.log("Det er ikke en af dine marker.", pid, "err")
            return
        plan = p.setdefault("fplan", {}).setdefault(key, {})
        if crop != "keep":
            if crop in CROPS:
                plan["crop"] = crop
                self.log(f"Markplan: {self.fname(p, key)} skal have {CROPS[crop]['navn'].lower()} "
                         f"(sås {sow_months_str(crop)}).", pid, "info")
            else:
                plan.pop("crop", None)
        if auto is not None:
            if auto and not p.get("manager"):
                self.log("Ansæt en driftsleder under fanen Råd først.", pid, "err")
            else:
                plan["auto"] = bool(auto)
                self.log(f"Driftslederen {'passer nu' if auto else 'passer ikke længere'} "
                         f"{self.fname(p, key)}" + (f" ({PLAN_FEE} kr pr. felt om måneden)." if auto else "."),
                         pid, "info")
        if run:
            comp = dict(self.fields_of(pid)).get(key, [])
            did = self._tend_field(p, key, comp, sow_only_plan=True)
            self.log(("Planen er sat i gang: " + ", ".join(did) + ".") if did else
                     "Der er intet at gøre på marken lige nu (eller afgrøden kan ikke sås i denne måned).", pid,
                     "info" if did else "warn")
        if not plan:
            p["fplan"].pop(key, None)
        if run or auto:
            self._guide_check()

    def _tend_field(self, p, key, comp, sow_only_plan=False):
        """Sæt det i gang, marken trænger til. Returnerer en liste med, hvad der blev sat i gang."""
        pid, T = p["id"], self.tiles
        did = []
        if not comp:
            return did
        plan = (p.get("fplan") or {}).get(key, {})

        def job(tool, cells, crop=None):
            if cells and self.act_job(pid, tool, 0, 0, 0, 0, crop, cells_in=cells, quiet=True):
                did.append(JOB_NAMES[tool].lower() + (f" af {CROPS[crop]['navn'].lower()}" if crop else ""))
        if not sow_only_plan:
            job("harvest", [c for c in comp if self._cost("harvest", T[c[1]][c[0]], None) is not None])
            sick = [c for c in comp if T[c[1]][c[0]].crop and not T[c[1]][c[0]].dead and
                    (T[c[1]][c[0]].pest or T[c[1]][c[0]].wd >= 40)]
            if sick:
                job("spray", [c for c in comp if T[c[1]][c[0]].crop and not T[c[1]][c[0]].dead])
            # efterårs-/forårsgødskning: næringen falder, mens afgrøden vokser – så gøder han en ekstra gang
            grow = [c for c in comp if T[c[1]][c[0]].crop and not T[c[1]][c[0]].dead and T[c[1]][c[0]].g < 0.75
                    and not CROPS[T[c[1]][c[0]].crop].get("green")]
            if grow and sum(T[c[1]][c[0]].n for c in grow) / len(grow) < MANAGER_TOPDRESS:
                comp_set_ = {tuple(c) for c in comp}
                if not any((c[0], c[1]) in comp_set_ for j in p["jobs"] for c in j["tiles"] if j["tool"] == "fertilize"):
                    job("fertilize", [c for c in grow if T[c[1]][c[0]].n < MANAGER_TOPDRESS + 10])
            if self.owns_tool(p, "water"):
                dry = [c for c in comp if T[c[1]][c[0]].crop and not T[c[1]][c[0]].dead and T[c[1]][c[0]].m < 25]
                if len(dry) >= max(2, len(comp) // 4):
                    reach = self.water_reach()
                    job("water", [c for c in dry if tuple(c) in reach])
        empty = [c for c in comp if not T[c[1]][c[0]].crop or T[c[1]][c[0]].dead]
        if not empty or len(empty) < len(comp):
            return did                                      # der står stadig afgrøder – hele marken sås på én gang
        comp_set = {tuple(c) for c in comp}
        if any((c[0], c[1]) in comp_set for j in p["jobs"] for c in j["tiles"]
               if j["tool"] in ("plow", "lime", "fertilize", "sow")):
            return did                                      # et trin er i gang – vent til det er færdigt
        want = plan.get("crop")
        if want and self.month() not in CROPS[want]["months"]:
            return did                                      # venter på såtiden for den planlagte afgrøde
        if not want:
            if sow_only_plan:
                return did
            opts = [o for o in self.plan_options(p, comp) if o[4] and o[1] > 0]
            if not opts:
                return did
            want = opts[0][0]
        for tool, need in (("plow", lambda t: self._cost("plow", t, None) is not None),
                           ("lime", lambda t: t.kc < 55),
                           ("fertilize", lambda t: t.n < 45 and t.t == "field")):
            cells = [c for c in empty if need(T[c[1]][c[0]])]
            if cells:
                job(tool, cells)
                return did                                  # ét trin ad gangen: pløj, kalk, gød – så så
        job("sow", [c for c in empty if T[c[1]][c[0]].t == "field" and not T[c[1]][c[0]].crop], want)
        if plan.get("crop") == want and did:
            plan.pop("crop", None)                          # planen er udført – næste år vælges på ny
        return did

    def fname(self, p, key):
        for i, (k, _) in enumerate(self.fields_of(p["id"])):
            if k == key:
                return self.field_name(p, key, i)
        return self.field_name(p, key)

    def _plan_day(self):
        """Driftslederen passer de marker, han har fået ansvaret for."""
        if self.day % 2:
            return                                         # han kigger forbi hver anden dag
        for p in self.players.values():
            plans = p.get("fplan") or {}
            autos = [k for k, v in plans.items() if v.get("auto")]
            if not autos or not p.get("manager") or p.get("ai"):
                continue
            fields = dict(self.fields_of(p["id"]))
            for key in autos:
                did = self._tend_field(p, key, fields.get(key, []))
                if did:
                    self.log(f"Driftslederen på {self.fname(p, key)}: " + ", ".join(did) + ".", p["id"], "info")

    def act_cancel(self, pid, jid):
        p = self.players.get(pid)
        if not p:
            return
        before = len(p["jobs"])
        p["jobs"] = [j for j in p["jobs"] if j["id"] != jid]
        if len(p["jobs"]) != before:
            for tr in self.tractors:
                if tr["j"] == jid:
                    tr["s"], tr["j"], tr["tool"] = "idle", None, None
            self.log("Opgaven er stoppet.", pid, "info")

    def prestige(self, p):
        bp_ = sum(BUILDINGS[k].get("prestige", 0) for k, n in self.stats(p["id"])["b"].items() if k in BUILDINGS and n)
        return max(0, HOUSE_DESIGNS[house_design(p)]["prestige"] + sum(ADDONS[a]["prestige"] for a in p.get("addons", []))
                   + self.lawn_prestige(p) + bp_)

    @staticmethod
    def lawn_prestige(p):
        """Græsplænen: pænt slået (mindst 4 felter) = +1, forvokset = -1."""
        n, avg = p.get("lawn") or (0, 0.0)
        if n < 4:
            return 0
        return 1 if avg < 0.45 else -1 if avg > 0.8 else 0

    def garage_doors(self, p):
        """[(feltet foran porten, garagens ankerfelt, nøgle)] – én pr. port, der kan køres ind ad."""
        out = []
        bpos = self.stats(p["id"])["bpos"]
        for key in ("garage", "dobbeltgarage"):
            flip = bool(p.get("aflip", {}).get(key))
            n = ADDONS[key]["size"][0]
            for ax, ay in bpos.get("ext:" + key, []):
                for i in range(n):
                    fx, fy = (ax + 1, ay + i) if flip else (ax + i, ay + 1)   # porten vender mod +y (drejet: +x)
                    if self.inb(fx, fy) and not self._blocked(fx, fy):
                        out.append(((fx, fy), (ax, ay), key))
        return out

    def _car_ids(self, pid):
        return sorted(t["id"] for t in self.tractors if t["o"] == pid and vkind(t["k"]) == "car")

    def car_garage(self, tr):
        """Holder bilen parkeret inde i sin garage? → (anker, nøgle) eller None."""
        if vkind(tr["k"]) != "car" or tr.get("s") != "parked" or tr["o"] not in self.players:
            return None
        cars = self._car_ids(tr["o"])
        doors = self.garage_doors(self.players[tr["o"]])
        idx = cars.index(tr["id"]) if tr["id"] in cars else 99
        if idx < len(doors) and (int(round(tr["x"])), int(round(tr["y"]))) == doors[idx][0]:
            return doors[idx][1], doors[idx][2]
        return None

    def car_spot(self, p, tr=None):
        """Hvor bilen holder: i garagen (foran hver sin port) – ellers et frit felt ved stuehuset."""
        pid = p["id"]
        cars = self._car_ids(pid)
        idx = cars.index(tr["id"]) if tr is not None and tr["id"] in cars else len(cars)
        cands = [d[0] for d in self.garage_doors(p)]
        hx, hy = p["home"]
        for dx, dy in ((0, 1), (-1, 1), (1, 1), (-1, 0), (0, -1)):
            x, y = hx + dx, hy + dy
            if self.inb(x, y) and not self._blocked(x, y) and (x, y) not in cands:
                cands.append((x, y))
        return cands[idx % len(cands)] if cands else (hx, hy + 1)

    def _addon_spot(self, p, w, h):
        hx, hy = p["home"]
        best = None
        for y in range(hy - 5, hy + 6):
            for x in range(hx - 5, hx + 6):
                ok = all(self.inb(xx, yy) and self.tiles[yy][xx].o == p["id"] and not self.tiles[yy][xx].b and
                         not self.tiles[yy][xx].crop and self.tiles[yy][xx].t in ("grass", "field", "stub")
                         for yy in range(y, y + h) for xx in range(x, x + w))
                if ok:
                    d = abs(x - hx) + abs(y - hy)
                    if best is None or d < best[0]:
                        best = (d, x, y)
        return best[1:] if best else None

    def house_tiles(self, pid):
        return [(x, y) for y in range(self.H) for x in range(self.W)
                if self.tiles[y][x].b == "gaard" and self.tiles[y][x].o == pid]

    def _free_area(self, pid, x0, y0, w, h, allow_house=False):
        """Er w×h felter fra (x0, y0) din egen, ledige jord (græs eller tom mark)?"""
        for y in range(y0, y0 + h):
            for x in range(x0, x0 + w):
                if not self.inb(x, y):
                    return False
                t = self.tiles[y][x]
                if t.o != pid:
                    return False
                if allow_house and t.b == "gaard":
                    continue
                if t.b or t.crop or t.t not in ("grass", "field", "stub", "gravel", "fliser"):
                    return False
        return True

    def act_house(self, pid, design=None, x=None, y=None, rot=False):
        """Byg stuehuset om til et andet design – og stil det, hvor du vil på din jord."""
        p = self.players.get(pid)
        if not p:
            return
        cur = house_design(p)
        if design is None:                                # ældre klienter: næste trin samme sted
            i = HOUSE_ORDER.index(cur) if cur in HOUSE_ORDER else 2
            if i >= len(HOUSE_ORDER) - 1:
                return
            design = HOUSE_ORDER[i + 1]
        if design not in HOUSE_DESIGNS or design == cur:
            return
        d = HOUSE_DESIGNS[design]
        w, h = d["size"]
        if rot and w != h:                                # aflang gård drejet: bredde og dybde bytter plads
            w, h = h, w
        if x is None:
            x, y = p["home"]
            x, y = x - w // 2, y - (h - 1)
        if not self._free_area(pid, x, y, w, h, allow_house=True):
            self.log(f"{d['navn']} fylder {w}×{h} felter og skal stå på ledig jord (græs, grus eller tom mark) "
                     "på din egen gård.", pid, "err")
            return
        if p["money"] < d["cost"]:
            self.log(f"{d['navn']} koster {kr(d['cost'])}.", pid, "err")
            return
        p["money"] -= d["cost"]
        self.book(p, "stuehus", -d["cost"])
        for hx, hy in self.house_tiles(pid):              # det gamle hus rives ned – der bliver gårdsplads
            t = self.tiles[hy][hx]
            t.b, t.ba, t.t = None, None, "gravel"
            self.touch(hx, hy)
        self._place(x, y, w, h, "gaard")
        p["hd"], p["hflip"] = design, bool(rot)
        p["house"] = HOUSE_ORDER.index(design) if design in HOUSE_ORDER else 1
        p["home"] = [x + w // 2, y + h - 1]
        self.log(f"Du har bygget {d['navn'].lower()} (-{kr(d['cost'])}). Det gamle stuehus er revet ned.", pid, "good")

    def act_addon(self, pid, key, x=None, y=None, rot=False):
        p = self.players.get(pid)
        if not p or key not in ADDONS or key in p["addons"]:
            return
        a = dict(ADDONS[key])
        if rot:                                           # drejet: bredde og dybde bytter plads
            a["size"] = a["size"][::-1]
        if p["money"] < a["cost"]:
            self.log(f"{a['navn']} koster {kr(a['cost'])}.", pid, "err")
            return
        if x is not None:                                 # du har selv valgt, hvor den skal stå
            spot = (x, y) if self._free_area(pid, x, y, *a["size"]) else None
            if spot is None:
                self.log(f"{a['navn']} fylder {a['size'][0]}×{a['size'][1]} felter og skal stå på ledig jord på din "
                         "egen gård.", pid, "err")
                return
        else:
            spot = self._addon_spot(p, *a["size"])
        if spot is None:
            self.log(f"Der er ikke {a['size'][0]}×{a['size'][1]} ledige felter græs tæt ved stuehuset. "
                     "Ryd lidt plads eller køb jord.", pid, "err")
            return
        p["money"] -= a["cost"]
        self.book(p, "stuehus", -a["cost"])
        p["addons"].append(key)
        p.setdefault("aflip", {})[key] = bool(rot)
        self._place(spot[0], spot[1], a["size"][0], a["size"][1], "ext:" + key)
        self.log(f"{a['navn']} er bygget ved stuehuset (-{kr(a['cost'])}).", pid, "good")

    def guide_active(self, p):
        g = p.get("guide")
        return bool(g) and not g.get("off") and g.get("i", 0) < len(guide_steps())

    def _guide_check(self):
        """Tjek de guidede opgaver: klarede trin giver et lille tilskud, og næste trin vises."""
        for p in self.players.values():
            if not self.guide_active(p):
                continue
            steps = guide_steps(self.manual_mode())
            g = p["guide"]
            while g["i"] < len(steps):
                key, title, text, tool, check = steps[g["i"]]
                if check is None or not check(self, p):
                    break
                self._guide_done(p, steps)

    def _guide_done(self, p, steps):
        g = p["guide"]
        title = steps[g["i"]][1]
        g["i"] += 1
        p["money"] += GUIDE_REWARD
        self.book(p, "praemie", GUIDE_REWARD)
        if g["i"] >= len(steps):
            p["money"] += GUIDE_FINAL
            self.book(p, "praemie", GUIDE_FINAL)
            self.log(f"Vejledningen er gennemført – tillykke med dit første år! Landboforeningen giver et "
                     f"tilskud på {kr(GUIDE_REWARD + GUIDE_FINAL)}.", p["id"], "big")
        else:
            self.log(f"Klaret: {title} (+{kr(GUIDE_REWARD)} fra landboforeningen). Næste: {steps[g['i']][1]}.",
                     p["id"], "good")

    def act_guide(self, pid, op):
        p = self.players.get(pid)
        if p and op == "on" and not p.get("guide"):
            p["guide"] = {"i": 0}                   # valgte "uden vejledning" – men vil gerne have den alligevel
        if not p or not p.get("guide"):
            return
        steps = guide_steps(self.manual_mode())
        g = p["guide"]
        if op == "next" and g["i"] < len(steps) and steps[g["i"]][4] is None:
            self._guide_done(p, steps)
        elif op == "skip" and g["i"] < len(steps):
            g["i"] += 1
            if g["i"] < len(steps):
                self.log(f"Trinnet er sprunget over. Næste: {steps[g['i']][1]}.", pid, "info")
        elif op == "off":
            g["off"] = True
            self.log("Vejledningen er slået fra. Hjælpen findes stadig under F1.", pid, "info")
        elif op == "on":
            g["off"] = False
            if g["i"] < len(steps):
                self.log(f"Vejledningen er slået til. Næste: {steps[g['i']][1]}.", pid, "info")
        self._guide_check()

    def act_manager(self, pid, on):
        p = self.players.get(pid)
        if not p or p["manager"] == on:
            return
        p["manager"] = on
        if on:
            self.log(f"Du har ansat en driftsleder for {kr(MANAGER_WAGE)} om måneden. Se fanen Råd.", pid, "good")
            for tip in self.advice(p)[:2]:
                self.log("Driftslederen: " + tip[1], pid, "chat")
        else:
            n = 0
            for plan in (p.get("fplan") or {}).values():
                if plan.get("auto"):
                    plan["auto"] = False
                    n += 1
            self.log("Driftslederen er afskediget – lønnen stopper fra nu." +
                     (f" De {n} marker, han passede, skal du nu selv passe." if n > 1 else
                      " Marken, han passede, skal du nu selv passe." if n else ""), pid, "info")

    def advice(self, p):
        """Driftslederens råd: [(vigtighed 0-3, tekst)] ud fra gårdens tilstand lige nu."""
        pid, m, out = p["id"], self.month(), []
        st = self.stats(pid)
        crops = st["crops"]
        ripe = sum(v[1] for v in crops.values())
        pests = sum(v[3] for v in crops.values())
        dead = sum(v[2] for v in crops.values())
        dry = sum(1 for row in self.tiles for t in row if t.o == pid and t.crop and not t.dead and t.m < 25)
        queued = {j["tool"] for j in p["jobs"]}
        if pests and "spray" not in queued:
            out.append((3, f"Der er skadedyr på {pests} felter. Sprøjt dem nu, før de spreder sig."))
        if ripe and "harvest" not in queued:
            out.append((3, f"{ripe} felter er modne. Høst dem inden ca. 1½ måned, ellers falder udbyttet."))
        if dry >= 5:
            out.append((2, f"{dry} felter med afgrøder er meget tørre. Grav en grøft fra en sø eller brønd."))
        if dead:
            out.append((1, f"{dead} felter er visnet. Ryd dem med Høst eller Pløj, så jorden kan bruges igen."))
        if p["hungry"]:
            out.append((3, "Dyrene sulter! Køb majs eller hvede på markedet, eller sælg nogle dyr."))
        if p["money"] < 0:
            out.append((3, "Du er i minus. Sælg fra lageret, eller tag et lån i banken."))
        worn = [v for v in (self.tractor_meta() if self.tractors else self.tractor_view)
                if v[1] == pid and len(v) > 12 and v[12] >= 40]
        if worn and self.opts.get("wear", True):
            out.append((1, f"{len(worn)} maskine{'r' if len(worn) > 1 else ''} er godt slidt og går oftere i stykker. "
                           f"Værkstedet servicerer dem, når de holder hjemme – eller højreklik og vælg Service."))
        cap, stored = self.storage_cap(p), self.stored(p)
        if stored > cap * 0.8:
            out.append((2, f"Kornlageret er næsten fuldt ({int(stored)}/{cap}). Sælg noget eller byg en silo."))
        stub = sum(1 for row in self.tiles for t in row if t.o == pid and t.t == "stub")
        if stub >= 6 and "plow" not in queued:
            out.append((2, f"{stub} felter står med stub efter høsten. Pløj dem, så de kan sås igen."))
        fallow = sum(1 for row in self.tiles for t in row if t.o == pid and t.t == "field" and not t.crop)
        sowable = [CROPS[c]["navn"].lower() for c in CROPS if m in CROPS[c]["months"] and crop_good(c)]
        if fallow >= 6 and sowable and "sow" not in queued:
            best = max((c for c in CROPS if m in CROPS[c]["months"] and crop_good(c)),
                       key=lambda c: CROPS[c]["udbytte"] * self.market[crop_good(c)]["p"] - CROPS[c]["seed"])
            out.append((2, f"{fallow} pløjede felter ligger tomme. Nu er det såtid for {', '.join(sowable)}"
                           f" – {CROPS[best]['navn'].lower()} giver mest lige nu."))
        for g, info in GOODS.items():
            have = p["inv"][g]
            if have >= 50 and self.market[g]["p"] > info["base"] * 1.15:
                out.append((2, f"{info['navn']} sælges {int((self.market[g]['p'] / info['base'] - 1) * 100)}% over "
                               f"normalpris. Godt tidspunkt at sælge dine {int(have)}."))
            elif have >= 50 and self.market[g]["p"] < info["base"] * 0.8:
                out.append((1, f"Prisen på {info['navn'].lower()} er lav. Vent med at sælge, hvis lageret kan."))
        sour = sum(1 for row in self.tiles for t in row if t.o == pid and t.t in ("field", "stub") and t.kc < 50)
        if sour >= 5 and "lime" not in queued:
            out.append((1 if m not in (7, 8, 9, 10) else 2,
                        f"{sour} felter er ved at blive sure (kalk under 50%). Kalk dem – bedst om efteråret."))
        poor = weedy = same = 0
        for yy, row in enumerate(self.tiles):
            for xx, t in enumerate(row):
                if t.o != pid or t.t != "field" or (xx, yy) in self.ctiles:
                    continue
                poor += t.n < 35
                weedy += t.wd >= 40 and bool(t.crop)
                same += bool(t.crop) and t.crop == t.lc and t.crop != "graes"
        if poor >= 4:
            out.append((2, f"{poor} marker er udpinte (under 35% næring). Gød dem – gyllen fra staldene er gratis."))
        if weedy >= 4:
            out.append((2, f"Ukrudtet har taget over på {weedy} marker. Sprøjt dem, ellers taber du op til halvdelen "
                           "af høsten."))
        if same >= 6:
            out.append((1, f"{same} marker har samme afgrøde som sidste år. Skift afgrøde (sædskifte) – det giver "
                           "8% mere i stedet for 15% mindre."))
        if p.get("gylle", 0) >= 200:
            out.append((1, f"Du har {int(p['gylle'])} gylle. Kør den ud med Gød – det sparer kunstgødning."))
        if p["cows"] and not p.get("mix") and p["inv"].get("graes", 0) < 5:
            out.append((1, "Køerne giver 20% mere mælk med blandet foder. Så kløvergræs og lav ensilage."))
        if (p["cows"] or p["pigs"]) and not p.get("straw_ok"):
            out.append((1, "Med halm som strøelse trives dyrene og yder 15% mere. Køb en ballepresser."))
        if p.get("fbreak"):
            out.append((2, "Der er hul i hegnet om folden efter stormen – dyrene kan smutte ud. Lap det fra en ATV, UTV "
                           f"eller terrænbil (O), eller klik på hullet med Fold og hegn ({kr(FENCE_FIX_COST)})."))
        if p.get("birth"):
            b_ = p["birth"]
            out.append((2, f"{ANIMAL_ONE[b_['k']].capitalize()} er ved at {BIRTH_WORD[b_['k']][1]} i folden – kør derud "
                           f"(Styr selv) inden for {int(b_['d'])} dage, så får du {BIRTH_WORD[b_['k']][2]} mere."))
        has_mucker = any(VEHICLES.get(t, {}).get("style") in MUCK_STYLES for _, t in self.vehicles_of(pid))
        if has_mucker and any(p.get(k, 0) for k in ANIMALS) and not p.get("muck"):
            out.append((0, f"Mug staldene ud med gummigeden eller minilæsseren: hold ved stalddøren og tryk E – dyrene "
                           f"yder {int(MUCK_BONUS * 100)}% mere i {MUCK_DAYS} dage."))
        if any(p.get(k, 0) for k in GRAZERS) and self.fold_bonus(p) < FOLD_BALE_BONUS - 1e-6 and \
                self.bales_total(p) + p["inv"].get("halm", 0) + p["inv"].get("wrap", 0) >= 1:
            out.append((0, f"Kør en halm- eller wrapballe ud i folden med en læsser (E i folden): dyrene yder "
                           f"{int(FOLD_BALE_BONUS * 100)}% mere i {FOLD_BALE_DAYS} dage. Én balle rækker til "
                           f"{FOLD_BALE_COVER} køer eller heste ({FOLD_BALE_COVER * 3} får)."))
        open_c = [c for c in self.contracts if c["pid"] is None]
        if open_c and p["money"] < 15000:
            best = max(open_c, key=lambda c: c["reward"])
            out.append((2, f"Pengene er små. {best['who']} betaler {kr(best['reward'])} for en opgave – se fanen "
                           "Opgaver."))
        pile = self.pile_total(p)
        if pile >= 100 and not self.haulers(pid, "grain"):
            out.append((2, f"{int(pile)} enheder høst ligger i marken, og vognmanden tager betaling pr. læs. "
                           "En tipvogn til 5.000 kr gør arbejdet selv."))
        elif pile >= 600:
            out.append((2, f"{int(pile)} enheder høst venter i marken. Flere vogne eller en kornbil får den "
                           "hurtigere i hus, før regnen tager den."))
        if any(d["rent"] for d in p.get("deliv", [])) and p["money"] > 10000:
            out.append((1, "Vognmanden kører dine dyr. En kreaturvogn sparer ventetid og gebyrer."))
        missing = [t for t in RENT if t not in ("harvest", "lime") and not self.owns_tool(p, t)]   # kalk = gødningsspreder
        if not any(vkind(k) == "combine" for _, k in self.vehicles_of(pid)) and p["money"] > 30000 and st["tiles"] > 200:
            out.append((1, f"Maskinstationen tager {self.hire_harvest()} kr pr. felt for at høste. Med mange marker "
                           "tjener en brugt mejetærsker sig hjem."))
        outside = [t for t in (self.tractor_meta() if self.tractors else self.tractor_view)
                   if t[1] == pid and len(t) > 13 and t[13] == 2]
        if outside:
            out.append((2, f"{len(outside)} maskine{'r' if len(outside) > 1 else ''} står udenfor og slides af vind og "
                           "vejr. Byg et maskinhus mere."))
        for key, off in self.offers.items():
            if off["until"] >= self.day and p["money"] > 5000:
                have = p.get("forraad", 0) if key == "saasaed" else p.get("inputs", {}).get(key, 0)
                if have < (2000 if key == "saasaed" else 50):
                    out.append((2, f"Tilbud på {INPUTS[key]['navn'].lower()} ({int(off['pct'] * 100)}% billigere i "
                                   f"{off['until'] - self.day} dage). Køb ind under Marked › Indkøb."))
        if missing and p["money"] > 20000:
            names = {"plow": "en plov", "sow": "en såmaskine", "spray": "en marksprøjte",
                     "fertilize": "en gødningsspreder"}
            out.append((1, f"Du lejer stadig udstyr. Køb {names.get(missing[0], 'eget udstyr')} – det tjener sig hjem "
                           "på et par sæsoner."))
        if self.n_vehicles(pid) - sum(1 for _, k in self.vehicles_of(pid) if vkind(k) == "car") < 2 \
                and st["tiles"] > 250 and p["money"] > 20000:
            out.append((1, "Gården er vokset. En traktor mere får markarbejdet gjort i tide."))
        if not any(g for g in st["b"] if g in BUILDINGS and BUILDINGS[g]["group"] == "broend") and \
                not self.wet_ditches() and m in (3, 4, 5):
            out.append((1, "Sommeren kommer. Uden grøfter kan en tørke koste hele høsten."))
        if p["loan"] > 0 and p["money"] > min(l_["amt"] for l_ in self.loans(p)) + 15000:
            out.append((1, "Du har penge nok til at indfri et lån i banken og spare renter."))
        wet = sum((p.get("wetg") or {}).values())
        if wet >= 20:
            out.append((2 if not self.capacity(p, "korntoerreri") else 0,
                        f"{int(wet)} enheder korn er vådt. " + ("Korntørreriet tørrer det." if self.capacity(
                            p, "korntoerreri") else "Sælg det snart, eller byg et korntørreri – ellers mugner det.")))
        if dry >= 5 and not self.owns_tool(p, "water") and p["money"] > 9000:
            out.append((1, "Et vandingsanlæg kan vande de tørre marker, hvis der er vand inden for 8 felter."))
        if self.snow >= 0.3 and not self.owns_tool(p, "snow") and \
                not any(plow_on(t) for t in self.tractors if t["o"] == pid):
            out.append((1, f"Der ligger sne. Med en sneplov kan du tjene {SNOW_PAY} kr pr. vejfelt for kommunen."))
        eg = egn_of(self)
        if eg["wind"] >= 1.3 and p["money"] - p["loan"] > 40000 and not st["bpos"].get("vindmoelle"):
            out.append((1, "Egnen er blæsende – en vindmølle tjener sig hurtigt hjem her."))
        if p.get("manager") and not any(v.get("auto") for v in (p.get("fplan") or {}).values()) and \
                len(self.fields_of(pid)) >= 2:
            out.append((0, "Jeg kan passe markerne for dig: højreklik på en mark › Lad driftslederen passe marken."))
        if self.month() in (1, 2, 6, 7):
            rows = self.budget(p, 6)
            money, low, lowm = p["money"], p["money"], None
            for r in rows:
                money += sum(r["inc"].values()) - sum(r["out"].values())
                if money < low:
                    low, lowm = money, r
            if lowm and low < 0:
                out.append((2, f"Budgettet (F6) viser, at pengene slipper op i {MONTHS[lowm['m']]}. Hold igen med "
                               "at investere, eller lån i tide."))
        if not out:
            out.append((0, "Alt ser fint ud på gården. Fortsæt det gode arbejde!"))
        out.sort(key=lambda a: -a[0])
        return out

    def act_equip(self, pid, key):
        p = self.players.get(pid)
        if not p or key not in EQUIPMENT:
            return
        e = EQUIPMENT[key]
        if key in p["equip"]:
            self.log(f"Du har allerede {e['navn'].lower()}.", pid, "err")
            return
        if p["money"] < e["price"]:
            self.log(f"Ikke nok penge til {e['navn'].lower()}.", pid, "err")
            return
        p["money"] -= e["price"]
        self.book(p, "maskiner", -e["price"])
        p["equip"].append(key)
        if e.get("shape"):                       # den nye presser bruges fra nu af
            p["bshape_pref"] = e["shape"]
        self._sync_park(p, True)
        where = self.item_where(p, f"e:{key}")
        self.log(f"Du købte {e['navn'].lower()} (-{kr(e['price'])})." +
                 (" Den står udenfor – der er ingen ledig bås i maskinhusene." if where and where[0] == "ground"
                  else ""), pid, "good")

    def act_vehicle(self, pid, kind=None, shed=None, sell=None):
        p = self.players.get(pid)
        if not p:
            return
        if sell is not None:
            tr = next((t for t in self.tractors if t["o"] == pid and t["id"] == int(sell)), None)
            if tr and any(r["item"] == f"v{tr['id']}" and r["renter"] == pid for r in self.rentals):
                self.log("Den er lejet – den kan ikke sælges. Aflever den under Handel › Udlejning.", pid, "err")
                return
            if tr:
                self._haul_abort(tr)
                self.tractors.remove(tr)
                v = VEHICLES[tr["k"]]
                val = v["price"] * (0.7 if self.show_open() else 0.6) + \
                    sum(upg_price(u, tr["k"]) * 0.5 for u in tr.get("upg", [])) + \
                    sum(upg_price(u, tr["k"]) for u in tr.get("upg_wait", []))
                p["money"] += val
                self.book(p, "maskiner", val)
                if tr.get("hitch"):                     # det påkoblede bliver stående, hvor traktoren var
                    p.setdefault("gear_pos", {})[tr["hitch"]] = [int(round(tr["x"])), int(round(tr["y"]))]
                self.log(f"Du solgte din {vname(tr['k'])} (+{kr(val)}).", pid, "info")
                self._sync_park(p, True)
            return
        if kind not in VEHICLES or VEHICLES[kind].get("hidden"):
            return
        v = VEHICLES[kind]
        if self.year() < v["year"] and not self.sandbox():
            self.log(f"{vname(kind)} kommer først på markedet i år {v['year']}.", pid, "err")
            return
        if v["kind"] == "car":
            return self._buy_car(p, kind)
        self._sync_park(p, True)
        size = 2 if v["kind"] in ("truck", "combine") else 1
        bays = self.shed_bays(pid)
        if shed is not None:
            shed = tuple(shed)
            k = self.shed_key(shed)
            if k not in bays:
                return
            if self._free_bay(p["park"][k], bays[k], size) is None:
                self.log("Der er ikke plads i dette maskinhus.", pid, "err")
                return
        price = v["price"] * (0.9 if self.show_open() else 1.0)
        if p["money"] < price:
            self.log(f"Ikke nok penge til en {vname(kind)}.", pid, "err")
            return
        p["money"] -= price
        self.book(p, "maskiner", -price)
        outside = bool(self._spawn_vehicle(pid, kind, shed).get("out"))
        self.log(f"Du købte en ny {vname(kind)} (-{kr(price)})" + (" med 10% messerabat." if self.show_open() else ".") +
                 (" Der er ikke plads i maskinhusene, så den står udenfor ved stuehuset og slides af vejret."
                  if outside else ""), pid, "warn" if outside else "good")

    @staticmethod
    def car_slots(p):
        """Hvor mange biler der er plads til: 1 i garagen, 2 i dobbeltgaragen."""
        a = p.get("addons", [])
        return (1 if "garage" in a else 0) + (2 if "dobbeltgarage" in a else 0)

    def _buy_car(self, p, kind):
        pid = p["id"]
        slots = self.car_slots(p)
        if not slots:
            self.log("Byg en garage eller dobbeltgarage ved stuehuset først (højreklik på stuehuset).", pid, "err")
            return
        if sum(1 for _, k in self.vehicles_of(pid) if vkind(k) == "car") >= slots:
            self.log("Der er ikke plads til flere biler – byg en garage mere (højreklik på stuehuset).", pid, "err")
            return
        if p["money"] < VEHICLES[kind]["price"]:
            self.log("Ikke nok penge.", pid, "err")
            return
        p["money"] -= VEHICLES[kind]["price"]
        self.book(p, "maskiner", -VEHICLES[kind]["price"])
        self._spawn_vehicle(pid, kind, self.car_spot(p))
        self.log(f"Du købte en {vname(kind)}. Højreklik på bilen og vælg Styr selv for at køre en tur.",
                 pid, "good")

    def _fix_capacity(self, p):
        for kind, a in ANIMALS.items():
            cap = self.animal_cap(p, kind)
            if p[kind] > cap:
                n = p[kind] - cap
                p[kind] = cap
                p["money"] += n * a[1] * 0.6
                self.book(p, "dyr", n * a[1] * 0.6)
                self._acc(p, "aacc", kind, sold=n * a[1] * 0.6)
                self.log(f"Solgte {n} {a[3]} – der var ikke plads til dem.", p["id"], "warn")
        self._sync_park(p)


    # ── regnskab ─────────────────────────────────────────────────────────────
    @staticmethod
    def new_book(money, loan):
        return {"cats": {}, "harv": {}, "prod": {}, "m0": round(money, 2), "l0": loan}

    def book(self, p, cat, amt):
        """Bogfør en indtægt (+) eller udgift (-) til årsrapporten."""
        if not p or not amt:
            return
        c = p.setdefault("yr", self.new_book(p["money"], p["loan"]))["cats"]
        c[cat] = round(c.get(cat, 0.0) + amt, 2)
        mi = self.day // DAYS_PER_MONTH                  # måned for måned (til Udgifter-siden): denne og sidste
        mb = p.get("mb")
        if not mb or mb.get("m") != mi:
            prev = mb["cur"] if mb and mb.get("m") == mi - 1 else {}
            mb = p["mb"] = {"m": mi, "cur": {}, "prev": prev}
        mb["cur"][cat] = round(mb["cur"].get(cat, 0.0) + amt, 2)

    def diesel_price(self):
        return DIESEL_BASE * self.diesel

    def _burn(self, tr, liters):
        """Maskinen bruger diesel fra sin egen tank. Løber en maskine, der kører selv, tør, kommer tankbilen."""
        p = self.players.get(tr["o"])
        if not p or liters <= 0 or tr.get("hire"):
            return
        liters *= fuel_factor(tr["k"]) * (1.1 if "tuning" in tr.get("upg", ()) else 1.0)
        tr["fuel"] = max(0.0, tr.get("fuel", fuel_cap(tr["k"], tr)) - liters)
        p["fuel_l"] = p.get("fuel_l", 0.0) + liters
        self._macc(tr, diesel=liters * self.diesel_price())
        if tr["fuel"] <= 0 and tr["s"] != "manual":
            self._rescue(tr, p)

    def refuel(self, tr, p, liters, how):
        """Fyld maskinens tank: how = 'tank' (gårdens dieseltank, allerede betalt) eller 'buy' (købes nu)."""
        cap = fuel_cap(tr["k"], tr)
        need = min(liters, cap - tr.get("fuel", cap))
        if need <= 0:
            return 0.0, 0.0
        if how == "tank":
            take = min(need, p.get("tank_l", 0.0))
            cost = take * p.get("tank_pris", self.diesel_price())
            p["tank_l"] = p.get("tank_l", 0.0) - take
        else:
            price = self.diesel_price() * (FUEL_TOWN_MARKUP if how == "town" else 1.0)
            take = need
            cost = take * price
            p["money"] -= cost
            self.book(p, "diesel", -cost)
        tr["fuel"] = tr.get("fuel", cap) + take
        p["fuel_kr"] = p.get("fuel_kr", 0.0) + cost
        return take, cost

    def _home_refuel(self, tr, p):
        """Maskiner, der kører selv, tanker op derhjemme: fra gårdens dieseltank, ellers fra tankbilen."""
        cap = fuel_cap(tr["k"], tr)
        if tr.get("fuel", cap) >= cap * 0.6:
            return
        if self.capacity(p, "dieseltank") and p.get("tank_l", 0) >= 1:
            self.refuel(tr, p, cap, "tank")
        if tr.get("fuel", cap) < cap * 0.6:
            self.refuel(tr, p, cap, "buy")

    def _rescue(self, tr, p):
        """Tør for diesel ude på marken eller vejen: tankbilen rykker ud (dyrt)."""
        cap = fuel_cap(tr["k"], tr)
        _, cost = self.refuel(tr, p, cap * 0.4, "buy")
        p["money"] -= FUEL_RESCUE_FEE
        self.book(p, "diesel", -FUEL_RESCUE_FEE)
        self.log(f"{vname(tr['k'])} #{tr['id']} løb tør for diesel! Tankbilen rykkede ud med en nødtankning "
                 f"(-{kr(cost + FUEL_RESCUE_FEE)}). Tank op hjemme ved dieseltanken for at undgå det.", tr["o"], "warn")
        if tr["s"] != "manual":
            tr.update(s="repair", w=0.2, path=None, tool=None, j=None)

    def act_fuelhelp(self, pid, vid, drv=None):
        tr = self._veh(pid, vid)
        p = self.players.get(pid)
        if not self._mine(tr, drv) or not p:
            return
        if tr.get("fuel", 1) > fuel_cap(tr["k"], tr) * 0.05:
            self.log("Der er stadig diesel på – kør hen til dieseltanken eller grovvarehandlens pumpe.", pid, "info")
            return
        self._rescue(tr, p)

    def act_diesel(self, pid, liters):
        """Tankbilen fylder gårdens dieseltank – med lidt rabat. Bedst, når dieselprisen er lav."""
        p = self.players.get(pid)
        if not p:
            return
        cap = self.capacity(p, "dieseltank")
        if not cap:
            self.log("Byg en dieseltank først (Byg og køb › Bygninger).", pid, "err")
            return
        room = cap - p.get("tank_l", 0.0)
        liters = min(int(liters), int(room))
        price = self.diesel_price() * TANK_DISCOUNT
        liters = min(liters, int(max(0, p["money"]) // price))
        if liters < 1:
            self.log("Tanken er fuld." if room < 1 else "Ikke nok penge til diesel.", pid, "err")
            return
        old = p.get("tank_l", 0.0)
        p["tank_pris"] = (old * p.get("tank_pris", price) + liters * price) / (old + liters)
        p["tank_l"] = old + liters
        cost = liters * price
        p["money"] -= cost
        self.book(p, "diesel", -cost)
        self.log(f"Tankbilen fyldte {liters:,} liter diesel på tanken til {fmt_price(price)}/l (-{kr(cost)})."
                 .replace(",", "."), pid, "good")

    def act_upgrade(self, pid, vid, key):
        tr = self._veh(pid, vid)
        p = self.players.get(pid)
        if not tr or not p or key not in UPGRADES or tr.get("hire"):
            return
        u = dict(UPGRADES[key], price=upg_price(key, tr["k"]))
        if not upg_fits(key, tr["k"]):
            return
        upg, wait = tr.setdefault("upg", []), tr.setdefault("upg_wait", [])
        if key in upg or key in wait:
            return
        if not self.workshop_spot(pid):
            self.log("Opgraderinger monteres i dit eget værksted – byg et værksted først (Byg og køb › Bygninger).",
                     pid, "err")
            return
        if p["money"] < u["price"]:
            self.log(f"Ikke nok penge til {u['navn'].lower()}.", pid, "err")
            return
        p["money"] -= u["price"]
        self.book(p, "maskiner", -u["price"])
        wait.append(key)
        if tr["s"] == "manual":
            where = "Kør selv hen til værkstedet og hold stille – så bliver den monteret."
        elif tr["s"] in ("idle", "parked", "move") and not tr.get("haul"):
            where = "Maskinen kører hen til værkstedet nu."
        else:
            where = "Maskinen kører til værkstedet, når den er færdig med det, den er i gang med."
        self.log(f"Købt {u['navn'].lower()} til {vname(tr['k'])} #{vid} (-{kr(u['price'])}). {where}", pid, "info")

    def workshop_spot(self, pid):
        """Feltet foran porten på spillerens værksted (hvor maskinerne holder, mens der skrues)."""
        for pos in self.stats(pid)["bpos"].get("vaerksted", []):
            d = self.bdoor(*pos)
            if d:
                return list(d[0])
        return None

    def near_workshop(self, tr):
        sp = self.workshop_spot(tr["o"])
        return bool(sp) and max(abs(tr["x"] - sp[0]), abs(tr["y"] - sp[1])) <= 1.3

    def _fit_upgrades(self, tr):
        """Værkstedet monterer de købte opgraderinger."""
        wait = tr.get("upg_wait") or []
        if not wait:
            return
        upg = tr.setdefault("upg", [])
        names = []
        for k in wait:
            if k not in upg:
                upg.append(k)
                self._svclog(tr, f"Monteret: {UPGRADES[k]['navn'].lower()}", upg_price(k, tr["k"]))
                names.append(UPGRADES[k]["navn"].lower())
                if k == "sneplov":                         # det nye sidder på; på traktoren må læsseren vige
                    tr["plow_off"] = False
                    if vkind(tr["k"]) == "tractor" and "frontlaesser" in upg:
                        self.log("Sneploven sidder nu foran i stedet for frontlæsseren. Højreklik på traktoren › "
                                 "Opgrader for at skifte tilbage.", tr["o"], "info")
                elif k == "frontlaesser" and vkind(tr["k"]) == "tractor" and "sneplov" in upg:
                    tr["plow_off"] = True
        tr["upg_wait"] = []
        if names:
            self.log(f"Værkstedet har monteret {' og '.join(names)} på {vname(tr['k'])} #{tr['id']}.", tr["o"], "good")

    def act_front(self, pid, vid):
        """Af- eller påmonter sneploven (opgraderingen). På traktoren skifter den plads med frontlæsseren."""
        tr = self._veh(pid, vid)
        if not tr or tr["o"] != pid or "sneplov" not in tr.get("upg", ()):
            return
        m = tr.get("man") or {}
        if m.get("fl"):
            self.log("Sæt ballerne fra dig, før frontlæsseren tages af.", pid, "err")
            return
        if tr.get("s") == "work" and tr.get("tool") == "snow":
            self.log("Maskinen er i gang med at rydde sne – vent, til den er færdig.", pid, "err")
            return
        tr["plow_off"] = not tr.get("plow_off")
        other = " – frontlæsseren kan bruges igen" if tr["plow_off"] and "frontlaesser" in tr.get("upg", ()) else \
            " – frontlæsseren er taget af imens" if "frontlaesser" in tr.get("upg", ()) else ""
        self.log(f"Sneploven er {'afmonteret' if tr['plow_off'] else 'monteret'} på {vname(tr['k'])} #{vid}{other}.",
                 pid, "info")

    def act_gps(self, pid, vid, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        m = tr["man"]
        if "gps" not in tr.get("upg", ()):
            self.log("Maskinen har ikke GPS – den kan købes under Opgrader (højreklik på maskinen) og monteres i dit værksted.", pid, "info")
            return
        m["gps"] = not m.get("gps")
        m.update(cruise_off=False, gps_stop=False, gps_side=None, uturn=None)
        self.log("GPS-autostyring er slået til: sænk redskabet, så holder den sporet og farten og vender selv ved "
                 "markkanten. Ned/S bremser." if m["gps"] else "GPS-autostyring er slået fra.", pid, "info")

    def _wear(self, tr, amt):
        if self.opts.get("wear", True) and not tr.get("hire"):
            dirt = 1 + tr.get("dirt", 0.0) / 300              # snavsede maskiner slides mere
            tr["wear"] = min(100.0, tr.get("wear", 0.0) + amt * wear_factor(tr["k"]) * dirt)

    # ── mudder, vask, værksted og servicebog ─────────────────────────────────
    def _svclog(self, tr, text, cost=0):
        if cost:
            self._macc(tr, rep=cost)
        lg = tr.setdefault("log", [])
        lg.append([self.day, text, int(cost)])
        del lg[:-8]

    def _dirty(self, tr, x, y, work):
        """Maskinen bliver beskidt i våde marker – og slæber mudder med ud på landevejen."""
        if tr.get("hire") or not self.inb(x, y):
            return
        t = self.tiles[y][x]
        tr["hours"] = tr.get("hours", 0.0) + (0.1 if work else 0.01)
        wet = self.weather in ("Regn", "Storm", "Sne") or t.m > 72
        if t.t in ("field", "stub", "grass", "pasture", "forest", "ditch"):
            tr["dirt"] = min(100.0, tr.get("dirt", 0.0) + ((2.5 if wet else 0.6) if work else (0.25 if wet else 0.03)))
        elif t.t in ("road", "asphalt") and t.o < 0 and tr.get("dirt", 0) > 50 and self.opts.get("wear", True):
            p = self.players.get(tr["o"])
            if p:
                p["mud"] = p.get("mud", 0) + 1
                if p["mud"] >= 40 and self.day - p.get("mud_fine", -99) > DAYS_PER_MONTH:
                    p["mud"], p["mud_fine"] = 0, self.day
                    fine = 500
                    p["money"] -= fine
                    self.book(p, "boeder", -fine)
                    self.log(f"Kommunen har fået klager over mudder på landevejen fra dine maskiner – bøde "
                             f"{kr(fine)}. Vask dem på vaskepladsen, før de kører ud på vejen.", tr["o"], "err")

    def washer(self, pid):
        b = self.stats(pid)["bpos"].get("vaskeplads")
        return [tuple(v) for v in b] if b else []

    def near_tank(self, tr):
        """Holder maskinen ved en af gårdens dieseltanke?"""
        return any(max(abs(tr["x"] - bx), abs(tr["y"] - by)) <= 1.6
                   for bx, by in self.stats(tr["o"])["bpos"].get("dieseltank", []))

    def near_washer(self, tr):
        return any(max(abs(tr["x"] - wx), abs(tr["y"] - wy)) <= 1.3 for wx, wy in self.washer(tr["o"]))

    def act_wash(self, pid, vid):
        """Medhjælperen vasker maskinen på vaskepladsen (kun hjemme)."""
        tr = self._veh(pid, vid)
        p = self.players.get(pid)
        if not tr or not p or tr.get("dirt", 0) < 1:
            return
        if not self.washer(pid):
            self.log("Byg en vaskeplads først (Byg og køb › Bygninger).", pid, "err")
            return
        if tr["s"] == "manual":
            self.log("Kør selv hen på vaskepladsen og hold stille – så bliver den vasket.", pid, "info")
            return
        self._wash(tr, p)
        self.log(f"{vname(tr['k'])} #{vid} er vasket (-{kr(WASH_COST)}).", pid, "good")

    def _wash(self, tr, p):
        tr["dirt"] = 0.0
        p["money"] -= WASH_COST
        self.book(p, "reparation", -WASH_COST)
        self._svclog(tr, "Vasket", WASH_COST)

    def _auto_wash(self):
        """Maskiner, der kører selv, bliver vasket, når de holder hjemme (hvis der er en vaskeplads)."""
        for tr in self.tractors:
            p = self.players.get(tr["o"])
            if not p or tr.get("hire") or tr["s"] != "parked" or tr.get("dirt", 0) < 30 or not self.washer(tr["o"]) \
                    or not self.auto_on(p, "vask"):
                continue
            if self.manual_mode() and not tr.get("helper"):
                continue
            self._wash(tr, p)

    def workshop(self, p):
        return bool(self.capacity(p, "vaerksted"))

    def act_parts(self, pid, n):
        p = self.players.get(pid)
        if not p or n <= 0:
            return
        n = min(int(n), int(max(0, p["money"]) // PART_PRICE))
        if n <= 0:
            self.log("Ikke nok penge til reservedele.", pid, "err")
            return
        p["money"] -= n * PART_PRICE
        self.book(p, "reparation", -n * PART_PRICE)
        p["parts"] = p.get("parts", 0) + n
        self.log(f"Købte {n} reservedel{'e' if n > 1 else ''} til værkstedet (-{kr(n * PART_PRICE)}).", pid, "good")

    def act_service(self, pid, vid, auto=False):
        p = self.players.get(pid)
        tr = next((t for t in self.tractors if t["o"] == pid and t["id"] == vid), None)
        if not p or not tr or tr.get("wear", 0) < 1:
            return
        cost = service_cost(tr["k"], tr["wear"])
        winter = self.month() in PREORDER_MONTHS
        if winter:
            cost = int(cost * WINTER_SERVICE)
        if self.workshop(p):
            cost = int(cost * 0.6)                     # eget værksted: kun reservedele og olie
        if p["money"] < cost:
            if not auto:
                self.log("Ikke nok penge til service.", pid, "err")
            return
        p["money"] -= cost
        self.book(p, "reparation", -cost)
        self._svclog(tr, f"Service (slid {int(tr['wear'])}%)", cost)
        tr["wear"] = 0.0
        self.log(f"{'Værkstedet har serviceret' if auto else 'Service på'} {vname(tr['k'])} #{tr['id']} "
                 f"(-{kr(cost)}{', vinterpris' if winter else ''}). Den er som ny igen.", pid, "info")

    def _auto_service(self):
        for tr in self.tractors:
            at = WINTER_SERVICE_AT if self.month() in PREORDER_MONTHS else SERVICE_AT
            if tr.get("wear", 0) >= at and tr["s"] == "parked" and self.auto_on(self.players.get(tr["o"]), "service"):
                self.act_service(tr["o"], tr["id"], auto=True)

    def _rec(self, p, kind, key, amt):
        if p and amt:
            d = p.setdefault("yr", self.new_book(p["money"], p["loan"]))[kind]
            d[key] = round(d.get(key, 0.0) + amt, 2)

    @staticmethod
    def year_result(p):
        """Årets tal indtil nu: (kategorier inkl. 'andet', resultat)."""
        yr = p.get("yr") or {"cats": {}, "m0": p["money"], "l0": p["loan"]}
        net = (p["money"] - p["loan"]) - (yr["m0"] - yr["l0"])
        cats = dict(yr["cats"])
        other = net - sum(cats.values())
        if abs(other) >= 1:
            cats["andet"] = cats.get("andet", 0.0) + other
        return cats, net

    def _close_year(self, p):
        for grp in ("cacc", "aacc", "macc", "eacc"):      # regnskab pr. afgrøde/dyr/maskine/energi: seneste 6 år
            d = p.get(grp) or {}
            for old in sorted(d, key=int)[:-6]:
                del d[old]
        ta = p.get("tacc") or {}
        for k in list(ta):                                 # udgifter på felter, der ikke længere er marker
            x, y = (int(v) for v in k.split(","))
            t = self.tiles[y][x]
            if t.o != p["id"] or t.t not in ("field", "stub"):
                del ta[k]
        cats, net = self.year_result(p)
        yr = p.get("yr") or {}
        rep = {"year": self.year() - 1, "cats": {k: round(v) for k, v in cats.items() if abs(v) >= 1},
               "harv": {k: round(v) for k, v in yr.get("harv", {}).items() if v >= 1},
               "prod": {k: round(v) for k, v in yr.get("prod", {}).items() if v >= 1},
               "net": round(net), "worth": round(self.worth(p)), "money": round(p["money"]), "loan": p["loan"],
               "town": self.town.get("lvl", 0), "pop": self.town.get("pop", 0)}
        p["hist"] = (p.get("hist", []) + [rep])[-12:]
        p["yr"] = self.new_book(p["money"], p["loan"])
        self.log(f"Årsrapporten for år {rep['year']} er klar – årets resultat blev {kr(net)}. "
                 f"Se den under Gård › Årsrapport.", p["id"], "big")

    # ── byen ─────────────────────────────────────────────────────────────────
    def town_lvl(self):
        return self.town.get("lvl", 0)

    def depth(self, g):
        return GOODS[g]["depth"] * (1 + TOWN_DEPTH * self.town_lvl())

    def town_pop(self):
        return 150 + sum(HOUSE_POP.get(t.b, 0) for row in self.tiles for t in row if t.b)

    def town_add(self, amt):
        """Handel med byen får den til at vokse."""
        if amt <= 0:
            return
        tw = self.town
        tw["pts"] = tw.get("pts", 0.0) + amt
        while tw["lvl"] + 1 < len(TOWN_LEVELS) and tw["pts"] >= TOWN_LEVELS[tw["lvl"] + 1]["pts"]:
            tw["lvl"] += 1
            lv = TOWN_LEVELS[tw["lvl"]]
            self.log(f"Byen er vokset til en {lv['navn'].lower()}! {lv['info']}", None, "big")
            self.add_news(f"{TOWN_NAME} er blevet {lv['navn'].lower()}", f"Handlen med egnens gårde får byen til at "
                          f"vokse. Nu bor der {self.town.get('pop', 0)} mennesker. {lv['info']}", big=True)
            self._town_landmarks()

    def _town_inner(self, x, y):
        x0, y0, x1, y1 = TOWN
        return x0 < x < x1 and y0 < y < y1

    def _near_farm(self, x, y, r=2):
        for yy in range(y - r, y + r + 1):
            for xx in range(x - r, x + r + 1):
                if self.inb(xx, yy) and (self.tiles[yy][xx].o >= 0 or (xx, yy) in self.ctiles):
                    return True
        return False

    def _town_spot(self):
        """Næste byggegrund: først tomme grunde inde i byen, så forstæder langs vejene ud af byen."""
        T, rng = self.tiles, self.rng
        x0, y0, x1, y1 = TOWN
        inner = [(x, y) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)
                 if T[y][x].t == "town" and not T[y][x].b]
        if inner:
            return rng.choice(inner)
        street = [tuple(c) for st_ in self.town.get("streets", []) for c in st_["cells"]]
        lots = []
        for a, b in street:                               # grunde langs de nye udstykningsveje
            for dx, dy in N4:
                q = (a + dx, b + dy)
                if self.inb(*q) and not in_town(*q):
                    t = T[q[1]][q[0]]
                    if t.t in ("grass", "forest") and not t.b and t.o < 0 and not t.crop and not self._near_farm(*q, 1):
                        lots.append(q)
        if lots:
            return rng.choice(lots)
        reach = 2 + 2 * self.town_lvl()
        cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
        best, bd = None, 1e9
        for y in range(y0 - reach, y1 + reach + 1):
            for x in range(x0 - reach, x1 + reach + 1):
                if not self.inb(x, y) or in_town(x, y):
                    continue
                t = T[y][x]
                if t.t != "grass" or t.b or t.o >= 0 or t.crop:
                    continue
                if not any(self.inb(x + dx, y + dy) and T[y + dy][x + dx].t in ROADS for dx, dy in N4):
                    continue
                if self._near_farm(x, y):
                    continue
                dd = max(abs(x - cx), abs(y - cy)) + rng.random() * 1.5
                if dd < bd:
                    best, bd = (x, y), dd
        return best

    def _town_landmarks(self):
        T, rng = self.tiles, self.rng
        lm = self.town.setdefault("lm", [])
        x0, y0, x1, y1 = TOWN
        for lvl, kind in LANDMARKS:
            if lvl > self.town_lvl() or kind in lm:
                continue
            cands = [(x, y) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)
                     if T[y][x].t == "town" and T[y][x].b in (None, "trae", "hus0", "hus1", "hus2")]
            by_road = [c for c in cands if any(T[c[1] + dy][c[0] + dx].t in ROADS for dx, dy in N4)]
            pool = by_road or cands
            if not pool:
                continue
            x, y = rng.choice(pool)
            T[y][x].b = kind
            self.touch(x, y)
            lm.append(kind)

    def _town_house(self):
        """Byg ét nyt hus på næste byggegrund – anlæg en ny vej, hvis der ikke er flere grunde."""
        tw, T, rng = self.town, self.tiles, self.rng
        spot = self._town_spot()
        if not spot and tw.get("street_day", -99) < self.day - 45:
            if self._town_street():
                spot = self._town_spot()
        if not spot:
            return False
        x, y = spot
        t = T[y][x]
        inner = self._town_inner(x, y)
        t.t = "town"
        t.clear_crop()
        t.b = rng.choice(("hus0", "hus1", "hus2")) if inner else rng.choice(("hus3", "hus3", "hus0", "hus2"))
        self.touch(x, y)
        tw["built"] = tw.get("built", 0) + 1
        return True

    def _town_street(self):
        """En ny udstykning: en kort vej fra en eksisterende vej ud i landskabet, med plads til huse på begge sider."""
        tw, T, rng = self.town, self.tiles, self.rng
        x0, y0, x1, y1 = TOWN
        cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
        L = TOWN_STREET_LEN
        streets = {tuple(c) for st_ in tw.get("streets", []) for c in st_["cells"]}
        reach = 4 + 3 * self.town_lvl() + 2 * len(tw.get("streets", []))
        best = None
        for y in range(y0 - reach, y1 + reach + 1):
            for x in range(x0 - reach, x1 + reach + 1):
                if not self.inb(x, y) or T[y][x].t not in ("road", "asphalt"):
                    continue
                for dx, dy in N4:
                    cells = [(x + dx * k, y + dy * k) for k in range(1, L + 1)]
                    ok = True
                    for i, (a, b) in enumerate(cells):
                        if not self.inb(a, b) or in_town(a, b):
                            ok = False
                            break
                        t = T[b][a]
                        if t.t not in ("grass", "forest") or t.b or t.o >= 0 or (a, b) in self.ctiles or t.crop:
                            ok = False
                            break
                        if self._near_farm(a, b, 1):
                            ok = False
                            break
                        # ikke lige op ad en anden vej (bortset fra startvejen)
                        side = [(a + dy, b + dx), (a - dy, b - dx)]
                        if i > 0 and any(self.inb(*q) and T[q[1]][q[0]].t in ROADS for q in side):
                            ok = False
                            break
                    if not ok:
                        continue
                    free = sum(1 for a, b in cells for q in ((a + dy, b + dx), (a - dy, b - dx))
                               if self.inb(*q) and T[q[1]][q[0]].t in ("grass", "forest") and T[q[1]][q[0]].o < 0
                               and not T[q[1]][q[0]].b)
                    if free < L:
                        continue
                    d = abs(x - cx) + abs(y - cy) - free * 0.3 + rng.random() * 2 + (0 if (x, y) in streets else 1)
                    if best is None or d < best[0]:
                        best = (d, cells)
        if not best:
            return False
        cells = best[1]
        for a, b in cells:
            t = T[b][a]
            t.t, t.lc, t.g = "road", None, 0.0
            t.clear_crop()
            self.touch(a, b)
        used = {st_["name"] for st_ in tw.get("streets", [])}
        name = next((n for n in STREET_NAMES if n not in used), f"Nyvej {len(used) + 1}")
        tw.setdefault("streets", []).append({"name": name, "cells": [list(c) for c in cells], "year": self.year()})
        tw["street_day"] = self.day
        self.add_news(f"Ny udstykning: {name}", f"{TOWN_NAME} vokser. Kommunen har anlagt {name} med byggegrunde "
                      "til nye parcelhuse – de første familier flytter ind i løbet af året.")
        self.log(f"{TOWN_NAME} har anlagt en ny vej, {name}, med byggegrunde.", None, "info")
        return True

    def _town_offer(self):
        """Kommunen vil købe jord tæt ved byen, som ikke er i brug – frivilligt at sælge."""
        tw, T = self.town, self.tiles
        x0, y0, x1, y1 = TOWN
        streets = [tuple(c) for st_ in tw.get("streets", []) for c in st_["cells"]]
        near = set()
        R = 3
        for y in range(y0 - R, y1 + R + 1):
            for x in range(x0 - R, x1 + R + 1):
                near.add((x, y))
        for a, b in streets:
            near.update((a + dx, b + dy) for dx in range(-2, 3) for dy in range(-2, 3))
        by = {}
        for x, y in near:
            if not self.inb(x, y):
                continue
            t = T[y][x]
            if t.o >= 0 and t.o in self.players and not t.b and not t.crop and t.t in ("grass", "stub", "field") \
                    and not self.players[t.o].get("ai"):
                by.setdefault(t.o, []).append([x, y])
        for pid, cells in by.items():
            p = self.players[pid]
            if len(cells) < 4 or (p.get("town_offer") or {}).get("until", -1) >= self.day:
                continue
            cells = cells[:12]
            price = len(cells) * TOWN_LAND_PRICE
            p["town_offer"] = {"cells": cells, "price": price, "until": self.day + 30}
            self.log(f"Kommunen vil gerne købe {len(cells)} felter af din jord tæt ved {TOWN_NAME} til nye "
                     f"boliger – den byder {kr(price)}. Se fanen Opgaver.", pid, "info")

    def act_townoffer(self, pid, yes):
        p = self.players.get(pid)
        of = (p or {}).get("town_offer")
        if not of or of.get("until", -1) < self.day:
            return
        p["town_offer"] = None
        if not yes:
            self.log("Du takkede nej til kommunens bud på jorden.", pid, "info")
            return
        T = self.tiles
        n = 0
        for x, y in of["cells"]:
            t = T[y][x]
            if t.o == pid and not t.b and not t.crop:
                t.o = -1
                if t.t in ("field", "stub"):
                    t.t = "grass"
                (p.get("tacc") or {}).pop(f"{x},{y}", None)
                self.touch(x, y)
                n += 1
        pay = n * TOWN_LAND_PRICE
        p["money"] += pay
        self.book(p, "jord", pay)
        self.log(f"Du solgte {n} felter jord til kommunen for {kr(pay)}. Byen kan nu bygge der.", pid, "good")
        self._fix_capacity(p)

    def _town_month(self):
        tw, T, rng = self.town, self.tiles, self.rng
        lv = self.town_lvl()
        want = int(tw.get("pts", 0) / TOWN_PTS_HOUSE) - tw.get("built", 0)
        for _ in range(max(0, min(want, 2 + lv))):
            if not self._town_house():
                break
        m = self.month()
        if m % 3 == 0:                                # byen vokser også lidt af sig selv – 4–6 huse om året
            for _ in range(1 + (rng.random() < 0.25)):
                if self._town_house():
                    tw["built"] -= 1                  # naturlig vækst tager ikke af handelens huse
                    tw["nat"] = tw.get("nat", 0) + 1
        if m == 4 and lv >= 1:
            self._town_offer()
        if lv >= 2:                                   # byen fortætter: etageboliger i midten
            x0, y0, x1, y1 = TOWN
            inner = [(x, y) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1) if T[y][x].t == "town"]
            homes = [c for c in inner if T[c[1]][c[0]].b in ("hus0", "hus1", "hus2")]
            flats = sum(1 for c in inner if T[c[1]][c[0]].b == "hus4")
            if homes and flats < int(len(inner) * 0.12 * (lv - 1)):
                x, y = rng.choice(homes)
                T[y][x].b = "hus4"
                self.touch(x, y)
        tw["pop"] = self.town_pop()
        tw["ph"] = (tw.get("ph", []) + [tw["pop"]])[-60:]

    def season(self):
        """Årstidens begivenhed lige nu: 'hoestfest', 'halloween', 'jul', 'stork' eller None."""
        m, d = self.month(), self.dom()
        if m == FEST_DAYS[0] and FEST_DAYS[1] <= d <= FEST_DAYS[2]:
            return "hoestfest"
        if m == HALLOWEEN_DAYS[0] and HALLOWEEN_DAYS[1] <= d <= HALLOWEEN_DAYS[2]:
            return "halloween"
        if m == XMAS_MONTH:
            return "jul"
        if m in STORK_MONTHS:
            return "stork"
        return None

    def sale_bonus(self, g, p=None):
        b = 1.10 if self.done("station") else 1.0
        if p and p.get("scen") == "oko" and g not in ("tommer", "vildt", "fisk", "svin", "aeg"):
            b *= 1 + OKO_PRICE                                # økologisk gård: merpris (svin og æg: økotillæg)
        if self.season() == "hoestfest":
            b *= 1 + FEST_BONUS
        if g in TOWN_LOCAL:
            b *= 1 + TOWN_LOCAL_BONUS * self.town_lvl()
        if p:
            b *= 1 + min(10, self.prestige(p)) * PRESTIGE_BONUS
            sb = p.get("show_bonus")
            if sb and sb.get("until", 0) >= self.day:
                b *= 1 + sb.get("pct", 0)
        if g in ("maelk", "aeg", "svin") and self.done("mejeri"):
            b *= 1.30
        if g == "kartofler" and p and self.month() <= 5 and self.capacity(p, "kartoffellager"):
            b *= POTATO_STORE_BONUS                       # lagerkartofler fra kølelageret i foråret
        return b

    SELL_CROPS = ("hvede", "byg", "majs", "kartofler", "raps", "jordbaer", "mel", "honning", "groent")

    def sale_value(self, g, qty, p=None):
        """Hvad et salg af qty giver lige nu (prisen falder undervejs, ligesom i act_sell)."""
        if qty <= 0:
            return 0.0
        p0 = self.market[g]["p"]
        p1 = p0 * max(0.35, 1 - qty / self.depth(g))
        return qty * (p0 + p1) / 2 * self.sale_bonus(g, p)

    def sellall_plan(self, p):
        """{vare: antal} for 'Sælg alle afgrøder'. Har man dyr, gemmes foder til ca. en måned."""
        need = 30 * (p["cows"] * ANIMALS["cows"][4] + sum(p[k] * a[4] for k, a in ANIMALS.items() if k != "cows"))
        keep = {}
        for g in self.feed_order(p):                  # gem det foder, dyrene alligevel æder først (det billigste)
            if need <= 0:
                break
            k = min(int(p["inv"].get(g, 0)), int(need + 0.999))
            keep[g] = k
            need -= k
        plan = {}
        for g in self.SELL_CROPS:
            have = int(p["inv"].get(g, 0)) - keep.get(g, 0)
            if have > 0:
                plan[g] = have
        return plan

    def act_sellall(self, pid):
        p = self.players.get(pid)
        if not p:
            return
        plan = self.sellall_plan(p)
        if not plan:
            self.log("Der er ingen afgrøder at sælge" + (" – resten er foder til dyrene." if p["cows"] + p["pigs"] +
                     p["chickens"] else "."), pid, "err")
            return
        for g, q in plan.items():
            self.act_sell(pid, g, q)

    def act_sell(self, pid, g, qty):
        p = self.players.get(pid)
        if not p or g not in GOODS:
            return
        qty = min(qty, int(p["inv"][g]))
        if qty <= 0:
            self.log(f"Du har ingen {GOODS[g]['navn'].lower()} at sælge.", pid, "err")
            return
        deal_rev, mqty = self._deal_take(p, g, qty)          # leveringsaftaler får varen først (fast pris)
        mk = self.market[g]
        p0 = mk["p"]
        p1 = p0 * max(0.35, 1 - mqty / self.depth(g))
        rev = mqty * (p0 + p1) / 2 * self.sale_bonus(g, p) + deal_rev
        wet = min(qty, (p.get("wetg") or {}).get(g, 0.0))
        if wet >= 1:                                   # vådt korn: grovvarehandlen trækker et fugtfradrag
            cut = rev * wet / qty * WET_DISCOUNT
            rev -= cut
            p["wetg"][g] -= wet
            self.log(f"Fugtfradrag på {int(wet)} {GOODS[g]['navn'].lower()}, der var vådt: -{kr(cut)}.", pid, "warn")
        if mqty > 0:
            mk["p"] = p1
        p["inv"][g] -= qty
        if g in GOOD_CARGO and self.haulers(pid, GOOD_CARGO[g]):     # egen transport: kør det selv – bedre pris
            self._freight(p, "out", g, qty, rev)
            who = "slagteriet" if g == "svin" else "mejeriet"
            auto = self.haulers(pid, GOOD_CARGO[g], True)
            self.log(f"Solgte {qty} {GOODS[g]['navn'].lower()} til {who} for {kr(rev)}. " +
                     ("Din egen transport kører det derhen og får 8% mere ved levering." if auto else
                      f"Kør det selv derhen (læs op ved gården) og få 8% mere – ellers henter {who} det om "
                      f"{HIRE_WAIT} dage til den aftalte pris."), pid, "good")
            return
        if g in STORE_GOODS:                  # korn, ensilage og halm skal køres ind til grovvarehandlen
            self._freight(p, "out", g, qty, rev)
            own = self.haulers(pid, "grain", True)
            if self._self_haul_wait(p):
                self.log(f"Solgte {qty} {GOODS[g]['navn'].lower()} for {kr(rev)} til grovvarehandlen. Kør det selv "
                         f"ind til byen (læs op ved gården) – ellers henter vognmanden det om {HIRE_WAIT} dage mod "
                         "betaling.", pid, "good")
                return
            self.log(f"Solgte {qty} {GOODS[g]['navn'].lower()} for {kr(rev)} til grovvarehandlen. " +
                     ("Din egen transport kører det til byen, og pengene kommer ved levering." if own else
                      f"Vognmanden henter det for {SALE_PICKUP:.2f} kr/enhed, og pengene kommer ved levering."
                      .replace(".", ",", 1)), pid, "good")
            return
        p["money"] += rev
        self.book(p, "salg", rev)
        self.town_add(rev)
        self.log(f"Solgte {qty} {GOODS[g]['navn'].lower()} for {kr(rev)}.", pid, "good")

    def act_buy(self, pid, g, qty):
        p = self.players.get(pid)
        if not p or g not in GOODS or qty <= 0:
            return
        mk = self.market[g]
        unit = mk["p"] * 1.25
        qty = min(qty, int(max(0, p["money"]) // unit))
        if g in STORE_GOODS:
            qty = min(qty, int(self._storage_free(p, g) - self._incoming(p, g)))
        if qty <= 0:
            self.log("Ikke nok penge eller plads på lageret.", pid, "err")
            return
        cost = qty * unit
        p["money"] -= cost
        self.book(p, "varekoeb", -cost)
        if g in STORE_GOODS:                  # grovvarehandlens lastbil kører varen ud til gården
            self._freight(p, "in", g, qty, cost)
            self.log(f"Købte {qty} {GOODS[g]['navn'].lower()} for {kr(cost)}. Grovvarehandlens lastbil kører "
                     "det ud til dig.", pid, "info")
            mk["p"] = min(mk["p"] * (1 + 0.5 * qty / self.depth(g)), GOODS[g]["base"] * 2.5)
            return
        p["inv"][g] += qty
        mk["p"] = min(mk["p"] * (1 + 0.5 * qty / self.depth(g)), GOODS[g]["base"] * 2.5)
        self.log(f"Købte {qty} {GOODS[g]['navn'].lower()} for {kr(cost)}.", pid, "info")

    def act_animal(self, pid, kind, delta):
        p = self.players.get(pid)
        if not p or kind not in ANIMALS or delta == 0:
            return
        b, price, one, many = ANIMALS[kind][:4]
        cap, cur = self.animal_cap(p, kind), p[kind]
        if delta > 0:
            if kind in GRAZERS and self.capacity(p, b) > cur and cap <= cur:
                self.log(f"{many.capitalize()} skal på græs: lav en fold med hegn, der rører stalden "
                         f"({'3 får' if kind == 'sheep' else '1 dyr'} pr. felt).", pid, "err")
                return
            if cap - cur <= 0:
                self.log(f"Byg en {BUILDINGS[b]['navn'].lower()} til dine {many} først.", pid, "err")
                return
            incoming = sum(d["n"] for d in p["deliv"] if d["kind"] == kind and d["dir"] in ("in", "home", "show")) + \
                p.get("at_show", {}).get(kind, 0)
            n = min(delta, cap - cur - incoming, int(max(0, p["money"]) // price))
            if cap - cur - incoming <= 0:
                self.log(f"Der er allerede {incoming} {many} på vej, og ikke plads til flere.", pid, "err")
                return
            if n <= 0:
                self.log("Ikke nok penge.", pid, "err")
                return
            p["money"] -= n * price
            self.book(p, "dyr", -n * price)
            self._acc(p, "aacc", kind, buy=n * price)
            self._order(p, "in", kind, n, 0)
            self.log(f"Købte {n} {one if n == 1 else many} på kvægtorvet (-{kr(n * price)}). "
                     + self._order_note(p), pid, "info")
        else:
            n = min(-delta, cur)
            if n <= 0:
                return
            p[kind] -= n
            self._order(p, "out", kind, n, n * price * 0.6)
            self.log(f"{n} {one if n == 1 else many} skal køres til kvægtorvet. " + self._order_note(p), pid, "info")

    # ── transport ────────────────────────────────────────────────────────────
    def _freight(self, p, direction, g, qty, value, carrier=None):
        p.setdefault("freight", []).append({"id": self.nid, "dir": direction, "good": g, "qty": float(qty),
                                            "value": value, "taken": 0.0, "made": self.day, "carrier": carrier})
        self.nid += 1

    def _milk_pickup(self):
        """Mejeriet henter mælken med sin tankbil – betaling til dagspris, når den er leveret."""
        for p in self.players.values():
            qty = int(p["inv"].get("maelk", 0))
            if qty < 1 or not p.get("milk_auto", True):
                continue
            if any(f.get("carrier") == "mejeri" or f["good"] == "maelk" for f in p.get("freight", [])):
                continue
            own = self.haulers(p["id"], "milk")
            deal_rev, mq = self._deal_take(p, "maelk", qty)       # en leveringsaftale får mælken først
            mk = self.market["maelk"]
            p0 = mk["p"]
            p1 = p0 * max(0.35, 1 - mq / self.depth("maelk"))
            rev = mq * (p0 + p1) / 2 * self.sale_bonus("maelk", p) + deal_rev
            mk["p"] = p1
            p["inv"]["maelk"] -= qty
            self._freight(p, "out", "maelk", qty, rev, carrier=None if own else "mejeri")

    def _own_freight_timeout(self):
        """Kører man ikke selv slagtesvin eller mælk ud i tide, henter slagteriet/mejeriet det selv (uden bonus)."""
        for p in self.players.values():
            for f in list(p.get("freight", [])):
                if f["dir"] != "out" or f.get("carrier") or f["good"] not in GOOD_CARGO or f["taken"] > 0.5:
                    continue
                if self.haulers(p["id"], GOOD_CARGO[f["good"]], True) and self.day - f["made"] < HIRE_WAIT * 2:
                    continue                          # egen transport kører selv – giv den tid
                if self.day - f["made"] < HIRE_WAIT:
                    continue
                if f["good"] == "maelk":
                    f["carrier"] = "mejeri"           # mejeriets tankbil henter den
                    continue
                pay = f["value"]
                p["money"] += pay
                self.book(p, "salg", pay)
                self.town_add(pay)
                p["freight"].remove(f)
                self.log(f"Slagteriet hentede selv {int(f['qty'])} slagtesvin (+{kr(pay)}).", p["id"], "info")

    def bee_hives(self):
        """Alle bistader på kortet [(x, y)] – bierne er ligeglade med skel (caches, til noget bygges om)."""
        c = getattr(self, "_hives", None)
        if c and c[0] == self.ver:
            return c[1]
        hv = [tuple(pos) for q in self.players.values() for pos in self.stats(q["id"])["bpos"].get("bistade", [])]
        self._hives = (self.ver, hv)
        return hv

    def bee_near(self, x, y):
        """Ligger feltet inden for biernes rækkevidde? (bestøvning)"""
        return any(abs(x - hx) <= BEE_R and abs(y - hy) <= BEE_R for hx, hy in self.bee_hives())

    def bee_flowers(self, hx, hy):
        """Blomster, ét bistade har for sig selv: felterne inden for rækkevidde, delt mellem de bistader, der når dem."""
        hives = self.bee_hives()
        f = 0.0
        for y in range(hy - BEE_R, hy + BEE_R + 1):
            for x in range(hx - BEE_R, hx + BEE_R + 1):
                if not self.inb(x, y):
                    continue
                t = self.tiles[y][x]
                w = 0.0
                if t.crop and not t.dead and t.crop in BEE_CROPS and t.g >= 0.3:
                    w = BEE_CROPS[t.crop]
                elif t.t in ("grass", "pasture", "forest"):
                    w = 0.3
                elif t.t == "plaene":
                    w = 0.1
                if w:
                    n = sum(1 for ax, ay in hives if abs(x - ax) <= BEE_R and abs(y - ay) <= BEE_R)
                    f += w / max(1, n)
        return f

    def bee_honey(self, hx, hy):
        """Honning pr. dag fra ét bistade (kg), når bierne flyver."""
        return BEE_BASE + BEE_PER_FLOWER * min(BEE_FLOWER_CAP, self.bee_flowers(hx, hy))

    def _bees(self, p):
        hives = self.stats(p["id"])["bpos"].get("bistade", [])
        if not hives or not (BEE_MONTHS[0] <= self.month() <= BEE_MONTHS[1]):
            return
        kg = sum(self.bee_honey(*h_) for h_ in hives)
        p["inv"]["honning"] = p["inv"].get("honning", 0.0) + kg
        self._rec(p, "prod", "honning", kg)
        if self.month() == BEE_MONTHS[1] and self.day % DAYS_PER_MONTH == DAYS_PER_MONTH - 1 and not p.get("ai"):
            self.log(f"Bierne går i vinterhi. Der er {int(p['inv'].get('honning', 0))} kg honning på lageret – "
                     "torvehandleren køber den.", p["id"], "info")

    def _halmfyr(self, p):
        """Halmfyret brænder overskudshalm i fyringssæsonen: varme til stuehuset og fjernvarme til byen."""
        n = self.stats(p["id"])["b"].get("halmfyr", 0)
        p["hf_on"] = False
        if not n or self.month() not in HEAT_MONTHS or not p.get("hf_auto", True):
            return
        keep = sum(p.get(k, 0) * STRAW_USE[k] for k in ANIMALS) * 30      # en måneds strøelse gemmes til dyrene
        burn = min(HALMFYR_USE * n, max(0.0, p["inv"].get("halm", 0.0) - keep))
        if burn < 0.5:
            if not p.get("ai") and self.day - p.get("hf_warn", -99) >= 20:
                p["hf_warn"] = self.day
                self.log("Halmfyret står stille – der er ingen overskudshalm (en måneds strøelse gemmes til dyrene).",
                         p["id"], "info")
            return
        p["inv"]["halm"] -= burn
        kr_ = burn * HALMFYR_KR
        p["money"] += kr_
        self.book(p, "varme", kr_)
        self.town_add(kr_ * 0.5)                          # fjernvarmen hjælper byen
        p["hf_on"] = True
        p["hf_kr"] = p.get("hf_kr", 0.0) + kr_

    def _greenhouse(self, p):
        """Drivhuset giver tomater og agurker hele året – om vinteren skal det varmes op (gratis med halmfyret)."""
        n = self.stats(p["id"])["b"].get("drivhus", 0)
        if not n:
            return
        m = self.month()
        light = 0.7 if m in (10, 11, 0) else 1.0
        prod = DRIVHUS_PROD * n * light
        p["inv"]["groent"] = p["inv"].get("groent", 0.0) + prod
        self._rec(p, "prod", "groent", prod)
        if m in HEAT_MONTHS and not p.get("hf_on"):
            cost = DRIVHUS_HEAT * n
            p["money"] -= cost
            self.book(p, "stroem", -cost)

    def _mill(self, p):
        """Kornmøllen maler hvede til mel, når det blæser (kan slås fra ved møllen)."""
        n = self.stats(p["id"])["b"].get("kornmoelle", 0)
        p["mill_today"] = 0.0
        if not n or not p.get("mill_on", True):
            return
        rate = MILL_RATE * n * MILL_WIND.get(self.weather, 1.0) * egn_of(self).get("wind", 1.0)
        a = min(rate, p["inv"].get("hvede", 0.0))
        if a < 0.5:
            return
        p["inv"]["hvede"] -= a
        p["inv"]["mel"] = p["inv"].get("mel", 0.0) + a
        p["mill_today"] = a
        self._rec(p, "prod", "mel", a)

    def _calves(self, p):
        """Kalvehytterne: køerne får kalve, der drikker mælk de første uger og efter CALF_DAYS dage bliver til en ko
        (er der plads i stalden) eller sælges."""
        cap = self.capacity(p, "kalvehytter")
        cv = p.setdefault("calves", [])
        if not cap and not cv:
            return
        for c in cv:
            c["d"] += 1
        milk = sum(CALF_MILK for c in cv if c["d"] <= 60)
        p["inv"]["maelk"] = max(0.0, p["inv"].get("maelk", 0.0) - milk)
        done = [c for c in cv if c["d"] >= CALF_DAYS]
        if done:
            p["calves"] = cv = [c for c in cv if c["d"] < CALF_DAYS]
            kept = sold = 0
            for c in done:
                if p.get("calf_keep", True) and self.animal_cap(p, "cows") > p.get("cows", 0):
                    p["cows"] += 1
                    kept += 1
                else:
                    sold += 1
            if sold:
                v = sold * CALF_PRICE
                p["money"] += v
                self.book(p, "dyr", v)
            if not p.get("ai"):
                self.log("Kalvene i kalvehytterne er store nu: " +
                         (f"{kept} er sat ind i kostalden" if kept else "") + (" og " if kept and sold else "") +
                         (f"{sold} er solgt (+{kr(v)})" if sold else "") + ".", p["id"], "good")
        if len(cv) < cap and p.get("cows", 0) and self.rng.random() < min(1.0, p["cows"] * CALF_RATE):
            cv.append({"d": 0})
            if not p.get("ai") and self.day - p.get("calf_log", -99) >= 15:
                p["calf_log"] = self.day
                self.log(f"En kalv er født og flyttet ud i kalvehytterne ({len(cv)}/{cap}).", p["id"], "good")

    def _mice(self, p):
        """Uden en gårdkat kommer der mus i kornlageret en gang imellem."""
        if p.get("ai") or (p.get("pets") or {}).get("kat"):
            return
        korn = [g for g in STORE_GOODS if self.store_group(g) == "korn" and g not in ("halm",)
                and p["inv"].get(g, 0) >= 1]
        if sum(p["inv"][g] for g in korn) < 200 or self.rng.random() >= MICE_CHANCE:
            return
        lost = 0.0
        for g in korn:
            a = p["inv"][g] * MICE_LOSS
            p["inv"][g] -= a
            lost += a
        self.log(f"Mus i kornlageret! De har ædt ca. {int(lost)} enheder korn. En gårdkat holder dem væk "
                 "(Gård-fanen › Dyr).", p["id"], "warn")

    def act_pet(self, pid, kind, on=True):
        p = self.players.get(pid)
        if not p or kind not in PETS:
            return
        pets = p.setdefault("pets", {})
        d = PETS[kind]
        if on and not pets.get(kind):
            if p["money"] < d["price"] and not self.sandbox():
                self.log("Ikke nok penge.", pid, "err")
                return
            p["money"] -= d["price"]
            self.book(p, "dyr", -d["price"])
            pets[kind] = True
            self.log(f"Du har fået en {d['navn'].lower()} (-{kr(d['price'])}). {d['desc'].split(' – ')[0]}.", pid, "good")
        elif not on and pets.get(kind):
            pets.pop(kind, None)
            self.log(f"{d['navn']}en har fået et nyt hjem hos en nabo.", pid, "info")

    def _stuck_jobs(self, p):
        """Opgaver, der ikke er kommet i gang efter nogle dage: fortæl hvorfor (højst hver 10. dag pr. slags)."""
        if p.get("ai") or self.day % 2:
            return
        pid = p["id"]
        sw = p.setdefault("stuck_w", {})
        own = [t for t in self.tractors if t["o"] == pid and not t.get("hire")]
        own_c = any(vkind(t["k"]) == "combine" for t in own)
        for j in p.get("jobs", []):
            if j.get("for") or self.day - j.get("made", self.day) < 5 or len(j["tiles"]) < j.get("n", 0):
                continue                                   # ny, en nabos opgave, eller den er i gang
            tool = j["tool"]
            if self.day - sw.get(tool, -99) < 10:
                continue
            why = None
            if tool == "harvest" and not own_c and not self.auto_on(p, "maskinstation") and \
                    any(not self._tractor_crop(c, p) for c in j["tiles"]):
                why = ("du har ingen mejetærsker, og maskinstationen er slået fra under Automatik")
            elif tool != "harvest" and not any(tool in self.jobs_for(t) for t in own):
                why = "du har ingen maskine, der kan det – køb en under Byg og køb"
            elif self.manual_mode() and not any(t.get("helper") for t in own if tool in self.jobs_for(t)):
                why = "i Styr selv-tilstand kører maskinerne kun af sig selv med en medhjælper (højreklik på maskinen)"
            elif tool in ("plow", "sow") and all(f"{c[0]},{c[1]}" in (p.get("bales") or {}) or
                                                 f"{c[0]},{c[1]}" in (p.get("wraps") or {}) for c in j["tiles"]):
                why = "der ligger baller på felterne – de skal køres hjem først"
            if why:
                sw[tool] = self.day
                self.log(f"Opgaven '{JOB_NAMES[tool].lower()}' er ikke kommet i gang: {why}.", pid, "warn")

    def _bale_overflow(self, p):
        """Ballerne på markerne kan ikke køres hjem, fordi ballepladsen er fuld: advar – og (Automatik) lad
        grovvarehandlen hente overskudsballerne på marken, når pladsen har været fuld i BALE_SELL_DAYS dage."""
        field = self.bales_total(p)
        no_pickup = not self.bale_loader(p["id"]) and not self.auto_on(p, "vognmand")
        if field < BALE_U * 0.5 or (self._storage_free(p, "halm") >= BALE_U and not no_pickup):
            p.pop("bfull", None)
            return
        since = p.setdefault("bfull", self.day)
        auto = self.auto_on(p, "halmsalg")
        if auto and self.day - since >= BALE_SELL_DAYS:
            rev, n = 0.0, 0
            for g, dk in BALE_GOODS.items():
                d = p.get(dk) or {}
                amt = sum(d.values())
                if amt < 0.5:
                    continue
                for k in list(d):
                    n += max(1, int(round(d[k] / bale_unit(g, self.spot_shape(p, g, k)))))
                    p.get("bshape", {}).pop(k, None)
                    self.touch(*map(int, k.split(",")))
                p[dk] = {}
                mk = self.market[g]
                p1 = mk["p"] * max(0.35, 1 - amt / self.depth(g))
                rev += amt * max(0.0, (mk["p"] + p1) / 2 - SALE_PICKUP)
                mk["p"] = p1
            p.pop("bfull", None)
            if rev > 0:
                p["money"] += rev
                self.book(p, "salg", rev)
                self.town_add(rev)
            if n:
                self.log(("Ingen kunne køre ballerne hjem" if no_pickup else "Ballepladsen var fuld") +
                         f", så grovvarehandlen hentede {n} baller på markerne (+{kr(rev)}). "
                         "Nu kan markerne pløjes igen.", p["id"], "info")
            return
        if not p.get("ai") and self.day - p.get("bfull_warn", -99) >= 10:
            p["bfull_warn"] = self.day
            n = int(round(field / BALE_U))
            self.log(("Ingen kan køre ballerne hjem (vognmanden er slået fra, og du har ingen frontlæsser og vogn)"
                      if no_pickup else "Ballepladsen er fuld") +
                     f" – ca. {n} baller ligger stadig på markerne, og felter med baller bliver "
                     "ikke pløjet eller sået. " +
                     (f"Grovvarehandlen henter dem om {max(1, BALE_SELL_DAYS - (self.day - since))} dage, hvis der "
                      "ikke bliver plads. " if auto else "") +
                     ("Slå vognmanden til, eller sæt en frontlæsser på traktoren." if no_pickup else
                      "Sælg halm, eller byg en balleplads eller en rundbuehal (halm)."), p["id"], "warn")

    def bales_total(self, p):
        return sum(p.get("bales", {}).values()) + sum(p.get("wraps", {}).values())

    def bale_spot(self, pid):
        """Hvor baller læsses af: ballepladsen, hvis der er en – ellers samme sted som høsten."""
        bp = self.stats(pid)["bpos"]
        b = list(bp.get("balleplads", [])) + list(bp.get("rundbuehal_halm", [])) + list(bp.get("lade", []))
        if b:
            p = self.players[pid]
            px, py = p.get("pile_pos") or p["home"]
            return tuple(min(b, key=lambda s: abs(s[0] - px) + abs(s[1] - py)))
        return self._drop_spot(pid)

    def _hire_haulers(self):
        """Vognmanden kommer med en synlig lastbil fra byen, når der er noget at køre, som gården ikke selv kan."""
        for p in self.players.values():
            pid = p["id"]
            own_g = self.haulers(pid, "grain", True)
            wait = self._self_haul_wait(p)
            fr = p.get("freight", [])
            haulable = any(v > 0.5 and self._storage_free(p, g) >= 10 for g, v in p.get("pile", {}).items()) or \
                (self.bales_total(p) > 0.5 and self._storage_free(p, "halm") >= 10)
            if not own_g and self.pile_total(p) > 0.5 and not haulable:
                self._warn_full(p, list(p.get("pile", {})))
            loader = self.bale_loader(pid, True)
            bale_wait = self.manual_mode() and self.bale_loader(pid) and not loader
            bales_hire = self.bales_total(p) > 0.5 and self._storage_free(p, "halm") >= 10 and not loader and \
                (not bale_wait or self._pile_age(p) >= HIRE_WAIT)
            if self.bales_total(p) > 0.5 and not self.bale_loader(pid) and p.get("bale_hint", -99) < self.day - 60:
                p["bale_hint"] = self.day
                if self.auto_on(p, "vognmand"):
                    self.log("Halmballerne samles op af vognmanden med kranbil. Med en frontlæsser på traktoren "
                             "(højreklik › Opgrader) og en tipvogn kan du selv gøre det.", pid, "info")
                else:
                    self.log("Halmballerne bliver liggende: vognmanden er slået fra under Automatik, og du har ingen "
                             "traktor med frontlæsser og vogn. Felter med baller bliver ikke pløjet.", pid, "warn")
            need_field = bales_hire or (not own_g and haulable and (not wait or self._pile_age(p) >= HIRE_WAIT))
            need_trade = any(f["qty"] - f["taken"] > 0.5 and not f.get("carrier") and
                             (f["dir"] == "in" or (not own_g and not wait) or self.day - f["made"] >= HIRE_WAIT)
                             for f in fr)
            if not self.auto_on(p, "vognmand"):
                need_field = False                            # slået fra: høst og baller bliver i marken
                if not own_g and self.pile_total(p) >= 20 and not p.get("ai") and \
                        self.day - p.setdefault("full_warn_g", {}).get("vgm", -99) >= 10:
                    p["full_warn_g"]["vgm"] = self.day
                    self.log("Høsten ligger i marken: vognmanden er slået fra under Automatik, og du har ingen egen "
                             "vogn og traktor, der kører den hjem af sig selv. Slå vognmanden til, eller kør selv.",
                             pid, "warn")
            need_g = need_field or need_trade                 # købte og solgte varer leveres altid
            own_a = self.haulers(pid, "animal", True)
            for d in p.get("deliv", []):                      # egen dyretransport, der ikke længere kan køre
                if not d["rent"] and d["n"] - d["taken"] > 0 and d["taken"] == 0 and not own_a:
                    fee = HAUL_RENT_ANIMAL[d["kind"]] * d["n"]
                    d["rent"], d["fee"] = True, fee
                    p["money"] -= fee
                    self.book(p, "transport", -fee)
                    self.log(f"Din egen dyretransport kan ikke køre lige nu, så vognmanden tager "
                             f"{d['n']} {ANIMALS[d['kind']][3]} (-{kr(fee)}).", pid, "info")
            need_a = any(d["rent"] and d["n"] - d["taken"] > 0 for d in p.get("deliv", []))
            need_m = any(f.get("carrier") == "mejeri" and f["qty"] - f["taken"] > 0.5 for f in fr)
            for key, need in (("vognmand", need_g), ("vognmand_dyr", need_a), ("maelkebil", need_m)):
                hired = [t for t in self.tractors if t["o"] == pid and t["k"] == key]
                if need and len(hired) < (HIRE_MAX if key == "vognmand" else 1):
                    self.tractors.append({"id": self.nid, "o": pid, "k": key, "hs": list(DEPOT), "x": float(DEPOT[0]),
                                          "y": float(DEPOT[1]), "d": 0, "s": "idle", "tx": None, "ty": None, "w": 0.0,
                                          "j": None, "tool": None, "path": None, "hire": key})
                    self.nid += 1
            for t in [t for t in self.tractors if t["o"] == pid and t.get("hire") in ("vognmand", "vognmand_dyr", "maelkebil")]:
                if t["s"] == "parked" and not t.get("haul") and tuple(t["hs"]) == DEPOT:
                    self.tractors.remove(t)

    def haulers(self, pid, cargo, auto=False):
        """Kan spilleren selv transportere denne slags last? (lastbil, eller vogn + traktor)
        auto=True: kan det ske af sig selv? I Styr selv-tilstand kun med en medhjælper på maskinen."""
        own = self.vehicles_of(pid)
        if auto and not self.auto_on(self.players.get(pid), "transport" if cargo == "grain" else "dyr"):
            return False                                       # slået fra under Automatik
        if auto and self.manual_mode() and self.tractors:
            helped = {t["id"] for t in self.tractors if t.get("helper")}
            own = [(i, k) for i, k in own if i in helped]
        if any(VEHICLES[k].get("cargo") == cargo for _, k in own if k in VEHICLES):
            return True
        p = self.players.get(pid)
        if not p:
            return False
        hks = [VEHICLES[k].get("hk", 0) for _, k in own if k in VEHICLES and vkind(k) == "tractor"]
        # en vogn tæller kun, hvis en af egne traktorer er stærk nok til at trække den
        return any(n > 0 and WAGONS[w]["cargo"] == cargo and not bale_wagon(w) and any(hk >= wagon_hk(w) for hk in hks)
                   for w, n in p["wagons"].items())

    def bale_loader(self, pid, auto=False):
        """Kan gården selv samle halmballer op? Det kræver en traktor med frontlæsser og en ballevogn/tipvogn."""
        p = self.players.get(pid)
        if not p or not any(n > 0 for w, n in p.get("wagons", {}).items() if WAGONS[w]["cargo"] == "grain"):
            return False
        if auto and not self.auto_on(p, "baller"):
            return False
        hks = [VEHICLES.get(t["k"], {}).get("hk", 0) for t in self.tractors
               if t["o"] == pid and not t.get("hire") and vkind(t["k"]) == "tractor"]
        if not any(n > 0 and WAGONS[w]["cargo"] == "grain" and any(hk >= wagon_hk(w) for hk in hks)
                   for w, n in p.get("wagons", {}).items()):
            return False                                   # ingen traktor kan trække vognene
        for t in self.tractors:
            if t["o"] == pid and not t.get("hire") and vkind(t["k"]) == "tractor" and loader_on(t):
                if not auto or not self.manual_mode() or t.get("helper"):
                    return True
        return False

    def _self_haul_wait(self, p):
        """Styr selv: har man egen transport uden medhjælper, venter vognmanden nogle dage, så man kan nå det selv."""
        return self.manual_mode() and self.haulers(p["id"], "grain") and not self.haulers(p["id"], "grain", True)

    def _pile_age(self, p):
        return self.day - p.get("pile_since", self.day)

    def _order(self, p, direction, kind, n, value):
        rent = not self.haulers(p["id"], "animal", True)
        d = {"id": self.nid, "dir": direction, "kind": kind, "n": n, "value": value, "rent": rent,
             "days": HAUL_RENT_DAYS, "taken": 0}
        self.nid += 1
        if rent:
            fee = HAUL_RENT_ANIMAL[kind] * n
            p["money"] -= fee
            self.book(p, "transport", -fee)
            d["fee"] = fee
        p["deliv"].append(d)

    def _order_note(self, p):
        d = p["deliv"][-1]
        if d["rent"]:
            return f"En vognmand kører dem om {HAUL_RENT_DAYS} dage (-{kr(d['fee'])})."
        return "Din kreaturvogn eller kreaturbil kører dem."

    def pile_total(self, p):
        return sum(p.get("pile", {}).values())

    def _drop_spot(self, pid):
        """Hvor høsten læsses af: nærmeste silo, ellers ved stuehuset."""
        silos = self.stats(pid)["bpos"].get("silo")
        p = self.players[pid]
        if silos:
            px, py = p.get("pile_pos") or p["home"]
            return min(silos, key=lambda s: abs(s[0] - px) + abs(s[1] - py))
        return tuple(p["home"])

    def timber_spot(self, pid):
        """Hvor stammerne læsses af: tømmerpladsen (den nærmeste), ellers samme sted som høsten."""
        b = self.stats(pid)["bpos"].get("toemmerplads")
        if b:
            p = self.players[pid]
            px, py = p.get("pile_pos") or p["home"]
            return tuple(min(b, key=lambda s: abs(s[0] - px) + abs(s[1] - py)))
        return self._drop_spot(pid)

    def unload_spot(self, pid, load):
        """Hvor et læs fra markbunken skal hen: stammer til tømmerpladsen, alt andet til siloen."""
        return self.timber_spot(pid) if load and set(load) <= {"tommer"} else self._drop_spot(pid)

    def _stable_spot(self, pid, kind):
        b = self.stats(pid)["bpos"]
        grp = ANIMALS[kind][0]
        for k in BUILDINGS:
            if BUILDINGS[k]["group"] == grp and b.get(k):
                return tuple(b[k][0])
        return tuple(self.players[pid]["home"])

    def _storage_free(self, p, g=None):
        return max(0.0, self.storage_cap(p, g) - self.stored(p, g))

    def _incoming(self, p, g):
        """Varer på vej ind på gården i samme lager som g (købt, ikke leveret endnu)."""
        grp = self.store_group(g)
        return sum(f["qty"] for f in p.get("freight", []) if f["dir"] == "in" and self.store_group(f["good"]) == grp)

    FULL_MSG = {
        "korn": "Kornlageret er fuldt – høsten bliver liggende i marken, hvor regnen kan ødelægge den. "
                "Sælg noget eller byg en kornsilo.",
        "ensilage": "Der er ikke plads til mere ensilage – den bliver liggende i marken, hvor regnen kan ødelægge "
                    "den. Byg en plansilo eller en foderhal, fodr den op eller sælg noget.",
        "tommer": "Tømmerpladsen er fuld – stammerne bliver liggende i markbunken. Sælg tømmer eller byg en "
                  "tømmerplads mere.",
        "baller": "Ballepladsen er fuld – halmen bliver liggende i markbunken. Sælg halm eller byg en balleplads.",
    }

    def _warn_full(self, p, goods=None):
        """Advar om de lagre, der er fulde (hvert lager for sig, højst hver 10. dag)."""
        grps = dict.fromkeys(self.store_group(g) for g in goods) if goods else {"korn": None}
        fw = p.setdefault("full_warn_g", {})
        for grp in grps:
            if self.day - fw.get(grp, -99) >= 10:
                fw[grp] = self.day
                self.log(self.FULL_MSG.get(grp, self.FULL_MSG["korn"]), p["id"], "warn")

    def _unload_grain(self, p, load):
        free = {grp: self._storage_free(p, g) for g, grp in (("hvede", "korn"), ("graes", "ensilage"), ("halm", "baller"),
                                                              ("tommer", "tommer"))}
        back = {}
        for g, v in load.items():
            grp = self.store_group(g)
            got = min(v, free[grp])
            p["inv"][g] += got
            free[grp] -= got
            if v - got > 0.01:
                back[g] = v - got
        for g, v in back.items():
            p["pile"][g] = p["pile"].get(g, 0.0) + v
        if back and not p.get("pile_pos"):
            p["pile_pos"] = list(p["home"])
        if back:
            self._warn_full(p, list(back))
        return sum(load.values()) - sum(back.values())

    def _haul_task(self, tr):
        """Find et transportjob til en ledig lastbil eller traktor (med vogn)."""
        p = self.players.get(tr["o"])
        if not p:
            return None
        kind = vkind(tr["k"])
        hire = tr.get("hire")
        own_g = self.haulers(tr["o"], "grain", True)
        wait = bool(hire) and self._self_haul_wait(p)
        if wait and self._pile_age(p) >= HIRE_WAIT:
            own_g = False
        options = []
        if kind == "truck":
            v = VEHICLES[tr["k"]]
            options.append((v["cargo"], int(v["cap"] * (1.25 if "lad" in tr.get("upg", ()) else 1)), None))
        if tr["k"] == "maelkebil":
            for f in p.get("freight", []):
                if f.get("carrier") == "mejeri" and f["qty"] - f["taken"] > 0.5:
                    n = f["qty"] - f["taken"]
                    f["taken"] += n
                    return dict(cargo="milk", job="out", fr=f["id"], n=n, wagon=None, leg=1, load={"maelk": n},
                                cap=n, frm=self._stable_spot(tr["o"], "cows"), to=freight_dest("maelk"))
            return None
        elif kind == "tractor":
            busy = {}
            for t in self.tractors:
                if t is not tr and t["o"] == tr["o"] and t.get("haul"):
                    w = t["haul"].get("wagon")
                    if w:
                        busy[w] = busy.get(w, 0) + 1
                if t is not tr and t["o"] == tr["o"] and (t.get("hitch") or "").startswith("w:"):
                    w = t["hitch"][2:].split("#")[0]           # koblet på en anden traktor
                    busy[w] = busy.get(w, 0) + 1
            hk_ = VEHICLES.get(tr["k"], {}).get("hk", 0)
            for w, n in p["wagons"].items():
                if n - busy.get(w, 0) > 0 and hk_ >= wagon_hk(w):
                    options.append((WAGONS[w]["cargo"], WAGONS[w]["cap"], w))
            options.sort(key=lambda o: -WAGONS[o[2]].get("big", False))     # de store vogne først
        if not hire and options:                   # egne maskiner: kun det, der er slået til under Automatik
            options = [o for o in options if self.auto_on(p, "transport" if o[0] == "grain" else "dyr")
                       or (o[0] == "grain" and self.auto_on(p, "baller"))]
        has_bw = any(bale_wagon(w_) for _, _, w_ in options)
        for cargo, cap, wagon in options:
            bw = bale_wagon(wagon)                 # ballevognen kører kun baller
            grain_ok = hire or self.auto_on(p, "transport")
            if cargo == "grain" and not bw and grain_ok and (not hire or not own_g) and \
                    (not hire or self.auto_on(p, "vognmand")) and not (wait and self._pile_age(p) < HIRE_WAIT):
                reserved = sum(sum(t["haul"]["load"].values()) for t in self.tractors
                               if t["o"] == tr["o"] and t.get("haul") and t["haul"]["cargo"] == "grain"
                               and t["haul"]["leg"] == 1)
                avail = self.pile_total(p) - reserved
                on_way = sum(sum(t["haul"]["load"].values()) for t in self.tractors
                             if t["o"] == tr["o"] and t.get("haul") and t["haul"]["cargo"] == "grain")
                # plads pr. lager: korn i kornlageret, ensilage i plansiloen – minus det, der allerede er på vej
                room_g = {}
                for grp, probe in (("korn", "hvede"), ("ensilage", "graes"), ("tommer", "tommer"), ("baller", "halm")):
                    way = sum(v for t in self.tractors if t["o"] == tr["o"] and t.get("haul") and
                              t["haul"]["cargo"] == "grain" for g, v in t["haul"]["load"].items()
                              if self.store_group(g) == grp)
                    room_g[grp] = self._storage_free(p, probe) - way
                pile_room = sum(v for g, v in p["pile"].items() if room_g[self.store_group(g)] >= 10)
                stuck_ = [g for g, v in p["pile"].items() if v >= 20 and room_g[self.store_group(g)] < 10]
                if stuck_ and not hire:                    # en del af bunken kan ikke komme ind (det lager er fuldt)
                    self._warn_full(p, stuck_)
                if avail >= 20 and pile_room < 1:
                    self._warn_full(p, [g for g in p["pile"] if room_g[self.store_group(g)] < 10])
                elif avail >= min(20, cap * 0.1) and p.get("pile_pos"):
                    # reservér en del af markbunken til dette læs – kun det, der er plads til derhjemme
                    take, left = {}, cap
                    tgrp = None                    # stammer køres for sig (til tømmerpladsen), resten til siloen
                    for g, v in sorted(p["pile"].items(), key=lambda kv: -kv[1]):
                        grp = self.store_group(g)
                        if room_g[grp] < 10 or (tgrp is not None and (grp == "tommer") != tgrp):
                            continue
                        r_g = sum(t["haul"]["load"].get(g, 0) for t in self.tractors
                                  if t["o"] == tr["o"] and t.get("haul") and t["haul"]["leg"] == 1)
                        a = min(v - r_g, left, room_g[grp])
                        if a > 0.01:
                            tgrp = grp == "tommer"
                            take[g] = a
                            left -= a
                            room_g[grp] -= a
                    if take:
                        return dict(cargo="grain", wagon=wagon, leg=1, load=take, cap=cap,
                                    frm=tuple(p["pile_pos"]), to=self.unload_spot(tr["o"], take))
            if cargo == "grain" and not bw and grain_ok:          # salg og køb til/fra grovvarehandlen
                for f in p.get("freight", []):
                    left = f["qty"] - f["taken"]
                    if left <= 0.5 or f.get("carrier"):
                        continue
                    if f["dir"] == "in" and not hire:
                        continue
                    if f["dir"] == "out" and hire and (own_g or wait) and self.day - f["made"] < HIRE_WAIT:
                        continue
                    if f["good"] in GOOD_CARGO:               # slagtesvin og mælk køres ikke i kornvogne
                        continue
                    n = min(left, cap)
                    f["taken"] += n
                    home = self._drop_spot(tr["o"])
                    dest = freight_dest(f["good"])
                    frm, to = (dest, home) if f["dir"] == "in" else (home, dest)
                    return dict(cargo="grain", job=f["dir"], fr=f["id"], n=n, wagon=wagon, leg=1,
                                load={f["good"]: n}, cap=cap, frm=frm, to=to)
            loader_ok = (loader_on(tr) and kind == "tractor" and self.auto_on(p, "baller")) if not hire else \
                (self.auto_on(p, "vognmand") and not self.bale_loader(tr["o"], True) and not (self.manual_mode() and self.bale_loader(tr["o"])
                                                               and self._pile_age(p) < HIRE_WAIT))
            if cargo == "grain" and loader_ok and (bw or not has_bw):     # baller: helst på ballevognen
                claimed = {(t["haul"].get("bk", "halm"), t["haul"].get("bale")) for t in self.tractors
                           if t["o"] == tr["o"] and t.get("haul") and t["haul"].get("job") == "bales"}
                free = self._storage_free(p, "halm")
                spots = [(g, k) for g, dk in BALE_GOODS.items() for k, v in p.get(dk, {}).items()
                         if v > 0.5 and (g, k) not in claimed]
                if spots and free > 10:
                    g, k = min(spots, key=lambda gk: abs(int(gk[1].split(",")[0]) - tr["x"]) +
                               abs(int(gk[1].split(",")[1]) - tr["y"]))
                    bx, by = map(int, k.split(","))
                    bs = self.spot_shape(p, g, k)
                    cap_b = wagon_slots(wagon) * bale_unit(g, bs) if bw else cap   # ballevognen: 16/24 baller af formen
                    return dict(cargo="grain", job="bales", bale=k, bk=g, bs=bs, wagon=wagon, leg=1, load={},
                                cap=min(cap_b, free), frm=(bx, by), to=self.bale_spot(tr["o"]))
            elif cargo in ("animal", "milk") and not hire:    # egen levering til slagteriet og mejeriet
                g_ = "svin" if cargo == "animal" else "maelk"
                for f in p.get("freight", []):
                    left = f["qty"] - f["taken"]
                    if f["dir"] != "out" or f.get("carrier") or f["good"] != g_ or left <= 0.5:
                        continue
                    n = min(left, int(cap / ANIMAL_UNITS["pigs"]) if cargo == "animal" else cap)
                    f["taken"] += n
                    frm = self._stable_spot(tr["o"], "pigs" if cargo == "animal" else "cows")
                    return dict(cargo=cargo, job="out", fr=f["id"], n=n, wagon=wagon, leg=1, load={g_: n},
                                cap=cap, frm=frm, to=freight_dest(g_))
            if cargo == "animal":
                for d in p["deliv"]:
                    if bool(d["rent"]) != bool(hire) or d["n"] - d["taken"] <= 0:
                        continue
                    unit = ANIMAL_UNITS[d["kind"]]
                    n = min(d["n"] - d["taken"], max(1, int(cap / unit)))
                    d["taken"] += n
                    stable = self._stable_spot(tr["o"], d["kind"])
                    frm, to = (KVAEGTORV, stable) if d["dir"] in ("in", "home") else (stable, KVAEGTORV)
                    return dict(cargo="animal", wagon=wagon, leg=1, d=d["id"], n=n, kind=d["kind"],
                                load={}, cap=cap, frm=frm, to=to)
        return None

    def _haul_arrive(self, tr):
        h, p = tr["haul"], self.players.get(tr["o"])
        if not p:
            tr["haul"] = None
            return
        if h["leg"] == 1:
            if h.get("job") == "bales":                   # saml ballerne på og omkring feltet
                g_ = h.get("bk", "halm")
                bales, got, left = p.get(BALE_GOODS[g_], {}), 0.0, h["cap"]
                fx, fy = h["frm"]
                bs_ = h.get("bs", "rund")
                for k in sorted(bales, key=lambda k: abs(int(k.split(",")[0]) - fx) + abs(int(k.split(",")[1]) - fy)):
                    kx, ky = map(int, k.split(","))
                    if abs(kx - fx) + abs(ky - fy) > 3 or left <= 0 or self.spot_shape(p, g_, k) != bs_:
                        continue
                    a = min(bales[k], left)
                    bales[k] -= a
                    got += a
                    left -= a
                    if bales[k] < 0.5:
                        del bales[k]
                        p.get("bshape", {}).pop(k, None)
                h["load"] = {g_: got}
                if got < 0.5:
                    tr["haul"] = None
                    return
            elif h.get("job") in ("in", "out"):
                pass                                      # varerne er allerede reserveret
            elif h["cargo"] == "grain":
                got = {}
                for g, v in h["load"].items():
                    a = min(v, p["pile"].get(g, 0.0))
                    if a > 0:
                        p["pile"][g] -= a
                        got[g] = a
                        if p["pile"][g] < 0.01:
                            del p["pile"][g]
                h["load"] = got
                if not got:
                    tr["haul"] = None
                    return
            else:
                h["load"] = {h["kind"]: h["n"]}
            h["leg"] = 2
            tr.update(s="move", tx=h["to"][0], ty=h["to"][1], path=None)
            return
        # leg 2: læs af
        if h.get("job") in ("in", "out"):
            f = next((f for f in p.get("freight", []) if f["id"] == h["fr"]), None)
            g, n = next(iter(h["load"].items()))
            if h["job"] == "in":
                self._unload_grain(p, h["load"])
                self.log(f"Grovvarehandlen har leveret {int(n)} {GOODS[g]['navn'].lower()} på gården.", tr["o"], "good")
            elif f:
                pay = f["value"] * n / f["qty"] if f["qty"] else 0
                fee = n * SALE_PICKUP if tr.get("hire") == "vognmand" else 0
                bonus = pay * OWN_DELIVERY_BONUS if g in GOOD_CARGO and not tr.get("hire") else 0
                p["money"] += pay - fee + bonus
                if bonus:
                    self.book(p, "salg", bonus)
                self.book(p, "salg", pay)
                if fee:
                    self.book(p, "transport", -fee)
                self.town_add(pay)
                f["value"] -= pay
                if f.get("carrier") == "mejeri":
                    self.log(f"Mejeriet har hentet {int(n)} liter mælk (+{kr(pay)}).", tr["o"], "good")
                else:
                    self.log(f"{int(n)} {GOODS[g]['navn'].lower()} er leveret hos {dest_name(g)} (+{kr(pay - fee + bonus)}"
                             + (f", vognmand {kr(fee)}" if fee else "") + (", heraf 8% for egen levering" if bonus else "")
                             + ").", tr["o"], "good")
            if f:
                f["qty"] -= n
                f["taken"] -= n
                if f["qty"] <= 0.5:
                    p["freight"].remove(f)
            tr["haul"] = None
            tr.update(s="idle")
            return
        if h["cargo"] == "grain":
            if h.get("job") == "bales" and h["load"].get("halm", 0) >= 0.5:
                p["yshape"] = h.get("bs", "rund")
            n = self._unload_grain(p, h["load"])
            if tr.get("hire") and n >= 1:
                fee = n * HAUL_RENT_GRAIN
                p["money"] -= fee
                self.book(p, "transport", -fee)
                p["rent_haul"] = p.get("rent_haul", 0) + fee
                p["rent_n"] = p.get("rent_n", 0) + n
            if n >= 1:
                p["hauled"] = p.get("hauled", 0) + n
                if self.pile_total(p) < 1:
                    self.log(f"Hele høsten er kørt i hus ({int(p['hauled'])} enheder).", tr["o"], "good")
                    p["hauled"] = 0
        else:
            d = next((d for d in p["deliv"] if d["id"] == h["d"]), None)
            one = ANIMALS[h["kind"]]
            if d:
                if d["dir"] == "in":
                    p[h["kind"]] += h["n"]
                    self.log(f"{h['n']} {one[2] if h['n'] == 1 else one[3]} er kommet hjem på gården.",
                             tr["o"], "good")
                elif d["dir"] == "home":
                    p[h["kind"]] += h["n"]
                    self.log(f"{h['n']} {one[2] if h['n'] == 1 else one[3]} er kommet hjem fra dyrskuet.",
                             tr["o"], "good")
                elif d["dir"] == "show":
                    at = p.setdefault("at_show", {})
                    at[h["kind"]] = at.get(h["kind"], 0) + h["n"]
                    self.log(f"{h['n']} {one[2] if h['n'] == 1 else one[3]} er ankommet til dyrskuet.", tr["o"], "good")
                else:
                    pay = d["value"] * h["n"] / d["n"] if d["n"] else 0
                    p["money"] += pay
                    self.book(p, "dyr", pay)
                    self._acc(p, "aacc", h["kind"], sold=pay)
                    self.town_add(pay)
                    d["value"] -= pay
                    self.log(f"{h['n']} {one[3]} er leveret på kvægtorvet (+{kr(pay)}).", tr["o"], "good")
                d["n"] -= h["n"]
                d["taken"] -= h["n"]
                if d["n"] <= 0:
                    p["deliv"].remove(d)
        tr["haul"] = None
        tr.update(s="idle")

    def _haul_abort(self, tr):
        """Transport afbrydes (fx styr selv) – læs og reservationer lægges tilbage."""
        h, p = tr.get("haul"), self.players.get(tr["o"])
        if not h or not p:
            tr["haul"] = None
            return
        if h.get("job") in ("in", "out"):
            f = next((f for f in p.get("freight", []) if f["id"] == h["fr"]), None)
            if f:
                f["taken"] -= h["n"]
        elif h.get("job") == "bales":
            if h["leg"] == 2:
                k = h["bale"]
                bl = p.setdefault(BALE_GOODS[h.get("bk", "halm")], {})
                bl[k] = bl.get(k, 0.0) + sum(h["load"].values())
                if h.get("bk", "halm") == "halm":
                    p.setdefault("bshape", {})[k] = h.get("bs", "rund")
        elif h["cargo"] == "grain" and h["leg"] == 2:
            for g, v in h["load"].items():
                p["pile"][g] = p["pile"].get(g, 0.0) + v
        if h["cargo"] == "animal":
            d = next((d for d in p["deliv"] if d["id"] == h["d"]), None)
            if d:
                d["taken"] -= h["n"]
        tr["haul"] = None

    def _spoil_piles(self):
        wet = self.weather in ("Regn", "Storm", "Sne")
        for p in self.players.values():
            if not p.get("pile"):
                continue
            f = 0.02 if wet else 0.005
            lost = 0.0
            for g in list(p["pile"]):
                l = p["pile"][g] * f
                p["pile"][g] -= l
                lost += l
                if p["pile"][g] < 0.01:
                    del p["pile"][g]
            if wet and lost >= 5 and self.day % 5 == 0:
                self.log(f"Regnen ødelægger høsten, der ligger i marken ({int(lost)} enheder i dag). "
                         "Få den kørt i hus!", p["id"], "warn")

    def act_wagon(self, pid, key, delta):
        p = self.players.get(pid)
        if not p or key not in WAGONS:
            return
        w = WAGONS[key]
        if delta > 0:
            if p["money"] < w["price"]:
                self.log(f"Ikke nok penge til en {w['navn'].lower()}.", pid, "err")
                return
            p["money"] -= w["price"]
            self.book(p, "maskiner", -w["price"])
            p["wagons"][key] += 1
            self._sync_park(p, True)
            self.log(f"Du købte en {w['navn'].lower()} (-{kr(w['price'])}). " +
                     ("Når du selv kører: bak traktoren hen til den og tryk K for at koble den på."
                      if self.manual_mode() else
                      "En ledig traktor kobler den på, når der er noget at køre – eller bak selv hen til den og "
                      "tryk K, når du styrer."), pid, "good")
            need_hk = wagon_hk(key)
            if need_hk and not any(VEHICLES.get(t["k"], {}).get("hk", 0) >= need_hk for t in self.tractors
                                   if t["o"] == pid and not t.get("hire") and vkind(t["k"]) == "tractor"):
                self.log(f"Pas på: {w['navn'].lower()} kræver en traktor på mindst {need_hk} hk, og du har ingen, der "
                         "er stærk nok – den bliver stående, til du køber en større traktor.", pid, "warn")
        elif p["wagons"][key] > sum(1 for r in self.rentals if r["renter"] == pid and r["item"].startswith(f"w:{key}#")):
            p["wagons"][key] -= 1
            p["money"] += w["price"] * 0.6
            self.book(p, "maskiner", w["price"] * 0.6)
            self._sync_park(p, True)
            self.log(f"Du solgte en {w['navn'].lower()} (+{kr(w['price'] * 0.6)}).", pid, "info")

    # ── kontrakter ───────────────────────────────────────────────────────────
    def _contract_area(self, rng):
        homes = [p["home"] for p in self.players.values()] or [[ROAD_X, ROAD_Y]]
        for _ in range(400):
            hx, hy = rng.choice(homes)
            w, h = rng.randint(4, 6), rng.randint(3, 5)
            x0, y0 = hx + rng.randint(-20, 16), hy + rng.randint(-20, 16)
            cells = [(x, y) for y in range(y0, y0 + h) for x in range(x0, x0 + w)]
            if all(self.inb(x, y) and self.tiles[y][x].o < 0 and self.tiles[y][x].t in ("grass", "field", "stub") and
                   not self.tiles[y][x].b and not in_town(x, y, 2) and (x, y) not in self.ctiles for x, y in cells):
                return cells
        return None

    def _new_offer(self):
        rng = self.rng
        m = self.month()
        c = {"id": self.nid, "made": self.day, "pid": None, "deadline": None}
        self.nid += 1
        if rng.random() < 0.5:
            who, goods = rng.choice(BUYERS)
            g = rng.choice(goods)
            base = GOODS[g]["base"]
            qty = int(rng.choice((0.6, 1.0, 1.5)) * {"svin": 30, "maelk": 300, "aeg": 600}.get(g, 250))
            qty = max(10, qty // 10 * 10)
            reward = int(qty * base * rng.uniform(1.3, 1.6) * (1 + TOWN_PAY * self.town_lvl()) / 50 + 1) * 50
            c.update(kind="deliver", who=who, good=g, qty=qty, reward=reward, days=40)
        else:
            kinds = ["plow", "harvest", "fertilize"]
            if 2 <= m <= 9 and self.opts["pests"]:
                kinds.append("spray")
            sowable = [k for k in CROPS if m in CROPS[k]["months"] and k != "graes" and crop_good(k)]
            if sowable:
                kinds.append("sow")
            kind = rng.choice(kinds)
            if kind == "harvest" and not (5 <= m <= 9):
                kind = "plow"
            cells = self._contract_area(rng)
            if not cells:
                return
            crop = rng.choice(sowable) if kind == "sow" else rng.choice(("hvede", "raps", "majs"))
            reward = int(len(cells) * WORK_PAY[kind] * (1 + TOWN_PAY * self.town_lvl()) / 50 + 1) * 50
            if kind == "sow":
                reward += len(cells) * CROPS[crop]["seed"]
            c.update(kind=kind, who="Gårdejer " + rng.choice(NEIGHBOURS), cells=[list(p) for p in cells],
                     crop=crop, reward=reward, days=25)
        self.contracts.append(c)

    def _setup_contract_field(self, c, pid):
        T = self.tiles
        for x, y in c["cells"]:
            t = T[y][x]
            t.o = pid
            t.clear_crop()
            self.ctiles[(x, y)] = c["id"]
            if c["kind"] == "plow":
                t.t = "grass"
            else:
                t.t, t.m, t.n = "field", 60.0, 60.0
                if c["kind"] == "harvest":
                    t.crop, t.g, t.h = c["crop"], 1.0, 90.0
                elif c["kind"] in ("spray", "fertilize"):
                    t.crop, t.g = c["crop"], 0.4
                    if c["kind"] == "spray":
                        t.pest, t.wd = 1, 50.0
                    else:
                        t.n = 20.0
            self.touch(x, y)

    def _contract_done(self, c):
        T = self.tiles
        k = c["kind"]
        for x, y in c["cells"]:
            t = T[y][x]
            if k == "plow" and not (t.t == "field" and not t.crop):
                return False
            if k == "harvest" and t.crop:
                return False
            if k == "sow" and t.crop != c["crop"]:
                return False
            if k == "spray" and t.pest:
                return False
            if k == "fertilize" and t.n < 50:
                return False
        return True

    def _release_contract(self, c):
        for x, y in c.get("cells", []):
            t = self.tiles[y][x]
            t.o = -1
            self.ctiles.pop((x, y), None)
            self.touch(x, y)
        p = self.players.get(c["pid"])
        cells = {tuple(q) for q in c.get("cells", [])}
        if p and cells:
            for j in p["jobs"]:
                j["tiles"] = [q for q in j["tiles"] if tuple(q) not in cells]
            p["jobs"] = [j for j in p["jobs"] if j["tiles"]]

    # ── leveringsaftaler ───────────────────────────────────────────────────────
    def _deal_take(self, p, g, qty):
        """Sælger man en vare, der er en aftale om, går den til aftalen først. → (betaling, rest til markedet)"""
        rev, left = 0.0, qty
        for d in list(p.get("deals", [])):
            if d["good"] != g or left <= 0:
                continue
            n = min(left, d["qty"] - d["done"])
            if n <= 0:
                continue
            d["done"] += n
            left -= n
            rev += n * d["price"]
            if d["done"] >= d["qty"]:
                p["deals"].remove(d)
                p["deals_ok"] = p.get("deals_ok", 0) + 1
                self.log(f"Aftalen med {d['buyer'].lower()} er opfyldt: {d['qty']} {GOODS[g]['navn'].lower()} "
                         f"til {fmt_price(d['price'])}.", p["id"], "good")
        return rev, left

    def deal_value(self, d):
        return d["qty"] * d["price"]

    def _deals_day(self):
        for o in list(self.deal_offers):
            if self.day > o["until"]:
                self.deal_offers.remove(o)
        for p in self.players.values():
            for d in list(p.get("deals", [])):
                if self.day <= d["due"]:
                    continue
                miss = d["qty"] - d["done"]
                fine = int(miss * d["price"] * DEAL_PENALTY)
                p["money"] -= fine
                self.book(p, "opgaver", -fine)
                p["deals"].remove(d)
                self.log(f"Fristen for aftalen med {d['buyer'].lower()} er overskredet – der manglede {int(miss)} "
                         f"{GOODS[d['good']]['navn'].lower()}. Bod: {kr(fine)}.", p["id"], "warn")
        if self.day % DAYS_PER_MONTH == 1 and len(self.deal_offers) < 3 and self.players:
            for _ in range(self.rng.choice((1, 1, 2))):
                self._new_deal_offer()
        for p in self.ai_players():                    # naboerne snupper også en aftale en gang imellem
            if self.deal_offers and len(p.get("deals", [])) < 1 and self.rng.random() < 0.04:
                o = self.rng.choice(self.deal_offers)
                g = o["good"]
                makes = p["inv"].get(g, 0) >= 1 or (g == "svin" and p["pigs"]) or (g == "maelk" and p["cows"]) or \
                    (g == "aeg" and p["chickens"]) or g in self.stats(p["id"])["crops"]
                if makes:
                    self.act_deal(p["id"], o["id"], "take")

    def _new_deal_offer(self):
        rng = self.rng
        buyer, g, (lo, hi) = rng.choice(DEAL_TYPES)
        if any(o["good"] == g for o in self.deal_offers):
            return
        qty = int(rng.randint(lo, hi) * (1 + 0.15 * self.town_lvl()))
        qty = max(10, int(round(qty / 10.0)) * 10)
        price = round(max(self.market[g]["p"], GOODS[g]["base"]) * rng.uniform(1.15, 1.32), 2)
        o = {"id": self.nid, "buyer": buyer, "good": g, "qty": qty, "price": price,
             "until": self.day + 15, "days": rng.choice((60, 75, 90, 120))}
        self.nid += 1
        self.deal_offers.append(o)
        self.log(f"Nyt tilbud om leveringsaftale: {buyer} vil købe {qty} {GOODS[g]['navn'].lower()} til "
                 f"{fmt_price(price)} (se fanen Opgaver).", None, "info")

    def act_deal(self, pid, oid, op):
        p = self.players.get(pid)
        if not p:
            return
        if op == "take":
            o = next((o for o in self.deal_offers if o["id"] == oid), None)
            if not o:
                self.log("Tilbuddet er væk – en anden har taget det.", pid, "err")
                return
            if len(p.setdefault("deals", [])) >= MAX_DEALS:
                self.log(f"Du kan højst have {MAX_DEALS} leveringsaftaler ad gangen.", pid, "err")
                return
            self.deal_offers.remove(o)
            d = dict(o, done=0, due=self.day + o["days"])
            p["deals"].append(d)
            self.log(f"Du har indgået en aftale med {o['buyer'].lower()}: {o['qty']} "
                     f"{GOODS[o['good']]['navn'].lower()} til {fmt_price(o['price'])} inden "
                     f"{o['days']} dage. Det, du sælger af varen, går til aftalen først.", pid, "good")
            for q in self.players.values():
                if q["id"] != pid and not q.get("ai"):
                    self.log(f"{p['name']} har indgået leveringsaftalen med {o['buyer'].lower()}.", q["id"], "info")
        elif op == "deliver":
            d = next((d for d in p.get("deals", []) if d["id"] == oid), None)
            if d:
                n = min(int(p["inv"].get(d["good"], 0)), d["qty"] - d["done"])
                if n <= 0:
                    self.log(f"Du har ingen {GOODS[d['good']]['navn'].lower()} på lager.", pid, "err")
                    return
                self.act_sell(pid, d["good"], n)

    # ── maskinstation mellem gårdene ─────────────────────────────────────────
    def _ms_tile(self, tr, p, job, t, c):
        """Ét felt for en anden gård: kunden betaler såsæd/gødning og arbejdslønnen, høsten går til kunden."""
        cust = self.players.get(job["for"])
        if not cust:
            return False
        total, rent_c, gylle = self.job_cost(cust, job["tool"], t, job["crop"], tr["k"])
        if total is None:
            return False
        inputs = total - rent_c
        fee = job.get("fee", 0)
        if cust["money"] < inputs + fee - self._stock_part(cust, job["tool"], job["crop"], gylle) and \
                job["tool"] != "harvest":
            if not job.get("broke"):
                job["broke"] = True
                self.log(f"{cust['name']} har ikke penge til at betale for mere arbejde.", p["id"], "warn")
                self.log(f"Du har ikke penge nok til at betale {p['name']} for arbejdet på din mark – det er stoppet. "
                         "Lån i banken eller sælg noget, så kan opgaven bestilles igen.", cust["id"], "warn")
            return False
        if gylle and job["tool"] == "fertilize":
            cust["gylle"] -= GYLLE_PER_TILE
        self._pay_work(cust, job["tool"], job["crop"], gylle, inputs, tr, c)
        rent_b = self.rent(p, job["tool"], tr["k"])       # maskinstationen lejer selv redskabet, hvis den mangler det
        cust["money"] -= fee
        self.book(cust, "markarbejde", -fee)
        p["money"] += fee - rent_b
        self.book(p, "opgaver", fee)
        if rent_b:
            self.book(p, "markarbejde", -rent_b)
        job["earn"] = job.get("earn", 0) + fee
        job["spent"] = job.get("spent", 0) + inputs
        self._burn(tr, FUEL_TILE)
        self._apply(job["tool"], t, job["crop"], cust, job, pos=c, gylle=gylle, by=tr["k"])
        self.touch(c[0], c[1])
        return True

    def ms_can(self, p, tool):
        """Kan gården påtage sig dette arbejde for andre? (har maskinen til det)"""
        own = [k for _, k in self.vehicles_of(p["id"])]
        if tool == "harvest":
            return any(vkind(k) == "combine" for k in own)
        return any(vkind(k) == "tractor" for k in own) and (tool == "plow" or self.owns_tool(p, tool))

    def act_ms(self, pid, op, msg):
        p = self.players.get(pid)
        if not p:
            return
        if op == "ask":                                    # kunden bestiller en planlagt opgave hos en anden
            job = self._job(pid, int(msg.get("job", -1)))
            to = self.players.get(int(msg.get("to", -1)))
            if not job or not to or to["id"] == pid or job.get("for") is not None or job["tool"] == "snow":
                return
            if any(r["job"] == job["id"] and r["from"] == pid for r in self.ms_req):
                self.log("Den opgave er allerede bestilt – vent på svar.", pid, "err")
                return
            fee = int(clamp(int(msg.get("fee", MS_FEE.get(job["tool"], 20))), 1, 500))
            r = {"id": self.nid, "from": pid, "to": to["id"], "job": job["id"], "tool": job["tool"],
                 "crop": job.get("crop"), "n": len(job["tiles"]), "fee": fee, "made": self.day}
            self.nid += 1
            self.ms_req.append(r)
            self.log(f"Du har bedt {to['name']} om {JOB_NAMES[job['tool']].lower()} af {r['n']} felter for "
                     f"{kr(fee)} pr. felt.", pid, "info")
            self.log(f"{p['name']} vil have dig til at stå for {JOB_NAMES[job['tool']].lower()} af {r['n']} felter "
                     f"for {kr(fee)} pr. felt ({kr(fee * r['n'])}). Se fanen Opgaver.", to["id"], "big")
            return
        r = next((r for r in self.ms_req if r["id"] == int(msg.get("id", -1))), None)
        if op in ("accept", "decline") and r and r["to"] == pid:
            self.ms_req.remove(r)
            cust = self.players.get(r["from"])
            job = self._job(r["from"], r["job"]) if cust else None
            if op == "decline" or not job:
                if cust:
                    self.log(f"{p['name']} kan ikke tage {JOB_NAMES[r['tool']].lower()} for dig.", cust["id"], "warn")
                return
            if not self.ms_can(p, r["tool"]):
                self.log(f"Du har ikke maskinen til {JOB_NAMES[r['tool']].lower()}.", pid, "err")
                self.ms_req.append(r)
                return
            cust["jobs"].remove(job)
            job = dict(job, **{"for": cust["id"], "fee": r["fee"], "earn": 0, "spent": 0, "yield": {}})
            p["jobs"].append(job)
            self.log(f"Du har taget opgaven for {cust['name']}: {JOB_NAMES[r['tool']].lower()} af {r['n']} felter. "
                     "Felterne er markeret på kortet – kør derud med dine maskiner.", pid, "good")
            self.log(f"{p['name']} står for {JOB_NAMES[r['tool']].lower()} af {r['n']} felter for dig "
                     f"({kr(r['fee'])} pr. felt).", cust["id"], "good")
        elif op == "cancel":                               # maskinstationen opgiver – opgaven går tilbage til kunden
            job = self._job(pid, int(msg.get("job", -1)))
            if not job or job.get("for") is None:
                return
            p["jobs"].remove(job)
            cust = self.players.get(job["for"])
            if cust and job["tiles"]:
                back = {k: v for k, v in job.items() if k not in ("for", "fee", "earn")}
                cust["jobs"].append(back)
                self.log(f"{p['name']} har opgivet {JOB_NAMES[job['tool']].lower()} – de resterende "
                         f"{len(job['tiles'])} felter er lagt tilbage i dine opgaver.", cust["id"], "warn")
            self.log("Du har opgivet maskinstationsopgaven.", pid, "warn")

    # ── udlejning af maskiner mellem gårdene ─────────────────────────────────
    def rent_item_price(self, item):
        """Foreslået lejepris pr. dag."""
        if item.startswith("h:"):
            return 60
        if item.startswith("v"):
            tr = next((t for t in self.tractors if t["id"] == int(item[1:])), None) if self.tractors else \
                next((t for t in self.tractor_view if t[0] == int(item[1:])), None)
            k = (tr["k"] if isinstance(tr, dict) else tr[6]) if tr else None
            base = VEHICLES.get(k, {}).get("price", 20000) * 0.004
        elif item.startswith("e:"):
            base = EQUIPMENT.get(item[2:], {}).get("price", 5000) * 0.008
        else:
            base = WAGONS.get(item[2:].split("#")[0], {}).get("price", 5000) * 0.008
        return max(20, int(round(base / 10.0)) * 10)

    def rentable(self, p):
        """Det, gården kan sætte til leje: egne maskiner, redskaber og vogne (ikke det, den selv har lejet)."""
        lent = {r["item"] for r in self.rentals}
        mine_in = {r["item"] for r in self.rentals if r["renter"] == p["id"]}
        out = []
        for it in self.owned_items(p) + [f"h:{h[0]},{h[1]}" for h in p.get("huts", [])]:
            if it.startswith("w:"):
                it = it.split("#")[0] + "#0"
            if it not in out and it not in mine_in and (it not in lent or it.startswith("h:")):
                out.append(it)                              # en jagthytte kan lejes af flere på én gang
        return out

    def _move_item(self, item, frm, to):
        """Flyt en maskine, et redskab eller en vogn fra én gård til en anden (udlejning og aflevering)."""
        pf, pt = self.players.get(frm), self.players.get(to)
        if not pf or not pt:
            return False
        if item.startswith("h:"):                          # jagthytten bliver stående – man får lov at bruge den
            return any(f"h:{h[0]},{h[1]}" == item for h in (pf.get("huts", []) + pt.get("huts", [])))
        if item.startswith("v"):
            tr = next((t for t in self.tractors if t["id"] == int(item[1:]) and t["o"] == frm), None)
            if not tr:
                return False
            if tr["s"] == "manual":
                self._release(tr)
            self._haul_abort(tr)
            tr.update(o=to, s="idle", tool=None, j=None, path=None, helper=False, hitch=None, show=None)
        elif item.startswith("e:"):
            k = item[2:]
            if k not in pf.get("equip", []):
                return False
            pf["equip"].remove(k)
            pt.setdefault("equip", []).append(k)
        else:
            k = item[2:].split("#")[0]
            if pf.get("wagons", {}).get(k, 0) < 1:
                return False
            pf["wagons"][k] -= 1
            pt["wagons"][k] = pt["wagons"].get(k, 0) + 1
            pf.get("wload", {}).pop(f"w:{k}#{pf['wagons'][k]}", None)
        self._sync_park(pf, True)
        self._sync_park(pt, True)
        return True

    def act_rent(self, pid, op, msg):
        p = self.players.get(pid)
        if not p:
            return
        if op == "list":
            item = str(msg.get("item", ""))
            if item not in self.rentable(p) or any(o["item"] == item and o["owner"] == pid for o in self.rent_offers):
                return
            price = int(clamp(int(msg.get("price", self.rent_item_price(item))), 10, 5000))
            self.rent_offers.append({"id": self.nid, "owner": pid, "item": item, "price": price,
                                     "name": self.item_name(item)})
            self.nid += 1
            self.log(f"{self.item_name(item)} er sat til leje for {kr(price)} pr. dag.", pid, "info")
            for q in self.players.values():
                if q["id"] != pid and not q.get("ai"):
                    self.log(f"{p['name']} udlejer {self.item_name(item).lower()} ({kr(price)} pr. dag) – se Handel.",
                             q["id"], "info")
        elif op == "unlist":
            self.rent_offers = [o for o in self.rent_offers if not (o["id"] == int(msg.get("id", -1)) and
                                                                    o["owner"] == pid)]
        elif op == "take":
            o = next((o for o in self.rent_offers if o["id"] == int(msg.get("id", -1))), None)
            days = int(msg.get("days", 3))
            if not o or o["owner"] == pid or days not in RENT_DAYS:
                return
            owner = self.players.get(o["owner"])
            if o["item"].startswith("h:") and any(r["item"] == o["item"] and r["renter"] == pid for r in self.rentals):
                self.log("Du har allerede lejet den jagthytte.", pid, "info")
                return
            cost = o["price"] * days
            if not owner or (p["money"] < cost and not self.sandbox()):
                self.log("Ikke nok penge til lejen.", pid, "err")
                return
            if not self._move_item(o["item"], o["owner"], pid):
                self.rent_offers.remove(o)
                self.log("Den er ikke til leje længere.", pid, "err")
                return
            if not o["item"].startswith("h:"):              # jagthytten forbliver til leje for de andre
                self.rent_offers.remove(o)
            p["money"] -= cost
            owner["money"] += cost
            self.book(p, "maskiner", -cost)
            self.book(owner, "handel", cost)
            item = o["item"]
            if item.startswith("w:"):                      # vognen hedder noget andet hos den, der lejer den
                k = item[2:].split("#")[0]
                item = f"w:{k}#{p['wagons'][k] - 1}"
            self.rentals.append({"id": self.nid, "owner": o["owner"], "renter": pid, "item": item,
                                 "orig": o["item"], "name": o["name"], "until": self.day + days, "price": o["price"]})
            self.nid += 1
            if o["item"].startswith("h:"):
                self.log(f"Du har lejet {owner['name']}s jagthytte i {days} dage (-{kr(cost)}). Kør derud og tryk J – "
                         "går I på jagt samtidig, bliver det en fællesjagt med mere vildt.", pid, "good")
            else:
                self.log(f"Du har lejet {o['name'].lower()} af {owner['name']} i {days} dage (-{kr(cost)}). "
                         "Den står hos dig nu.", pid, "good")
            self.log(f"{p['name']} har lejet din {o['name'].lower()} i {days} dage (+{kr(cost)}).", o["owner"], "good")
        elif op == "return":
            r = next((r for r in self.rentals if r["id"] == int(msg.get("id", -1)) and r["renter"] == pid), None)
            if r:
                self._end_rental(r)

    def _end_rental(self, r):
        if r in self.rentals:
            self.rentals.remove(r)
        item = r["item"]
        if item.startswith("w:"):
            k = item[2:].split("#")[0]
            q = self.players.get(r["renter"])
            item = f"w:{k}#{max(0, (q or {}).get('wagons', {}).get(k, 1) - 1)}"
        if item.startswith("h:"):
            self.log(f"Lejen af {self.pname(r['owner'])}s jagthytte er udløbet.", r["renter"], "info")
            return
        ok = self._move_item(item, r["renter"], r["owner"])
        if ok:
            self.log(f"{r['name']} er afleveret tilbage til {self.pname(r['owner'])}.", r["renter"], "info")
            self.log(f"Du har fået din {r['name'].lower()} tilbage.", r["owner"], "info")

    def _rent_day(self):
        for r in list(self.rentals):
            if self.day >= r["until"]:
                self._end_rental(r)
        for o in list(self.rent_offers):                  # tilbud på ting, der er solgt, fjernes
            q = self.players.get(o["owner"])
            if not q or o["item"] not in self.rentable(q):
                self.rent_offers.remove(o)
        if self.day % DAYS_PER_MONTH == 3:                # naboerne udlejer en maskine en gang imellem
            for q in self.ai_players():
                if any(o["owner"] == q["id"] for o in self.rent_offers) or self.rng.random() > 0.35:
                    continue
                cand = [it for it in self.rentable(q) if it.startswith("e:") or
                        (it.startswith("v") and vkind(next(t["k"] for t in self.tractors if t["id"] == int(it[1:])))
                         in ("combine", "truck"))]
                if cand:
                    it = self.rng.choice(cand)
                    self.act_rent(q["id"], "list", {"item": it, "price": int(self.rent_item_price(it) * 1.2)})

    # ── byens fælles bestillinger ─────────────────────────────────────────────
    def _torder_day(self):
        for o in list(self.torders):
            if o.get("done") is None and self.day > o["due"]:
                o["done"] = False
                tot = sum(o["have"].values())
                self.log(f"{o['who']} fik kun {int(tot)} af {o['qty']} {GOODS[o['good']]['navn'].lower()} – ingen "
                         "bonus denne gang. Det leverede er betalt.", None, "warn")
            if o.get("done") is not None and self.day > max(o["due"], o.get("end", o["due"])) + 10:
                self.torders.remove(o)
        if len([o for o in self.torders if o.get("done") is None]) < TOWN_ORDER_MAX and self.players and \
                self.day % DAYS_PER_MONTH == 12 and self.rng.random() < 0.6:
            m = self.month()
            busy = {(o["who"], o["good"]) for o in self.torders}
            long_ = any(o.get("done") is None and o.get("long") for o in self.torders)
            cands = [t for t in TOWN_ORDERS if m in t[3] and (t[0], t[1]) not in busy and
                     not (long_ and t[4] >= 300)]                 # højst én helårsordning ad gangen
            if cands:
                who, g, qty, _, days = self.rng.choice(cands)
                qty = int(qty * (1 + 0.25 * self.town_lvl()) * (0.8 + 0.2 * len([p for p in self.players.values()
                                                                                   if not p.get("ai")])))
                qty = int(round(qty / 50.0)) * 50
                price = round(max(self.market[g]["p"], GOODS[g]["base"]) * 1.1, 2)
                bonus = int(qty * GOODS[g]["base"] * 0.35 / 100 + 1) * 100
                self.torders.append({"id": self.nid, "who": who, "good": g, "qty": qty, "price": price, "bonus": bonus,
                                     "have": {}, "due": self.day + days, "done": None, "long": days >= 300})
                self.nid += 1
                frist = "inden et år" if days >= 300 else f"inden {days} dage"
                self.log(f"{who} i {TOWN_NAME} bestiller {qty} {GOODS[g]['navn'].lower()} {frist} – alle gårde kan "
                         f"levere (fanen Fælles). Bliver det hele leveret, deles {kr(bonus)} i bonus.", None, "big")
                self.add_news(f"{who} mangler {GOODS[g]['navn'].lower()}",
                              f"{who} skal bruge {qty} {GOODS[g]['navn'].lower()} {frist} og betaler "
                              f"{fmt_price(price)}. Når det hele er leveret, deles en bonus på {kr(bonus)} mellem "
                              "gårdene efter, hvor meget hver har leveret.")
        for o in self.torders:
            if o.get("done") is None:                      # naboerne leverer også lidt
                for p in self.ai_players():
                    if self.rng.random() < 0.15 and p["inv"].get(o["good"], 0) >= 10:
                        self.act_torder(p["id"], int(min(p["inv"][o["good"]] * 0.5, o["qty"] * 0.2)), o["id"])

    def act_torder(self, pid, qty, oid=None):
        p = self.players.get(pid)
        o = next((o for o in self.torders if o["id"] == oid), None) if oid is not None else \
            next((o for o in self.torders if o.get("done") is None), None)
        if not p or not o or o.get("done") is not None or qty <= 0:
            return
        g = o["good"]
        left = o["qty"] - sum(o["have"].values())
        n = int(min(qty, left, p["inv"].get(g, 0)))
        if n <= 0:
            self.log(f"Du har ingen {GOODS[g]['navn'].lower()} at levere.", pid, "err")
            return
        p["inv"][g] -= n
        pay = n * o["price"]
        p["money"] += pay
        self.book(p, "salg", pay)
        self.town_add(pay)
        o["have"][str(pid)] = o["have"].get(str(pid), 0) + n
        self.log(f"Du leverede {n} {GOODS[g]['navn'].lower()} til {o['who'].lower()} (+{kr(pay)}).", pid, "good")
        if sum(o["have"].values()) >= o["qty"]:
            o["done"], o["end"] = True, self.day
            parts = []
            for k, v in o["have"].items():
                q = self.players.get(int(k))
                if not q:
                    continue
                b = int(o["bonus"] * v / o["qty"])
                q["money"] += b
                self.book(q, "opgaver", b)
                parts.append(f"{q['name']} {int(100 * v / o['qty'])}%")
                self.log(f"{o['who']} har fået alt, hvad der skulle bruges! Din andel af bonussen: {kr(b)}.",
                         q["id"], "good")
            self.add_news(f"{o['who']} fik sine {GOODS[g]['navn'].lower()}",
                          f"Egnens gårde leverede tilsammen {o['qty']} {GOODS[g]['navn'].lower()}: " +
                          ", ".join(parts) + ".")

    def _ms_day(self):
        for r in list(self.ms_req):
            to = self.players.get(r["to"])
            if self.day - r["made"] > MS_EXPIRE or not to:
                self.ms_req.remove(r)
                if r["from"] in self.players:
                    self.log(f"Ingen svar på din bestilling af {JOB_NAMES[r['tool']].lower()} – den er annulleret.",
                             r["from"], "warn")
            elif to.get("ai") and self.day - r["made"] >= 1:     # computernaboen svarer dagen efter
                ok = self.ms_can(to, r["tool"]) and r["fee"] >= MS_FEE.get(r["tool"], 20) * 0.9 and \
                    sum(1 for j in to["jobs"] if j.get("for") is not None) < 2
                self.act_ms(to["id"], "accept" if ok else "decline", {"id": r["id"]})

    def act_contract(self, pid, cid, op):
        p = self.players.get(pid)
        c = next((c for c in self.contracts if c["id"] == cid), None)
        if not p or not c:
            return
        if op == "accept":
            if c["pid"] is not None:
                self.log("Den opgave er allerede taget.", pid, "err")
                return
            if sum(1 for q in self.contracts if q["pid"] == pid) >= MAX_CONTRACTS:
                self.log(f"Du kan højst have {MAX_CONTRACTS} opgaver ad gangen.", pid, "err")
                return
            c["pid"], c["deadline"] = pid, self.day + c["days"]
            if c["kind"] != "deliver":
                self._setup_contract_field(c, pid)
                self.log(f"Du har påtaget dig opgaven for {c['who']}: {self.contract_title(c).lower()}. "
                         "Marken er markeret med din farve – brug dine egne maskiner.", pid, "good")
            else:
                self.log(f"Aftale med {c['who']}: lever {c['qty']} {GOODS[c['good']]['navn'].lower()} "
                         f"inden {c['days']} dage.", pid, "good")
            if len(self.players) > 1:
                self.log(f"{p['name']} tog en opgave for {c['who']}.", None, "info")
        elif op == "deliver" and c["pid"] == pid and c["kind"] == "deliver":
            if p["inv"][c["good"]] < c["qty"]:
                self.log(f"Du har kun {int(p['inv'][c['good']])} af {c['qty']}.", pid, "err")
                return
            p["inv"][c["good"]] -= c["qty"]
            p["money"] += c["reward"]
            self.book(p, "opgaver", c["reward"])
            self.town_add(c["reward"])
            self.contracts.remove(c)
            self.log(f"{c['who']} har modtaget leverancen og betalt {kr(c['reward'])}.", pid, "good")
        elif op == "cancel" and c["pid"] == pid:
            self._release_contract(c)
            self.contracts.remove(c)
            self.log("Du har opgivet opgaven.", pid, "warn")

    def contract_title(self, c):
        if c["kind"] == "deliver":
            return f"Lever {c['qty']} {GOODS[c['good']]['navn'].lower()}"
        n = len(c["cells"])
        crop = CROPS[c["crop"]]["navn"].lower()
        return {"plow": f"Pløj {n} felter", "harvest": f"Høst {n} felter {crop}",
                "sow": f"Så {n} felter med {crop}", "spray": f"Sprøjt {n} felter mod bladlus og ukrudt",
                "fertilize": f"Gød {n} felter"}[c["kind"]]

    def _contracts_day(self):
        for c in list(self.contracts):
            if c["pid"] is None:
                if self.day - c["made"] > 25:
                    self.contracts.remove(c)
                continue
            if c["kind"] != "deliver" and self._contract_done(c):
                p = self.players.get(c["pid"])
                if p:
                    p["money"] += c["reward"]
                    self.book(p, "opgaver", c["reward"])
                    self.log(f"{c['who']} er tilfreds med arbejdet og betaler {kr(c['reward'])}.", c["pid"], "good")
                self._release_contract(c)
                self.contracts.remove(c)
            elif self.day > c["deadline"]:
                self._release_contract(c)
                self.contracts.remove(c)
                self.log(f"Fristen for opgaven hos {c['who']} er overskredet. Aftalen er annulleret.",
                         c["pid"], "warn")
        if self.day % 5 == 0 and sum(1 for c in self.contracts if c["pid"] is None) < MAX_OFFERS + self.town_lvl() // 2 and self.players:
            self._new_offer()

    def act_send(self, pid, to, what, qty):
        p, q = self.players.get(pid), self.players.get(to)
        if not p or not q or pid == to or qty <= 0:
            return
        if what == "penge":
            qty = min(qty, int(max(0, p["money"])))
            if qty <= 0:
                self.log("Ikke nok penge.", pid, "err")
                return
            p["money"] -= qty
            q["money"] += qty
            self.book(p, "handel", -qty)
            self.book(q, "handel", qty)
            desc = kr(qty)
        elif what in GOODS:
            qty = min(qty, int(p["inv"][what]))
            if qty <= 0:
                self.log(f"Du har ingen {GOODS[what]['navn'].lower()}.", pid, "err")
                return
            p["inv"][what] -= qty
            q["inv"][what] += qty
            desc = f"{qty} {GOODS[what]['navn'].lower()}"
        else:
            return
        self.log(f"Du sendte {desc} til {q['name']}.", pid, "info")
        self.log(f"{p['name']} sendte dig {desc}.", to, "good")

    def act_contribute(self, pid, proj, what, qty):
        p = self.players.get(pid)
        if not p or proj not in PROJECTS or qty <= 0:
            return
        pr = self.projects[proj]
        need = PROJECTS[proj]["need"]
        if pr["done"] or what not in need:
            return
        rem = need[what] - pr["have"][what]
        avail = int(max(0, p["money"])) if what == "penge" else int(p.get("gylle", 0)) if what == "gylle" else \
            int(p["inv"][what])
        qty = min(qty, rem, avail)
        if qty <= 0:
            self.log("Du har ikke nok at bidrage med.", pid, "err")
            return
        if what == "penge":
            p["money"] -= qty
            self.book(p, "faelles", -qty)
            value, desc = qty, kr(qty)
        elif what == "gylle":
            p["gylle"] -= qty
            value, desc = qty * 2, f"{qty} enheder gylle"
        else:
            p["inv"][what] -= qty
            value = qty * self.market[what]["p"]
            desc = f"{qty} {GOODS[what]['navn'].lower()}"
        self.town_add(value)
        pr["have"][what] += qty
        pr["by"][p["name"]] = int(pr["by"].get(p["name"], 0) + value)
        self.log(f"{p['name']} bidrog med {desc} til {PROJECTS[proj]['navn'].lower()}.", None, "info")
        if all(pr["have"][r] >= n for r, n in need.items()):
            pr["done"] = True
            x, y = PROJECTS[proj]["pos"]
            self.tiles[y][x].b = "proj:" + proj
            self.touch(x, y)
            self.log(f"{PROJECTS[proj]['navn']} er færdigbygget! {PROJECTS[proj]['effekt']}", None, "big")
            self.add_news(f"{PROJECTS[proj]['navn']} er indviet", f"Egnens landmænd har sammen bygget "
                          f"{PROJECTS[proj]['navn'].lower()}. {PROJECTS[proj]['effekt']}", big=True)

    # ── banken ───────────────────────────────────────────────────────────────
    def loans(self, p):
        """Spillerens lån: [{amt: restgæld, orig: lånt, rate: afdrag pr. måned, left: måneder tilbage}]."""
        ls = p.get("loans")
        if ls is None:
            ls = p["loans"] = []
            if p.get("loan", 0) > 0:                     # ældre gemt spil: ét stort lån, der betales af over et år
                ls.append({"amt": float(p["loan"]), "orig": float(p["loan"]), "rate": p["loan"] / LOAN_MONTHS,
                           "left": LOAN_MONTHS, "day": self.day})
        return ls

    def _sync_loan(self, p):
        p["loan"] = int(round(sum(l_["amt"] for l_ in self.loans(p))))

    def loan_room(self, p):
        """(hvor meget der kan lånes nu, hvorfor ikke mere)"""
        if self.sandbox():
            return 0, "Ingen lån i sandkassen."
        if len(self.loans(p)) >= LOAN_SLOTS:
            return 0, f"Du har {LOAN_SLOTS} lån. Banken låner først ud igen, når et af dem er betalt ud."
        ly = p.get("lent_yr") or {}
        used = ly.get("sum", 0) if ly.get("year") == self.year() else 0
        room = max(0, LOAN_YEAR_MAX - used)
        if room <= 0:
            return 0, f"Du har lånt {kr(LOAN_YEAR_MAX)} i år – mere kan du ikke låne før nytår."
        return room, ""

    def act_loan(self, pid, delta=0, amt=None, payoff=None):
        p = self.players.get(pid)
        if not p:
            return
        ls = self.loans(p)
        if amt is None and delta > 0:
            amt = LOAN_STEP
        if amt:
            room, why = self.loan_room(p)
            n = min(int(amt), room)
            if n < 1000:
                self.log(why or "Banken kan ikke låne dig mere lige nu.", pid, "err")
                return
            ls.append({"amt": float(n), "orig": float(n), "rate": n / LOAN_MONTHS, "left": LOAN_MONTHS,
                       "day": self.day})
            ly = p.get("lent_yr") or {}
            if ly.get("year") != self.year():
                ly = {"year": self.year(), "sum": 0}
            ly["sum"] += n
            p["lent_yr"] = ly
            p["money"] += n
            self._sync_loan(p)
            self.log(f"Du lånte {kr(n)} i banken ({int(LOAN_RATE * 100)}% rente om året). Det betales tilbage med "
                     f"{kr(n / LOAN_MONTHS)} om måneden i {LOAN_MONTHS} måneder.", pid, "info")
            return
        if payoff is None and delta < 0 and ls:
            payoff = min(range(len(ls)), key=lambda k: ls[k]["amt"])
        if payoff is None or not (0 <= int(payoff) < len(ls)):
            return
        l_ = ls[int(payoff)]
        if p["money"] < l_["amt"]:
            self.log(f"Du mangler penge til at indfri lånet ({kr(l_['amt'])}).", pid, "err")
            return
        p["money"] -= l_["amt"]
        ls.pop(int(payoff))
        self._sync_loan(p)
        self.log(f"Du indfriede et lån på {kr(l_['amt'])}. Nu kan du låne igen, hvis du får brug for det.", pid, "good")

    def _pay_loans(self, p):
        """Hver måned: renter af restgælden + en rate (afdrag). Returnerer (renter, afdrag)."""
        rent = paid = 0.0
        ls = self.loans(p)
        for l_ in list(ls):
            r = l_["amt"] * LOAN_RATE / 12
            a = min(l_["amt"], l_["rate"])
            l_["amt"] -= a
            l_["left"] -= 1
            rent += r
            paid += a
            if l_["amt"] < 1 or l_["left"] <= 0:
                paid += max(0.0, l_["amt"])
                ls.remove(l_)
                self.log(f"Et lån på {kr(l_['orig'])} er betalt ud. Du kan låne igen i banken.", p["id"], "good")
        p["money"] -= rent + paid
        self._sync_loan(p)
        return rent, paid

    # ── køretøjer (kører i realtid, målt i spildage) ─────────────────────────
    def pace(self):
        """Årets længde (1.0 = som før). En dag varer så meget længere, og maskinerne arbejder lige så meget mere."""
        v = self.opts.get("pace", YEAR_PACE_DEFAULT)
        return v if v in YEAR_PACE else YEAR_PACE_DEFAULT

    def tick(self, days):
        self._sandbox_topup()
        wd = days * self.pace()                 # maskinerne kører i "arbejdsdage" – længere dage, mere arbejde
        for tr in list(self.tractors):
            if tr["s"] != "manual":
                self._drive(tr, wd)

    # ── manuel kørsel ("Styr selv") ──────────────────────────────────────────
    def _veh(self, pid, vid):
        return next((t for t in self.tractors if t["id"] == vid and t["o"] == pid), None)

    def act_drive(self, pid, vid, on, drv=None, dname=None):
        tr = self._veh(pid, vid)
        if not tr:
            return
        who = f"{dname} " if dname and self.shared() else ""
        if on:
            if tr["s"] == "manual":
                if tr["man"].get("drv") != drv:
                    self.log(f"{tr['man'].get('dname') or 'En anden'} kører allerede {vname(tr['k'])} #{vid}.",
                             pid, "err")
                return
            for other in self.tractors:          # man styrer én maskine ad gangen
                if other["o"] == pid and other["s"] == "manual" and other["man"].get("drv") == drv:
                    self._release(other)
            x, y = round(tr["x"]), round(tr["y"])
            cx, cy = VDIRS[tr["d"] % 8]
            door = self.shed_door(x, y)
            if door:                             # kør ud af porten foran, så man kan se maskinen
                (x, y), (cx, cy) = door
            hdg = math.atan2((cx + cy) * HALF_H, (cx - cy) * HALF_W)     # retning på skærmen
            self._haul_abort(tr)
            wagon = None
            h = tr.get("hitch") or ""
            if h.startswith("w:") and WAGONS.get(h[2:].split("#")[0], {}).get("cargo") == "grain":
                wagon = h[2:].split("#")[0]                  # en påkoblet tipvogn kan tage last
            tr.update(s="manual", tool=None, j=None, path=None, w=0.0, x=float(x), y=float(y),
                      man={"thr": 0, "turn": 0, "v": 0.0, "hdg": hdg, "tool": None, "crop": "hvede",
                           "last": None, "job": None, "drv": drv, "dname": dname, "wagon": wagon, "cargo": None})
            wl = self.players[pid].get("wload", {}).pop(h, None) if h else None
            ws_ = self.players[pid].get("wshape", {}).pop(h, None) if h else None
            if wl and wagon:
                tr["man"]["cargo"] = {"src": "pile", "load": wl, "s": ws_}
            if who:
                self.log(f"{who}kører nu {vname(tr['k'])} #{vid}.", pid, "info")
            else:
                self.log(f"Du styrer nu {vname(tr['k'])} #{vid}. Op/W giver gas, venstre/højre "
                         "drejer, L sænker/løfter redskabet, K kobler på/af, E styrer frontlæsseren, Esc giver den tilbage.", pid, "info")
        elif tr["s"] == "manual" and tr["man"].get("drv") == drv:
            self._release(tr)
            if self.manual_mode() and not tr.get("helper") and vkind(tr["k"]) != "car":
                self.log(f"{who.strip() + ' ' if who else ''}{'s' if who else 'S'}tillede {vname(tr['k'])} #{vid} "
                         "– den kører hjem og parkerer.", pid, "info")
            else:
                self.log(f"{vname(tr['k'])} #{vid} kører igen selv." if vkind(tr["k"]) != "car"
                         else f"{vname(tr['k'])} kører hjem i garagen.", pid, "info")

    def _release(self, tr):
        self._manual_summary(tr)
        self._cargo_abort(tr)
        m, p = tr.get("man") or {}, self.players.get(tr["o"])
        if m.get("fl") and p:                   # baller i frontlæsseren sættes ned, hvor man slipper
            self._loader_drop(tr, p, self.front_point(tr))
        tr.update(s="idle", tool=None, j=None, path=None, w=0.0, x=float(round(tr["x"])), y=float(round(tr["y"])))
        tr.pop("man", None)

    def release_manual(self, pid, drv=None):
        for tr in self.tractors:
            if tr["o"] == pid and tr["s"] == "manual" and (drv is None or tr["man"].get("drv") == drv):
                self._release(tr)

    def _mine(self, tr, drv):
        return tr and tr["s"] == "manual" and tr["man"].get("drv") == drv

    def act_steer(self, pid, vid, thr, turn, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        tr["man"]["thr"], tr["man"]["turn"] = clamp(thr, -1, 1), clamp(turn, -1, 1)

    def act_pos(self, pid, vid, x, y, hdg, v, drv=None):
        """Klienten kører selv sin maskine (glat styring over netværket) – serveren tjekker, at det er rimeligt."""
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv) or not (math.isfinite(x) and math.isfinite(y)):
            return
        if math.hypot(x - tr["x"], y - tr["y"]) > 3.0:
            return
        x, y = clamp(x, 0.0, self.W - 1.0), clamp(y, 0.0, self.H - 1.0)
        nt = (int(math.floor(x + 0.5)), int(math.floor(y + 0.5)))
        cur = (int(round(tr["x"])), int(round(tr["y"])))
        if nt != cur and (self._blocked(*nt) or self.fence_blocks(cur, nt)):
            return
        m = tr["man"]
        tr["x"], tr["y"] = x, y
        m["hdg"], m["v"], m["cl"] = hdg, clamp(v, -MANUAL_REVERSE, 12.0), time.time()
        tr["d"] = self.hdg_dir(hdg)

    @staticmethod
    def hdg_dir(hdg):
        sx, sy = math.cos(hdg), math.sin(hdg)
        ux, uy = (sx / HALF_W + sy / HALF_H) / 2, (sy / HALF_H - sx / HALF_W) / 2
        return int(round(math.atan2(uy, ux) / (math.pi / 4))) % 8

    def act_helper(self, pid, vid, on):
        tr = self._veh(pid, vid)
        if not tr or tr.get("hire") or vkind(tr["k"]) == "car" or bool(tr.get("helper")) == on:
            return
        tr["helper"] = on
        if on:
            self.log(f"Du har ansat en medhjælper på {vname(tr['k'])} #{vid} ({kr(HELPER_WAGE)} om måneden). "
                     "Den kører nu selv dine planlagte opgaver og transporter.", pid, "good")
        else:
            self.log(f"Medhjælperen på {vname(tr['k'])} #{vid} er afskediget.", pid, "info")

    def manual_tools(self, kind, tr=None):
        out = list(KIND_JOBS[kind]) + (["harvest"] if kind == "tractor" else [])
        if tr is not None and VEHICLES.get(tr["k"], {}).get("mower"):
            out.append("mow")
        if tr is not None and plow_on(tr) and "snow" not in out:
            out.append("snow")
        return out

    def jobs_for(self, tr):
        """De opgaver, maskinen kan tage: dens slags + sne (traktor med sneplov-udstyr, lastbil med sneplov)."""
        kind = vkind(tr["k"])
        jobs = [j for j in KIND_JOBS[kind] if j != "snow"]
        if (kind == "tractor" and self.owns_tool(self.players.get(tr["o"]) or {}, "snow")) or plow_on(tr):
            jobs.append("snow")
        return jobs

    def act_implement(self, pid, vid, tool, crop=None, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        m = tr["man"]
        if tool is not None and tool not in self.manual_tools(vkind(tr["k"]), tr):
            return
        if tool == "sow":
            if crop not in CROPS:
                return
            if self.month() not in CROPS[crop]["months"]:
                self.log(f"{CROPS[crop]['navn']} kan kun sås i {sow_months_str(crop)}.", pid, "err")
                return
            m["crop"] = crop
        if tool == "fell" and vkind(tr["k"]) == "tractor" and not self._fell_ready(self.players[pid]):
            return
        if tool == "snow" and not self._snow_ready(self.players[pid]):
            return
        if tool == "lime" and self.hitch_vis(tr) in ("gylle", "gylle_s"):
            self.log("Kalk spredes med gødningssprederen – ikke med gyllevognen.", pid, "err")
            return
        if tool in ("plow", "sow", "spray", "fertilize", "lime", "fell", "water") and vkind(tr["k"]) == "tractor":
            need = "fertilize" if tool == "lime" else tool
            if self.hitch_tool(tr) != need:            # når man selv kører, bruger man det redskab, der er koblet på
                self.log("Kobl redskabet på først: kør hen til maskinhuset (eller redskabet), bak ind mod det og "
                         "tryk K.", pid, "err")
                return
        self._manual_summary(tr)
        m["tool"] = tool
        m["job"] = {"tool": tool, "crop": m["crop"], "n": 0, "spent": 0, "yield": {}, "lost": 0.0} if tool else None
        m["last"] = None                        # arbejd også det felt, traktoren holder på

    # ── markkort: marker med navne og historik ───────────────────────────────
    def fields_of(self, pid):
        """[(nøgle, [(x, y) …])] – sammenhængende marker (pløjet, sået eller stub) på spillerens jord.
        Nøglen er et fast felt i marken, så navn og historik følger med, selv om marken vokser."""
        cache = getattr(self, "_fcache", None)
        if cache and cache[0] == (self.ver, pid, self.day):
            return cache[1]
        p = self.players.get(pid) or {}
        known = set(p.get("fnames", {})) | set(p.get("fhist", {})) | set(p.get("fplan", {}))
        seen, out = set(), []
        for y in range(self.H):
            for x in range(self.W):
                t = self.tiles[y][x]
                if (x, y) in seen or t.o != pid or t.t not in ("field", "stub"):
                    continue
                comp, todo = [], [(x, y)]
                seen.add((x, y))
                while todo:
                    cx, cy = todo.pop()
                    comp.append((cx, cy))
                    for dx, dy in N4:
                        nx, ny = cx + dx, cy + dy
                        if self.inb(nx, ny) and (nx, ny) not in seen:
                            tt = self.tiles[ny][nx]
                            if tt.o == pid and tt.t in ("field", "stub"):
                                seen.add((nx, ny))
                                todo.append((nx, ny))
                keys = sorted(k for k in (f"{a},{b}" for a, b in comp) if k in known)
                key = keys[0] if keys else "%d,%d" % min(comp, key=lambda c: (c[1], c[0]))
                out.append((key, comp))
        out.sort(key=lambda kc: -len(kc[1]))
        self._fcache = ((self.ver, pid, self.day), out)
        return out

    def field_key(self, pid, x, y):
        for retry in (False, True):
            if retry:
                self._fcache = None                         # marken er lige blevet pløjet – regn forfra
            for key, comp in self.fields_of(pid):
                if (x, y) in comp:
                    return key
        return None

    def field_econ(self, p, key, comp):
        """(brugt i år indtil nu, seneste høstår, udgifter, høstværdi, felter) for en mark."""
        ta = p.get("tacc") or {}
        open_ = sum(ta.get(f"{x},{y}", 0.0) for x, y in comp)
        hist = (p.get("fhist") or {}).get(key, {})
        last = next((yr for yr in sorted(hist, key=int, reverse=True) if hist[yr].get("n") and "rev" in hist[yr]),
                    None)
        if last is None:
            return open_, None, 0.0, 0.0, 0
        h_ = hist[last]
        return open_, int(last), h_.get("cost", 0.0), h_.get("rev", 0.0), h_["n"]

    def field_name(self, p, key, i=None):
        n = p.get("fnames", {}).get(key)
        return n if n else (f"Mark {i + 1}" if i is not None else "Unavngivet mark")

    def _field_note(self, p, pos, what, t, crop, amt, cost=0.0, rev=0.0):
        key = self.field_key(p["id"], int(pos[0]), int(pos[1]))
        if not key:
            return
        hist = p.setdefault("fhist", {}).setdefault(key, {})
        yr = hist.setdefault(str(self.year()), {"sow": {}, "harv": {}, "yield": 0.0, "n": 0, "kc": 0.0, "nut": 0.0,
                                                  "wd": 0.0})
        if what == "sow":
            yr["sow"][crop] = yr["sow"].get(crop, 0) + 1
        else:
            yr["harv"][crop] = yr["harv"].get(crop, 0) + 1
            yr["yield"] += amt
            yr["cost"] = yr.get("cost", 0.0) + cost
            yr["rev"] = yr.get("rev", 0.0) + rev
            yr["n"] += 1
            yr["kc"] += t.kc
            yr["nut"] += t.n
            yr["wd"] += t.wd
        for old in sorted(hist, key=int)[:-6]:              # de seneste 6 år gemmes
            del hist[old]

    def act_fieldname(self, pid, x, y, name):
        p = self.players.get(pid)
        if not p or not self.inb(x, y):
            return
        key = self.field_key(pid, x, y)
        if not key:
            self.log("Det er ikke en af dine marker (pløj den først).", pid, "err")
            return
        name = name.strip()[:22]
        fn = p.setdefault("fnames", {})
        if name:
            fn[key] = name
            self.log(f"Marken hedder nu \"{name}\".", pid, "good")
        else:
            fn.pop(key, None)

    # ── Egnens Dyrskue ───────────────────────────────────────────────────────
    def show_open(self):
        sh = self.show
        return bool(sh and sh.get("year") == self.year() and self.month() == SHOW_MONTH
                    and SHOW_OPEN <= self.dom() <= SHOW_END and sh.get("stage") != "invite")

    def show_entry(self, pid):
        sh = self.show
        return sh["entries"].setdefault(str(pid), {"ok": None, "veh": [], "animals": {}}) if sh else None

    # ── traktortræk ──────────────────────────────────────────────────────────
    def pull_power(self, tr):
        """Trækkraft: motoren, opgraderingerne (vægt, greb og tuning) og slid."""
        v = VEHICLES.get(tr["k"], {})
        upg = tr.get("upg", ())
        pw = v.get("kraft", 0.7)
        pw *= 1.15 if "tuning" in upg else 1.0
        pw *= 1.12 if "frontvaegt" in upg else 1.0
        pw *= 1.10 if "tvilling" in upg else 1.0
        return pw * (1 - min(60.0, tr.get("wear", 0.0)) / 250)

    def pull_entry(self, pid):
        pl = self.pull
        return pl["entries"].setdefault(str(pid), {"ok": None, "tries": []}) if pl else None

    def _pull_invite(self):
        rng = self.rng
        npc = []
        tractors = [k for k, v in VEHICLES.items() if v["kind"] == "tractor" and not v.get("hidden")]
        for n in rng.sample(NEIGHBOURS, 5):
            k = rng.choice(tractors)
            pw = VEHICLES[k]["kraft"] * rng.uniform(0.95, 1.25)
            npc.append([f"Gårdejer {n}", vname(k), round(pull_max(pw) * rng.uniform(0.72, 0.97), 1), k])
        self.pull = {"year": self.year(), "stage": "invite", "entries": {}, "npc": npc, "results": []}
        for p in self.players.values():
            self.pull_entry(p["id"])
            self.log(f"Invitation til traktortræk på {self.pull_place()} {PULL_OPEN}.–{PULL_END}. august! "
                     "Tryk på Traktortræk-knappen øverst for at svare.", p["id"], "big")
        self.add_news("Traktortræk i august",
                      f"Egnens landmænd samles på {self.pull_place()} {PULL_OPEN}.–{PULL_END}. august. Hvem kan "
                      "trække slæden længst? Der er pengepræmier til de tre bedste.")

    def at_pull(self, tr):
        return at_pull_xy(tr["x"], tr["y"])

    @staticmethod
    def pull_place():
        return f"traktortræk-banen uden for {TOWN_NAME}" if PULL_AREA else "festpladsen ved kvægtorvet"

    def pull_open(self):
        pl = self.pull
        return bool(pl and pl.get("year") == self.year() and pl["stage"] == "open")

    def act_pull(self, pid, msg, drv=None):
        p, pl = self.players.get(pid), self.pull
        if not p or not pl or pl.get("year") != self.year():
            return
        e = self.pull_entry(pid)
        op = msg.get("op")
        if op == "reply" and pl["stage"] in ("invite", "open") and e["ok"] is None:
            yes = bool(msg.get("yes"))
            if yes and p["money"] < PULL_FEE:
                self.log("Du har ikke råd til startgebyret.", pid, "err")
                return
            e["ok"] = yes
            if yes:
                p["money"] -= PULL_FEE
                self.book(p, "dyrskue", -PULL_FEE)
                self.log(f"Du er tilmeldt traktortrækket (-{kr(PULL_FEE)}). Kør din traktor til "
                         f"{self.pull_place()} {PULL_OPEN}.–{PULL_END}. august og tryk T.", pid, "good")
            else:
                self.log("Du takkede nej til traktortrækket i år.", pid, "info")
        elif op == "try":
            tr = self._veh(pid, int(msg.get("id", -1)))
            if not self.pull_open() or not e["ok"] or len(e["tries"]) >= PULL_TRIES:
                return
            if not self._mine(tr, drv) or vkind(tr["k"]) != "tractor" or not self.at_pull(tr):
                return
            pw = self.pull_power(tr)
            dist = clamp(float(msg.get("dist", 0)), 0.0, min(PULL_FULL, pull_max(pw) + 3))
            dist = round(dist, 1)
            e["tries"].append([dist, vname(tr["k"])])
            self._wear(tr, 3.0)
            self._burn(tr, 4.0)
            full = dist >= PULL_FULL - 0.05
            best = max(t[0] for t in e["tries"])
            self.log((f"FULL PULL! {vname(tr['k'])} trak slæden hele vejen ({meters(dist)})!" if full else
                      f"Du trak {meters(dist)} med {vname(tr['k'])}.") +
                     f" Bedste: {meters(best)}. Forsøg tilbage: {PULL_TRIES - len(e['tries'])}.",
                     pid, "good" if full else "info")

    def _pull_day(self):
        pl = self.pull
        if not pl or pl.get("year") != self.year():
            return
        m, d = self.month(), self.dom()
        if pl["stage"] == "invite" and m == PULL_MONTH and d >= PULL_OPEN:
            pl["stage"] = "open"
            self._pull_ai_enter()                             # computernaboerne melder sig og kører derud
            for pid_, e in pl["entries"].items():
                if e.get("ok"):
                    self.log(f"Traktortrækket er åbent! Kør din traktor til {self.pull_place()} og tryk T for "
                             f"at trække ({PULL_TRIES} forsøg).", int(pid_), "big")
        if pl["stage"] in ("invite", "open") and (m > PULL_MONTH or (m == PULL_MONTH and d > PULL_END)):
            self._pull_judge()

    def _pull_ai_enter(self):
        for p in self.ai_players():                           # computernaboerne stiller op med deres bedste traktor
            trs = [t for t in self.tractors if t["o"] == p["id"] and vkind(t["k"]) == "tractor" and not t.get("hire")]
            e = self.pull_entry(p["id"])
            if not trs or e.get("ok") is not None or p["money"] < PULL_FEE or self.rng.random() > 0.8:
                continue
            best = max(trs, key=self.pull_power)
            p["money"] -= PULL_FEE
            self.book(p, "dyrskue", -PULL_FEE)
            e["ok"] = True
            e["k"] = best["k"]
            e["tries"] = [[round(pull_max(self.pull_power(best)) * self.rng.uniform(0.74, 0.97), 1), vname(best["k"])]]

    def pull_lineup(self):
        """Traktorerne på parkeringen ved banen, mens trækket står på: [(model, ejer-id eller -1)] – naboerne og
        egnens gårdejere (spillernes egne traktorer kører de selv derud)."""
        pl = self.pull or {}
        out = []
        for pid_, e in sorted(pl.get("entries", {}).items()):
            p = self.players.get(int(pid_))
            if p and p.get("ai") and e.get("ok") and e.get("k"):
                out.append((e["k"], int(pid_)))
        for row in pl.get("npc", []):
            if len(row) > 3 and row[3] in VEHICLES:
                out.append((row[3], -1))
        return out

    def _pull_judge(self):
        pl = self.pull
        self._pull_ai_enter()
        rows = [[r[0], r[2], r[1], None] for r in pl["npc"]]
        for pid_, e in pl["entries"].items():
            p = self.players.get(int(pid_))
            if p and e.get("ok") and e["tries"]:
                best = max(e["tries"], key=lambda t: t[0])
                rows.append([p["name"], best[0], best[1], int(pid_)])
        rows.sort(key=lambda r: -r[1])
        pl["results"] = [[r[0], r[1], r[2], i + 1, r[3]] for i, r in enumerate(rows)]
        pl["stage"] = "done"
        for name, dist, trn, place, pid_ in pl["results"]:
            if pid_ is None:
                continue
            p = self.players[pid_]
            prize = PULL_PRIZES.get(place, 0)
            if prize:
                p["money"] += prize
                self.book(p, "praemie", prize)
            p["pull_best"] = max(p.get("pull_best", 0.0), dist)
            self.log(f"Traktortræk: du blev nr. {place} med {meters(dist)}" +
                     (f" og vandt {kr(prize)}!" if prize else "."), pid_, "good" if prize else "info")
        w = pl["results"][0]
        self.add_news("Traktortrækket er afgjort",
                      f"{w[0]} vandt årets traktortræk i {TOWN_NAME} med {meters(w[1])}" +
                      f" i en {w[2]}. " + ("Publikum jublede over et full pull!" if w[1] >= PULL_FULL - 0.05 else
                                          "Ingen nåede helt til enden af banen i år."), True)

    def _show_invite(self):
        self.show = {"year": self.year(), "stage": "invite", "entries": {}, "results": [], "npc": []}
        for p in self.players.values():
            self.show_entry(p["id"])
            self.log(f"Invitation til Egnens Dyrskue i {TOWN_NAME} {SHOW_JUDGE}. juni! Vis dine bedste maskiner og "
                     "dyr frem – tryk på Dyrskue-knappen øverst for at svare.", p["id"], "big")
        self.add_news("Egnens Dyrskue nærmer sig",
                      f"Dyrskuet holdes på kvægtorvet i {TOWN_NAME} {SHOW_OPEN}.–{SHOW_END}. juni. Bedømmelsen "
                      f"er {SHOW_JUDGE}. juni. Der er rosetter og pengepræmier til de bedste maskiner og dyr – og "
                      "10% messerabat på nye maskiner.")

    def _show_spot(self, tr):
        sh = self.show or {}
        ids = [v for e in sh.get("entries", {}).values() for v in e.get("veh", [])]
        i = ids.index(tr["id"]) if tr["id"] in ids else 0
        return SHOW_SPOTS[i % len(SHOW_SPOTS)]

    def at_show(self, tr):
        return max(abs(tr["x"] - SHOW_POS[0]), abs(tr["y"] - SHOW_POS[1])) <= 3.5

    def _show_drive(self, tr):
        """Maskiner, der er tilmeldt dyrskuet: bliver stående der – eller køres derhen, hvis man har bedt om det."""
        if self.at_show(tr):
            tr["s"], tr["show"] = "parked", "there"
            return True
        if tr["show"] == "send":
            sx, sy = self._show_spot(tr)
            tr.update(s="move", tx=sx, ty=sy, tool=None, j=None, path=None)
            return False
        return False

    def act_show(self, pid, msg):
        p, sh = self.players.get(pid), self.show
        if not p or not sh or sh.get("year") != self.year():
            return
        e = self.show_entry(pid)
        op = msg.get("op")
        judged = sh.get("stage") == "done"
        if op == "reply" and not judged:
            ok = bool(msg.get("ok"))
            if ok and not e["ok"]:
                if p["money"] < SHOW_FEE:
                    self.log("Ikke nok penge til standgebyret.", pid, "err")
                    return
                p["money"] -= SHOW_FEE
                self.book(p, "dyrskue", -SHOW_FEE)
                self.log(f"Du har tilmeldt dig Egnens Dyrskue (standgebyr {kr(SHOW_FEE)}). Vælg op til 2 maskiner og "
                         "nogle dyr under Dyrskue – og få dem derhen før bedømmelsen.", pid, "good")
            elif not ok and e["ok"]:
                self._show_withdraw(p, e)
                self.log("Du har meldt fra til dyrskuet.", pid, "info")
            elif not ok:
                self.log("Du har takket nej til dyrskuet i år.", pid, "info")
            e["ok"] = ok
        elif op == "veh" and e["ok"] and not judged:
            vid = int(msg.get("id", -1))
            tr = self._veh(pid, vid)
            if not tr or tr.get("hire") or vkind(tr["k"]) == "car":
                return
            if vid in e["veh"]:
                e["veh"].remove(vid)
                tr.pop("show", None)
                if tr["s"] == "parked":
                    tr["s"] = "idle"
            elif len(e["veh"]) < 2:
                e["veh"].append(vid)
                tr["show"] = tr.get("show") or "entered"
        elif op == "send" and e["ok"] and not judged:
            tr = self._veh(pid, int(msg.get("id", -1)))
            if tr and tr["id"] in e["veh"] and tr["s"] != "manual":
                tr["show"] = "send"
                if tr["s"] == "parked":
                    tr["s"] = "idle"
                self.log(f"En medhjælper kører {vname(tr['k'])} #{tr['id']} til dyrskuet.", pid, "info")
        elif op == "animals" and e["ok"] and not judged:
            kind = msg.get("kind")
            if kind in SHOW_LIMITS:
                n = int(clamp(int(msg.get("n", 0)), 0, SHOW_LIMITS[kind]))
                e["animals"][kind] = n
        elif op == "ship" and e["ok"] and not judged:
            sent = []
            at = p.setdefault("at_show", {})
            for kind, want in e["animals"].items():
                have = at.get(kind, 0) + sum(d["n"] for d in p["deliv"] if d["kind"] == kind and d["dir"] == "show")
                n = min(want - have, p.get(kind, 0))
                if n > 0:
                    p[kind] -= n
                    self._order(p, "show", kind, n, 0)
                    sent.append(f"{n} {ANIMALS[kind][2] if n == 1 else ANIMALS[kind][3]}")
            if sent:
                self.log(f"{', '.join(sent).capitalize()} køres til dyrskuet. " + self._order_note(p), pid, "info")

    def _show_withdraw(self, p, e):
        for vid in e.get("veh", []):
            tr = self._veh(p["id"], vid)
            if tr:
                tr.pop("show", None)
                if tr["s"] == "parked":
                    tr["s"] = "idle"
        e["veh"] = []
        self._show_send_home(p)

    def _show_send_home(self, p):
        at = p.get("at_show", {})
        for kind, n in list(at.items()):
            if n > 0:
                self._order(p, "home", kind, n, 0)
        p["at_show"] = {}

    def _show_day(self):
        sh = self.show
        if not sh or sh.get("year") != self.year():
            return
        m, d = self.month(), self.dom()
        if m == SHOW_MONTH and d == SHOW_OPEN and sh["stage"] == "invite":
            sh["stage"] = "open"
            self.log(f"Egnens Dyrskue er åbnet på kvægtorvet i {TOWN_NAME}! Bedømmelsen er {SHOW_JUDGE}. juni. "
                     "Nye maskiner er 10% billigere under messen.", None, "big")
        if m == SHOW_MONTH and d == SHOW_JUDGE and sh["stage"] in ("invite", "open"):
            self._show_judge()
        if m == SHOW_MONTH and d == SHOW_END and sh["stage"] == "done" and not sh.get("home"):
            sh["home"] = True
            for p in self.players.values():
                self._show_send_home(p)
            for tr in self.tractors:
                if tr.get("show"):
                    tr.pop("show", None)
                    if tr["s"] == "parked":
                        tr["s"] = "idle"
            self.log("Dyrskuet er slut – maskiner og dyr kommer hjem igen.", None, "info")

    def _machine_score(self, tr):
        v = VEHICLES[tr["k"]]
        wear = tr.get("wear", 0.0)
        sc = 58 - wear * 0.6 + (12 if wear < 5 else 0) + 4 * len(tr.get("upg", [])) + min(15, v["price"] / 4000)
        sc -= tr.get("dirt", 0.0) * 0.2                    # dommerne kan ikke lide mudder
        if v.get("year", 0) == 0 and v["price"] <= 9000:
            sc += 10                                   # publikum elsker de gamle traktorer
        return sc + self.rng.uniform(-6, 6)

    def _animal_score(self, p, kind, n):
        sc = 52 + (14 if not p.get("hungry") else 0) + 2 * min(n, 5)
        if STRAW_USE.get(kind) and p["inv"].get("halm", 0) >= 1:
            sc += 9
        if kind in GRAZERS and self.pasture(p["id"]):
            sc += 8
        if kind == "cows" and sum(p["inv"].get(g, 0) for g in SILAGE_GOODS) >= 1 and \
                any(p["inv"].get(g, 0) >= 1 for g in FEED_ORDER):
            sc += 8
        return sc + self.rng.uniform(-7, 7)

    def _show_judge(self):
        sh = self.show
        sh["stage"] = "done"
        rng = self.rng
        cats = {k: [] for k in SHOW_CATS}
        for p in self.players.values():
            e = self.show_entry(p["id"])
            if not e.get("ok"):
                continue
            there = [t for t in self.tractors if t["o"] == p["id"] and t["id"] in e["veh"] and self.at_show(t)
                     and abs((t.get("man") or {}).get("v", 0)) < 0.2]
            if there:
                best = max(there, key=self._machine_score)
                cats["maskine"].append((p["name"], round(min(99, self._machine_score(best))), p["id"],
                                        vname(best["k"])))
            for kind, n in p.get("at_show", {}).items():
                if n > 0 and kind in cats:
                    cats[kind].append((p["name"], round(min(99, self._animal_score(p, kind, n))), p["id"],
                                       f"{n} {ANIMALS[kind][2] if n == 1 else ANIMALS[kind][3]}"))
            if e.get("ok") and not there and not any(p.get("at_show", {}).values()):
                self.log("Du var tilmeldt dyrskuet, men hverken maskiner eller dyr nåede frem til bedømmelsen.",
                         p["id"], "warn")
        for p in self.ai_players():                           # computernaboerne viser deres bedste maskine og dyr
            if p["money"] < SHOW_FEE or self.rng.random() > 0.75:
                continue
            p["money"] -= SHOW_FEE
            self.book(p, "dyrskue", -SHOW_FEE)
            trs = [t for t in self.tractors if t["o"] == p["id"] and not t.get("hire") and vkind(t["k"]) != "car"]
            if trs:
                best = max(trs, key=self._machine_score)
                cats["maskine"].append((p["name"], round(min(99, self._machine_score(best))), p["id"],
                                        vname(best["k"])))
            for kind in cats:
                if kind in ANIMALS and p.get(kind, 0) > 0:
                    n = min(p[kind], SHOW_LIMITS.get(kind, 3))
                    cats[kind].append((p["name"], round(min(99, self._animal_score(p, kind, n))), p["id"],
                                       f"{n} {ANIMALS[kind][2] if n == 1 else ANIMALS[kind][3]}"))
        names = [f"Gårdejer {n}" for n in NEIGHBOURS]
        results, firsts = [], {}
        for cat, rows in cats.items():
            if not rows and cat != "maskine":
                continue
            npc = [(n, rng.randint(58, 90), None, "") for n in rng.sample(names, 3)]
            allr = sorted(rows + npc, key=lambda r: -r[1])
            out = []
            for place, (name, score, pid, what) in enumerate(allr[:5], 1):
                out.append([name, score, pid, what, place])
                if pid is not None and place <= 3:
                    p = self.players[pid]
                    prize = SHOW_PRIZES[place]
                    p["money"] += prize
                    self.book(p, "dyrskue", prize)
                    p.setdefault("rosetter", []).append([self.year(), cat, place])
                    if place == 1:
                        firsts[pid] = firsts.get(pid, 0) + 1
                    self.log(f"Dyrskuet: {place}. plads i {SHOW_CATS[cat].lower()}"
                             + (f" med {what}" if what else "") + f"! Rosette og {kr(prize)} i præmie.", pid, "big")
            for name, score, pid, what in allr[5:]:
                if pid is not None:
                    out.append([name, score, pid, what, allr.index((name, score, pid, what)) + 1])
            results.append({"cat": cat, "rows": out})
        sh["results"] = results
        for pid, n in firsts.items():                      # vinderne får lidt bedre priser et år
            self.players[pid]["show_bonus"] = {"until": self.day + DAYS_PER_YEAR, "pct": min(0.05, 0.02 * n)}
        winners = [f"{r['rows'][0][0]} ({SHOW_CATS[r['cat']].lower()})" for r in results if r["rows"]]
        self.add_news(f"Dyrskuet i {TOWN_NAME} er afgjort",
                      "Årets vindere: " + ", ".join(winners) + ". Tillykke til alle rosettevinderne!", big=True)

    # ── jagt og fiskeri (kør selv hen til en sø eller skov) ──────────────────
    def jagttegn_ok(self, p):
        return p.get("gear", {}).get("jagttegn", -1) >= self.day

    def in_season(self, sp, month=None):
        return (self.month() if month is None else month) in GAME[sp]["season"]

    def near_water(self, x, y):
        cx, cy = int(round(x)), int(round(y))
        n = 0
        for yy in range(cy - 4, cy + 5):
            for xx in range(cx - 4, cx + 5):
                if self.inb(xx, yy) and self.tiles[yy][xx].t == "water":
                    n += 1
        close = any(self.inb(xx, yy) and self.tiles[yy][xx].t == "water"
                    for yy in range(cy - 1, cy + 2) for xx in range(cx - 1, cx + 2))
        return n if close else 0

    def near_forest(self, x, y, pid, also=()):
        """Antal skovfelter tæt på, som man må jage i (egen skov eller statsskov – ikke naboens, medmindre man
        har lejet en jagthytte hos naboen: also = de ejere, hvis skov man må jage i)."""
        cx, cy = int(round(x)), int(round(y))
        best, n = None, 0
        for yy in range(cy - 3, cy + 4):
            for xx in range(cx - 3, cx + 4):
                if self.inb(xx, yy):
                    t = self.tiles[yy][xx]
                    if t.t == "forest" and t.lc != "ung" and (t.o in (-1, pid) or t.o in also) and not t.b:
                        n += 1
                        d = abs(xx - cx) + abs(yy - cy)
                        if best is None or d < best[0]:
                            best = (d, [xx, yy])
        return n, (best[1] if best else None)

    def _act_view(self, m):
        tp, g = m.get("trip"), m.get("game")
        if g:
            return {"g": g["sp"], "ttl": round(g["ttl"], 1), "pos": g["pos"]}
        if tp:
            return {"k": tp["k"], "p": round(min(1.0, tp["t"] / tp["dur"]), 2)}
        return None

    def act_gear(self, pid, key):
        p = self.players.get(pid)
        if not p or key not in GEAR:
            return
        gear = p.setdefault("gear", {})
        g = GEAR[key]
        if key == "jagttegn":
            if self.jagttegn_ok(p) and gear["jagttegn"] - self.day > 30:
                self.log("Dit jagttegn gælder stadig.", pid, "info")
                return
        elif gear.get(key):
            self.log(f"Du har allerede {g['navn'].lower()}.", pid, "info")
            return
        if p["money"] < g["price"]:
            self.log(f"Ikke nok penge til {g['navn'].lower()}.", pid, "err")
            return
        p["money"] -= g["price"]
        self.book(p, "jagt", -g["price"])
        self.town_add(g["price"] * 0.5)
        if key == "jagttegn":
            gear["jagttegn"] = max(self.day, gear.get("jagttegn", -1)) + 12 * DAYS_PER_MONTH
            self.log(f"Du har løst jagttegn for et år (-{kr(g['price'])}). Husk jagttiderne – de står i jagtbutikken.",
                     pid, "good")
        else:
            gear[key] = True
            self.log(f"Du købte {g['navn'].lower()} i jagtbutikken (-{kr(g['price'])}).", pid, "good")

    def act_trip(self, pid, vid, kind, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        m, p = tr["man"], self.players[pid]
        if m.get("trip") or m.get("game"):
            return
        if abs(m["v"]) > 0.2:
            self.log("Hold stille først.", pid, "info")
            return
        gear = p.get("gear", {})
        if kind == "fish":
            if not (gear.get("fiskestang") or gear.get("fiskegrej")):
                self.log("Du skal have en fiskestang – køb den i jagtbutikken i byen.", pid, "err")
                return
            if not self.near_water(tr["x"], tr["y"]):
                self.log("Kør helt hen til bredden af en sø for at fiske.", pid, "info")
                return
            if self.snow >= 0.3:
                self.log("Søen er frosset til – der kan ikke fiskes nu.", pid, "info")
                return
            if self.weather == "Storm":
                self.log("Det blæser en halv pelikan – ingen fisketur i dag.", pid, "info")
                return
            wait = FISH_WAIT - (self.day - p.get("fish_day", -99))
            if wait > 0:
                self.log(f"Fiskene skal lige have ro – prøv igen om {wait} dag{'e' if wait > 1 else ''}.", pid, "info")
                return
            p["fish_day"] = self.day
            m["trip"] = {"k": "fish", "t": 0.0, "dur": FISH_SECS}
            self.log("Du slår dig ned ved bredden og kaster ud …", pid, "info")
        elif kind == "hunt":
            if not self.jagttegn_ok(p):
                self.log("Du skal have et gyldigt jagttegn – det løses i jagtbutikken i byen.", pid, "err")
                return
            if not (gear.get("riffel") or gear.get("haglgevaer")):
                self.log("Du har intet gevær – køb et haglgevær eller en riffel i jagtbutikken.", pid, "err")
                return
            n, spot = self.near_forest(tr["x"], tr["y"], pid, self.hut_hosts(p, tr["x"], tr["y"]))
            hut = self.near_hut(p, tr["x"], tr["y"])
            if n < (3 if hut else 5):
                self.log("Kør ud til kanten af en større skov (din egen eller statsskov) for at gå på jagt.",
                         pid, "info")
                return
            wait = (HUT_WAIT if hut else HUNT_WAIT) - (self.day - p.get("hunt_day", -99))
            if wait > 0:
                self.log(f"Vildtet er sky efter sidst – prøv igen om {wait} dag{'e' if wait > 1 else ''}.", pid, "info")
                return
            p["hunt_day"] = self.day
            m["trip"] = {"k": "hunt", "t": 0.0, "dur": HUNT_SECS, "spot": spot, "hut": hut}
            self.log("Du sætter dig op i skydetårnet ved jagthytten og venter …" if hut else
                     "Du sætter dig stille i skovkanten og venter …", pid, "info")

    def _trip_tick(self, tr, dt):
        m, pid = tr["man"], tr["o"]
        if abs(m["v"]) > 0.3:                          # kører man, er turen forbi
            if m.get("trip") or m.get("game"):
                self.log("Du kørte fra turen.", pid, "info")
            m["trip"] = m["game"] = None
            return
        g = m.get("game")
        if g:
            g["ttl"] -= dt
            if g["ttl"] <= 0:
                m["game"] = None
                d = GAME[g["sp"]]["den"]
                self.log(f"{d.capitalize()} forsvandt ind i skoven." if g["sp"] not in ("and", "fasan", "stork") else
                         f"{d.capitalize()} lettede og fløj væk.", pid, "info")
            return
        tp = m["trip"]
        tp["t"] += dt
        if tp["t"] < tp["dur"]:
            return
        m["trip"] = None
        if tp["k"] == "fish":
            self._fish_result(tr)
        else:
            rng = self.rng
            hut = tp.get("hut")
            sp = rng.choices(list(GAME), [v["w"] * (1.6 if hut and v["kg"][1] >= 15 else 1) for v in GAME.values()])[0]
            spot = tp.get("spot") or [int(round(tr["x"])), int(round(tr["y"]))]
            mates = [self.pname(o["o"]) for o in self.tractors if o is not tr and o["o"] != pid and o["s"] == "manual"
                     and max(abs(o["x"] - tr["x"]), abs(o["y"] - tr["y"])) <= HUT_RANGE + 2 and
                     (o["man"].get("trip") or o["man"].get("game") or self.day - self.players.get(o["o"], {})
                      .get("hunt_day", -99) <= 0)]
            m["game"] = {"sp": sp, "ttl": GAME_SECS + (1.5 if hut else 0), "pos": spot, "hut": hut,
                         "mates": len(set(mates))}
            if mates:
                self.log(f"Fællesjagt med {', '.join(sorted(set(mates)))} – I driver vildtet frem sammen "
                         "(mere vildt pr. skud).", pid, "info")
            self.log(f"Der kommer {GAME[sp]['en']} frem ved skovkanten! Tryk J for at skyde – "
                     "eller lad være, hvis det er uden for jagttiden.", pid, "big")

    def _fish_result(self, tr):
        p, rng = self.players[tr["o"]], self.rng
        gear = p.get("gear", {})
        lake = self.near_water(tr["x"], tr["y"])
        rolls = 2 + (1 if gear.get("fiskegrej") else 0) + (1 if self.weather in ("Regn", "Tåge") else 0)
        big = 1.0 + (0.25 if gear.get("fiskegrej") else 0) + min(0.3, lake / 80)
        m = self.month()
        pool = [k for k, v in FISH.items() if m in v["months"]]
        got = {}
        for _ in range(rolls):
            if rng.random() < 0.18:
                continue                                      # ingen bid
            k = rng.choices(pool, [FISH[x]["w"] * (1.6 if x == "gedde" and lake > 25 else 1) for x in pool])[0]
            lo, hi = FISH[k]["kg"]
            kg = round(rng.uniform(lo, hi) * big * (1.4 if rng.random() < 0.06 else 1.0), 2)
            got.setdefault(k, []).append(kg)
        if not got:
            self.log("Ikke et eneste bid i dag. Sådan er fiskeri – prøv igen en anden dag.", tr["o"], "info")
            return
        tot = round(sum(sum(v) for v in got.values()), 1)
        p["inv"]["fisk"] += tot
        parts = []
        for k, kgs in got.items():
            f = FISH[k]
            parts.append(f"{len(kgs)} {f['flere'] if len(kgs) > 1 else f['navn']}" +
                         (f" på {max(kgs):.1f} kg".replace(".", ",") if max(kgs) >= 1.5 else ""))
        self.log(f"Fisketuren gav {', '.join(parts)} – i alt {str(tot).replace('.', ',')} kg fisk. Sælg dem i "
                 "jagtbutikken eller i gårdbutikken.", tr["o"], "good")
        best_k, best = max(((k, max(v)) for k, v in got.items()), key=lambda kv: kv[1])
        if best >= max(4.0, self.records.get("fish", 0)):
            self.records["fish"] = best
            self.add_news(f"Rekordfisk i søen: {FISH[best_k]['navn']} på {best:.1f} kg".replace(".", ","),
                          f"{p['name']} fangede egnens største {FISH[best_k]['navn']} til dato. \"Den kæmpede godt\", "
                          "fortæller den stolte fisker.")

    def act_shoot(self, pid, vid, drv=None):
        tr = self._veh(pid, vid)
        if not self._mine(tr, drv):
            return
        m, p, rng = tr["man"], self.players[pid], self.rng
        g = m.get("game")
        if not g:
            return
        m["game"] = None
        sp = g["sp"]
        info = GAME[sp]
        gear = p.get("gear", {})
        if info["gun"] and not gear.get(info["gun"]):
            need = GEAR[info["gun"]]["navn"].lower()
            self.log(f"Du har ikke det rette våben ({need}) – {info['den']} slap væk.", pid, "info")
            return
        hit = (0.88 if info["gun"] else 0.8) + (0.06 if g.get("hut") else 0)
        if rng.random() > hit:
            self.log("Pang! Forbi – dyret forsvandt.", pid, "info")
            return
        if not self.in_season(sp):
            fine = info["fine"]
            p["money"] -= fine
            self.book(p, "jagt", -fine)
            why = "den er fredet hele året" if not info["season"] else "det er uden for jagttiden"
            self.log(f"Du skød {info['en']}, men {why}! Jagtbetjenten giver dig en bøde på {kr(fine)}.", pid, "err")
            if fine >= 5000 and self.day - self.records.get("fine_news", -99) > DAYS_PER_MONTH:
                self.records["fine_news"] = self.day
                self.add_news("Jæger fik bøde", f"En jæger fra egnen skød {info['en']} – {why}. Bøden lød på "
                              f"{kr(fine)}. Jagttiderne hænger i jagtbutikken.")
            return
        kg = round(rng.uniform(*info["kg"]) * (1.2 if g.get("hut") else 1.0) * (1 + 0.15 * min(3, g.get("mates", 0))), 1)
        p["inv"]["vildt"] += kg
        self.log(f"Flot skud! Du nedlagde {info['en']} ({str(kg).replace('.', ',')} kg vildt). Sælg det i jagtbutikken "
                 "eller gårdbutikken.", pid, "good")
        if sp == "vildsvin" and kg >= max(70, self.records.get("boar", 0)):
            self.records["boar"] = kg
            self.add_news("Kæmpe vildsvin nedlagt", f"{p['name']} nedlagde et vildsvin på {kg:.0f} kg i skoven ved "
                          f"{TOWN_NAME}.")

    # ── last, når man selv kører (Styr selv) ─────────────────────────────────
    def cargo_cap(self, tr):
        v = VEHICLES.get(tr["k"], {})
        if v.get("kind") == "truck" and v.get("cargo") in ("grain", "animal", "milk"):
            return int(v["cap"] * (1.25 if "lad" in tr.get("upg", ()) else 1))
        w = (tr.get("man") or {}).get("wagon")
        return WAGONS[w]["cap"] if w else 0

    def cargo_kind(self, tr):
        """Hvad maskinen kan køre med: grain (tipvogn/kornbil), animal (kreaturvogn/-bil) eller milk (mælketank)."""
        v = VEHICLES.get(tr["k"], {})
        if v.get("kind") == "truck":
            return v.get("cargo")
        w = (tr.get("man") or {}).get("wagon")
        return WAGONS[w]["cargo"] if w else None

    def _cargo_abort(self, tr):
        m, p = tr.get("man"), self.players.get(tr["o"])
        c = m and m.get("cargo")
        if not c or not p:
            return
        if c["src"] == "fr":
            f = next((f for f in p.get("freight", []) if f["id"] == c["fr"]), None)
            if f:
                f["taken"] -= sum(c["load"].values())
        elif (tr.get("hitch") or "").startswith("w:"):     # læsset bliver på vognen
            p.setdefault("wload", {})[tr["hitch"]] = dict(c["load"])
            if c.get("s"):
                p.setdefault("wshape", {})[tr["hitch"]] = c["s"]
        else:
            for g, v in c["load"].items():
                p["pile"][g] = p["pile"].get(g, 0.0) + v
            if not p.get("pile_pos"):
                p["pile_pos"] = [int(round(tr["x"])), int(round(tr["y"]))]
        m["cargo"] = None

    @staticmethod
    def _near(tr, pos, r):
        return pos is not None and max(abs(tr["x"] - pos[0]), abs(tr["y"] - pos[1])) <= r

    def _manual_cargo(self, tr, moving=False):
        """Holder man stille med en tipvogn eller kornbil, læsses der op eller af automatisk.
        moving=True: man kører langsomt – så læsses der, når selve vognen er kørt helt hen til markbunken,
        lageret eller ballepladsen (man behøver ikke stoppe)."""
        m, p = tr["man"], self.players.get(tr["o"])
        cap = self.cargo_cap(tr)
        if not p or cap <= 0:
            return
        c = m.get("cargo")
        kind = self.cargo_kind(tr)
        if kind in ("animal", "milk"):                # slagtesvin til slagteriet, mælk til mejeriet
            if not moving:
                self._manual_deliver(tr, p, kind, cap)
            return
        if moving:                                    # vognens midte (bag traktoren) – en kornbil er sin egen vogn
            if m.get("wagon"):
                wx_, wy_ = self.rear_point(tr["x"], tr["y"], m["hdg"], 1.05 if bale_wagon(m["wagon"]) else 0.85)
            else:
                wx_, wy_ = tr["x"], tr["y"]
            pt_ = {"x": wx_, "y": wy_}
            LR, UR = 1.2, 1.6
        else:
            pt_, LR, UR = tr, LOAD_RANGE, UNLOAD_RANGE
        load = sum(c["load"].values()) if c else 0.0
        home = self.unload_spot(tr["o"], c["load"]) if c and c["src"] == "pile" else self._drop_spot(tr["o"])
        at_home = self._near(pt_, home, UR) or (c and c["src"] != "fr" and set(c["load"]) <= set(BALE_GOODS)
                                                         and self._near(pt_, self.bale_spot(tr["o"]), UR))
        # læs af
        if c and c["src"] != "fr" and at_home:
            bl_ = set(c["load"]) <= set(BALE_GOODS)
            if bl_ and c["load"].get("halm", 0) >= 0.5:
                p["yshape"] = c.get("s") or "rund"
            nbl_ = int(round(wagon_slots_used(c["load"], c.get("s")))) if bl_ else 0
            n = self._unload_grain(p, c["load"])
            m["cargo"] = None
            if n >= 1:
                p["hauled"] = p.get("hauled", 0) + n
                self.log((f"Du læssede {nbl_} baller af på gården." if bl_ else
                          f"Du læssede {int(n)} enheder af på gården.") +
                         (" Hele høsten er kørt i hus." if self.pile_total(p) < 1 and not p.get("bales") else ""),
                         tr["o"], "good")
            return
        if c and c["src"] == "fr" and self._near(pt_, c["dest"], UR):
            f = next((f for f in p.get("freight", []) if f["id"] == c["fr"]), None)
            g, n = next(iter(c["load"].items()))
            m["cargo"] = None
            if f:
                pay = f["value"] * n / f["qty"] if f["qty"] else 0
                p["money"] += pay
                self.book(p, "salg", pay)
                self.town_add(pay)
                f["value"] -= pay
                f["qty"] -= n
                f["taken"] -= n
                if f["qty"] <= 0.5:
                    p["freight"].remove(f)
                self.log(f"Du leverede {int(n)} {GOODS[g]['navn'].lower()} hos {dest_name(g)} (+{kr(pay)}).",
                         tr["o"], "good")
            return
        if c and load >= cap - 0.5:
            return
        if bale_wagon(m.get("wagon")):              # ballevognen læsses kun med frontlæsseren
            return
        # læs op: markbunke eller halmballer (ikke hvis bunken ligger ved lageret – så læsser man i ring)
        if (not c or c["src"] == "pile") and not at_home:
            got = {}
            room = cap - load
            if p.get("pile") and self._near(pt_, p.get("pile_pos"), LR):
                tgrp = (set(c["load"]) <= {"tommer"}) if c and c["load"] else None
                for g, v in sorted(p["pile"].items(), key=lambda kv: -kv[1]):
                    if tgrp is None:
                        tgrp = g == "tommer"
                    if (g == "tommer") != tgrp:              # stammer og korn køres hver for sig
                        continue
                    a = min(v, room)
                    if a > 0.01:
                        p["pile"][g] -= a
                        got[g] = got.get(g, 0.0) + a
                        room -= a
                        if p["pile"][g] < 0.01:
                            del p["pile"][g]
            if not moving and not m.get("bale_warn") and self.bales_at(p, (tr["x"], tr["y"]), LR):
                m["bale_warn"] = True                   # baller læsses med frontlæsseren – ikke af sig selv
                self.log("Ballerne læsses med frontlæsseren: stil vognen (helst en ballevogn) på marken (K), og brug "
                         "så en traktor med frontlæsser – sænk (E) ved ballerne, hæv (E), og kør helt frem til vognen. "
                         "Så læsses de af og stables af sig selv.", tr["o"], "info")
            if got:
                if not c:
                    c = m["cargo"] = {"src": "pile", "load": {}}
                for g, v in got.items():
                    c["load"][g] = c["load"].get(g, 0.0) + v
                tot = sum(c["load"].values())
                where_ = "tømmerpladsen" if set(c["load"]) <= {"tommer"} else "lageret (siloen)"
                self.log(f"Du læssede op: {int(tot)} af {int(cap)} enheder." +
                         (f" Kør helt hen til {where_} derhjemme – så læsses der af." if tot >= cap - 0.5 or
                          not p.get("pile") else ""), tr["o"], "info")
            return
        # læs solgte varer op ved gården og kør dem til byen (kun når man holder stille – ikke bare kører forbi)
        if not c and at_home and not moving:
            for f in p.get("freight", []):
                left = f["qty"] - f["taken"]
                if f["dir"] != "out" or f.get("carrier") or left <= 0.5 or f["good"] in GOOD_CARGO:
                    continue
                n = min(left, cap)
                f["taken"] += n
                dest = freight_dest(f["good"])
                m["cargo"] = {"src": "fr", "fr": f["id"], "load": {f["good"]: n}, "dest": list(dest)}
                self.log(f"Du læssede {int(n)} solgt {GOODS[f['good']]['navn'].lower()} op. Kør til "
                         f"{dest_name(f['good'])} i byen og hold stille.", tr["o"], "info")
                return

    def _manual_deliver(self, tr, p, kind, cap):
        """Kør selv: læs solgte slagtesvin/mælk op ved gården, kør til slagteriet/mejeriet og hold stille."""
        m = tr["man"]
        c = m.get("cargo")
        g = "svin" if kind == "animal" else "maelk"
        if c and c.get("src") == "fr":
            if not self._near(tr, c["dest"], UNLOAD_RANGE):
                return
            f = next((f for f in p.get("freight", []) if f["id"] == c["fr"]), None)
            n = next(iter(c["load"].values()))
            m["cargo"] = None
            if f:
                pay = f["value"] * n / f["qty"] if f["qty"] else 0
                bonus = pay * OWN_DELIVERY_BONUS
                p["money"] += pay + bonus
                self.book(p, "salg", pay + bonus)
                self.town_add(pay)
                f["value"] -= pay
                f["qty"] -= n
                f["taken"] -= n
                if f["qty"] <= 0.5:
                    p["freight"].remove(f)
                self.log(f"Du leverede {int(n)} {GOODS[g]['navn'].lower()} hos {dest_name(g)} "
                         f"(+{kr(pay + bonus)}, heraf {kr(bonus)} for egen levering).", tr["o"], "good")
            return
        if c:
            return
        stable = self._stable_spot(tr["o"], "pigs" if g == "svin" else "cows")
        if not (self._near(tr, stable, UNLOAD_RANGE + 1) or self._near(tr, p["home"], UNLOAD_RANGE + 1) or
                self._near(tr, self._drop_spot(tr["o"]), UNLOAD_RANGE)):
            return
        capn = int(cap / ANIMAL_UNITS["pigs"]) if g == "svin" else cap
        for f in p.get("freight", []):
            left = f["qty"] - f["taken"]
            if f["dir"] != "out" or f.get("carrier") or f["good"] != g or left <= 0.5:
                continue
            n = min(left, capn)
            f["taken"] += n
            m["cargo"] = {"src": "fr", "fr": f["id"], "load": {g: n}, "dest": list(freight_dest(g))}
            self.log(f"Du læssede {int(n)} {'slagtesvin' if g == 'svin' else 'liter mælk'} op. Kør til "
                     f"{dest_name(g)} uden for byen og hold stille – egen levering giver 8% mere.", tr["o"], "info")
            return

    def _manual_summary(self, tr):
        m = tr.get("man")
        job = m and m.get("job")
        if not job or job["n"] == 0:
            return
        txt = f"Du kørte selv: {JOB_NAMES[job['tool']].lower()} af {job['n']} felt{'er' if job['n'] > 1 else ''}"
        if job["yield"]:
            txt += " – " + ", ".join(f"{int(v)} {GOODS[g]['navn'].lower()}" for g, v in job["yield"].items())
        txt += f" (-{kr(job['spent'])}" + (f", heraf leje {kr(job['rent'])}" if job.get("rent") else "") + ")."
        if job["lost"] >= 1:
            txt += f" {int(job['lost'])} gik tabt – lageret er fuldt."
        self.log(txt, tr["o"], "good" if job["yield"] else "info")
        m["job"] = {**job, "n": 0, "spent": 0, "yield": {}, "lost": 0.0, "rent": 0}

    def _blocked(self, x, y):
        if not self.inb(x, y):
            return True
        t = self.tiles[y][x]
        return t.t == "water" or bool(t.b) and not t.b.startswith("site:")

    def tick_manual(self, dt):
        for tr in self.tractors:
            if tr["s"] == "manual":
                self._manual(tr, dt)
                if (self.players.get(tr["o"]) or {}).get("birth"):
                    self._birth_visit(tr)

    def _town_visit(self, tr, cx, cy):
        """Når man selv kører bil ind til byen, hører man nyt fra markedet (højst én gang om måneden)."""
        p = self.players.get(tr["o"])
        if not p or vkind(tr["k"]) not in ("car", "smaa") or not in_town(cx, cy):
            return
        month_id = self.day // DAYS_PER_MONTH
        if p.get("visit") == month_id:
            return
        p["visit"] = month_id
        rng = self.rng
        g = max(GOODS, key=lambda g: self.market[g]["p"] / GOODS[g]["base"] + rng.uniform(0, 0.05))
        lo = min(GOODS, key=lambda g: self.market[g]["p"] / GOODS[g]["base"])
        tips = [f"På kroen siger de, at {GOODS[g]['navn'].lower()} er dyr lige nu "
                f"({fmt_price(self.market[g]['p'])}). Godt tidspunkt at sælge.",
                f"Grovvarehandleren klager over, at ingen vil købe {GOODS[lo]['navn'].lower()}. Vent med at sælge den."]
        m = self.month()
        if m in (5, 6, 7) and self.opts["drought"]:
            tips.append("Den gamle bager spår en tør sommer. Sørg for grøfter ved markerne.")
        if m in (8, 9, 10) and self.opts["storm"]:
            tips.append("Radioen melder om efterårsstorme. Få høsten i hus i tide.")
        bonus = 250 + rng.randrange(6) * 50
        p["money"] += bonus
        self.book(p, "salg", bonus)
        self.town_add(bonus)
        self.log(f"Du tog en tur til byen. {rng.choice(tips)}", tr["o"], "chat")
        self.log(f"Du solgte et par kasser æg og grønt på torvet (+{kr(bonus)}).", tr["o"], "good")

    def _manual(self, tr, dt):
        m = tr["man"]
        cx, cy = int(round(tr["x"])), int(round(tr["y"]))
        if m.get("cell") != (cx, cy):
            m["cell"] = (cx, cy)
            self._town_visit(tr, cx, cy)
            self._dirty(tr, cx, cy, bool(m["tool"]))
            self._burn(tr, FUEL_MOVE)
            self._wear(tr, WEAR_MOVE)
        if m["tool"] and m["last"] != (cx, cy):
            m["last"] = (cx, cy)
            self._manual_work(tr, cx, cy)
        if m.get("trip") or m.get("game"):
            self._trip_tick(tr, dt)
        if abs(m["v"]) < 0.15 and tr.get("dirt", 0) > 0 and self.near_washer(tr):
            tr["dirt"] = max(0.0, tr["dirt"] - 35 * dt)       # højtryksrenseren kører
            m["washing"] = True
            if tr["dirt"] <= 0:
                p = self.players.get(tr["o"])
                if p:
                    p["money"] -= WASH_COST
                    self.book(p, "reparation", -WASH_COST)
                self._svclog(tr, "Vasket", WASH_COST)
                self.log(f"{vname(tr['k'])} er skinnende ren igen (-{kr(WASH_COST)}).", tr["o"], "good")
                m["washing"] = False
        else:
            m["washing"] = False
        m["fueling"] = False
        cap = fuel_cap(tr["k"], tr)
        if abs(m["v"]) < 0.15 and tr.get("fuel", cap) < cap - 0.5:
            p_ = self.players.get(tr["o"])
            how = None
            if p_ and self.near_tank(tr):
                how = "tank" if p_.get("tank_l", 0) >= 0.5 else None
                if how is None and not m.get("tank_warn"):
                    m["tank_warn"] = True
                    self.log("Gårdens dieseltank er tom – bestil diesel hos tankbilen (højreklik på tanken).", tr["o"],
                             "warn")
            elif p_ and self._near(tr, GROVVARE, 2.2):
                how = "town"
            if how:
                got, cost = self.refuel(tr, p_, FUEL_RATE * dt, how)
                m["fueling"] = got > 0
                m["fuel_got"] = m.get("fuel_got", 0.0) + got
                m["fuel_kr"] = m.get("fuel_kr", 0.0) + cost
                if tr["fuel"] >= cap - 0.5 or (how == "tank" and p_.get("tank_l", 0) < 0.5):
                    self.log(f"Tanket {int(m['fuel_got'])} liter diesel" +
                             (f" (-{kr(m['fuel_kr'])})." if how == "town" else " fra gårdens dieseltank.") +
                             ("" if tr["fuel"] >= cap - 0.5 else " Gårdens tank er nu tom."), tr["o"], "good")
                    m["fuel_got"], m["fuel_kr"] = 0.0, 0.0
        if tr.get("upg_wait") and abs(m["v"]) < 0.15 and self.near_workshop(tr):
            m["fit"] = m.get("fit", 0.0) + dt
            if m["fit"] >= 2.0:                               # et par sekunder med skruenøglen
                m["fit"] = 0.0
                self._fit_upgrades(tr)
        else:
            m["fit"] = 0.0
        m["ct"] = m.get("ct", 0.0) + dt
        if abs(m["v"]) < 0.15 and m["ct"] >= 0.4:
            m["ct"] = 0.0
            self._manual_cargo(tr)
        elif abs(m["v"]) < 1.6 and m["ct"] >= 0.2 and (m.get("wagon") or vkind(tr["k"]) == "truck"):
            m["ct"] = 0.0                            # kør langsomt helt hen til bunken/lageret: læs op eller af
            self._manual_cargo(tr, moving=True)
        if m.get("fl") and m.get("ld", "up") == "up" and abs(m["v"]) < 1.2 and loader_on(tr):
            # kør helt frem til en vogn med ballerne i læsseren: de læsses af og stables af sig selv
            m["ft"] = m.get("ft", 0.0) + dt
            if m["ft"] >= 0.15:
                m["ft"] = 0.0
                p_ = self.players.get(tr["o"])
                fp_ = self.front_point(tr, 0.65)
                if p_ and self.loader_target(p_, fp_, tr, 0.75):
                    self._loader_drop(tr, p_, fp_)
        if time.time() - m.get("cl", 0.0) < 0.6:      # klienten kører maskinen selv lige nu
            return
        self.kinematics(tr, m, dt)

    def kinematics(self, tr, m, dt):
        """Bilstyring: gas/bremse/bak og rat. Retningen er i skærmkoordinater, så venstre er venstre.
        Bruges både af serveren og af klienten (som forudsiger sin egen maskine, så styringen er glat)."""
        cx, cy = int(round(tr["x"])), int(round(tr["y"]))
        t = self.tiles[cy][cx]
        f = VEHICLES[tr["k"]]["fart"]
        vmax = MANUAL_SPEED.get(t.t, 2.2) * (f if t.t in ROADS else min(1.0, f) * VEHICLES.get(tr["k"], {}).get("offroad", 1.0))
        if t.t not in ROADS and ("tvilling" in tr.get("upg", ()) or "terraendaek" in tr.get("upg", ())):
            vmax *= 1.25
        if m["tool"]:
            vmax = min(vmax, MANUAL_WORK_SPEED)
        if self.hm:                                       # bakker: op ad går langsommere
            sx_, sy_ = math.cos(m["hdg"]), math.sin(m["hdg"])
            ux_, uy_ = (sx_ / HALF_W + sy_ / HALF_H) / 2, (sy_ / HALF_H - sx_ / HALF_W) / 2
            n_ = math.hypot(ux_, uy_) or 1.0
            sg_ = -1 if m["v"] < -0.05 else 1
            vmax *= self.slope_speed(tr["x"], tr["y"], tr["x"] + sg_ * ux_ / n_ * 0.6, tr["y"] + sg_ * uy_ / n_ * 0.6)
        gps = m.get("gps")
        if gps and m.get("uturn"):
            if m["turn"] or m["thr"] < 0:
                m["uturn"] = None                        # man tager selv over
            else:
                self._gps_uturn(tr, m, dt)
                return
        thr = m["thr"]
        if tr.get("fuel", 1) <= 0:                       # tør for diesel: motoren går ud
            thr = 0
        if gps:                                          # fartpilot med sænket redskab
            if thr < 0:
                m["cruise_off"] = True
            elif thr > 0:
                m["cruise_off"], m["gps_stop"] = False, False
            if thr == 0 and m["tool"] and not m.get("cruise_off") and not m.get("gps_stop"):
                thr = 1
        v = m["v"]
        if thr > 0:
            v = v + MANUAL_BRAKE * dt if v < 0 else min(vmax, v + MANUAL_ACCEL * dt)
        elif thr < 0:
            v = v - MANUAL_BRAKE * dt if v > 0 else max(-MANUAL_REVERSE, v - MANUAL_ACCEL * dt)
        else:
            v = max(0.0, v - MANUAL_ROLL * dt) if v > 0 else min(0.0, v + MANUAL_ROLL * dt)
        if v > vmax:                                  # terrænet bremser
            v = max(vmax, v - MANUAL_BRAKE * dt)
        if m["turn"]:
            grip = 0.35 + 0.65 * min(1.0, abs(v) / 1.2)
            m["hdg"] += m["turn"] * MANUAL_TURN * grip * dt * (-1 if v < -0.05 else 1)
            m["snap"] = 0.0
        elif gps:
            # GPS: retningen låses fast til markens retning
            diff = min(((a - m["hdg"] + math.pi) % (2 * math.pi) - math.pi for a in self.AXES), key=abs)
            m["hdg"] += diff * min(1.0, dt * 8)
        elif abs(v) > 0.2:
            # kørehjælp: slipper man rattet tæt på vejenes retning, retter traktoren sig selv ind
            m["snap"] = m.get("snap", 0.0) + dt
            if m["snap"] > 0.15:
                axes = [math.atan2(HALF_H, HALF_W), math.atan2(HALF_H, -HALF_W),
                        math.atan2(-HALF_H, -HALF_W), math.atan2(-HALF_H, HALF_W)]
                diff = min(((a - m["hdg"] + math.pi) % (2 * math.pi) - math.pi for a in axes), key=abs)
                if abs(diff) < math.radians(28):
                    m["hdg"] += diff * min(1.0, dt * 5)
        m["v"] = v
        # skærmretning -> retning på kortet
        sx, sy = math.cos(m["hdg"]), math.sin(m["hdg"])
        ux, uy = (sx / HALF_W + sy / HALF_H) / 2, (sy / HALF_H - sx / HALF_W) / 2
        n = math.hypot(ux, uy) or 1.0
        ux, uy = ux / n, uy / n
        tr["d"] = int(round(math.atan2(uy, ux) / (math.pi / 4))) % 8
        if abs(v) < 1e-3:
            return
        nx, ny = tr["x"] + ux * v * dt, tr["y"] + uy * v * dt
        nx, ny = clamp(nx, 0.0, self.W - 1.0), clamp(ny, 0.0, self.H - 1.0)
        tx, ty = int(math.floor(nx + 0.5)), int(math.floor(ny + 0.5))
        if (tx, ty) != (cx, cy) and (self._blocked(tx, ty) or self.fence_blocks((cx, cy), (tx, ty))):
            # glid langs forhindringen i stedet for at stoppe brat
            if not self._blocked(tx, ty):
                m["fence_hit"] = time.time()                 # vises i køreboksen: hegnet spærrer
            for gx, gy in ((nx, tr["y"]), (tr["x"], ny)):
                ttx, tty = int(math.floor(gx + 0.5)), int(math.floor(gy + 0.5))
                if (ttx, tty) == (cx, cy) or (not self._blocked(ttx, tty) and
                                              not self.fence_blocks((cx, cy), (ttx, tty))):
                    tr["x"], tr["y"] = gx, gy
                    m["v"] = v * 0.85
                    return
            m["v"] = 0.0                              # helt blokeret – stop
            return
        tr["x"], tr["y"] = nx, ny
        if gps and not m["turn"] and abs(v) > 0.1:
            ax, ay = self.axis_dir(m["hdg"])
            k = min(1.0, dt * 3)
            if ax:                                       # hold sporet midt i rækken af felter
                tr["y"] += (round(tr["y"]) - tr["y"]) * k
            else:
                tr["x"] += (round(tr["x"]) - tr["x"]) * k
            if m["tool"] and v > 0.3:
                self._gps_headland(tr, m, ax, ay)

    AXES = [math.atan2(16, 32), math.atan2(16, -32), math.atan2(-16, -32), math.atan2(-16, 32)]   # = TH/2, TW/2
    AXIS_DIRS = [(1, 0), (0, 1), (-1, 0), (0, -1)]

    def axis_dir(self, hdg):
        i = min(range(4), key=lambda i: abs((self.AXES[i] - hdg + math.pi) % (2 * math.pi) - math.pi))
        return self.AXIS_DIRS[i]

    def _gps_ok(self, tr, m, x, y):
        """Må GPS'en køre videre hertil? Følger planen for redskabet, ellers kun marker og stub (ikke græs)."""
        if not self.inb(x, y) or self._blocked(x, y):
            return False
        t = self.tiles[y][x]
        if t.o != tr.get("o"):
            return False
        tool = m.get("tool")
        p = self.players.get(tr.get("o")) or {}
        plan = [j for j in p.get("jobs", []) if j["tool"] == tool]
        if plan:
            return any([x, y] in j.get("all", j["tiles"]) or [x, y] in j["tiles"] for j in plan)
        return t.t in ("field", "stub")

    def _gps_headland(self, tr, m, ax, ay):
        """Ved markkanten vender GPS'en selv og kører tilbage i næste række (samme side hver gang)."""
        cx, cy = int(round(tr["x"])), int(round(tr["y"]))
        along = (tr["x"] - cx) * ax + (tr["y"] - cy) * ay
        if along < 0.05 or self._gps_ok(tr, m, cx + ax, cy + ay):
            return
        sides = [(-ay, ax), (ay, -ax)]
        side = m.get("gps_side")
        if side:
            side = tuple(side)
            cand = [side] if self._gps_ok(tr, m, cx + side[0], cy + side[1]) else []
        else:
            cand = [sd for sd in sides if self._gps_ok(tr, m, cx + sd[0], cy + sd[1])]
        if not cand:
            m["gps_stop"] = True                         # marken er færdig – stop
            return
        sx, sy = cand[0]
        m["gps_side"] = [sx, sy]
        m["uturn"] = {"t": 0.0, "x0": tr["x"], "y0": tr["y"], "x1": float(cx + sx), "y1": float(cy + sy),
                      "ax": ax, "ay": ay}

    def _gps_uturn(self, tr, m, dt):
        u = m["uturn"]
        u["t"] = min(1.0, u["t"] + dt / 1.4)
        t, ax, ay = u["t"], u["ax"], u["ay"]
        bulge = 0.45
        tr["x"] = u["x0"] + (u["x1"] - u["x0"]) * t + ax * math.sin(math.pi * t) * bulge
        tr["y"] = u["y0"] + (u["y1"] - u["y0"]) * t + ay * math.sin(math.pi * t) * bulge
        vx = (u["x1"] - u["x0"]) + ax * math.pi * math.cos(math.pi * t) * bulge
        vy = (u["y1"] - u["y0"]) + ay * math.pi * math.cos(math.pi * t) * bulge
        m["hdg"] = math.atan2((vx + vy) * HALF_H, (vx - vy) * HALF_W)
        m["v"] = 1.0
        if t >= 1.0:
            tr["x"], tr["y"] = u["x1"], u["y1"]
            m["hdg"] = self.AXES[self.AXIS_DIRS.index((-ax, -ay))]
            m["uturn"] = None
        tr["d"] = self.hdg_dir(m["hdg"])

    def _manual_work(self, tr, x, y):
        m, p = tr["man"], self.players.get(tr["o"])
        t = self.tiles[y][x]
        job = m["job"]
        if p and job and t.o != tr["o"] and t.o >= 0:      # maskinstation: et felt, man har påtaget sig for en anden
            fj = next((j for j in p["jobs"] if j.get("for") == t.o and j["tool"] == job["tool"] and
                       [x, y] in j["tiles"]), None)
            if fj:
                fj["tiles"].remove([x, y])
                if self._ms_tile(tr, p, fj, t, [x, y]):
                    job["n"] += 1
                    self.touch(x, y)
                if not fj["tiles"]:
                    self._job_done(p, fj)
            return
        if not p or not job or (t.o != tr["o"] and not (job["tool"] == "snow" and t.o < 0)):
            return
        if job["tool"] == "snow" and (x, y) in self.plowed:
            return
        if job["tool"] == "sow" and self.month() not in CROPS[job["crop"]]["months"]:
            return
        if job["tool"] == "water" and (x, y) not in self.water_reach():
            if not job.get("warned"):
                job["warned"] = True
                self.log(f"Slangen når ikke herud – der skal være vand højst {WATER_REACH} felter væk.", tr["o"], "warn")
            return
        potato_ = self.hitch_vis(tr) == "potato" and t.crop == "kartofler"
        if job["tool"] == "harvest" and vkind(tr["k"]) == "tractor" and not self._is_orchard((x, y)) and not potato_:
            if not job.get("warned"):
                job["warned"] = True
                self.log("Traktoren kan kun plukke frugt i plantagen og tage kartofler op (med kartoffeloptager) – "
                         "korn høstes med en mejetærsker.", tr["o"], "warn")
            return
        hk_ = GEAR_IMP.get((tr.get("hitch") or "")[2:]) if (tr.get("hitch") or "").startswith("e:") else None
        src = "gylle" if hk_ in ("gylle", "gylle_s") else "kunst" if hk_ == "fertilize" else \
            "harve" if hk_ == "harrow" else "plov" if hk_ == "plow" else None
        if src == "harve" and job["tool"] == "plow" and not self._harrow_ok(p, t, True):
            if self._cost("plow", t, None) is not None and not job.get("warned"):
                job["warned"] = True
                self.log("Stubharven kan kun behandle stubmark – græs og døde afgrøder skal pløjes med ploven.",
                         tr["o"], "warn")
            return
        if src == "gylle" and job["tool"] == "fertilize" and p.get("gylle", 0) < GYLLE_PER_TILE:
            if not job.get("warned"):
                job["warned"] = True
                self.log("Gylletanken er tom – gyllevognen har intet at køre ud. Brug gødningssprederen.", tr["o"], "warn")
            return
        cost, rent, gylle = self.job_cost(p, job["tool"], t, job["crop"], tr["k"], src)
        if cost is None:
            return
        job["rent"] = job.get("rent", 0) + rent
        if gylle and job["tool"] == "fertilize":
            p["gylle"] -= GYLLE_PER_TILE
        if p["money"] < cost - self._stock_part(p, job["tool"], job["crop"], gylle) and job["tool"] != "harvest":
            if job.get("broke") is None:
                job["broke"] = True
                self.log("Ikke nok penge til at arbejde videre.", tr["o"], "err")
            return
        cost = self._pay_work(p, job["tool"], job["crop"], gylle, cost, tr, (x, y))
        if job["tool"] not in p.setdefault("did", []):
            p["did"].append(job["tool"])
        self._burn(tr, FUEL_TILE)
        self._wear(tr, WEAR_TILE * (0.7 if "frontvaegt" in tr.get("upg", ()) else 1.0))
        job["spent"] += cost
        job["n"] += 1
        self._apply(job["tool"], t, job["crop"], p, job, pos=(x, y), gylle=gylle, by=tr["k"])
        self.touch(x, y)
        if job["tool"] == "mow" and "bredklip" in tr.get("upg", ()):      # bredt klippebord: også felterne ved siden af
            cx_, cy_ = VDIRS[tr["d"] % 8]
            px_, py_ = int(round(-cy_)), int(round(cx_))
            for sgn in (-1, 1):
                nx, ny = x + sgn * px_, y + sgn * py_
                if self.inb(nx, ny) and self.tiles[ny][nx].o == tr["o"] and \
                        self._cost("mow", self.tiles[ny][nx], None) is not None:
                    self._apply("mow", self.tiles[ny][nx], None, p, job, pos=(nx, ny))
                    job["n"] += 1
                    self.touch(nx, ny)
        for pj in list(p["jobs"]):              # felter, man selv har kørt, strøges af planen
            if pj["tool"] == job["tool"] and [x, y] in pj["tiles"]:
                pj["tiles"].remove([x, y])
                if not pj["tiles"]:
                    p["jobs"].remove(pj)
                    self.log(f"Planen er klaret: {JOB_NAMES[pj['tool']].lower()} af hele området er gjort.",
                             p["id"], "good")

    def terrain_speed(self, x, y, route=False, pid=None, prof=1.0):
        t = self.tiles[y][x]
        if t.b:
            return 0.08 if route else 2.0
        if route:                          # vejene er klart at foretrække – terræn kun når der ingen vej er
            if t.crop and not t.dead:
                return 0.25                # afgrøder kører man udenom
            if pid is not None and t.o == pid and t.t in OWN_ROUTE:
                # over egen mark/eng: maskinens fart i terræn i forhold til på vej (prof) – kun en lille omvej
                # ad vejen er værd at tage
                return max(ROUTE_SPEED.get(t.t, 0.4), TERRAIN_SPEED.get(t.t, 4.0) * prof / OWN_ROUTE_PENALTY)
            return ROUTE_SPEED.get(t.t, 0.4)
        return TERRAIN_SPEED.get(t.t, 4.0) * (0.8 if t.crop and not t.dead else 1.0)

    def shed_door(self, x, y):
        """Feltet lige foran porten på maskinhuset, (x, y) ligger i – og retningen ud (dx, dy). Ellers None."""
        if not self.inb(x, y):
            return None
        t = self.tiles[y][x]
        if not t.b or BUILDINGS.get(t.b, {}).get("group") != "maskinhus":
            return None
        return self.bdoor(x, y)

    def bdoor(self, x, y):
        """Feltet lige foran en bygnings port. Porten sidder på den langside, man ser på skærmen (den nederste)."""
        if not self.inb(x, y) or not self.tiles[y][x].b:
            return None
        x0, y0, w, h = self.anchor(x, y)
        if w >= h:
            sides = [((x0 + i, y0 + h) for i in range(w)), (0, 1)], [((x0 + w, y0 + i) for i in range(h)), (1, 0)]
            mid = [x0 + (w - 1) / 2, y0 + h]
        else:
            sides = [((x0 + w, y0 + i) for i in range(h)), (1, 0)], [((x0 + i, y0 + h) for i in range(w)), (0, 1)]
            mid = [x0 + w, y0 + (h - 1) / 2]
        for cells, out in sides:                # først forsiden, er den spærret så gavlen ved siden af
            ok = [c for c in cells if not self._blocked(*c)]
            if ok:
                c = min(ok, key=lambda c: abs(c[0] - mid[0]) + abs(c[1] - mid[1]))
                return c, out
            mid = [x0 + w, y0 + (h - 1) / 2] if w >= h else [x0 + (w - 1) / 2, y0 + h]
        return None

    def _route_grid(self, pid=None, prof=1.0):
        """Tiden pr. felt for vejfindingen som én flad liste (genbruges, til noget på kortet ændrer sig).
        Én liste pr. ejer: over egen jord må maskinerne gerne køre, over andres holder de sig til vejene."""
        rgs = self.__dict__.setdefault("_rgs", {})
        if pid is None:
            prof = 1.0
        c = rgs.get((pid, prof))
        key = (self.day, self.W, self.H)
        ts = self.terrain_speed
        if c is not None and c[0] == key:            # kun de felter, der er ændret siden sidst, regnes om
            g, rd = c[1], c[2]
            if rd:
                W = self.W
                for x, y in rd:
                    if 0 <= x < W and 0 <= y < self.H:
                        g[y * W + x] = 1.0 / ts(x, y, True, pid, prof)
                rd.clear()
            return g
        g = [1.0 / ts(x, y, True, pid, prof) for y in range(self.H) for x in range(self.W)]
        for k_ in [k_ for k_, c_ in rgs.items() if c_[0] != key]:    # gamle lister (fra i går) smides ud
            del rgs[k_]
        rgs[(pid, prof)] = [key, g, set()]
        return g

    def find_path(self, sx, sy, tx, ty, pid=None, prof=1.0):
        """A*-vejfinding. Omkostning = tid, så køretøjerne foretrækker asfalt og grus."""
        import heapq
        if (sx, sy) == (tx, ty):
            return []
        W, H = self.W, self.H
        if not (0 <= sx < W and 0 <= sy < H and 0 <= tx < W and 0 <= ty < H):
            return [[tx, ty]]
        cost = self._route_grid(pid, prof)
        start, goal = sy * W + sx, ty * W + tx
        best, came = {start: 0.0}, {}
        heap = [(0.0, 0.0, start)]
        inv = 1.0 / TERRAIN_SPEED["asphalt"]
        push, pop = heapq.heappush, heapq.heappop
        big = 1e18
        while heap:
            _, g, cur = pop(heap)
            if cur == goal:
                break
            if g > best.get(cur, big):
                continue
            cy, cx = divmod(cur, W)
            for ok, ni, nx, ny in ((cx + 1 < W, cur + 1, cx + 1, cy), (cx > 0, cur - 1, cx - 1, cy),
                                   (cy + 1 < H, cur + W, cx, cy + 1), (cy > 0, cur - W, cx, cy - 1)):
                if not ok:
                    continue
                ng = g + cost[ni]
                if ng < best.get(ni, big):
                    best[ni] = ng
                    came[ni] = cur
                    push(heap, (ng + (abs(nx - tx) + abs(ny - ty)) * inv, ng, ni))
        if goal not in came:
            return [[tx, ty]]
        path, cur = [], goal
        while cur != start:
            cy, cx = divmod(cur, W)
            path.append([cx, cy])
            cur = came[cur]
        path.reverse()
        return path

    def _hire_combines(self):
        """Maskinstationen: har man ingen mejetærsker, kommer en lejet ud fra byen, når der er høst."""
        for p in self.players.values():
            pid = p["id"]
            harvest = any(j["tool"] == "harvest" and any(not self._tractor_crop(c, p) for c in j["tiles"])
                          for j in p["jobs"])
            hired = [t for t in self.tractors if t["o"] == pid and t["k"] == "maskinstation"]
            own = any(vkind(k) == "combine" for _, k in self.vehicles_of(pid))
            if not self.auto_on(p, "maskinstation"):
                harvest = False                               # slået fra: maskinstationen kommer ikke (og kører hjem)
            if harvest and not own and not hired:
                self.tractors.append({"id": self.nid, "o": pid, "k": "maskinstation", "hs": [ROAD_X, ROAD_Y],
                                      "x": float(ROAD_X), "y": float(ROAD_Y), "d": 0, "s": "idle", "tx": None,
                                      "ty": None, "w": 0.0, "j": None, "tool": None, "path": None,
                                      "hire": "maskinstation"})
                self.nid += 1
                self.log(f"Maskinstationen sender en mejetærsker med fører ud til dig ({self.hire_harvest()} kr/felt).",
                         pid, "info")
            for t in hired:
                if (not harvest or own) and t["s"] == "parked" and tuple(t["hs"]) == (ROAD_X, ROAD_Y):
                    self.tractors.remove(t)
                    self.log("Maskinstationens mejetærsker er færdig og kørt hjem igen.", pid, "info")

    def _outside_spot(self, pid, skip=None):
        """Et ledigt sted udenfor tæt ved stuehuset, hvor en maskine kan holde."""
        p = self.players.get(pid)
        if not p:
            return [0, 0]
        hx, hy = p["home"]
        taken = {tuple(t["hs"]) for t in self.tractors if t["o"] == pid and t is not skip}
        best = None
        for y in range(hy - 8, hy + 9):                     # fliser (parkeringsplads) foretrækkes
            for x in range(hx - 8, hx + 9):
                if not self.inb(x, y) or (x, y) in taken:
                    continue
                t = self.tiles[y][x]
                if t.o != pid or t.b or t.crop or t.t not in ("grass", "gravel", "stub", "field", "fliser"):
                    continue
                d = abs(x - hx) + abs(y - hy) + (0 if t.t in ("grass", "gravel") else -8 if t.t == "fliser" else 3)
                if max(abs(x - hx), abs(y - hy)) > 6 and t.t != "fliser":
                    continue
                if best is None or d < best[0]:
                    best = (d, [x, y])
        return best[1] if best else [hx, hy]

    def is_outside(self, tr):
        return not tr.get("hire") and vkind(tr["k"]) != "car" and \
            tuple(tr["hs"]) not in {sp for sp, _ in self.sheds(tr["o"])}

    def _weather_wear(self):
        """Maskiner, der står udenfor, går til i vind og vejr."""
        if not self.opts.get("wear", True):
            return
        f = {"Regn": 2.0, "Storm": 4.0, "Sne": 2.5, "Frost": 2.0, "Tåge": 1.5}.get(self.weather, 1.0)
        for tr in self.tractors:
            if tr["s"] == "parked" and self.is_outside(tr):
                hx_, hy_ = int(round(tr["x"])), int(round(tr["y"]))
                on_tiles = self.inb(hx_, hy_) and self.tiles[hy_][hx_].t == "fliser"
                tr["wear"] = min(100.0, tr.get("wear", 0.0) + 0.12 * f * (FLISER_WEAR if on_tiles else 1.0))

    def _home_of(self, tr):
        if tr.get("hire"):                       # lejede maskiner kører hjem til byen
            return tuple(tr["hs"])
        if vkind(tr["k"]) == "car" and tr["o"] in self.players:
            return self.car_spot(self.players[tr["o"]], tr)
        return tuple(tr["hs"])

    def _job(self, pid, jid):
        p = self.players.get(pid)
        return next((j for j in p["jobs"] if j["id"] == jid), None) if p else None

    def machine_score(self, tr):
        """Hvor god en maskine er til markarbejde: trækkraft først, så fart, opgraderinger og slid."""
        v = VEHICLES.get(tr["k"], {})
        upg = tr.get("upg", ())
        return (v.get("kraft", 1.0) * (1.15 if "tuning" in upg else 1.0) + 0.2 * v.get("fart", 1.0) +
                (0.1 if "tvilling" in upg else 0.0) - tr.get("wear", 0.0) / 400)

    def _better_idle(self, tr, tool):
        """Står der en bedre maskine af samme slags ledig, som kan tage opgaven? (så vælges den bedste først)"""
        if tr.get("hire"):
            return False
        kind = vkind(tr["k"])
        mine = self.machine_score(tr)
        for t in self.tractors:
            if t is tr or t["o"] != tr["o"] or t.get("hire") or vkind(t["k"]) != kind or tool not in self.jobs_for(t):
                continue
            if t["s"] not in ("idle", "parked") or t.get("haul") or t.get("show") or t.get("upg_wait"):
                continue
            if self.manual_mode() and not t.get("helper"):
                continue
            sc = self.machine_score(t)
            if sc > mine + 1e-6 or (abs(sc - mine) <= 1e-6 and t["id"] < tr["id"]):
                return True
        return False

    def _pick_target(self, tr):
        p = self.players.get(tr["o"])
        if not p:
            return None
        others = [t for t in self.tractors if t is not tr and t["o"] == tr["o"] and (t["tool"] or t.get("fj"))]
        claimed = {(t["tx"], t["ty"]) for t in self.tractors if t is not tr and t["tool"]} | \
            {tuple(c_) for t in self.tractors if t is not tr and t["tool"] for c_ in t.get("swath", ())}
        jobs_ok = self.jobs_for(tr)
        # én maskine pr. mark: marker (sammenhængende felter i en opgave), som en anden maskine er i gang
        # med, lades være – så arbejder flere traktorer på hver sin mark
        busy = set()
        for o in others:
            jid, fx, fy = (o["j"], o["tx"], o["ty"]) if o["tool"] else o["fj"]
            job_o = self._job(tr["o"], jid)
            if job_o:
                busy |= self._field_of(job_o.get("all", job_o["tiles"]), (fx, fy))
        prio = {"spray": 0, "harvest": 1}
        for job in sorted(p["jobs"], key=lambda j: prio.get(j["tool"], 2)):
            if job["tool"] == "sow" and self.month() not in CROPS[job["crop"]]["months"]:
                p["jobs"].remove(job)
                self.log(f"Såsæsonen for {CROPS[job['crop']]['navn'].lower()} er slut – opgaven stoppede.",
                         tr["o"], "warn")
                continue
            orchard_ok = job["tool"] == "harvest" and vkind(tr["k"]) == "tractor" and not tr.get("hire")
            if job["tool"] not in jobs_ok and not orchard_ok:
                continue
            while True:
                bales = set(p.get("bales", {})) | set(p.get("wraps", {}))
                cands = [c for c in job["tiles"] if (c[0], c[1]) not in claimed and (c[0], c[1]) not in busy and
                         not (job["tool"] in ("plow", "sow") and f"{c[0]},{c[1]}" in bales) and
                         (job["tool"] != "harvest" or self._tractor_crop(c, p) == orchard_ok)]
                if not cands:
                    break
                c = min(cands, key=lambda c: abs(c[0] - tr["x"]) * 1.02 + abs(c[1] - tr["y"]))
                cont = tr.get("fj") and tr["fj"][0] == job["id"]
                if not cont or abs(c[0] - tr["x"]) + abs(c[1] - tr["y"]) > 1.5:
                    c = self._field_start(cands, c, tr)        # ny mark (eller ny stribe): start i et hjørne
                t = self.tiles[c[1]][c[0]]
                snow_ = job["tool"] == "snow"
                if (t.o != tr["o"] and not (snow_ and t.o < 0) and t.o != job.get("for")) or \
                        self._cost(job["tool"], t, job["crop"]) is None \
                        or (snow_ and (c[0], c[1]) in self.plowed):
                    job["tiles"].remove(c)
                    continue
                return job, c
            if not job["tiles"]:
                self._job_done(p, job)
        return None

    def _field_start(self, cands, near, tr):
        """Start i det hjørne af marken, der ligger nærmest maskinen – ikke midt i marken."""
        field = self._field_of(cands, tuple(near))
        pts = [c for c in cands if (c[0], c[1]) in field] or cands
        xs, ys = [c[0] for c in pts], [c[1] for c in pts]
        corners = [(x_, y_) for x_ in (min(xs), max(xs)) for y_ in (min(ys), max(ys))]
        cx, cy = min(corners, key=lambda k: abs(k[0] - tr["x"]) + abs(k[1] - tr["y"]))
        return min(pts, key=lambda c: (abs(c[0] - cx) + abs(c[1] - cy), abs(c[0] - tr["x"]) + abs(c[1] - tr["y"])))

    def _is_orchard(self, c):
        cr = self.tiles[c[1]][c[0]].crop
        return bool(cr and CROPS[cr].get("orchard"))

    def _tractor_crop(self, c, p):
        """Høstes feltet af en traktor? Frugt i plantagen – og kartofler, når gården har en kartoffeloptager."""
        cr = self.tiles[c[1]][c[0]].crop
        return bool(cr and (CROPS[cr].get("orchard") or (cr == "kartofler" and p and self.owns_tool(p, "potato"))))

    @staticmethod
    def _field_of(tiles, start):
        """De felter i en opgave, der hænger sammen med 'start' (én mark)."""
        cells = {(c[0], c[1]) for c in tiles} | {tuple(start)}
        seen, todo = {tuple(start)}, [tuple(start)]
        while todo:
            x, y = todo.pop()
            for dx, dy in N4:
                nb = (x + dx, y + dy)
                if nb in cells and nb not in seen:
                    seen.add(nb)
                    todo.append(nb)
        return seen

    def _job_done(self, p, job):
        if job in p["jobs"]:
            p["jobs"].remove(job)
        if job.get("for") is not None:                     # maskinstationsopgaven er færdig
            cust = self.players.get(job["for"])
            earned = job.get("earn", 0)
            self.log(f"Maskinstation: {JOB_NAMES[job['tool']].lower()} for {cust['name'] if cust else '?'} er færdig "
                     f"– du har tjent {kr(earned)}.", p["id"], "good")
            if cust:
                txt = f"{p['name']} har gjort {JOB_NAMES[job['tool']].lower()} færdig på din jord (-{kr(earned)})"
                if job.get("yield"):
                    txt += ": " + ", ".join(f"{int(v)} {GOODS[g]['navn'].lower()}" for g, v in job["yield"].items())
                self.log(txt + ".", cust["id"], "good")
            return
        tot = sum(v for g, v in job.get("yield", {}).items() if g not in ("halm", "tommer"))
        if job["tool"] == "harvest" and tot > max(400, self.records.get("harvest", 0)):
            self.records["harvest"] = tot
            self.add_news(f"Rekordhøst hos {p['name']}", f"{p['name']} har høstet {int(tot)} enheder fra én mark – "
                          "egnens største høst til dato.")
        txt = f"{JOB_NAMES[job['tool']]} færdig"
        if job["tool"] == "snow":
            self.log(f"Snerydning færdig – kommunen har betalt {kr(job.get('earn', 0))}.", p["id"], "good")
            return
        if job["yield"]:
            txt += ": " + ", ".join(f"{int(v)} {GOODS[g]['navn'].lower()}" for g, v in job["yield"].items())
        txt += f" (-{kr(job['spent'])}"
        if job.get("rent"):
            txt += (f", heraf lejet hjælp {kr(job['rent'])}" if job["tool"] == "harvest"
                    else f", heraf leje af udstyr {kr(job['rent'])}")
        txt += ")."
        if job.get("gylle"):
            txt += f" {job['gylle']} felter fik gylle i stedet for kunstgødning."
        if job["yield"]:
            txt += " Høsten ligger i marken og venter på transport."
        self.log(txt, p["id"], "good" if job["yield"] else "info")

    def work_width(self, tr):
        """Hvor mange felter i bredden maskinen tager pr. tur. Store maskiner arbejder hurtigt – i stedet for at
        fare hen over marken (hurtigere end på vejen) tager de en bredere stribe: et bredt skærebord eller en stor
        plov. Farten i marken holdes på højst ca. 80% af maskinens fart i terræn."""
        if not tr.get("tool") or tr.get("tool") == "snow":
            return 1
        v = VEHICLES[tr["k"]]
        rate = 0.7 / max(1e-6, self._work_time(tr, single=True))       # så hurtigt den ville køre over feltet
        field = TERRAIN_SPEED["field"] * min(1.0, v["fart"]) * v.get("offroad", 1.0)
        return max(1, min(6, int(round(rate / (0.8 * field)))))

    def _swath(self, tr):
        """Nabofelterne på tværs af kørselsretningen, maskinen tager med på denne tur."""
        job = self._job(tr["o"], tr["j"])
        if not job or job.get("for") is not None or tr.get("tx") is None:
            return []
        w = self.work_width(tr)
        if w <= 1:
            return []
        dx, dy = VDIRS[tr["d"] % 8]
        px, py = (0, 1) if abs(dx) >= abs(dy) else (1, 0)          # på tværs af retningen
        left = set(map(tuple, job["tiles"]))
        claimed = {(t["tx"], t["ty"]) for t in self.tractors if t is not tr and t["tool"]} | \
            {tuple(c_) for t in self.tractors if t is not tr for c_ in t.get("swath", ())}
        p = self.players.get(tr["o"]) or {}
        orchard_ok = job["tool"] == "harvest" and vkind(tr["k"]) == "tractor"
        out = []
        for sgn in sorted((1, -1), key=lambda s_: -sum((tr["tx"] + px * s_ * k, tr["ty"] + py * s_ * k) in left
                                                     for k in range(1, w))):
            for k in range(1, w):
                c = (tr["tx"] + px * sgn * k, tr["ty"] + py * sgn * k)
                if len(out) >= w - 1 or c not in left or c in claimed:
                    break
                t = self.tiles[c[1]][c[0]]
                if t.o != tr["o"] or self._cost(job["tool"], t, job["crop"]) is None or \
                        (job["tool"] == "harvest" and self._tractor_crop(list(c), p) != orchard_ok):
                    break
                out.append(list(c))
        return out

    def _work_time(self, tr, single=False):
        if not single:
            return self._work_time(tr, True) * (1 + len(tr.get("swath") or ()))
        v = VEHICLES[tr["k"]]
        wt = KIND_WORK.get(v["kind"], {}).get(tr["tool"], WORK_TIME[tr["tool"]]) / max(0.3, v["kraft"])
        if tr.get("hire") == "maskinstation" and self.done("maskinst"):
            wt /= MASKINST_SPEED                           # den fælles maskinstations store mejetærsker
        if "tuning" in tr.get("upg", ()):
            wt /= 1.15
        p = self.players.get(tr["o"])
        if tr["tool"] == "plow" and tr.get("tx") is not None and self.inb(tr["tx"], tr["ty"]) and \
                self._harrow_ok(p, self.tiles[tr["ty"]][tr["tx"]]):
            return wt * HARROW_TIME                           # stubharven kører dobbelt så hurtigt
        for key in (p.get("equip", []) if p else []):
            if EQUIPMENT[key]["tool"] == tr["tool"]:
                wt *= EQUIPMENT[key]["faktor"]
        return wt

    def _drive(self, tr, days):
        if tr["s"] == "repair":
            tr["w"] -= days / self.pace()         # værkstedet regner i kalenderdage
            if tr["w"] <= 0:
                tr.update(s="idle", w=0.0)
                if tr.pop("fit", None):
                    self._fit_upgrades(tr)
                else:
                    self.log(f"{vname(tr['k'])} #{tr['id']} er repareret og klar igen.", tr["o"], "good")
            return
        if tr.get("show") and tr["s"] in ("idle", "parked") and self._show_drive(tr):
            return
        if vkind(tr["k"]) == "car":
            if tr["s"] != "parked":
                hx, hy = self._home_of(tr)
                if tr["s"] != "move":
                    tr.update(s="move", tx=hx, ty=hy, tool=None, j=None, path=None)
            else:
                return
        rem, guard = days, 0
        while rem > 1e-6 and guard < 40:
            guard += 1
            if tr["s"] == "work":
                need = self._work_time(tr) - tr["w"]
                if rem >= need:
                    rem -= need
                    self._finish_tile(tr)
                    self._dirty(tr, tr["tx"], tr["ty"], True)
                    self._burn(tr, FUEL_TILE)
                    self._wear(tr, WEAR_TILE * (0.7 if "frontvaegt" in tr.get("upg", ()) else 1.0))
                    tr["fj"] = (tr["j"], tr["tx"], tr["ty"])      # husk marken, så en anden maskine ikke tager den
                    tr["wd"], tr["wpos"] = tr["d"], (tr["tx"], tr["ty"])   # hvor og hvordan den sluttede (visning)
                    tr.update(s="idle", tool=None, j=None, w=0.0)
                    worn = 1 + tr.get("wear", 0.0) / 50 if self.opts.get("wear", True) else 1
                    if self.rng.random() < (100 - VEHICLES[tr["k"]]["rel"]) / 100 * 0.02 * worn:
                        p = self.players.get(tr["o"])
                        if p and self.workshop(p) and p.get("parts", 0) >= 1 and not tr.get("hire"):
                            p["parts"] -= 1
                            tr.update(s="repair", w=1.0, path=None)
                            self._svclog(tr, "Repareret i eget værksted (1 reservedel)", PART_PRICE)
                            self.log(f"{vname(tr['k'])} #{tr['id']} er brudt sammen. Du reparerer den selv i "
                                     f"værkstedet (1 reservedel) – den er klar i morgen.", tr["o"], "warn")
                            return
                        cost = int(VEHICLES[tr["k"]]["price"] * 0.03)
                        if p:
                            p["money"] -= cost
                            self.book(p, "reparation", -cost)
                        self._svclog(tr, "Reparation hos mekanikeren", cost)
                        tr.update(s="repair", w=float(REPAIR_DAYS), path=None)
                        tip = ""
                        if p and self.workshop(p):
                            tip = " Med reservedele på lager klarer du det selv på én dag."
                        self.log(f"{vname(tr['k'])} #{tr['id']} er brudt sammen og står på værksted i "
                                 f"{REPAIR_DAYS} dage (-{kr(cost)}).{tip}", tr["o"], "warn")
                        return
                else:
                    tr["w"] += rem
                    rem = 0
                continue
            if tr["s"] in ("idle", "parked") and not tr.get("hire") and not tr.get("haul"):
                p_ = self.players.get(tr["o"])
                cap_ = fuel_cap(tr["k"], tr)
                home_ = self._home_of(tr)
                at_home = max(abs(tr["x"] - home_[0]), abs(tr["y"] - home_[1])) < 0.2
                lazy_ = self.manual_mode() and not tr.get("helper")
                if p_ and at_home and not lazy_:
                    self._home_refuel(tr, p_)
                elif p_ and not lazy_ and tr.get("fuel", cap_) < cap_ * 0.15:
                    tr.update(s="move", tx=home_[0], ty=home_[1], tool=None, j=None, path=None)   # hjem og tanke
                    continue
            if tr["s"] in ("idle", "parked") and tr.get("upg_wait") and not tr.get("haul") and not tr.get("hire"):
                sp = self.workshop_spot(tr["o"])
                if sp is None:
                    pass
                elif max(abs(tr["x"] - sp[0]), abs(tr["y"] - sp[1])) < 0.2:
                    tr.update(s="repair", w=0.4, path=None, fit=True)      # mekanikeren skruer
                    return
                else:
                    tr.update(s="move", tx=sp[0], ty=sp[1], tool=None, j=None, path=None)
                    continue
            if tr["s"] in ("idle", "parked"):
                lazy = self.manual_mode() and not tr.get("hire") and not tr.get("helper")
                pick = self._pick_target(tr) if not tr.get("haul") and not lazy else None
                going = pick and tr.get("fj") and tr["fj"][0] == pick[0]["id"]   # er allerede i gang med opgaven
                if pick and not going and self._better_idle(tr, pick[0]["tool"]):
                    pick = None                     # en bedre maskine holder ledig – den tager opgaven
                if pick and not going:
                    tr.pop("wd", None)              # ny opgave: den kører ikke videre fra et felt
                    tr.pop("wpos", None)
                hl = None if pick or tr.get("haul") or lazy else self._haul_task(tr)
                tr["fj"] = None
                if pick:
                    job, c = pick
                    tr.update(s="move", tx=c[0], ty=c[1], tool=job["tool"], j=job["id"], w=0.0, path=None)
                elif hl:
                    tr["haul"] = hl
                    tr.update(s="move", tx=hl["frm"][0], ty=hl["frm"][1], tool=None, j=None, path=None)
                elif tr["s"] == "parked":
                    return
                else:
                    hx, hy = self._home_of(tr)
                    tr.update(s="move", tx=hx, ty=hy, tool=None, j=None, path=None)
            if tr["s"] == "move":
                if tr["tool"] and not self._job(tr["o"], tr["j"]):
                    tr.update(s="idle", tool=None, j=None)
                    continue
                if tr.get("path") is None:
                    sx_, sy_ = int(round(tr["x"])), int(round(tr["y"]))
                    out = self.shed_door(sx_, sy_)
                    if out and (sx_, sy_) != (tr["tx"], tr["ty"]):      # kør ud gennem porten foran
                        (sx_, sy_), (ox_, oy_) = out
                        tr["x"], tr["y"] = float(sx_), float(sy_)
                        tr["d"] = (0 if ox_ > 0 else 4) if ox_ else (2 if oy_ > 0 else 6)
                    inn = self.shed_door(tr["tx"], tr["ty"])
                    vv_ = VEHICLES.get(tr["k"], {})
                    fr_ = vv_.get("fart", 1.0)
                    fo_ = min(1.0, fr_) * vv_.get("offroad", 1.0) * (1.25 if "tvilling" in tr.get("upg", ()) else 1.0)
                    prof = round(fo_ / max(0.1, fr_) * 4) / 4          # terrænfart i forhold til vejfart
                    if tr.get("hire") in ("vognmand", "vognmand_dyr"):
                        prof = 0.0                                     # vognmanden holder sig til vejene
                    if inn and self.shed_door(sx_, sy_) is None:        # og ind samme vej
                        tr["path"] = self.find_path(sx_, sy_, *inn[0], pid=tr["o"], prof=prof) + \
                            [[tr["tx"], tr["ty"]]]
                    else:
                        tr["path"] = self.find_path(sx_, sy_, tr["tx"], tr["ty"], pid=tr["o"], prof=prof)
                while rem > 1e-6 and tr["path"]:
                    nx, ny = tr["path"][0]
                    if len(tr["path"]) == 1 and self.shed_door(nx, ny) and \
                            self.shed_door(int(round(tr["x"])), int(round(tr["y"]))) is None:
                        tr["x"], tr["y"] = float(nx), float(ny)          # ind gennem porten
                        tr["path"].pop(0)
                        break
                    dx, dy = nx - tr["x"], ny - tr["y"]
                    dist = math.hypot(dx, dy)
                    if dist > 1e-6:
                        tr["d"] = (0 if dx > 0 else 4) if abs(dx) >= abs(dy) else (2 if dy > 0 else 6)
                    vv = VEHICLES[tr["k"]]
                    road = self.tiles[ny][nx].t in ROADS
                    sp = self.terrain_speed(nx, ny) * (vv["fart"] if road else min(1.0, vv["fart"]) * vv.get("offroad", 1.0))
                    if not road and "tvilling" in tr.get("upg", ()):
                        sp *= 1.25
                    if self.hm:                                # op ad bakke går det langsommere
                        sp *= self.slope_speed(tr["x"], tr["y"], nx, ny)
                    if tr.get("hire") in ("vognmand", "vognmand_dyr"):
                        sp *= 2.0            # vognmanden kender vejen og har travlt (holder spillet i gang)
                    if tr["tool"] and len(tr["path"]) <= 3 and dist <= 1.01:
                        sp = max(sp, 40.0)   # arbejder sig videre til nabofeltet på samme mark
                    step = sp * rem
                    if step >= dist:
                        tr["x"], tr["y"] = float(nx), float(ny)
                        rem -= dist / sp
                        tr["path"].pop(0)
                        self._dirty(tr, nx, ny, False)
                        self._burn(tr, FUEL_MOVE * dist)
                        self._wear(tr, WEAR_MOVE * dist)
                    else:
                        tr["x"] += dx / dist * step
                        tr["y"] += dy / dist * step
                        rem = 0
                if not tr["path"]:
                    tr["x"], tr["y"], tr["path"] = float(tr["tx"]), float(tr["ty"]), None
                    if tr["tool"]:
                        tr["s"], tr["w"] = "work", 0.0
                        tr["swath"] = self._swath(tr)            # store maskiner tager flere felter i bredden
                    elif tr.get("haul"):
                        self._haul_arrive(tr)
                    else:
                        tr["s"] = "parked"
                        return

    def _finish_tile(self, tr):
        sw = tr.pop("swath", None) or []
        self._finish_one(tr, [tr["tx"], tr["ty"]])
        for c in sw:                                       # resten af striben, maskinen tog med
            job = self._job(tr["o"], tr["j"])
            if job and c in job["tiles"]:
                self._finish_one(tr, list(c))

    def _finish_one(self, tr, c):
        p = self.players.get(tr["o"])
        job = self._job(tr["o"], tr["j"])
        if not p or not job:
            return
        if c in job["tiles"]:
            job["tiles"].remove(c)
        t = self.tiles[c[1]][c[0]]
        if job.get("for") is not None:                     # maskinstation: arbejde på en anden spillers jord
            if t.o == job["for"]:
                self._ms_tile(tr, p, job, t, c)
            if not job["tiles"]:
                self._job_done(p, job)
            return
        cost, rent, gylle = self.job_cost(p, job["tool"], t, job["crop"], tr["k"])
        if cost is not None and (t.o == tr["o"] or (job["tool"] == "snow" and t.o < 0)):
            job["rent"] = job.get("rent", 0) + rent
            if gylle and job["tool"] == "fertilize":
                p["gylle"] -= GYLLE_PER_TILE
                job["gylle"] = job.get("gylle", 0) + 1
            if p["money"] < cost - self._stock_part(p, job["tool"], job["crop"], gylle) and job["tool"] != "harvest":
                p["jobs"].remove(job)
                self.log(f"Ikke nok penge – {JOB_NAMES[job['tool']].lower()} er stoppet.", p["id"], "err")
                return
            cost = self._pay_work(p, job["tool"], job["crop"], gylle, cost, tr, c)
            job["spent"] += cost
            self._apply(job["tool"], t, job["crop"], p, job, pos=c, gylle=gylle, by=tr["k"])
            self.touch(c[0], c[1])
        if not job["tiles"]:
            self._job_done(p, job)

    def view_xy(self, tr):
        """Hvor maskinen vises (også mellem to felter på marken) – samme sted i alle beskeder til klienterne."""
        x, y = tr["x"], tr["y"]
        working = tr["s"] == "work" and tr["tool"]
        if working:
            f = tr["w"] / self._work_time(tr) - 0.5
            dx, dy = VDIRS[tr["d"] % 8]
            x, y = x + dx * f * 0.7, y + dy * f * 0.7
        elif tr.get("wd") is not None and tr["s"] in ("move", "idle"):
            # mellem to felter på marken: fortsæt fra hvor den slap (felt + 0,35) til hvor næste felt
            # begynder (felt − 0,35) – ellers hopper den tilbage til feltets midte og ser ud til at vende
            ex, ey = VDIRS[tr["wd"] % 8]
            rx, ry = ((tr["tx"] - x, tr["ty"] - y) if tr.get("tx") is not None else (0.0, 0.0))
            dist = math.hypot(rx, ry)
            d0 = math.hypot(x - tr["wpos"][0], y - tr["wpos"][1]) if tr.get("wpos") else 9.0
            if tr["s"] == "idle":
                if d0 < 0.01:
                    x, y = x + ex * 0.35, y + ey * 0.35
            elif tr["tool"] and 1e-6 < dist <= 1.01 and d0 <= 1.01:
                nx_, ny_ = rx / dist, ry / dist
                k = 1.0 - dist
                sx_, sy_ = tr["tx"] - nx_ + ex * 0.35, tr["ty"] - ny_ + ey * 0.35
                fx_, fy_ = tr["tx"] - nx_ * 0.35, tr["ty"] - ny_ * 0.35
                x, y = sx_ + (fx_ - sx_) * k, sy_ + (fy_ - sy_) * k
            elif tr["tool"] and dist <= 1.01:
                x, y = self._approach(tr, x, y, rx, ry, dist)
            elif d0 < 1.0:                                     # kører væk fra feltet: glid ud af det
                x, y = x + ex * 0.35 * (1.0 - d0), y + ey * 0.35 * (1.0 - d0)
        elif tr["s"] == "move" and tr["tool"] and tr.get("tx") is not None:
            rx, ry = tr["tx"] - x, tr["ty"] - y
            dist = math.hypot(rx, ry)
            if dist <= 1.01:
                x, y = self._approach(tr, x, y, rx, ry, dist)
        return x, y, working

    def _approach(self, tr, x, y, rx, ry, dist):
        """Sidste stykke hen til et felt, der skal arbejdes: stop hvor arbejdet begynder (felt − 0,35)."""
        if dist > 1e-6:
            nx_, ny_ = rx / dist, ry / dist
        else:
            nx_, ny_ = VDIRS[tr["d"] % 8]
        k = 0.35 * (1.0 - min(1.0, dist))
        return x - nx_ * k, y - ny_ * k

    def tractor_meta(self):
        out = []
        for tr in self.tractors:
            x, y = tr["x"], tr["y"]
            if tr["s"] == "manual":
                m = tr["man"]
                moving = abs(m["v"]) > 0.05
                cap = self.cargo_cap(tr)
                ld = sum(m["cargo"]["load"].values()) if m.get("cargo") else 0.0
                gv_ = self.hitch_vis(tr) if self.hitch_vis(tr) in ("gylle", "gylle_s", "potato", "harrow") else None
                vis = gv_ or m["tool"] or self.hitch_tool(tr) or m.get("wagon") or \
                    ((tr.get("hitch") or "")[2:].split("#")[0] if (tr.get("hitch") or "").startswith("w:") else None)
                out.append([tr["id"], tr["o"], round(tr["x"], 3), round(tr["y"], 3), tr["d"],
                            m["tool"] if moving else None, tr["k"], "manual", tr["hs"], vis,
                            round(m["v"], 2), round(ld / cap, 2) if cap else 0.0, int(tr.get("wear", 0)),
                            2 if self.is_outside(tr) else 0, m.get("drv"), m.get("dname"), bool(tr.get("helper")),
                            [round(ld), cap, (m.get("cargo") or {}).get("src")] if cap else None,
                            self._act_view(m), tr.get("hitch"), m["tool"], tr.get("upg", []), bool(m.get("gps")),
                            int(tr.get("dirt", 0)), round(tr.get("hours", 0.0), 1), tr.get("log", []),
                            bool(m.get("washing")), tr.get("upg_wait", []),
                            [m.get("ld", "up"), m.get("fl")],
                            [round(tr.get("fuel", fuel_cap(tr["k"], tr)), 1), fuel_cap(tr["k"], tr), bool(m.get("fueling"))],
                            plow_on(tr), bale_view((m.get("cargo") or {}).get("load"), wagon_slots(m.get("wagon")),
                                                   shape=(m.get("cargo") or {}).get("s"))
                            if m.get("wagon") else None])
                continue
            x, y, working = self.view_xy(tr)
            state = tr["tool"] if working else ("drive" if tr["s"] == "move" else
                                                 "repair" if tr["s"] == "repair" else "home")
            imp = tr["tool"]
            if imp == "fertilize" and self.use_gylle(self.players.get(tr["o"]) or {}):
                imp = "gylle_s" if "gyllevogn_slange" in (self.players.get(tr["o"]) or {}).get("equip", []) else "gylle"
            elif imp == "harvest" and vkind(tr["k"]) == "tractor" and tr.get("tx") is not None and \
                    self.inb(tr["tx"], tr["ty"]) and self.tiles[tr["ty"]][tr["tx"]].crop == "kartofler":
                imp = "potato"
            elif imp == "plow" and tr.get("tx") is not None and self.inb(tr["tx"], tr["ty"]) and \
                    self._harrow_ok(self.players.get(tr["o"]), self.tiles[tr["ty"]][tr["tx"]]):
                imp = "harrow"
            h = tr.get("haul")
            load = 0.0
            if h:
                state = "haul_milk" if h["cargo"] == "milk" else \
                    {"in": "haul_in", "out": "haul_out", "bales": "haul_bales"}.get(h.get("job"), "haul_" + h["cargo"])
                imp = h.get("wagon")
                if h["leg"] == 2:
                    load = min(1.0, (sum(h["load"].values()) if h["cargo"] in ("grain", "milk") else
                                     h["n"] * ANIMAL_UNITS[h["kind"]]) / max(1, h["cap"]))
            d_ = tr["spot_d"] if tr["s"] == "parked" and tr.get("spot") and list(tr["hs"]) == list(tr["spot"]) \
                and tr.get("spot_d") is not None else tr["d"]          # holder på sin faste plads, som den blev sat
            out.append([tr["id"], tr["o"], round(x, 3), round(y, 3), d_,
                        tr["tool"] if working else None, tr["k"], state, tr["hs"], imp, 0.0, round(load, 2),
                        int(tr.get("wear", 0)), 1 if tr.get("hire") else 2 if self.is_outside(tr) else
                        3 if self.car_garage(tr) else 0,
                        None, None, bool(tr.get("helper")), None, None, tr.get("hitch"), None, tr.get("upg", []), False,
                        int(tr.get("dirt", 0)), round(tr.get("hours", 0.0), 1), tr.get("log", []), False,
                        tr.get("upg_wait", []), None,
                        [round(tr.get("fuel", fuel_cap(tr["k"], tr)), 1), fuel_cap(tr["k"], tr), False]
                        if not tr.get("hire") else None, plow_on(tr),
                        bale_view(h["load"], wagon_slots(h.get("wagon")), shape=h.get("bs")) if h and h.get("job") == "bales" and h["leg"] == 2 and h.get("wagon")
                        else None])
        return out

    @staticmethod
    def lawn_stage(g):
        return 0 if g < 0.35 else 1 if g < 0.7 else 2

    def _grow_lawns(self, m):
        """Græsplæner gror i vækstsæsonen. Står der en havetraktor, som ikke køres manuelt, slår den selv
        plænen en gang om ugen, når græsset er blevet langt."""
        rate = PLAENE_GROW.get(m, 0.0)
        lawns = {}
        for y, row in enumerate(self.tiles):
            for x, t in enumerate(row):
                if t.t != "plaene":
                    continue
                st = self.lawn_stage(t.g)
                t.g = min(1.0, t.g + rate)
                if self.lawn_stage(t.g) != st:
                    self.dirty.add((x, y))
                lawns.setdefault(t.o, []).append((x, y, t))
        manual = self.manual_mode()
        for pid, p in self.players.items():
            tl = lawns.get(pid, [])
            if not tl:
                p["lawn"] = (0, 0.0)
                continue
            avg = sum(t.g for _, _, t in tl) / len(tl)
            mowers = [tr for tr in self.tractors if tr["o"] == pid and VEHICLES.get(tr["k"], {}).get("mower")
                      and not tr.get("hire") and tr["s"] != "manual"]
            auto = [tr for tr in mowers if not manual or p.get("ai") or tr.get("helper")] \
                if self.auto_on(p, "plaene") else []
            wide = any("bredklip" in tr.get("upg", ()) for tr in auto)
            if auto and (avg > 0.3 and self.day % 4 == 0 if wide else avg > 0.5 and self.day % 7 == 0):
                for x, y, t in tl:
                    if t.g >= 0.1:
                        t.g = 0.0
                        self.dirty.add((x, y))
                tr = auto[0]
                tr["hours"] = tr.get("hours", 0.0) + 0.05 * len(tl)
                p["mowed"] = p.get("mowed", 0) + len(tl)
                avg = 0.0
                if not p.get("ai"):
                    self.log(f"Havetraktoren har slået græsplænen ({len(tl)} felt{'er' if len(tl) > 1 else ''}).",
                             pid, "info")
            elif avg >= 0.8 and len(tl) >= 4 and not p.get("ai") and p.get("lawn_warn", -99) < self.day - 30:
                p["lawn_warn"] = self.day
                self.log("Græsplænen er ved at gro til – det koster prestige. Slå den med en havetraktor "
                         "(sænk klipperen med L, når du kører selv).", pid, "warn")
            p["lawn"] = (len(tl), round(avg, 3))

    # ── en dag går ───────────────────────────────────────────────────────────
    def advance_day(self):
        self._sandbox_topup()
        self.ver += 1
        fields = [(x, y, t) for y, row in enumerate(self.tiles) for x, t in enumerate(row) if t.t in ("field", "stub")]
        before = [t.pack() for _, _, t in fields]
        self.day += 1
        m = self.month()
        rng = self.rng
        self._roll_weather(m)
        w = self.weather
        irr, near_water = set(), set()
        for y, row in enumerate(self.tiles):
            for x, t in enumerate(row):
                if t.t == "water":
                    near_water.update((x + dx, y + dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1))
        for y_, row in enumerate(self.tiles):          # ung skov vokser til
            for x_, t in enumerate(row):
                if t.t == "forest" and t.lc == "ung":
                    t.g += 1.0 / FOREST_GROW
                    if t.g >= 1:
                        t.lc, t.g = None, 0.0
                    if self.day % 30 == 0 or t.lc is None:
                        self.dirty.add((x_, y_))
        self._grow_lawns(m)
        R = DITCH_REACH
        for x, y in self.wet_ditches():
            irr.update((x + dx, y + dy) for dx in range(-R, R + 1) for dy in range(-R, R + 1))
        net, forsoeg = self.done("vandingsnet"), self.done("forsoeg")
        dm = {"Regn": 14, "Storm": 12, "Sne": 4, "Skyet": -3, "Sol": -6, "Tørke": -9, "Frost": -1, "Tåge": 0}[w]
        # snedækket: lægger sig ved sne, smelter i mildt vejr (kun pynt)
        if m in range(3, 10):
            self.snow = 0.0
        if self.snow < 0.3 and self.plowed:
            self.plowed = set()
        elif w == "Sne":
            self.snow = min(1.0, self.snow + 0.4)
            if self.plowed:
                self.plowed = set()                  # ny sne på vejene
            if self.snow >= 0.3 and self.records.get("snow_news", -99) < self.day - 20:
                self.records["snow_news"] = self.day
                self.log(f"Sne på vejene! Kommunen betaler {SNOW_PAY} kr pr. vejfelt, der ryddes med sneplov "
                         "(værktøjet Sneplov).", None, "info")
        elif w in ("Regn", "Storm"):
            self.snow = max(0.0, self.snow - 0.35)
        elif w in ("Sol", "Skyet", "Tåge"):
            self.snow = max(0.0, self.snow - (0.2 if m in (2, 10) else 0.08))
        if w == "Sol" and m in (5, 6, 7):
            dm = -7
        growing = 2 <= m <= 9
        ripe_n, dead_n, over_n = {}, {}, {}
        shelter = self.shelter_cells()
        for x, y, t in fields:
            t.m = clamp(t.m + dm + rng.uniform(-1.5, 1.5) + (self.topo_moist(x, y) if self.hm else 0.0), 0.0, 100.0)
            if (x, y) in near_water:
                t.m = max(t.m, 45.0)
            if (x, y) in irr:
                t.m = max(t.m, 60.0)
            if net:
                t.m = max(t.m, 35.0)
            if t.imm > 0:
                t.imm -= 1
            t.kc = max(0.0, t.kc - LIME_DROP)
            if not t.crop:
                t.n = min(100.0, t.n + 0.06)             # jorden hviler
                if growing:
                    t.wd = min(100.0, t.wd + 0.25)
            elif t.crop == "graes":
                t.n = min(100.0, t.n + 0.12)             # kløveren binder kvælstof
            elif CROPS[t.crop].get("green"):
                t.n = min(100.0, t.n + 0.08)             # efterafgrøden samler næring
                t.wd = max(0.0, t.wd - 0.2)              # og kvæler ukrudtet
            elif growing and not t.dead and self.opts.get("weeds", True):
                t.wd = min(100.0, t.wd + 0.3)
            if not t.crop or t.dead:
                continue
            c = CROPS[t.crop]
            own = t.o if t.o >= 0 else None
            if t.g >= 1:
                t.rip += 1
                if c.get("perennial") or c.get("green"):
                    t.rip = min(t.rip, 1)                # græs visner ikke – det står bare og venter på slæt
                if t.rip > RIPE_DAYS:                    # overmoden: udbyttet falder langsomt
                    t.h = max(1.0, t.h - 1.5)
                    if t.rip == RIPE_DAYS + 1 and own in self.players:
                        over_n[own] = over_n.get(own, 0) + 1
                if t.rip > OVERRIPE_DEAD:
                    t.dead, t.pest = True, 0
                    dead_n[own] = dead_n.get(own, 0) + 1
                continue
            rate = 1.0 if growing else (0.25 if c["hardy"] and not c.get("orchard") else 0.0)
            if c.get("orchard") and w == "Frost" and m in (3, 4) and self.opts["frost"]:
                t.h -= 6                                 # nattefrost i blomstringen koster frugt
            if not c["hardy"] and w in ("Frost", "Sne") and self.opts["frost"]:
                if not growing:
                    t.h -= 40
                elif t.g < 0.4:
                    t.h -= 7
            thirst = self.opts["thirst"]
            # tørke går mest ud over sundheden (udbyttet) – væksten bremses kun lidt, så høsttiden holder
            sh_ = LAEHEGN_SHIELD if (x, y) in shelter else 1.0      # læhegn: mindre udtørring og stormskade
            if t.m < 12:
                mf = 0.5
                t.h -= DROUGHT_DAMAGE * c["water"] * sh_ if thirst else 0
            elif t.m < 30:
                mf = 0.85
                t.h -= 0.3 * c["water"] if thirst else 0
            elif t.m <= 90:
                mf = 1.0
                if not t.pest:
                    t.h = min(100.0, t.h + 0.6)
            else:
                mf = 0.9
                t.h -= 0.2
            if w == "Storm":
                t.h -= rng.uniform(0, STORM_DAMAGE) * sh_
            if t.pest:
                t.h -= PEST_DAMAGE
            if forsoeg:
                rate *= 1.15
            if t.wd > 60:
                rate *= 0.92                             # ukrudtet konkurrerer med afgrøden
            t.g = min(1.0, t.g + rate * mf / c["days"])
            if c.get("orchard"):
                t.h = max(t.h, 15.0)                     # træerne overlever tørke – de giver bare mindre frugt
            if t.h <= 0:
                t.h, t.dead, t.pest = 0.0, True, 0
                dead_n[own] = dead_n.get(own, 0) + 1
            elif t.g >= 1 and not c.get("green"):
                t.rip = 0
                ripe_n.setdefault(own, {})
                ripe_n[own][t.crop] = ripe_n[own].get(t.crop, 0) + 1
        self._sync_fields(fields, ripe_n)
        self._pests(m, forsoeg)
        self._livestock()
        self._spoil_piles()
        for p in self.players.values():
            self._sync_park(p, True)
        self._show_day()
        self._pull_day()
        self._stormflod()
        self._season_day()
        self._plan_day()
        self._energy_day()
        self._shared_power()
        self._dry_day()
        self._ai_days()
        self._guide_check()
        self._auto_wash()
        for p in self.players.values():              # hvor længe har høsten ligget i marken (Styr selv)
            if self.pile_total(p) + self.bales_total(p) > 0.5:
                p.setdefault("pile_since", self.day)
            else:
                p.pop("pile_since", None)
        self._hire_combines()
        if self.day % MILK_PICKUP_DAYS == 0:
            self._milk_pickup()
        self._own_freight_timeout()
        self._hire_haulers()
        self._weather_wear()
        self._auto_service()
        self._contracts_day()
        self._deals_day()
        self._ms_day()
        self._rent_day()
        self._torder_day()
        for own, crops in ripe_n.items():
            if own in self.players:
                s = ", ".join(f"{n} felter {CROPS[c]['navn'].lower()}" for c, n in crops.items())
                self.log(f"Klar til høst: {s}.", own, "good")
        for own, n in over_n.items():
            self.log(f"{n} felter står overmodne – udbyttet falder lidt hver dag, til de bliver høstet.", own, "warn")
        for own, n in dead_n.items():
            if own in self.players:
                self.log(f"{n} felt{'er' if n > 1 else ''} med afgrøder er gået tabt.", own, "err")
        if self.day % DAYS_PER_MONTH == 0:
            self._new_month(m)
        self._market(m)
        for (x, y, t), b in zip(fields, before):
            if t.pack() != b:
                self.dirty.add((x, y))

    @staticmethod
    def _same_field(a, b):
        """Hører to nabofelter til samme mark? Samme ejer, samme afgrøde og sået omtrent samtidig."""
        if a.o != b.o or a.t != b.t or a.crop != b.crop or a.dead != b.dead:
            return False
        return not a.crop or abs(a.g - b.g) < 0.25 or (a.g >= 1 and b.g >= 1)

    def _sync_fields(self, fields, ripe_n):
        """En mark vokser og modner samlet, og ukrudtet fordeler sig jævnt over hele marken."""
        idx = {(x, y): t for x, y, t in fields}
        seen = set()
        for start, t0 in idx.items():
            if start in seen:
                continue
            seen.add(start)
            comp, k = [start], 0
            while k < len(comp):
                cx, cy = comp[k]
                k += 1
                a = idx[(cx, cy)]
                for dx, dy in N4:
                    nb = (cx + dx, cy + dy)
                    b = idx.get(nb)
                    if b is not None and nb not in seen and self._same_field(a, b):
                        seen.add(nb)
                        comp.append(nb)
            if len(comp) < 2:
                continue
            tiles = [idx[c] for c in comp]
            n = len(tiles)
            wd = sum(t.wd for t in tiles) / n
            for t in tiles:
                t.wd = wd
            if not t0.crop or t0.dead:
                continue
            g = sum(t.g for t in tiles) / n
            if max(t.g for t in tiles) >= 1 and g >= 0.97:          # hele marken modner på én gang
                new = 0
                for t in tiles:
                    if t.g < 1:
                        t.g, t.rip = 1.0, 0
                        new += 1
                if new and not CROPS[t0.crop].get("green"):
                    own = t0.o if t0.o >= 0 else None
                    ripe_n.setdefault(own, {})
                    ripe_n[own][t0.crop] = ripe_n[own].get(t0.crop, 0) + new
                rip = min(t.rip for t in tiles)
                for t in tiles:
                    t.rip = rip
            else:
                for t in tiles:
                    t.g = min(g, 0.999)

    def _roll_weather(self, m):
        rng = self.rng
        if self.drought > 0:
            self.drought -= 1
            self.weather = "Tørke"
            if self.drought == 0:
                self.weather = "Regn"
                self.log("Tørken er ovre – endelig regn!", None, "good")
            return
        eg = egn_of(self)
        if self.opts["drought"] and m in (5, 6, 7) and rng.random() < 0.012 * eg["drought"]:
            self.drought = rng.randint(12, 28)
            self.weather = "Tørke"
            self.log("TØRKE! Ingen regn de næste uger. Grøfter med vand fra sø eller brønd – eller et vandingsanlæg – "
                     "redder markerne.", None, "warn")
            self.add_news("Tørken rammer egnen", f"Meteorologerne venter ingen regn de næste {self.drought} dage. "
                          "Landmænd med grøfter fra søer og brønde klarer sig bedst.")
            return
        winter = m in (11, 0, 1)
        r = rng.random()
        if self.opts["storm"] and m in (8, 9, 10) and r < 0.03:
            self.weather = "Storm"
            self.log("Storm over egnen – afgrøderne tager skade.", None, "warn")
            if self.day - self.records.get("storm_news", -99) > 20:
                self.records["storm_news"] = self.day
                self.add_news("Storm over egnen", "Et kraftigt stormvejr har væltet træer og lagt korn ned flere steder.")
        elif r < RAIN_CHANCE[m] * eg["rain"]:
            self.weather = "Sne" if winter else "Regn"
        elif m in (2, 9, 10) and rng.random() < 0.12:
            self.weather = "Tåge"                      # efterårs- og forårståge – kun stemning
        elif (winter and rng.random() < 0.5) or (m in (2, 3) and rng.random() < 0.06):
            self.weather = "Frost"
            if m in (2, 3) and self.opts["frost"]:
                self.log("Nattefrost! Unge afgrøder kan tage skade.", None, "warn")
        else:
            self.weather = "Skyet" if rng.random() < 0.4 else "Sol"

    def _pests(self, m, forsoeg):
        rng = self.rng
        if not self.opts["pests"]:
            return
        chance = (PEST_SPREAD if 2 <= m <= 9 else 0.01) * (0.5 if forsoeg else 1.0)
        pests = [(x, y) for y, row in enumerate(self.tiles) for x, t in enumerate(row) if t.pest]
        new, cross = [], set()
        for x, y in pests:
            for dx, dy in N4:
                nx, ny = x + dx, y + dy
                if not self.inb(nx, ny):
                    continue
                nt = self.tiles[ny][nx]
                if nt.crop and not nt.dead and not nt.pest and nt.imm == 0 and rng.random() < chance:
                    new.append((nx, ny))
                    a, b = self.owner(x, y), self.owner(nx, ny)
                    if a != b and b is not None:
                        cross.add((a, b))
        for x, y in new:
            self.tiles[y][x].pest = 1
        for a, b in cross:
            if b in self.players and a is not None:
                self.log(f"Skadedyr fra {self.pname(a)}s marker har spredt sig til dine!", b, "warn")
                if a in self.players:
                    self.log(f"Dine skadedyr har spredt sig til {self.pname(b)}s marker.", a, "warn")
        if 3 <= m <= 8 and rng.random() < PEST_OUTBREAK:
            cands = [(x, y) for y, row in enumerate(self.tiles) for x, t in enumerate(row)
                     if t.crop and not t.dead and t.imm == 0 and not t.pest]
            if cands:
                x, y = rng.choice(cands)
                self.tiles[y][x].pest = 1
                own = self.owner(x, y)
                crop = CROPS[self.tiles[y][x].crop]["navn"].lower()
                self.log(f"Bladlus angriber din {crop}! Send traktoren ud og sprøjt, før de spreder sig.",
                         own, "warn")
                for pid in self.players:
                    if pid != own:
                        self.log(f"Bladlus hos {self.pname(own)} – hold øje med dine marker.", pid, "info")

    def _auto_feed(self, p, inv, cneed):
        """Automatik › Køb foder: køb dagens manglende foder hos grovvarehandlen (lidt over markedsprisen)."""
        oneed = sum(self.feed_need(p, k) for k in ANIMALS if k not in GRAZERS)
        grain = sum(inv.get(g, 0.0) for g in FEED_ORDER)
        silage = sum(inv.get(g, 0.0) for g in SILAGE_GOODS)
        buy = {}
        # græsserne tager ensilage op til 70% og korn til resten – grise og høns kun korn
        buy_s = max(0.0, cneed * 0.7 - silage)
        s_used = min(silage + buy_s, cneed * 0.7)
        buy_g = max(0.0, oneed + (cneed - s_used) - grain)
        if buy_s > 0.01:
            buy["graes"] = buy_s
        if buy_g > 0.01:
            buy["byg"] = buy_g
        if not buy:
            return
        cost = sum(q * max(self.market[g]["p"], 0.01) * AUTO_FEED_MARKUP for g, q in buy.items())
        if p["money"] < cost and not self.sandbox():
            if self.day - p.get("feed_buy_warn", -99) >= 10:
                p["feed_buy_warn"] = self.day
                self.log("Der er ikke penge nok til at købe foder automatisk.", p["id"], "err")
            return
        for g, q in buy.items():
            inv[g] = inv.get(g, 0.0) + q
        p["money"] -= cost
        self.book(p, "varekoeb", -cost)
        p["feed_bought"] = p.get("feed_bought", 0.0) + cost
        if self.day - p.get("feed_buy_log", -99) >= 10:
            p["feed_buy_log"] = self.day
            self.log(f"Foderet slap op – der er købt foder automatisk hos grovvarehandlen (i dag {kr(cost)}). "
                     "Kan slås fra under Menu › Automatik.", p["id"], "info")

    @staticmethod
    def _take_silage(inv, amount, used=None):
        """Ensilage fra plansiloen først – græs- og majsensilage blandes efter, hvor meget der er af hver –
        derefter wrapballer. used: {vare: mængde} fyldes med, hvad der blev taget."""
        got = 0.0
        if amount <= 0:
            return got
        bunk = [g for g in ("graes", "majsens") if inv.get(g, 0.0) > 0]
        tot = sum(inv[g] for g in bunk)
        if tot > 0:
            want = min(amount, tot)
            for g in bunk:
                a = min(inv[g], want * inv[g] / tot)
                inv[g] -= a
                got += a
                if used is not None:
                    used[g] = used.get(g, 0.0) + a
        for g in SILAGE_GOODS:
            a = min(amount - got, inv.get(g, 0.0))
            if a > 1e-9:
                inv[g] = inv.get(g, 0.0) - a
                got += a
                if used is not None:
                    used[g] = used.get(g, 0.0) + a
        return got

    def _livestock(self):
        grazing = 2 <= self.month() <= 9
        for p in self.players.values():
            inv = p["inv"]
            # græssere (køer, får, heste): ensilage først – de græsser halvdelen af foderet selv om sommeren
            cneed = sum(p.get(k, 0) * ANIMALS[k][4] for k in GRAZERS) * (0.5 if grazing else 1.0) * \
                self.feed_factor(p["id"]) * \
                (1.0 - FODERHAL_SAVE if self.has_foderhal(p) else 1.0)       # foderhallen: ensilage under tag
            if self.auto_on(p, "foder") and not p.get("ai"):
                self._auto_feed(p, inv, cneed)
            # baller i foldens foderhække: de ædes op over FOLD_BALE_DAYS dage – wrapballer tæller som ensilage
            fb = p.get("fbales")
            fold_feed = 0.0
            if fb:
                past_ = set(self.pasture(p["id"]))
                for k_ in list(fb):
                    b_ = fb[k_]
                    if b_["g"] == "wrap" and b_["f"] > 0 and fold_feed < cneed:
                        e_ = min(b_["f"], b_["f0"] / FOLD_BALE_DAYS, cneed - fold_feed)
                        b_["f"] -= e_
                        fold_feed += e_
                    b_["d"] -= 1
                    if b_["d"] <= 0 or tuple(map(int, k_.split(","))) not in past_:
                        del fb[k_]
                        self.touch(*map(int, k_.split(",")))
                if not fb and not p.get("ai") and sum(p.get(k, 0) for k in GRAZERS):
                    self.log("Ballerne i folden er ædt op – sæt en ny halm- eller wrapballe i foderhækken "
                             f"(+{int(FOLD_BALE_BONUS * 100)}% mælk og afkast).", p["id"], "info")
            self._farm_chores(p)
            self._bale_overflow(p)
            self._auto_fold_bales(p)
            self._stuck_jobs(p)
            self._bees(p)
            self._mice(p)
            self._halmfyr(p)
            self._greenhouse(p)
            self._mill(p)
            self._calves(p)
            self._gates_day(p)
            fbonus = 1.0 + self.fold_bonus(p)
            p["fold_bonus"] = round(fbonus - 1.0, 3)
            # foderplan: højst 70% ensilage, resten korn – mangler der korn, gives mere ensilage
            sused = {"wrap": fold_feed}                   # hvilken ensilage køerne fik (til majsblandingen)
            silage = fold_feed + self._take_silage(inv, max(0.0, cneed * 0.7 - fold_feed), sused)
            cgot = silage
            cval = 0.0                                    # foderets værdi (til regnskabet pr. dyreart)
            feed_order = self.feed_order(p)
            for g in feed_order:
                if cgot >= cneed:
                    break
                take = min(cneed - cgot, inv.get(g, 0.0))
                inv[g] -= take
                cgot += take
                cval += self.val(g, take)
            if cgot < cneed:
                extra = self._take_silage(inv, cneed - cgot, sused)
                silage += extra
                cgot += extra
            cval += sum(self.val("graes" if g == "wrap" else g, q) for g, q in sused.items())
            oneed = sum(self.feed_need(p, k) for k in ANIMALS if k not in GRAZERS)
            ogot = oval = 0.0
            for g in feed_order:
                if ogot >= oneed:
                    break
                take = min(oneed - ogot, inv.get(g, 0.0))
                inv[g] -= take
                ogot += take
                oval += self.val(g, take)
            fc = cgot / cneed if cneed > 0 else 1.0
            fo = ogot / oneed if oneed > 0 else 1.0
            # halm til strøelse: dyrene trives bedre og yder 15% mere
            sneed = sum(p.get(k, 0) * STRAW_USE[k] for k in ANIMALS)
            straw_ok = False
            if sneed > 0 and inv.get("halm", 0) >= sneed:
                inv["halm"] -= sneed
                straw_ok = True
            bonus = 1.15 if straw_ok else 1.0
            mix = 1.0
            if cgot > 0 and 0.3 <= silage / cgot <= 0.9:
                mix = 1.2                                 # blandet foder: ensilage + korn giver mere mælk
            # græs- og majsensilage sammen: hver mindst en femtedel af ensilagen giver køerne endnu mere mælk
            ms_ = sused.get("majsens", 0.0)
            mix2 = silage > 0 and min(ms_, silage - ms_) >= MAJSENS_SHARE * silage
            p["mix"], p["straw_ok"], p["mix2"] = mix > 1.0, straw_ok, bool(mix2)
            if mix2:
                mix += MAJSENS_MIX
            straw_val = self.val("halm", sneed) if straw_ok else 0.0
            for k, a in ANIMALS.items():
                f = fc if k in GRAZERS else fo
                n = p.get(k, 0)
                if n:                                          # foder og strøelse fordelt efter dyrenes behov
                    need_k = (n * a[4] * (0.5 if grazing else 1.0)) if k in GRAZERS else self.feed_need(p, k)
                    fv = cval * need_k / cneed if k in GRAZERS and cneed > 0 else \
                        oval * need_k / oneed if k not in GRAZERS and oneed > 0 else 0.0
                    sv = straw_val * n * STRAW_USE[k] / sneed if sneed > 0 else 0.0
                    self._acc(p, "aacc", k, feed=fv + sv, days=n)
                if a[5]:
                    # sultne dyr giver ingen mælk, æg, uld eller tilvækst – først når de får foder nok igen
                    n_ = n - (1 if (p.get("loose") or {}).get("k") == k else 0)       # det udbrudte dyr giver intet
                    prod = a[6] * max(0, n_) * bonus * (mix if k == "cows" else 1.0) * \
                        (fbonus if k in GRAZERS else 1.0) * (1.0 + self.muck_bonus(p, k)) if f >= HUNGRY_FED else 0.0
                    if k in ("pigs", "chickens") and self.capacity(p, "fodersilo"):
                        prod *= 1 + FEEDSILO_BONUS             # fodersiloen blander kraftfoderet rigtigt
                    if k == "cows" and n:                      # malkerobot: mere mælk til de køer, den kan klare
                        prod *= 1 + ROBOT_MILK * min(1.0, self.robot_cap(p) / n)
                    inv[a[5]] += prod
                    self._rec(p, "prod", a[5], prod)
                    if prod > 0:
                        self._acc(p, "aacc", k, rev=self.val(a[5], prod))
                    if k in ECO_KINDS and prod > 0:                # økologisk på græs: økotillæg for den del, der går ude
                        es = self.eco_share(p, k)
                        if es > 0:
                            cut = prod * ECO_YIELD * es               # … men de giver lidt mindre
                            inv[a[5]] -= cut
                            self._rec(p, "prod", a[5], -cut)
                            prod -= cut
                            bonus_kr = self.val(a[5], prod) * ECO_BONUS * es
                            p["money"] += bonus_kr
                            self.book(p, "oko", bonus_kr)
                            self._acc(p, "aacc", k, rev=bonus_kr)
                elif k == "horses" and n:                     # rideskolen betaler for opstaldningen
                    pay = HORSE_PENSION * n * (0.5 + 0.5 * f) * fbonus * (1.0 + self.muck_bonus(p, k))
                    p["money"] += pay
                    self.book(p, "heste", pay)
                    self._acc(p, "aacc", k, rev=pay)
                g_add = GYLLE[k] * n
                gcap = self.gylle_cap(p)
                if p.get("gylle", 0.0) < gcap:
                    p["gylle"] = min(gcap, p.get("gylle", 0.0) + g_add)
                elif g_add > 0:
                    p["gylle_full"] = True
            if p.pop("gylle_full", False) and self.day - p.get("gylle_warn", -99) >= DAYS_PER_MONTH:
                p["gylle_warn"] = self.day
                self.log(f"Gylletanken er fuld ({int(p['gylle'])} af {int(self.gylle_cap(p))}) – den nye gylle går til "
                         "spilde. Kør den ud med Gød (vælg Gylle), eller byg en gylletank.", p["id"], "warn")
            self._biogas(p)
            self._farm_shop(p)
            was = p["hungry"]
            p["hungry"] = (cneed > 0 and fc < 0.99) or (oneed > 0 and fo < 0.99)
            if p["hungry"] and (not was or self.day % 5 == 0):
                stop = [ANIMALS[k][3] for k, a in ANIMALS.items() if p.get(k, 0) and a[5] and
                        (fc if k in GRAZERS else fo) < HUNGRY_FED]
                self.log("Dine dyr mangler foder (ensilage, majs, byg, hvede eller kartofler)!" +
                         (f" Sultne {', '.join(stop)} giver ingen mælk, æg eller uld, før de får nok." if stop else ""),
                         p["id"], "warn")

    def _dry_day(self):
        """Vådt korn: korntørreriet tørrer det (mod betaling) – ellers mugner lidt af det hver dag."""
        for p in self.players.values():
            wg = p.get("wetg")
            if not wg:
                continue
            cap = self.capacity(p, "korntoerreri")
            dried = cost = lost = 0.0
            for g in list(wg):
                have = p["inv"].get(g, 0.0) + p.get("pile", {}).get(g, 0.0)
                wg[g] = min(wg[g], have)                 # det, der er solgt eller spist, er ikke vådt længere
                if cap > 0 and wg[g] > 0:
                    d = min(wg[g], cap)
                    if p["money"] >= d * DRY_COST or self.sandbox():
                        wg[g] -= d
                        cap -= d
                        dried += d
                        cost += d * DRY_COST
                if wg[g] > 0.5:
                    rot = wg[g] * WET_ROT
                    wg[g] -= rot
                    lost += rot
                    src = "pile" if p.get("pile", {}).get(g, 0) >= rot else None
                    if src:
                        p["pile"][g] -= rot
                    else:
                        p["inv"][g] = max(0.0, p["inv"].get(g, 0.0) - rot)
                if wg[g] < 0.5:
                    del wg[g]
            if cost > 0:
                p["money"] -= cost
                self.book(p, "toerring", -cost)
            if dried and not wg:
                self.log(f"Korntørreriet har tørret det våde korn ({int(dried)} enheder i dag, -{kr(cost)}).", p["id"], "good")
            if lost > 0 and p.get("rot_hint", -99) < self.day - 10:
                p["rot_hint"] = self.day
                self.log(f"Vådt korn mugner: {sum(wg.values()):.0f} enheder er stadig våde. Sælg det, eller byg et "
                         "korntørreri.", p["id"], "warn")

    def wind_now(self):
        return WIND.get(self.weather, 1.0) * WIND_SEASON[self.month()] * egn_of(self)["wind"]

    def sun_now(self):
        return SUN.get(self.weather, 0.5) * SUN_SEASON[self.month()]

    def _energy_day(self):
        """Vindmøller og solceller sælger strøm hver dag – efter vejret og årstiden."""
        for p in self.players.values():
            bp = self.stats(p["id"])["bpos"]
            mills, panels = bp.get("vindmoelle", []), bp.get("solcelleanlaeg", [])
            if not mills and not panels:
                continue
            stop = p.setdefault("mill_stop", {})
            for k in [k for k, until in stop.items() if until <= self.day]:
                del stop[k]
                self.log("Vindmøllen er repareret og kører igen.", p["id"], "good")
            wind_pay = 0.0
            for (x, y) in mills:
                key = f"{x},{y}"
                if key in stop:
                    continue
                if self.weather == "Storm" and self.rng.random() < 0.12:
                    stop[key] = self.day + 5
                    p["money"] -= MILL_REPAIR
                    self.book(p, "reparation", -MILL_REPAIR)
                    self._acc(p, "eacc", "vindmoelle", upk=MILL_REPAIR)
                    self.log(f"Stormen har skadet en vindmølle – reparation {kr(MILL_REPAIR)}, og den står stille i 5 dage.",
                             p["id"], "warn")
                    continue
                wind_pay += MILL_BASE * self.wind_now()
            sun_pay = SOLAR_BASE * self.sun_now() * len(panels)
            for key, pay in (("vindmoelle", wind_pay), ("solcelleanlaeg", sun_pay)):
                if pay > 0:
                    p["money"] += pay
                    self.book(p, "stroem", pay)
                    self._acc(p, "eacc", key, rev=pay)
            p["power_kr"] = p.get("power_kr", 0) + wind_pay + sun_pay

    def _biogas(self, p):
        """Biogasanlægget laver strøm af gylle og overskudsensilage. Den afgassede gylle kommer tilbage som gødning."""
        n = self.stats(p["id"])["b"].get("biogas", 0)
        if not n:
            return
        # dagens gylle fra dyrene går gennem anlægget og kommer ud igen som afgasset gylle (bliver i gyllelageret)
        g_use = min(sum(GYLLE[k] * p.get(k, 0) for k in ANIMALS), BIOGAS_GYLLE * n)
        feed30 = 30 * sum(p.get(k, 0) * ANIMALS[k][4] for k in GRAZERS)
        e_use = min(max(0.0, p["inv"].get("graes", 0.0) - feed30), BIOGAS_SILAGE * n) if p.get("bio_silage", True) else 0
        p["inv"]["graes"] -= e_use
        kwh = g_use * 3 + e_use * 14
        if kwh <= 0:
            return
        pay = kwh * POWER_PRICE
        p["money"] += pay
        self.book(p, "stroem", pay)
        self._acc(p, "eacc", "biogas", rev=pay)
        p["bio_kwh"] = p.get("bio_kwh", 0) + kwh
        p["bio_kr"] = p.get("bio_kr", 0) + pay

    def shop_traffic(self, p):
        """Kunder til gårdbutikken: veje tæt på butikken og en stor by giver flere kunder."""
        spot = self.stats(p["id"])["bpos"].get("ext:gaardbutik")
        if not spot:
            return 0.0
        x, y = spot[0]
        roads = sum(1 for yy in range(y - 3, y + 4) for xx in range(x - 3, x + 4)
                    if self.inb(xx, yy) and self.tiles[yy][xx].t in ROADS)
        public = any(self.inb(xx, yy) and self.tiles[yy][xx].t in ("road", "asphalt") and self.tiles[yy][xx].o < 0
                     for yy in range(y - 4, y + 5) for xx in range(x - 4, x + 5))
        return min(1.6, 0.35 + min(0.5, roads * 0.05) + (0.3 if public else 0) + 0.1 * self.town_lvl())

    def _farm_shop(self, p):
        if "gaardbutik" not in p.get("addons", []):
            return
        f = self.shop_traffic(p) * (2.0 if self.season() == "hoestfest" else 1.0)
        if self.month() == XMAS_MONTH and self.dom() <= XMAS_LAST:
            self._xmas_trees(p, f)
        total = 0.0
        for g, per_day in SHOP_GOODS.items():
            q = min(p["inv"].get(g, 0.0), per_day * f * self.rng.uniform(0.6, 1.4))
            if q <= 0:
                continue
            price = self.market[g]["p"] * SHOP_MARKUP * self.sale_bonus(g, p)
            p["inv"][g] -= q
            total += q * price
        if total > 0:
            p["money"] += total
            self.book(p, "butik", total)
            self.town_add(total * 0.5)
            p["shop_kr"] = p.get("shop_kr", 0) + total

    def _xmas_trees(self, p, traffic):
        """Juletræer fra egen skov sælges i gårdbutikken i december. For hver 8 træer bliver et skovfelt ungskov."""
        T = self.tiles
        forest = [(x, y) for y, row in enumerate(T) for x, t in enumerate(row)
                  if t.o == p["id"] and t.t == "forest" and t.lc != "ung"]
        xs = p.setdefault("xmas", {})
        if xs.get("year") != self.year():
            xs.clear()
            xs.update(year=self.year(), sold=0, quota=int(len(forest) * XMAS_PER_TILE), kr=0)
            if forest:
                self.log(f"Juletræssalget er åbnet i gårdbutikken – du har {xs['quota']} træer i din skov "
                         f"({kr(XMAS_TREE)} stk.).", p["id"], "good")
            else:
                self.log("Julen nærmer sig – med skov på din jord kunne gårdbutikken sælge juletræer.", p["id"], "info")
        if not forest or xs["sold"] >= xs["quota"]:
            return
        n = min(xs["quota"] - xs["sold"], max(0, int(round(traffic * self.rng.uniform(2.0, 6.0)))))
        if n <= 0:
            return
        pay = n * XMAS_TREE
        before = xs["sold"] // 8
        xs["sold"] += n
        xs["kr"] += pay
        p["money"] += pay
        self.book(p, "juletraer", pay)
        self.town_add(pay * 0.3)
        hx, hy = p["home"]
        for _ in range(xs["sold"] // 8 - before):          # et skovfelt tæt på gården bliver til ungskov
            forest.sort(key=lambda c: abs(c[0] - hx) + abs(c[1] - hy))
            if forest:
                x, y = forest.pop(0)
                T[y][x].lc, T[y][x].g = "ung", 0.0
                self.touch(x, y)
        if self.dom() == XMAS_LAST or xs["sold"] >= xs["quota"]:
            self.log(f"Juletræssalget er slut: {xs['sold']} træer for {kr(xs['kr'])}. Glædelig jul!", p["id"], "good")

    def _stormflod(self):
        """Marsken: stormflod om vinteren oversvømmer markerne helt ude ved vandet."""
        if (getattr(self, "world", None) or {}).get("egn") != "marsken" or self.month() not in (10, 11, 0, 1):
            return
        if not self.opts.get("storm", True) or self.rng.random() > 0.02:
            return
        T = self.tiles
        hit = {}
        for y, row in enumerate(T):
            for x, t in enumerate(row):
                if t.t in ("field", "stub") and any(self.inb(x + dx, y + dy) and T[y + dy][x + dx].t == "water"
                                                     for dx, dy in N4):
                    t.m = 100.0
                    if t.crop and not t.dead:
                        t.h = max(1.0, t.h - 30)
                    if t.o >= 0:
                        hit[t.o] = hit.get(t.o, 0) + 1
                    self.touch(x, y)
        self.weather = "Storm"
        self.log("Stormflod i marsken! Vandet er gået over markerne langs søerne.", None, "warn")
        for pid, n in hit.items():
            if pid in self.players:
                self.log(f"Stormfloden har oversvømmet {n} af dine markfelter – afgrøderne har taget skade.", pid, "warn")

    def _season_day(self):
        """Årstidens begivenheder: avis og log, når de begynder."""
        m, d = self.month(), self.dom()
        if (m, d) == (FEST_DAYS[0], FEST_DAYS[1]):
            self.log(f"Høstfest i {TOWN_NAME}! En uge med telte, musik og flag i byen – byen betaler 10% mere for "
                     "dine varer, og gårdbutikkerne har dobbelt så mange kunder.", None, "big")
            self.add_news(f"Høstfest i {TOWN_NAME}", "Byen fejrer høsten med telt på torvet, spillemænd og kagebord. "
                          "Handlende og gårdbutikker venter travle dage.")
        elif (m, d) == (HALLOWEEN_DAYS[0], HALLOWEEN_DAYS[1]):
            self.log("Græskarlygterne er tændt i byen – det er Halloween.", None, "info")
            self.add_news("Uhyggelig uge i byen", f"Børnene i {TOWN_NAME} går rundt og samler slik, og der står "
                          "græskarlygter på trapperne.")
        elif (m, d) == (XMAS_MONTH, 1):
            self.log(f"December! Julelys i {TOWN_NAME}, juletræ på torvet – og gårdbutikker med egen skov kan "
                     "sælge juletræer.", None, "big")
            self.add_news("Julen er tændt", f"Juletræet på torvet i {TOWN_NAME} er tændt, og der hænger lyskæder "
                          "over alle døre.")
        elif (m, d) == (STORK_MONTHS[0], 8):
            self.log("Storkene er tilbage! De går og snapper frøer på de pløjede marker.", None, "info")
            self.add_news("Storkene er landet", "De første storke er set på markerne uden for byen. Et godt tegn "
                          "for foråret, siger de gamle.")

    def _new_month(self, m):
        if m == SHOW_INVITE_MONTH and self.players:
            self._show_invite()
        if m == PULL_INVITE_MONTH and self.players:
            self._pull_invite()
        for p in self.players.values():                 # tip: fyld dieseltanken, når prisen er lav
            cap = self.capacity(p, "dieseltank")
            if cap and self.diesel < 0.93 and p.get("tank_l", 0) < cap * 0.6:
                self.log(f"Dieselprisen er lav ({fmt_price(self.diesel_price())}/l) – god tid at fylde dieseltanken "
                         "(højreklik på den).", p["id"], "info")
        if m == 0:
            self.log(f"Godt nytår! År {self.year()} begynder.", None, "big")
            for p in self.players.values():
                self._close_year(p)
            if self.players:
                self._aarets_gaard()
            for k, v in VEHICLES.items():
                if v["year"] == self.year() and not v.get("hidden"):
                    self.add_news(f"Ny på markedet: {vname(k)}", f"{MAKERS[v['maker']]['navn']} præsenterer {vname(k)} "
                                  f"med {v['hk']} HK til {kr(v['price'])}. {v['desc']}")
        elif self.rng.random() < 0.5:
            title, text = self.rng.choice(self.LOCAL_NEWS)
            self.add_news(title, text.replace("{by}", TOWN_NAME))
        for g, mk in self.market.items():
            h = mk["h"]
            self.phist.setdefault(g, [])
            self.phist[g] = (self.phist[g] + [round(sum(h) / len(h), 2)])[-36:]
        self.phist["diesel"] = (self.phist.get("diesel", []) + [round(self.diesel_price(), 2)])[-36:]
        self._town_month()
        self._new_offers()
        sow = [CROPS[c]["navn"] for c in CROPS if m in CROPS[c]["months"]]
        txt = f"Det er nu {MONTHS[m]}. {MONTH_TASKS[m]}"
        if sow:
            txt += " Kan sås nu: " + ", ".join(s_.lower() for s_ in sow) + "."
        self.log(txt, None, "info")
        for p in self.players.values():
            up = self.upkeep(p)
            auto_n = 0
            if p.get("manager") and p.get("fplan"):
                fl = dict(self.fields_of(p["id"]))
                auto_n = sum(len(fl.get(k, [])) for k, v in p["fplan"].items() if v.get("auto"))
            if auto_n:
                p["money"] -= auto_n * PLAN_FEE
                self.book(p, "drift", -auto_n * PLAN_FEE)
            p["money"] -= up
            interest, afdrag = self._pay_loans(p)
            for tr in self.tractors:                      # faste udgifter til hver maskine og stald i regnskabet
                if tr["o"] == p["id"] and not tr.get("hire") and tr["k"] in VEHICLES:
                    self._macc(tr, upk=VEHICLES[tr["k"]]["upkeep"])
            bcount = self.stats(p["id"])["b"]
            for b_ in ("vindmoelle", "solcelleanlaeg", "biogas"):
                if bcount.get(b_):
                    self._acc(p, "eacc", b_, upk=BUILDINGS[b_]["upkeep"] * bcount[b_])
            for k, a in ANIMALS.items():
                su = sum(BUILDINGS[b]["upkeep"] * n for b, n in bcount.items()
                         if b in BUILDINGS and (b == a[0] or BUILDINGS[b].get("group") == a[0]))
                if su and (p.get(k, 0) or str(k) in p.get("aacc", {}).get(str(self.year()), {})):
                    self._acc(p, "aacc", k, upk=su)
            self.book(p, "drift", -up)
            self.book(p, "renter", -interest)
            if p.get("rent_n"):
                self.log(f"Vognmanden kørte {int(p['rent_n'])} enheder høst hjem i sidste måned "
                         f"(-{kr(p['rent_haul'])}). Med en tipvogn eller kornbil gør du det selv.", p["id"], "info")
                p["rent_haul"] = p["rent_n"] = 0
            s = f"Månedlige udgifter: {kr(up)}"
            if interest > 0:
                s += f" + renter {kr(interest)}"
            if afdrag > 0:
                s += f" + afdrag på lån {kr(afdrag)}"
            ude = list(p.get("gear_pos", {}))
            if ude and self.opts.get("wear", True):
                val = sum(EQUIPMENT[it[2:]]["price"] if it.startswith("e:") else
                          WAGONS[it[2:].split("#")[0]]["price"] for it in ude)
                fix = int(val * 0.01)
                if fix > 0:
                    p["money"] -= fix
                    self.book(p, "reparation", -fix)
                    s += f". Udstyr, der står ude i vind og vejr: {kr(fix)} i reparationer – byg et maskinhus"
            if p.get("bio_kr", 0) >= 1:
                self.log(f"Biogasanlægget lavede {int(p['bio_kwh']):,} kWh strøm i sidste måned (+{kr(p['bio_kr'])})."
                         .replace(",", "."), p["id"], "good")
                p["bio_kr"] = p["bio_kwh"] = 0
            if p.get("shop_kr", 0) >= 1:
                self.log(f"Gårdbutikken solgte for {kr(p['shop_kr'])} i sidste måned.", p["id"], "good")
                p["shop_kr"] = 0
            if p.get("fuel_l", 0) >= 1:
                s += f". Diesel i sidste måned: {int(p['fuel_l'])} liter ({kr(p.get('fuel_kr', 0))} tanket)"
                p["fuel_l"] = p["fuel_kr"] = 0.0
            self.log(s + ".", p["id"], "info")
            p["wh"] = (p.get("wh", []) + [[round(self.worth(p)), round(p["money"])]])[-60:]
            if p["money"] < 0:
                self.log("Du er i minus! Sælg varer eller tag et lån.", p["id"], "err")
            if p.get("manager"):
                for imp, tip in self.advice(p)[:2]:
                    if imp >= 1:
                        self.log("Driftslederen: " + tip, p["id"], "chat")

    def _market(self, m):
        self.diesel = clamp(self.diesel + (1.0 - self.diesel) * 0.03 + self.rng.uniform(-0.015, 0.015), 0.8, 1.25)
        rate = 0.08 if self.done("station") else 0.04
        for g, mk in self.market.items():
            info = GOODS[g]
            target = info["base"]
            if info["season"]:
                target *= 1 + 0.18 * math.cos(2 * math.pi * (m - 3) / 12)
                if self.drought:
                    target *= 1.2
            mk["p"] += (target - mk["p"]) * rate
            mk["p"] *= 1 + self.rng.uniform(-0.02, 0.02)
            mk["p"] = clamp(mk["p"], info["base"] * 0.3, info["base"] * 2.5)
            mk["h"] = mk["h"][1:] + [round(mk["p"], 2)]

    # ── hastighed og afstemning ──────────────────────────────────────────────
    def _set_speed(self, v, who=None):
        if v == self.speed:
            return
        if self.speed:
            self.prev_speed = self.speed
        self.speed = v
        if who and self.n_voters > 1:
            txt = "satte spillet på pause" if v == 0 else f"satte hastigheden til {SPEED_NAMES[v]}"
            self.log(f"{who} {txt}.", None, "info")

    def act_speed(self, pid, v, drv=None, name=None):
        """Pause virker altid med det samme, og det gør det også at fortsætte i den hastighed, man holdt
        pause fra. Alt andet kræver flertal, når flere spillere er på."""
        who = name or self.pname(pid)
        if v not in DAY_SECONDS and v != 0:
            return
        if v == self.speed and not self.vote:
            return
        if v == 0 or self.n_voters <= 1 or (self.speed == 0 and v == self.prev_speed):
            self.vote = None
            self._set_speed(v, who)
            return
        if self.vote and self.vote["v"] == v:      # samme forslag igen = en ja-stemme
            self.act_vote(self.vote["id"], True, drv)
            return
        self.vote_seq += 1
        self.vote = {"id": self.vote_seq, "by": drv, "by_name": who, "v": v, "yes": [drv], "no": [],
                     "until": time.time() + VOTE_SECONDS, "n": self.n_voters}
        self.log(f"{who} foreslår at sætte tiden til {SPEED_NAMES[v]}. Stem ja eller nej øverst på skærmen.",
                 None, "info")
        self._vote_check()

    def act_vote(self, vid, yes, drv):
        vt = self.vote
        if not vt or vt["id"] != vid or drv in vt["yes"] or drv in vt["no"]:
            return
        (vt["yes"] if yes else vt["no"]).append(drv)
        self._vote_check()

    def _vote_need(self):
        return self.vote["n"] // 2 + 1

    def _vote_check(self, now=None):
        vt = self.vote
        if not vt:
            return
        vt["n"] = max(1, self.n_voters)
        need = self._vote_need()
        if len(vt["yes"]) >= need:
            self.vote = None
            self._set_speed(vt["v"])
            self.log(f"Flertal for {SPEED_NAMES[vt['v']]} tid ({len(vt['yes'])} af {vt['n']}).", None, "good")
        elif vt["n"] - len(vt["no"]) < need:
            self.vote = None
            self.log(f"Forslaget om {SPEED_NAMES[vt['v']]} tid blev stemt ned.", None, "warn")
        elif (now or time.time()) > vt["until"]:
            self.vote = None
            self.log(f"Forslaget om {SPEED_NAMES[vt['v']]} tid fik ikke flertal i tide.", None, "warn")

    def vote_view(self):
        vt = self.vote
        if not vt:
            return None
        return {"id": vt["id"], "by": vt["by"], "by_name": vt["by_name"], "v": vt["v"], "yes": len(vt["yes"]),
                "no": len(vt["no"]), "need": self._vote_need(), "n": vt["n"],
                "left": max(0, int(vt["until"] - time.time() + 0.99)), "voted": vt["yes"] + vt["no"]}

    # ── serialisering ────────────────────────────────────────────────────────
    def meta(self):
        players = []
        for p in self.players.values():
            q = dict(p)
            if p.get("ai"):                                   # computernaboernes driftsregnskab vises ikke
                for k in ("tacc", "fhist", "cacc", "aacc", "macc", "eacc"):
                    q.pop(k, None)
            elif p.get("tacc"):
                q["tacc"] = {k: round(v) for k, v in p["tacc"].items()}
            q["inv"] = {g: round(v, 2) for g, v in p["inv"].items()}
            q["money"] = round(p["money"], 2)
            players.append(q)
        return {"day": self.day, "weather": self.weather, "drought": self.drought, "speed": self.speed,
                "clock": round(getattr(self, "clock", 0.0), 1), "players": players, "nid": self.nid,
                "market": {g: {"p": round(v["p"], 3), "h": v["h"]} for g, v in self.market.items()},
                "projects": self.projects, "tractors": self.tractor_meta(), "opts": self.opts,
                "contracts": self.contracts, "deal_offers": self.deal_offers, "ms_req": self.ms_req,
                "rent_offers": self.rent_offers, "rentals": self.rentals, "torders": self.torders, "town": self.town, "phist": self.phist,
                "diesel": round(self.diesel, 3), "snow": round(self.snow, 2), "world": self.world,
                "plowed": [list(c) for c in self.plowed],
                "offers": self.offers, "news": self.news[-16:], "aarets": self.aarets, "mode": self.mode,
                "show": self.show, "vote": self.vote_view(), "pull": self.pull, "hmv": self.hm_ver,
                **({"hm": hm_pack(self.hm)} if self.hm and time.time() - self.hm_t < 3.0 else {})}

    def apply_meta(self, d):
        self.day, self.weather, self.drought, self.speed = d["day"], d["weather"], d["drought"], d["speed"]
        self.clock = d.get("clock", getattr(self, "clock", 0.0))
        if d.get("world"):
            self.world = d["world"]
        if "hm" in d and d.get("hmv", 0) != self.hm_ver:      # jorden er jævnet et sted (byggeri)
            self.hm, self.hm_ver, self._topo = hm_unpack(d["hm"]), d.get("hmv", 0), None
        pl = {tuple(c) for c in d.get("plowed", [])}
        if pl != self.plowed:                          # ryddede veje: jorden skal tegnes om
            self.plowed = pl
            self.ground_gen = getattr(self, "ground_gen", 0) + 1
        self.players = {p["id"]: p for p in d["players"]}
        self.market = d["market"]
        self.projects = d["projects"]
        for k_, v_ in PROJECTS.items():                   # nye fællesprojekter i ældre gemte spil
            self.projects.setdefault(k_, {"have": {r: 0 for r in v_["need"]}, "done": False, "by": {}})
        self.nid = d.get("nid", self.nid)
        self.tractor_view = d.get("tractors", [])
        self.opts = {**{k: True for k in WEATHER_OPTS}, **d.get("opts", {})}
        self.contracts = d.get("contracts", [])
        self.deal_offers = d.get("deal_offers", [])
        self.ms_req = d.get("ms_req", [])
        self.rent_offers = d.get("rent_offers", [])
        self.rentals = d.get("rentals", [])
        self.torders = d.get("torders") or ([d["torder"]] if d.get("torder") else [])
        self.town = d.get("town", self.town)
        self.phist = d.get("phist", self.phist)
        self.diesel = d.get("diesel", self.diesel)
        self.snow = d.get("snow", self.snow)
        self.offers = d.get("offers", self.offers)
        self.news = d.get("news", self.news)
        self.aarets = d.get("aarets", self.aarets)
        self.mode = {**MODE_DEFAULT, **(d.get("mode") or {})}
        self.show = d.get("show", self.show)
        self.vote = d.get("vote")
        self.pull = d.get("pull", self.pull)
        self.ctiles = {(x, y): c["id"] for c in self.contracts if c.get("pid") is not None
                       for x, y in c.get("cells", [])}

    def full(self):
        d = self.meta()
        d["tiles"] = [[t.pack() for t in row] for row in self.tiles]
        d["hm"] = hm_pack(self.hm)
        return d

    @classmethod
    def from_full(cls, d):
        set_world(d.get("world"))                  # kortets størrelse og byens placering først
        s = cls()
        for y, row in enumerate(d["tiles"]):
            for x, td in enumerate(row):
                s.tiles[y][x].unpack(td)
        s.hm = hm_unpack(d.get("hm"))                  # ældre gemte spil: fladt land
        if s.hm and (len(s.hm) != s.H + 1 or len(s.hm[0]) != s.W + 1):
            s.hm = None
        s.hm_ver = d.get("hmv", 0)
        s.apply_meta(d)
        s.vote = None                          # en åben afstemning overlever ikke en genindlæsning
        gt = s.tiles[GROVVARE[1]][GROVVARE[0]]
        if gt.b != "grovvare":                # grovvarehandlen findes ikke i ældre gemte spil
            gt.t, gt.b = "town", "grovvare"
        sv = s.tiles[SAVVAERK[1]][SAVVAERK[0]]
        if sv.b != "savvaerk":
            sv.t, sv.b = "town", "savvaerk"
        jb = s.tiles[JAGTBUTIK[1]][JAGTBUTIK[0]]
        if jb.b != "jagtbutik":                # jagtbutikken findes ikke i ældre gemte spil
            jb.t, jb.b, jb.ba = "town", "jagtbutik", None
        for k_, v_ in PROJECTS.items():        # byggepladser til nye fællesprojekter (ældre gemte spil)
            px_, py_ = v_["pos"]
            if s.inb(px_, py_):
                pt_ = s.tiles[py_][px_]
                want_ = ("proj:" if s.projects[k_]["done"] else "site:") + k_
                if pt_.b != want_:
                    pt_.t, pt_.b, pt_.ba = "town", want_, None
                    pt_.clear_crop()
        if s.world is not None and "pull_area" not in s.world:   # ældre gemte spil: anlæg traktortræk-pladsen
            area = s.find_pull_area()
            s.world["pull_area"] = area
            s.apply_pull_area(area)
        if s.world is not None and "buyers" not in s.world:      # ældre gemte spil: slagteri og mejeri
            b = s.find_buyer_spots()
            s.world["buyers"] = b
            s.apply_buyers(b)
        for g, v in GOODS.items():            # nye varer i ældre gemte spil
            s.market.setdefault(g, {"p": v["base"], "h": [v["base"]] * 30})
        for p in s.players.values():          # ældre gemte spil
            for g in GOODS:
                p["inv"].setdefault(g, 0.0)
            for w in WAGONS:                  # nye vogntyper (ballevognen)
                p.setdefault("wagons", {}).setdefault(w, 0)
            p.setdefault("yr", s.new_book(p["money"], p["loan"]))
            p.setdefault("inputs", {"goedning": 0, "sproejte": 0})
            p["inputs"].setdefault("kalk", 0)
            p.setdefault("sheep", 0)
            p.setdefault("horses", 0)
            p.setdefault("hist", [])
            p.setdefault("wh", [])
            if "old_yard" not in p:           # før tømmerpladsen og skovvognen: behold det, man havde
                had = p["inv"].get("tommer", 0) > 0 or p.get("pile", {}).get("tommer", 0) > 0 or \
                    any(j["tool"] == "fell" for j in p.get("jobs", []))
                p["old_yard"] = bool(had)
                if had and "skovvogn" not in p.setdefault("equip", []):
                    p["equip"].append("skovvogn")
        if not s.town.get("pop"):
            s.town["pop"] = s.town_pop()
        for p in s.players.values():                       # ældre gemte spil: hver fold får en låge
            s.ensure_gates(p)
            s._robots_fix(p)
        s.npcs, s.records = d.get("npcs", []), d.get("records", {})
        if d.get("news_all"):
            s.news = d["news_all"]
        if "trfull" in d:
            s.tractors = d["trfull"]
            for tr in s.tractors:
                if tr.get("haul"):
                    s._haul_abort(tr)
                tr.update(s="idle", tool=None, j=None, w=0.0, path=None)
            for p in s.players.values():          # båse i maskinhusene (ældre gemte spil får dem her)
                s._sync_park(p, True)
                for tr in s.tractors:
                    if tr["o"] == p["id"] and tr["s"] == "idle" and not tr.get("hire"):
                        tr["x"], tr["y"], tr["s"] = float(tr["hs"][0]), float(tr["hs"][1]), "parked"
        return s

    def apply_tiles(self, tiles):
        gen = self.__dict__.setdefault("chunk_gen", {})
        for x, y, td in tiles:
            t = self.tiles[y][x]
            wet_before = t.t in ("ditch", "water") or t.b == "broend"
            t.unpack(td)
            self._fold_mark(x, y)
            if wet_before or t.t in ("ditch", "water") or t.b == "broend":
                self.ground_gen = getattr(self, "ground_gen", 0) + 1     # grøfternes vand kan ændre sig langt væk
            for dx, dy in ((0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)):   # naboerne: veje, grøfter og skel
                k = ((x + dx) // CHUNK, (y + dy) // CHUNK)
                gen[k] = gen.get(k, 0) + 1
        if tiles:
            self.ver += 1


def save_game(state, path):
    d = state.meta()
    d["tiles"] = [[t.pack_save() for t in row] for row in state.tiles]
    d["hm"] = hm_pack(state.hm)
    d["trfull"] = state.tractors
    d["npcs"], d["records"], d["news_all"] = state.npcs, state.records, state.news[-40:]
    d["version"] = VERSION
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False)
    if os.path.exists(path):                          # det forrige gem beholdes som reserve (.bak)
        try:
            os.replace(path, path + ".bak")
        except OSError:
            pass
    os.replace(tmp, path)
    _rolling_backup(path)


def _rolling_backup(path):
    """Ekstra sikkerhedskopi i mappen backup/ hvert 20. minut (de 5 nyeste gemmes)."""
    try:
        name = os.path.splitext(os.path.basename(path))[0]
        os.makedirs(BACKUP_DIR, exist_ok=True)
        old = sorted(f for f in os.listdir(BACKUP_DIR) if f.startswith(name + "_") and f.endswith(".json"))
        if old and time.time() - os.path.getmtime(os.path.join(BACKUP_DIR, old[-1])) < BACKUP_EVERY:
            return
        import shutil
        shutil.copy2(path, os.path.join(BACKUP_DIR, f"{name}_{time.strftime('%Y%m%d_%H%M%S')}.json"))
        for f in old[:max(0, len(old) + 1 - BACKUP_KEEP)]:
            os.remove(os.path.join(BACKUP_DIR, f))
    except OSError:
        pass


def load_game(path):
    try:
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
    except (json.JSONDecodeError, UnicodeDecodeError):
        if os.path.exists(path + ".bak"):            # ødelagt gem (fx strømsvigt): brug det forrige
            print("Det gemte spil var ødelagt – indlæser det forrige gem (.bak).")
            return load_game(path + ".bak")
        raise
    if d.get("version") not in SAVE_COMPAT:
        raise ValueError("gemt med en anden version af spillet")
    s = GameState.from_full(d)
    for p in s.players.values():
        p["connected"] = False
    return s


SAVE_SLOTS = 5                    # gemmepladser pr. slags spil (singleplayer og vært)


def slot_path(single, n):
    """Filen til gemmeplads n (1 = den gamle fil, så tidligere gemte spil ligger i plads 1)."""
    base = SAVE_SINGLE if single else SAVE_MULTI
    return base if n <= 1 else base[:-5] + f"_{n}.json"


def slot_infos(single):
    """[(plads, beskrivelse eller None, ændret-tidspunkt)] for alle gemmepladser."""
    out = []
    for n in range(1, SAVE_SLOTS + 1):
        p = slot_path(single, n)
        info = save_info(p)
        try:
            mt = os.path.getmtime(p) if info else 0.0
        except OSError:
            mt = 0.0
        out.append((n, info, mt))
    return out


def saved_when(mt):
    if not mt:
        return ""
    lt, now = time.localtime(mt), time.localtime()
    if lt.tm_yday == now.tm_yday and lt.tm_year == now.tm_year:
        return time.strftime("i dag %H:%M", lt)
    return time.strftime("%d/%m %H:%M", lt)


def save_info(path):
    try:
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
        if d.get("version") not in SAVE_COMPAT:
            return None
        s = GameState()
        s.day = d["day"]
        names = ", ".join(p["name"] for p in d["players"])
        return f"{s.date_str()} – {names}"
    except (OSError, ValueError, KeyError):
        return None


# ═════════════════════════════════════════════════════════════════════════════
#  NETVÆRK — autoritativ server, JSON-linjer over TCP, UDP-broadcast til LAN-søgning
#  Singleplayer bruger samme server, men kun på 127.0.0.1 og uden broadcast.
# ═════════════════════════════════════════════════════════════════════════════
def encode(obj):
    return (json.dumps(obj, separators=(",", ":"), ensure_ascii=False) + "\n").encode("utf-8")


def all_ips():
    """Alle maskinens IPv4-adresser (LAN, VPN som Tailscale/ZeroTier/Hamachi) – til at give vennerne."""
    out = []
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            ip = info[4][0]
            if ip not in out and not ip.startswith("127."):
                out.append(ip)
    except OSError:
        pass
    lan = lan_ip()
    if lan not in out and not lan.startswith("127."):
        out.insert(0, lan)
    return out


def ip_kind(ip):
    """Hvad slags adresse: til forklaringen i værtsvinduet."""
    a = [int(x) for x in ip.split(".")[:2]]
    if a[0] == 100 and 64 <= a[1] <= 127:
        return "Tailscale / VPN – brug den, hvis I spiller over Tailscale"
    if a[0] == 25 or a[0] == 26:
        return "Hamachi – brug den, hvis I spiller over Hamachi"
    if a[0] == 10 or (a[0] == 172 and 16 <= a[1] <= 31) or (a[0] == 192 and a[1] == 168):
        return "lokalt netværk (LAN) – til venner på samme net" if ip == lan_ip() else "lokalt/virtuelt netværk"
    return "offentlig adresse"


def lan_ip():
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(("10.255.255.255", 1))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except OSError:
        return "127.0.0.1"


class Conn:
    _uid = 0

    def __init__(self, sock, addr):
        self.sock, self.addr = sock, addr
        self.pid = None
        Conn._uid += 1
        self.uid, self.name = Conn._uid, None
        self.lock = threading.Lock()
        self.alive = True

    def send(self, obj):
        if not self.alive:
            return
        data = obj if isinstance(obj, bytes) else encode(obj)
        try:
            with self.lock:
                self.sock.sendall(data)
        except OSError:
            self.alive = False

    def close(self):
        self.alive = False
        try:
            self.sock.close()
        except OSError:
            pass


class Server:
    def __init__(self, title, state=None, port=TCP_PORT, save_path=SAVE_MULTI, local=False, mode=None, world=None):
        self.state = state or GameState.new_world((world or {}).get("seed", random.randrange(1 << 30)), world)
        self.state.speed = START_SPEED                    # spillet starter altid i ½ tid
        if state is None:
            self.state.rng = random.Random()
            self.state.mode = {**MODE_DEFAULT, **(mode or {})}
            if local:
                self.state.mode["farm"] = "own"
        for p in self.state.players.values():
            p["connected"] = False
        self.title, self.port, self.save_path, self.local = title, port, save_path, local
        self.max_players = 1 if local else MAX_PLAYERS
        self.q = queue.Queue()
        self.conns = []
        self.running = False
        self.save_req = False
        self.save_on_stop = True
        self.threads = []

    def start(self):
        self.lsock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.lsock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.lsock.bind(("127.0.0.1" if self.local else "", 0 if self.local else self.port))
        self.port = self.lsock.getsockname()[1]
        self.lsock.listen(8)
        self.running = True
        fns = [self._accept, self._loop] + ([] if self.local else [self._beacon])
        for fn in fns:
            th = threading.Thread(target=fn, daemon=True)
            th.start()
            self.threads.append(th)

    def stop(self, save=True):
        self.save_on_stop = save
        self.running = False
        try:                                          # væk accept() (ellers holdes porten optaget, og man kan
            self.lsock.shutdown(socket.SHUT_RDWR)     # ikke være vært igen med det samme)
        except OSError:
            pass
        try:
            self.lsock.close()
        except OSError:
            pass
        if len(self.threads) > 0:
            self.threads[0].join(timeout=2)
        self.threads[1].join(timeout=3)
        for c in list(self.conns):
            c.close()

    def request_save(self):
        self.save_req = True

    def connected_count(self):
        if self.state.shared():
            return len([c for c in list(self.conns) if c.pid is not None])
        return sum(1 for p in list(self.state.players.values()) if p.get("connected"))

    def _members(self):
        for p in self.state.players.values():
            p["members"] = [c.name for c in self.conns if c.pid == p["id"]]

    def _accept(self):
        while self.running:
            try:
                s, a = self.lsock.accept()
            except OSError:
                break
            s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            c = Conn(s, a)
            threading.Thread(target=self._reader, args=(c,), daemon=True).start()

    def _reader(self, c):
        buf = b""
        try:
            while self.running and c.alive:
                data = c.sock.recv(65536)
                if not data:
                    break
                buf += data
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    if line.strip():
                        try:
                            self.q.put((c, json.loads(line.decode("utf-8"))))
                        except ValueError:
                            pass
        except OSError:
            pass
        self.q.put((c, {"a": "_gone"}))

    def _loop(self):
        while self.running:
            try:
                self._loop_body()
                return
            except Exception:
                import traceback
                log_error("simulation", traceback.format_exc())
                self.state.log("Der skete en fejl i simulationen – spillet fortsætter. Detaljerne står i "
                               "farmland_fejl.txt.", None, "err")
                time.sleep(0.2)

    def _loop_body(self):
        acc, last, last_bc, last_save = 0.0, time.time(), 0.0, time.time()
        st = self.state
        while self.running:
            now = time.time()
            dt, last = now - last, now
            while True:
                try:
                    c, msg = self.q.get_nowait()
                except queue.Empty:
                    break
                try:
                    self._handle(c, msg)
                except Exception as e:  # en fejl i én besked må ikke vælte serveren
                    print("Serverfejl:", repr(e))
            if st.speed > 0 and self.connected_count() > 0:
                st.clock = getattr(st, "clock", 0.0) + min(dt, 0.5)     # fælles ur (natten) – kun mens spillet kører
                days = min(dt / (DAY_SECONDS[st.speed] * st.pace()), 2.0)
                st.tick(days)
                acc += days
                while acc >= 1.0:
                    acc -= 1.0
                    st.advance_day()
            if st.vote:
                st.n_voters = max(1, len(self.conns))
                st._vote_check(now)
            if self.connected_count() > 0:
                st.tick_manual(min(dt, 0.1))
            if self.save_req or now - last_save > 300:
                self.save_req = False
                last_save = now
                self._save()
            self._flush_events()
            if now - last_bc >= 0.2:
                last_bc = now
                self._broadcast()
            elif now - getattr(self, "last_mv", 0.0) >= 0.05:
                self.last_mv = now
                self._broadcast_manual()
            time.sleep(0.02)
        if self.save_on_stop:
            self._save(quiet=True)

    def _save(self, quiet=False):
        try:
            save_game(self.state, self.save_path)
            if not quiet:
                m_ = re.search(r"_(\d+)\.json$", self.save_path or "")
                self.state.log(f"Spillet er gemt i plads {m_.group(1) if m_ else 1} ({self.state.date_str()}).",
                               None, "good")
        except OSError as e:
            self.state.log(f"Kunne ikke gemme: {e}", None, "err")

    def _handle(self, c, msg):
        a = msg.get("a")
        st = self.state
        if a == "hello":
            if msg.get("v") != VERSION or msg.get("gv") != GAME_VERSION:
                theirs = msg.get("gv") or "en ældre version"
                c.send({"k": "err", "t": f"Værten kører FarmLand {GAME_VERSION}, men du har {theirs}. "
                                         "Brug samme version på begge computere."})
                c.close()
                return
            name = (str(msg.get("name") or "Bonde").strip() or "Bonde")[:16]
            if st.shared() and not self.local:
                others = [o.name for o in self.conns if o.pid is not None]
                if len(others) >= MAX_PLAYERS:
                    c.send({"k": "err", "t": f"Gården er fuld ({MAX_PLAYERS} spillere)."})
                    c.close()
                    return
                if name in others:
                    name = name[:13] + " " + str(random.randint(2, 99))
                first = 0 not in st.players
                c.pid, c.name = 0, name
                st.add_player(0, name if first else st.players[0]["name"])
                self.conns.append(c)
                self._members()
                c.send({"k": "welcome", "you": 0, "drv": c.uid, "title": self.title, "single": False,
                        "state": st.full()})
                if not first:
                    st.log(f"{name} er kommet med på gården.", None, "big")
                return
            pid = next((p["id"] for p in st.players.values() if p["name"] == name and not p["connected"]
                        and not p.get("ai")), None)
            if pid is None:
                if any(p["name"] == name for p in st.players.values()):
                    name = name[:13] + " " + str(random.randint(2, 99))
                pid = next((f for f in HUMAN_IDS[:self.max_players] if f not in st.players), None)
            if pid is None:  # alle pladser har haft en ejer – overtag en offline gård
                pid = next((p["id"] for p in st.players.values() if not p["connected"] and not p.get("ai")),
                           None)
            if pid is None:
                c.send({"k": "err", "t": "Spillet er fuldt." if self.local else f"Spillet er fuldt ({self.max_players} gårde)."})
                c.close()
                return
            back = pid in st.players and st.players[pid]["name"] == name
            c.pid, c.name = pid, name
            st.add_player(pid, name)
            self.conns.append(c)
            self._members()
            c.send({"k": "welcome", "you": pid, "drv": c.uid, "title": self.title, "single": self.local,
                    "state": st.full()})
            if not self.local:
                st.log(f"{name} {'er tilbage på sin gård' if back else 'har overtaget en gård'}.", None, "big")
        elif a == "_gone":
            if c in self.conns:
                self.conns.remove(c)
            if c.pid is not None and c.pid in st.players:
                st.release_manual(c.pid, c.uid)
                self._members()
                if not any(o.pid == c.pid for o in self.conns):
                    st.players[c.pid]["connected"] = False
                if not self.local and c.name:
                    st.log(f"{c.name if st.shared() else st.pname(c.pid)} har forladt spillet.", None, "warn")
            c.close()
        elif a == "save" and c.pid is not None:          # en medspiller beder værten om at gemme
            self.request_save()
        elif c.pid is not None:
            msg["_drv"], msg["_nm"] = c.uid, c.name
            st.n_voters = max(1, len(self.conns))
            st.handle(c.pid, msg)

    def _flush_events(self):
        ev, self.state.events = self.state.events, []
        for pid, text, color in ev:
            msg = encode({"k": "log", "t": text, "c": color})
            for c in list(self.conns):
                if pid is None or c.pid == pid:
                    c.send(msg)

    def _broadcast(self):
        st = self.state
        tiles = [[x, y, st.tiles[y][x].pack()] for x, y in st.dirty]
        st.dirty.clear()
        msg = encode({"k": "delta", "tiles": tiles, "meta": st.meta()})
        for c in list(self.conns):
            c.send(msg)
            if not c.alive:
                self.q.put((c, {"a": "_gone"}))

    def _broadcast_manual(self):
        """Køretøjer i bevægelse sendes 20 gange i sekundet, så de kører glat på skærmen: selvkørte maskiner
        (til de andre spillere) og maskiner/lastbiler på vej et sted hen (fx vognmanden fra byen)."""
        many = len(self.conns) >= 2
        st_ = self.state
        mv = []
        for t in st_.tractors:
            if t["s"] == "manual" and many:
                mv.append([t["id"], round(t["x"], 3), round(t["y"], 3), t["d"], round(t["man"]["v"], 2)])
            elif t["s"] == "move" and t.get("path"):
                x_, y_, _w = st_.view_xy(t)                # samme visning som i de store beskeder (ingen hop)
                mv.append([t["id"], round(x_, 3), round(y_, 3), t["d"], 0.0])
        if not mv:
            return
        msg = encode({"k": "mv", "v": mv})
        for c in list(self.conns):
            c.send(msg)

    def _beacon(self):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_BROADCAST, 1)
        except OSError:
            return
        while self.running:
            data = json.dumps({"g": "farmland", "v": VERSION, "gv": GAME_VERSION, "title": self.title, "port": self.port,
                               "n": self.connected_count()}).encode("utf-8")
            for addr in ("<broadcast>", "255.255.255.255"):
                try:
                    s.sendto(data, (addr, DISC_PORT))
                except OSError:
                    pass
            time.sleep(1.0)
        s.close()


class Discovery:
    """Lytter efter spil på det lokale netværk."""

    def __init__(self):
        self.found = {}
        self.sock = None
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if hasattr(socket, "SO_REUSEPORT"):
                try:
                    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
                except OSError:
                    pass
            s.bind(("", DISC_PORT))
            s.setblocking(False)
            self.sock = s
        except OSError:
            self.sock = None

    def poll(self):
        if self.sock:
            while True:
                try:
                    data, (ip, _) = self.sock.recvfrom(2048)
                except (BlockingIOError, OSError):
                    break
                try:
                    d = json.loads(data.decode("utf-8"))
                    if d.get("g") == "farmland":
                        title = d["title"]
                        if d.get("v") != VERSION or d.get("gv") != GAME_VERSION:
                            title += f" (version {d.get('gv') or 'ældre'} – du har {GAME_VERSION})"
                        self.found[(ip, d["port"])] = (title, d["n"], time.time())
                except (ValueError, KeyError):
                    pass
        now = time.time()
        self.found = {k: v for k, v in self.found.items() if now - v[2] < 4}
        return self.found

    def close(self):
        if self.sock:
            self.sock.close()


class Client:
    def __init__(self, host, port, name):
        self.sock = socket.create_connection((host, port), timeout=5)
        self.sock.settimeout(None)
        self.sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        self.q = queue.Queue()
        self.alive = True
        self.lock = threading.Lock()
        self.send({"a": "hello", "name": name, "v": VERSION, "gv": GAME_VERSION})
        threading.Thread(target=self._reader, daemon=True).start()

    def send(self, msg):
        if not self.alive:
            return
        try:
            with self.lock:
                self.sock.sendall(encode(msg))
        except OSError:
            self.alive = False

    def _reader(self):
        buf = b""
        try:
            while self.alive:
                data = self.sock.recv(262144)
                if not data:
                    break
                buf += data
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    if line.strip():
                        self.q.put(json.loads(line.decode("utf-8")))
        except (OSError, ValueError):
            pass
        self.alive = False
        self.q.put({"k": "disconnected"})

    def drain(self):
        out = []
        while True:
            try:
                out.append(self.q.get_nowait())
            except queue.Empty:
                return out

    def close(self):
        self.alive = False
        try:
            self.sock.close()
        except OSError:
            pass


# ═════════════════════════════════════════════════════════════════════════════
#  GRAFIK — al grafik tegnes i kode (isometrisk pixel-stil)
# ═════════════════════════════════════════════════════════════════════════════
TW, TH = 64, 32
HALF_W, HALF_H = TW // 2, TH // 2
SPR_H = 112
MILL_HUB = 70                   # vindmøllens navhøjde i pixel over feltet
GY = SPR_H - TH

pygame = None  # importeres først når der skal tegnes (så --dedicated ikke kræver pygame)


def P(u, v, gy=GY):
    return (HALF_W + HALF_W * u - HALF_W * v, gy + HALF_H * u + HALF_H * v)


def in_diamond(px, py):
    return abs(px + 0.5 - HALF_W) / HALF_W + abs(py + 0.5 - HALF_H) / HALF_H <= 1.0


def lerpc(a, b, k):
    return tuple(int(a[i] + (b[i] - a[i]) * k) for i in range(3))


def fast_surf(surf):
    """Samme billede i skærmens pixelformat (tegnes langt hurtigere). Uden vindue: uændret."""
    if pygame.display.get_surface() is None or not surf.get_flags() & pygame.SRCALPHA:
        return surf
    try:
        return surf.convert_alpha()
    except pygame.error:
        return surf


def solid_surf(surf):
    """Jordstykker (uden træer) er helt dækkende eller helt gennemsigtige: som farvenøgle-billede (RLE) tegnes de
    ca. 5 gange hurtigere end med alfakanal."""
    if pygame.display.get_surface() is None:
        return surf
    try:
        key = (255, 0, 255)
        out = pygame.Surface(surf.get_size()).convert()
        out.fill(key)
        out.blit(surf, (0, 0))
        out.set_colorkey(key, pygame.RLEACCEL)
        return out
    except pygame.error:
        return surf


_DIM = {}


def dim_screen(surf, rgba):
    """Halvgennemsigtigt slør over hele skærmen bag et vindue (genbruges – ikke en ny flade hver frame)."""
    key = (surf.get_size(), tuple(rgba))
    o = _DIM.get(key)
    if o is None:
        if len(_DIM) > 12:
            _DIM.clear()
        o = pygame.Surface(surf.get_size())
        o.fill(rgba[:3])
        o.set_alpha(rgba[3])
        _DIM[key] = o
    surf.blit(o, (0, 0))


def shade(c, f):
    return tuple(int(clamp(v * f, 0, 255)) for v in c[:3])


def mid(a, b):
    return ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)


def up(p, d):
    return (p[0], p[1] - d)


DIAMOND = [(HALF_W, -1), (TW + 1, HALF_H), (HALF_W, TH + 1), (-1, HALF_H)]
VEH_PAD = 80                     # køretøjer tegnes på en bredere flade, så sprøjtebom m.m. kan stikke ud
IMPLEMENTS = ("plow", "sow", "spray", "fertilize", "water", "snow", "gylle", "gylle_s", "potato", "harrow")


# ── pixel-bygninger: klodser (voxels) ───────────────────────────────────────────────────────────────
# Samme gitter som pixel-køretøjerne: 16 klodser pr. felt og 2 px pr. klods i højden. i løber langs u (feltets
# bredde w), j langs v (dybden h). De synlige sider er +j (venstre side, "forsiden") og +i (højre side, "gavlen").
# Designene tegnes altid med bygningen længst langs i; er den drejet (w < h), byttes akserne bagefter.

def _vsh(c, f):
    return (max(0, min(255, int(c[0] * f))), max(0, min(255, int(c[1] * f))), max(0, min(255, int(c[2] * f))))


class VoxB:
    """En lille klodsbygger til bygninger. Alle mål i klodser (1 felt = 16, 1 klods i højden = 2 px)."""

    def __init__(self, I, J):
        self.I, self.J = I, J
        self.v = {}

    # grundelementer
    def put(self, i, j, k, c):
        if k >= 0:
            self.v[(i, j, k)] = (_vsh(c, 1.14), c, _vsh(c, 0.76))

    def put3(self, i, j, k, cols):
        if k >= 0:
            self.v[(i, j, k)] = cols

    def box(self, i0, i1, j0, j1, k0, k1, c, fn=None):
        """Kasse (kun skallen – det indre ses aldrig). fn(i, j, k) kan give hver klods sin egen farve."""
        for i in range(i0, i1):
            ei = i in (i0, i1 - 1)
            for j in range(j0, j1):
                ej = ei or j in (j0, j1 - 1)
                for k in range(k0, k1):
                    if ej or k in (k0, k1 - 1):
                        cc = fn(i, j, k) if fn else c
                        if cc:
                            self.put(i, j, k, cc)

    def paint(self, face, fixed, a0, a1, k0, k1, c):
        """Mal et felt på en væg: face 'j' = forsiden (j = fixed, løber langs i), 'i' = gavlen (i = fixed)."""
        for a in range(a0, a1):
            for k in range(k0, k1):
                if face == "j":
                    self.put(a, fixed, k, c)
                else:
                    self.put(fixed, a, k, c)

    def win(self, face, fixed, a0, a1, k0, k1, glass=(84, 124, 168), frame=(244, 242, 234)):
        self.paint(face, fixed, a0 - 1, a1 + 1, k0 - 1, k1 + 1, frame)
        self.paint(face, fixed, a0, a1, k0, k1, glass)

    def windows(self, face, fixed, a0, a1, k0, k1, every=4, width=2, glass=(84, 124, 168),
                frame=(244, 242, 234), skip=()):
        a = a0
        while a + width <= a1:
            if not any(s0 <= a < s1 or s0 < a + width <= s1 for s0, s1 in skip):
                self.win(face, fixed, a, a + width, k0, k1, glass, frame)
            a += every

    def roof(self, i0, i1, j0, j1, kb, rise, col, wall=None, kind="i", over=1, ridge=None, stripes=True):
        """Tag over rektanglet: kind 'i' = sadeltag med kip langs i, 'j' = kip langs j, 'hip' = valmtag,
        'flat' = fladt. Gavltrekanterne fyldes med væggens farve."""
        ii0, ii1, jj0, jj1 = i0 - over, i1 + over, j0 - over, j1 + over
        hw_j, hw_i = (jj1 - jj0) / 2, (ii1 - ii0) / 2
        dark = _vsh(col, 0.86)
        for i in range(ii0, ii1):
            for j in range(jj0, jj1):
                dj = min(j - jj0, jj1 - 1 - j) + 0.5
                di = min(i - ii0, ii1 - 1 - i) + 0.5
                if kind == "i":
                    t = dj / hw_j
                elif kind == "j":
                    t = di / hw_i
                elif kind == "hip":
                    t = min(dj / hw_j, di / max(hw_j, 1))
                else:
                    t = 0
                top = kb + int(round(min(1.0, t) * rise))
                inside = i0 <= i < i1 and j0 <= j < j1
                for k in range(kb, top + 1):
                    if k >= top - 1:
                        c = col if not stripes or k % 2 else dark
                        if ridge and k == top and t >= 0.9:
                            c = ridge
                        self.put(i, j, k, c)
                    elif inside and wall and (i in (i0, i1 - 1) or j in (j0, j1 - 1)):
                        self.put(i, j, k, wall)

    def cyl(self, ci, cj, r, k0, k1, c, fn=None):
        for i in range(int(ci - r - 1), int(ci + r + 2)):
            for j in range(int(cj - r - 1), int(cj + r + 2)):
                d = math.hypot(i + 0.5 - ci, j + 0.5 - cj)
                if d <= r:
                    edge = d > r - 1.5
                    for k in range(k0, k1):
                        if edge or k in (k0, k1 - 1):
                            self.put(i, j, k, fn(i, j, k) if fn else c)

    def cone(self, ci, cj, r, k0, k1, c):
        n = max(1, k1 - k0)
        for k in range(k0, k1):
            self.cyl(ci, cj, max(0.6, r * (1 - (k - k0) / n)), k, k + 1, c)

    def hcyl(self, axis, c0, c1, p, kc, r, c, end=None):
        """Liggende cylinder langs 'i' eller 'j' (tank, rundballe, stamme). kc = midtens højde (klodser)."""
        for a in range(c0, c1):
            for q in range(int(p - r - 1), int(p + r + 2)):
                for k in range(max(0, int(kc - r - 1)), int(kc + r + 2)):
                    if math.hypot(q + 0.5 - p, (k + 0.5 - kc) * 1.0) <= r:
                        cc = end if end and a in (c0, c1 - 1) else c
                        if axis == "i":
                            self.put(a, q, k, cc)
                        else:
                            self.put(q, a, k, cc)

    def blob(self, ci, cj, kc, r, c, c2=None):
        for i in range(int(ci - r - 1), int(ci + r + 2)):
            for j in range(int(cj - r - 1), int(cj + r + 2)):
                for k in range(max(0, int(kc - r - 1)), int(kc + r + 2)):
                    if math.hypot(i + 0.5 - ci, j + 0.5 - cj, (k + 0.5 - kc) * 1.2) <= r:
                        self.put(i, j, k, c2 if c2 and (i * 7 + j * 3 + k * 5) % 5 == 0 else c)

    def beam(self, p0, p1, c, r=0.5):
        n = int(max(abs(p1[t] - p0[t]) for t in range(3)) * 2) + 1
        rr = int(math.ceil(r - 0.5))
        for q in range(n + 1):
            f = q / n
            i, j, k = (p0[t] + (p1[t] - p0[t]) * f for t in range(3))
            for di in range(-rr, rr + 1):
                for dj in range(-rr, rr + 1):
                    for dk in range(-rr, rr + 1):
                        if di * di + dj * dj + dk * dk <= r * r:
                            self.put(int(i) + di, int(j) + dj, int(k) + dk, c)

    def tree(self, i, j, s=1.0):
        self.box(i, i + 2, j, j + 2, 0, int(4 * s), (96, 70, 44))
        self.blob(i + 1, j + 1, 6 * s, 3.4 * s, (70, 128, 60), (92, 150, 72))

    def ground(self, i0, i1, j0, j1, c, fn=None):
        for i in range(i0, i1):
            for j in range(j0, j1):
                self.put(i, j, 0, fn(i, j) if fn else c)

    def transpose(self):
        """Drej bygningen (byt i og j) – venstre og højre side bytter også farve."""
        self.v = {(j, i, k): (t, r, l) for (i, j, k), (t, l, r) in self.v.items()}
        self.I, self.J = self.J, self.I


def vox_sprite(b, w, h, sw=None, shh=None):
    """Tegn en VoxB som bygningssprite med samme mål og ankerpunkt som de klassiske (_bsurf/_surf)."""
    W = sw or HALF_W * (w + h)
    H = shh or (GY + HALF_H * (w + h) + 2)
    ox = HALF_W * (h - 1)
    v = b.v
    layer = pygame.Surface((W, H), pygame.SRCALPHA)
    fill = layer.fill
    for (i, j, k) in sorted(v, key=lambda t: (t[0] + t[1], t[2])):
        if (i + 1, j, k) in v and (i, j + 1, k) in v and (i, j, k + 1) in v:
            continue
        top, lf, rt = v[(i, j, k)]
        X = HALF_W + ox + 2 * (i - j)
        Y = GY + (i + j) - 2 * (k + 1)
        fill(top, (X - 1, Y, 2, 1))
        fill(top, (X - 2, Y + 1, 4, 1))
        fill(lf, (X - 2, Y + 2, 2, 2))
        fill(lf, (X - 1, Y + 4, 1, 1))
        fill(rt, (X, Y + 2, 2, 2))
        fill(rt, (X, Y + 4, 1, 1))
    # kontur
    m = pygame.mask.from_surface(layer, 127)
    big = pygame.mask.Mask(m.get_size())
    for off in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        big.draw(m, off)
    big.erase(m, (0, 0))
    layer.blit(big.to_surface(setcolor=(30, 26, 22), unsetcolor=(0, 0, 0, 0)), (0, 0))
    # slagskygge på jorden (inden for byggefeltet), så lyset kommer fra samme side som de klassiske
    out = pygame.Surface((W, H), pygame.SRCALPHA)
    cols = {}
    for (i, j, k) in v:
        if k > cols.get((i, j), -1):
            cols[(i, j)] = k
    shade_ = (0, 0, 0, 50)
    done = set()
    for (i, j), kk in cols.items():
        if kk < 2:
            continue
        for t in range(1, min(10, int((kk + 1) * 0.35)) + 1):
            q = (i, j - t)
            if q in done or q in cols or q[1] < 0:
                continue
            done.add(q)
            X = HALF_W + ox + 2 * (q[0] - q[1])
            Y = GY + (q[0] + q[1])
            out.fill(shade_, (X - 1, Y, 2, 1))
            out.fill(shade_, (X - 2, Y + 1, 4, 1))
    out.blit(layer, (0, 0))
    return out


