PB_DOOR, PB_FRAME, PB_GLASS = (116, 72, 42), (244, 242, 234), (84, 124, 168)


def _brick(base):
    d = _vsh(base, 0.88)
    return lambda i, j, k: d if ((k % 2 == 0) and (i + j) % 4 == 0) or ((k % 2 == 1) and (i + j) % 4 == 2) else base


def _ribs(base):
    d = _vsh(base, 0.9)
    return lambda i, j, k: d if (i + j) % 2 else base



def px_sprite(rows, pal, shadow=True):
    """Håndtegnet pixelfigur ud fra tekstlinjer (ét tegn = én pixel, '.' = gennemsigtig), med mørk kontur og
    en lille skygge under fødderne. Bruges til dyrene, der er for små til klodser."""
    w = max(len(r) for r in rows)
    h = len(rows)
    s = pygame.Surface((w + 2, h + 4), pygame.SRCALPHA)
    for y, r in enumerate(rows):
        for x, ch in enumerate(r):
            if ch != ".":
                s.set_at((x + 1, y + 1), pal[ch])
    m = pygame.mask.from_surface(s, 127)
    big = pygame.mask.Mask(m.get_size())
    for off in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        big.draw(m, off)
    big.erase(m, (0, 0))
    s.blit(big.to_surface(setcolor=(30, 26, 22), unsetcolor=(0, 0, 0, 0)), (0, 0))
    if shadow:
        out = pygame.Surface(s.get_size(), pygame.SRCALPHA)
        pygame.draw.ellipse(out, (0, 0, 0, 55), (2, h, w - 2, 4))
        out.blit(s, (0, 0))
        s = out
    return s


