        I, J = b.I, b.J
        ht = 7
        b.box(2, I - 2, 3, J - 4, 0, ht, wall)
        b.windows("j", J - 5, 4, I - 4, 3, 5, every=3, glass=(90, 120, 160), frame=wall)
        b.paint("i", I - 3, J // 2 - 2, J // 2 + 1, 0, 5, (110, 104, 96))
        b.roof(2, I - 2, 3, J - 4, ht, 5 if not big else 6, PB_DARK_ROOF, wall)
        if animals:
            for q in range(3 + 2 * big):
                pi = 5 + q * (I - 10) // (2 + 2 * big)
                b.box(pi, pi + 3, J - 3, J - 1, 0, 2, animals)

