    def bale_yard(self, b, w, h, halm, wrap, shape="rund"):
        """halm, wrap: antal synlige baller – de stables stak for stak i fast rækkefølge (se yard_slots)."""
        I, J = b.I, b.J
        b.ground(1, I - 1, 1, J - 1, None, lambda i, j: (176, 162, 128) if (i * 3 + j) % 5 else (160, 146, 110))
        cols, rows, _ = yard_grid(I // 16, J // 16)
        si, sj = (I - 4) / cols, (J - 4) / rows
        cols_ = {False: ((214, 184, 96), (236, 210, 128)), True: ((226, 228, 226), (200, 202, 200))}
        for (col, row, lay), wr in yard_slots(I // 16, J // 16, halm, wrap):
            ci = 2 + si * (col + 0.5)
            j0 = int(round(2 + sj * row + 0.5))
            c1, c2 = cols_[wr]
            j1 = j0 + max(3, int(sj) - 1)
            if wr or shape == "rund":
                b.hcyl("j", j0, j1, ci, 2.9 + lay * 5.4, 2.7, c1, c2)
            else:                                     # firkantede: bigballer og pakker med småballer
                k0 = int(round(0.2 + lay * 5.4))
                hh_ = 5 if shape == "stor" else 4
                b.box(int(round(ci - 2.3)), int(round(ci + 2.3)), j0, j1 - 1, k0, k0 + hh_, c1,
                      (lambda i, j, k: (176, 146, 70) if (j - j0) % 2 == 0 and k > k0 else c1) if shape == "lille"
                      else None)

    def hoop_hall(self, b, w, h, mode, lv=0):
        """Rundbuehal: buer af stål med dug over, set ind ad den åbne gavl (fronten). Buen spænder over den lange
        side, så gavlen – og porten – vender mod den side, man ser på skærmen."""
        I, J = b.I, b.J
        i0, i1, j0, j1 = 2, I - 2, 2, J - 2
        ci, R = (i0 + i1) / 2, (i1 - i0) / 2
        H = R * 0.9
        dug, rib, rim = (196, 204, 192), (150, 160, 150), (110, 116, 112)
        inner = (1 - 1.7 / R) ** 2
        b.ground(i0, i1, j0, j1, (176, 162, 128) if mode == "halm" else (158, 154, 144))
        for i in range(i0, i1):
            for k in range(0, int(H) + 1):
                e = ((i + 0.5 - ci) / R) ** 2 + ((k + 0.5) / H) ** 2
                if e > 1:
                    continue
                for j in range(j0, j1):
                    if e >= inner:                       # selve buen
                        c = rib if (j - j0) % 5 == 0 else dug
                        if j == j1 - 1:
                            c = rim
                        b.put(i, j, k, c)
                    elif j <= j0 + 1:                    # den lukkede bagerste gavl, set indefra
                        b.put(i, j, k, (214, 216, 208) if (i % 6) else (186, 190, 182))
        if mode == "halm":                               # hver række stables ens: nederste lag først
            rows = max(1, (j1 - j0 - 4) // 6)
            for (cc, kc) in hoop_slots(w, h)[:lv]:
                for r in range(rows):
                    ja = j1 - 2 - (r + 1) * 6
                    b.hcyl("j", ja, ja + 5, cc, kc, 2.7, (214, 184, 96), (236, 210, 128))
        elif mode == "foder":                            # ensilagestak under dug med dæk på + en fodervogn
            self._hoop_silage(b, i0, i1, j0, j1, ci, R, H, inner, lv)
        else:                                            # en traktor og en vogn står inde i hallen
            tc, tw = (70, 130, 60), (34, 34, 36)
            ta = int(ci) - 9
            b.box(ta, ta + 6, j1 - 13, j1 - 3, 2, 6, tc)
            b.box(ta + 1, ta + 5, j1 - 13, j1 - 8, 6, 11, (80, 120, 150))
            b.box(ta + 1, ta + 5, j1 - 13, j1 - 8, 11, 12, tc)
            for (jj, rr) in ((j1 - 11, 3.5), (j1 - 4, 2.2)):
                b.hcyl("i", ta - 1, ta, jj, rr, rr, tw, (60, 60, 62))
                b.hcyl("i", ta + 6, ta + 7, jj, rr, rr, tw, (60, 60, 62))
            wa = int(ci) + 3
            b.box(wa, wa + 8, j0 + 4, j1 - 6, 2, 3, (150, 40, 34))
            b.box(wa, wa + 8, j0 + 4, j0 + 5, 3, 6, (170, 50, 40))
            b.box(wa, wa + 1, j0 + 4, j1 - 6, 3, 6, (170, 50, 40))
            b.box(wa + 7, wa + 8, j0 + 4, j1 - 6, 3, 6, (170, 50, 40))
            for jj in (j1 - 10, j0 + 9):
                b.hcyl("i", wa - 1, wa + 9, jj, 1.8, 1.8, tw, (60, 60, 62))

    @staticmethod
    def _hoop_silage(b, i0, i1, j0, j1, ci, R, H, inner, lv):
        """Foderhallen: en ensilagestak dækket af sort plast med bildæk – højden følger, hvor fuld hallen er.
        Fronten er skåret lige af, så man ser den gulgrønne majs- og græsensilage."""
        if lv <= 0:                                      # tom: kun betonvæggene, der holder stakken
            for j in range(j0 + 2, j1 - 4):
                for k in range(0, 3):
                    b.put(i0 + 2, j, k, (170, 168, 160))
                    b.put(i1 - 3, j, k, (170, 168, 160))
            return
        top = H * (0.22 + 0.13 * min(4, lv))             # stakkens højde midt i hallen
        jf = j1 - 5                                      # den afskårne front
        for i in range(i0 + 2, i1 - 2):
            x_ = (i + 0.5 - ci) / R
            if x_ * x_ >= inner:
                continue
            room = H * math.sqrt(inner - x_ * x_) - 1.5   # under buen
            edge = min(1.0, (min(i - i0 - 2, i1 - 3 - i) + 1) / 4.0)   # skrå sider
            hk = int(min(room, top * edge))
            for j in range(j0 + 2, jf + 1):
                back = min(1.0, (j - j0 - 1) / 3.0)      # skrå bagkant
                kk = max(1, int(hk * back))
                for k in range(kk):
                    if j == jf:                          # snitfladen: gulgrøn ensilage med lag
                        c = (176, 166, 74) if (k // 2) % 2 else (150, 146, 62)
                    elif k == kk - 1:                    # den sorte plast foroven
                        c = (40, 42, 40) if (i + j) % 7 else (64, 66, 62)
                    else:
                        c = (120, 120, 56)
                    b.put(i, j, k, c)
                if j < jf - 1 and (i % 5 == 2) and (j % 5 == 1) and kk > 1:   # bildæk på plasten
                    b.put(i, j, kk, (26, 26, 26))
        wa = int(ci) - 4                                 # en rød fodervogn står foran stakken
        b.box(wa, wa + 8, j1 - 4, j1 - 1, 1, 5, (176, 46, 36))
        b.box(wa + 1, wa + 7, j1 - 4, j1 - 1, 5, 6, (120, 120, 56))

    def timber_yard(self, b, w, h, lv):
        I, J = b.I, b.J
        b.ground(1, I - 1, 1, J - 1, None, lambda i, j: (150, 130, 96) if (i + j * 3) % 5 else (136, 118, 86))
        for r in range(min(4, lv)):
            j = 5 + r * (J - 8) // 4
            for layer, n in ((0, 3), (1, 2), (2, 1)):
                for q in range(n):
                    b.hcyl("i", 3, I - 3, j + q * 3 + layer * 1.5, 1.6 + layer * 2.6, 1.5, (116, 80, 46), (214, 176, 120))

