    def tribune(self, b):
        r = random.Random(17)
        wood = (150, 110, 70)
        for k, (j0, j1) in enumerate(((10, 14), (7, 11), (4, 8))):
            b.box(1, 15, j0, j1, 0, 2 + 2 * k, wood, lambda i, j, kk: (118, 84, 52) if kk == 0 else wood)
            for i in range(2, 14, 2):
                if r.random() < 0.8:
                    c = r.choice(Art.SPECTATORS)
                    jj = (j0 + j1) // 2
                    b.put(i, jj, 2 + 2 * k, c)
                    b.put(i, jj, 3 + 2 * k, (236, 196, 160))
        for i in (1, 14):
            b.beam((i, 4, 0), (i, 4, 13), (90, 70, 50))
        b.box(0, 16, 3, 9, 13, 14, (200, 60, 50), lambda i, j, kk: (240, 236, 226) if j == 3 else (200, 60, 50))

