    # tilbygninger
    GAR_WALL, GAR_ROOF = (240, 236, 226), (168, 62, 46)

    def _gar_door(self, b, j, a0, a1, h=5):
        b.paint("j", j, a0 - 1, a1 + 1, 0, h + 1, (90, 86, 82))                  # karm
        for k in range(0, h):
            b.paint("j", j, a0, a1, k, k + 1, (96, 100, 108) if k % 2 == 0 else (80, 84, 92))
        for a in range(a0 + 1, a1 - 1, 2):
            b.put(a, j, h - 1, (170, 206, 230))                                   # vinduesbånd i porten

    def _gar_drive(self, b, i0, i1, j0, j1):
        b.ground(i0, i1, j0, j1, None, lambda i, j: (156, 152, 144) if (i - i0) % 4 == 0 or j == j0 + 1
                 else (188, 184, 174))

    def garage(self, b):
        w = self.GAR_WALL
        self._gar_drive(b, 4, 12, 13, 16)
        b.box(3, 13, 3, 13, 0, 8, w, lambda i, j, k: (128, 126, 122) if k == 0 else w)
        self._gar_door(b, 12, 5, 11, 6)
        b.put(4, 12, 6, (255, 220, 120))                                          # lampe
        b.win("i", 12, 6, 9, 3, 5)                                                # sidevindue
        b.roof(3, 13, 3, 13, 8, 4, self.GAR_ROOF, w, kind="j")

