        w = self.GAR_WALL
        self._gar_drive(b, 3, 29, 13, 16)
        b.box(2, 30, 3, 13, 0, 8, w, lambda i, j, k: (128, 126, 122) if k == 0 else w)
        self._gar_door(b, 12, 4, 14, 6)
        self._gar_door(b, 12, 18, 28, 6)
        b.put(16, 12, 6, (255, 220, 120))
        b.win("i", 29, 6, 9, 3, 5)
        b.roof(2, 30, 3, 13, 8, 4, self.GAR_ROOF, w, kind="i")

