        self.gravel = self._ground((160, 146, 118), [(138, 124, 100), (180, 168, 140), (122, 112, 94)], 0.3)
        self.asphalt = self._asphalt()
        self.fliser = self._fliser()
        self.pasture = self.pasture0 = self._ground((84, 160, 56), [(72, 146, 48), (100, 176, 66), (118, 186, 74)], 0.3,
                                    flowers=True)
        self.cow = [self._cow(False), self._cow(True)]
        self.sheep = [self._sheep(False), self._sheep(True)]
        self.horse = [self._horse(False), self._horse(True)]
        self.pig = [self._pig(False), self._pig(True)]
        self.hen = [self._hen(False), self._hen(True)]
        self.ditch = {(m, w): self._ditch(m, w) for m in range(16) for w in (0, 1)}
        self.ditch_snow = {(m, w): self._ditch(m, w, True) for m in range(16) for w in (0, 1)}
        self.town = self._town()
        self.water = self.water0 = [self._water() for _ in range(2)]
        self.stub = self.stub0 = self._stubble()
        self.hover = self._outline((255, 255, 240, 230))
        self.mark = self._outline((250, 214, 90, 200), 1)
        self.sel_ok = self._fill((255, 240, 150, 80))
        self.sel_bad = self._fill((255, 70, 60, 70))
        self.moist = [self._fill((*lerpc((226, 84, 56), (56, 118, 232), k / 9), 120)) for k in range(10)]
        self.soil = [self._fill((*lerpc((214, 70, 50), (80, 190, 70), k / 9), 150)) for k in range(10)]
        self.weedfill = [self._fill((236, 214, 60, 30 + int(18 * k))) for k in range(10)]
        self.weeds = [self._weeds(i) for i in range(3)]
        self.spr = {}
        for c in CROPS:
            for s in range(6):
                self.spr[(c, s)] = self._crop(c, s)
