        self.spr["gaard"] = self._farmhouse()
        self._bcache = {}
        for k, b in BUILDINGS.items():
            if b["size"] != (1, 1):
                self.spr[k] = self.building_sprite(k, *b["size"])
        self.spr["silo"] = self._silo()
        self.spr["broend"] = self._well()
        self.spr["vindmoelle"] = self._windmill()
        self.spr["dieseltank"] = self._diesel_tank()
        self.spr["gylletank"] = self._slurry_tank()
        self.spr["malkerobot"] = self._milk_robot()
        self.spr["fodersilo"] = self._feed_silo()
        self.spr["vaskeplads"] = self._wash_bay()
        self.spr["kirke"] = self._church()
        self.spr["kvaegtorv"] = self._market_yard()
        self.spr["tribune"] = self._tribune()
