    def trim(self, spr):
        """(beskåret sprite, dx, dy): kun den synlige del – gennemsigtige kanter koster tid at blitte."""
        tc = self.__dict__.setdefault("_trimc", {})
        c = tc.get(id(spr))
        if c is None or c[0] is not spr:
            br = spr.get_bounding_rect()
            c = tc[id(spr)] = (spr, spr.subsurface(br).copy() if br.w and br.h else spr, br.x, br.y)
        return c[1], c[2], c[3]

    def z(self, surf, z):
        """Skaleret udgave af en flade til zoom (skarpe pixels, caches). Billedet konverteres til skærmens
        pixelformat, så det tegnes (blittes) hurtigst muligt."""
        key = (id(surf), z)
        c = self._zcache.get(key)
        if c is None or c[0] is not surf:              # hold fast i kilden, så et genbrugt id ikke giver et forkert billede
            if len(self._zcache) > 8000:
                self._zcache.clear()
            if z == 1.0:
                out = surf
            else:
                w, h = surf.get_size()
                out = pygame.transform.scale(surf, (max(1, int(round(w * z))), max(1, int(round(h * z)))))
            c = self._zcache[key] = (surf, fast_surf(out))
        return c[1]

    def _mud(self, spr, level):
        """Mudder på maskinens nederste halvdel (niveau 1–2)."""
        out = spr.copy()
        br = spr.get_bounding_rect()
        rng = random.Random(br.w * 31 + br.h + level)
        cols = [(92, 70, 44), (110, 84, 52), (76, 58, 38)]
        n = int(br.w * br.h * (0.05 if level == 1 else 0.13))
        top = br.y + br.h * 0.45
        for _ in range(n):
            x = rng.randrange(br.x, br.right)
            y = rng.randrange(int(top), br.bottom)
            if spr.get_at((x, y))[3] > 200:
                out.set_at((x, y), rng.choice(cols))
                if level == 2 and x + 1 < br.right and spr.get_at((x + 1, y))[3] > 200:
                    out.set_at((x + 1, y), cols[0])
        return out

    def vehicle_sprite(self, model, o, d, imp=None, loaded=False, front=False, mud=0, twin=False, roll=0, plow=False):
        # frontlæsser: None = ingen, ellers højden 0–8 (True = hvilestilling). OBS: 0 == False i Python, så
        # værdien lægges i en tuple i cache-nøglen – ellers deler "sænket læsser" og "ingen læsser" billede.
        front = None if front is False or front is None else (2 if front is True else int(front))
        roll = roll % ROLL_FRAMES if self.pixel_veh else 0     # hjulenes drejning (kun pixel-køretøjer)
        plow = bool(plow)
        fk = ("fl", front, bool(twin), roll, plow)
        if mud:
            key = ("mud", model, o, d, imp, loaded if isinstance(loaded, tuple) else bool(loaded), fk, mud)
            spr = self.vehicle.get(key)
            if spr is None:
                spr = self._mud(self.vehicle_sprite(model, o, d, imp, loaded, front, 0, twin, roll, plow), mud)
                self.vehicle[key] = spr
            return spr
        """model er en nøgle i VEHICLES (farve og størrelse efter mærke), eller 'tractor'/'combine'/'car'."""
        key = (model, o, d, imp, loaded if isinstance(loaded, tuple) else bool(loaded), fk)
        spr = self.vehicle.get(key)
        if spr is None:
            self._roll = roll
            v = VEHICLES.get(model)
            if model.startswith("car:"):
                mk_, _, sty = model[4:].partition(":")
                spr = self._car(MAKERS[mk_]["body"], d, sty or "sedan")
                if self.pixel_veh:
                    spr = self._vox_outline(spr)
                self.vehicle[key] = spr
                return spr
            if v:
                mk = MAKERS[v["maker"]]
                col, trim, size, kind = mk["body"], mk["trim"], v["size"], v["kind"]
            else:
                col, trim, size, kind = PLAYER_COLORS[o], (236, 200, 60), 1, model
            style = v.get("style") if v else None
            if kind == "tractor":
                spr = self._tractor(col, d, imp, trim, size, loaded, style or "klassisk", front, twin, plow)
            elif kind == "truck":
                spr = self._truck(col, d, v["cargo"], trim, size, loaded, style or "front", plow)
            elif kind == "combine":
                spr = self._combine(col, d, trim, 3 if v and v.get("xl") else size)
            else:
                spr = self._car(col, d, style or "sedan", trim, front, twin, plow)
            if self.pixel_veh:
                spr = self._vox_outline(spr)
            self.vehicle[key] = spr
        return spr


    # ── jord ─────────────────────────────────────────────────────────────────
    def _surf(self, h=TH):
        return pygame.Surface((TW, h), pygame.SRCALPHA)

    def _ground(self, base, specks, dens, flowers=False):
        s = self._surf()
        pygame.draw.polygon(s, base, DIAMOND)
        for _ in range(int(TW * TH * dens)):
            x, y = self.r.randrange(TW), self.r.randrange(TH)
            if in_diamond(x, y):
                s.set_at((x, y), self.r.choice(specks))
        if flowers:
            for _ in range(6):
                x, y = self.r.randrange(TW), self.r.randrange(TH)
                if in_diamond(x, y):
                    s.set_at((x, y), self.r.choice([(244, 232, 120), (246, 246, 240), (230, 140, 170)]))
        return s

    def _field(self, base):
        s = self._ground(base, [shade(base, 0.86), shade(base, 1.12)], 0.2)
        for i in range(1, 8):
            v = i / 8
            pygame.draw.line(s, shade(base, 0.72), P(0.03, v, 0), P(0.97, v, 0))
            pygame.draw.line(s, shade(base, 1.1), up(P(0.05, v, 0), 1), up(P(0.95, v, 0), 1))
        return s

    def _stubble(self):
        """Høstet mark med stub."""
        base = (170, 142, 86)
        s = self._ground(base, [shade(base, 0.85), shade(base, 1.1)], 0.2)
        for i in range(1, 8):
            v = i / 8
            for k in range(9):
                u = 0.08 + k * 0.105 + (0.05 if i % 2 else 0)
                x, y = P(u, v, 0)
                if in_diamond(int(x), int(y)):
                    pygame.draw.line(s, (222, 196, 112), (x, y), (x, y - 2))
                    s.set_at((int(x) + 1, int(y)), (120, 96, 58))
        return s

    def _sheep(self, flip):
        s = pygame.Surface((14, 11), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 50), (2, 8, 10, 3))
        for lx in (4, 9):
            pygame.draw.line(s, (50, 44, 40), (lx, 6), (lx, 9))
        pygame.draw.ellipse(s, (240, 238, 228), (2, 2, 10, 6))
        pygame.draw.ellipse(s, (226, 222, 210), (3, 1, 7, 4))
        pygame.draw.rect(s, (44, 40, 38), (11, 3, 3, 3))
        return pygame.transform.flip(s, True, False) if flip else s

    def _pig(self, flip):
        s = pygame.Surface((14, 10), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 50), (2, 7, 10, 3))
        for lx in (4, 9):
            pygame.draw.line(s, (196, 120, 120), (lx, 6), (lx, 8))
        pygame.draw.ellipse(s, (240, 172, 172), (2, 2, 10, 6))
