    def _cow(self, flip):
        s = pygame.Surface((18, 14), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 50), (2, 10, 14, 4))
        for lx in (5, 7, 11, 13):
            pygame.draw.line(s, (60, 50, 44), (lx, 8), (lx, 11))
        pygame.draw.ellipse(s, (244, 242, 236), (3, 3, 13, 7))
        pygame.draw.ellipse(s, (40, 36, 34), (6, 4, 4, 3))
        pygame.draw.ellipse(s, (40, 36, 34), (11, 6, 3, 2))
