    def _fliser(self):
        """Flisebelagt plads: lyse betonfliser i et gitter med fuger."""
        base = (178, 178, 172)
        s = self._ground(base, [(168, 168, 162), (188, 188, 182)], 0.15)
        for i in range(1, 4):
            pygame.draw.line(s, (136, 136, 132), P(0, i / 4, 0), P(1, i / 4, 0))
            pygame.draw.line(s, (136, 136, 132), P(i / 4, 0, 0), P(i / 4, 1, 0))
        return s

    # ── traktortræk-pladsen: jordbane med hjulspor og grusparkering med hvide båse ──
    def pull_ground(self, kind, x, y):
        axis = (PULL_AREA or {}).get("axis", "x")
        start = PULL_AREA is not None and kind == "bane" and (x, y) == tuple(PULL_POS)
        key = (kind, axis, start, self.pixel_road, self.look_key if self.look_key == "snow" else 0)
        cache = self.__dict__.setdefault("_pullg", {})
        s = cache.get(key)
        if s is None:
            s = (self._pix_pull if self.pixel_road else self._pull_tile)(kind, axis, start)
            if self.look_key == "snow":
                s = s.copy()
                s.blit(self.snow_road(), (0, 0))
            cache[key] = s
        return s

    def _pull_tile(self, kind, axis, start):
        along = (lambda a, b: P(a, b, 0)) if axis == "x" else (lambda a, b: P(b, a, 0))
        if kind == "bane":
            s = self._ground((150, 112, 70), [(130, 96, 60), (168, 128, 82), (120, 88, 56)], 0.3)
            for b in (0.3, 0.38, 0.62, 0.7):                       # hjulspor langs banen
                pygame.draw.line(s, (112, 82, 52), along(0.0, b), along(1.0, b), 2)
            if start:                                              # startstregen
                pygame.draw.line(s, (244, 242, 236), along(0.12, 0.05), along(0.12, 0.95), 3)
            return s
        s = self._ground((176, 162, 132), [(156, 144, 116), (192, 180, 150), (140, 128, 104)], 0.3)
        for a in (0.0, 0.5):                                       # to parkeringsbåse pr. felt
            pygame.draw.line(s, (240, 238, 228), along(a + 0.02, 0.15), along(a + 0.02, 0.85), 1)
        return s

    def _pix_pull(self, kind, axis, start):
        def col(i, j):
            a, b = (i, j) if axis == "x" else (j, i)
            n = self._noise(i, j, 31)
            if kind == "bane":
                if start and a in (1, 2):
                    return (240, 238, 228)
                if b in (5, 6, 10, 11):
                    return shade((128, 94, 60), 0.95 + n * 0.08)
                return shade((152, 114, 72), 0.92 + n * 0.16)
            if a in (0, 8) and 2 <= b <= 13:
                return (236, 234, 222)
            return shade((176, 162, 132), 0.9 + n * 0.18)
        return self._pix_ground(col)

    # ── græsplæne: nyslået med striber, halvlang, og groet til med totter og mælkebøtter ──
    LAWN_BASE = ((96, 174, 66), (80, 150, 54), (72, 134, 48))

    def lawn(self, stage):
        if self.look_key == "snow":
            return self.grass[0]
        key = (stage, self.pixel_road, self.look_key, getattr(self, "pixel_tree", False))
        cache = self.__dict__.setdefault("_lawnc", {})
        s = cache.get(key)
        if s is None:
            s = self._pix_lawn(stage) if self.pixel_road else self._lawn(stage)
            tint = self.GROUND_TINT.get(self.look_key) if isinstance(self.look_key, int) else None
            if tint:
                s = self._tint(s, *tint)
            cache[key] = s
        return s

    def _lawn(self, stage):
        base = self.LAWN_BASE[stage]
        r = random.Random(40 + stage)
        s = self._surf()
        pygame.draw.polygon(s, base, DIAMOND)
        if stage == 0:                                  # slåningsstriber på langs
            k = 0.12
            for i in range(4):
                c = shade(base, 1 + k) if i % 2 else shade(base, 1 - k * 0.6)
                pygame.draw.polygon(s, c, [P(0, i / 4, 0), P(1, i / 4, 0), P(1, (i + 1) / 4, 0), P(0, (i + 1) / 4, 0)])
        for _ in range((60, 140, 90)[stage]):
            x, y = r.randrange(TW), r.randrange(TH)
            if in_diamond(x, y):
                s.set_at((x, y), shade(base, r.choice((0.86, 0.92, 1.1, 1.16))))
        if stage >= 1:                                  # græsset rejser sig: små totter
            for _ in range((0, 26, 70)[stage]):
                x, y = r.randrange(3, TW - 3), r.randrange(4, TH - 2)
                if in_diamond(x, y) and in_diamond(x, y - 3):
                    h = r.choice((1, 2, 2, 3)) + stage - 1
                    pygame.draw.line(s, shade(base, 0.72), (x, y), (x, y - h + 1))
                    s.set_at((x, y - h), shade(base, 1.25))
        if stage == 2:                                  # mælkebøtter og kløver
            for _ in range(9):
                x, y = r.randrange(TW), r.randrange(TH)
                if in_diamond(x, y) and in_diamond(x + 1, y):
                    c = r.choice(((250, 220, 50), (250, 220, 50), (246, 246, 238)))
                    s.set_at((x, y), c)
                    s.set_at((x + 1, y), shade(c, 0.85))
        return s

    def _pix_lawn(self, stage):
        base = self.LAWN_BASE[stage]

        def col(i, j):
            n = self._noise(i, j, 21 + stage)
            if stage == 0:
                return shade(base, (1.1 if (i // 4) % 2 else 0.93) + (n - 0.5) * 0.04)
            r = rnd[i * 16 + j]
            if stage == 1:
                return shade(base, 0.88 + r * 0.26)
            if r > 0.975:
                return (250, 220, 50)                   # mælkebøtte
            if r < 0.008:
                return (244, 244, 236)
            return shade(base, 0.78 + r * 0.42)
        rg = random.Random(77)
        rnd = [rg.random() for _ in range(256)]
        return self._pix_ground(col)

    def _pix_fliser(self):
        c = self.__dict__.get("_pfliser")
        if c is None:
            def col(i, j):
                if i % 4 == 0 or j % 4 == 0:
                    return (138, 138, 134)                     # fuger
                n = self._noise(i // 4, j // 4, 13)
                return shade((180, 180, 174), 0.95 + n * 0.08)
            c = self._pfliser = self._pix_ground(col)
        return c

    def _pix_brosten(self):
        """Brosten: runde, toppede sten i grå og brune nuancer med mørke fuger."""
        c = self.__dict__.get("_pbrosten")
        if c is None:
            def col(i, j):
                row = j // 3
                ii = i + (2 if row % 2 else 0)
                if j % 3 == 2 or ii % 4 == 3:
                    return (92, 86, 78)                        # fuger
                n = self._noise(ii // 4, row, 21)
                base = (150, 140, 124) if n > 0.5 else (128, 124, 118) if n > 0.2 else (164, 150, 128)
                return shade(base, 1.08 if j % 3 == 0 else 0.96)
            c = self._pbrosten = self._pix_ground(col)
        return c

    def _asphalt(self):
        base = (78, 78, 84)
        s = self._ground(base, [(70, 70, 76), (92, 92, 98), (64, 64, 70)], 0.3)
        pygame.draw.lines(s, (110, 110, 114), True, [(HALF_W, 1), (TW - 2, HALF_H), (HALF_W, TH - 2), (2, HALF_H)], 1)
        return s

    # ── pixel-veje og -pladser: jorden som et gitter af 16×16 små klodstoppe (samme gitter som bygningerne) ──
    pixel_road = False

    @staticmethod
    def _pix_ground(colfn):
        s = pygame.Surface((TW, TH), pygame.SRCALPHA)
        for i in range(16):
            for j in range(16):
                c = colfn(i, j)
                X, Y = HALF_W + 2 * (i - j), i + j
                s.fill(c, (X - 1, Y, 2, 1))
                s.fill(c, (X - 2, Y + 1, 4, 1))
        return s

    @staticmethod
    def _noise(i, j, seed=0):
        return ((i * 73856093) ^ (j * 19349663) ^ (seed * 83492791)) % 97 / 97

    def _pix_road(self, mask):
        c = self.__dict__.setdefault("_proad", {}).get(mask)
        if c is None:
            base = (76, 76, 82)
            shades = ((70, 70, 76), (80, 80, 86), (76, 76, 82), (86, 86, 92))
            kerb, gutter, paint = (156, 156, 150), (58, 58, 62), (236, 236, 226)
            conn = [bool(mask & (1 << d)) for d in range(4)]          # +x, +y, -x, -y
            arms = [d for d in range(4) if conn[d]]
            if not arms:
                arms = [0, 2]
            elif len(arms) == 1:
                arms = arms                                         # vejen ender: striben går til midten

            def col(i, j):
                # kantsten mod de sider, hvor vejen ikke fortsætter
                for d, (edge, inner) in enumerate((((i == 15), (i == 14)), ((j == 15), (j == 14)),
                                                   ((i == 0), (i == 1)), ((j == 0), (j == 1)))):
                    if not conn[d]:
                        if edge:
                            return kerb
                        if inner:
                            return gutter
                for d in arms:                                      # stiplet midterstribe
                    if d in (0, 2) and j == 7 and ((d == 0 and i >= 7) or (d == 2 and i <= 8)) and (i // 2) % 2 == 0:
                        return paint
                    if d in (1, 3) and i == 7 and ((d == 1 and j >= 7) or (d == 3 and j <= 8)) and (j // 2) % 2 == 0:
                        return paint
                n = self._noise(i, j, mask)
                return shades[int(n * 4)] if n < 0.9 else (64, 64, 70)
            c = self._proad[mask] = self._pix_ground(col)
        return c

    def _pix_gravel(self):
        c = self.__dict__.get("_pgravel")
        if c is None:
            cols = ((160, 146, 118), (150, 136, 110), (170, 158, 130), (160, 146, 118), (138, 124, 100), (184, 172, 146))
            c = self._pgravel = self._pix_ground(lambda i, j: cols[int(self._noise(i, j, 5) * len(cols))])
        return c

    def _pix_town(self):
        c = self.__dict__.get("_ptown")
        if c is None:
            base = (182, 172, 152)

            def col(i, j):
                if i % 4 == 0 or j % 4 == 0:
                    return (150, 142, 124)                          # fuger mellem fliserne
                n = self._noise(i // 4, j // 4, 9)
                return shade(base, 0.94 + n * 0.1)
            c = self._ptown = self._pix_ground(col)
        return c

    def asphalt_striped(self, mask):
        """Asfalt med hvid stiplet midterstribe hen mod de naboer, vejen fortsætter til."""
        if self.pixel_road:
            return self._pix_road(mask)
        c = self._road_cache.get(mask) if hasattr(self, "_road_cache") else None
        if c is None:
            if not hasattr(self, "_road_cache"):
                self._road_cache = {}
            c = self.asphalt.copy()
            ends = [self.EDGE_MID[d] for d in range(4) if mask & (1 << d)]
            if len(ends) == 1:                            # vejen ender her: striben går hen til midten
                pass
            elif not ends:
                ends = [self.EDGE_MID[0], self.EDGE_MID[2]]
            cx, cy = HALF_W, HALF_H
            for ex, ey in ends:
                for f0, f1 in ((0.12, 0.38), (0.62, 0.88)):   # to streger pr. halvdel = stiplet
                    a = (cx + (ex - cx) * f0, cy + (ey - cy) * f0)
                    b = (cx + (ex - cx) * f1, cy + (ey - cy) * f1)
                    pygame.draw.line(c, (236, 236, 228), a, b, 1)
            self._road_cache[mask] = c
        return c

    # kanten mod nabo i retning +x, +y, -x, -y (midtpunkt af diamantens kant)
    EDGE_MID = {0: (48, 24), 1: (16, 24), 2: (16, 8), 3: (48, 8)}

    def _ditch(self, mask, wet, snow=False):
        """Grøften selv – uden græs under (græsset tegnes efter årstiden under den). Med sne: hvide kanter og is."""
        s = self._surf()
        edge, bank = ((236, 240, 246), (204, 212, 224)) if snow else ((156, 124, 82), (96, 70, 44))
        if snow:
            water = (176, 206, 232) if wet else (214, 220, 230)
            hi = (226, 240, 252) if wet else (236, 240, 246)
        else:
            water = (58, 118, 196) if wet else (74, 54, 34)
            hi = (150, 196, 240) if wet else (92, 70, 46)
        c = (HALF_W, HALF_H)
        ends = [self.EDGE_MID[d] for d in range(4) if mask & (1 << d)]
        if not ends:
            ends = [self.EDGE_MID[0], self.EDGE_MID[2]]   # enkeltstående grøft ligger langs x-aksen
        for w, col in ((13, edge), (9, bank), (5, water)):
            for e in ends:
                pygame.draw.line(s, col, c, e, w)
            pygame.draw.circle(s, col, c, w // 2)
        for e in ends:
            for f in (0.3, 0.7):
                m = (int(c[0] + (e[0] - c[0]) * f), int(c[1] + (e[1] - c[1]) * f))
                s.set_at(m, hi)
        return s

    def _town(self):
        base = (178, 168, 148)
        s = self._ground(base, [shade(base, 0.9), shade(base, 1.08)], 0.2)
        for i in range(1, 4):
            pygame.draw.line(s, shade(base, 0.84), P(0, i / 4, 0), P(1, i / 4, 0))
            pygame.draw.line(s, shade(base, 0.84), P(i / 4, 0, 0), P(i / 4, 1, 0))
        return s

    def _water(self):
        s = self._surf()
        pygame.draw.polygon(s, (56, 108, 178), DIAMOND)
        for _ in range(12):
            x, y = self.r.randrange(TW), self.r.randrange(TH)
            if in_diamond(x, y) and in_diamond(x + 4, y):
                pygame.draw.line(s, (128, 178, 228), (x, y), (x + 4, y))
        return s

    def _outline(self, col, w=2):
        s = self._surf()
        pts = [(HALF_W, 0), (TW - 1, HALF_H), (HALF_W, TH - 1), (0, HALF_H)]
        pygame.draw.lines(s, col, True, pts, w)
        return s

    def _fill(self, col):
        s = self._surf()
        pygame.draw.polygon(s, col, DIAMOND)
        return s

    # ── afgrøder ─────────────────────────────────────────────────────────────
    def _crop(self, crop, stage, dead=False):
        s = self._surf(SPR_H)
        orchard = bool(crop and CROPS[crop].get("orchard"))
        n = 3 if crop == "majs" else 2 if orchard else 4
        pts = []
        for i in range(n):
            for j in range(n):
                u = (i + 0.5) / n + self.r.uniform(-0.04, 0.04)
                v = (j + 0.5) / n + self.r.uniform(-0.04, 0.04)
                pts.append(P(u, v))
        pts.sort(key=lambda p: p[1])
        k = stage / 5
        for (x, y) in pts:
            x, y = int(x), int(y)
            if dead:
                col = (128, 100, 64)
                pygame.draw.line(s, col, (x - 1, y), (x - 3, y - 4))
                pygame.draw.line(s, shade(col, 0.8), (x + 1, y), (x + 2, y - 3))
                continue
            if stage == 0 and not orchard:
                s.set_at((x, y - 1), (98, 172, 72))
                s.set_at((x + 1, y - 1), (80, 150, 60))
                s.set_at((x, y - 2), (124, 194, 84))
                continue
            getattr(self, "_p_" + crop)(s, x, y, stage, k)
        return s

    def _p_hvede(self, s, x, y, st, k):
        h = 3 + int(10 * k)
        ripe = max(0.0, (st - 3) / 2)
        col = lerpc((88, 160, 58), (220, 186, 88), ripe)
        for dx in (-2, 0, 2):
            top = y - h + abs(dx) // 2
            sx = x + dx + (1 if dx > 0 else -1 if dx < 0 else 0)
            pygame.draw.line(s, col, (x + dx, y), (sx, top))
            if st >= 4:
                pygame.draw.line(s, lerpc((176, 204, 96), (242, 212, 124), ripe), (sx, top), (sx, top + 2))

    def _p_vinterhvede(self, s, x, y, st, k):
        self._p_hvede(s, x, y, st, k)
        if st >= 4:                                   # lidt tættere bestand end vårhvede
            pygame.draw.line(s, lerpc((88, 160, 58), (212, 176, 80), (st - 3) / 2), (x + 1, y), (x + 1, y - 3 - int(9 * k)))

    def _p_byg(self, s, x, y, st, k, pale=False):
        """Byg: lavere strå med nikkende aks og lange stak."""
        h = 3 + int(8 * k)
        ripe = max(0.0, (st - 3) / 2)
        col = lerpc((96, 166, 64), (226, 204, 120) if pale else (214, 190, 104), ripe)
        for dx in (-2, 1):
            top = y - h + abs(dx) // 2
            pygame.draw.line(s, col, (x + dx, y), (x + dx, top))
            if st >= 4:
                ear = lerpc((170, 200, 100), (236, 214, 140), ripe)
                pygame.draw.line(s, ear, (x + dx, top), (x + dx + 2, top + 2))
                s.set_at((x + dx + 3, top + 1), ear)

    def _p_vaarbyg(self, s, x, y, st, k):
        self._p_byg(s, x, y, st, k, pale=True)

    def _p_vinterbyg(self, s, x, y, st, k):
        self._p_byg(s, x, y, st, k)

    def _p_efterafgr(self, s, x, y, st, k):
        """Olieræddike: lave brede blade og hvide/lilla blomster."""
        r = 1 + int(3 * k)
        pygame.draw.circle(s, (70, 146, 58), (x, y - r), r)
        pygame.draw.circle(s, (96, 170, 70), (x - 1, y - r - 1), max(1, r - 1))
        if st >= 4:
            s.set_at((x, y - 2 * r - 1), (246, 244, 250))
            s.set_at((x + 1, y - 2 * r), (214, 190, 232))

    def _p_fruit(self, s, x, y, st, fruit):
        """Frugttræ: blomstrer om foråret (stadie 1), grønt om sommeren og fuldt af frugt, når det er modent."""
        pygame.draw.rect(s, (104, 72, 44), (x - 1, y - 8, 3, 9))
        r = 7
        pygame.draw.circle(s, (48, 110, 46), (x + 1, y - 12), r)
        pygame.draw.circle(s, (70, 140, 58), (x - 1, y - 14), r - 2)
        rng = random.Random(x * 17 + y)
        if st == 1:
            for _ in range(7):
                s.set_at((x + rng.randint(-5, 5), y - 12 + rng.randint(-5, 4)), (250, 238, 244))
        elif st >= 4:
            n = 4 if st == 4 else 9
            for _ in range(n):
                cx, cy = x + rng.randint(-5, 5), y - 12 + rng.randint(-5, 4)
                pygame.draw.circle(s, fruit if st == 5 else lerpc(fruit, (110, 170, 70), 0.5), (cx, cy), 1)

    def _p_aeble(self, s, x, y, st, k):
        self._p_fruit(s, x, y, st, (214, 44, 40))

    def _p_paere(self, s, x, y, st, k):
        self._p_fruit(s, x, y, st, (214, 206, 70))

    def _p_majs(self, s, x, y, st, k):
        h = 4 + int(20 * k)
        stalk = (66, 140, 48) if st < 5 else (170, 158, 74)
        leaf = (86, 162, 62) if st < 5 else (190, 172, 90)
        pygame.draw.line(s, stalk, (x, y), (x, y - h), 2)
        for f, side in ((0.35, -1), (0.55, 1), (0.75, -1)):
            yy = y - int(h * f)
            pygame.draw.line(s, leaf, (x, yy), (x + side * 5, yy - 3))
            pygame.draw.line(s, leaf, (x + side * 5, yy - 3), (x + side * 7, yy - 1))
        if st >= 4:
            pygame.draw.rect(s, (238, 208, 78) if st == 5 else (150, 192, 92), (x + 1, y - int(h * 0.55), 2, 4))
            s.set_at((x, y - h - 1), (226, 204, 128))

    def _p_kartofler(self, s, x, y, st, k):
        r = 2 + int(4 * k)
        col = (58, 124, 48) if st < 5 else (152, 148, 70)
        hi = (90, 156, 62) if st < 5 else (182, 172, 92)
        pygame.draw.ellipse(s, shade(col, 0.75), (x - r, y - r, 2 * r, r + 2))
        pygame.draw.ellipse(s, col, (x - r, y - r - 1, 2 * r, r + 1))
        pygame.draw.ellipse(s, hi, (x - r + 1, y - r - 1, r, max(2, r // 2 + 1)))
        if st == 4:
            s.set_at((x - 1, y - r - 1), (246, 246, 246))
            s.set_at((x + 2, y - r), (190, 150, 220))

    def _p_raps(self, s, x, y, st, k):
        h = 3 + int(12 * k)
        col = (80, 152, 60) if st < 5 else (150, 140, 70)
        for dx in (-1, 2):
            pygame.draw.line(s, col, (x + dx, y), (x + dx, y - h))
        if st in (3, 4):
            for ox, oy in ((-2, 0), (-1, -1), (0, 0), (1, -1), (2, 0), (3, -1), (0, -2), (2, -2), (1, 1)):
                s.set_at((x + ox, y - h + oy), (252, 224, 46) if (ox + oy) % 2 else (255, 242, 96))
        elif st == 5:
            for ox in (-1, 0, 1, 2):
                s.set_at((x + ox, y - h), (178, 152, 82))

    def _weeds(self, level):
        s = self._surf()
        rng = random.Random(level * 11 + 5)
        for _ in range(6 + level * 8):
            x, y = rng.randrange(TW), rng.randrange(TH)
            if in_diamond(x, y):
                s.set_at((x, y), rng.choice([(240, 214, 60), (246, 246, 236), (170, 196, 70)]))
                if level >= 1:
                    s.set_at((x, max(0, y - 1)), (110, 150, 60))
        return s

    def _p_graes(self, s, x, y, st, k):
        h = 2 + int(6 * k)
        for dx in (-3, -1, 1, 3):
            pygame.draw.line(s, (84, 162, 62), (x + dx, y), (x + dx + (1 if dx > 0 else -1), y - h))
        pygame.draw.line(s, (110, 184, 76), (x, y), (x, y - h - 1))
        if st >= 4:
            s.set_at((x - 2, y - h), (240, 240, 250))
            s.set_at((x + 2, y - h + 1), (220, 130, 170))

    def _p_jordbaer(self, s, x, y, st, k):
        r = 1 + int(3 * k)
        pygame.draw.ellipse(s, (34, 104, 50), (x - r - 1, y - r, 2 * r + 2, r + 2))
        pygame.draw.ellipse(s, (54, 138, 64), (x - r, y - r - 1, 2 * r, r + 1))
        if st == 4:
            s.set_at((x, y - r - 1), (248, 248, 240))
        if st == 5:
            for ox, oy in ((-2, 0), (1, -1), (2, 1)):
                s.set_at((x + ox, y - r + oy + 1), (226, 38, 52))
                s.set_at((x + ox + 1, y - r + oy + 1), (250, 84, 80))

    # ── træer ────────────────────────────────────────────────────────────────
    # løvfarver pr. årstid: (mørk, mellem, lys) – None = bladløst
    LEAVES = {0: ((38, 96, 42), (58, 128, 52), (96, 170, 74)), 1: ((34, 86, 38), (46, 108, 44), (70, 138, 58)),
              2: None, 3: None}
    AUTUMN = [((150, 70, 28), (196, 104, 36), (232, 164, 60)), ((160, 120, 30), (206, 166, 48), (240, 210, 90)),
              ((130, 44, 30), (172, 62, 36), (214, 110, 50))]

    def _pine(self, s, x, y, sz=1.0, season=0, snow=False, rng=None):
        pygame.draw.rect(s, (96, 66, 40), (x - 1, y - 5, 3, 6))
        dark, light = ((30, 80, 48), (44, 104, 58)) if season == 3 else ((36, 94, 50), (56, 124, 62))
        for i, (w, hh) in enumerate(((9, 11), (7, 10), (5, 9))):
            w, hh = int(w * sz), int(hh * sz)
            by = y - 4 - i * int(6 * sz)
            pygame.draw.polygon(s, dark, [(x - w, by), (x + w, by), (x, by - hh)])
            pygame.draw.polygon(s, light, [(x - w + 1, by - 1), (x, by - 1), (x, by - hh + 1)])
            if snow:
                pygame.draw.polygon(s, (244, 246, 250), [(x - w // 2, by - hh // 2), (x + w // 2, by - hh // 2 + 1),
                                                         (x, by - hh)])
                pygame.draw.line(s, (236, 240, 246), (x - w, by), (x - w // 2, by - 1))

    def _oak(self, s, x, y, sz=1.0, season=0, snow=False, rng=None):
        pygame.draw.rect(s, (98, 68, 42), (x - 1, y - 7, 3, 8))
        r = int(8 * sz)
        rng = rng or random.Random(x * 31 + y)
        if season == 3 or snow:                                        # bladløs krone af grene
            col = (92, 70, 52)
            for a, l in ((-1.2, 1.0), (-0.5, 1.15), (0.2, 1.1), (0.9, 0.95), (-2.2, 0.8)):
                ex, ey = x + math.cos(a - 1.57) * r * l, y - 9 + math.sin(a - 1.57) * r * l
                pygame.draw.line(s, col, (x, y - 7), (int(ex), int(ey)), 1)
                if snow:
                    s.set_at((int(ex), int(ey)), (246, 248, 252))
                    s.set_at((int((x + ex) / 2), int((y - 7 + ey) / 2) - 1), (240, 244, 250))
            return
        pal = self.LEAVES.get(season) or rng.choice(self.AUTUMN)
        pygame.draw.circle(s, pal[0], (x + 1, y - 11), r)
        pygame.draw.circle(s, pal[1], (x, y - 13), r - 1)
        pygame.draw.circle(s, pal[2], (x - 2, y - 15), max(2, r // 2))
        if season == 0:                                                # forårsblomster
            for _ in range(3):
                s.set_at((x + rng.randint(-r + 2, r - 2), y - 13 + rng.randint(-r + 3, r - 3)), (246, 236, 240))

    def _forest(self, i, season=0, snow=False):
        s = self._surf(SPR_H)
        rng = random.Random(i * 7 + 3)
        spots = [(0.25, 0.3), (0.72, 0.28), (0.5, 0.6), (0.2, 0.78), (0.8, 0.75)]
        rng.shuffle(spots)
        spots = sorted(spots[:4], key=lambda p: P(*p)[1])
        for u, v in spots:
            x, y = P(u, v)
            kind = self._pine if rng.random() < 0.55 else self._oak
            kind(s, int(x), int(y), rng.uniform(0.85, 1.15), season, snow, random.Random(int(x * 13 + y + i)))
        return s

    def _young_forest(self, stage, season=0, snow=False):
        """Nyplantet skov i tre størrelser."""
        s = self._surf(SPR_H)
        rng = random.Random(stage * 5 + 1)
        sz = (0.4, 0.6, 0.8)[stage]
        for u, v in sorted([(0.3, 0.3), (0.7, 0.3), (0.5, 0.55), (0.3, 0.75), (0.72, 0.72)], key=lambda p: P(*p)[1]):
            x, y = P(u + rng.uniform(-0.05, 0.05), v + rng.uniform(-0.05, 0.05))
            (self._pine if rng.random() < 0.6 else self._oak)(s, int(x), int(y), sz, season, snow, rng)
        return s

    def _single_tree(self, season=0, snow=False):
        s = self._surf(SPR_H)
        x, y = P(0.5, 0.5)
        self._oak(s, int(x), int(y), 1.2, season, snow, random.Random(5))
        return s

    # ── årstider ─────────────────────────────────────────────────────────────
    GROUND_TINT = {0: None, 1: ((1.06, 1.0, 0.8), (0, 0, 0)), 2: ((1.25, 0.9, 0.58), (6, 0, 0)),
                   3: ((0.86, 0.76, 0.68), (22, 20, 16))}

    @staticmethod
    def _tint(surf, mult, add=(0, 0, 0)):
        s = surf.copy()
        s.fill((int(min(255, mult[0] * 255)), int(min(255, mult[1] * 255)), int(min(255, mult[2] * 255)), 255),
               special_flags=pygame.BLEND_RGBA_MULT)
        if any(add):
            s.fill((*add, 0), special_flags=pygame.BLEND_RGBA_ADD)
        return s

    def _make_seasons(self):
        """Forudtegnede udgaver af jord og træer for hver årstid samt snedække."""
        self.looks = {}
        for season in range(4):
            tint = self.GROUND_TINT[season]
            f = (lambda g: self._tint(g, *tint)) if tint else (lambda g: g)
            self.looks[season] = dict(grass=[f(g) for g in self.grass0], pasture=f(self.pasture0), field=self.field0,
                                      forest=[self._forest(i, season) for i in range(3)],
                                      tree=self._single_tree(season), water=self.water0,
                                      young=[self._young_forest(k, season) for k in range(3)],
                                      stub=self._tint(self.stub0, *tint) if season == 3 else self.stub0)
        snowg = [self._ground((230, 234, 240), [(212, 218, 228), (246, 248, 252), (200, 208, 220)], 0.2)
                 for _ in range(3)]
        self.looks["snow"] = dict(grass=snowg, pasture=snowg[0],
                                  field=[self._tint(fl, (0.32, 0.32, 0.34), (170, 172, 180)) for fl in self.field0],
                                  forest=[self._forest(i, 3, True) for i in range(3)], tree=self._single_tree(3, True),
                                  young=[self._young_forest(k, 3, True) for k in range(3)],
                                  water=[self._ice()] * 2, stub=None)
        self.look_key = 0
        self._apply_look()

    def snow_road(self):
        """Sne på en vej, der ikke er ryddet."""
        spr = self.spr.get("snow_road")
        if spr is None:
            spr = self._ground((232, 236, 244), [(216, 222, 232), (246, 248, 252), (206, 212, 224)], 0.25)
            spr.set_alpha(None)
            mask = pygame.Surface(spr.get_size(), pygame.SRCALPHA)
            mask.blit(spr, (0, 0))
            mask.fill((255, 255, 255, 240), special_flags=pygame.BLEND_RGBA_MULT)
            spr = self.spr["snow_road"] = mask
        return spr

    def _ice(self):
        s = self._ground((176, 206, 226), [(196, 222, 238), (160, 192, 214), (220, 236, 246)], 0.15)
        for _ in range(3):
            x, y = self.r.randrange(12, TW - 12), self.r.randrange(8, TH - 8)
            pygame.draw.line(s, (236, 246, 252), (x, y), (x + 8, y - 3), 1)
        return s

    # ── pixel-træer (valgfrit): skov, ung skov og enkelte træer af klodser ──
    pixel_tree = False

    def _vox_pine(self, b, ci, cj, sz, season, snow):
        b.box(int(ci), int(ci) + 1, int(cj), int(cj) + 1, 0, max(2, int(2 * sz)), (96, 66, 40))
        dark, light = ((30, 80, 48), (44, 104, 58)) if season == 3 else ((36, 94, 50), (56, 124, 62))
        k = max(2, int(2 * sz))
        for r, hh in ((2.9, 4), (2.2, 4), (1.5, 3), (0.8, 3)):
            r, hh = max(0.8, r * sz), max(1, int(round(hh * sz)))
            for kk in range(k, k + hh):
                rr = r * (1 - (kk - k) / (hh + 1) * 0.55)
                top = kk == k + hh - 1
                for i in range(int(ci - rr - 1), int(ci + rr + 2)):
                    for j in range(int(cj - rr - 1), int(cj + rr + 2)):
                        d = math.hypot(i + 0.5 - ci, j + 0.5 - cj)
                        if d <= rr:
                            c = light if (i + j + kk) % 3 == 0 else dark
                            if snow and (top or d > rr - 1.2) and (i * 3 + j + kk) % 2 == 0:
                                b.put3(i, j, kk, ((244, 246, 250), c, _vsh(c, 0.76)))
                            else:
                                b.put(i, j, kk, c)
            k += max(1, hh - 1)

    def _vox_oak(self, b, ci, cj, sz, season, snow, rng):
        th = max(2, int(4 * sz))
        b.box(int(ci), int(ci) + 1, int(cj), int(cj) + 1, 0, th, (98, 68, 42))
        if season == 3 or snow:                                        # bladløs krone af grene
            col = (92, 70, 52)
            b.box(int(ci), int(ci) + 1, int(cj), int(cj) + 1, th, th + int(2 * sz), col)
            r = 2.8 * sz                                               # glisne kviste i kronens form
            kc = th + r * 0.9
            for i in range(int(ci - r - 1), int(ci + r + 2)):
                for j in range(int(cj - r - 1), int(cj + r + 2)):
                    for k in range(max(0, int(kc - r)), int(kc + r + 1)):
                        d = math.hypot(i + 0.5 - ci, j + 0.5 - cj, (k + 0.5 - kc) * 1.15)
                        if d <= r and (d > r - 1.6 or k >= kc + r - 2):
                            top = snow and k >= kc + r * 0.3 and (i + j) % 2 == 0
                            c = (128, 108, 90) if (i + j + k) % 2 else (104, 84, 66)
                            b.put3(i, j, k, ((246, 248, 252) if top else _vsh(c, 1.12), c, _vsh(c, 0.76)))
            return
        pal = self.LEAVES.get(season) or rng.choice(self.AUTUMN)
        r = 2.8 * sz
        kc = th + r * 0.9
        for i in range(int(ci - r - 1), int(ci + r + 2)):
            for j in range(int(cj - r - 1), int(cj + r + 2)):
                for k in range(max(0, int(kc - r)), int(kc + r + 1)):
                    d = math.hypot(i + 0.5 - ci, j + 0.5 - cj, (k + 0.5 - kc) * 1.15)
                    if d <= r and (d > r - 1.6 or k >= kc + r - 2):
                        up_ = (k + 0.5 - kc) / r
                        c = pal[2] if up_ > 0.45 else pal[1] if up_ > -0.2 else pal[0]
                        if (i * 7 + j * 3 + k * 5) % 7 == 0:
                            c = pal[0] if c != pal[0] else pal[1]
                        b.put(i, j, k, c)
        if season == 0:                                                # forårsblomster
            for _ in range(3):
                b.put(int(ci + rng.uniform(-r, r) * 0.6), int(cj + r * 0.7), int(kc + rng.uniform(-1, 2)),
                      (246, 236, 240))

    def _pix_trees(self, spots, season, snow, seed):
        """spots: [(u, v, størrelse, 'pine'/'oak')] i feltet -> sprite (samme mål som de klassiske)."""
        b = VoxB(16, 16)
        rng = random.Random(seed)
        for u, v, sz, kind in spots:
            if kind == "pine":
                self._vox_pine(b, u * 16, v * 16, sz, season, snow)
            else:
                self._vox_oak(b, u * 16, v * 16, sz, season, snow, rng)
        return vox_sprite(b, 1, 1, TW, SPR_H)

    def _pix_forest(self, i, season=0, snow=False):
        rng = random.Random(i * 7 + 3)
        spots = [(0.25, 0.3), (0.72, 0.28), (0.5, 0.6), (0.2, 0.78), (0.8, 0.75)]
        rng.shuffle(spots)
        return self._pix_trees([(u, v, rng.uniform(0.85, 1.15), "pine" if rng.random() < 0.55 else "oak")
                                for u, v in spots[:4]], season, snow, i)

    def _pix_young(self, stage, season=0, snow=False):
        rng = random.Random(stage * 5 + 1)
        sz = (0.4, 0.6, 0.8)[stage]
        return self._pix_trees([(u + rng.uniform(-0.05, 0.05), v + rng.uniform(-0.05, 0.05), sz,
                                 "pine" if rng.random() < 0.6 else "oak")
                                for u, v in [(0.3, 0.3), (0.7, 0.3), (0.5, 0.55), (0.3, 0.75), (0.72, 0.72)]],
                               season, snow, stage)

    def _pix_look(self, key):
        """Pixel-træerne for en årstid (eller sne) – laves første gang, de skal bruges."""
        c = self.__dict__.setdefault("_ptrees", {})
        if key not in c:
            season, snow = (3, True) if key == "snow" else (key, False)
            c[key] = dict(forest=[self._pix_forest(i, season, snow) for i in range(3)],
                          young=[self._pix_young(k, season, snow) for k in range(3)],
                          tree=self._pix_trees([(0.5, 0.5, 1.2, "oak")], season, snow, 5))
        return c[key]

    def set_pixel_tree(self, on):
        self.pixel_tree = bool(on)
        self._apply_look()
        self.__dict__.get("_chunks", {}).clear()           # zoomet ud er skoven bagt ind i jorden

    def mill_blades(self, ang):
        """Pixel-vindmøllevinger: 24 trin pr. tredjedel omgang (vingerne ser ens ud hver 120°)."""
        step = int(round((ang % (2 * math.pi / 3)) / (2 * math.pi / 3) * 24)) % 24
        c = self.__dict__.setdefault("_pblades", {})
        spr = c.get(step)
        if spr is None:
            spr = pygame.Surface((60, 60), pygame.SRCALPHA)
            a0 = step / 24 * 2 * math.pi / 3
            for k in range(3):
                a = a0 + k * 2 * math.pi / 3
                ca, sa = math.cos(a), math.sin(a)
                px, py = -sa, ca
                pts = [(30 + px * 2, 30 + py * 2), (30 + ca * 25 + px * 1, 30 + sa * 25 + py * 1),
                       (30 + ca * 25 - px * 1, 30 + sa * 25 - py * 1), (30 - px * 1, 30 - py * 1)]
                pygame.draw.polygon(spr, (246, 246, 244), pts)
                pygame.draw.line(spr, (206, 208, 212), (30, 30), (30 + ca * 24, 30 + sa * 24), 1)
            pygame.draw.rect(spr, (226, 228, 230), (28, 28, 5, 5))
            pygame.draw.rect(spr, (220, 60, 50), (29, 29, 3, 3))
            m = pygame.mask.from_surface(spr, 127)
            big = pygame.mask.Mask(m.get_size())
            for off in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                big.draw(m, off)
            big.erase(m, (0, 0))
            spr.blit(big.to_surface(setcolor=(30, 26, 22), unsetcolor=(0, 0, 0, 0)), (0, 0))
            c[step] = spr
        return spr

    def _apply_look(self):
        L = self.looks[self.look_key]
        if self.pixel_tree:
            L = dict(L, **self._pix_look(self.look_key))
        self.grass, self.pasture, self.field = L["grass"], L["pasture"], L["field"]
        self.forest, self.water = L["forest"], L["water"]
        self.young = L["young"]
        self.stub = L["stub"] or self.field[1]
        self.spr["trae"] = L["tree"]

    def set_look(self, st):
        """Vælg årstidens udseende ud fra datoen og snedækket."""
        m = st.month()
        key = "snow" if getattr(st, "snow", 0) >= 0.3 else (3 if m in (11, 0, 1) else 0 if m in (2, 3, 4) else
                                                             1 if m in (5, 6, 7) else 2)
        if key != self.look_key:
            self.look_key = key
            self._apply_look()

    # ── bygninger ────────────────────────────────────────────────────────────
    def _box(self, s, u0, v0, u1, v1, h, wl, wr, roof, rh, hip=False, shadow=True, ox=0, ridge="u"):
        T, R, B, L = [(p[0] + ox, p[1]) for p in (P(u0, v0), P(u1, v0), P(u1, v1), P(u0, v1))]
        T2, R2, B2, L2 = up(T, h), up(R, h), up(B, h), up(L, h)
        if shadow:
            pygame.draw.polygon(s, (0, 0, 0, 50), [L, B, (B[0] + 8, B[1] - 4), (R[0] + 8, R[1] - 4), R])
        pygame.draw.polygon(s, wl, [L, B, B2, L2])
        pygame.draw.polygon(s, wr, [B, R, R2, B2])
        pygame.draw.line(s, shade(wl, 0.75), B, B2)
        if rh <= 0:
            pygame.draw.polygon(s, roof, [T2, R2, B2, L2])
        elif hip:
            apex = up(mid(T2, B2), rh)
            pygame.draw.polygon(s, shade(roof, 0.8), [T2, R2, apex])
            pygame.draw.polygon(s, shade(roof, 0.9), [L2, T2, apex])
            pygame.draw.polygon(s, roof, [L2, B2, apex])
            pygame.draw.polygon(s, shade(roof, 0.82), [B2, R2, apex])
        elif ridge == "v":            # rygningen løber langs v (bygningen er længst i den retning)
            A, Bp = up(mid(T2, R2), rh), up(mid(L2, B2), rh)
            pygame.draw.polygon(s, shade(roof, 0.9), [T2, A, Bp, L2])
            pygame.draw.polygon(s, shade(roof, 0.78), [A, R2, B2, Bp])
            pygame.draw.polygon(s, wl, [L2, B2, Bp])
            pygame.draw.line(s, shade(roof, 1.25), A, Bp)
            pygame.draw.line(s, shade(roof, 0.6), B2, R2)
        else:
            A, Bp = up(mid(T2, L2), rh), up(mid(R2, B2), rh)
            pygame.draw.polygon(s, shade(roof, 0.78), [T2, R2, Bp, A])
            pygame.draw.polygon(s, wr, [R2, B2, Bp])
            pygame.draw.polygon(s, roof, [A, Bp, B2, L2])
            pygame.draw.line(s, shade(roof, 1.25), A, Bp)
            pygame.draw.line(s, shade(roof, 0.6), L2, B2)
        return L, B, R

    @staticmethod
    def _face(s, a, b, a0, a1, z0, z1, col):
        pa = (a[0] + (b[0] - a[0]) * a0, a[1] + (b[1] - a[1]) * a0)
        pb = (a[0] + (b[0] - a[0]) * a1, a[1] + (b[1] - a[1]) * a1)
        pygame.draw.polygon(s, col, [up(pa, z0), up(pb, z0), up(pb, z1), up(pa, z1)])

    def _cyl(self, s, cx, by, rx, h, col):
        ry = max(2, rx // 2)
        pygame.draw.ellipse(s, shade(col, 0.82), (cx - rx, by - ry, 2 * rx, 2 * ry))
        pygame.draw.rect(s, col, (cx - rx, by - h, rx, h))
        pygame.draw.rect(s, shade(col, 0.82), (cx, by - h, rx, h))
        pygame.draw.ellipse(s, shade(col, 1.15), (cx - rx, by - h - ry, 2 * rx, 2 * ry))

    def flipped(self, spr):
        """Spejlvendt sprite = bygningen drejet (u og v bytter plads i den skrå visning)."""
        key = ("flip", id(spr))
        c = self._bcache.get(key)
        if c is None or c[0] is not spr:
            c = self._bcache[key] = (spr, pygame.transform.flip(spr, True, False))
        return c[1]

    def ghost(self, spr, z):
        """Gennemsigtig forhåndsvisning af en bygning, man er ved at placere."""
        key = ("ghost", id(spr), z)
        c = self._bcache.get(key)
        if c is None or c[0] is not spr:
            g = self.z(spr, z).copy()
            g.fill((255, 255, 255, 150), special_flags=pygame.BLEND_RGBA_MULT)
            c = self._bcache[key] = (spr, g)
        return c[1]

    def addon_sprite(self, key, flip=False):
        if flip:
            return self.flipped(self.addon_sprite(key))
        if self.pixel_bld:
            pb = self._pbx()
            fn = {"garage": pb.garage, "anneks": pb.annex, "springvand": pb.fountain, "gaardbutik": pb.farm_stall,
                  "pool": pb.pool, "tennis": pb.tennis, "dobbeltgarage": pb.garage2}.get(key)
            if fn:
                wide = ADDONS[key]["size"][0] == 2
                return self._pix(("addon", key), 2 if wide else 1, 1, fn, not wide)
        c = self._bcache.get(("addon", key))
        if c is None:
            if ADDONS[key]["size"][0] == 2:
                c, _, Q = self._bsurf(2, 1)
                sub = pygame.Surface((TW * 2, SPR_H + HALF_H), pygame.SRCALPHA)
                {"pool": self._pool, "tennis": self._tennis, "dobbeltgarage": self._garage2}[key](sub, wide=True)
                c.blit(sub, (0, 0))
            else:
                c = self._surf(SPR_H)
                {"garage": self._garage, "springvand": self._fountain, "gaardbutik": self._farm_stall,
                 "anneks": lambda sub: self._house_body(sub, 0, small=True)}[key](c)
            self._bcache[("addon", key)] = c
        return c

    def farm_sprite(self, w, h, flip=False, design="trelaenget"):
        """Gårde på flere felter. Trelænget: stuehus bagerst og lade/stald som sidelænger om en brolagt gårdsplads.
        De nyere gårde (tolænget, firlænget, længehus) findes kun i pixel."""
        d = HOUSE_DESIGNS.get(design) or HOUSE_DESIGNS["trelaenget"]
        sw, sh = d["size"]
        if sw != sh:                                     # aflang: drejet = spejlvendt tegning
            return self.flipped(self.farm_sprite(sw, sh, False, design)) if (w, h) == (sh, sw) else \
                self._pix(("farm", design, sw, sh), sw, sh,
                          lambda b: getattr(self._pbx(), "farm_" + design)(b, sw, sh))
        if flip:
            return self.flipped(self.farm_sprite(w, h, False, design))
        if design != "trelaenget":
            return self._pix(("farm", design, w, h), w, h, lambda b: getattr(self._pbx(), "farm_" + design)(b, w, h))
        if self.pixel_bld:
            return self._pix(("farm", w, h), w, h, lambda b: self._pbx().farm(b, w, h))
        key = ("trelaenget", w, h)
        c = self._bcache.get(key)
        if c is not None:
            return c
        c, ox, Q = self._bsurf(w, h)
        wall, wall_d = (238, 226, 190), (206, 192, 156)       # kalket mur
        red, thatch = (164, 58, 42), (150, 120, 70)
        timber = (96, 64, 40)
        pygame.draw.polygon(c, (150, 146, 136), [Q(0.3, 0.3), Q(w - 0.3, 0.3), Q(w - 0.3, h - 0.1), Q(0.3, h - 0.1)])
        for i in range(1, 12):                               # brosten på gårdspladsen
            u = 0.9 + (w - 1.8) * i / 12
            pygame.draw.line(c, (132, 128, 118), Q(u, 0.9), Q(u, h - 0.15), 1)
        # stuehuset bagerst (langs u)
        L, B, R = self._box(c, 0.08, 0.08, w - 0.08, 0.9, 22, wall, wall_d, red, 14, ox=ox, ridge="u")
        for a in (0.12, 0.24, 0.36, 0.64, 0.76, 0.88):
            self._face(c, L, B, a, a + 0.05, 8, 15, (84, 124, 168))
        self._face(c, L, B, 0.47, 0.54, 0, 13, (120, 70, 40))
        cx, cy = Q(w * 0.3, 0.45)
        pygame.draw.rect(c, (150, 64, 52), (int(cx) - 2, int(cy) - 44, 5, 10))
        # venstre længe: laden (bindingsværk og stråtag)
        L, B, R = self._box(c, 0.08, 0.9, 0.9, h - 0.08, 20, wall, wall_d, thatch, 13, ox=ox, ridge="v")
        for f in (0.2, 0.4, 0.6, 0.8):
            self._face(c, B, R, f, f + 0.02, 0, 20, timber)
        self._face(c, B, R, 0.34, 0.66, 0, 14, (110, 72, 44))         # ladeport
        self._face(c, B, R, 0.49, 0.51, 0, 14, (70, 46, 28))
        # højre længe: stalden (røde tegl, små staldvinduer)
        L, B, R = self._box(c, w - 0.9, 0.9, w - 0.08, h - 0.08, 18, wall, wall_d, red, 12, ox=ox, ridge="v")
        for f in (0.15, 0.35, 0.55, 0.75):
            self._face(c, B, R, f, f + 0.06, 9, 13, (84, 124, 168))
        self._face(c, L, B, 0.4, 0.6, 0, 12, (120, 70, 40))          # staldør ud mod gårdspladsen
        # træ og møddingsplads-hygge
        tx, ty = Q(w * 0.5, h * 0.62)
        pygame.draw.circle(c, (70, 128, 60), (int(tx), int(ty) - 12), 7)
        pygame.draw.rect(c, (96, 70, 44), (int(tx) - 1, int(ty) - 6, 3, 7))
        self._bcache[key] = c
        return c

    def house_sprite(self, level, flip=False):
        if flip:
            return self.flipped(self.house_sprite(level))
        if self.pixel_bld or level >= 3:                  # nye huse tegnes kun i pixel
            return self._pix(("house", level), 1, 1, lambda b: self._pbx().house(b, level), True)
        c = self._bcache.get(("house", level))
        if c is None:
            c = self._surf(SPR_H)
            self._house_body(c, level)
            self._bcache[("house", level)] = c
        return c

    def _house_body(self, s, level, small=False):
        if small:
            L, B, R = self._box(s, 0.25, 0.3, 0.75, 0.7, 14, (226, 214, 176), (196, 184, 150), (120, 60, 44), 10)
            self._face(s, L, B, 0.2, 0.35, 5, 10, (92, 134, 176))
            self._face(s, L, B, 0.6, 0.75, 0, 9, (116, 72, 42))
            return
        if level == 0:
            self._farmhouse_into(s)
        elif level == 1:
            L, B, R = self._box(s, 0.04, 0.18, 0.96, 0.82, 26, (240, 236, 222), (208, 200, 184), (150, 48, 38), 16)
            for a in (0.08, 0.26, 0.44, 0.74, 0.9):
                self._face(s, L, B, a, a + 0.07, 14, 21, (92, 134, 176))
                self._face(s, L, B, a, a + 0.07, 3, 9, (92, 134, 176))
            self._face(s, L, B, 0.58, 0.68, 0, 11, (116, 72, 42))
            self._face(s, B, R, 0.3, 0.45, 14, 21, (80, 118, 158))
            cx, cy = P(0.3, 0.35)
            pygame.draw.rect(s, (150, 64, 52), (int(cx) - 2, int(cy) - 48, 5, 12))
        else:
            L, B, R = self._box(s, 0.02, 0.1, 0.98, 0.9, 32, (246, 230, 190), (214, 196, 156), (60, 64, 72), 18,
                                hip=True)
            for a in (0.06, 0.2, 0.34, 0.62, 0.76, 0.9):
                for z0 in (4, 18):
                    self._face(s, L, B, a, a + 0.06, z0, z0 + 8, (80, 112, 150))
            self._face(s, L, B, 0.44, 0.56, 0, 14, (90, 58, 34))
            self._face(s, L, B, 0.4, 0.6, 14, 18, (236, 236, 230))
            for a in (0.2, 0.5, 0.8):
                self._face(s, B, R, a, a + 0.08, 18, 26, (80, 112, 150))
            for u in (0.2, 0.8):
                x, y = P(u, 0.1)
                pygame.draw.rect(s, (120, 116, 110), (int(x) - 2, int(y) - 58, 5, 12))

    GARAGE_WALL, GARAGE_ROOF = ((240, 236, 226), (206, 200, 188)), (168, 62, 46)

    def _garage_door(self, s, L, B, a0, a1, h):
        """Ledhejseport med rammer, vandrette paneler og et lille vinduesbånd."""
        self._face(s, L, B, a0 - 0.03, a1 + 0.03, 0, h + 1.5, (90, 86, 82))
        self._face(s, L, B, a0, a1, 0, h, (92, 96, 104))
        for z in range(2, int(h) - 2, 2):
            self._face(s, L, B, a0, a1, z, z + 0.5, (72, 76, 84))
        n = 4
        for i in range(n):
            w = (a1 - a0) / n
            self._face(s, L, B, a0 + i * w + w * 0.25, a0 + (i + 1) * w - w * 0.25, h - 2.4, h - 1.2, (170, 206, 230))

    def _garage_drive(self, s, u0, u1, v0, v1):
        """Belægning foran porten (fliser med fuger)."""
        pygame.draw.polygon(s, (186, 182, 172), [P(u0, v0), P(u1, v0), P(u1, v1), P(u0, v1)])
        n = max(2, int(round((u1 - u0) * 6)))
        for i in range(1, n):
            u = u0 + (u1 - u0) * i / n
            pygame.draw.line(s, (156, 152, 144), P(u, v0), P(u, v1))
        pygame.draw.line(s, (156, 152, 144), P(u0, (v0 + v1) / 2), P(u1, (v0 + v1) / 2))

    def _garage_lamp(self, s, L, B, a, z):
        pa = (L[0] + (B[0] - L[0]) * a, L[1] + (B[1] - L[1]) * a)
        x, y = up(pa, z)
        pygame.draw.rect(s, (40, 40, 44), (int(x) - 1, int(y) - 2, 3, 4))
        s.set_at((int(x), int(y)), (255, 226, 130))

    def _garage(self, s):
        wl, wr = self.GARAGE_WALL
        self._garage_drive(s, 0.22, 0.78, 0.8, 1.0)
        L, B, R = self._box(s, 0.18, 0.2, 0.82, 0.8, 12, wl, wr, self.GARAGE_ROOF, 8, ridge="v")
        self._face(s, L, B, 0, 1, 0, 1.5, (130, 128, 124))                  # sokkel
        self._face(s, B, R, 0, 1, 0, 1.5, (110, 108, 104))
        self._garage_door(s, L, B, 0.16, 0.84, 9)
        self._garage_lamp(s, L, B, 0.08, 9)
        self._face(s, B, R, 0.36, 0.64, 5, 9, (244, 242, 234))              # sidevindue
        self._face(s, B, R, 0.4, 0.6, 5.6, 8.4, (92, 130, 170))

    def _garage2(self, s, wide=True):
        wl, wr = self.GARAGE_WALL
        self._garage_drive(s, 0.14, 1.86, 0.8, 1.0)
        L, B, R = self._box(s, 0.1, 0.2, 1.9, 0.8, 12, wl, wr, self.GARAGE_ROOF, 8)
        self._face(s, L, B, 0, 1, 0, 1.5, (130, 128, 124))
        self._face(s, B, R, 0, 1, 0, 1.5, (110, 108, 104))
        self._garage_door(s, L, B, 0.07, 0.45, 9)
        self._garage_door(s, L, B, 0.55, 0.93, 9)
        self._garage_lamp(s, L, B, 0.5, 9.5)
        self._face(s, B, R, 0.3, 0.7, 5, 9, (244, 242, 234))
        self._face(s, B, R, 0.36, 0.64, 5.6, 8.4, (92, 130, 170))

    def _pool(self, s, wide=True):
        Q = lambda u, v: P(u, v)
        pygame.draw.polygon(s, (224, 220, 206), [Q(0.06, 0.1), Q(1.94, 0.1), Q(1.94, 0.9), Q(0.06, 0.9)])
        pygame.draw.polygon(s, (60, 150, 214), [Q(0.2, 0.22), Q(1.8, 0.22), Q(1.8, 0.78), Q(0.2, 0.78)])
        for u in (0.5, 0.9, 1.3):
            pygame.draw.line(s, (170, 220, 246), Q(u, 0.35), Q(u + 0.15, 0.35), 1)
        x, y = Q(1.85, 0.2)
        pygame.draw.line(s, (200, 200, 206), (x, y), (x, y - 6), 1)
        for u in (0.4, 0.8, 1.2):
            x, y = Q(u, 0.95)
            pygame.draw.rect(s, (236, 110, 70), (int(x) - 4, int(y) - 3, 8, 3))
        x, y = Q(1.6, 0.95)
