    def windmill_pic(self):
        """Vindmøllen med vinger (til kataloget og skyggen, når man placerer den)."""
        pk = "vindmoelle_pic" + ("_px" if self.pixel_bld else "")
        spr = self.spr.get(pk)
        if spr is None:
            spr = self.bspr("vindmoelle").copy()
            x, y = P(0.5, 0.5)
            hx, hy = int(x) + 1, int(y) - MILL_HUB - 1
            if self.pixel_bld:
                spr.blit(self.mill_blades(-math.pi / 2), (hx - 30, hy - 30))
                self.spr[pk] = spr
                return spr
            for k in range(3):
                a_ = -math.pi / 2 + k * 2 * math.pi / 3
                pygame.draw.line(spr, (244, 246, 248), (hx, hy), (hx + math.cos(a_) * 24, hy + math.sin(a_) * 24), 3)
            pygame.draw.circle(spr, (220, 222, 226), (hx, hy), 3)
            self.spr[pk] = spr
        return spr

    def _solar(self, w, h):
        """Solcelleanlæg: rækker af skrå, mørkeblå paneler på stativer."""
        s, ox, Q = self._bsurf(w, h)
        pygame.draw.polygon(s, (120, 150, 80), [Q(0.05, 0.05), Q(w - 0.05, 0.05), Q(w - 0.05, h - 0.05), Q(0.05, h - 0.05)])
        rows = max(2, h * 2)
        for r in range(rows):
            v0 = 0.15 + r * (h - 0.3) / rows
            v1 = v0 + (h - 0.3) / rows * 0.7
            a, b = Q(0.12, v1), Q(w - 0.12, v1)
            c, d = Q(w - 0.12, v0), Q(0.12, v0)
            lift = 9
            quad = [a, b, (c[0], c[1] - lift), (d[0], d[1] - lift)]
            for u in (0.2, w - 0.2):
                x_, y_ = Q(u, v1)
                pygame.draw.line(s, (90, 90, 96), (x_, y_), (x_, y_ - 3), 2)
            pygame.draw.polygon(s, (34, 54, 104), quad)
            for k in range(1, 6):                          # cellernes net
                f = k / 6
                p0 = (a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f)
                p1 = (d[0] + (c[0] - d[0]) * f, d[1] - lift + (c[1] - d[1]) * f)
                pygame.draw.line(s, (70, 100, 160), p0, p1, 1)
            pygame.draw.polygon(s, (150, 170, 210), quad, 1)
        return s

