    def _bunker(self, w, h, big=False):
        """Plansilo: lave betonvægge og en stak dækket med plastik og dæk."""
        s, ox, Q = self._bsurf(w, h)
        lng = w >= h
        a1, b1 = (w, h) if lng else (w, h)
        pygame.draw.polygon(s, (150, 150, 146), [Q(0, 0), Q(a1, 0), Q(a1, b1), Q(0, b1)])
        for side in ((0, 0, a1, 0), (0, 0, 0, b1), (0, b1, a1, b1) if not lng else (a1, 0, a1, b1)):
            u0, v0, u1, v1 = side
            p0, p1 = Q(u0, v0), Q(u1, v1)
            pygame.draw.polygon(s, (186, 186, 180), [p0, p1, up(p1, 9), up(p0, 9)])
            pygame.draw.line(s, (120, 120, 116), up(p0, 9), up(p1, 9))
        cx, cy = Q(a1 / 2, b1 / 2)
        rx, ry = HALF_W * (w + h) * 0.36, HALF_H * (w + h) * 0.32
        pygame.draw.ellipse(s, (34, 44, 36), (cx - rx, cy - ry - 10, rx * 2, ry * 2 + 6))
        pygame.draw.ellipse(s, (52, 66, 54), (cx - rx * 0.8, cy - ry - 12, rx * 1.6, ry * 1.4))
        for i in range(7):
            x = cx - rx * 0.7 + i * rx * 0.23
            y = cy - 8 + math.sin(i * 1.7) * ry * 0.4
            pygame.draw.ellipse(s, (24, 24, 26), (int(x) - 3, int(y) - 2, 6, 4))
        return s

    SPECTATORS = ((200, 60, 50), (60, 110, 190), (236, 200, 60), (240, 240, 236), (70, 140, 70), (40, 40, 44))

    def _tribune(self):
        """Tribune ved traktortræk-banen: trappetrin af træ med tag og publikum."""
        s = self._surf(SPR_H)
        r = random.Random(17)
        wood, wood_d = (150, 110, 70), (118, 84, 52)
        for k, (v0, v1, h) in enumerate(((0.62, 0.86, 4), (0.42, 0.66, 8), (0.22, 0.46, 12))):
            self._box(s, 0.06, v0, 0.94, v1, h, wood, wood_d, shade(wood, 1.15), 0, shadow=k == 0)
            for u in (0.15, 0.32, 0.5, 0.68, 0.85):
                if r.random() < 0.8:
                    x, y = P(u, (v0 + v1) / 2)
                    y -= h
                    c = r.choice(self.SPECTATORS)
                    pygame.draw.rect(s, c, (int(x) - 2, int(y) - 5, 4, 5))
                    pygame.draw.rect(s, (236, 196, 160), (int(x) - 1, int(y) - 8, 3, 3))
        for u in (0.08, 0.92):                                   # stolper og tag
            x, y = P(u, 0.24)
            pygame.draw.line(s, (90, 70, 50), (x, y - 12), (x, y - 26), 2)
        a, b = P(0.04, 0.2), P(0.96, 0.2)
        c, d = P(0.96, 0.5), P(0.04, 0.5)
        pygame.draw.polygon(s, (200, 60, 50), [(a[0], a[1] - 28), (b[0], b[1] - 28), (c[0], c[1] - 22), (d[0], d[1] - 22)])
        pygame.draw.polygon(s, (240, 236, 226), [(a[0], a[1] - 28), (b[0], b[1] - 28), (b[0], b[1] - 26), (a[0], a[1] - 26)])
        return s

