    BALE_COLS = {False: ((214, 184, 96), (232, 206, 120), (196, 164, 80), (200, 170, 86)),
                 True: ((226, 228, 226), (246, 246, 244), (196, 198, 196), (206, 208, 206))}

    def _one_bale(self, c, x, y, wrap=False, shadow=True, shape="rund"):
        body, end, core, back = self.BALE_COLS[wrap]
        if shadow:
            pygame.draw.ellipse(c, (0, 0, 0, 50), (x - 8, y - 2, 18, 6))
        if not wrap and shape in ("stor", "lille"):       # firkantet: bigballe – eller en pakke småballer
            w_, h_, d_ = (8, 9, 4) if shape == "stor" else (7, 7, 4)
            top = [(x - w_, y - h_ - d_ + 2), (x + w_ - 4, y - h_ - d_ - 1), (x + w_ + 2, y - h_ + 1), (x - w_ + 6, y - h_ + 4)]
            pygame.draw.polygon(c, end, top)
            pygame.draw.polygon(c, body, [(x - w_, y - h_ - d_ + 2), (x - w_ + 6, y - h_ + 4), (x - w_ + 6, y + 1),
                                          (x - w_, y - d_ + 1)])
            pygame.draw.polygon(c, back, [(x - w_ + 6, y - h_ + 4), (x + w_ + 2, y - h_ + 1), (x + w_ + 2, y - 2),
                                          (x - w_ + 6, y + 1)])
            if shape == "lille":                          # snorene om småballerne
                for f in (0.33, 0.66):
                    xa = x - w_ + 6 + (w_ * 2 - 4) * f
                    pygame.draw.line(c, core, (xa, y - h_ + 4 - 3 * f), (xa, y - 1 - 3 * f))
            else:
                for f in (0.3, 0.7):
                    xa = x - w_ + 6 + (w_ * 2 - 4) * f
                    pygame.draw.line(c, core, (xa, y - h_ + 3 - 3 * f), (xa, y - 1 - 3 * f))
            return
        pygame.draw.rect(c, body, (x - 7, y - 11, 12, 10))
        pygame.draw.ellipse(c, end, (x + 1, y - 12, 8, 12))
        pygame.draw.ellipse(c, core, (x + 3, y - 9, 4, 6))
        pygame.draw.ellipse(c, back, (x - 11, y - 12, 8, 12))
        if wrap:                                          # plastikkens folder
            pygame.draw.line(c, (180, 182, 180), (x - 5, y - 8), (x + 2, y - 8))

    def fold_bale_sprite(self, wrap=False, shape="rund", stage=2):
        """En balle i en rund foderhæk i folden. stage 2 = frisk, 1 = halvt ædt, 0 = næsten væk."""
        key = ("fbale", bool(wrap), shape, stage)
        c = self._bcache.get(key)
        if c is None:
            c = self._surf(SPR_H)
            x, y = P(0.5, 0.5)
            x, y = int(x), int(y)
            pygame.draw.ellipse(c, (0, 0, 0, 50), (x - 11, y - 3, 22, 8))
            straw = (226, 228, 226) if wrap else (226, 196, 108)
            pygame.draw.ellipse(c, shade(straw, 0.8) if not wrap else (120, 150, 90), (x - 9, y - 4, 18, 7))  # spild
            if stage >= 1:
                if stage == 2:
                    self._one_bale(c, x, y + 1, wrap, False, shape)
                else:
                    pygame.draw.ellipse(c, straw, (x - 7, y - 7, 14, 8))
                    pygame.draw.ellipse(c, shade(straw, 0.85), (x - 7, y - 4, 14, 6))
            ring = (70, 74, 80)
            for yy in (y - 9, y - 3):                                   # foderhækkens to ringe
                pygame.draw.ellipse(c, ring, (x - 10, yy, 20, 7), 1)
            for dx in (-10, -5, 0, 5, 9):                               # tremmer
                pygame.draw.line(c, ring, (x + dx, y - 6 + abs(dx) // 4), (x + dx, y + abs(dx) // 4))
            self._bcache[key] = c
        return c

    def bale_sprite(self, n, wrap=False, shape="rund"):
        """1–3 baller (halm – eller hvide wrapballer med ensilage) liggende på marken."""
        shape = "rund" if wrap else (shape or "rund")
