    def bale_yard(self, w, h, lh, lw, shape="rund"):
        """Ballepladsen: en grusplads med stakke af halmballer (lh) og wrapballer (lw) – antal synlige baller,
        stablet stak for stak i fast rækkefølge (halm fra den ene ende, wrap fra den anden)."""
        if self.pixel_bld:
            return self._pix(("yard", w, h, lh, lw, shape), w, h,
                             lambda b: self._pbx().bale_yard(b, max(w, h), min(w, h), lh, lw, shape))
        key = ("yard", w, h, lh, lw, shape)
        c = self._bcache.get(key)
        if c is None:
            c, ox, Q = self._bsurf(w, h)
            pygame.draw.polygon(c, (176, 162, 128), [Q(0.05, 0.05), Q(w - 0.05, 0.05), Q(w - 0.05, h - 0.05),
                                                     Q(0.05, h - 0.05)])
            cols, rows, _ = yard_grid(w, h)
            items = []
            for (col, row, lay), wr in yard_slots(w, h, lh, lw):
                x, y = Q(0.3 + (w - 0.6) * (col + 0.5) / cols, 0.3 + (h - 0.6) * (row + 0.5) / rows)
                items.append((y, lay, x, wr))
            for y, lay, x, wr in sorted(items):          # bagfra og frem, nederste lag først
                self._one_bale(c, int(x), int(y) - lay * 11, wr, lay == 0, "rund" if wr else shape)
            self._bcache[key] = c
        return c

    def timber_yard(self, w, h, lvl):
        """Tømmerpladsen: en grusplads med stammestakke, der vokser med lageret (0–4)."""
        if self.pixel_bld:
            return self._pix(("tyard", w, h, lvl), w, h,
                             lambda b: self._pbx().timber_yard(b, max(w, h), min(w, h), lvl))
        key = ("tyard", w, h, lvl)
        c = self._bcache.get(key)
        if c is None:
            c, ox, Q = self._bsurf(w, h)
            pygame.draw.polygon(c, (160, 146, 116), [Q(0.05, 0.05), Q(w - 0.05, 0.05), Q(w - 0.05, h - 0.05),
                                                     Q(0.05, h - 0.05)])
            for u in (0.3, w * 0.5 + 0.1):                       # bundstokke
                a, b = Q(u, 0.3), Q(u, h - 0.3)
                pygame.draw.line(c, (96, 72, 44), a, b, 2)
            piles = [(0.25, w * 0.5 - 0.05), (w * 0.5 + 0.05, w - 0.25)]
            for i, (u0, u1) in enumerate(piles):
                layers = min(4, lvl) if i == 0 else max(0, lvl - 1)
