                    for k in range(n):
                        v = 0.35 + (h - 0.7) * (k + 0.5 + layer * 0.5) / (5 + 0.0)
                        a, b = Q(u0, v), Q(u1, v)
                        y = -4 - layer * 5
                        pygame.draw.line(c, (122, 86, 50), (a[0], a[1] + y), (b[0], b[1] + y), 5)
                        pygame.draw.line(c, (170, 124, 78), (a[0], a[1] + y - 2), (b[0], b[1] + y - 2), 1)
                        pygame.draw.circle(c, (214, 176, 120), (int(b[0]), int(b[1] + y)), 3)
