    def log_pile_sprite(self, size):
        """Stak af træstammer på skovbunden efter fældning – size 0..3."""
        key = ("logpile", size)
        c = self._bcache.get(key)
        if c is None:
            c = self._surf(SPR_H)
            bark, dark, end, ring = (116, 80, 46), (78, 52, 30), (222, 188, 128), (176, 136, 82)
            rows = [4, 3, 2, 1][:2 + size // 2 + (1 if size == 3 else 0)]
            ln = (0.42, 0.5, 0.58, 0.64)[size]                # stammernes længde (langs feltet)
            u0, u1 = 0.5 - ln / 2, 0.5 + ln / 2
            x_, y_ = P(0.5, 0.5)
            pygame.draw.ellipse(c, (0, 0, 0, 50), (int(x_) - 20, int(y_) - 6, 40, 12))
            rw = 4 + (size >= 2)
            for lay, n in enumerate(rows):
                for i in range(n):
                    v = 0.5 + (i - (n - 1) / 2) * 0.13
                    a, b = up(P(u0, v), 3 + lay * (rw + 1)), up(P(u1, v), 3 + lay * (rw + 1))
                    pygame.draw.line(c, dark, a, b, rw + 2)
                    pygame.draw.line(c, bark, a, b, rw)
                    pygame.draw.line(c, shade(bark, 1.2), (a[0], a[1] - rw // 2), (b[0], b[1] - rw // 2), 1)
                    e = b                                    # snitfladen vender mod os
                    pygame.draw.ellipse(c, dark, (int(e[0]) - rw // 2 - 1, int(e[1]) - rw // 2 - 1, rw + 2, rw + 2))
                    pygame.draw.ellipse(c, end, (int(e[0]) - rw // 2, int(e[1]) - rw // 2, rw, rw))
                    pygame.draw.circle(c, ring, (int(e[0]), int(e[1])), 1)
            self._bcache[key] = c
        return c

