    # ── køretøjer (4 retninger, spillerens farve, evt. med redskab) ─────────
    def _veh_tools(self, s, d):
        pad = VEH_PAD

        def pt(a, b):
            x, y = P(*veh_uv(d, a, b))
            return x + pad, y

        def box(a0, a1, b0, b1, h, wl, wr, roof, shadow=False):
            self._prism(s, [pt(a0, b0), pt(a1, b0), pt(a1, b1), pt(a0, b1)], h, wl, wr, roof, shadow)

        def wheel(a, b, r, hub=(236, 200, 60)):
            x, y = pt(a, b)
            pygame.draw.circle(s, (28, 28, 30), (int(x), int(y) - r + 1), r)
            pygame.draw.circle(s, hub, (int(x), int(y) - r + 1), max(1, r // 2))
        return pt, box, wheel

    @staticmethod
    def _prism(s, g, h, wl, wr, roof, shadow=False):
        """Kasse med vilkårligt drejet grundflade g (4 skærmpunkter). Viser de sider, der vender mod os."""
        cx, cy = sum(p[0] for p in g) / 4, sum(p[1] for p in g) / 4
        if shadow:
            pygame.draw.polygon(s, (0, 0, 0, 50), [(x + (x - cx) * 0.15 + 5, y + (y - cy) * 0.15 + 1) for x, y in g])
        faces = []
        for i in range(4):
            p, q = g[i], g[(i + 1) % 4]
            mx, my = (p[0] + q[0]) / 2, (p[1] + q[1]) / 2
            ox_, oy_ = mx - cx, my - cy
            if oy_ > 0.01:
                k = clamp(0.5 + ox_ / (abs(ox_) + abs(oy_) + 1e-6) * 0.5, 0, 1)   # 0 = venstre side, 1 = højre
                faces.append((my, [p, q, (q[0], q[1] - h), (p[0], p[1] - h)], lerpc(wl, wr, k)))
        for _, poly, col in sorted(faces, key=lambda f: f[0]):
            pygame.draw.polygon(s, col, poly)
        pygame.draw.polygon(s, roof, [(x, y - h) for x, y in g])
        low = max(g, key=lambda p: p[1])
        pygame.draw.line(s, shade(lerpc(wl, wr, 0.5), 0.75), low, (low[0], low[1] - h))

    # ── pixel-køretøjer: små 3D-klodser (voxels) ───────────────────────────
    # Samme dele-lister som den klassiske tegning (_parts), men hver del fyldes ud i et gitter af klodser
    # (16 pr. felt, 2 px høje) i feltets egne akser og tegnes skråt fra oven. Så passer alle 8 retninger
    # automatisk, og redskaber/vogne (som stadig tegnes klassisk) sidder samme sted som før.
    pixel_veh = False
    VOX_R = 16
    VOX_OUTLINE = (30, 26, 22)

    def _vox_parts(self, s, d, sc, parts, ox=0.0, extra=()):
        """Klodsmotoren. parts (og hver gruppe i extra = [(sc, ox, parts), …]) fyldes ud i ét fælles gitter, så
        karosseri, redskab, vogn og læsser skjuler hinanden rigtigt. Ud over _parts' dele findes:
        ("beam", a0, b0, z0, a1, b1, z1, r, col)  – stang/rør fra punkt til punkt (r i px)
        ("cyl", akse, c0, c1, p, zc, r, col, col2, ende) – liggende cylinder langs 'a' eller 'b' (tromle, balle, stamme)"""
        cx, cy = VDIRS[d % 8]
        R = self.VOX_R
        vox = {}
        wheel_v = set()
        later = []
        glass = self.GLASS[0]
        side_n = ((cx, cy), (-cx, -cy), (-cy, cx), (cy, -cx))       # a1, a0, b1, b0
        rf = getattr(self, "_roll", 0) / ROLL_FRAMES           # 0..1 af én mønsterperiode
        roll_a = rf * 6.4                                       # dækmønstret: 2 klodser pr. 6,4 px omkreds
        roll_t = rf * 2
        pt0 = self._veh_tools(s, d)[0]

        def put(key, cols):
            if key not in wheel_v:
                vox[key] = cols

        def add(sc, ox, parts):
            def uv(a, b):
                return veh_uv(d, 0.5 + (a - 0.5 + ox) * sc, 0.5 + (b - 0.5) * sc)

            def cells(a0, a1, b0, b1):
                """Klodser, hvis midtpunkt ligger i rektanglet (i delens egne a/b-koordinater), som (i, j, a, b)."""
                pts = [uv(a0, b0), uv(a1, b0), uv(a1, b1), uv(a0, b1)]
                i0 = int(math.floor(min(p[0] for p in pts) * R)) - 1
                i1 = int(math.ceil(max(p[0] for p in pts) * R)) + 1
                j0 = int(math.floor(min(p[1] for p in pts) * R)) - 1
                j1 = int(math.ceil(max(p[1] for p in pts) * R)) + 1
                for i in range(i0, i1):
                    for j in range(j0, j1):
                        du, dv = (i + 0.5) / R - 0.5, (j + 0.5) / R - 0.5
                        a = (du * cx + dv * cy) / sc + 0.5 - ox
                        b = (-du * cy + dv * cx) / sc + 0.5
                        if a0 <= a <= a1 and b0 <= b <= b1:
                            yield i, j, a, b

            def grow(lo, hi):          # tynde plader skal mindst være én klods tykke
                m = 0.55 / R / sc
                if hi - lo < 2 * m:
                    c = (lo + hi) / 2
                    return c - m, c + m
                return lo, hi

            def kr(z0, z1):
                k0 = int(round(z0 * sc / 2))
                return k0, max(k0 + 1, int(round(z1 * sc / 2)))

            def cell_of(a, b):
                u, v = uv(a, b)
                return int(math.floor(u * R)), int(math.floor(v * R))

            # Fladernes retning (i u/v): a1 = fronten, a0 = bagenden, b0/b1 = siderne. En klods ved en flade får
            # fladens farve på begge sider – så bliver skrå flader (45°-retningerne) ensfarvede i stedet for stribede.
            near = 1.5 / R / sc

            def face_cols(a, b, a0, a1, b0, b1, wl, wr):
                best_l = best_r = None
                for dist, (nu, nv) in zip((a1 - a, a - a0, b1 - b, b - b0), side_n):
                    if dist < near and nu + nv > 0.05:
                        c = lerpc(wl, wr, clamp(nu / (nu + nv), 0, 1)) if nu > 0 and nv > 0 else \
                            (wr if nu > nv else wl)
                        if best_l is None or nv > best_l[0]:
                            best_l = (nv, c)
                        if best_r is None or nu > best_r[0]:
                            best_r = (nu, c)
                if best_l is None:
                    return wl, wr
                return best_l[1], best_r[1]

            last_body = None
            for p in parts:
                k = p[0]
                if k == "box":
                    _, a0, a1, b0, b1, z0, h, wl, wr, roof = p
                    a0, a1 = grow(*sorted((a0, a1)))
                    b0, b1 = grow(*sorted((b0, b1)))
                    k0, k1 = kr(z0, z0 + h)
                    is_glass = wl == glass
                    if not is_glass:
                        last_body = (wl, wr, roof)
                    sill = k0 + int((k1 - k0) * 0.36) if is_glass and z0 < 4 and last_body else k0
                    ea = 1.2 / R / sc
                    for i, j, a, b in cells(a0, a1, b0, b1):
                        post = is_glass and (a - a0 < ea or a1 - a < ea) and (b - b0 < ea or b1 - b < ea)
                        fl, fr = face_cols(a, b, a0, a1, b0, b1, wl, wr)
                        if sill > k0:
                            sl, sr = face_cols(a, b, a0, a1, b0, b1, last_body[0], last_body[1])
                        if post:
                            pl, pr = face_cols(a, b, a0, a1, b0, b1, shade(roof, 1.3), roof)
                        for kk in range(k0, k1):
                            if is_glass and kk < sill and (i, j, kk) in vox:
                                continue                   # ruden dækker aldrig karosseriet under vinduerne
                            if kk < sill:
                                put((i, j, kk), (shade(last_body[0], 1.1), sl, sr))
                            elif kk == k1 - 1:
                                put((i, j, kk), (roof, fl, fr))
                            elif post:
                                put((i, j, kk), (roof, pl, pr))
                            else:
                                put((i, j, kk), (shade(wl, 1.12), fl, fr))
                elif k == "track":
                    _, a0, a1, b0, b1, h = p
                    k0, k1 = kr(0, h)
                    a0, a1 = sorted((a0, a1))
                    b0, b1 = sorted((b0, b1))
                    for i, j, a, b in cells(a0, a1, b0, b1):
                        band = int((a - a0) * sc * R * 1.4 + roll_t) % 2
                        for kk in range(k0, k1):
                            c = (40, 40, 42) if band and kk in (k0, k1 - 1) else (58, 58, 60)
                            vox[(i, j, kk)] = (shade(c, 1.2),) + face_cols(a, b, a0, a1, b0, b1, c, shade(c, 0.72))
                elif k == "wheel":
                    _, a, b, r, hub = p
                    rr = max(3.0, r * sc)
                    hw = max(0.045, rr / 9 * 0.062) / sc          # dækkets halve bredde (i b)
                    ra = rr / 32 / sc                                # radius i a (32 px-højde pr. felt)
                    out_sign = -1 if b < 0.5 else 1
                    nu, nv = side_n[3] if b < 0.5 else side_n[2]    # dækkets yderside
                    kf = clamp(nu / (nu + nv), 0, 1) if nu + nv > 0.05 else None
                    for i, j, aa, bb in cells(a - ra - 0.05, a + ra + 0.05, b - hw, b + hw):
                        x = (aa - a) * sc * 32
                        outer = (bb - b) * out_sign * sc > hw * sc - 1.0 / R
                        for kk in range(0, int(rr) + 1):
                            z = kk * 2 + 1 - rr
                            dd = math.hypot(x, z)
                            if dd > rr:
                                continue
                            if outer and dd <= rr * 0.5:
                                c = hub
                                if rr >= 6 and 0.9 < dd and \
                                        int((math.atan2(z, x) + 4 + roll_a / rr) * 4 / math.pi) % 2:
                                    c = shade(hub, 0.78)           # fælgens huller drejer med rundt
                            elif dd > rr - 2.6:
                                c = (26, 25, 24) if int((math.atan2(z, x) + 4 + roll_a / rr) * rr / 3.2) % 2 \
                                    else (66, 63, 60)
                            else:
                                c = (40, 39, 38)
                            if outer and kf is not None:
                                f = lerpc(c, shade(c, 0.72), kf)
                                vox[(i, j, kk)] = (shade(c, 1.25), f, f)
                            else:
                                vox[(i, j, kk)] = (shade(c, 1.25), c, shade(c, 0.72))
                            wheel_v.add((i, j, kk))
                elif k == "line":
                    _, a, b, z0, z1, col, w = p
                    i, j = cell_of(a, b)
                    k0, k1 = kr(min(z0, z1), max(z0, z1))
                    for kk in range(k0, k1):
                        put((i, j, kk), (shade(col, 1.3), col, shade(col, 0.75)))
                elif k == "dot":
                    _, a, b, z, r, col = p
                    rr = r * sc
                    if rr >= 4:                                # en bunke (fx korn på ladet)
                        ra = rr / 32 / sc
                        kb = int(round((z - r) * sc / 2))
                        for i, j, aa, bb in cells(a - ra, a + ra, b - ra, b + ra):
                            dd = math.hypot((aa - a) * sc * 32, (bb - b) * sc * 32)
                            top = int((rr - dd) * 0.45)
                            for kk in range(kb, kb + top + 1):
                                put((i, j, kk), (shade(col, 1.12), col, shade(col, 0.78)))
                    else:
                        i, j = cell_of(a, b)
                        put((i, j, int(round(z * sc / 2))), (col, col, shade(col, 0.85)))
                elif k == "beam":
                    _, a0, b0, z0, a1, b1, z1, r, col = p
                    u0, v0 = uv(a0, b0)
                    u1, v1 = uv(a1, b1)
                    ln = math.hypot((u1 - u0) * 32, (v1 - v0) * 32, (z1 - z0) * sc)
                    n = max(1, int(ln / 0.8))
                    rv = r * sc / 2
                    m = int(math.ceil(rv - 0.5))
                    offs = [(di, dj, dk) for di in range(-m, m + 1) for dj in range(-m, m + 1)
                            for dk in range(-m, m + 1) if di * di + dj * dj + dk * dk <= max(0.0, rv - 0.5) ** 2 + 0.01]
                    cols = (shade(col, 1.25), col, shade(col, 0.72))
                    for q in range(n + 1):
                        f = q / n
                        i = int(math.floor((u0 + (u1 - u0) * f) * R))
                        j = int(math.floor((v0 + (v1 - v0) * f) * R))
                        kk = int(math.floor((z0 + (z1 - z0) * f) * sc / 2))
                        for di, dj, dk in offs:
                            if kk + dk >= 0:
                                put((i + di, j + dj, kk + dk), cols)
                elif k == "cyl":
                    _, axis, c0, c1, pp, zc, r, col, col2, end = p
                    c0, c1 = sorted((c0, c1))
                    rr = r * sc
                    rt = rr / 32 / sc
                    rect = (c0, c1, pp - rt, pp + rt) if axis == "a" else (pp - rt, pp + rt, c0, c1)
                    k0, k1 = kr(zc - r, zc + r)
                    for i, j, a, b in cells(*rect):
                        x = ((b if axis == "a" else a) - pp) * sc * 32
                        along = a if axis == "a" else b
                        cap = end and (along - c0 < 1.0 / R / sc or c1 - along < 1.0 / R / sc)
                        for kk in range(k0, k1 + 1):
                            z = kk * 2 + 1 - zc * sc
                            if math.hypot(x, z) > rr:
                                continue
                            c = end if cap else (col2 if int((along - c0) * sc * R) % 2 else col)
                            put((i, j, kk), (shade(c, 1.2), c, shade(c, 0.74)))
                elif k == "fn":
                    later.append((p[3], sc, ox))

        add(sc, ox, parts)
        for g in extra:
            add(*g)
        self._vox_draw(s, vox)
        for fn, sc_, ox_ in later:
            fn(lambda a, b, sc_=sc_, ox_=ox_: pt0(0.5 + (a - 0.5 + ox_) * sc_, 0.5 + (b - 0.5) * sc_), sc_)

        def pt(a, b):
            return pt0(0.5 + (a - 0.5 + ox) * sc, 0.5 + (b - 0.5) * sc)
        return pt

    def _vox_draw(self, s, vox):
        pad = VEH_PAD
        fill = s.fill
        for (i, j, k) in sorted(vox, key=lambda t: (t[0] + t[1], t[2])):
            if (i + 1, j, k) in vox and (i, j + 1, k) in vox and (i, j, k + 1) in vox:
                continue                                   # helt skjult
            top, lf, rt = vox[(i, j, k)]
            X = HALF_W + 2 * (i - j) + pad
            Y = GY + (i + j) - 2 * (k + 1)
            fill(top, (X - 1, Y, 2, 1))
            fill(top, (X - 2, Y + 1, 4, 1))
            fill(lf, (X - 2, Y + 2, 2, 2))
            fill(lf, (X - 1, Y + 4, 1, 1))
            fill(rt, (X, Y + 2, 2, 2))
            fill(rt, (X, Y + 4, 1, 1))

    def _vox_outline(self, spr):
        """Mørk 1-pixels kontur om alt det uigennemsigtige (skygger tæller ikke med)."""
        m = pygame.mask.from_surface(spr, 127)
        big = pygame.mask.Mask(m.get_size())
        for off in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            big.draw(m, off)
        big.erase(m, (0, 0))
        out = spr.copy()
        out.blit(big.to_surface(setcolor=self.VOX_OUTLINE, unsetcolor=(0, 0, 0, 0)), (0, 0))
        return out

    def _parts(self, s, d, sc, parts, ox=0.0, mid_a=0.5):
        """Tegner køretøjsdele sorteret bagfra og frem.
        parts: ("box", a0, a1, b0, b1, z0, h, wl, wr, roof) · ("wheel", a, b, r, hub) · ("line", a, b, z0, z1, col, w)
               ("dot", a, b, z, r, col) · ("track", a0, a1, b0, b1, h)
        a = langs køretøjet (0 bag, 1 front), b = på tværs, z = højde over jorden i pixels."""
        if self.pixel_veh:
            return self._vox_parts(s, d, sc, parts, ox)
        pt0 = self._veh_tools(s, d)[0]

        def pt(a, b):
            return pt0(0.5 + (a - 0.5 + ox) * sc, 0.5 + (b - 0.5) * sc)
        items = []
        mid_y = pt(mid_a, 0.5)[1]
        for p in parts:
            k = p[0]
            if k in ("box", "track"):
                a0, a1, b0, b1 = p[1:5]
                depth = pt((a0 + a1) / 2, (b0 + b1) / 2)[1] + (p[5] if k == "box" else 0) * 0.02
            elif k == "wheel":      # hjul på den fjerne side under karosseriet, de nære foran (bagfra og frem)
                yy = pt(p[1], p[2])[1]
                depth = (-1e4 if yy < mid_y else 1e4) + yy
            else:
                depth = pt(p[1], p[2])[1] + 0.5
            items.append((depth, p))
        items.sort(key=lambda it: it[0])
        for _, p in items:
            k = p[0]
            if k == "box":
                _, a0, a1, b0, b1, z0, h, wl, wr, roof = p
                g = [pt(a0, b0), pt(a1, b0), pt(a1, b1), pt(a0, b1)]
                self._prism(s, [(x, y - z0 * sc) for x, y in g], h * sc, wl, wr, roof, z0 == 0 and h > 6)
            elif k == "track":
                _, a0, a1, b0, b1, h = p
                g = [pt(a0, b0), pt(a1, b0), pt(a1, b1), pt(a0, b1)]
                self._prism(s, g, h * sc, (54, 54, 56), (40, 40, 42), (70, 70, 72))
                for aa in (a0 + 0.06, a1 - 0.06):
                    bb = b1 if pt(aa, b1)[1] > pt(aa, b0)[1] else b0
                    x, y = pt(aa, bb)
                    pygame.draw.circle(s, (120, 120, 124), (int(x), int(y - h * sc / 2)), max(2, int(h * sc / 2.6)))
                for i in range(1, 8):
                    aa = a0 + (a1 - a0) * i / 8
                    bb = b1 if pt(aa, b1)[1] > pt(aa, b0)[1] else b0
                    x, y = pt(aa, bb)
                    pygame.draw.line(s, (28, 28, 30), (x, y), (x, y - h * sc), 1)
            elif k == "wheel":
                _, a, b, r, hub = p
                x, y = pt(a, b)
                rr = max(3, int(r * sc))
                pygame.draw.circle(s, (28, 28, 30), (int(x), int(y) - rr + 1), rr)
                pygame.draw.circle(s, hub, (int(x), int(y) - rr + 1), max(1, rr // 2))
            elif k == "line":
                _, a, b, z0, z1, col, w = p
                x, y = pt(a, b)
                pygame.draw.line(s, col, (x, y - z0 * sc), (x, y - z1 * sc), w)
            elif k == "dot":
                _, a, b, z, r, col = p
                x, y = pt(a, b)
                pygame.draw.circle(s, col, (int(x), int(y - z * sc)), max(1, int(r * sc)))
            elif k == "fn":
                p[3](pt, sc)
        return pt

    GLASS = ((184, 216, 234), (150, 186, 208), (40, 40, 44))

    def _tractor_body(self, style, col, trim, sc, size):
        """Karosseri pr. type som liste af dele."""
        gl, gr, dark = self.GLASS
        c9, c7, c11 = shade(col, 0.9), shade(col, 0.72), shade(col, 1.12)
        blk = (44, 44, 46)
        P_ = []
        if style == "veteran":
            P_ += [("wheel", 0.3, 0.18, 10, trim), ("wheel", 0.3, 0.82, 10, trim),
                   ("wheel", 0.86, 0.34, 5, trim), ("wheel", 0.86, 0.66, 5, trim),
                   ("box", 0.2, 0.44, 0.1, 0.26, 12, 3, c9, c7, col), ("box", 0.2, 0.44, 0.74, 0.9, 12, 3, c9, c7, col),
                   ("box", 0.36, 0.98, 0.38, 0.62, 5, 11, c9, c7, col),
                   ("box", 0.22, 0.36, 0.42, 0.58, 8, 6, blk, blk, (70, 60, 50)),
                   ("line", 0.4, 0.5, 14, 21, blk, 2), ("dot", 0.4, 0.5, 21, 3, blk),
                   ("line", 0.78, 0.44, 16, 30, blk, 3),
                   ("line", 0.16, 0.3, 4, 30, blk, 2), ("line", 0.16, 0.7, 4, 30, blk, 2)]
            P_ += [("line", 0.16, bb, 29, 30, blk, 2) for bb in (0.35, 0.45, 0.55, 0.65)]
        elif style == "kompakt":
            P_ += [("wheel", 0.3, 0.24, 7, trim), ("wheel", 0.3, 0.76, 7, trim),
                   ("wheel", 0.82, 0.3, 5, trim), ("wheel", 0.82, 0.7, 5, trim),
                   ("box", 0.14, 0.92, 0.32, 0.68, 3, 7, c9, c7, col),
                   ("box", 0.58, 0.95, 0.36, 0.64, 9, 8, col, c7, c11),
                   ("box", 0.14, 0.5, 0.3, 0.7, 10, 18, gl, gr, col),
                   ("line", 0.66, 0.42, 17, 24, blk, 2)]
        elif style == "moderne":
            P_ += [("wheel", 0.28, 0.2, 11, trim), ("wheel", 0.28, 0.8, 11, trim),
                   ("wheel", 0.82, 0.26, 8, trim), ("wheel", 0.82, 0.74, 8, trim),
                   ("box", 0.12, 0.98, 0.33, 0.67, 4, 7, blk, blk, (60, 60, 62)),
                   ("box", 0.5, 1.0, 0.35, 0.65, 11, 9, col, c7, c11),
                   ("box", 0.5, 0.78, 0.35, 0.65, 20, 3, col, c7, c11),
                   ("box", 1.0, 1.08, 0.3, 0.7, 3, 9, blk, blk, (70, 70, 72)),
                   ("box", 0.1, 0.52, 0.27, 0.73, 11, 25, gl, gr, dark),
                   ("box", 0.08, 0.54, 0.25, 0.75, 36, 3, col, c7, c11),
                   ("dot", 0.3, 0.5, 41, 2, (246, 150, 40)),
                   ("line", 0.52, 0.22, 26, 32, blk, 1), ("line", 0.52, 0.78, 26, 32, blk, 1),
                   ("line", 0.62, 0.36, 22, 34, (60, 60, 62), 3)]
        elif style == "kantet":                       # klassisk blå med firkantet snude og lys grill
            grill, white = (200, 202, 206), (240, 240, 236)
            rr, fr = (8, 5) if size == 0 else (9, 6) if size == 1 else (10, 7)
            P_ += [("wheel", 0.26, 0.2, rr, trim), ("wheel", 0.26, 0.8, rr, trim),
                   ("wheel", 0.84, 0.3, fr, trim), ("wheel", 0.84, 0.7, fr, trim)]
            if size == 2:
                P_ += [("wheel", 0.26, 0.07, rr, trim), ("wheel", 0.26, 0.93, rr, trim)]
            hood_h = 11 if size == 0 else 13 if size == 1 else 15
            P_ += [("box", 0.12, 0.98, 0.36, 0.64, 3, 5, blk, blk, (60, 60, 62)),                 # chassis
                   ("box", 0.46, 0.97, 0.36, 0.64, 8, hood_h, col, c7, c11),                    # den firkantede snude
                   ("box", 0.97, 1.03, 0.37, 0.63, 8, hood_h - 1, grill, shade(grill, 0.8), grill),   # grillen
                   ("box", 0.14, 0.4, 0.12, 0.28, 13, 2, col, c7, c11), ("box", 0.14, 0.4, 0.72, 0.88, 13, 2, col, c7, c11),
                   ("line", 0.6, 0.4, 8 + hood_h, 16 + hood_h, blk, 2)]                         # udstødningen
