    def _car(self, col, d, style="sedan", trim=(236, 200, 60), front=None, extra=False, plow=False):
        """extra: bredt klippebord (havetraktor) eller terrændæk (ATV, UTV, terrænbil, minilæsser)."""
        lift = 0.25 if front is None or front is True else front / 8      # gafler/skovl: 0 = nede, 1 = oppe
        s = pygame.Surface((TW + 2 * VEH_PAD, SPR_H + 36), pygame.SRCALPHA)
        pt0 = self._veh_tools(s, d)[0]
        cx, cy = pt0(0.5, 0.5)
        pygame.draw.ellipse(s, (0, 0, 0, 60), (cx - 18, cy - 6, 36, 12))
        gl, gr, _ = self.GLASS
        hub = (170, 170, 176)
        c9, c7, c11 = shade(col, 0.95), shade(col, 0.75), shade(col, 1.1)
        blk, grey, seat = (40, 40, 44), (120, 122, 128), (34, 32, 30)
        if style == "havetraktor":
            P_ = [("wheel", 0.3, b, 4, (236, 200, 60)) for b in (0.33, 0.67)] + \
                 [("wheel", 0.8, b, 3, (236, 200, 60)) for b in (0.37, 0.63)]
            wb = 0.14 if extra else 0.28                                                          # bredt bord
