TEXT_SCALES = {1.0: "100%", 1.15: "115%", 1.25: "125%", 1.4: "140%"}
TEXT_SCALE = 1.0          # menuen til højre, avisen, beskederne i bunden og teksten, når musen holdes over


def set_text_scale(sc):
    """Større tekst i menuen til højre, avisen, beskederne i bunden og i hjælpeteksterne (layoutet skaleres med)."""
    global TEXT_SCALE, PANEL_W, LOG_H
    sc = float(sc) if sc in TEXT_SCALES or float(sc) in TEXT_SCALES else 1.0
    TEXT_SCALE = sc
    PANEL_W, LOG_H = int(round(340 * sc)), int(round(118 * sc))


class GameScene:
    VIS_DELAY = 0.13          # maskiner vises så meget bagud, så de kan glide jævnt mellem serverens positioner
    def _k(self, v):
        """Et layout-mål ganget med tekststørrelsen i det område, der tegnes lige nu (1 = uændret)."""
        sc = self.ui.scale
        if sc == 1.0:
            return v
        r = v * sc
        return int(round(r)) if isinstance(v, int) else r

    def _scaled_fit(self, fn, bw, bh, aw, ah, *a):
        """Som _scaled, men et vindue (bw × bh ved 100 %) bliver aldrig større end pladsen (aw × ah)."""
        sc = min(TEXT_SCALE, max(1.0, min(aw / bw, ah / bh)))
        old = self.ui.scale
        self.ui.scale = sc
        try:
            return fn(*a)
        finally:
            self.ui.scale = old

    def _scaled(self, fn, *a):
        """Tegn et område med den valgte tekststørrelse (skrift og afstande skaleres sammen)."""
        old = self.ui.scale
        self.ui.scale = TEXT_SCALE
        try:
            return fn(*a)
        finally:
            self.ui.scale = old

    def __init__(self, app, client, server=None):
        self.app, self.ui, self.art = app, app.ui, app.art
        self.client, self.server = client, server
        self.single = bool(server and server.local)
        self.st, self.me, self.title = None, None, ""
        self.cam = [0.0, 0.0]
        self.tool, self.crop, self.tab = "inspect", "hvede", "gaard"
        self.drag = None
        self.pan = None
        self.hover = None
        self.log = deque(maxlen=200)
        self.chat = None
        self.overlay = False
        self.menu = False
        self.lost = None
        self.trade_to, self.trade_what, self.trade_amt = None, "penge", 1000
        self.ip = lan_ip() if server and not self.single else None
        self.t = 0.0
        self.trac = {}
        self.mini = None
        self.mini_t = -9.0
        self.mini_rect = pygame.Rect(0, 0, 0, 0)
        self.popup_rect = pygame.Rect(0, 0, 0, 0)
        self.bpop = None
        self.bpop_rect = pygame.Rect(0, 0, 0, 0)
        self.zi = ZOOMS.index(1.0)
        self.z = 1.0
        self.catalog = None          # {"cat": ..., "i": ...} når Byg og køb-vinduet er åbent
        self.traffic = None
        self.driving = None          # id på den maskine, spilleren selv styrer
        self.slow_prev = None        # tempoet før man satte sig bag rattet (½ tempo, mens man kører)
        self.drv = None              # min fører-id fra serveren (flere kan køre på samme gård)
        self.local = None            # klientens egen forudsigelse af maskinen, man kører
        self.pos_t = 0.0
        self.steer = (0, 0)
        self.hud_rect = pygame.Rect(0, 0, 0, 0)
        self.cat_rect = pygame.Rect(0, 0, 0, 0)
        self.report = None           # årsrapporten: {"sel": indeks i historikken, -1 = i år}
        self.paper = False           # egnens avis
        self.showwin = False         # Egnens Dyrskue
        self.show_seen = None
        self.pullwin = False         # traktortrækket
        self.bankwin = False         # banken (lån)
        self.fplanwin = None         # markplan for én mark: {"key", "xy"}
        self.ms_pick = None          # maskinstation: bestil en opgave hos en anden gård
        self.pull_seen = None
        self.pullgame = None         # minispillet, mens man trækker
        self.guide_rect = pygame.Rect(0, 0, 0, 0)
        self.guide_min = False       # vejledningen foldet sammen
        self.fieldwin = False        # markkortet
        self.fpage = 0
        self.fedit = None            # omdøbning af en mark: {"xy", "input"}
        self.flabels = (None, [])
        self.news_seen = None
        self.fx = WeatherFX()
        self.townwin = False

    # ── layout ───────────────────────────────────────────────────────────────
    def view_rect(self):
        W, H = self.app.screen.get_size()
        return pygame.Rect(TOOLBAR_W, TOPBAR, W - TOOLBAR_W - PANEL_W, H - TOPBAR - LOG_H)

    def center_on(self, x, y):
        v = self.view_rect()
        wx, wy = iso(x + 0.5, y + 0.5)
        self.cam = [wx * self.z - v.w / 2, wy * self.z - v.h / 2]

    def set_zoom(self, zi, anchor=None):
        """Skift zoomniveau, så punktet under musen bliver stående."""
        zi = clamp(zi, 0, len(ZOOMS) - 1)
        if zi == self.zi:
            return
        v = self.view_rect()
        ax, ay = anchor if anchor else v.center
        wx, wy = (ax - v.x + self.cam[0]) / self.z, (ay - v.y + self.cam[1]) / self.z
        self.zi = zi
        self.z = ZOOMS[zi]
        self.cam = [wx * self.z - (ax - v.x), wy * self.z - (ay - v.y)]

    def theme(self):
        return self.app.cfg.get("theme", "klassisk") if PIXEL_THEME_ENABLED else "klassisk"

    def my(self):
        return self.st.players.get(self.me) if self.st else None

    def quit(self):
        self.client.close()
        if self.server:
            self.server.stop(save=True)

    def leave(self, error=None):
        self.app.sfx.silence()
        self.quit()
        self.app.scene = MenuScene(self.app, error)

    # ── input ────────────────────────────────────────────────────────────────
    def event(self, e):
        ui = self.ui
        view = self.view_rect()
        modal = self.menu or self.lost or self.st is None or self.report or self.townwin or self.paper or \
            self.showwin or self.fieldwin or self.pullwin or self.pullgame or self.bankwin or self.fplanwin or \
            self.ms_pick or getattr(self, "hostwin", False) or bool(getattr(self, "demo", None))
        psb = getattr(self, "_psb", None)
        if e.type == pygame.MOUSEBUTTONDOWN and e.button == 1 and not modal and psb and \
                psb[0].inflate(10, 0).collidepoint(e.pos) and not (self.bpop and self.bpop_rect.collidepoint(e.pos)):
            tr_, th_, mx_ = psb                              # sidepanelets rullebjælke
            ps = self.__dict__.setdefault("pscroll", {})
            if not th_.inflate(10, 0).collidepoint(e.pos):   # klik på skinnen: en side op eller ned
                step = tr_.h - 40
                ps[self.tab] = max(0, min(mx_, ps.get(self.tab, 0) + (step if e.pos[1] > th_.centery else -step)))
            self.psdrag = (e.pos[1], self.__dict__.get("pscroll", {}).get(self.tab, 0))
            return
        if e.type == pygame.MOUSEMOTION and getattr(self, "psdrag", None) is not None and psb:
            tr_, th_, mx_ = psb
            y0_, s0_ = self.psdrag
            self.pscroll[self.tab] = max(0, min(mx_, s0_ + (e.pos[1] - y0_) * mx_ / max(1, tr_.h - th_.h)))
            return
        if e.type == pygame.MOUSEBUTTONUP and e.button == 1 and getattr(self, "psdrag", None) is not None:
            self.psdrag = None
            return
        if e.type == pygame.MOUSEBUTTONDOWN:
            if e.button == 1:
                if not modal and self.driving and self.hud_rect.collidepoint(e.pos):
                    ui.click = e.pos
                elif not modal and self.catalog and self.cat_rect.collidepoint(e.pos):
                    ui.click = e.pos
                elif not modal and self.catalog and self.view_rect().collidepoint(e.pos):
                    self.catalog = None
                elif not modal and self.bpop and self.bpop_rect.collidepoint(e.pos):
                    ui.click = e.pos
                    if getattr(self, "shed_geo", None) and self.bpop.get("pos") == self.shed_geo["anchor"]:
                        self.sdrag = {"start": e.pos, "item": self._shed_item_at(e.pos), "moved": False}
                elif not modal and self.bpop and self.view_rect().collidepoint(e.pos):
                    self.bpop = None
                elif not modal and self.mini_rect.collidepoint(e.pos):
                    self._mini_jump(e.pos)
                elif not modal and self.popup_rect.collidepoint(e.pos):
                    ui.click = e.pos
                elif not modal and self.guide_rect.collidepoint(e.pos):
                    ui.click = e.pos
                elif not modal and view.collidepoint(e.pos):
                    self.drag = self._tile_at(e.pos)
                else:
                    ui.click = e.pos
            elif e.button in (2, 3) and view.collidepoint(e.pos):
                self.pan = (e.pos, list(self.cam), False)
        elif e.type == pygame.MOUSEMOTION and getattr(self, "sdrag", None):
            st_ = self.sdrag["start"]
            if abs(e.pos[0] - st_[0]) + abs(e.pos[1] - st_[1]) > 6:
                self.sdrag["moved"] = True
        elif e.type == pygame.MOUSEBUTTONUP and e.button == 1 and getattr(self, "sdrag", None):
            self._shed_drop(e.pos)
        elif e.type == pygame.MOUSEMOTION and self.pan:
            (sx, sy), c0, moved = self.pan
            dx, dy = e.pos[0] - sx, e.pos[1] - sy
            moved = moved or abs(dx) + abs(dy) > 4
            self.pan = ((sx, sy), c0, moved)
            if moved:
                self.cam = [c0[0] - dx, c0[1] - dy]
        elif e.type == pygame.MOUSEBUTTONUP:
            if e.button == 1 and self.drag is not None:
                self._apply_tool(self.drag, self._tile_at(e.pos))
                self.drag = None
            elif e.button in (2, 3) and self.pan:
                if e.button == 3 and not self.pan[2]:
                    self._right_click(e.pos)
                self.pan = None
        elif e.type == pygame.MOUSEWHEEL and self.menu and getattr(self, "menu_smax", None):
            mt_, mx_, _cr = self.menu_smax                 # rul i menuen (stor tekst / lille skærm)
            msc = self.__dict__.setdefault("menu_scroll", {})
            msc[mt_] = max(0, min(mx_, msc.get(mt_, 0) - e.y * 40))
        elif e.type == pygame.MOUSEWHEEL and not modal and self.tab == "marked" and \
                getattr(self, "market_rows", (pygame.Rect(0, 0, 0, 0), 0))[0].collidepoint(pygame.mouse.get_pos()):
            self.market_scroll = max(0, min(self.market_rows[1], getattr(self, "market_scroll", 0) - e.y))
        elif e.type == pygame.MOUSEWHEEL and not modal and getattr(self, "tb_max", 0) and \
                getattr(self, "tb_rect", None) is not None and self.tb_rect.collidepoint(pygame.mouse.get_pos()):
            self.tb_scroll = max(0, min(self.tb_max, getattr(self, "tb_scroll", 0) - e.y))   # rul værktøjerne
        elif e.type == pygame.MOUSEWHEEL and not modal and getattr(self, "log_rect", None) is not None and \
                self.log_rect.collidepoint(pygame.mouse.get_pos()):
            self.log_scroll = max(0, min(getattr(self, "log_scroll_max", 0),
                                         getattr(self, "log_scroll", 0) + e.y * 3))   # rul i beskederne
        elif e.type == pygame.MOUSEWHEEL and not modal and getattr(self, "panel_rect", None) is not None and \
                self.panel_rect.collidepoint(pygame.mouse.get_pos()):
            if self.tab != "marked":                         # rul i sidepanelet (ikke zoom på kortet)
                ps = self.__dict__.setdefault("pscroll", {})
                mx_ = self.__dict__.get("pscroll_max", {}).get(self.tab, 0)
                ps[self.tab] = max(0, min(mx_, ps.get(self.tab, 0) - e.y * 40))
        elif e.type == pygame.MOUSEWHEEL and not modal and not self.catalog:
            if e.y:
                self.set_zoom(self.zi + (1 if e.y > 0 else -1), pygame.mouse.get_pos())
        elif e.type == pygame.TEXTINPUT:
            if self.fedit is not None:
                self.fedit["input"].event(e)
            elif self.chat is not None:
                self.chat.event(e)
        elif e.type == pygame.KEYDOWN:
            self._key(e)

    def _key(self, e):
        k = e.key
        if self.fedit is not None:
            if k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                x, y = self.fedit["xy"]
                if self.fedit.get("key") == "farmname":
                    self.client.send({"a": "farmname", "name": self.fedit["input"].text})
                else:
                    self.client.send({"a": "fieldname", "x": x, "y": y, "name": self.fedit["input"].text})
                self.fedit = None
            elif k == pygame.K_ESCAPE:
                self.fedit = None
            else:
                self.fedit["input"].event(e)
            return
        if k == pygame.K_F3 and self.st and not self.menu:
            self.fieldwin, self.fpage = not self.fieldwin, 0
            return
        if self.chat is not None:
            if k in (pygame.K_RETURN, pygame.K_KP_ENTER):
                if self.chat.text.strip():
                    self.client.send({"a": "chat", "text": self.chat.text})
                self.chat = None
            elif k == pygame.K_ESCAPE:
                self.chat = None
            else:
                self.chat.event(e)
            return
        if self.lost:
            if k in (pygame.K_RETURN, pygame.K_ESCAPE):
                self.leave()
            return
        if self.pullgame:                            # traktortræk: tasterne bruges af minispillet
            if self.pullgame["state"] == "done" and k in (pygame.K_RETURN, pygame.K_ESCAPE, pygame.K_SPACE):
                self.pullgame = None
            elif self.pullgame["state"] == "ready" and k == pygame.K_ESCAPE:
                self.pullgame = None
            return
        if self.pullwin and k in (pygame.K_ESCAPE, pygame.K_RETURN):
            self.pullwin = False
            return
        if self.bankwin and k in (pygame.K_ESCAPE, pygame.K_RETURN):
            self.bankwin = False
            return
        if self.fplanwin and k in (pygame.K_ESCAPE, pygame.K_RETURN):
            self.fplanwin = None
            return
        if self.ms_pick and k == pygame.K_ESCAPE:
            self.ms_pick = None
            return
        if self.report or self.townwin or self.paper or self.showwin or self.fieldwin:
            if k in (pygame.K_ESCAPE, pygame.K_F2, pygame.K_RETURN):
                self.report, self.townwin, self.paper, self.showwin, self.fieldwin = None, False, False, False, False
            elif self.report and k in (pygame.K_LEFT, pygame.K_RIGHT):
                self._report_flip(-1 if k == pygame.K_LEFT else 1)
            elif self.report and k == pygame.K_F4:
                self.report["tab"] = "acc" if self.report.get("tab") == "earn" else "earn"
            elif self.report and k == pygame.K_F6:
                self.report["tab"] = "acc" if self.report.get("tab") == "budget" else "budget"
            elif self.report and k == pygame.K_F7:
                self.report["tab"] = "acc" if self.report.get("tab") == "cost" else "cost"
            return
        if k == pygame.K_TAB and self.st and not self.menu and not self.catalog:
            self.cycle_vehicle()
            return
        if self.driving and not self.menu and not self.catalog:
            if k == pygame.K_ESCAPE:
                self.stop_driving()
                return
            if k == pygame.K_k:
                self.client.send({"a": "hitch", "id": self.driving})
                return
            if k == pygame.K_p:
                self.client.send({"a": "parkhere", "id": self.driving})
                return
            if k == pygame.K_t and self.pull_ready():
                self.start_pull()
                return
            if k == pygame.K_g:
                self.client.send({"a": "gps", "id": self.driving})
                return
            if k in (pygame.K_f, pygame.K_j):
                me = next((t for t in self.st.tractor_view if t[0] == self.driving), None)
                act = me[18] if me and len(me) > 18 else None
                if k == pygame.K_j and act and act.get("g"):
                    self.client.send({"a": "shoot", "id": self.driving})
                    self.app.sfx.play("click", 1.0)
                elif not act:
                    self.client.send({"a": "trip", "id": self.driving, "kind": "fish" if k == pygame.K_f else "hunt"})
                return
            if k == pygame.K_l:
                self.toggle_implement()
                return
            if k == pygame.K_e:
                self.client.send({"a": "loader", "id": self.driving})
                return
            if k == pygame.K_o:                              # åbn eller luk lågen i foldens hegn
                self.client.send({"a": "gate", "id": self.driving, "x": 0, "y": 0, "d": 0})
                return
            if k in (pygame.K_UP, pygame.K_DOWN, pygame.K_LEFT, pygame.K_RIGHT, pygame.K_w, pygame.K_a,
                     pygame.K_s, pygame.K_d):
                return
        if k == pygame.K_ESCAPE and self.catalog:
            self.catalog = None
        elif self.catalog and k in (pygame.K_LEFT, pygame.K_RIGHT, pygame.K_a, pygame.K_d):
            self._cat_flip(-1 if k in (pygame.K_LEFT, pygame.K_a) else 1)
        elif k == pygame.K_ESCAPE and self.bpop:
            self.bpop = None
        elif k == pygame.K_F1 or (k == pygame.K_ESCAPE and (self.tool == "inspect" or self.menu)):
            self.menu = not self.menu
        elif k == pygame.K_ESCAPE:
            self.tool = "inspect"
        elif self.menu or self.st is None:
            return
        elif k in (pygame.K_RETURN, pygame.K_KP_ENTER) and not self.single:
            self.chat = TextInput("", 160)
        elif k in (pygame.K_1, pygame.K_2, pygame.K_3, pygame.K_4):
            p = self.st.players.get(HUMAN_IDS[k - pygame.K_1])
            if p:
                self.center_on(*p["home"])
        elif k == pygame.K_h:
            self.center_on(*self.my()["home"])
        elif k == pygame.K_t:
            self.center_on(ROAD_X, ROAD_Y)
        elif k == pygame.K_SPACE:
            self.client.send({"a": "speed", "v": 0 if self.st.speed else getattr(self, "last_speed", START_SPEED)})
        elif k == pygame.K_m:
            self.cycle_overlay()
        elif k in (pygame.K_PLUS, pygame.K_EQUALS, pygame.K_KP_PLUS):
            self.set_zoom(self.zi + 1)
        elif k in (pygame.K_MINUS, pygame.K_KP_MINUS):
            self.set_zoom(self.zi - 1)
        elif k == pygame.K_b:
            self.catalog, self.cat_shed = (None if self.catalog else {"cat": 0, "i": 0}), None
        elif k == pygame.K_r and self.placing() and self.placing()[2]:
            self.rot = not getattr(self, "rot", False)
        elif k == pygame.K_F5:
            self.save_game()
        elif k == pygame.K_F2:
            self.report = {"sel": -1}
        elif k == pygame.K_F4:
            self.report = {"sel": -1, "tab": "earn"}
        elif k == pygame.K_F6:
            self.report = {"sel": -1, "tab": "budget"}
        elif k == pygame.K_F7:
            self.report = {"sel": -1, "tab": "cost"}

    def _tile_at(self, pos):
        x, y = screen_to_tile(pos[0], pos[1], self.cam, self.view_rect(), self.z, self.st)
        return clamp(x, 0, MAP_W - 1), clamp(y, 0, MAP_H - 1)

    def placing(self):
        """(størrelse, navn, kan drejes) for det, man er ved at placere – eller None."""
        t = self.tool or ""
        if t in BUILDINGS:
            return BUILDINGS[t]["size"], BUILDINGS[t]["navn"], True
        if t.startswith("house:") and t[6:] in HOUSE_DESIGNS:
            d = HOUSE_DESIGNS[t[6:]]
            return d["size"], d["navn"], True
        if t.startswith("addon:") and t[6:] in ADDONS:
            a = ADDONS[t[6:]]
            return a["size"], a["navn"], True
        if t.startswith("move:"):
            b = self._move_kind()
            if b in BUILDINGS:
                return BUILDINGS[b]["size"], "flyt " + BUILDINGS[b]["navn"].lower(), True
            if b and b.startswith("ext:") and b[4:] in ADDONS:
                return ADDONS[b[4:]]["size"], "flyt " + ADDONS[b[4:]]["navn"].lower(), True
            self.tool = "inspect"
        return None

    def _move_kind(self):
        try:
            sx, sy = (int(v) for v in self.tool[5:].split(","))
            t = self.st.tiles[sy][sx]
            return t.b if t.o == self.me else None
        except (ValueError, IndexError):
            return None

    def _addon_pos(self, key):
        """Hvor står min tilbygning (ankerfeltet) – eller None."""
        b = "ext:" + key
        for y, row in enumerate(self.st.tiles):
            for x, t in enumerate(row):
                if t.b == b and t.o == self.me:
                    return self.st.anchor(x, y)[:2]
        return None

    def start_move(self, x, y):
        """Højreklik › Flyt: bygningen følger musen som en skygge – klik for at sætte den, R drejer."""
        st = self.st
        ax, ay, w, h = st.anchor(x, y)
        b = st.tiles[y][x].b
        size = BUILDINGS[b]["size"] if b in BUILDINGS else ADDONS[b[4:]]["size"]
        self.tool = f"move:{ax},{ay}"
        me_ = self.my() or {}
        self.rot = bool(me_.get("aflip", {}).get(b[4:])) if b.startswith("ext:") else \
            bool(me_.get("bflip", {}).get(f"{ax},{ay}")) if w == h else (w, h) != tuple(size)
        self.bpop = None
        self.log.append((f"Vælg en ny plads til bygningen og klik ({kr(st.move_cost(b))}). R drejer · Esc fortryder.",
                         "info"))

    def _ghost(self):
        """(sprite, x, y, bredde, dybde) for den gennemsigtige forhåndsvisning ved musen – eller None."""
        pl = self.placing()
        if not pl or not self.hover:
            return None
        w, h = self.footprint()
        rot = bool(getattr(self, "rot", False))
        t, art = self.tool, self.art
        if t.startswith("move:"):
            t = self._move_kind() or ""
            t = t if t in BUILDINGS else "addon:" + t[4:]
        if t in BUILDINGS:
            spr = art.building_sprite(t, w, h) if (w, h) != (1, 1) else \
                art.windmill_pic() if t == "vindmoelle" else art.bspr(t)
            if spr is not None and rot and w == h:        # kvadratisk: drejet = spejlvendt
                spr = art.flipped(spr)
        elif t.startswith("house:"):
            lv = HOUSE_DESIGNS[t[6:]]["lvl"]
            spr = art.farm_sprite(w, h, rot, t[6:]) if lv is None else art.house_sprite(lv, rot)
        else:
            spr = art.addon_sprite(t[6:], rot)
        return (spr, self.hover[0], self.hover[1], w, h) if spr else None

    def footprint(self):
        pl = self.placing()
        w, h = pl[0] if pl else (1, 1)
        return (h, w) if pl and pl[2] and getattr(self, "rot", False) else (w, h)

    def _apply_tool(self, a, b):
        x0, y0 = a
        x1, y1 = b
        t = self.st.tiles[y0][x0]
        if self.tool == "inspect":
            if t.b and (t.b.startswith("site:") or t.b.startswith("proj:")):
                self.tab = "faelles"
            return
        if self.tool == "gate":
            g = self._gate_edge(x1, y1) if t.t == "pasture" or self.st.tiles[y1][x1].t == "pasture" else None
            tx_, ty_ = x1, y1
            if g is None:                                    # ved siden af folden: se om naboen er et foldfelt
                for d_, (dx_, dy_) in enumerate(N4):
                    nx_, ny_ = x1 + dx_, y1 + dy_
                    if self.st.inb(nx_, ny_) and self.st.tiles[ny_][nx_].t == "pasture" and \
                            self.st.tiles[ny_][nx_].o == self.me:
                        g2 = self._gate_edge(nx_, ny_)
                        if g2 is not None and (nx_ + N4[g2][0], ny_ + N4[g2][1]) == (x1, y1):
                            g, tx_, ty_ = g2, nx_, ny_
                            break
            if g is not None and self.st.tiles[ty_][tx_].o == self.me:
                self.client.send({"a": "gate", "x": tx_, "y": ty_, "d": g, "op": "place"})
            else:
                self.log.append(("Klik på hegnet om en af dine folde – tæt ved den kant, hvor lågen skal sidde.",
                                 "info"))
            return
        if self.tool == "pasture" and a == b and t.t == "pasture" and t.o == self.me:
            g = self._gate_edge(x0, y0)                      # klik på foldens hegn: sæt en låge – eller åbn/luk den
            if g is not None:
                self.client.send({"a": "gate", "x": x0, "y": y0, "d": g, "op": "place"})
            return
        if self.tool == "bulldoze":                         # Ryd over en bygning: spørg først (Riv ned)
            T_ = self.st.tiles
            hit = next(((xx, yy) for yy in range(min(y0, y1), max(y0, y1) + 1)
                        for xx in range(min(x0, x1), max(x0, x1) + 1)
                        if self.st.inb(xx, yy) and T_[yy][xx].o == self.me and T_[yy][xx].b in BUILDINGS), None)
            if hit:
                self._ask_demolish(*hit)
                if (x0, y0) == (x1, y1):
                    return                                  # et klik på bygningen: kun spørgsmålet
        self.client.send({"a": "tool", "tool": self.tool, "x0": x0, "y0": y0, "x1": x1, "y1": y1,
                          "crop": getattr(self, "fence_col", "hvid") if self.tool == "hegn" else self.crop,
                          "rot": getattr(self, "rot", False)})
        if self.tool.startswith(("house:", "addon:", "move:")):   # huset, tilbygninger og flytning: én gang
            self.tool = "inspect"

    def _gate_edge(self, x, y):
        """Den kant af foldfeltet (x, y), musen er nærmest, hvis der er hegn der: N4-indeks – ellers None."""
        st = self.st
        v = self.view_rect()
        mx, my = pygame.mouse.get_pos() if not getattr(self, "_mouse_override", None) else self._mouse_override
        wx, wy = mx - v.x + self.cam[0], my - v.y + self.cam[1]
        if st.hm:
            wy += st.htile(x, y) * hstep(self.z)
        a_, b_ = wx / (HALF_W * self.z), wy / (HALF_H * self.z)
        fu, fv = (a_ + b_) / 2 - x, (b_ - a_) / 2 - y
        cands = [(fu, 1), (1 - fu, 0), (fv, 3), (1 - fv, 2)]
        cands = [(dist, d) for dist, d in sorted(cands) if st.fence_edge(x, y, d)]
        return cands[0][1] if cands and cands[0][0] < 0.45 else None

    def _mini_jump(self, pos):
        s = getattr(self, "mini_sc", 1.5)
        mx, my = (pos[0] - self.mini_rect.x) / s, (pos[1] - self.mini_rect.y) / s
        v = self.view_rect()
        wx, wy = (mx - (MAP_H - 1)) * HALF_W * self.z, my * TH * self.z
        self.cam = [wx - v.w / 2, wy - v.h / 2]

    def _lift(self, x, y):
        """Hvor mange pixels jorden er løftet (bakker) i punktet (x, y) – feltkoordinater med midten i heltal."""
        st = self.st
        return st.hpos(x + 0.5, y + 0.5) * hstep(self.z) if st and st.hm else 0.0

    def _vehicle_at(self, pos):
        v = self.view_rect()
        hw, hh = HALF_W * self.z, HALF_H * self.z
        best, bd = None, 30 * self.z
        for tv in self.st.tractor_view:
            if self._in_shed(tv):
                continue
            x, y = self.trac.get(tv[0], tv[2:4])
            sx = v.x - self.cam[0] + (x - y) * hw
            sy = v.y - self.cam[1] + (x + y + 1) * hh - 14 * self.z - self._lift(x, y)
            dd = math.hypot(pos[0] - sx, pos[1] - sy)
            if dd < bd:
                best, bd = tv, dd
        return best

    LIFT_UP, LIFT_SPEED = 0.45, 1.1                 # frontlæsserens køre-/bærehøjde og fart (andel pr. sek.)

    def _loader_lifts(self):
        """Frontlæsserne bevæger sig blødt op og ned, når de hæves og sænkes."""
        now = self.t
        dt = clamp(now - getattr(self, "_lift_t", now), 0.0, 0.1)
        self._lift_t = now
        cur = getattr(self, "lifts", None)
        if cur is None:
            cur = self.lifts = {}
        out = {}
        for tr in self.st.tractor_view:
            if not view_loader(tr):
                continue
            down = len(tr) > 28 and tr[28] and tr[28][0] == "down"
            tgt = 0.0 if down else self.LIFT_UP
            v = cur.get(tr[0], tgt)
            step = self.LIFT_SPEED * dt
            v = min(tgt, v + step) if v < tgt else max(tgt, v - step)
            cur[tr[0]] = out[tr[0]] = v
        return out

    def _night(self, screen, view, tractors):
        """Natten (eksperiment): et mørkeblåt lag over landskabet med lys i husene, staldene og på maskinerne."""
        st = self.st
        d = night_level(getattr(self, "night_t", 0.0), st.month())
        self.night_d = d
        if d <= 0.01:
            return
        z = self.z

        def scr(tx_, ty_, up=0.0):
            return (view.x - self.cam[0] + (tx_ - ty_) * HALF_W * z,
                    view.y - self.cam[1] + (tx_ + ty_ + 1) * HALF_H * z - self._lift(int(tx_), int(ty_)) - up * z)
        holes, glows = [], []
        warm, cool = (255, 190, 90), (230, 236, 255)
        for q in st.players.values():                            # stuehuse og stalde
            hx, hy = q["home"]
            holes.append((scr(hx + 0.5, hy + 0.5, 12), 64 * z, 0.8))
            glows.append((scr(hx + 0.5, hy + 0.5, 14), 12 * z, warm))
            for k_, poss in st.stats(q["id"])["bpos"].items():
                if k_ in BUILDINGS and (BUILDINGS[k_]["group"] in STALL_GROUPS or k_ in ("lade", "drivhus", "halmfyr")):
                    for (ax, ay) in poss:
                        _a, _b, bw, bh = st.anchor(ax, ay)
                        holes.append((scr(ax + bw / 2, ay + bh / 2, 8), 40 * z, 0.55))
                        glows.append((scr(ax + bw - 0.2, ay + bh - 0.2, 6), 7 * z, warm))
            for (lx, ly) in st.stats(q["id"])["bpos"].get("lygtepael", []):   # lygtepælene
                holes.append((scr(lx + 0.5, ly + 0.5, 6), 44 * z, 0.85))
                glows.append((scr(lx + 0.5, ly + 0.5, 46), 8 * z, warm))
        tl = getattr(self, "_town_lights", None)                 # husene i byen
        if not tl or tl[0] != st.ver:
            pts = [(x, y) for y, row in enumerate(st.tiles) for x, t in enumerate(row) if t.t == "town" and t.b]
            tl = self._town_lights = (st.ver, pts)
        for (x, y) in tl[1]:
            p_ = scr(x + 0.5, y + 0.5, 10)
            if view.inflate(120, 120).collidepoint(p_):
                holes.append((p_, 30 * z, 0.38))
                glows.append((p_, 6 * z, warm))
        state = {tv[0]: tv[7] for tv in st.tractor_view if len(tv) > 7}
        for tr in tractors:                                        # lygter og arbejdslys
            stt = state.get(tr[0], "drive")
            if stt in ("home", "repair") or stt == "manual" and not tr[5]:
                continue
            x, y, dd = tr[2], tr[3], tr[4]
            dx, dy = VDIRS[int(dd) % 8]
            front = scr(x + 0.5 + dx * 0.9, y + 0.5 + dy * 0.9, 3)
            holes.append((front, 34 * z, 0.75))
            glows.append((scr(x + 0.5 + dx * 0.35, y + 0.5 + dy * 0.35, 6), 5 * z, cool))
            if tr[5] and stt not in ("drive",):                    # arbejdslys rundt om maskinen i marken
                holes.append((scr(x + 0.5, y + 0.5, 4), 52 * z, 0.7))
        layer = getattr(self, "_night_layer", None)
        if layer is None or layer.get_size() != view.size:
            layer = self._night_layer = pygame.Surface(view.size, pygame.SRCALPHA)
        a = int(NIGHT_MAX * d)
        layer.fill((10, 16, 46, a))
        for (px, py), r, k_ in holes:
            hs = light_hole(r, k_)
            layer.blit(hs, (int(px - view.x - r), int(py - view.y - r)), special_flags=pygame.BLEND_RGBA_SUB)
        screen.blit(layer, view.topleft)
        if d > 0.3:                                                # det varme skær i vinduerne og lygterne
            for (px, py), r, col in glows:
                gs = light_glow(r, tuple(int(c * min(1.0, (d - 0.3) * 1.6)) for c in col))
                screen.blit(gs, (int(px - r), int(py - r)), special_flags=pygame.BLEND_RGB_ADD)

    def _in_shed(self, tv):
        """Parkeret inde i sit maskinhus (tegnes ikke – vælg den via maskinhuset). Står den udenfor, ses den.
        Biler i garagen tegnes heller ikke (højreklik på garagen)."""
        if len(tv) > 13 and tv[13] == 3 and tv[7] in ("home", "parked"):
            return True
        if not (tv[7] in ("home", "repair") and vkind(tv[6]) != "car" and
                abs(tv[2] - tv[8][0]) < 0.01 and abs(tv[3] - tv[8][1]) < 0.01):
            return False
        return not (len(tv) > 13 and tv[13] == 2)

    def _buy_to_shed(self, shed):
        self.cat_shed = list(shed)
        self.catalog, self.bpop = {"cat": 1, "i": 0}, None

    def start_driving(self, vid):
        self.client.send({"a": "drive", "id": vid, "on": True})
        self.driving, self.steer, self.bpop, self.tool = vid, (0, 0), None, "inspect"
        self._drive_seen, self._drive_t, self.local = False, self.t, None
        self._slow_start()

    def stop_driving(self):
        if self.driving is not None:
            self.client.send({"a": "drive", "id": self.driving, "on": False})
        self.driving, self.local = None, None
        self._slow_end()

    def _slow_start(self):
        """Sæt dig bag rattet: tiden går ned på ½, så man kan nå at køre (husk tempoet fra før).
        I multiplayer bliver det din stemme i tempo-afstemningen."""
        if self.slow_prev is not None or not self.app.cfg.get("slowdrive", True):
            return                                   # allerede sat ned (fx Tab til næste maskine)
        sp = self.st.speed
        if sp in (1, 2, 3):
            self.slow_prev = sp
            self.client.send({"a": "speed", "v": 4})
            if not getattr(self, "_slow_told", False):
                self._slow_told = True
                self.log.append(("Tiden går i ½ tempo, mens du kører – Esc giver tilbage og skruer op igen. "
                                 "(Kan slås fra under Menu › Vejr og indstillinger.)", "info"))

    def _slow_end(self):
        """Stå ud (Esc): tilbage til tempoet fra før – medmindre du selv har skiftet tempo undervejs."""
        prev, self.slow_prev = self.slow_prev, None
        if prev is not None and self.st.speed == 4 and not self.st.vote:
            self.client.send({"a": "speed", "v": prev})

    def _predict(self, me, steer, dt):
        """Kør min egen maskine lokalt (samme fysik som serveren) og send positionen – så styringen er glat,
        også over netværket. Serveren tjekker og overtager, hvis noget ikke passer."""
        L = self.local
        if L is None or abs(L["tr"]["x"] - me[2]) + abs(L["tr"]["y"] - me[3]) > 3.5:
            cx, cy = VDIRS[me[4] % 8]
            L = self.local = {"tr": {"k": me[6], "x": float(me[2]), "y": float(me[3]), "d": me[4]},
                              "m": {"thr": 0, "turn": 0, "v": 0.0, "hdg": math.atan2((cx + cy) * HALF_H,
                                                                                     (cx - cy) * HALF_W), "tool": None}}
        m = L["m"]
        m["thr"], m["turn"] = steer
        L["tr"]["upg"] = me[21] if len(me) > 21 else []
        L["tr"]["o"] = me[1]
        if len(me) > 29 and me[29]:
            L["tr"]["fuel"] = me[29][0]
        gps = bool(me[22]) if len(me) > 22 else False
        if gps != bool(m.get("gps")):
            m.update(gps=gps, cruise_off=False, gps_stop=False, gps_side=None, uturn=None)
        m["tool"] = me[20] if len(me) > 20 else (me[9] if me[9] in WORK_TIME else None)
        self.st.kinematics(L["tr"], m, min(dt, 0.1))
        tr = L["tr"]
        me[2], me[3], me[4], me[10] = tr["x"], tr["y"], tr["d"], m["v"]
        self.trac[me[0]] = [tr["x"], tr["y"]]
        self.pos_t += dt
        if self.pos_t >= 0.05 and (abs(m["v"]) > 0.01 or L.get("sent") != (tr["x"], tr["y"], m["v"])):
            self.pos_t = 0.0
            L["sent"] = (tr["x"], tr["y"], m["v"])
            self.client.send({"a": "pos", "id": me[0], "x": round(tr["x"], 3), "y": round(tr["y"], 3),
                              "hdg": round(m["hdg"], 4), "v": round(m["v"], 3)})

    def cycle_vehicle(self):
        """Tab: skift til næste af mine maskiner (Styr selv)."""
        mine = sorted((v for v in self.st.tractor_view if v[1] == self.me and vkind(v[6]) != "car"
                       and not VEHICLES.get(v[6], {}).get("hidden") and v[7] != "repair"
                       and not (v[7] == "manual" and len(v) > 14 and v[14] != self.drv)), key=lambda v: v[0])
        if not mine:
            self.log.append(("Du har ingen ledige maskiner at køre.", "warn"))
            return
        ids = [v[0] for v in mine]
        nxt = ids[(ids.index(self.driving) + 1) % len(ids)] if self.driving in ids else ids[0]
        if nxt != self.driving:
            if self.driving is not None:
                self.client.send({"a": "drive", "id": self.driving, "on": False})
            self.start_driving(nxt)

    def work_tool(self, v):
        """Hvad der sker, når man sænker: det afhænger af, hvad der er koblet på (eller skærebordet på mejetærskeren)."""
        kind = vkind(v[6])
        if kind == "combine":
            return "harvest"
        if kind == "truck" and self.st.snow >= 0.3 and view_plow(v):
            return "snow"                             # lastbil med sneplov
        if VEHICLES.get(v[6], {}).get("mower"):
            return "mow"                              # havetraktorens klipper under bugen
        if kind == "smaa" and self.st.snow >= 0.3 and view_plow(v):
            return "snow"                             # ATV/UTV/terrænbil med sneblad
        if kind != "tractor":
            return None
        if self.st.snow >= 0.3 and view_plow(v):
            return "snow"                             # traktor med sneplov-opgradering foran
        h = (v[19] if len(v) > 19 else None) or ""
        imp = GEAR_IMP.get(h[2:]) if h.startswith("e:") else None
        if imp in ("gylle", "gylle_s"):
            return "fertilize"                        # gyllevognen kører gylle ud
        if imp == "potato":
            return "harvest"                          # kartoffeloptageren
        if imp == "harrow":
            return "plow"                             # stubharven behandler stubmarken
        if imp == "fertilize":
            return getattr(self, "spread", "fertilize")
        if imp in ("plow", "sow", "spray", "fell", "water"):
            return imp
        if not h and self.st.snow >= 0.3 and "sneplov" in (self.my() or {}).get("equip", []):
            return "snow"                             # sneploven sidder foran – den kan bruges uden redskab bagpå
        if not h and self.st._is_orchard((int(round(v[2])), int(round(v[3])))):
            return "harvest"                          # frugtplukning i plantagen
        return None

    def toggle_implement(self):
        v = next((t for t in self.st.tractor_view if t[0] == self.driving), None)
        if not v:
            return
        cur = v[20] if len(v) > 20 else None
        if cur:
            self.set_implement(None)
        else:
            tool = self.work_tool(v)
            if tool:
                self.set_implement(tool)

    def set_implement(self, tool):
        v = next((t for t in self.st.tractor_view if t[0] == self.driving), None)
        if not v or (tool and tool not in self.st.manual_tools(vkind(v[6])) and
                     not (tool == "mow" and VEHICLES.get(v[6], {}).get("mower")) and
                     not (tool == "snow" and view_plow(v))):
            return
        self.client.send({"a": "implement", "id": self.driving, "tool": tool, "crop": self.crop})

    def cycle_overlay(self):
        order = [False, "moist", "soil", "weeds", "lime"]
        self.overlay = order[(order.index(self.overlay) + 1) % len(order)]

    def _right_click(self, pos):
        veh = self._vehicle_at(pos)
        if veh:
            self.bpop = {"veh": veh[0], "at": pos}
            return
        x, y = self._tile_at(pos)
        t = self.st.tiles[y][x]
        if t.b == "jagthytte":
            self.bpop = {"hut": (x, y), "at": pos}
        elif t.b in ("ext:garage", "ext:dobbeltgarage") and t.o == self.me:
            self.bpop = {"garage": tuple(self.st.anchor(x, y)[:2]), "at": pos}
        elif t.b == "gaard" or (t.b or "").startswith("ext:"):
            if t.o >= 0 and t.o in self.st.players:
                self.bpop = {"house": t.o, "at": pos}
        elif t.b in BUILDINGS:
            ax, ay, _, _ = self.st.anchor(x, y)
            self.bpop = {"pos": (ax, ay), "at": pos}
        elif t.b == "kvaegtorv":
            self.bpop = {"torv": True, "at": pos}
        elif t.b == "grovvare":
            self.bpop = {"grovvare": True, "at": pos}
        elif t.b == "jagtbutik":
            self.bpop = {"jagt": True, "at": pos}
        elif t.b and t.b.startswith(("site:", "proj:")):
            self.tab = "faelles"
        elif t.t == "town" or t.b in TOWN_BNAMES:
            self.townwin, self.bpop = True, None
        elif t.o == self.me and t.t in ("field", "stub") and self.st.field_key(self.me, x, y):
            self.bpop = None
            self.fplanwin = {"key": self.st.field_key(self.me, x, y), "xy": (x, y)}
        else:
            self.bpop = None
            self.tool = "inspect"

    def _sel_ok(self, x, y, t):
        if self.tool == "jagthytte":                  # egen jord – eller statsskov (skov uden ejer)
            return self.st.hut_site(self.me, x, y)[0] is not None
        if self.tool in BUILDINGS:
            return t.o == self.me and not t.b and not t.crop and t.t in ("grass", "field", "stub", "plaene")
        if self.placing():                            # hus og tilbygninger: også grus (gårdspladsen)
            if self.tool.startswith("house:") and t.b == "gaard" and t.o == self.me:
                return True
            return t.o == self.me and not t.b and not t.crop and t.t in ("grass", "field", "stub", "gravel", "fliser")
        if self.tool == "buyland":
            return t.o < 0 and t.t not in PUBLIC_T and not t.b
        return t.o == self.me

    # ── opdatering ───────────────────────────────────────────────────────────
    def update(self, dt):
        self.t += dt
        if self.st is not None and self.st.speed:
            self.night_t = getattr(self, "night_t", 0.0) + dt   # døgnet går kun, mens spillet kører
        if self.st is not None and abs(getattr(self, "night_t", 0.0) - getattr(self.st, "clock", 0.0)) > 3:
            self.night_t = getattr(self.st, "clock", 0.0)          # følg serverens ur: samme nat for alle
        for msg in self.client.drain():
            k = msg.get("k")
            if k == "welcome":
                self.st = GameState.from_full(msg["state"])
                lvl = self.st.town.get("lvl", 0)
                self.traffic_lvl = lvl
                self.traffic = TownTraffic(self.st, 12 + 5 * lvl, margin=3 + 2 * lvl)
                self.seen_hist = len(self.my().get("hist", [])) if self.my() else 0
                self.me, self.title = msg["you"], msg.get("title", "")
                self.drv = msg.get("drv")
                self.single = msg.get("single", self.single)
                self.center_on(*self.my()["home"])
                if self.st.manual_mode():
                    self.log.append(("Velkommen! Du kører selv: højreklik på traktoren og vælg Styr selv (eller tryk "
                                     "Tab). Træk med Pløj, Så osv. for at planlægge markerne. F1 = hjælp.", "big"))
                else:
                    self.log.append(("Velkommen! Tryk F1 for hjælp. Pløj, så og høst – traktoren kører ud og gør "
                                     "arbejdet.", "big"))
            elif k == "delta" and self.st:
                self.st.apply_tiles(msg["tiles"])
                self.st.apply_meta(msg["meta"])
            elif k == "mv" and self.st:
                rows = {r[0]: r for r in self.st.tractor_view}
                for vid, x, y, d, v in msg["v"]:
                    r = rows.get(vid)
                    if r and vid != self.driving:
                        r[2], r[3], r[4], r[10] = x, y, d, v
            elif k == "log":
                self.log.append((msg["t"], msg.get("c", "info")))
                if msg.get("c") == "good" and ("(+" in msg["t"] or msg["t"].startswith("Solgte")):
                    self.app.sfx.play("cash", 0.5)
            elif k == "err":
                if self.st is None:
                    self.leave(msg["t"])
                    return
                self.log.append((msg["t"], "err"))
            elif k == "disconnected":
                if self.st is None:
                    self.leave("Forbindelsen blev afvist eller afbrudt.")
                    return
                self.lost = "Forbindelsen til værten blev afbrudt."
        if self.st is None:
            return
        lvl = self.st.town.get("lvl", 0)
        if lvl != getattr(self, "traffic_lvl", 0):
            self.traffic_lvl = lvl
            self.traffic = TownTraffic(self.st, 12 + 5 * lvl, margin=3 + 2 * lvl)
        nh = len(self.my().get("hist", [])) if self.my() else 0
        if nh > getattr(self, "seen_hist", nh) and not self.driving:
            self.report = {"sel": nh - 1}
        self.seen_hist = nh
        news = self.st.news
        if self.news_seen is None:
            self.news_seen = news[-1]["id"] if news else 0
        elif news and news[-1]["id"] > self.news_seen and any(n["big"] and n["id"] > self.news_seen for n in news) \
                and not self.driving and not self.menu and not self.report:
            self.paper = True
        if self.paper and news:
            self.news_seen = news[-1]["id"]
        sh = self.st.show
        if sh and sh.get("year") == self.st.year() and not self.driving and not self.menu and not self.report:
            e = sh.get("entries", {}).get(str(self.me), {})
            key = (sh["year"], sh["stage"])
            if self.show_seen != key and ((sh["stage"] == "invite" and e.get("ok") is None) or
                                          (sh["stage"] == "done" and e.get("ok") and not sh.get("home"))):
                self.show_seen = key
                self.showwin, self.paper = True, False
        pl = self.st.pull
        if pl and pl.get("year") == self.st.year() and not self.driving and not self.menu and not self.report:
            e = pl.get("entries", {}).get(str(self.me), {})
            key = (pl["year"], pl["stage"])
            if self.pull_seen != key and ((pl["stage"] == "invite" and e.get("ok") is None) or
                                          (pl["stage"] == "done" and e.get("ok"))):
                self.pull_seen = key
                self.pullwin, self.paper = True, False
        self.fx.update(dt, self.st.weather)
        me = next((t for t in self.st.tractor_view if t[0] == self.driving), None) if self.driving else None
        view = self.view_rect()
        working = 0
        for tv in self.st.tractor_view:
            if tv[7] not in ("home", "repair") and not self._in_shed(tv):
                x_, y_ = self.trac.get(tv[0], tv[2:4])
                sx_ = view.x - self.cam[0] + (x_ - y_) * HALF_W * self.z
                sy_ = view.y - self.cam[1] + (x_ + y_) * HALF_H * self.z
                working += view.collidepoint(sx_, sy_)
        cows_vis = self.z >= 1 and any(q["cows"] for q in self.st.players.values())
        self.app.sfx.update(dt, self.fx, self.st.weather, self.st.month(),
                            speed=(me[10] if me and len(me) > 10 else None), working=working,
                            cows=cows_vis and bool(getattr(self, "_cows_on_screen", False)),
                            hungry=bool((self.my() or {}).get("hungry")) and
                            any((self.my() or {}).get(k, 0) for k in ("cows", "sheep")))
        self.traffic.update(dt)
        # glid maskinerne mod serverens position: positionerne gemmes med ankomsttid, og maskinen vises,
        # hvor den var for VIS_DELAY sekunder siden (lineært mellem to positioner). Så kører en hurtig lastbil
        # glat, selvom beskederne fra serveren kommer lidt ujævnt.
        seen = set()
        now_ = time.time()
        tri = self.__dict__.setdefault("_tri", {})
        trd = self.__dict__.setdefault("_trd", {})       # vist retning (følger den forsinkede position)
        rt = now_ - self.VIS_DELAY
        for tr in self.st.tractor_view:
            tid = tr[0]
            seen.add(tid)
            cur = self.trac.get(tid)
            if cur is None or abs(cur[0] - tr[2]) + abs(cur[1] - tr[3]) > 14 or \
                    (tr[7] in ("home", "repair") and abs(cur[0] - tr[2]) + abs(cur[1] - tr[3]) > 3):
                self.trac[tid] = [tr[2], tr[3]]
                tri[tid] = [(now_ - 1.0, tr[2], tr[3], tr[4])]
                trd.pop(tid, None)
                continue
            if tr[7] == "manual":
                f = min(1.0, dt * 16)
                cur[0] += (tr[2] - cur[0]) * f
                cur[1] += (tr[3] - cur[1]) * f
                tri.pop(tid, None)
                trd.pop(tid, None)
                continue
            hs = tri.get(tid)
            if not hs:
                hs = tri[tid] = [(now_ - 1.0, cur[0], cur[1], tr[4])]
            if (hs[-1][1], hs[-1][2]) != (tr[2], tr[3]):          # ny position fra serveren
                if now_ - hs[-1][0] > 0.3:                         # holdt stille: kør fra hvor den stod
                    hs.append((now_ - 0.06, hs[-1][1], hs[-1][2], tr[4]))
                t0_, x0_, y0_, d0_ = hs[-1]
                x1_, y1_ = tr[2], tr[3]
                if abs(x1_ - x0_) > 0.01 and abs(y1_ - y0_) > 0.01:
                    # maskinerne kører fra felt til felt langs akserne – har den drejet siden sidst, så tag
                    # hjørnet med, så den ikke ser ud til at skære hen over marken ved et vejkryds
                    on = lambda v: abs(v - round(v)) < 0.02
                    cx_ = cy_ = None
                    if on(y0_) and on(x1_):
                        cx_, cy_ = round(x1_), y0_
                    elif on(x0_) and on(y1_):
                        cx_, cy_ = x0_, round(y1_)
                    if cx_ is not None:
                        d1 = abs(cx_ - x0_) + abs(cy_ - y0_)
                        d2 = abs(x1_ - cx_) + abs(y1_ - cy_)
                        tc = t0_ + (now_ - t0_) * d1 / max(1e-6, d1 + d2)
                        hs.append((tc, cx_, cy_, d0_))
                hs.append((now_, tr[2], tr[3], tr[4]))
                while len(hs) > 2 and hs[1][0] <= rt:
                    hs.pop(0)
            if rt <= hs[0][0]:
                cur[0], cur[1] = hs[0][1], hs[0][2]
                trd[tid] = hs[0][3]
            elif rt >= hs[-1][0]:
                cur[0], cur[1] = hs[-1][1], hs[-1][2]
                trd.pop(tid, None)
            else:
                for (t0, x0, y0, d0), (t1, x1, y1, _d1) in zip(hs, hs[1:]):
                    if t0 <= rt <= t1:
                        k = (rt - t0) / max(1e-6, t1 - t0)
                        cur[0], cur[1] = x0 + (x1 - x0) * k, y0 + (y1 - y0) * k
                        dx_, dy_ = x1 - x0, y1 - y0
                        if abs(dx_) + abs(dy_) > 1e-4:         # retningen passer til stykket, den kører
                            trd[tid] = (0 if dx_ > 0 else 4) if abs(dx_) >= abs(dy_) else (2 if dy_ > 0 else 6)
                        else:
                            trd[tid] = _d1
                        break
        for tid in list(self.trac):
            if tid not in seen:
                del self.trac[tid]
                tri.pop(tid, None)
                trd.pop(tid, None)
        if self.driving is not None:
            me = next((t for t in self.st.tractor_view if t[0] == self.driving), None)
            mine = me is not None and me[7] == "manual" and (len(me) < 15 or me[14] == self.drv)
            if not me or (not mine and (getattr(self, "_drive_seen", False) or self.t - self._drive_t > 3)):
                self.driving, self.local = None, None
                self._slow_end()
                return
            if mine:
                self._drive_seen = True
            keys = pygame.key.get_pressed()
            steer = (0, 0)       # (gas, rat)
            if self.pullgame:
                self._pull_tick(dt, keys)
            elif self.chat is None and not self.menu and not self.catalog:
                thr = (1 if keys[pygame.K_UP] or keys[pygame.K_w] else 0) - \
                      (1 if keys[pygame.K_DOWN] or keys[pygame.K_s] else 0)
                turn = (1 if keys[pygame.K_RIGHT] or keys[pygame.K_d] else 0) - \
                       (1 if keys[pygame.K_LEFT] or keys[pygame.K_a] else 0)
                steer = (thr, turn)
            if steer != self.steer:
                self.steer = steer
                self.client.send({"a": "steer", "id": self.driving, "thr": steer[0], "turn": steer[1]})
            if mine:
                self._predict(me, steer, dt)
            if me:
                x, y = self.trac.get(me[0], me[2:4])
                v = self.view_rect()
                wx, wy = (x - y) * HALF_W * self.z, (x + y + 1) * HALF_H * self.z - self._lift(x, y)
                tx, ty = wx - v.w / 2, wy - v.h / 2
                f = min(1.0, dt * 6)
                self.cam = [self.cam[0] + (tx - self.cam[0]) * f, self.cam[1] + (ty - self.cam[1]) * f]
            return
        if self.chat is not None or self.catalog:
            return
        keys = pygame.key.get_pressed()
        sp = 900 * dt
        if keys[pygame.K_a] or keys[pygame.K_LEFT]:
            self.cam[0] -= sp
        if keys[pygame.K_d] or keys[pygame.K_RIGHT]:
            self.cam[0] += sp
        if keys[pygame.K_w] or keys[pygame.K_UP]:
            self.cam[1] -= sp
        if keys[pygame.K_s] or keys[pygame.K_DOWN]:
            self.cam[1] += sp
        v = self.view_rect()
        z = self.z
        self.cam[0] = clamp(self.cam[0], -MAP_H * HALF_W * z - v.w / 2, MAP_W * HALF_W * z - v.w / 2)
        self.cam[1] = clamp(self.cam[1], -v.h / 2, (MAP_W + MAP_H) * HALF_H * z - v.h / 2)

    # ── tegning ──────────────────────────────────────────────────────────────
    def draw(self, screen):
        _UIMAP["on"], _UIMAP["screen"] = False, screen    # kortet tegnes altid i sine egne farver
        ui = self.ui
        W, H = screen.get_size()
        screen.fill(C_BG)
        if self.st is None:
            ui.text(screen, "Forbinder …", (W // 2, H // 2), 32, C_TEXT, center=True)
            if ui.button(screen, (W // 2 - 70, H // 2 + 40, 140, 36), "Annullér"):
                self.leave()
            return
        st, p = self.st, self.my()
        view = self.view_rect()
        mp = ui.mouse
        self.hover = self._tile_at(mp) if view.collidepoint(mp) and not self.menu \
            and not self.guide_rect.collidepoint(mp) \
            and not self.mini_rect.collidepoint(mp) and not self.popup_rect.collidepoint(mp) \
            and not (self.bpop and self.bpop_rect.collidepoint(mp)) \
            and not (self.catalog and self.cat_rect.collidepoint(mp)) \
            else None
        sel = None
        if self.placing() and self.hover:
            w, h = self.footprint()
            sel = (self.hover[0], self.hover[1], self.hover[0] + w - 1, self.hover[1] + h - 1)
        elif self.drag is not None and self.hover and self.tool != "inspect":
            b = self.hover
            sel = (min(self.drag[0], b[0]), min(self.drag[1], b[1]), max(self.drag[0], b[0]),
                   max(self.drag[1], b[1]))
        elif self.hover and self.tool != "inspect":
            sel = (*self.hover, *self.hover)
        labels = {q["id"]: (q["name"], PLAYER_COLORS[q["id"] % len(PLAYER_COLORS)], q["connected"] or bool(q.get("ai")),
                            *q["home"])
                  for q in st.players.values()}
        lifts = self._loader_lifts()
        trd = getattr(self, "_trd", {})
        tractors = [[tr[0], tr[1], *self.trac.get(tr[0], tr[2:4]), trd.get(tr[0], tr[4]), tr[5], tr[6], tr[9], True,
                     tuple(tr[31]) if len(tr) > 31 and tr[31] else tr[11] if len(tr) > 11 else 0,
                     int(round(lifts[tr[0]] * 8)) if tr[0] in lifts else False,
                     (0 if tr[23] < 25 else 1 if tr[23] < 60 else 2) if len(tr) > 23 else 0,
                     ((tr[28][1]["g"] == "wrap", lifts.get(tr[0], 0.45),
                       max(1, int(round(tr[28][1]["n"] / bale_unit(tr[28][1]["g"], tr[28][1].get("s"))))),
                       tr[28][1].get("s") or "rund")
                      if len(tr) > 28 and tr[28] and tr[28][1] else None),
                     len(tr) > 21 and bool({"tvilling", "bredklip", "terraendaek"} & set(tr[21] or [])),
                     (tr[29][0] / max(1, tr[29][1])) if len(tr) > 29 and tr[29] and tr[1] == self.me else None,
                     view_plow(tr)]
                    for tr in st.tractor_view if not self._in_shed(tr)] + self.traffic.view() + self._pull_display()
        sel_cells = None
        if (self.tool in LINE_TOOLS or self.tool == "hegn") and self.hover:
            a = self.drag if self.drag is not None else self.hover
            sel_cells = set(line_cells(a[0], a[1], self.hover[0], self.hover[1]))
        marks = {(c[0], c[1]) for j in p["jobs"] for c in j["tiles"]} if p else None
        of_ = (p or {}).get("town_offer")
        if of_ and of_.get("until", -1) >= st.day and getattr(self, "mark_cells", None):
            marks = (marks or set()) | self.mark_cells       # kommunens bud: vis hvilken jord det gælder
        cows = {}
        for q in st.players.values():
            cows.update(st.fold_use(q))
        self._cows_on_screen = self.z >= 1 and any(
            view.collidepoint(view.x - self.cam[0] + (cx_ - cy_) * HALF_W * self.z,
                              view.y - self.cam[1] + (cx_ + cy_) * HALF_H * self.z) for cx_, cy_ in cows)
        draw_world(screen, self.art, st, self.cam, view, self.t, ui.font(20), labels, self.overlay,
                   self.hover, sel, self._sel_ok, tractors, marks, sel_cells, self.z, cows,
                   self.app.cfg.get("skel", "hegn"), self.tool not in ("inspect", None), self._ghost())
        if self.app.cfg.get("night", False):
            self._night(screen, view, tractors)
        self._field_labels(screen, view)
        sh = st.show
        if sh and sh.get("year") == st.year() and st.month() == SHOW_MONTH and SHOW_OPEN <= st.dom() <= SHOW_END:
            def scr(tx_, ty_):
                return (view.x - self.cam[0] + (tx_ - ty_) * HALF_W * self.z,
                        view.y - self.cam[1] + (tx_ + ty_ + 1) * HALF_H * self.z - self._lift(tx_, ty_))
            gx, gy = SHOW_POS
            pts = [scr(gx - 1.2, gy - 1.2), scr(gx + 1.2, gy - 1.2), scr(gx + 1.2, gy + 1.2), scr(gx - 1.2, gy + 1.2)]
            for a, b in zip(pts, pts[1:] + pts[:1]):        # flagranke rundt om kvægtorvet
                a2, b2 = (a[0], a[1] - 22 * self.z), (b[0], b[1] - 22 * self.z)
                pygame.draw.line(screen, (60, 50, 40), a2, b2, 1)
                for i in range(6):
                    fx = a2[0] + (b2[0] - a2[0]) * (i + 0.5) / 6
                    fy = a2[1] + (b2[1] - a2[1]) * (i + 0.5) / 6
                    col = ((220, 60, 50), (240, 210, 70), (60, 120, 200))[i % 3]
                    w_ = 3 * self.z
                    pygame.draw.polygon(screen, col, [(fx - w_, fy), (fx + w_, fy), (fx, fy + 6 * self.z)])
            cx_, cy_ = scr(gx, gy)
            if view.collidepoint(cx_, cy_):
                ui.text(screen, "DYRSKUE", (int(cx_), int(cy_ - 70 * self.z)), 20, (250, 230, 120), center=True)
            k_ = 0
            for q in st.players.values():
                for kind, n in q.get("at_show", {}).items():
                    spr0 = {"cows": self.art.cow, "sheep": self.art.sheep, "horses": self.art.horse}.get(kind)
                    for i in range(min(n, 5)):
                        if not spr0:
                            break
                        ox_, oy_ = [(-0.7, 0.3), (0.3, -0.7), (0.6, 0.5), (-0.3, -0.2), (0.1, 0.8), (0.8, -0.1)][k_ % 6]
                        k_ += 1
                        px_, py_ = scr(gx + ox_, gy + oy_)
                        spr = self.art.z(spr0[i % 2], self.z)
                        screen.blit(spr, (int(px_ - spr.get_width() / 2), int(py_ - spr.get_height())))
        if st.pull_open() and PULL_AREA:      # traktortræk-banen: slæde ved start, flagranke og skilt
            self._pull_event_draw(screen, view)
        elif st.pull_open():                  # traktortræk på festpladsen (ældre spil): bane, slæde og skilt
            def scr2(tx_, ty_):
                return (view.x - self.cam[0] + (tx_ - ty_) * HALF_W * self.z,
                        view.y - self.cam[1] + (tx_ + ty_ + 1) * HALF_H * self.z - self._lift(tx_, ty_))
            gx, gy = PULL_POS
            a_, b_ = scr2(gx - 3.5, gy + 2.2), scr2(gx + 3.5, gy + 2.2)
            c_, d_ = scr2(gx + 3.5, gy + 3.0), scr2(gx - 3.5, gy + 3.0)
            pygame.draw.polygon(screen, (132, 100, 64), [a_, b_, c_, d_])
            sx_, sy_ = scr2(gx + 2.6, gy + 2.6)
            z_ = self.z
            pygame.draw.rect(screen, (200, 170, 50), (int(sx_ - 9 * z_), int(sy_ - 12 * z_), int(18 * z_), int(8 * z_)))
            pygame.draw.rect(screen, (70, 70, 76), (int(sx_ - 10 * z_), int(sy_ - 5 * z_), int(20 * z_), int(5 * z_)))
            cx_, cy_ = scr2(gx, gy + 2.6)
            if view.collidepoint(cx_, cy_):
                ui.text(screen, "TRAKTORTRÆK", (int(cx_), int(cy_ - 40 * z_)), 20, (250, 200, 120), center=True)
        for tv in st.tractor_view:            # vildt, der er kommet frem ved skovkanten
            act = tv[18] if len(tv) > 18 else None
            if tv[7] == "manual" and act and act.get("g") and tv[1] == self.me:
                gx, gy = act["pos"]
                spr = self.art.z(self.art.game[act["g"]], self.z)
                sx_ = view.x - self.cam[0] + (gx - gy) * HALF_W * self.z
                sy_ = view.y - self.cam[1] + (gx + gy + 1) * HALF_H * self.z - self._lift(gx, gy)
                bob = abs(math.sin(self.t * 5)) * 2 * self.z
                screen.blit(spr, (int(sx_ - spr.get_width() / 2), int(sy_ - spr.get_height() - bob)))
                ui.text(screen, "!", (int(sx_), int(sy_ - spr.get_height() - 18 * self.z)), 26, C_WARN, center=True)
        if st.shared():                       # hvem kører hvad på den fælles gård
            for tv in st.tractor_view:
                if tv[7] == "manual" and len(tv) > 15 and tv[15]:
                    x_, y_ = self.trac.get(tv[0], tv[2:4])
                    sx_ = view.x - self.cam[0] + (x_ - y_) * HALF_W * self.z
                    sy_ = view.y - self.cam[1] + (x_ + y_) * HALF_H * self.z - 30 * self.z - self._lift(x_, y_)
                    if view.collidepoint(sx_, sy_):
                        lab = ui.font(15).render(tv[15], True, C_TEXT)
                        bg = lab.get_rect(center=(sx_, sy_)).inflate(8, 4)
                        pygame.draw.rect(screen, (30, 26, 21), bg, border_radius=4)
                        pygame.draw.rect(screen, C_ACC if tv[14] == self.drv else C_EDGE, bg, 1, border_radius=4)
                        screen.blit(lab, lab.get_rect(center=bg.center))
        if self.app.cfg.get("weatherfx", True):
            self.fx.draw(screen, view, self.cam, self.z)
        _UIMAP["on"] = True                              # herfra tegnes menuer og vinduer (kan farves om)
        self._minimap(screen, view)
        self._guide_panel(screen, view)
        if self.bpop:
            if "veh" in self.bpop:
                self._vehicle_popup(screen, view)
            elif "house" in self.bpop:
                self._house_popup(screen, view)
            elif "garage" in self.bpop:
                self._garage_popup(screen, view)
            elif "hut" in self.bpop:
                self._hut_popup(screen, view)
            elif "torv" in self.bpop:
                self._torv_popup(screen, view)
            elif "grovvare" in self.bpop:
                self._grovvare_popup(screen, view)
            elif "jagt" in self.bpop:
                self._jagt_popup(screen, view)
            else:
                self._building_popup(screen, view)
        if self.driving:
            self._scaled(self._drive_hud, screen, view)
        if self.tool == "sow":
            self._crop_popup(screen, view)
        else:
            self.crop_open = True                            # næste gang Så vælges, vises afgrøderne igen
        if self.tool == "fertilize" and self.my():
            self._fert_popup(screen, view)
        if self.tool == "plow" and self.my() and self.st.owns_tool(self.my(), "harrow"):
            self._plow_popup(screen, view)
        if self.tool == "sow":
            pass
        elif self.tool == "hegn":
            self._fence_popup(screen, view)
        elif any(self.tool in [g[0] for g in grp] for grp in TOOL_GROUPS.values()):
            self._group_popup(screen, view)
        elif self.tool not in ("fertilize", "plow"):
            self.popup_rect = pygame.Rect(0, 0, 0, 0)
        if self.drag is not None and self.hover and self.tool not in ("inspect",) and not self.placing():
            self._drag_preview(screen, view)
        elif self.hover:
            self._scaled(self._tile_tooltip, screen, view)
        if self.catalog:
            self._scaled_fit(self._catalog_window, 700, 500, view.w - 16, view.h - 8, screen, view)
        self._topbar(screen, W)
        self.ui.bump = SIDE_FONT_BUMP                  # lidt større skrift i menuerne i siderne
        try:
            self._toolbar(screen, H)
            self._scaled(self._panel, screen, W, H)
        finally:
            self.ui.bump = 0
        self._scaled(self._logbox, screen, W, H)
        if self.townwin:
            self._town_window(screen, W, H)
        if self.report:
            self._scaled_fit(self._report_window, 1000, 680, W - 40, H - 40, screen, W, H)
        if self.paper:
            self._scaled(self._paper_window, screen, W, H)
        if self.showwin:
            self._show_window(screen, W, H)
        if self.pullwin:
            self._pull_window(screen, W, H)
        if getattr(self, "hostwin", False):
            self._host_window(screen, W, H)
        if getattr(self, "demo", None):
            self._scaled(self._demolish_window, screen, W, H)
        if self.fedit is not None and self.fedit.get("key") == "farmname":
            self._scaled(self._farm_name_window, screen, W, H)
        if self.bankwin:
            self._scaled_fit(self._bank_window, 620, 412, W - 40, H - 40, screen, W, H)
        if self.ms_pick:
            self._ms_window(screen, W, H)
        if self.pullgame:                                # traktortrækkets bane skal beholde sine jordfarver
            _UIMAP["on"] = False
            self._pull_draw(screen, W, H)
            _UIMAP["on"] = True
        if self.fieldwin:
            self._field_window(screen, W, H)
        if self.fplanwin:
            self._fplan_window(screen, W, H)
        tip = getattr(self, "_tooltip", None)
        if tip and not self.menu and self.drag is None:
            self._scaled(self._draw_tooltip, screen, tip)
        if self.menu:
            self._scaled_fit(self._menu, 760, 620, W - 20, H - 20, screen, W, H)
        if self.lost:
            self._modal(screen, W, H, self.lost, "Tilbage til menuen", self.leave)
        _UIMAP["on"] = False

    def _draw_tooltip(self, s, tip):
        """Forklaring ved musen, når den holdes over et værktøj i venstre side."""
        ui = self.ui
        title, price, desc, y = tip
        w = self._k(300)
        lines = ui.wrap(desc, 15, w - 20) if desc else []
        plines = ui.wrap(price, 16, w - 20) if price else []
        h = self._k(34) + self._k(19) * len(plines) + (self._k(4) if plines else 0) + self._k(17) * len(lines) + self._k(6)
        r = pygame.Rect(TOOLBAR_W + 6, y, w, h)
        r.bottom = min(r.bottom, s.get_height() - 6)
        pygame.draw.rect(s, (30, 26, 22), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        pygame.draw.polygon(s, C_ACC, [(r.x, y + self._k(12)), (r.x - self._k(6), y + self._k(17)), (r.x, y + self._k(22))])
        ui.text(s, title, (r.x + self._k(10), r.y + self._k(7)), 19, C_ACC)
        yy = r.y + self._k(32)
        for ln in plines:
            ui.text(s, ln, (r.x + self._k(10), yy), 16, C_GOOD)
            yy += self._k(19)
        if plines:
            yy += self._k(4)
        for ln in lines:
            ui.text(s, ln, (r.x + self._k(10), yy), 15, C_TEXT)
            yy += self._k(17)

    STATE_NAMES = {"home": "Parkeret", "drive": "Kører", "plow": "Pløjer", "sow": "Sår", "harvest": "Høster",
                   "spray": "Sprøjter", "manual": "Styres af dig", "repair": "På værksted",
                   "haul_grain": "Kører høst hjem", "haul_animal": "Kører dyr", "haul_bales": "Henter halmballer",
                   "haul_out": "Kører solgte varer til byen", "haul_in": "Kører varer ud til gården",
                   "haul_milk": "Henter mælk", "fertilize": "Gøder", "lime": "Kalker", "fell": "Fælder skov",
                   "water": "Vander", "snow": "Rydder sne"}
    IMP_SHORT = {None: "Løft", "sow": "Så", "fertilize": "Gød", "fell": "Fæld", "spray": "Sprøjt", "harvest": "Høst",
                 "water": "Vand", "snow": "Plov"}
    IMP_NAMES = {None: "Løftet", "plow": "Plov", "sow": "Såmaskine", "harvest": "Høst", "spray": "Sprøjte",
                 "lime": "Kalk", "fell": "Skovvogn", "water": "Vandingsanlæg", "snow": "Sneplov",
                 "fertilize": "Gødning"}

    def _house_popup(self, s, view):
        ui, st = self.ui, self.st
        own = self.bpop["house"]
        q = st.players.get(own)
        if not q:
            self.bpop = None
            return
        mine = own == self.me
        lvl = q.get("house", 0)
        nrow = max(len(HOUSE_DESIGNS) - 2, len(ADDONS))
        r = pygame.Rect(self.bpop["at"][0] + 14, self.bpop["at"][1] - 20, min(800, view.w - 10) if mine else 420,
                        140 + nrow * 40 if mine else 130)
        r.clamp_ip(view)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, HOUSE_DESIGNS[house_design(q)]["navn"], (r.x + 12, r.y + 8), 24, C_ACC)
        ui.text(s, f"{q['name']}s gård · prestige {st.prestige(q)}", (r.x + 12, r.y + 32), 16,
                PLAYER_COLORS[own % len(PLAYER_COLORS)])
        if ui.button(s, (r.right - 30, r.y + 8, 22, 22), "X", size=16):
            self.bpop = None
            return
        y = r.y + 58
        pb = min(10, st.prestige(q)) * PRESTIGE_BONUS * 100
        ui.text(s, f"Prestige giver +{pb:.0f}% på alle salgspriser (højst +10%).", (r.x + 12, y), 16, C_DIM)
        y += 24
        if not mine:
            has = ", ".join(ADDONS[a]["navn"].lower() for a in q.get("addons", [])) or "ingen tilbygninger"
            ui.text(s, "Har: " + has, (r.x + 12, y), 16, C_TEXT)
            return
        cur = house_design(q)
        top = y
        hov = "Hold musen over et design for at læse om det."
        cr = r.x + r.w // 2 - 8                           # to spalter: design til venstre, tilbygninger til højre
        ui.text(s, "BYG OM – VÆLG DESIGN OG PLACÉR DET", (r.x + 12, y + 4), 16, C_ACC)
        y += 24
        for k, d in HOUSE_DESIGNS.items():
            if k == cur or k == "stuehus":
                continue
            dp = d["prestige"] - HOUSE_DESIGNS[cur]["prestige"]
            ui.text(s, d["navn"], (r.x + 12, y + 2), 18, C_TEXT)
            ui.text(s, f"{d['size'][0]}×{d['size'][1]} felter · {'+' if dp >= 0 else ''}{dp} prestige", (r.x + 12, y + 20),
                    14, C_DIM)
            if pygame.Rect(r.x + 6, y, cr - r.x - 118, 38).collidepoint(ui.mouse):
                hov = d["desc"]
            if ui.button(s, (cr - 106, y + 4, 100, 28), kr(d["cost"]), enabled=q["money"] >= d["cost"], size=16):
                self.tool, self.bpop = "house:" + k, None
                self.log.append((f"Placér {d['navn'].lower()} på din jord – klik, hvor den skal stå (Esc fortryder). "
                                 "Det gamle stuehus rives ned.", "info"))
                return
            y += 40
        ui.text(s, hov, (r.x + 12, r.bottom - 22), 14, C_DIM)
        y = top
        ui.text(s, "TILBYGNINGER – du vælger selv, hvor de skal stå", (cr + 16, y + 4), 16, C_ACC)
        y += 24
        pygame.draw.line(s, (70, 60, 50), (cr + 4, top + 4), (cr + 4, r.bottom - 30))
        for k, a in ADDONS.items():
            have = k in q.get("addons", [])
            extra = f" · +{a['prestige']} prestige" if a["prestige"] else ""
            if a.get("income"):
                extra += f" · +{a['income']} kr/md"
            ui.text(s, a["navn"], (cr + 16, y + 2), 18, C_GOOD if have else C_TEXT)
            ui.text(s, f"{a['size'][0]}×{a['size'][1]} felt{extra}", (cr + 16, y + 20), 14, C_DIM)
            if have:
                pos = self._addon_pos(k)
                if pos and ui.button(s, (r.right - 112, y + 4, 100, 28), f"Flyt {kr(st.move_cost('ext:' + k))}",
                                     enabled=q["money"] >= st.move_cost("ext:" + k) or st.sandbox(), size=15):
                    self.bpop = None
                    self.start_move(*pos)
                    return
                ui.text(s, "Bygget", (r.right - 120, y + 8), 17, C_GOOD, right=True)
                if k == "gaardbutik":
                    ui.text(s, f"kunder {int(st.shop_traffic(q) * 100)}%", (r.right - 190, y + 8), 14, C_DIM,
                            right=True)
            elif ui.button(s, (r.right - 112, y + 4, 100, 28), kr(a["cost"]), enabled=q["money"] >= a["cost"],
                           size=16):
                self.tool, self.bpop = "addon:" + k, None
                self.log.append((f"Placér {a['navn'].lower()} – klik, hvor den skal stå (Esc fortryder).", "info"))
                return
            y += 40

    def _hut_popup(self, s, view):
        ui, st = self.ui, self.st
        x, y = self.bpop["hut"]
        owner, h = st.hut_owner(x, y)
        r = pygame.Rect(self.bpop["at"][0] + 14, self.bpop["at"][1] - 20, 380, 210)
        r.clamp_ip(view)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, "Jagthytte", (r.x + 12, r.y + 8), 24, C_ACC)
        if ui.button(s, (r.right - 30, r.y + 8, 22, 22), "X", size=16):
            self.bpop = None
            return
        if not owner:
            ui.text(s, "Ingen ejer.", (r.x + 12, r.y + 40), 16, C_DIM)
            return
        state = h[2] == "state"
        ui.text(s, f"{owner['name']}s hytte" + (" i statsskoven" if state else " på egen jord"), (r.x + 12, r.y + 36),
                16, PLAYER_COLORS[owner["id"] % len(PLAYER_COLORS)])
        yy = r.y + 60
        for line in ui.wrap(f"Jagt inden for {HUT_RANGE} felter: hver {HUT_WAIT}. dag, oftere rådyr og vildsvin, "
                            "bedre skud og 20% mere vildt." + (f" Jagtleje {kr(HUT_LEASE)} pr. måned." if state else ""),
                            15, r.w - 24):
            ui.text(s, line, (r.x + 12, yy), 15, C_DIM)
            yy += 16
        it = f"h:{x},{y}"
        renters = [r_ for r_ in st.rentals if r_["item"] == it]
        if renters:
            ui.text(s, "Lejes af: " + ", ".join(f"{st.pname(r_['renter'])} ({max(0, r_['until'] - st.day)} d)"
                                               for r_ in renters), (r.x + 12, yy + 2), 15, C_GOOD)
        yy += 22
        offer = next((o for o in st.rent_offers if o["item"] == it), None)
        if owner["id"] == self.me:
            if offer:
                ui.text(s, f"Til leje for {kr(offer['price'])} pr. dag", (r.x + 12, yy + 4), 15, C_TEXT)
                if ui.button(s, (r.right - 112, yy, 100, 26), "Ikke til leje", size=14):
                    self.client.send({"a": "rent", "op": "unlist", "id": offer["id"]})
            elif ui.button(s, (r.x + 12, yy, 220, 26), f"Lej den ud ({kr(st.rent_item_price(it))}/dag)", size=14):
                self.client.send({"a": "rent", "op": "list", "item": it, "price": st.rent_item_price(it)})
            if ui.button(s, (r.x + 12, r.bottom - 38, 200, 28),
                         f"Sælg hytten (+{kr(BUILDINGS['jagthytte']['cost'] * 0.5)})", size=15):
                self.client.send({"a": "hutsell", "x": x, "y": y})
                self.bpop = None
        elif offer and not any(r_["renter"] == self.me for r_ in renters):
            ui.text(s, f"Til leje: {kr(offer['price'])} pr. dag", (r.x + 12, yy + 4), 15, C_TEXT)
            bw = (r.w - 32) // 3
            for i, d in enumerate(RENT_DAYS):
                if ui.button(s, (r.x + 12 + i * (bw + 4), r.bottom - 38, bw, 28), f"{d} dage · {kr(offer['price'] * d)}",
                             size=13):
                    self.client.send({"a": "rent", "op": "take", "id": offer["id"], "days": d})
        elif not offer:
            ui.text(s, "Ikke til leje lige nu.", (r.x + 12, yy + 4), 15, C_DIM)

    def _garage_popup(self, s, view):
        """Højreklik på garagen: hvilke biler holder her – kør en tur, se bilen eller køb en ny."""
        ui, st, p = self.ui, self.st, self.my()
        anchor = tuple(self.bpop["garage"])
        t = st.tiles[anchor[1]][anchor[0]] if st.inb(*anchor) else None
        if not p or not t or t.b not in ("ext:garage", "ext:dobbeltgarage"):
            self.bpop = None
            return
        key = t.b[4:]
        doors = st.garage_doors(p)
        cars = sorted((v for v in st.tractor_view if v[1] == self.me and vkind(v[6]) == "car"), key=lambda v: v[0])
        mine = [(i, d) for i, d in enumerate(doors) if tuple(d[1]) == anchor]
        nports = ADDONS[key]["size"][0]
        r = pygame.Rect(self.bpop["at"][0] + 14, self.bpop["at"][1] - 20, 400, 128 + 44 * nports)
        r.clamp_ip(view)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, ADDONS[key]["navn"], (r.x + 12, r.y + 8), 24, C_ACC)
        here = sum(1 for i, _ in mine if i < len(cars) and len(cars[i]) > 13 and cars[i][13] == 3)
        ui.text(s, f"{here} af {nports} pladser optaget", (r.x + 12, r.y + 34), 16, C_DIM)
        if ui.button(s, (r.right - 30, r.y + 8, 22, 22), "X", size=16):
            self.bpop = None
            return
        y = r.y + 60
        for n in range(nports):
            ui.text(s, f"Port {n + 1}" if nports > 1 else "Porten", (r.x + 12, y + 2), 15, C_DIM)
            slot = mine[n] if n < len(mine) else None
            v = cars[slot[0]] if slot and slot[0] < len(cars) else None
            if slot is None:
                ui.text(s, "Spærret – der står noget foran porten", (r.x + 80, y + 2), 15, C_WARN)
            elif v is None:
                ui.text(s, "Tom", (r.x + 80, y + 2), 17, C_TEXT)
                if ui.button(s, (r.right - 112, y, 100, 28), "Køb bil …", size=15):
                    cat = next(i for i, (nm, _) in enumerate(CATALOG) if nm == "Biler")
                    self.catalog, self.bpop = {"cat": cat, "i": 0}, None
                    return
            else:
                inside = len(v) > 13 and v[13] == 3
                ui.text(s, vname(v[6]), (r.x + 80, y), 17, C_TEXT)
                ui.text(s, "holder i garagen" if inside else
                        ("du kører den" if self.driving == v[0] else "er ude at køre"),
                        (r.x + 80, y + 18), 13, C_GOOD if inside else C_DIM)
                if self.driving == v[0]:
                    if ui.button(s, (r.right - 112, y, 100, 28), "Slip", active=True, size=15):
                        self.stop_driving()
                else:
                    if ui.button(s, (r.right - 112, y, 100, 28), "Styr selv", enabled=v[7] != "repair", size=15):
                        self.start_driving(v[0])
                        return
                if ui.button(s, (r.right - 170, y, 52, 28), "Vis", size=15):
                    self.bpop = {"veh": v[0], "at": self.bpop["at"]}
                    return
            y += 44
        extra = len(cars) - len(doors)
        if extra > 0:
            ui.text(s, f"{extra} bil{'er' if extra > 1 else ''} holder ved stuehuset – der er ikke garageplads.",
                    (r.x + 12, y + 2), 14, C_WARN)
        y = r.bottom - 40
        if ui.button(s, (r.x + 12, y, 150, 28), f"Flyt ({kr(st.move_cost(t.b))})", size=15):
            self.bpop = None
            self.start_move(*anchor)
            return
        if ui.button(s, (r.x + 170, y, 150, 28), "Stuehuset …", size=15):
            self.bpop = {"house": self.me, "at": self.bpop["at"]}

