    def _svc(self, key, wear):
        c = service_cost(key, wear)
        c = int(c * WINTER_SERVICE) if self.st.month() in PREORDER_MONTHS else c
        return int(c * 0.6) if self.st.workshop(self.my() or {"id": self.me}) else c

    def _jagt_popup(self, s, view):
        ui, st, p = self.ui, self.st, self.my()
        r = pygame.Rect(self.bpop["at"][0] + 14, self.bpop["at"][1] - 20, 470, 452)
        r.clamp_ip(view)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, "Jagtbutikken", (r.x + 12, r.y + 8), 24, C_ACC)
        if ui.button(s, (r.right - 30, r.y + 8, 22, 22), "X", size=16):
            self.bpop = None
            return
        gear = p.get("gear", {})
        y = r.y + 38
        jt = gear.get("jagttegn", -1)
        ui.text(s, f"Jagttegn gælder til {st.pdate(jt)}" if st.jagttegn_ok(p) else "Du har ikke et gyldigt jagttegn.",
                (r.x + 12, y), 16, C_GOOD if st.jagttegn_ok(p) else C_WARN)
        y += 22
        for key, g in GEAR.items():
            have = st.jagttegn_ok(p) and jt - st.day > 30 if key == "jagttegn" else bool(gear.get(key))
            ui.text(s, g["navn"], (r.x + 12, y + 1), 18, C_TEXT)
            ui.text(s, g["desc"], (r.x + 12, y + 18), 14, C_DIM)
            if ui.button(s, (r.right - 118, y + 2, 106, 28), "Har" if have else f"Køb {kr(g['price'])}",
                         enabled=not have and p["money"] >= g["price"], size=15):
                self.client.send({"a": "gear", "key": key})
            y += 36
        y += 4
        ui.text(s, "JAGTTIDER", (r.x + 12, y), 16, C_ACC)
        ui.text(s, f"nu: {MONTHS[st.month()]}", (r.right - 12, y), 15, C_DIM, right=True)
        y += 20
        for sp, g in GAME.items():
            ok = st.in_season(sp)
            ui.text(s, g["navn"], (r.x + 12, y), 16, C_TEXT)
            ui.text(s, months_str(g["season"]) if g["season"] else "fredet hele året", (r.x + 130, y), 16, C_TEXT)
            ui.text(s, ("i sæson" if ok else "fredet nu") + (f" · bøde {kr(g['fine'])}" if g["fine"] and not ok else ""),
                    (r.right - 12, y), 15, C_GOOD if ok else C_BAD, right=True)
            y += 18
        y += 6
        for line in ui.wrap("Kør selv hen til en skov (J) eller en sø (F) og hold stille. Fisk bider bedst i regn og "
                            "tåge. Skyd kun, hvis dyret er i sæson!", 15, r.w - 24):
            ui.text(s, line, (r.x + 12, y), 15, C_DIM)
            y += 16
        y += 6
        vk, fk = p["inv"].get("vildt", 0), p["inv"].get("fisk", 0)
        val = st.sale_value("vildt", int(vk), p) + st.sale_value("fisk", int(fk), p)
        ui.text(s, f"På lager: {vk:.1f} kg vildt og {fk:.1f} kg fisk".replace(".", ","), (r.x + 12, y + 7), 16, C_TEXT)
        if ui.button(s, (r.right - 168, y, 156, 30), f"Sælg alt ({kr(val)})", enabled=vk >= 1 or fk >= 1, size=15):
            for g_, q_ in (("vildt", vk), ("fisk", fk)):
                if q_ >= 1:
                    self.client.send({"a": "sell", "good": g_, "qty": int(q_)})

