    def _vehicle_popup(self, s, view):
        ui, st = self.ui, self.st
        v = next((t for t in st.tractor_view if t[0] == self.bpop["veh"]), None)
        if not v:
            self.bpop = None
            return
        mine = v[1] == self.me
        owner = st.players.get(v[1])
        wear = v[12] if len(v) > 12 else 0
        if VEHICLES.get(v[6], {}).get("hidden"):
            mine = False
        helper_row = mine and st.manual_mode() and vkind(v[6]) not in ("car", "smaa")
        ups = [k for k in UPGRADES if upg_fits(k, v[6])] if mine and VEHICLES.get(v[6]) else []
        show_up = bool(self.bpop.get("upg")) and ups
        book = (v[25] if len(v) > 25 else []) or []
        show_book = bool(self.bpop.get("book")) and mine
        base = (268 if helper_row else 232)
        ucols = 2 if show_up and len(ups) > 4 else 1         # mange opgraderinger: to kolonner
        pw = (780 if ucols == 2 else 480) if show_up else 400
        ucw = (pw - 36) // ucols
        upg_h = {k: 34 + 14 * len(ui.wrap(UPGRADES[k]["desc"], 13, ucw - 8)) + 6 for k in ups}
        urows = [ups[i:i + ucols] for i in range(0, len(ups), ucols)]
        extra = ((30 + sum(max(upg_h[k] for k in row) for row in urows)) if show_up else 0) + \
            ((28 + 17 * max(1, len(book))) if show_book else 0)
        r = pygame.Rect(self.bpop["at"][0] + 14, self.bpop["at"][1] - 20, 300 if not (show_up or show_book) else pw,
                        (base + extra) if mine else 86)
        area = view.copy()
        if self.driving and self.hud_rect.h:                # hold popup'en fri af kørepanelet
            area.height = max(r.h, self.hud_rect.top - 50 - view.y)
        r.clamp_ip(area)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, f"{vname(v[6])} #{v[0]}", (r.x + 12, r.y + 8), 24, C_ACC)
        who = f"Lejet fra {MAKERS[VEHICLES[v[6]]['maker']]['navn'].lower()}" if VEHICLES.get(v[6], {}).get("hidden") else \
            "Din maskine" if mine else f"Tilhører {owner['name'] if owner else '?'}"
        if mine and len(v) > 13 and v[13] == 2:
            who += " · står udenfor"
        ui.text(s, who, (r.x + 12, r.y + 32),
                16, PLAYER_COLORS[v[1] % len(PLAYER_COLORS)])
        other = v[7] == "manual" and len(v) > 14 and v[14] != self.drv
        state_txt = f"Køres af {v[15] or 'en anden'}" if other else self.STATE_NAMES.get(v[7], v[7])
        if len(v) > 16 and v[16] and not other:
            state_txt += " · medhjælper"
        ui.text(s, state_txt, (r.x + 12, r.y + 54), 18, C_TEXT)
        if ui.button(s, (r.right - 30, r.y + 8, 22, 22), "X", size=16):
            self.bpop = None
            return
        if mine:
            vv = VEHICLES.get(v[6], {})
            per = f"{FUEL_TILE * fuel_factor(v[6]) * st.diesel_price():.1f}".replace(".", ",")
            dirt = v[23] if len(v) > 23 else 0
            hrs = v[24] if len(v) > 24 else 0
            ui.text(s, (f"Slid {wear}% · " if st.opts.get("wear", True) else "") + f"snavs {dirt}% · "
                    + f"{hrs:.0f} timer", (r.x + 12, r.y + 120), 16, C_WARN if wear >= 40 or dirt >= 60 else C_TEXT)
            fu = v[29] if len(v) > 29 and v[29] else None
            ui.text(s, f"diesel ca. {per} kr pr. felt" + (f" · tank {int(fu[0])}/{fu[1]} l" if fu else ""),
                    (r.x + 12, r.y + 137), 14, C_WARN if fu and fu[0] < fu[1] * 0.2 else C_DIM)
            if st.opts.get("wear", True) and ui.button(s, (r.x + 12, r.y + 152, 150, 28),
                                                      f"Service {kr(self._svc(v[6], wear))}" if wear >= 1 else "Service",
                                                      enabled=wear >= 1 and bool(vv), size=15):
                self.client.send({"a": "service", "id": v[0]})
            if self.driving == v[0]:
                if ui.button(s, (r.x + 12, r.y + 82, 170, 34), "Stil den (Esc)" if st.manual_mode() and not v[16]
                             else "Giv tilbage (Esc)", size=18):
                    self.stop_driving()
                    self.bpop = None
            elif ui.button(s, (r.x + 12, r.y + 82, 130, 34), "Styr selv", enabled=not other, size=20):
                if self.driving is not None:
                    self.client.send({"a": "drive", "id": self.driving, "on": False})
                self.start_driving(v[0])
                return
            wash_ok = bool(st.stats(self.me)["bpos"].get("vaskeplads"))
            if ui.button(s, (r.x + 12, r.y + 188, 150, 28), f"Vask ({kr(WASH_COST)})" if wash_ok else "Vask (ingen plads)",
                         enabled=wash_ok and dirt >= 1 and v[7] != "manual", size=15):
                self.client.send({"a": "wash", "id": v[0]})
            if ui.button(s, (r.x + 170, r.y + 188, 118, 28), f"Servicebog", size=15, active=show_book):
                self.bpop["book"] = not self.bpop.get("book")
            if helper_row:
                on = len(v) > 16 and bool(v[16])
                if ui.button(s, (r.x + 12, r.y + 228, 276, 30),
                             "Afskedig medhjælperen" if on else f"Ansæt medhjælper ({kr(HELPER_WAGE)}/md.)", size=16,
                             active=on):
                    self.client.send({"a": "helper", "id": v[0], "on": not on})
            have = v[21] if len(v) > 21 else []
            if ups and ui.button(s, (r.x + 170, r.y + 152, 118, 28), f"Opgrader ({len(have)})", size=15,
                                 active=bool(show_up)):
                self.bpop["upg"] = not self.bpop.get("upg")
            y0 = r.y + base
            if show_book:
                ui.text(s, "SERVICEBOG", (r.x + 12, y0), 15, C_ACC)
                y0 += 20
                if not book:
                    ui.text(s, "Ingen noter endnu.", (r.x + 12, y0), 14, C_DIM)
                    y0 += 17
                for day, txt, cost in reversed(book):
                    ui.text(s, f"{st.pdate(day)}  {txt}", (r.x + 12, y0), 14, C_TEXT)
                    if cost:
                        ui.text(s, kr(cost), (r.right - 12, y0), 14, C_DIM, right=True)
                    y0 += 17
                y0 += 8
            if show_up:
                waiting = (v[27] if len(v) > 27 else []) or []
                has_ws = bool(st.stats(self.me)["bpos"].get("vaerksted"))
                ui.text(s, "OPGRADERINGER – monteres i dit værksted" if has_ws else
                        "OPGRADERINGER – byg et værksted for at få dem monteret", (r.x + 12, y0), 15,
                        C_ACC if has_ws else C_WARN)
                y0 += 22
                for row in urows:
                    for ci, k in enumerate(row):
                        u = dict(UPGRADES[k], price=upg_price(k, v[6]))
                        cx0 = r.x + 12 + ci * (ucw + 12)
                        cxr = cx0 + ucw
                        ui.text(s, u["navn"], (cx0, y0 + 4), 17, C_GOOD if k in have else C_TEXT)
                        for i_, line in enumerate(ui.wrap(u["desc"], 13, ucw - 8)):
                            ui.text(s, line, (cx0, y0 + 32 + i_ * 14), 13, C_DIM)
                        if k == "sneplov" and k in have:       # sneploven kan tages af og sættes på igen
                            on_ = view_plow(v)
                            if ui.button(s, (cxr - 98, y0 + 2, 98, 26), "Afmontér" if on_ else "Montér", size=15,
                                         active=on_):
                                self.client.send({"a": "front", "id": v[0]})
                        elif k == "frontlaesser" and k in have and view_plow(v):
                            ui.text(s, "taget af – sneplov på", (cxr, y0 + 6), 14, C_WARN, right=True)
                        elif k in have:
                            ui.text(s, "monteret", (cxr, y0 + 6), 15, C_GOOD, right=True)
                        elif k in waiting:
                            ui.text(s, "venter på værksted", (cxr, y0 + 6), 15, C_WARN, right=True)
                        elif not has_ws:
                            ui.text(s, f"{kr(u['price'])} · kræver værksted", (cxr, y0 + 6), 14, C_DIM, right=True)
                        elif ui.button(s, (cxr - 110, y0 + 2, 110, 26), f"Køb {kr(u['price'])}",
                                       enabled=self.my()["money"] >= u["price"], size=15):
                            self.client.send({"a": "upgrade", "id": v[0], "key": k})
                    y0 += max(upg_h[k] for k in row)
            if ui.button(s, (r.right - 82, r.y + 82, 70, 34), "Sælg", size=18):
                if self.driving == v[0]:
                    self.stop_driving()
                self.client.send({"a": "vehicle", "sell": v[0]})
                self.bpop = None

    def _fit(self, txt, size, width):
        """Teksten forkortet med … så den kan være i bredden (i den aktuelle tekststørrelse)."""
        f = self.ui.font(size)
        if f.size(txt)[0] <= width:
            return txt
        while txt and f.size(txt + " …")[0] > width:
            txt = txt[:-1]
        return txt.rstrip() + " …"

    def _drive_hud(self, s, view):
        ui, st = self.ui, self.st
        v = next((t for t in st.tractor_view if t[0] == self.driving), None)
        if not v:
            return
        w = min(view.w - self._k(20), self._k(760))
        r = pygame.Rect(0, 0, w, self._k(116))
        r.midbottom = (view.centerx, view.bottom - self._k(8))
        self.hud_rect = r
        pygame.draw.rect(s, (30, 26, 21), r, border_radius=8)
        pygame.draw.rect(s, C_ACC, r, 2, border_radius=8)
        tr_ = ui.text(s, f"Du kører {vname(v[6])}", (r.x + self._k(12), r.y + self._k(7)), 21, C_ACC)
        keys_ = self._fit("L: sænk/løft · K: kobl på/af · E: frontlæsser · O: låge · P: parkér", 16,
                          r.right - self._k(12) - tr_.right - self._k(16))
        if len(keys_) > 3:
            ui.text(s, keys_, (r.right - self._k(12), r.y + self._k(10)), 16, C_DIM, right=True)
        boxes = []                                   # (tekst, hjælpelinje, andel 0..1 eller None, farve)
        if len(v) > 26 and v[26]:
            boxes.append((f"Vasker … snavs {v[23]}%", "Hold stille, til den er ren", max(0.0, 1 - v[23] / 100), C_ACC))
        elif len(v) > 23 and v[23] >= 1 and st.near_washer({"x": v[2], "y": v[3], "o": v[1]}):
            boxes.append(("Vaskepladsen", "Hold stille for at vaske maskinen", None, C_ACC))
        if len(v) > 22 and v[22]:
            lm = self.local["m"] if self.local else {}
            state = ("vender ved markkanten" if lm.get("uturn") else "marken er færdig – giv gas for at fortsætte"
                     if lm.get("gps_stop") else "fartpilot" if (len(v) > 20 and v[20]) and not lm.get("cruise_off")
                     else "holder sporet")
            boxes.append((f"GPS-autostyring: {state}", "Sænk redskabet, så kører den selv og vender ved kanten · "
                          "Ned/S bremser · G slår fra", None, C_GOOD))
        cg = v[17] if len(v) > 17 else None
        if cg:
            n, cap, src = cg
            txt = f"Last {n}/{cap}" + (" – solgte varer til byen" if src == "fr" else "")
            hint = ("Kør helt hen til markbunken for at læsse – og hen til lageret for at læsse af" if not n else
                    "Hold stille ved grovvarehandlen i byen" if src == "fr" else
                    "Kør helt hen til lageret (siloen) – så læsses der af")
            if bale_wagon(v[19] if len(v) > 19 else None):        # ballevognen: tæl i baller
                bv_ = v[31] if len(v) > 31 and v[31] else None
                txt = f"{WAGONS.get(wagon_key(v[19]), {}).get('navn', 'Ballevogn')}: {(bv_[1] + bv_[2]) if bv_ else 0}/" \
                      f"{wagon_slots(v[19])} baller"
                hint = ("Stil den på marken (K) og kør frontlæsseren helt frem til den – eller hold stille, så en "
                        "anden traktor med læsser kan køre frem til den" if not n else
                        "Kør helt hen til ballepladsen – så læsses den af")
            boxes.append((txt, hint + " · Tab: næste maskine", min(1, n / max(1, cap)), C_GOOD))
        act = v[18] if len(v) > 18 else None
        p = self.my()
        if act and act.get("g"):
            g = GAME[act["g"]]
            boxes.append((f"{g['en'].capitalize()} kommer frem!  Tryk J for at skyde",
                          "Er den i sæson? Uden for jagttiden koster det en bøde.", max(0.0, act["ttl"] / GAME_SECS),
                          C_WARN))
        elif act:
            boxes.append(("Fisketur …" if act["k"] == "fish" else "Du venter stille i skovkanten …",
                          "Hold stille – kører du, er turen forbi", act["p"], C_ACC))
        elif p and abs(v[10] if len(v) > 10 else 0) < 0.2:
            gear = p.get("gear", {})
            opts = []
            if st.near_water(v[2], v[3]):
                opts.append("F: tag på fisketur" if gear.get("fiskestang") or gear.get("fiskegrej")
                            else "Her kan man fiske – køb en fiskestang i jagtbutikken")
            if st.near_forest(v[2], v[3], self.me)[0] >= 5:
                opts.append("J: gå på jagt" if st.jagttegn_ok(p) and (gear.get("riffel") or gear.get("haglgevaer"))
                            else "Her kan man jage – jagttegn og gevær fås i jagtbutikken")
            if opts:
                boxes.append((" · ".join(opts), "Jagt- og fisketure: se jagttider og grej i jagtbutikken i byen", None,
                              C_ACC))
        ldv = v[28] if len(v) > 28 and v[28] else ["up", None]
        has_loader = view_loader(v)
        if has_loader and p and abs(v[10] if len(v) > 10 else 0) < 0.2:
            fake = {"x": v[2], "y": v[3], "d": v[4], "man": {"hdg": self.local["m"]["hdg"]} if self.local else {}}
            fp = st.front_point(fake)
            fl = ldv[1]
            if fl:
                nb = max(1, round(fl["n"] / bale_unit(fl["g"], fl.get("s"))))
                tg = st.loader_target(p, fp)
                if tg and tg[0] == "ground":
                    wg = tg[1]
                    wl = p.get("wload", {}).get(wg, {})
                    wk_ = wg[2:].split("#")[0]
                    if bale_wagon(wk_):
                        cnt_ = f"{int(round(wagon_slots_used(wl, p.get('wshape', {}).get(wg))))}/{wagon_slots(wk_)} baller"
                    else:
                        cnt_ = f"{int(sum(wl.values()))}/{WAGONS[wk_]['cap']}"
                    hint = f"Kør helt frem til {st.item_name(wg).lower()} – så læsses de af ({cnt_})"
                elif tg:
                    hint = "Kør helt frem til vognen – så læsses de af"
                elif st._fold_tile(p, fp) is not None:
                    hint = f"E: sæt en balle i foderhækken (+{int(FOLD_BALE_BONUS * 100)}% i {FOLD_BALE_DAYS} dage)"
                elif st._near({"x": fp[0], "y": fp[1]}, st.bale_spot(self.me), UNLOAD_RANGE):
                    hint = "E: sænk og sæt dem af på ballepladsen"
                else:
                    hint = "Kør helt frem til ballevognen – eller sænk (E) ved ballepladsen"
                boxes.append((f"Frontlæsseren bærer {nb} {bale_name(fl['g'], fl.get('s'), nb)}", hint, None, C_GOOD))
            elif st.bales_at(p, fp):
                boxes.append(("Baller foran læsseren", "E: løft dem op" if ldv[0] == "down" else
                              "E: sænk læsseren – og E igen for at løfte ballerne", None, C_ACC))
            elif (p["inv"].get("halm", 0) >= 1 or p["inv"].get("wrap", 0) >= 1) and \
                    st._near({"x": fp[0], "y": fp[1]}, st.bale_spot(self.me), UNLOAD_RANGE):
                boxes.append(("Ballepladsen", "E: løft baller fra lageret" if ldv[0] == "down" else
                              "E: sænk læsseren – og E igen for at tage baller fra lageret", None, C_ACC))
        if p and self.local and time.time() - self.local["m"].get("fence_hit", 0) < 1.5:
            boxes.append(("Hegnet om folden spærrer", "Kør ind ad lågen – O åbner og lukker den", None, C_WARN))
        elif p and st.breaks_near(self.me, v[2], v[3]):
            boxes.append(("Hul i hegnet", "O: lap hullet" if VEHICLES.get(v[6], {}).get("style") in ATV_STYLES else
                          "Lappes fra ATV, UTV eller terrænbil (O)", None, C_WARN))
        elif p and VEHICLES.get(v[6], {}).get("style") in MUCK_STYLES and not (len(v) > 28 and v[28] and v[28][1]):
            fake_ = {"x": v[2], "y": v[3], "o": v[1], "d": v[4], "man": {"hdg": (self.local or {}).get("m", {}).get("hdg")}}
            ms_ = st.muck_spot(fake_)
            if ms_:
                dl_ = (p.get("muck") or {}).get(ms_[0], 0)
                boxes.append((BUILDING_NAMES.get(ms_[1], "Stalden"),
                              f"Muget ud – {int(dl_)} dage tilbage" if dl_ > MUCK_DAYS * 0.5 else
                              f"E: muge ud og lægge frisk strøelse (+{int(MUCK_BONUS * 100)}% i {MUCK_DAYS} dage)",
                              None, C_GOOD if dl_ > MUCK_DAYS * 0.5 else C_ACC))
        if p:
            gn_ = [g for g in st.gates_near(v[2], v[3]) if st.tiles[g[2]][g[1]].o == self.me]
            if gn_:
                _, gx_, gy_, gd_ = gn_[0]
                op_ = st.gate_at(gx_, gy_, gd_)[1]
                boxes.append(("Låge i hegnet", "O: luk lågen" if op_ else "O: åbn lågen", None, C_ACC))
        fuel_btn = False
        fu = v[29] if len(v) > 29 and v[29] else None
        if fu and p:
            fl_, cap_, pumping = fu
            fake = {"x": v[2], "y": v[3], "o": v[1]}
            if pumping:
                boxes.append((f"Tanker … {int(fl_)}/{cap_} l", "Hold stille, til tanken er fuld", fl_ / max(1, cap_),
                              C_GOOD))
            elif fl_ <= 0:
                fuel_btn = True
                boxes.append(("Tør for diesel!", f"Ring efter tankbilen: nødtankning koster {kr(FUEL_RESCUE_FEE)} + "
                              "dieslen", 0.0, C_BAD))
            elif fl_ < cap_ - 0.5 and abs(v[10] if len(v) > 10 else 0) < 0.2 and st.near_tank(fake):
                boxes.append(("Dieseltanken", f"Hold stille for at tanke · gårdens tank: {int(p.get('tank_l', 0))} l",
                              None, C_ACC))
            elif fl_ < cap_ - 0.5 and abs(v[10] if len(v) > 10 else 0) < 0.2 and \
                    max(abs(v[2] - GROVVARE[0]), abs(v[3] - GROVVARE[1])) <= 2.2:
                boxes.append(("Pumpen ved grovvarehandlen",
                              f"Hold stille for at tanke ({fmt_price(st.diesel_price() * FUEL_TOWN_MARKUP)}/l)", None, C_ACC))
            elif fl_ < cap_ * 0.2:
                boxes.append((f"Lidt diesel tilbage ({int(fl_)} l)", "Kør hjem til dieseltanken eller til pumpen ved "
                              "grovvarehandlen i byen og hold stille", fl_ / max(1, cap_), C_WARN))
        pull_btn = False
        if p and vkind(v[6]) == "tractor" and st.pull_open():
            e = st.pull.get("entries", {}).get(str(self.me), {})
            if e.get("ok") and len(e.get("tries", [])) < PULL_TRIES and \
                    at_pull_xy(v[2], v[3]):
                pull_btn = True
                boxes.append(("Traktortræk", f"T: start dit forsøg ({len(e.get('tries', [])) + 1} af {PULL_TRIES})",
                              None, C_WARN))
        park_btn = False
        if p and vkind(v[6]) != "car" and abs(v[10] if len(v) > 10 else 0) < 0.2 and \
                st.shed_near(self.me, (v[2], v[3]), 1.3):
            park_btn = True
            boxes.append(("Maskinhus", "P: parkér maskinen her (og slip styringen)", None, C_ACC))
        elif p and vkind(v[6]) != "car" and abs(v[10] if len(v) > 10 else 0) < 0.2:
            fx_, fy_ = int(round(v[2])), int(round(v[3]))
            if st.inb(fx_, fy_) and park_tile_ok(st.tiles[fy_][fx_], self.me):
                park_btn = True
                if st.tiles[fy_][fx_].t == "fliser":
                    boxes.append(("Fliser", "P: fast plads her (maskinen holder, som den vender nu)", None, C_ACC))
                else:
                    boxes.append(("Parkering", "P: parkér her ved traktortræk-banen (holder, som den vender nu)",
                                  None, C_ACC))
        hitch_btns = []
        if vkind(v[6]) == "tractor" and p:
            h = v[19] if len(v) > 19 else None
            if h:
                boxes.append((f"Koblet på: {st.item_name(h)}", "K: kobl af – her, eller i maskinhuset, hvis du bakker "
                              "ind mod det", None, C_EDGE))
            elif abs(v[10] if len(v) > 10 else 0) < 0.2:
                hdg = self.local["m"]["hdg"] if self.local else math.atan2(
                    (VDIRS[v[4] % 8][0] + VDIRS[v[4] % 8][1]) * HALF_H, (VDIRS[v[4] % 8][0] - VDIRS[v[4] % 8][1]) * HALF_W)
                opts, _ = st.hitch_options(p, v[2], v[3], hdg)
                if opts:
                    hitch_btns = opts[:6]
                    boxes.append(("Kobl på:", "K kobler den første på – eller klik på den, du vil have", None, C_ACC))
        by = r.y - self._k(6)
        top = r.top
        for bi, (txt, hint, frac, col) in enumerate(boxes):
            box = pygame.Rect(r.x, by - self._k(42), r.w, self._k(42))
            by -= self._k(46)
            pygame.draw.rect(s, (30, 26, 21), box, border_radius=6)
            pygame.draw.rect(s, col if frac is None or col != C_GOOD else C_EDGE, box, 1, border_radius=6)
            tx = box.x + self._k(10)
            if frac is not None:
                pygame.draw.rect(s, (20, 17, 14), (box.x + self._k(10), box.y + self._k(8), self._k(120), self._k(10)), border_radius=3)
                pygame.draw.rect(s, col, (box.x + self._k(10), box.y + self._k(8), int(self._k(120) * frac), self._k(10)), border_radius=3)
                tx = box.x + self._k(140)
            ui.text(s, self._fit(txt, 17, box.right - tx - self._k(8)), (tx, box.y + self._k(3)), 17, C_TEXT)
            ui.text(s, self._fit(hint, 15, box.w - self._k(18)), (box.x + self._k(10), box.y + self._k(22)), 15, C_DIM)
            top = box.top
            if txt == "Tør for diesel!" and fuel_btn:
                if ui.button(s, (box.right - self._k(190), box.y + self._k(6), self._k(180), self._k(26)), "Ring efter tankbilen", size=15):
                    self.client.send({"a": "fuelhelp", "id": self.driving})
            if txt == "Traktortræk" and pull_btn:
                if ui.button(s, (box.right - self._k(130), box.y + self._k(6), self._k(120), self._k(26)), "Start (T)", size=15):
                    self.start_pull()
            if txt in ("Maskinhus", "Fliser", "Parkering") and park_btn:
                if ui.button(s, (box.right - self._k(130), box.y + self._k(6), self._k(120), self._k(26)), "Parkér (P)", size=15):
                    self.client.send({"a": "parkhere", "id": self.driving})
            if txt == "Kobl på:" and hitch_btns:
                bxx = box.x + self._k(80)
                for it in hitch_btns:
                    nm = st.item_name(it)
                    w_ = ui.font(15).size(nm)[0] + 16
                    if bxx + w_ > box.right - self._k(6):
                        break
                    if ui.button(s, (bxx, box.y + self._k(3), w_, self._k(17)), nm, size=15):
                        self.client.send({"a": "hitch", "id": self.driving, "item": it})
                    bxx += w_ + 4
        self.hud_rect = r.union(pygame.Rect(r.x, top, r.w, r.top - top)) if top < r.top else r
        has_gps = len(v) > 21 and "gps" in (v[21] or [])
        for i, line in enumerate(("Op/W: gas · Ned/S: bak", "Ven./Højre: rat · Esc: slip")):
            ui.text(s, line, (r.x + self._k(12), r.y + self._k(30) + i * self._k(14)), 15, C_DIM)
        if has_gps:
            on = len(v) > 22 and v[22]
            ui.text(s, "G: GPS " + ("TIL" if on else "fra"), (r.x + self._k(12), r.y + self._k(58)), 15, C_GOOD if on else C_DIM)
        # speedometer
        speed = v[10] if len(v) > 10 else 0.0
        g = pygame.Rect(r.x + self._k(12), r.y + self._k(72), self._k(124), self._k(14))
        pygame.draw.rect(s, (20, 17, 14), g, border_radius=4)
        frac = clamp(abs(speed) / 2.8, 0, 1)
        col = C_WARN if speed < 0 else (C_GOOD if speed > 0 else C_DIM)
        pygame.draw.rect(s, col, (g.x, g.y, int(g.w * frac), g.h), border_radius=4)
        pygame.draw.rect(s, C_EDGE, g, 1, border_radius=4)
        kmh = int(abs(speed) * 11)
        ui.text(s, f"{kmh} km/t" + (" (bak)" if speed < -0.05 else ""), (g.x, g.bottom + self._k(3)), 15, col)
        fu = v[29] if len(v) > 29 and v[29] else None
        if fu:                                        # tankmåler
            ff = clamp(fu[0] / max(1, fu[1]), 0, 1)
            fg = pygame.Rect(r.x + self._k(96), g.bottom + self._k(5), self._k(40), self._k(9))
            pygame.draw.rect(s, (20, 17, 14), fg, border_radius=3)
            pygame.draw.rect(s, C_BAD if ff < 0.15 else C_WARN if ff < 0.3 else (200, 170, 60),
                             (fg.x, fg.y, int(fg.w * ff), fg.h), border_radius=3)
            pygame.draw.rect(s, C_EDGE, fg, 1, border_radius=3)
            ui.text(s, "D", (fg.x - self._k(10), fg.y - self._k(2)), 13, C_DIM)
        bx = r.x + self._k(150)
        cur = v[20] if len(v) > 20 else (v[9] if v[9] in WORK_TIME else None)
        h = (v[19] if len(v) > 19 else None) or ""
        tool = self.work_tool(v)
        kind = vkind(v[6])
        if kind == "combine":
            what = "Skærebord"
        elif h:
            what = st.item_name(h)
        elif tool == "harvest":
            what = "Frugtplukning"
        else:
            what = None
        x_ = bx
        if what:
            ok = bool(cur or tool)
            if ui.button(s, (x_, r.y + self._k(52), self._k(150), self._k(52)), "Løft" if cur else "Sænk", active=bool(cur), enabled=ok, size=20,
                         sub=f"{what} · L"):
                self.toggle_implement()
            x_ += self._k(154)
            if not tool and not cur:
                ui.text(s, "Kan ikke sænkes – den bruges" if h.startswith("e:") else "", (x_, r.y + self._k(58)), 15, C_DIM)
                ui.text(s, "automatisk ved høst" if h.startswith("e:") else "", (x_, r.y + self._k(74)), 15, C_DIM)
        elif kind == "tractor":
            lines_ = ("Intet redskab koblet på.", "Bak ind mod et redskab", "eller maskinhuset og tryk K.") if has_loader \
                else ("Intet redskab koblet på.", "Kør hen til maskinhuset eller redskabet,", "bak ind mod det og tryk K.")
            for i, line in enumerate(lines_):
                ui.text(s, line, (x_, r.y + self._k(54) + i * self._k(16)), 15, C_DIM if i else C_TEXT)
            x_ += max(ui.font(15).size(l_)[0] for l_ in lines_) + self._k(14)
        if h.startswith("e:") and GEAR_IMP.get(h[2:]) == "fertilize":
            sp = getattr(self, "spread", "fertilize")
            if ui.button(s, (x_, r.y + self._k(52), self._k(96), self._k(52)), "Gødning" if sp == "fertilize" else "Kalk", size=17,
                         sub="skift"):
                self.spread = "lime" if sp == "fertilize" else "fertilize"
                if cur:
                    self.set_implement(self.spread)
            x_ += self._k(100)
        if h.startswith("e:") and GEAR_IMP.get(h[2:]) in ("gylle", "gylle_s") and p:
            n_ = int(p.get("gylle", 0) // GYLLE_PER_TILE)
            ui.text(s, f"Gylletank: {int(p.get('gylle', 0))}", (x_, r.y + self._k(56)), 15, C_TEXT if n_ else C_WARN)
            ui.text(s, f"nok til {n_} felter" if n_ else "tom – brug sprederen", (x_, r.y + self._k(74)), 15, C_DIM)
            x_ += self._k(130)
        if tool == "sow" and x_ + self._k(100) <= r.right:
            if ui.button(s, (x_, r.y + self._k(52), self._k(110), self._k(52)), CROPS[self.crop]["navn"], size=17, sub="skift afgrøde"):
                keys_ = list(CROPS)
                self.crop = keys_[(keys_.index(self.crop) + 1) % len(keys_)]
                if cur == "sow":
                    self.set_implement("sow")
            x_ += self._k(114)
        if has_loader and x_ + self._k(112) <= r.right:
            fl = ldv[1]
            if ui.button(s, (x_, r.y + self._k(52), min(self._k(170), r.right - x_ - self._k(8)), self._k(52)),
                         "Hæv læsser" if ldv[0] == "down" else "Sænk læsser", active=ldv[0] == "down", size=17,
                         sub=("Gafler" if VEHICLES.get(v[6], {}).get("style") == "gaffeltruck" else "Skovl"
                              if VEHICLES.get(v[6], {}).get("loader") else "Frontlæsser") + " · E"
                         + (" · bærer" if fl else "")):
                self.client.send({"a": "loader", "id": self.driving})

    # ── maskinhuset set uden tag: båse, træk og slip ─────────────────────────
    def _shed_item_at(self, pos):
        for rect, it in reversed(getattr(self, "shed_items", [])):
            if rect.collidepoint(pos):
                return it
        return None

    def _shed_bay_at(self, pos):
        g = self.shed_geo
        if g["out"].collidepoint(pos):
            return "out"
        dx, dy = pos[0] - g["ox"], pos[1] - g["oy"]
        u = (dx / (HALF_W * g["z"]) + dy / (HALF_H * g["z"])) / 2
        v = (dy / (HALF_H * g["z"]) - dx / (HALF_W * g["z"])) / 2
        c, r = int(math.floor(u)), int(math.floor(v))
        if 0 <= c < g["cols"] and 0 <= r < SHED_ROWS:
            return r * g["cols"] + c
        return None

    def _shed_drop(self, pos):
        d, self.sdrag = self.sdrag, None
        g = getattr(self, "shed_geo", None)
        if not g or not d:
            return
        it = d["item"]
        if not d["moved"]:
            if it:
                self.shed_sel = it
            return
        if not it:
            return
        tgt = self._shed_bay_at(pos)
        if tgt == "out":
            self.client.send({"a": "park", "item": it, "shed": None, "slot": 0})
        elif tgt is not None:
            self.client.send({"a": "park", "item": it, "shed": g["key"], "slot": tgt})
        self.shed_sel = it

    def _shed_name(self, key):
        """Maskinhusene nummereres, så man kan kende dem fra hinanden (Maskinhus 1, Stort maskinhus 2 …)."""
        st = self.st
        keys = sorted(st.shed_bays(self.me), key=lambda k: tuple(int(v) for v in k.split(",")))
        ax, ay = (int(v) for v in key.split(","))
        name = BUILDING_NAMES.get(st.tiles[ay][ax].b, "Maskinhus")
        return f"{name} {keys.index(key) + 1}" if len(keys) > 1 and key in keys else name

    def _shed_move_list(self, s, px, y, w, key, sel):
        """Vælg hvilket maskinhus maskinen/redskabet skal flyttes til."""
        ui, st, p = self.ui, self.st, self.my()
        ui.text(s, f"Flyt {st.item_name(sel) if sel.startswith('v') else st.item_name(sel).lower()} til:",
                (px, y), 16, C_ACC)
        y += self._k(22)
        bays = st.shed_bays(self.me)
        others = sorted((k for k in bays if k != key), key=lambda k: tuple(int(v) for v in k.split(",")))
        size = st.item_size(sel)
        for k in others[:5]:
            lay_ = [None if it == sel else it for it in p.get("park", {}).get(k, [])]
            free = sum(1 for it in lay_ if it is None)
            ok = bool(lay_) and st._free_bay(lay_, bays[k], size) is not None
            if ui.button(s, (px, y, w, self._k(26)), f"{self._shed_name(k)}  ({free} ledige)", enabled=ok, size=15):
                self.client.send({"a": "park", "item": sel, "shed": k, "slot": -1})
                self.shed_move = None
                self.bpop = {"pos": [int(v) for v in k.split(",")], "at": (0, 0)}     # vis det andet hus
                self.shed_sel = sel
                return y
            y += self._k(30)
        if ui.button(s, (px, y, w, self._k(26)), "Fortryd", size=15):
            self.shed_move = None
        return y + self._k(30)

    def _shed_popup(self, s, view, anchor):
        ui, st, p = self.ui, self.st, self.my()
        art = self.art
        key = st.shed_key(anchor)
        cols = st.shed_bays(self.me).get(key)
        lay = p.get("park", {}).get(key)
        if not cols or not lay:
            self.bpop = None
            return
        r = pygame.Rect(0, 0, min(view.w - 20, self._k(700)), min(view.h - 10, self._k(470)))
        r.center = view.center
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        t = st.tiles[anchor[1]][anchor[0]]
        ui.text(s, self._shed_name(key) + " – set uden tag", (r.x + self._k(12), r.y + self._k(8)), 24, C_ACC)
        used = sum(1 for it in lay if it)
        ui.text(s, f"{used}/{len(lay)} båse · træk maskiner, redskaber og vogne rundt med musen",
                (r.x + self._k(12), r.y + self._k(34)), 15, C_DIM)
        if ui.button(s, (r.right - self._k(30), r.y + self._k(8), self._k(22), self._k(22)), "X", size=16):
            self.bpop = None
            return
        if ui.button(s, (r.right - self._k(200), r.y + self._k(7), self._k(164), self._k(24)), f"Flyt huset ({kr(st.move_cost(t.b))})", size=15):
            self.start_move(anchor[0], anchor[1])
            return
        if ui.button(s, (r.right - self._k(312), r.y + self._k(7), self._k(104), self._k(24)), "Riv ned …", size=15):
            self._ask_demolish(anchor[0], anchor[1])
            return
        scene = pygame.Rect(r.x + self._k(10), r.y + self._k(54), r.w - self._k(250), r.h - self._k(150))
        pygame.draw.rect(s, (26, 22, 18), scene, border_radius=4)
        wall = 38
        z = min(2.0, (scene.w - self._k(30)) / ((cols + SHED_ROWS) * HALF_W),
                (scene.h - self._k(30)) / ((cols + SHED_ROWS) * HALF_H + wall))
        z = round(z * 4) / 4                                 # hele kvarte, så sprites skaleres pænt
        ox = scene.centerx - (cols - SHED_ROWS) / 2 * HALF_W * z
        tot_h = (cols + SHED_ROWS) * HALF_H * z + wall * z
        oy = scene.y + wall * z + max(8, (scene.h - tot_h) / 2)
        out_r = pygame.Rect(r.x + self._k(10), r.bottom - self._k(88), r.w - self._k(20), self._k(78))

        def L(u, v, h=0.0):
            return (ox + (u - v) * HALF_W * z, oy + (u + v) * HALF_H * z - h * z)
        self.shed_geo = {"ox": ox, "oy": oy, "z": z, "cols": cols, "key": key, "out": out_r, "anchor": anchor}
        s.set_clip(scene)
        # gulv og båse
        pygame.draw.polygon(s, (158, 156, 150), [L(0, 0), L(cols, 0), L(cols, SHED_ROWS), L(0, SHED_ROWS)])
        drag = getattr(self, "sdrag", None)
        hover = self._shed_bay_at(ui.mouse) if scene.collidepoint(ui.mouse) else None
        if drag and drag.get("moved") and drag.get("item") and isinstance(hover, int):
            sz = st.item_size(drag["item"])
            for i in st.bay_idx(hover, cols, sz):
                c_, r_ = i % cols, i // cols
                pygame.draw.polygon(s, (120, 170, 110), [L(c_, r_), L(c_ + 1, r_), L(c_ + 1, r_ + 1), L(c_, r_ + 1)])
        for c in range(cols + 1):
            pygame.draw.line(s, (230, 196, 70), L(c, 0), L(c, SHED_ROWS), 2)
        for c in range(cols):
            a, b = L(c + 0.1, 1), L(c + 0.9, 1)
            pygame.draw.line(s, (200, 196, 186), a, b, 1)
        # bagvægge (ingen tag)
        pygame.draw.polygon(s, (128, 132, 138), [L(0, 0), L(cols, 0), L(cols, 0, wall), L(0, 0, wall)])
        pygame.draw.polygon(s, (104, 108, 114), [L(0, 0), L(0, SHED_ROWS), L(0, SHED_ROWS, wall), L(0, 0, wall)])
        for c in range(1, cols * 2):
            pygame.draw.line(s, (112, 116, 122), L(c / 2, 0), L(c / 2, 0, wall), 1)
        pygame.draw.line(s, (70, 72, 76), L(0, 0, wall), L(cols, 0, wall), 2)
        pygame.draw.line(s, (70, 72, 76), L(0, 0, wall), L(0, SHED_ROWS, wall), 2)
        # det, der står i båsene – bagerst først
        views = {v[0]: v for v in st.tractor_view}
        entries, seen = [], set()
        for i, it in enumerate(lay):
            if not it or it in seen:
                continue
            seen.add(it)
            c, r_ = i % cols, i // cols
            sz = st.item_size(it)
            cu, cv = (c + 0.5, 1.0) if sz == 2 else (c + 0.5, r_ + 0.5)
            entries.append((cu + cv, it, cu, cv))
        entries.sort()
        self.shed_items = []
        for _, it, cu, cv in entries:
            ghost = drag and drag.get("moved") and drag.get("item") == it
            spr, away = None, False
            if it.startswith("v"):
                v = views.get(int(it[1:]))
                if v:
                    spr = art.trimmed(art.vehicle_sprite(v[6], v[1] % len(PLAYER_COLORS), 2,
                                                         v[9] if v[9] in IMPLEMENTS else None, False,
                                                         view_loader(v), 0, False, 0, view_plow(v)))
                    away = not (v[7] in ("home", "repair") and abs(v[2] - v[8][0]) < 0.01 and abs(v[3] - v[8][1]) < 0.01)
            else:
                spr = art.gear_sprite(it)
            cx, cy = L(cu, cv)
            if spr is None:
                continue
            img = art.z(spr, round(z * 0.85, 2))
            if ghost or away:
                img = img.copy()
                img.set_alpha(90)
            rr = img.get_rect(midbottom=(int(cx), int(cy + 10 * z)))
            s.blit(img, rr)
            if away and not ghost:
                ui.text(s, "ude", (int(cx), int(cy - 4 * z)), 15, C_TEXT, center=True)
            if it == getattr(self, "shed_sel", None):
                pygame.draw.rect(s, C_ACC, rr.inflate(self._k(6), self._k(6)), 1, border_radius=4)
            self.shed_items.append((rr, it))
        # lave forvægge ved enden, så man kan se, at huset er skåret over
        pygame.draw.polygon(s, (118, 122, 128), [L(cols, 0), L(cols, SHED_ROWS), L(cols, SHED_ROWS, 8), L(cols, 0, 8)])
        s.set_clip(None)
        # udenfor
        pygame.draw.rect(s, (30, 38, 26), out_r, border_radius=4)
        pygame.draw.rect(s, C_ACC if drag and drag.get("moved") and out_r.collidepoint(ui.mouse) else C_EDGE, out_r, 1,
                         border_radius=4)
        ui.text(s, "Udenfor ved gården – træk herud for at stille noget udenfor, eller herfra ind i en bås",
                (out_r.x + self._k(8), out_r.y + self._k(3)), 14, C_DIM)
        outside = [f"v{v[0]}" for v in st.tractor_view if v[1] == self.me and len(v) > 13 and v[13] == 2]
        hx, hy = p["home"]
        far = 0
        for it_, pos in p.get("gear_pos", {}).items():
            if max(abs(pos[0] - hx), abs(pos[1] - hy)) <= 8:
                outside.append(it_)
            else:
                far += 1
        xx = out_r.x + self._k(8)
        for it in outside:
            if xx + self._k(64) > out_r.right - self._k(90):
                break
            if it.startswith("v"):
                v = views.get(int(it[1:]))
                spr = art.trimmed(art.vehicle_sprite(v[6], v[1] % len(PLAYER_COLORS), 2)) if v else None
            else:
                spr = art.gear_sprite(it)
            cell = pygame.Rect(xx, out_r.y + self._k(20), self._k(60), self._k(52))
            pygame.draw.rect(s, (44, 54, 38), cell, border_radius=3)
            if spr:
                f_ = min(1.0, 54 / max(1, spr.get_width()), 36 / max(1, spr.get_height()))
                img = pygame.transform.scale(spr, (max(1, int(spr.get_width() * f_)), max(1, int(spr.get_height() * f_))))
                s.blit(img, img.get_rect(midbottom=(cell.centerx, cell.bottom - self._k(12))))
            nm = st.item_name(it)
            ui.text(s, nm if len(nm) <= 11 else nm[:10] + "…", (cell.centerx, cell.bottom - self._k(11)), 13, C_TEXT, center=True)
            if it == getattr(self, "shed_sel", None):
                pygame.draw.rect(s, C_ACC, cell, 1, border_radius=3)
            self.shed_items.append((cell, it))
            xx += self._k(64)
        if not outside:
            ui.text(s, "Intet står udenfor.", (out_r.x + self._k(10), out_r.y + self._k(32)), 16, C_DIM)
        if far:
            ui.text(s, f"+{far} ude i marken", (out_r.right - self._k(8), out_r.bottom - self._k(18)), 14, C_DIM, right=True)
        # trækket genstand følger musen
        if drag and drag.get("moved") and drag.get("item"):
            it = drag["item"]
            if it.startswith("v"):
                v = views.get(int(it[1:]))
                spr = art.trimmed(art.vehicle_sprite(v[6], v[1] % len(PLAYER_COLORS), 2)) if v else None
            else:
                spr = art.gear_sprite(it)
            if spr:
                img = art.z(spr, round(z * 0.9, 2)).copy()
                img.set_alpha(190)
                s.blit(img, img.get_rect(midbottom=(ui.mouse[0], ui.mouse[1] + 10)))
        # detaljer om det valgte
        px = scene.right + self._k(12)
        y = scene.y
        sel = getattr(self, "shed_sel", None)
        if sel and sel not in lay and sel not in outside:
            sel = None
        ui.text(s, "Valgt", (px, y), 16, C_ACC)
        y += self._k(20)
        if not sel:
            for line in ui.wrap("Klik på en maskine, et redskab eller en vogn. Træk den til en anden bås – "
                                "lastbiler og mejetærskere fylder en hel række.", 15, r.right - px - self._k(12)):
                ui.text(s, line, (px, y), 15, C_DIM)
                y += self._k(17)
        elif getattr(self, "shed_move", None) == sel:
            self._shed_move_list(s, px, y, r.right - px - self._k(12), key, sel)
        else:
            ui.text(s, st.item_name(sel), (px, y), 19, C_TEXT)
            y += self._k(24)
            if len(st.shed_bays(self.me)) > 1 and not (sel.startswith("v") and views.get(int(sel[1:])) and
                                                        views[int(sel[1:])][7] == "manual"):
                if ui.button(s, (px, y, r.right - px - self._k(12), self._k(26)), "Flyt til andet maskinhus …", size=15):
                    self.shed_move = sel
                    return
                y += self._k(30)
            if sel.startswith("v"):
                v = views.get(int(sel[1:]))
                if v:
                    wr = v[12] if len(v) > 12 else 0
                    ui.text(s, self.STATE_NAMES.get(v[7], v[7]) + (f" · slid {wr}%" if st.opts.get("wear", True) else ""),
                            (px, y), 15, C_DIM)
                    y += self._k(22)
                    bw_ = r.right - px - self._k(12)
                    if ui.button(s, (px, y, bw_, self._k(28)), "Styr selv", enabled=v[7] != "repair", size=17):
                        self.bpop = None
                        self.start_driving(v[0])
                        return
                    y += self._k(32)
                    if st.opts.get("wear", True) and ui.button(s, (px, y, bw_, self._k(28)),
                                                              f"Service {kr(self._svc(v[6], wr))}" if wr >= 1 else
                                                              "Service", enabled=wr >= 1, size=16):
                        self.client.send({"a": "service", "id": v[0]})
                    y += self._k(32)
                    if VEHICLES.get(v[6]) and any(upg_fits(k_, v[6]) for k_ in UPGRADES):
                        have = v[21] if len(v) > 21 else []
                        if ui.button(s, (px, y, bw_, self._k(28)), f"Opgraderinger ({len(have)}) …", size=16):
                            self.bpop = {"veh": v[0], "at": (r.x + self._k(40), r.y + self._k(40)), "upg": True}
                            return
                        y += self._k(32)
                    if ui.button(s, (px, y, bw_, self._k(28)), "Sælg", size=16):
                        self.client.send({"a": "vehicle", "sell": v[0]})
                        self.shed_sel = None
                    y += self._k(34)
            else:
                txt = ("Tipvognen kobles på traktoren, når du selv kører: bak ind mod maskinhuset og tryk K."
                       if sel.startswith("w:") else
                       "Kobles på traktoren, når du selv kører: bak traktoren ind mod maskinhuset og tryk K. "
                       "Maskinerne, der kører selv, bruger den automatisk.")
                for line in ui.wrap(txt, 15, r.right - px - self._k(12)):
                    ui.text(s, line, (px, y), 15, C_DIM)
                    y += self._k(17)
        free_rows = sum(1 for c in range(cols) if lay[c] is None and lay[c + cols] is None)
        if ui.button(s, (px, scene.bottom - self._k(30), r.right - px - self._k(12), self._k(28)), "Køb maskine hertil …", size=16,
                     enabled=any(it is None for it in lay)):
            self._buy_to_shed(anchor)
        ui.text(s, f"Hele rækker ledige: {free_rows}", (px, scene.bottom - self._k(50)), 14, C_DIM)
        if t.b == "rundbuehal":
            bw_ = (r.right - px - self._k(12) - self._k(6)) // 2
            ui.text(s, f"Byg hallen om ({kr(HOOP_SWITCH)}):", (px, scene.bottom - self._k(102)), 14, C_DIM)
            for i_, (to_, lbl_) in enumerate((("rundbuehal_halm", "Halmlager"), ("rundbuehal_foder", "Foderhal"))):
                if ui.button(s, (px + i_ * (bw_ + self._k(6)), scene.bottom - self._k(84), bw_, self._k(26)),
                             lbl_, size=15):
                    self.client.send({"a": "hoop", "x": anchor[0], "y": anchor[1], "to": to_})
                    self.bpop = None

    def _building_popup(self, s, view):
        ui, st = self.ui, self.st
        x, y = self.bpop["pos"]
        t = st.tiles[y][x]
        if not t.b:
            self.bpop = None
            return
        own = t.o
        mine = own == self.me
        owner = st.players.get(own)
        if mine and BUILDINGS.get(t.b, {}).get("group") == "maskinhus":
            return self._scaled_fit(self._shed_popup, 700, 470, view.w - 20, view.h - 10, s, view, (x, y))
        rows = []   # (tekst, farve, [(knaptekst, besked, aktiv)])
        title = BUILDING_NAMES.get(t.b, t.b)
        sub = "Din bygning" if mine else (f"Tilhører {owner['name']}" if owner else "")
        group = BUILDINGS.get(t.b, {}).get("group")
        if t.ba:
            sub += f" · {t.ba[2]}×{t.ba[3]} felter"
        if group == "maskinhus":
            slots = BUILDINGS[t.b]["cap"]
            here = [v for v in st.tractor_view if v[1] == own and list(v[8]) == [x, y]]
            rows.append((f"Pladser: {len(here)}/{slots}", C_TEXT, []))
            if not here:
                rows.append(("Tomt maskinhus", C_DIM, []))
            for v in here:
                name = f"{vname(v[6])} #{v[0]}"
                btns = [("Styr selv", (lambda vid=v[0]: self.start_driving(vid)), v[7] != "repair"),
                        ("Sælg", {"a": "vehicle", "sell": v[0]}, True)] if mine else []
                rows.append((name, C_TEXT, btns))
                wr = v[12] if len(v) > 12 else 0
                sl = self.STATE_NAMES.get(v[7], v[7]) + (f" · slid {wr}%" if st.opts.get("wear", True) else "")
                if mine and wr >= 1 and st.opts.get("wear", True):
                    rows.append(("   " + sl, C_WARN if wr >= 40 else C_DIM,
                                 [(f"Service {kr(self._svc(v[6], wr))}", {"a": "service", "id": v[0]}, True)]))
                else:
                    rows.append(("   " + sl, C_DIM, []))
            if mine and len(here) < slots:
                rows.append(("", C_DIM, [("Køb maskine hertil …", (lambda sp=(x, y): self._buy_to_shed(sp)), True)]))
            if owner:
                tools = [EQUIPMENT[k]["navn"] for k in owner.get("equip", []) if not EQUIPMENT[k].get("hidden")]
                tools += [f"{WAGONS[w]['navn']}{f' ×{n}' if n > 1 else ''}" for w, n in owner.get("wagons", {}).items()
                          if n]
                rows.append(("Redskaber og vogne på gården:", C_ACC, []))
                if not tools:
                    rows.append(("  Ingen – maskinerne lejer udstyret.", C_DIM, []))
                line = "  "
                for tname in tools:
                    if len(line) + len(tname) > 40:
                        rows.append((line.rstrip(", "), C_TEXT, []))
                        line = "  "
                    line += tname + ", "
                if line.strip():
                    rows.append((line.rstrip(", "), C_TEXT, []))
        elif group == "vaerksted" and owner:
            parts = owner.get("parts", 0)
            rows.append((f"Reservedele på lager: {parts}", C_GOOD if parts else C_WARN, []))
            rows.append(("Går en maskine i stykker, reparerer du den selv på 1 dag (1 reservedel) – ellers 3 dage "
                         "hos mekanikeren.", C_DIM, []))
            rows.append(("Service koster 40% mindre med eget værksted.", C_DIM, []))
            if mine:
                rows.append(("", C_DIM, [(f"Køb 1 ({kr(PART_PRICE)})", {"a": "parts", "n": 1}, True),
                                         (f"Køb 5 ({kr(PART_PRICE * 5)})", {"a": "parts", "n": 5}, True)]))
            rep_ = [v for v in st.tractor_view if v[1] == own and v[7] == "repair"]
            for v in rep_:
                rows.append((f"På værksted: {vname(v[6])} #{v[0]}", C_WARN, []))
        elif group == "vaskeplads" and owner:
            dirty = sorted((v for v in st.tractor_view if v[1] == own and len(v) > 23 and v[23] >= 1
                            and not VEHICLES.get(v[6], {}).get("hidden")), key=lambda v: -v[23])
            rows.append(("Kør selv herhen og hold stille – så vaskes maskinen.", C_DIM, []))
            rows.append(("Maskiner, der kører selv, vaskes, når de holder hjemme.", C_DIM, []))
            if not dirty:
                rows.append(("Alle maskiner er rene.", C_GOOD, []))
            for v in dirty[:5]:
                rows.append((f"{vname(v[6])} #{v[0]}: snavs {v[23]}%", C_WARN if v[23] >= 60 else C_TEXT,
                             [(f"Vask", {"a": "wash", "id": v[0]}, v[7] != "manual")] if mine else []))
        elif group == "toemmerplads" and owner:
            cap = st.storage_cap(owner, "tommer")
            rows.append((f"Tømmer: {int(owner['inv'].get('tommer', 0))} af {int(cap)}", C_TEXT, []))
        elif group == "balleplads" and owner:
            cap = st.storage_cap(owner, "halm")
            h_, w_ = owner["inv"].get("halm", 0), owner["inv"].get("wrap", 0)
            ysh = owner.get("yshape") or "rund"
            rows.append((f"{BALE_SHAPES[ysh]['flertal'].capitalize()}: {int(round(h_ / bale_unit('halm', ysh)))} · "
                         f"wrapballer: {int(round(w_ / BALE_U))}", C_TEXT, []))
            rows.append((f"Plads i alt: {int(h_ + w_)} / {int(cap)} enheder",
                         C_WARN if h_ + w_ >= cap * 0.95 else C_DIM, []))
            if t.b == "rundbuehal_halm":
                rows.append(("Ballerne ligger tørt. Stakkene ved porten viser, hvor fuld den er.", C_DIM, []))
                if mine:
                    ax_, ay_ = (t.ba or (x, y))[:2]
                    rows.append(("", C_DIM, [(f"Gør til maskinhal ({kr(HOOP_SWITCH)})",
                                              {"a": "hoop", "x": ax_, "y": ay_, "to": "rundbuehal"}, True),
                                             (f"Foderhal ({kr(HOOP_SWITCH)})",
                                              {"a": "hoop", "x": ax_, "y": ay_, "to": "rundbuehal_foder"}, True)]))
            S_ = yard_grid(2, 2)[0] * yard_grid(2, 2)[1] * yard_grid(2, 2)[2]
            if t.b == "balleplads":
                rows.append((f"Stakkene viser, hvor fuld pladsen er (hver synlig balle er ca. {max(1, round(cap / S_))} "
                         "enheder). Halm stables fra den ene ende, wrap fra den anden.", C_DIM, []))
            rows.append(("Ballerne fra marken køres herhen.", C_DIM, []))
            rows.append(("Wrapballer er ensilage, som dyrene æder, når plansiloen er tom.", C_DIM, []))
        elif group == "kostald" and owner:
            ak_ = "%d,%d" % tuple((t.ba or (x, y, 1, 1))[:2])
            n_c = owner.get("cows", 0)
            rows.append((f"Køer på gården: {n_c} · plads i denne stald: {BUILDINGS[t.b]['cap']}", C_TEXT, []))
            if ak_ in (owner.get("robots") or {}):
                rows.append((f"Malkerobot installeret: op til {BUILDINGS[t.b]['cap']} køer giver "
                             f"{int(ROBOT_MILK * 100)}% mere mælk (service {kr(ROBOT_UPKEEP)} om måneden).", C_GOOD, []))
            elif mine and t.b in ROBOT_COST:
                rows.append(("Malkerobot: køerne går selv hen og bliver malket, når de vil – "
                             f"{int(ROBOT_MILK * 100)}% mere mælk.", C_DIM,
                             [(f"Installer ({kr(ROBOT_COST[t.b])})", {"a": "robot", "x": x, "y": y},
                               owner["money"] >= ROBOT_COST[t.b] or st.sandbox())]))
        elif group == "fodersilo" and owner:
            order = [GOODS[g]["navn"].lower() for g in st.feed_order(owner)]
            rows.append(("Foderplan: billigste korn først – i dag " + ", ".join(order) + ".", C_TEXT, []))
            rows.append((f"Grise og høns giver {int(FEEDSILO_BONUS * 100)}% mere med blandet kraftfoder.", C_DIM, []))
        elif group == "gylletank" and owner:
            gc, gl = st.gylle_cap(owner), owner.get("gylle", 0.0)
            rows.append((f"Gylle: {int(gl)} af {int(gc)} (nok til {int(gl // GYLLE_PER_TILE)} felter)",
                         C_WARN if gl >= gc * 0.95 else C_TEXT, []))
            rows.append((f"Fyldes af sig selv fra staldene. Fortanken under staldene rummer {BASE_GYLLE}, hver "
                         f"gylletank {BUILDINGS['gylletank']['cap']} mere.", C_DIM, []))
            rows.append(("Gød markerne med gylle i stedet for kunstgødning: vælg Gød og så Gylle.", C_DIM, []))
        elif group == "dieseltank" and owner:
            cap = st.capacity(owner, "dieseltank")
            lvl = owner.get("tank_l", 0.0)
            price = st.diesel_price()
            rows.append((f"I tanken: {int(lvl):,} af {cap:,} liter".replace(",", "."), C_TEXT, []))
            if lvl >= 1:
                rows.append((f"Købt til {fmt_price(owner.get('tank_pris', price))}/l i gennemsnit", C_DIM, []))
            cheap = st.diesel < 0.95
            rows.append((f"Dieselprisen nu: {fmt_price(price)}/l ({'lav' if cheap else 'høj' if st.diesel > 1.05 else 'normal'})",
                         C_GOOD if cheap else C_WARN if st.diesel > 1.05 else C_TEXT, []))
            rows.append((f"Tankbilen: {fmt_price(price * TANK_DISCOUNT)}/l (8% rabat)", C_DIM, []))
            if mine:
                room = int(cap - lvl)
                rows.append(("", C_DIM, [("Køb 500 l", {"a": "diesel", "liters": 500}, room >= 1),
                                         (f"Fyld op ({room:,} l)".replace(",", "."), {"a": "diesel", "liters": room},
                                          room >= 1)]))
            rows.append(("Dine egne maskiner tanker her, så længe der er diesel i tanken.", C_DIM, []))
        elif group in ("kostald", "svinestald", "hoensehus") and owner:
            kind = next(k for k, a in ANIMALS.items() if a[0] == group)
            a = ANIMALS[kind]
            cap = st.animal_cap(owner, kind)
            rows.append((f"Plads til {BUILDINGS[t.b]['cap']} {a[3]} i denne bygning", C_DIM, []))
            if kind == "cows" or (owner.get("eco") or {}).get(kind):
                n = st.fold_tiles_for(owner, kind)
                per_ = GRAZERS.get(kind) or ECO_KINDS.get(kind, 1)
                rows.append((f"Fold ved stalden: {n} felter = plads til {int(n / per_ + 1e-6)} {a[3]} på græs",
                             C_GOOD if n else C_WARN, []))
                if not n:
                    rows.append(("Lav en fold med 'Fold og hegn', der rører stalden.", C_WARN, []))
            rows.append((f"{a[3].capitalize()} i alt: {owner[kind]} / {cap}", C_TEXT, []))
            rows.append((f"Spiser {a[4]:g} foder/dag · giver {GOODS[a[5]]['navn'].lower()}", C_DIM, []))
            if mine:
                step = 10 if kind == "chickens" else (5 if kind == "pigs" else 1)
                rows.append((f"{kr(a[1])} pr. stk.", C_DIM,
                             [(f"Køb {step}", {"a": "animal", "kind": kind, "delta": step}, owner[kind] < cap),
                              (f"Sælg {step}", {"a": "animal", "kind": kind, "delta": -step}, owner[kind] > 0)]))
        elif t.b == "halmfyr" and owner:
            on_ = owner.get("hf_auto", True)
            rows.append((f"Brænder op til {HALMFYR_USE} enheder halm om dagen fra oktober til april.", C_TEXT, []))
            rows.append((f"Giver {int(HALMFYR_KR)} kr pr. enhed halm: varme til stuehuset og fjernvarme til byen.",
                         C_DIM, []))
            rows.append(("En måneds strøelse gemmes altid til dyrene. Drivhuset varmes gratis op, når fyret brænder.",
                         C_DIM, []))
            rows.append((("Brænder i dag" if owner.get("hf_on") else "Står stille") +
                         f" · tjent i alt {kr(owner.get('hf_kr', 0))}", C_GOOD if owner.get("hf_on") else C_DIM, []))
            rows.append(("Fyret" + (" (til)" if on_ else " (fra)"), C_TEXT, [("Fra" if on_ else "Til", {"a": "hfauto", "on": not on_}, mine)]))
        elif t.b == "kalvehytter" and owner:
            cv_ = owner.get("calves") or []
            cap_ = st.capacity(owner, "kalvehytter")
            keep_ = owner.get("calf_keep", True)
            rows.append((f"Kalve: {len(cv_)} / {cap_}", C_TEXT, []))
            if cv_:
                rows.append(("Alder: " + ", ".join(f"{c['d']} d" for c in sorted(cv_, key=lambda c: -c["d"])[:8]), C_DIM, []))
            rows.append((f"Køerne får ca. én kalv om året, når der er plads i hytterne. Kalvene drikker {CALF_MILK:g} l "
                         f"mælk om dagen de første 60 dage og er store efter {CALF_DAYS} dage.", C_DIM, []))
            rows.append(("Store kalve: " + ("bliver til køer, hvis der er plads i stalden – ellers sælges de"
                                            if keep_ else f"sælges ({kr(CALF_PRICE)} stk.)"), C_TEXT,
                         [("Sælg altid" if keep_ else "Behold", {"a": "calfkeep", "on": not keep_}, mine)]))
        elif t.b == "kornmoelle" and owner:
            on_ = owner.get("mill_on", True)
            rows.append((f"Maler op til {MILL_RATE} enheder hvede til mel om dagen – mere i blæsevejr, næsten intet i tåge.",
                         C_TEXT, []))
            rows.append((f"I dag: {int(owner.get('mill_today', 0))} enheder · mel på lageret: "
                         f"{int(owner['inv'].get('mel', 0))}", C_GOOD if owner.get("mill_today") else C_DIM, []))
            rows.append(("Mel sælges til bageren (via grovvarehandlen) – mere værd end hveden. Møllen er et vartegn: "
                         "+1 prestige.", C_DIM, []))
            rows.append(("Møllen" + (" (maler)" if on_ else " (står stille)"), C_TEXT,
                         [("Stop" if on_ else "Start", {"a": "millon", "on": not on_}, mine)]))
        elif t.b == "drivhus" and owner:
            rows.append((f"Tomater og agurker: ca. {DRIVHUS_PROD:g} enheder om dagen hele året (lidt mindre midt om vinteren).",
                         C_TEXT, []))
            rows.append((f"På lageret: {int(owner['inv'].get('groent', 0))} – sælges til torvehandleren.", C_DIM, []))
            rows.append((f"Fra oktober til april koster varmen {DRIVHUS_HEAT} kr om dagen – gratis, når et halmfyr brænder.",
                         C_DIM, []))
        elif t.b == "gaardskilt" and owner:
            nm_ = owner.get("farm_name") or (owner["name"] + "s gård")
            rows.append((f"På skiltet står: {nm_}", C_TEXT,
                         [("Skift navn …", (lambda: self._edit_farm_name()), True)] if mine else []))
        elif t.b == "andedam" and owner:
            rows.append(("En lille dam med ænder, siv og en badebro. Den pynter: +1 prestige (lidt bedre priser).",
                         C_TEXT, []))
        elif t.b == "bistade" and owner:
            fl_ = st.bee_flowers(*(t.ba or (x, y))[:2]) if hasattr(st, "bee_flowers") else 0
            on_ = BEE_MONTHS[0] <= st.month() <= BEE_MONTHS[1]
            kg_ = st.bee_honey(*(t.ba or (x, y))[:2])
            rows.append((f"Blomster inden for {BEE_R} felter: {fl_:.0f}".replace(".", ","), C_TEXT, []))
            rows.append(("Honning: ca. " + f"{kg_:.2f}".replace(".", ",") + " kg om dagen" +
                         ("" if on_ else " (bierne er i vinterhi til april)"), C_GOOD if on_ else C_DIM, []))
            rows.append((f"Honning på lageret: {int(owner['inv'].get('honning', 0))} kg – sælges til torvehandleren",
                         C_DIM, []))
            rows.append(("Raps, frugttræer, jordbær og kløvergræs giver mest. Raps, frugt og jordbær inden for "
                         f"{BEE_R} felter giver {int(BEE_POLLEN * 100)}% mere.", C_DIM, []))
            rows.append(("Flere bistader tæt på hinanden deler blomsterne.", C_DIM, []))
        elif t.b == "biogas" and owner:
            rows.append((f"Tager dyrenes gylle og op til {BIOGAS_SILAGE} ensilage om dagen.", C_TEXT, []))
            rows.append(("Gyllen kommer ud igen som afgasset gylle til gødskning.", C_DIM, []))
            rows.append(("Ensilage bruges kun, hvis der er mere end en måneds foder.", C_DIM, []))
            rows.append((f"Strøm denne måned: {int(owner.get('bio_kwh', 0))} kWh ({kr(owner.get('bio_kr', 0))})", C_GOOD, []))
            on = owner.get("bio_silage", True)
            rows.append(("Brug overskudsensilage" + (" (til)" if on else " (fra)"), C_TEXT,
                         [("Fra" if on else "Til", {"a": "biosilage", "on": not on}, mine)]))
        elif t.b in ("plansilo", "rundbuehal_foder") and owner:
            rows.append((f"Ensilage: {int(st.stored(owner, 'graes'))} / {st.storage_cap(owner, 'graes')}", C_TEXT, []))
            gs_, ms_ = owner["inv"].get("graes", 0), owner["inv"].get("majsens", 0)
            if ms_ >= 1:
                rows.append((f"  græsensilage {int(gs_)} · majsensilage {int(ms_)}", C_DIM, []))
            if t.b == "rundbuehal_foder":
                rows.append((f"Ensilagen ligger under tag: {int(FODERHAL_SAVE * 100)}% mindre spild, når køer, får "
                             "og heste fodres.", C_GOOD, []))
                if mine:
                    ax_, ay_ = (t.ba or (x, y))[:2]
                    rows.append(("", C_DIM, [(f"Gør til maskinhal ({kr(HOOP_SWITCH)})",
                                              {"a": "hoop", "x": ax_, "y": ay_, "to": "rundbuehal"}, True),
                                             (f"Halmlager ({kr(HOOP_SWITCH)})",
                                              {"a": "hoop", "x": ax_, "y": ay_, "to": "rundbuehal_halm"}, True)]))
            else:
                rows.append(("Kløvergræs og majsensilage lagres her som foder til køerne.", C_DIM, []))
            rows.append(("Køer med både græs- og majsensilage (mindst 1/5 af hver) giver "
                         f"{int(MAJSENS_MIX * 100)}% mere mælk.", C_DIM, []))
        elif t.b == "silo" and owner:
            rows.append((f"Kornlager: {int(st.stored(owner))} / {st.storage_cap(owner)}", C_TEXT, []))
            rows.append((f"Ensilage (plansilo): {int(st.stored(owner, 'graes'))} / {st.storage_cap(owner, 'graes')}",
                         C_DIM, []))
            for g in STORE_GOODS:
                if owner["inv"].get(g, 0) >= 1 and st.store_group(g) == "korn":
                    wet_ = (owner.get("wetg") or {}).get(g, 0)
                    rows.append((f"  {GOODS[g]['navn']}: {int(owner['inv'][g])}" +
                                 (f" (heraf {int(wet_)} vådt)" if wet_ >= 1 else ""), C_WARN if wet_ >= 1 else C_DIM, []))
        elif t.b == "vindmoelle" and owner:
            stopped = f"{x},{y}" in owner.get("mill_stop", {})
            w_ = st.wind_now()
            if stopped:
                rows.append(("Står stille – repareres efter stormen.", C_WARN, []))
            elif st.weather == "Storm":
                rows.append(("Står stille i stormen for at skåne vingerne.", C_WARN, []))
            else:
                rows.append((f"Vinden i dag: {int(w_ * 100)}% · ca. {kr(MILL_BASE * w_)} i dag", C_TEXT, []))
            e_ = (owner.get("eacc") or {}).get(str(st.year()), {}).get("vindmoelle", {})
            rows.append((f"Strøm i år: {kr(e_.get('rev', 0))} (alle vindmøller)", C_GOOD, []))
            rows.append(("Giver mest i blæsevejr og om vinteren.", C_DIM, []))
        elif t.b == "solcelleanlaeg" and owner:
            sn = st.sun_now()
            rows.append((f"Solen i dag: {int(sn * 100)}% · ca. {kr(SOLAR_BASE * sn)} i dag", C_TEXT, []))
            e_ = (owner.get("eacc") or {}).get(str(st.year()), {}).get("solcelleanlaeg", {})
            rows.append((f"Strøm i år: {kr(e_.get('rev', 0))} (alle solcelleanlæg)", C_GOOD, []))
            rows.append(("Giver mest i solskin om sommeren.", C_DIM, []))
        elif t.b == "korntoerreri" and owner:
            wg = owner.get("wetg") or {}
            cap = st.capacity(owner, "korntoerreri")
            rows.append((f"Tørrer {cap} enheder om dagen · {str(DRY_COST).replace('.', ',')} kr pr. enhed", C_TEXT, []))
            if wg:
                for g, v in wg.items():
                    rows.append((f"  Vådt {GOODS[g]['navn'].lower()}: {int(v)} – tørres nu", C_WARN, []))
            else:
                rows.append(("Intet vådt korn lige nu.", C_GOOD, []))
            rows.append(("Korn høstet i regnvejr eller fra en meget våd mark er vådt.", C_DIM, []))
        elif t.b == "broend":
            n = sum(1 for dx, dy in N4 if st.inb(x + dx, y + dy) and st.tiles[y + dy][x + dx].t == "ditch")
            rows.append(("Giver vand til grøfter, der rører brønden.", C_TEXT, []))
            rows.append((f"{n} grøft{'er' if n != 1 else ''} tilsluttet." if n else
                         "Ingen grøfter tilsluttet – grav en grøft herfra.", C_GOOD if n else C_WARN, []))
        elif t.b == "gaard" and owner:
            rows.append((f"{owner['name']}s gård", PLAYER_COLORS[own], []))
            rows.append((f"Jord: {st.stats(own)['tiles']} felter · maskiner: {st.n_vehicles(own)}", C_TEXT, []))
        if mine and st.movable(t.b):
            btns_ = [(f"Flyt ({kr(st.move_cost(t.b))})", (lambda: self.start_move(x, y)), True)]
            if t.b in BUILDINGS:
                btns_.append(("Riv ned …", (lambda: self._ask_demolish(x, y)), True))
            rows.append(("", C_DIM, btns_))
        k_ = self._k
        FS, BS = 19, 16                                     # lidt større tekst i bygningsvinduerne
        lh, bh_ = k_(23), k_(30)
        maxw = min(view.w - 20, k_(580))
        need = max([ui.font(26).size(title)[0] + k_(50), ui.font(18).size(sub)[0] + k_(24)] +
                   [ui.font(FS).size(t_)[0] + k_(24) + sum(max(k_(60), ui.font(BS).size(l_)[0] + k_(18)) + 4
                                                          for l_, _m, _e in b_) for t_, _c, b_ in rows])
        w = max(k_(380), min(maxw, need))
        lay = []                                            # (linjer, farve, knapper)
        for text, col, btns in rows:
            if btns:
                bw_tot = sum(max(k_(60), ui.font(BS).size(l_)[0] + k_(18)) + 4 for l_, _m, _e in btns)
                lines = ui.wrap(text, FS, max(k_(60), w - k_(24) - bw_tot)) if text else [""]
            else:
                lines = ui.wrap(text, FS, w - k_(24)) if text else [""]
            lay.append((lines, col, btns))
        h = k_(66) + sum((bh_ + lh * (len(ln) - 1)) if b else lh * len(ln) for ln, _c, b in lay)
        ax, ay = self.bpop["at"]
        r = pygame.Rect(ax + 14, ay - 20, w, min(h, view.h - 10))
        r.clamp_ip(view)
        self.bpop_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=6)
        pygame.draw.rect(s, C_ACC, r, 1, border_radius=6)
        ui.text(s, title, (r.x + k_(12), r.y + k_(8)), 26, C_ACC)
        ui.text(s, sub, (r.x + k_(12), r.y + k_(36)), 18, PLAYER_COLORS[own] if own >= 0 else C_DIM)
        if ui.button(s, (r.right - k_(32), r.y + k_(8), k_(24), k_(24)), "X", size=17):
            self.bpop = None
            return
        yy = r.y + k_(64)
        for lines, col, btns in lay:
            if btns:
                ui.text(s, lines[0], (r.x + k_(12), yy + k_(5)), FS, col)
                bx = r.right - k_(10)
                for lbl, msg, en in reversed(btns):
                    bw = max(k_(60), ui.font(BS).size(lbl)[0] + k_(18))
                    bx -= bw
                    if ui.button(s, (bx, yy, bw, k_(27)), lbl, enabled=en, size=BS):
                        if callable(msg):
                            msg()
                        else:
                            self.client.send(msg)
                        return
                    bx -= 4
                yy += bh_
                for ln in lines[1:]:
                    ui.text(s, ln, (r.x + k_(12), yy), FS, col)
                    yy += lh
            else:
                for ln in lines:
                    ui.text(s, ln, (r.x + k_(12), yy + 2), FS, col)
                    yy += lh

    def _cat_flip(self, d):
        items = CATALOG[self.catalog["cat"]][1]
        self.catalog["i"] = (self.catalog["i"] + d) % len(items)

    def _cat_item(self, kind, key):
        st, p, art = self.st, self.my(), self.art
        info = {"stats": [], "buttons": []}
        if kind == "build":
            b = BUILDINGS[key]
            info.update(title=b["navn"], price=b["cost"], desc=BUILD_DESC[key],
                        pic=art.windmill_pic() if key == "vindmoelle" else art.bspr(key))
            n = st.stats(self.me)["b"].get(key, 0) if key != "jagthytte" else len(p.get("huts", []))
            w, h = b["size"]
            info["stats"] = [f"Størrelse: {w}×{h} felter (R drejer ved placering)",
                             f"Vedligehold: {kr(b['upkeep'])} pr. måned", f"Du har: {n}"]
            info["buttons"] = [("Placér på kortet", "place", p["money"] >= b["cost"])]
        elif kind == "vehicle":
            v = VEHICLES[key]
            info.update(title=vname(key), price=v["price"] * (0.9 if st.show_open() else 1), desc=v["desc"],
                        pic=art.vehicle_sprite(key, self.me % len(PLAYER_COLORS), 0))
            if st.show_open():
                info["desc"] = "MESSETILBUD: 10% rabat under dyrskuet. " + v["desc"]
            n = sum(1 for _, k in st.vehicles_of(self.me) if k == key)
            size = ("Lille", "Mellem", "Stor")[v["size"]]
            info["specs"] = [("Hestekræfter", f"{v['hk']} HK", min(1, v["hk"] / 620)),
                             ("Topfart på vej", f"{int(v['fart'] * 30)} km/t", v["fart"] / 1.8)]
            if v["kind"] == "truck":
                unit = "dyreenheder (ko = 1)" if v["cargo"] == "animal" else "enheder høst"
                info["specs"].append(("Lasteevne", f"{v['cap']}", min(1, v["cap"] / (1600 if v["cargo"] == "grain" else 50))))
                info["specs"].append(("Fart i terræn", f"{int(v['offroad'] * 100)}%", v["offroad"]))
            elif v["kind"] != "car":
                info["specs"].append(("Arbejdsfart i marken", f"{int(v['kraft'] * 100)}%", min(1, v["kraft"] / 2.1)))
                if "offroad" in v:
                    info["specs"].append(("Fart i terræn", f"{int(v['offroad'] * 100)}%", min(1, v["offroad"] / 1.2)))
            info["specs"].append(("Pålidelighed", f"{v['rel']}%", (v["rel"] - 75) / 25))
            fuel = (f"diesel ca. {FUEL_TILE * fuel_factor(key):.2f}".replace(".", ",") + " l pr. felt"
                    if v["kind"] in ("tractor", "combine") else
                    f"diesel ca. {FUEL_MOVE * 10 * fuel_factor(key):.1f}".replace(".", ",") + " l pr. 10 felter kørsel")
            info["stats"] = [f"{size} · {STYLE_NAMES.get(v.get('style'), KIND_NAMES[v['kind']]).lower()}"
                             f" · drift {kr(v['upkeep'])} pr. måned · {fuel}",
                             f"Du har: {n}"]
            avail = st.year() >= v["year"] or st.sandbox()
            if not avail:
                info["stats"].append(f"Kommer på markedet i år {v['year']}")
            if v["kind"] == "car":
                slots = st.car_slots(p)
                n_cars = sum(1 for _, k in st.vehicles_of(self.me) if vkind(k) == "car")
                has_g, has_car = slots > 0, n_cars >= slots
                info["buttons"] = [("Køb", "buy", avail and has_g and not has_car and p["money"] >= v["price"])]
                if not has_g:
                    info["stats"].append("Kræver en garage eller dobbeltgarage – højreklik på stuehuset.")
                elif has_car:
                    info["stats"].append(f"Garagerne er fulde ({n_cars}/{slots} biler) – byg en garage mere.")
                else:
                    info["stats"].append(f"Plads i garagerne: {n_cars}/{slots} biler")
            else:
                used, cap = st.bays_used(p)
                size = 2 if v["kind"] in ("truck", "combine") else 1
                info["stats"].append(f"Båse i maskinhusene: {used}/{cap} brugt" +
                                     (" · fylder en hel række (2 båse)" if size == 2 else ""))
                info["buttons"] = [("Køb", "buy", avail and p["money"] >= info["price"])]
                lay = p.get("park", {})
                room = any(st._free_bay(l, len(l) // SHED_ROWS, size) is not None for l in lay.values())
                if not room:
                    info["stats"].append("Ingen plads: den kommer til at stå udenfor og slides af vejret.")
        elif kind == "wagon":
            w = WAGONS[key]
            info.update(title=w["navn"], price=w["price"], desc=w["desc"],
                        pic=art.vehicle_sprite("valtra_6400" if w.get("hk") else START_TRACTOR,
                                               self.me % len(PLAYER_COLORS), 0, key,
                                               (("bl", 15, 9) if w.get("big") else ("bl", 10, 6))
                                               if w.get("bales") else True))
            n = p.get("wagons", {}).get(key, 0)
            unit = "dyreenheder (ko = 1, gris = 0,4)" if w["cargo"] == "animal" else "enheder høst"
            capt = (f"{wagon_slots(key)} baller i {wagon_slots(key) // 8} lag (rund-, big- eller småballer)"
                    if w.get("bales") else f"{w['cap']} {unit}")
            info["stats"] = [f"Lasteevne: {capt}", f"Vedligehold: {kr(w['upkeep'])} pr. måned",
                             f"Du har: {n}", "Trækkes af en ledig traktor" +
                             (f" på mindst {w['hk']} hk" if w.get("hk") else "") + " – kræver ingen plads i maskinhuset."]
            info["buttons"] = [("Køb", 1, p["money"] >= w["price"]), ("Sælg 1", -1, n > 0)]
        elif kind == "equip":
            e = EQUIPMENT[key]
            pic = art.vehicle_sprite("claus_dominator", self.me % len(PLAYER_COLORS), 0) if key == "skaerebord" else \
                art.vehicle_sprite(START_TRACTOR, self.me % len(PLAYER_COLORS), 0,
                                   GEAR_IMP.get(key) if GEAR_IMP.get(key) in IMPLEMENTS else
                                   e["tool"] if e["tool"] in IMPLEMENTS else None)
            owned = key in p.get("equip", [])
            info.update(title=e["navn"], price=e["price"], desc=e["desc"], pic=pic)
            if e["tool"] in RENT:
                info["stats"] = [f"Gælder: {JOB_NAMES[e['tool']].lower()} med alle dine maskiner",
                                 f"Uden eget udstyr lejer du for {RENT[e['tool']]} kr pr. felt"]
            else:
                info["stats"] = ["Bruges automatisk, når du høster hvede eller raps"]
            info["stats"].append("Du ejer det allerede" if owned else "Engangskøb")
            info["buttons"] = [("Købt" if owned else "Køb", "buy", not owned and p["money"] >= e["price"])]
            if e.get("shape"):                       # presserne: vælg hvilken der bruges
                cur = GameState.bale_shape(p)
                info["stats"].append(f"Laver {BALE_SHAPES[e['shape']]['flertal']} ({bale_unit('halm', e['shape'])} "
                                     "enheder pr. balle)" + (" – bruges nu" if owned and cur == e["shape"] else ""))
                if owned and cur != e["shape"]:
                    info["buttons"].append(("Brug denne", "use", True))
        else:
            a = ANIMALS[key]
            cap = st.animal_cap(p, key)
            info.update(title=a[3].capitalize(), price=a[1], desc=ANIMAL_DESC[key], pic=art.spr[a[0]])
            fold = {"cows": " og en fold (1 felt pr. ko)", "horses": " og en fold (1 felt pr. hest)",
                    "sheep": " og en fold (3 får pr. felt)"}.get(key, "")
            need = BUILDINGS[a[0]]["navn"].lower() + fold
            have = p.get(key, 0)
            info["stats"] = [f"Du har: {have} / {cap}", f"Kræver: {need}"]
            if key in GRAZERS:
                info["stats"].append(f"Stald: {st.capacity(p, a[0])} pladser · fold ved stalden: "
                                     f"{st.fold_tiles_for(p, key)} felter")
            for n in ((1, 5) if key in ("cows", "horses") else (5, 10) if key in ("pigs", "sheep") else (10, 25)):
                info["buttons"].append((f"Køb {n}", n, have + n <= cap and p["money"] >= n * a[1]))
            info["buttons"].append(("Sælg 1", -1, have > 0))
        return info

    def _cat_action(self, kind, key, act):
        if kind == "build":
            self.tool, self.catalog = key, None
        elif kind == "vehicle":
            msg = {"a": "vehicle", "kind": key}
            if getattr(self, "cat_shed", None) and vkind(key) != "car":
                msg["shed"] = self.cat_shed
            self.client.send(msg)
        elif kind == "wagon":
            self.client.send({"a": "wagon", "key": key, "delta": act})
        elif kind == "equip" and act == "use":
            self.client.send({"a": "bshape", "key": EQUIPMENT[key].get("shape")})
        elif kind == "equip":
            self.client.send({"a": "equip", "key": key})
        else:
            self.client.send({"a": "animal", "kind": key, "delta": act})

    def _catalog_window(self, s, view):
        ui = self.ui
        cat = self.catalog
        if CATALOG[cat["cat"]][0] not in ("Traktorer", "Mejetærskere", "Lastbiler"):
            self.cat_shed = None
        r = pygame.Rect(0, 0, min(self._k(700), view.w - 16), min(self._k(500), view.h - 8))
        r.center = view.center
        self.cat_rect = r
        pygame.draw.rect(s, (36, 30, 25), r, border_radius=8)
        pygame.draw.rect(s, C_ACC, r, 2, border_radius=8)
        ui.text(s, "Byg og køb", (r.x + self._k(16), r.y + self._k(12)), 28, C_ACC)
        if ui.button(s, (r.right - self._k(34), r.y + self._k(10), self._k(24), self._k(24)), "X", size=17):
            self.catalog = None
            self.cat_shed = None
            return
        if getattr(self, "cat_shed", None):
            ui.text(s, "Køber til det valgte maskinhus", (r.x + self._k(170), r.y + self._k(18)), 16, C_DIM)
        tw = (r.w - self._k(32)) // len(CATALOG)
        for i, (name, _) in enumerate(CATALOG):
            if ui.button(s, (r.x + self._k(16) + i * tw, r.y + self._k(46), tw - 4, self._k(30)), name, active=cat["cat"] == i, size=16):
                cat["cat"], cat["i"] = i, 0
        items = CATALOG[cat["cat"]][1]
        kind, key = items[cat["i"] % len(items)]
        info = self._cat_item(kind, key)
        # billede på en lille græsplæne
        box = pygame.Rect(r.x + self._k(16), r.y + self._k(88), self._k(230), self._k(290))
        pygame.draw.rect(s, (24, 20, 16), box, border_radius=6)
        pic = self.art.z(info["pic"], 1.0)
        br = pic.get_bounding_rect()
        crop = pic.subsurface(br)
        f = max(1, min(4, int(min((box.w - self._k(30)) / max(1, br.w), (box.h - self._k(60)) / max(1, br.h)))))
        g = self.art.z(self.art.grass[0], f * 1.0) if f in (1, 2) else None
        if g:
            s.blit(g, g.get_rect(center=(box.centerx, box.bottom - self._k(40))))
        img = pygame.transform.scale(crop, (br.w * f, br.h * f))
        s.blit(img, img.get_rect(midbottom=(box.centerx, box.bottom - self._k(30))))
        # tekst
        tx = box.right + self._k(18)
        tw2 = r.right - tx - self._k(16)
        ui.text(s, info["title"], (tx, box.y), 30, C_TEXT)
        ui.text(s, kr(info["price"]) + (" pr. stk." if kind == "animal" else ""), (tx, box.y + self._k(32)), 24, C_GOOD)
        yy = box.y + self._k(66)
        for line in ui.wrap(info["desc"], 19, tw2):
            ui.text(s, line, (tx, yy), 19, C_TEXT)
            yy += self._k(21)
        yy += self._k(8)
        for label, val, frac in info.get("specs", []):
            ui.text(s, label, (tx, yy), 16, C_DIM)
            bar = pygame.Rect(tx + self._k(150), yy + self._k(2), tw2 - 230, self._k(11))
            pygame.draw.rect(s, (24, 20, 16), bar, border_radius=3)
            pygame.draw.rect(s, C_GOOD, (bar.x, bar.y, int(bar.w * clamp(frac, 0.05, 1)), bar.h), border_radius=3)
            ui.text(s, val, (tx + tw2, yy), 16, C_TEXT, right=True)
            yy += self._k(18)
        if info.get("specs"):
            yy += self._k(6)
        for line in info["stats"]:
            ui.text(s, line, (tx, yy), 17, C_DIM)
            yy += self._k(19)
        bx = tx
        by = max(box.bottom - self._k(36), yy + self._k(6))
        for lbl, act, en in info["buttons"]:
            bw = max(self._k(90), ui.font(20).size(lbl)[0] + self._k(24))
            if ui.button(s, (bx, by, bw, self._k(36)), lbl, enabled=en, size=20):
                self._cat_action(kind, key, act)
            bx += bw + 8
        # bladring
        ny = r.bottom - self._k(50)
        if ui.button(s, (r.x + self._k(16), ny, self._k(120), self._k(34)), "< Forrige", size=19):
            self._cat_flip(-1)
        ui.text(s, f"{cat['i'] % len(items) + 1} / {len(items)}", (r.centerx, ny + 17), 20, C_DIM, center=True)
        if ui.button(s, (r.right - self._k(136), ny, self._k(120), self._k(34)), "Næste >", size=19):
            self._cat_flip(1)

    def _minimap(self, s, view):
        self.mini_sc = 216.0 / (self.st.W + self.st.H)        # minikortet har samme størrelse på alle kort
        if self.t - self.mini_t > 1.0 or self.mini is None:
            self.mini = render_minimap(self.st, self.mini_sc)
            self.mini_t = self.t
        mw, mh = self.mini.get_size()
        r = pygame.Rect(view.right - mw - 12, view.y + 10, mw, mh)
        self.mini_rect = r
        bg = r.inflate(10, 10)
        pygame.draw.rect(s, (28, 24, 20), bg, border_radius=5)
        pygame.draw.rect(s, C_EDGE, bg, 1, border_radius=5)
        s.blit(self.mini, r)
        sc = self.mini_sc
        zw, zh = HALF_W * self.z, TH * self.z
        vx = (self.cam[0] / zw + self.st.H - 1) * sc
        vy = self.cam[1] / zh * sc
        vr = pygame.Rect(r.x + vx, r.y + vy, view.w / zw * sc, view.h / zh * sc).clip(r)
        pygame.draw.rect(s, (255, 255, 255), vr, 1)

    def _group_popup(self, s, view):
        """Undervalg for et samlet værktøj (Veje: grusvej/asfalt/fliser · Fold og hegn: fold/låge)."""
        ui = self.ui
        key, grp = next((k, g) for k, g in TOOL_GROUPS.items() if self.tool in [x[0] for x in g])
        bw = 160 if len(grp) > 2 else 184
        r = pygame.Rect(view.x + 10, view.y + 10, len(grp) * (bw + 6) + 14, 66)
        self.popup_rect = r
        pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
        pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
        for i, (k, lbl, sub) in enumerate(grp):
            if ui.button(s, (r.x + 8 + i * (bw + 6), r.y + 8, bw, 50), lbl, active=self.tool == k, size=17, sub=sub,
                         icon=tool_icon(k, self.theme())):
                self.tool = k
                self.__dict__["grp_" + key] = k

    def _fence_popup(self, s, view):
        """Farvevalg til gårdhegnet."""
        ui = self.ui
        picks = list(FENCE_COLS.items()) + [("alle", ("Allé", None, None))]
        r = pygame.Rect(view.x + 10, view.y + 10, len(picks) * 116 + 16, 94)
        self.popup_rect = r
        pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
        pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
        ui.text(s, f"Gårdhegn – vælg farve · læhegn {LAEHEGN_COST} kr/stk giver læ", (r.x + 10, r.y + 7), 18, C_ACC)
        cur = getattr(self, "fence_col", "hvid")
        for i, (k, (navn, c, cd)) in enumerate(picks):
            x = r.x + 8 + i * 116
            if ui.button(s, (x, r.y + 30, 110, 34), "", active=cur == k, size=16):
                self.fence_col = cur = k
            draw_picket(s, (x + 8, r.y + 58), (x + 44, r.y + 58), 1.6, "laehegn" if k == "alle" else k)
            ui.text(s, navn, (x + 54, r.y + 39), 16, C_TEXT)
        ui.text(s, "Allé: træk hen ad en vej – træer på begge sider." if cur == "alle" else
                "Træk en linje langs kanten – hegnet sættes i yderkanten.", (r.x + 10, r.y + 72), 14, C_DIM)

    def _plow_popup(self, s, view):
        """Pløj: vælg plov eller stubharve (stubharven tager kun stubmark – resten pløjes)."""
        ui, p = self.ui, self.my()
        cur = p.get("plowmode", "plov")
        r = pygame.Rect(view.x + 10, view.y + 10, 470, 62)
        self.popup_rect = r
        pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
        pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
        ui.text(s, "Jordbehandling", (r.x + 10, r.y + 6), 17, C_ACC)
        ui.text(s, "Stubharven tager kun", (r.x + 10, r.y + 28), 14, C_DIM)
        ui.text(s, "stubmark – resten pløjes", (r.x + 10, r.y + 43), 14, C_DIM)
        if ui.button(s, (r.x + 180, r.y + 8, 136, 46), "Plov", active=cur == "plov", size=17, sub="fjerner ukrudtet"):
            self.client.send({"a": "plowmode", "v": "plov"})
        if ui.button(s, (r.x + 322, r.y + 8, 140, 46), "Stubharve", active=cur == "harve", size=17,
                     sub=f"2× hurtig · {HARROW_COST} kr/felt"):
            self.client.send({"a": "plowmode", "v": "harve"})

    def _fert_popup(self, s, view):
        """Gød: vælg gylle fra gylletanken eller kunstgødning."""
        ui, st, p = self.ui, self.st, self.my()
        g = p.get("gylle", 0.0)
        n = int(g // GYLLE_PER_TILE)
        cur = p.get("fert", "gylle")
        r = pygame.Rect(view.x + 10, view.y + 10, 470, 62)
        self.popup_rect = r
        pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
        pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
        ui.text(s, "Gød med", (r.x + 10, r.y + 6), 17, C_ACC)
        ui.text(s, f"Gylletank: {int(g)} af {int(st.gylle_cap(p))}", (r.x + 10, r.y + 28), 14, C_DIM)
        ui.text(s, f"(nok til {n} felter)", (r.x + 10, r.y + 43), 14, C_DIM)
        own_gv = st.owns_tool(p, "gylle")
        if ui.button(s, (r.x + 180, r.y + 8, 136, 46), "Gylle", active=cur == "gylle" and n > 0, enabled=n > 0,
                     size=17, sub=("egen gyllevogn" if own_gv else f"lejet vogn {RENT_GYLLE} kr/felt") if n
                     else "tanken er tom"):
            self.client.send({"a": "fert", "v": "gylle"})
        inv = p.get("inputs", {})
        sub = f"lager {int(inv['goedning'])}" if inv.get("goedning", 0) >= 1 else \
            f"{int(st.input_price('goedning') * INPUT_SPOT + WORK_LABOR)} kr/felt"
        if ui.button(s, (r.x + 322, r.y + 8, 140, 46), "Kunstgødning", active=cur == "kunst" or n == 0, size=17, sub=sub):
            self.client.send({"a": "fert", "v": "kunst"})

    def _crop_popup(self, s, view):
        ui, st = self.ui, self.st
        if not getattr(self, "crop_open", True):            # afgrøden er valgt: kun en lille bjælke
            d = CROPS[self.crop]
            ok = st.month() in d["months"]
            r = pygame.Rect(view.x + 10, view.y + 10, 430, 40)
            self.popup_rect = r
            pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
            pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
            ui.text(s, f"Sår: {d['navn']}", (r.x + 10, r.y + 3), 18, C_GOOD if ok else C_WARN)
            ui.text(s, f"{d['seed']} kr/felt · " + ("træk hen over marken" if ok else f"sås {sow_months_str(self.crop)}"),
                    (r.x + 10, r.y + 22), 13, C_DIM)
            if ui.button(s, (r.right - 132, r.y + 6, 124, 28), "Skift afgrøde", size=15):
                self.crop_open = True
            return
        rows = (len(CROPS) + 1) // 2
        cw = 290
        r = pygame.Rect(view.x + 10, view.y + 10, cw * 2 + 18, 32 + rows * 56 + 50)
        self.popup_rect = r
        pygame.draw.rect(s, (40, 34, 28), r, border_radius=5)
        pygame.draw.rect(s, C_EDGE, r, 1, border_radius=5)
        m = st.month()
        ui.text(s, f"Vælg afgrøde – det er {MONTHS[m]}", (r.x + 10, r.y + 7), 18, C_ACC)
        for i, (c, d) in enumerate(CROPS.items()):
            ok = m in d["months"]
            x, y = r.x + 6 + (i % 2) * (cw + 6), r.y + 30 + (i // 2) * 56
            short, _ = crop_plan(c, st.day)
            if ui.button(s, (x, y, cw, 52), f"{d['navn']}  ·  {d['seed']} kr/felt", active=self.crop == c,
                         size=17, sub=short, color=C_GOOD if ok else (120, 110, 96)):
                self.crop = c
                self.crop_open = False                       # vinduet lukker – afgrøden forbliver valgt
            ui.text(s, f"sås {sow_months_str(c)}" + ("  (kan sås nu)" if ok else "  (ikke nu)"),
                    (x + 12, y + 20), 14, C_GOOD if ok else C_DIM)
        _, lines = crop_plan(self.crop, st.day)
        yy = r.y + 32 + rows * 56
        for line in lines[1:3]:
            for w in ui.wrap(line, 14, r.w - 20):
                if yy < r.bottom - 8:
                    ui.text(s, w, (r.x + 10, yy), 14, C_DIM)
                    yy += 15

    def _vote_box(self, s, right):
        """Lille boks under topbjælken, når nogen foreslår en ny hastighed."""
        ui, vt = self.ui, self.st.vote
        w, h = 430, 62
        r = pygame.Rect(0, TOPBAR + 6, w, h)
        r.centerx = right
        r.right = min(r.right, s.get_width() - PANEL_W - 6)
        ui.panel(s, r)
        pygame.draw.rect(s, C_ACC, r, 2, border_radius=6)
        mine = vt.get("by") == self.drv
        head = ("Du foreslår" if mine else f"{vt['by_name']} foreslår") + f" {SPEED_NAMES[vt['v']]} tid"
        ui.text(s, head, (r.x + 10, r.y + 6), 17, C_ACC)
        ui.text(s, f"Ja {vt['yes']} · Nej {vt['no']} · kræver {vt['need']} af {vt['n']} · {vt['left']} s",
                (r.x + 10, r.y + 34), 15, C_DIM)
        if self.drv in vt.get("voted", []):
            ui.text(s, "Venter på de andre …", (r.right - 150, r.y + 34), 15, C_TEXT)
        else:
            if ui.button(s, (r.right - 132, r.y + 8, 58, 26), "Ja", size=16):
                self.client.send({"a": "vote", "id": vt["id"], "yes": True})
            if ui.button(s, (r.right - 68, r.y + 8, 58, 26), "Nej", size=16):
                self.client.send({"a": "vote", "id": vt["id"], "yes": False})

    def _topbar(self, s, W):
        ui, st, p = self.ui, self.st, self.my()
        pygame.draw.rect(s, (46, 38, 30), (0, 0, W, TOPBAR))
        pygame.draw.line(s, C_EDGE, (0, TOPBAR - 1), (W, TOPBAR - 1))
        ui.text(s, "FARMLAND", (12, 11), 26, C_ACC)
        x = 140
        ui.text(s, st.date_str(), (x, 12), 22)
        x += 190
        draw_weather_icon(s, st.weather, x, 19)
        wtxt = st.weather + (f" ({st.drought} dage)" if st.drought else "")
        ui.text(s, wtxt, (x + 16, 12), 22, C_WARN if st.weather in ("Tørke", "Storm", "Frost") else C_TEXT)
        x += 150
        mx = x
        if p:
            if st.sandbox():
                mx = ui.text(s, "Sandkasse", (x, 12), 24, C_GOOD).right
            else:
                mx = ui.text(s, kr(p["money"]), (x, 12), 24, C_GOOD if p["money"] >= 0 else C_BAD).right
        R = max(W - PANEL_W, mx + 366)                    # stor tekst: højre del må ikke dække pengene
