        for line in (help_lines if mt == "help" else more_lines if mt == "more" else []):
            if mt == "more":
                head, sep, rest = line.partition(": ")
                if sep and head.isupper():                  # overskriften i guld, resten i hvidt – lange linjer brydes
                    r_ = ui.text(s, head + ":", (box.x + self._k(28), y), 17, C_ACC)
                    avail = box.right - self._k(28) - (r_.right + self._k(6))
