# ═════════════════════════════════════════════════════════════════════════════
def run_dedicated():
    state = None
    if "--load" in sys.argv and os.path.exists(SAVE_MULTI):
        state = load_game(SAVE_MULTI)
    mode = {"drive": "manual" if "--styr-selv" in sys.argv else "auto",
            "farm": "shared" if "--faelles" in sys.argv else "own",
            "money": "sandbox" if "--sandkasse" in sys.argv else "ekstra" if "--45000" in sys.argv else "normal"}
    world = {}
    for a_ in sys.argv:
        if a_.startswith("--naboer="):                 # computernaboer: --naboer=2
            mode["ai"] = max(0, min(AI_MAX, int(a_.split("=")[1] or 0)))
        for opt, key, valid in (("--kort=", "size", MAP_SIZES), ("--egn=", "egn", EGNE), ("--by=", "by", BY_PLACES),
                                ("--terraen=", "terrain", TERRAIN_OPTS)):
            if a_.startswith(opt) and a_.split("=")[1] in valid:
                world[key] = a_.split("=")[1]
        if a_.startswith("--kortnummer="):
            world["seed"] = int(a_.split("=")[1] or 1)
    srv = Server("FarmLand-server", state, mode=mode, world=world or None)
    srv.start()
    print(f"FarmLand-server kører på {lan_ip()}:{srv.port}  (Ctrl+C for at stoppe og gemme)")
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Gemmer og stopper …")
        srv.stop(save=True)


def main():
    global pygame
    if "--version" in sys.argv:                       # bruges af byg_installer.bat: versionsnummeret
        print(GAME_VERSION)
        return
    migrate_old_files()
    if "--dedicated" in sys.argv:
        run_dedicated()
        return
    if "--make-icon" in sys.argv:                     # bruges af byg_exe.bat: lav farmland.ico
        import pygame as _pg
        pygame = _pg
        pygame.init()
        out = sys.argv[sys.argv.index("--make-icon") + 1] if len(sys.argv) > sys.argv.index("--make-icon") + 1 \
            else "farmland.ico"
        write_icon_file(out)
        print("Ikon gemt:", out)
        return
    try:
        import pygame as _pg
    except ImportError:
        print("FarmLand kræver pygame:  pip install pygame")
        sys.exit(1)
    pygame = _pg
    for name in ("stdout", "stderr"):                 # .exe uden konsol: print og fejltekster må ikke vælte spillet
        if getattr(sys, name) is None:
            setattr(sys, name, open(os.devnull, "w"))
    if sys.platform == "win32":                       # skarp tekst: Windows må ikke forstørre (og sløre) vinduet
        try:
            import ctypes
            try:
                ctypes.windll.shcore.SetProcessDpiAwareness(1)
            except Exception:
                ctypes.windll.user32.SetProcessDPIAware()
        except Exception:
            pass
    pygame.init()
    install_ui_theme()
    pygame.key.set_repeat(400, 40)
    app = None
    try:
        app = App()
        app.run()
    except Exception:                                 # skriv fejlen i en fil, så den er nem at sende videre
        import traceback
        log_error(f"spillet stoppede · pygame {pygame.version.ver}", traceback.format_exc())
        _emergency_save(app)
        traceback.print_exc()
        _crash_box(f"FarmLand stoppede desværre med en fejl.\n\nDetaljerne står i:\n{ERROR_LOG}\n\n"
                   "Send gerne filen videre, så fejlen kan blive rettet. Dit spil er gemt, så du kan "
                   "fortsætte, hvor du slap.")
        sys.exit(1)
    finally:
        pygame.quit()


ICON_TRACTOR = "cassel_1394"


def game_icon(art=None, size=64):
    """Spillets ikon: en rød traktor på en grøn plet."""
    art = art or Art()
    spr = art.trimmed(art.vehicle_sprite(ICON_TRACTOR, 0, 7))
    s = pygame.Surface((size, size), pygame.SRCALPHA)
    pygame.draw.ellipse(s, (96, 150, 64), (2, size * 0.52, size - 4, size * 0.44))
    pygame.draw.ellipse(s, (70, 118, 46), (2, size * 0.52, size - 4, size * 0.44), max(1, size // 32))
    k = min((size - 4) / spr.get_width(), (size * 0.86) / spr.get_height())
    if k >= 1:                                        # forstørret: hele pixels (skarpt), formindsket: blødt
        k = int(k)
    sz = (max(1, int(spr.get_width() * k)), max(1, int(spr.get_height() * k)))
    im = pygame.transform.scale(spr, sz) if k >= 1 else pygame.transform.smoothscale(spr, sz)
    s.blit(im, ((size - im.get_width()) // 2, size - im.get_height() - size // 10))
    return s


def write_icon_file(path):
    """Gem ikonet som .ico (til .exe-filen) – PNG-billeder i 16, 32, 48 og 256 px."""
    import io
    import struct
    pngs = []
    for n in (16, 32, 48, 256):
        b = io.BytesIO()
        pygame.image.save(game_icon(None, n), b, "png")
        pngs.append((n, b.getvalue()))
    head = struct.pack("<HHH", 0, 1, len(pngs))
    off = 6 + 16 * len(pngs)
    dirs, data = b"", b""
    for n, png in pngs:
        dirs += struct.pack("<BBBBHHII", n % 256, n % 256, 0, 0, 1, 32, len(png), off + len(data))
        data += png
    with open(path, "wb") as f:
        f.write(head + dirs + data)


def _emergency_save(app):
    """Prøv at gemme spillet, før vinduet lukker efter en fejl."""
    try:
        srv = getattr(getattr(app, "scene", None), "server", None)
        if srv is not None and getattr(srv, "save_path", None):
            save_game(srv.state, srv.save_path)
    except Exception:
        pass


def _crash_box(msg):
    """Vis en beskedboks (på Windows), så man ser, at spillet stoppede – .exe-udgaven har ingen konsol."""
    if sys.platform == "win32":
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(None, msg, GAME_TITLE, 0x10)
        except Exception:
            pass


if __name__ == "__main__":
    main()
